// ==UserScript==
// @name         Torn Archive
// @namespace    torn-archive
// @version      1.3.0
// @description  Museum sets and points: what to buy and where, what your open trades hold, and what a set earns you - on a page of its own, with small marks on Torn's pages.
// @author       -
// @match        https://www.torn.com/*
// @match        https://abrahamdelosreyes17-oss.github.io/torn-archive/*
// @match        https://abrahamdelosreyes17-oss.github.io/torn-moneymaker-releases/*
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_deleteValue
// @grant        GM_registerMenuCommand
// @grant        GM_openInTab
// @grant        GM_xmlhttpRequest
// @grant        GM_addValueChangeListener
// @grant        GM_setClipboard
// @connect      api.torn.com
// @connect      weav3r.dev
// @connect      workers.dev
// @downloadURL  https://raw.githubusercontent.com/abrahamdelosreyes17-oss/torn-archive/main/torn-archive.user.js
// @updateURL    https://raw.githubusercontent.com/abrahamdelosreyes17-oss/torn-archive/main/torn-archive.user.js
// @noframes
// ==/UserScript==

/*
 * Built from src/ by build.mjs - do not edit this file directly.
 *
 * Rules this script keeps, deliberately:
 *   - Data comes from the Torn API, from TornW3B, or from the page you are
 *     currently viewing. It never requests a Torn page you are not on.
 *   - It never buys anything, and never presses Torn's buttons. Its buttons
 *     navigate (one page per press) or type one number into a Torn box on
 *     your press (Fill); you press Buy / Add / Accept / Exchange yourself.
 *   - Your Torn API keys go to api.torn.com and nowhere else, and are never
 *     logged.
 *   - TornW3B (weav3r.dev) is asked for public prices by item id, with no
 *     key. The key you registered on TornW3B is sent to weav3r.dev only, in
 *     a header, and only for your own price list and your receipts.
 *   - Only Torn Archive's own tab asks anything, in view or not, so a new
 *     trade is noticed while you are on Torn. Torn's tabs ask nothing.
 *   - Beside Torn Trading (Torn Bids) the two scripts share the limits: the
 *     one whose page you look at asks more, the other less.
 *   - The shared server needs no setting up and serves only the people its
 *     owner added. Torn Archive asks one server of ours (a workers.dev
 *     address) whether this PC is one of theirs, and says your Torn id for
 *     it - never a key. Only a PC the server knows then tells it bazaar
 *     and item numbers, prices and counts - never your stock or your
 *     money - and its part of your Torn limit is left to it.
 */

(function () {
    'use strict';

    const TARC_BUILD_VERSION = '1.3.0';
    const TARC_SERVER_HOME = 'https://torn-bids-shared.pumping-iron-worker.workers.dev';

    /* ===== src/platform/gm.js ===== */
    /*
     * Userscript-host adapter.
     *
     * Every GM_* call in the project goes through this file. core/ and api/ never
     * touch it directly, so those layers stay portable to a plain web app: swap
     * this one module for a localStorage (or server) adapter and nothing else
     * changes.
     *
     * Falls back to an in-memory store when the GM_* globals are absent, which is
     * what lets the unit tests run under plain node.
     */

    const GM_NAMESPACE = 'tornArchive.v1.';

    const gmMemoryStore = new Map();

    const gmHasStorage =
        typeof GM_getValue === 'function' && typeof GM_setValue === 'function';

    function gmKey(key) {
        return GM_NAMESPACE + key;
    }

    /*
     * The speed log's probe (3.17.0, platform/perf.js): told of each read and
     * write - the value's name, how long it took, how long its text is. Two
     * clock reads a call while one is set; nothing at all otherwise (the tests).
     */
    let gmProbe = null;
    const gmClock = typeof performance !== 'undefined' && typeof performance.now === 'function' ? () => performance.now() : () => 0;

    /** @param {null|function(string, boolean, number, number)} probe - (key, isWrite, ms, textLength) */
    function gmSetProbe(probe) {
        gmProbe = typeof probe === 'function' ? probe : null;
    }

    /** How long a stored value's text is (0 when absent) - its size, without parsing it. */
    function gmSize(key) {
        const full = gmKey(key);
        const raw = gmHasStorage ? GM_getValue(full, null) : gmMemoryStore.has(full) ? gmMemoryStore.get(full) : null;
        return typeof raw === 'string' ? raw.length : 0;
    }

    /** Read a JSON-serialisable value. Returns `fallback` if absent or corrupt. */
    function gmGet(key, fallback = null) {
        if (!gmProbe) return gmRead(key, fallback, null);
        const t = gmClock();
        const size = [0];
        const out = gmRead(key, fallback, size);
        gmProbe(key, false, gmClock() - t, size[0]);
        return out;
    }

    function gmRead(key, fallback, size) {
        const full = gmKey(key);

        let raw;
        if (gmHasStorage) {
            raw = GM_getValue(full, null);
        } else {
            raw = gmMemoryStore.has(full) ? gmMemoryStore.get(full) : null;
        }

        if (raw === null || raw === undefined || raw === '') return fallback;
        if (size && typeof raw === 'string') size[0] = raw.length;

        try {
            return JSON.parse(raw);
        } catch {
            // A corrupt entry is not worth crashing over; treat it as absent.
            return fallback;
        }
    }

    /** Write a JSON-serialisable value. */
    function gmSet(key, value) {
        const t = gmProbe ? gmClock() : 0;
        const full = gmKey(key);
        const raw = JSON.stringify(value);

        if (gmHasStorage) {
            GM_setValue(full, raw);
        } else {
            gmMemoryStore.set(full, raw);
        }
        if (gmProbe) gmProbe(key, true, gmClock() - t, typeof raw === 'string' ? raw.length : 0);
    }

    /** Remove a stored value. */
    function gmDel(key) {
        const full = gmKey(key);

        if (gmHasStorage && typeof GM_deleteValue === 'function') {
            GM_deleteValue(full);
        } else if (gmHasStorage) {
            GM_setValue(full, '');
        } else {
            gmMemoryStore.delete(full);
        }
    }

    /** Register a Tampermonkey menu command, if the host supports them. */
    function gmMenu(label, handler) {
        if (typeof GM_registerMenuCommand === 'function') {
            GM_registerMenuCommand(label, handler);
        }
    }

    /**
     * HTTP GET through the userscript host's own transport.
     *
     * This matters more than it looks. A plain fetch() from a userscript runs in
     * the PAGE's context and is therefore subject to Torn's Content-Security-
     * Policy: if their CSP does not allow connect-src to api.torn.com, every API
     * call is blocked by the browser before it is sent. The panel still loads and
     * the buttons still respond - there is simply never any data, which presents
     * as "it does not scan".
     *
     * GM_xmlhttpRequest runs outside the page, so the page's CSP does not apply.
     * It requires `@connect api.torn.com` in the header.
     *
     * Falls back to fetch when the host does not provide it (and under node, for
     * the tests).
     *
     * @param {string} url
     * @param {{timeoutMs?: number}} [options] - how long to wait for the answer (30 s)
     * @returns {Promise<{ok: boolean, status: number, json: function, header: function(string): (string|null)}>}
     */
    function gmFetch(url, { timeoutMs = 30000 } = {}) {
        if (typeof GM_xmlhttpRequest !== 'function') {
            if (typeof fetch === 'function') return fetch(url);
            return Promise.reject(new Error('No HTTP transport available.'));
        }

        return new Promise((resolve, reject) => {
            GM_xmlhttpRequest({
                method: 'GET',
                url,
                timeout: timeoutMs,
                onload(response) {
                    resolve({
                        ok: response.status >= 200 && response.status < 300,
                        status: response.status,
                        json: async () => JSON.parse(response.responseText),
                        // One answer header by name (TornW3B's Retry-After on a 429), or null.
                        header: (name) => gmHeader(response.responseHeaders, name),
                    });
                },
                onerror() {
                    reject(new Error('Network request failed.'));
                },
                ontimeout() {
                    reject(new Error('Torn API request timed out.'));
                },
            });
        });
    }

    /**
     * A request that carries a body or headers (Torn Archive: your own price list on TornW3B, the shared server).
     * Never used for Torn's API. The answer has the same shape as gmFetch's.
     */
    function gmSend(url, { method = 'GET', headers = {}, body = null, timeoutMs = 30000 } = {}) {
        const data = body == null ? undefined : typeof body === 'string' ? body : JSON.stringify(body);
        const head = { ...(data !== undefined ? { 'Content-Type': 'application/json' } : {}), ...headers };
        if (typeof GM_xmlhttpRequest !== 'function') {
            if (typeof fetch === 'function') return fetch(url, { method, headers: head, body: data }).then((r) => ({ ok: r.ok, status: r.status, json: () => r.json(), text: () => r.text(), header: (name) => r.headers.get(name) }));
            return Promise.reject(new Error('No HTTP transport available.'));
        }
        return new Promise((resolve, reject) => {
            GM_xmlhttpRequest({
                method, url, headers: head, data, timeout: timeoutMs,
                onload(response) {
                    resolve({
                        ok: response.status >= 200 && response.status < 300,
                        status: response.status,
                        json: async () => JSON.parse(response.responseText),
                        text: async () => String(response.responseText || ''),
                        header: (name) => gmHeader(response.responseHeaders, name),
                    });
                },
                onerror() { reject(new Error('Network request failed.')); },
                ontimeout() { reject(new Error('The request timed out.')); },
            });
        });
    }

    /** One header out of GM_xmlhttpRequest's raw header text ("name: value" lines), whatever its case; null when absent. */
    function gmHeader(raw, name) {
        const want = String(name || '').toLowerCase();
        for (const line of String(raw || '').split(/\r?\n/)) {
            const at = line.indexOf(':');
            if (at > 0 && line.slice(0, at).trim().toLowerCase() === want) return line.slice(at + 1).trim();
        }
        return null;
    }

    /** Open a URL in a new tab, if the host supports it; otherwise fall back. */
    function gmOpenTab(url) {
        if (typeof GM_openInTab === 'function') {
            GM_openInTab(url, { active: true });
        } else if (typeof window !== 'undefined') {
            window.open(url, '_blank', 'noopener');
        }
    }

    /**
     * Be told when ANOTHER tab changes a stored value. This is how follower tabs
     * see the live feed the leader tab writes, without polling anything.
     * Returns false when the host has no listener API (the caller then re-reads
     * on its own timer).
     */
    function gmOnChange(key, handler) {
        if (typeof GM_addValueChangeListener !== 'function') return false;

        GM_addValueChangeListener(gmKey(key), (_name, _old, _new, remote) => {
            if (remote) handler();
        });

        return true;
    }

    /**
     * Put text on the clipboard (3.24.0, Sets: a trade message, a forum title). Only ever on a press of yours.
     * @returns {boolean} false when the host has no way to do it
     */
    function gmCopy(text) {
        const value = String(text ?? '');
        try {
            if (typeof GM_setClipboard === 'function') {
                GM_setClipboard(value, 'text');
                return true;
            }
            if (typeof navigator !== 'undefined' && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
                navigator.clipboard.writeText(value).catch(() => {});
                return true;
            }
        } catch {
            // No clipboard: the caller says so.
        }
        return false;
    }

    /* ===== src/platform/tab-window.js ===== */
    /*
     * A request window every tab shares, without tabs losing each other's writes.
     *
     * The old shared window was one stored array: each tab read it, pushed its
     * request and wrote it back. Tampermonkey hands each tab its own copy of a
     * value and syncs changes asynchronously, so two tabs taking a slot at about
     * the same time each wrote back an array without the other's timestamp - and
     * the shared count ran low exactly when the most tabs were busy.
     *
     * Now each tab writes ONLY its own timestamps, under its own key, and a small
     * registry lists the tabs. Reading adds every live tab's list together. A
     * registry write can still race, but only on a tab's first slot (or after a
     * cleanup), and a tab missing from the registry puts itself back on its next
     * slot - so at worst one tab's calls go uncounted until its next call.
     */

    /** A tab whose newest slot is older than this is gone; its key is deleted. */
    const TAB_WINDOW_STALE_MS = 2 * 60 * 1000;

    /**
     * @param {string} name - storage key prefix, e.g. 'apiWindow'
     * @param {string} tabId
     * @param {object} store - {get(key, fallback), set(key, value), del(key)}
     * @param {function} [now]
     */
    function tabWindow(name, tabId, store, now = () => Date.now()) {
        const regKey = name + '.tabs';
        const ownKey = name + '.' + tabId;
        let own = [];

        const registry = () => {
            const r = store.get(regKey, null);
            return r && typeof r === 'object' && !Array.isArray(r) ? r : {};
        };

        return {
            /** Every live tab's timestamps of the last minute, oldest first. */
            load() {
                const t = now();
                const out = [];
                for (const id of Object.keys(registry())) {
                    const list = id === tabId ? own : store.get(name + '.' + id, []);
                    if (!Array.isArray(list)) continue;
                    for (const x of list) if (Number.isFinite(x) && t - x < 60000) out.push(x);
                }
                // This tab before it is registered (its first slot is being taken).
                if (!Object.prototype.hasOwnProperty.call(registry(), tabId)) {
                    for (const x of own) if (t - x < 60000) out.push(x);
                }
                return out.sort((a, b) => a - b);
            },

            /** Record one slot taken by this tab. */
            add(at) {
                const t = now();
                own = own.filter((x) => t - x < 60000);
                own.push(at);
                store.set(ownKey, own);

                const reg = registry();
                let changed = false;
                if (!reg[tabId] || t - reg[tabId] > TAB_WINDOW_STALE_MS / 4) {
                    reg[tabId] = t;
                    changed = true;
                }
                for (const [id, seen] of Object.entries(reg)) {
                    if (id !== tabId && !(t - seen <= TAB_WINDOW_STALE_MS)) {
                        delete reg[id];
                        store.del(name + '.' + id);
                        changed = true;
                    }
                }
                if (changed) store.set(regKey, reg);
            },
        };
    }

    /* ===== src/core/speed.js ===== */
    /*
     * The speed log (3.17.0).
     *
     * The friend: it lags on his laptop. He will not take screenshots of Chrome's
     * task manager or change anything on his PC, so the script keeps its own
     * evidence (the owner: "we should just have something ... that exports his
     * logs (that also doesnt lag ...) we can include it in the zip file he
     * already gives us"). No speed was measured anywhere before this.
     *
     * What is kept: the name of a kind of work, how often it ran, how long it
     * took in all and at its longest - by the hour for a day, then by the day
     * for a week. The browser's own reports of freezes (a stretch of 50 ms or
     * more with the tab stuck) and of slow clicks and key presses (over 100 ms
     * to show). Each stored value's reads and writes. How many changes inside
     * the rows we watch did not come from us. The 50 slowest single events.
     *
     * What is never kept: a name, a player id, an item, a price, a key, a page
     * address. Every label is one of this file's own words, or a stored value's
     * name (ours), or a kind of page ("bazaar", "trade", "Torn Archive").
     *
     * Why it does not lag: recording is two clock reads around work that is
     * already happening and a counter bumped in memory (speedAdd). The record is
     * written to storage at most once a minute and when the tab goes, added to
     * what the other tabs stored (speedMerge) the way the API use record is.
     *
     * And why it stays small - the browser hands every stored value to the script
     * on every page, this one too: the stored record writes each label once
     * (`n`) and its buckets hold only the label's number; the stored values'
     * reads and writes are kept by the day, not the hour. About 20 KB for a week
     * of ordinary use. speedExpand gives it back with the labels.
     *
     * Pure: no DOM, no clock of its own, no storage.
     */

    /** Hours kept one by one; older ones are folded into their day. */
    const SPEED_HOURS_KEPT = 24;
    /** Days kept. */
    const SPEED_DAYS_KEPT = 7;
    /** The slowest single events kept. */
    const SPEED_TOP = 50;
    /** An event this long is one of the slow ones (and what the browser calls a long task). */
    const SPEED_SLOW_MS = 50;
    /** Start-ups kept (the newest). */
    const SPEED_STARTS = 40;
    /** Labels the stored record can hold; any more are counted together as "other". */
    const SPEED_NAMES = 300;

    const SP_HOUR_MS = 3600000;
    const SP_DAY_MS = 86400000;

    const spRound = (n) => Math.round((Number(n) || 0) * 10) / 10;

    /** A stored value's name without what would tell one tab or one trade from another. */
    function speedKey(key) {
        const k = String(key || '?');
        // The per-tab request windows: 'apiWindow.<tab>' (the list of tabs is 'apiWindow.tabs').
        const dot = k.indexOf('.');
        if (dot > 0 && k.slice(dot + 1) !== 'tabs') return k.slice(0, dot) + '.tab';
        return k.replace(/\d{3,}/g, 'N').slice(0, 40);
    }

    /** A tab's counts not yet written. */
    function speedNew() {
        return { h: {}, top: [], start: [], machine: null };
    }

    function spBucket(p, at) {
        const hour = String(Math.floor(at / SP_HOUR_MS));
        return p.h[hour] || (p.h[hour] = { w: {}, f: {}, i: {}, s: {}, x: [0, 0, 0] });
    }

    function spBump(group, name, ms) {
        const row = group[name] || (group[name] = [0, 0, 0]);
        row[0] += 1;
        row[1] += ms;
        if (ms > row[2]) row[2] = ms;
    }

    function spNoteTop(p, ms, kind, where, at) {
        if (!(ms >= SPEED_SLOW_MS)) return;
        const top = p.top;
        if (top.length >= SPEED_TOP && ms <= top[top.length - 1][0]) return;
        top.push([spRound(ms), kind, where, Math.floor(at / SP_HOUR_MS)]);
        top.sort((a, b) => b[0] - a[0]);
        if (top.length > SPEED_TOP) top.length = SPEED_TOP;
    }

    /**
     * One piece of work, timed.
     * @param {object} p - speedNew
     * @param {'w'|'f'|'i'} group - work of ours, a freeze, a slow click or key
     * @param {string} kind - what it was (this file's callers' own words)
     * @param {number} ms
     * @param {string} where - the kind of page
     */
    function speedAdd(p, group, kind, ms, where = '', at = Date.now()) {
        const d = Number(ms);
        if (!(d >= 0) || !Number.isFinite(d)) return p;
        const name = group === 'w' ? kind : where + ' · ' + kind;
        spBump(spBucket(p, at)[group], name, d);
        spNoteTop(p, d, group === 'w' ? kind : (group === 'f' ? 'freeze' : 'slow ' + kind), where, at);
        return p;
    }

    /** One read or write of a stored value: how long, and how big its text was. */
    function speedStore(p, key, write, ms, size, at = Date.now()) {
        const d = Number(ms);
        if (!(d >= 0) || !Number.isFinite(d)) return p;
        const s = spBucket(p, at).s;
        const name = speedKey(key);
        const row = s[name] || (s[name] = [0, 0, 0, 0, 0, 0, 0]);
        const o = write ? 3 : 0;
        row[o] += 1;
        row[o + 1] += d;
        if (d > row[o + 2]) row[o + 2] = d;
        if (size > 0) row[6] = size;
        return p;
    }

    /**
     * A change inside the rows we watch that we did not make (Torn redrawing, or
     * another extension writing into them): how many times we were told, and how
     * many changes those held; the busiest minute is kept too.
     */
    function speedForeign(p, records, at = Date.now()) {
        const x = spBucket(p, at).x;
        x[0] += 1;
        x[1] += Math.max(0, Number(records) || 0);
        const minute = Math.floor(at / 60000);
        if (!p.min || p.min[0] !== minute) p.min = [minute, 0];
        p.min[1] += 1;
        if (p.min[1] > x[2]) x[2] = p.min[1];
        return p;
    }

    /** One page load's start-up: when the script started, its panel showed and its item data was ready (ms after the page began). */
    function speedStartup(p, where, { script = null, panel = null, items = null } = {}, at = Date.now()) {
        const n = (v) => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Math.round(Number(v)));
        p.start.push([Math.floor(at / SP_HOUR_MS), String(where || ''), n(script), n(panel), n(items)]);
        if (p.start.length > SPEED_STARTS) p.start.splice(0, p.start.length - SPEED_STARTS);
        return p;
    }

    /** What the browser says of the machine (nothing a page cannot already read). */
    function speedMachine(p, facts) {
        p.machine = facts && typeof facts === 'object' ? { ...facts } : null;
        return p;
    }

    /** Is there anything to write? */
    function speedHasData(p) {
        return Boolean(p && (Object.keys(p.h).length || p.top.length || p.start.length || p.machine));
    }

    function spClean(stored) {
        const s = stored && typeof stored === 'object' && !Array.isArray(stored) ? stored : {};
        // Buckets by hour or day number; anything else in there is junk.
        const obj = (v) => Object.fromEntries(Object.entries(v && typeof v === 'object' && !Array.isArray(v) ? v : {}).filter(([k, b]) => Number.isFinite(Number(k)) && Number(k) > 0 && b && typeof b === 'object'));
        return {
            v: 1,
            n: Array.isArray(s.n) ? s.n.map(String) : [],
            h: { ...obj(s.h) },
            d: { ...obj(s.d) },
            top: Array.isArray(s.top) ? s.top.filter((t) => Array.isArray(t) && Number(t[0]) > 0 && Number.isFinite(Number(t[3]))) : [],
            start: Array.isArray(s.start) ? s.start.filter((t) => Array.isArray(t) && Number.isFinite(Number(t[0]))) : [],
            machine: s.machine && typeof s.machine === 'object' ? s.machine : null,
        };
    }

    function spAddRows(into, from, width, as) {
        for (const [key, row] of Object.entries(from || {})) {
            if (!Array.isArray(row)) continue;
            const name = as(key);
            const t = Array.isArray(into[name]) ? [...into[name]] : new Array(width).fill(0);
            if (width === 3) {
                t[0] += Number(row[0]) || 0;
                t[1] = spRound(t[1] + (Number(row[1]) || 0));
                t[2] = spRound(Math.max(t[2], Number(row[2]) || 0));
            } else {
                for (const o of [0, 3]) {
                    t[o] += Number(row[o]) || 0;
                    t[o + 1] = spRound(t[o + 1] + (Number(row[o + 1]) || 0));
                    t[o + 2] = spRound(Math.max(t[o + 2], Number(row[o + 2]) || 0));
                }
                if (Number(row[6]) > 0) t[6] = Number(row[6]);
            }
            into[name] = t;
        }
    }

    /** `b` added into target[key]; `as` turns a label of `b` into the label target uses (its number, or itself). */
    function spAddBucket(target, key, b, as = (k) => k) {
        const src = b && typeof b === 'object' ? b : {};
        const cur = target[key] && typeof target[key] === 'object' ? target[key] : {};
        const out = { w: { ...(cur.w || {}) }, f: { ...(cur.f || {}) }, i: { ...(cur.i || {}) }, s: { ...(cur.s || {}) }, x: Array.isArray(cur.x) ? [...cur.x] : [0, 0, 0] };
        spAddRows(out.w, src.w, 3, as);
        spAddRows(out.f, src.f, 3, as);
        spAddRows(out.i, src.i, 3, as);
        spAddRows(out.s, src.s, 7, as);
        const x = Array.isArray(src.x) ? src.x : [0, 0, 0];
        out.x = [out.x[0] + (Number(x[0]) || 0), out.x[1] + (Number(x[1]) || 0), Math.max(out.x[2], Number(x[2]) || 0)];
        // Empty parts are not stored.
        for (const g of ['w', 'f', 'i', 's']) if (!Object.keys(out[g]).length) delete out[g];
        if (!out.x.some((v) => v > 0)) delete out.x;
        target[key] = out;
    }

    /**
     * The stored record with a tab's pending counts added: hours over a day
     * old folded into their day, days over a week old dropped, the 50 slowest
     * kept. Two tabs writing in the same instant can lose a few counts - this is
     * a record to read where the time goes from, not a meter.
     */
    function speedMerge(stored, pending, now = Date.now()) {
        const out = spClean(stored);
        const p = pending || {};
        // Each label is written once; the buckets hold its number.
        const at = new Map(out.n.map((name, i) => [name, i]));
        const numberOf = (name) => {
            let label = String(name);
            if (!at.has(label) && out.n.length >= SPEED_NAMES) label = 'other';
            if (!at.has(label)) {
                at.set(label, out.n.length);
                out.n.push(label);
            }
            return String(at.get(label));
        };
        for (const [hour, b] of Object.entries(p.h || {})) {
            if (!b || typeof b !== 'object') continue;
            spAddBucket(out.h, hour, { w: b.w, f: b.f, i: b.i, x: b.x }, numberOf);
            // The stored values' reads and writes: by the day.
            if (b.s && Object.keys(b.s).length) spAddBucket(out.d, String(Math.floor((Number(hour) * SP_HOUR_MS) / SP_DAY_MS)), { s: b.s }, numberOf);
        }
        const nowHour = Math.floor(now / SP_HOUR_MS);
        for (const hour of Object.keys(out.h)) {
            if (nowHour - Number(hour) >= SPEED_HOURS_KEPT) {
                spAddBucket(out.d, String(Math.floor((Number(hour) * SP_HOUR_MS) / SP_DAY_MS)), out.h[hour]);
                delete out.h[hour];
            }
        }
        const nowDay = Math.floor(now / SP_DAY_MS);
        for (const day of Object.keys(out.d)) if (nowDay - Number(day) >= SPEED_DAYS_KEPT) delete out.d[day];
        const oldest = nowHour - SPEED_DAYS_KEPT * 24;
        out.top = [...out.top, ...(p.top || [])].filter((t) => Number(t[3]) >= oldest).sort((a, b) => b[0] - a[0]).slice(0, SPEED_TOP);
        out.start = [...out.start, ...(p.start || [])].filter((t) => Number(t[0]) >= oldest).slice(-SPEED_STARTS);
        if (p.machine) out.machine = p.machine;
        return spCompact(out);
    }

    /** The record without the labels no bucket holds any more (their numbers closed up). */
    function spCompact(r) {
        const used = new Set();
        const groups = ['w', 'f', 'i', 's'];
        for (const b of [...Object.values(r.h), ...Object.values(r.d)]) for (const g of groups) for (const k of Object.keys(b[g] || {})) used.add(Number(k));
        if (used.size === r.n.length) return r;
        const order = [...used].filter((i) => r.n[i] !== undefined).sort((a, b) => a - b);
        const to = new Map(order.map((old, i) => [String(old), String(i)]));
        const renumber = (buckets) => {
            const out = {};
            for (const [key, b] of Object.entries(buckets)) {
                const nb = { ...b };
                for (const g of groups) {
                    if (!b[g]) continue;
                    nb[g] = {};
                    for (const [k, row] of Object.entries(b[g])) if (to.has(k)) nb[g][to.get(k)] = row;
                }
                out[key] = nb;
            }
            return out;
        };
        return { ...r, n: order.map((i) => r.n[i]), h: renumber(r.h), d: renumber(r.d) };
    }

    /** The stored record with its labels written out again: {h, d: {key: {w, f, i, s, x}}, top, start, machine}. */
    function speedExpand(record) {
        const r = spClean(record);
        const nameOf = (k) => (r.n[Number(k)] === undefined ? 'label ' + k : r.n[Number(k)]);
        const open = (buckets) => {
            const out = {};
            for (const [key, b] of Object.entries(buckets)) {
                spAddBucket(out, key, b, nameOf);
                out[key] = { w: {}, f: {}, i: {}, s: {}, x: [0, 0, 0], ...out[key] };
            }
            return out;
        };
        return { h: open(r.h), d: open(r.d), top: r.top, start: r.start, machine: r.machine };
    }

    /** Everything in the record added into one bucket (the week's totals), labels written out. */
    function speedTotals(record) {
        const r = speedExpand(record);
        const all = {};
        for (const b of Object.values(r.d)) spAddBucket(all, 'all', b);
        for (const b of Object.values(r.h)) spAddBucket(all, 'all', b);
        return { w: {}, f: {}, i: {}, s: {}, x: [0, 0, 0], ...(all.all || {}) };
    }

    const spPad = (s, n) => String(s).padEnd(n);
    const spLpad = (s, n) => String(s).padStart(n);
    const spMs = (n) => (Number(n) >= 100 ? Math.round(Number(n)).toLocaleString('en-US') : (Math.round(Number(n) * 10) / 10).toFixed(1));
    const spKb = (n) => (Number(n) / 1024).toFixed(Number(n) < 10240 ? 1 : 0) + ' KB';

    function spTable(rows, head) {
        if (!rows.length) return ['  (nothing recorded)'];
        // Each column as wide as its widest cell: the first to the left, the numbers to the right.
        const all = [head, ...rows];
        const w = head.map((_, c) => Math.max(...all.map((r) => String(r[c] === undefined ? '' : r[c]).length)));
        const line = (r) => '  ' + spPad(r[0], w[0]) + r.slice(1).map((c, i) => '  ' + spLpad(c, w[i + 1])).join('');
        return all.map(line);
    }

    /**
     * The record as text, worst first - for a person to read.
     *
     * @param {object} record - speedMerge output
     * @param {object} [o]
     * @param {Array<[string, number]>} [o.sizes] - every stored value's size (bytes), for this export
     * @param {object} [o.machine] - the machine as this tab sees it now
     * @param {string} [o.version]
     */
    function speedText(record, { sizes = [], machine = null, version = null, now = Date.now() } = {}) {
        const r = speedExpand(record);
        const all = speedTotals(record);
        const hours = Object.keys(r.h).map(Number);
        const days = Object.keys(r.d).map(Number);
        // From the first hour on record - or, when an earlier day was folded away, from that day.
        const firstHour = hours.length ? Math.min(...hours) * SP_HOUR_MS : Infinity;
        const firstDay = days.length ? Math.min(...days) * SP_DAY_MS : Infinity;
        const first = Math.min(firstHour === Infinity || firstDay < firstHour - SP_DAY_MS ? firstDay : Infinity, firstHour, now);
        const stamp = (t) => new Date(t).toISOString().slice(0, 16).replace('T', ' ');
        const out = [
            'Torn Archive - speed log' + (version ? ' (script ' + version + ')' : ''),
            'Made ' + stamp(now) + ' UTC, covering from ' + stamp(first) + ' UTC.',
            'Times are milliseconds. No name, id, item, price or key is in this file.',
            '',
        ];
        const m = machine || r.machine;
        out.push('THE MACHINE (what the browser tells any page)');
        out.push(m ? '  ' + Object.entries(m).map(([k, v]) => k + ': ' + v).join(' · ') : '  (not recorded)');
        out.push('');

        const work = Object.entries(all.w).sort((a, b) => b[1][1] - a[1][1]);
        out.push('OUR OWN WORK, the most time first (one kind can be inside another: a scan ends with a panel redraw)');
        out.push(...spTable(work.map(([k, v]) => [k, v[0].toLocaleString('en-US'), spMs(v[1]), spMs(v[0] ? v[1] / v[0] : 0), spMs(v[2])]), ['what', 'times', 'in all', 'each', 'longest']));
        out.push('');

        const freezes = Object.entries(all.f).sort((a, b) => b[1][1] - a[1][1]);
        out.push('FREEZES - the tab stuck for ' + SPEED_SLOW_MS + ' ms or more (the browser\'s own count; any script on the page, not only this one)');
        out.push(...spTable(freezes.map(([k, v]) => [k, v[0].toLocaleString('en-US'), spMs(v[1]), spMs(v[0] ? v[1] / v[0] : 0), spMs(v[2])]), ['where', 'times', 'in all', 'each', 'longest']));
        out.push('');

        const inputs = Object.entries(all.i).sort((a, b) => b[1][1] - a[1][1]);
        out.push('SLOW CLICKS AND KEY PRESSES - over 100 ms until the page showed it (the browser\'s own count)');
        out.push(...spTable(inputs.map(([k, v]) => [k, v[0].toLocaleString('en-US'), spMs(v[1]), spMs(v[0] ? v[1] / v[0] : 0), spMs(v[2])]), ['where · what', 'times', 'in all', 'each', 'longest']));
        out.push('');

        out.push('CHANGES IN THE ROWS WE WATCH THAT WE DID NOT MAKE (Torn redrawing, or another extension)');
        out.push('  told ' + all.x[0].toLocaleString('en-US') + ' times, ' + all.x[1].toLocaleString('en-US') + ' changes in all; the busiest minute: ' + all.x[2].toLocaleString('en-US') + ' times');
        out.push('');

        const store = Object.entries(all.s).sort((a, b) => b[1][1] + b[1][4] - (a[1][1] + a[1][4]));
        out.push('STORED VALUES - reads and writes, the most time first');
        out.push(...spTable(store.map(([k, v]) => [k, v[0].toLocaleString('en-US'), spMs(v[1]), spMs(v[2]), v[3].toLocaleString('en-US'), spMs(v[4]), spMs(v[5]), v[6] ? spKb(v[6]) : '-']), ['value', 'reads', 'read ms', 'longest', 'writes', 'write ms', 'longest', 'size']));
        out.push('');

        out.push('START-UP - ms after the page began to load (the newest last)');
        out.push(...spTable(r.start.slice(-15).map((s) => [s[1] || '?', s[2] === null ? '-' : s[2], s[3] === null ? '-' : s[3], s[4] === null ? '-' : s[4]]), ['where', 'script', 'panel', 'item data']));
        out.push('');

        out.push('THE ' + SPEED_TOP + ' SLOWEST SINGLE EVENTS');
        out.push(...spTable(r.top.map((t) => [t[1], spMs(t[0]), t[2] || '', stamp(Number(t[3]) * SP_HOUR_MS).slice(0, 13) + 'h']), ['what', 'ms', 'where', 'hour (UTC)']));
        out.push('');

        const sized = [...sizes].sort((a, b) => b[1] - a[1]);
        out.push('EVERYTHING STORED BY THE SCRIPT - ' + spKb(sized.reduce((a, s) => a + s[1], 0)) + ' in all (the browser hands all of it to the script on every page)');
        out.push(...spTable(sized.map(([k, n]) => [k, spKb(n)]), ['value', 'size']));
        out.push('');

        out.push('BY HOUR (UTC) - our own work, freezes, slow clicks and keys');
        const byHour = Object.entries(r.h).sort((a, b) => Number(a[0]) - Number(b[0])).map(([hour, b]) => {
            const sum = (g) => Object.values(g || {}).reduce((a, v) => [a[0] + v[0], a[1] + v[1]], [0, 0]);
            const w = sum(b.w);
            const f = sum(b.f);
            const i = sum(b.i);
            return [stamp(Number(hour) * SP_HOUR_MS).slice(0, 13) + 'h', spMs(w[1]), f[0], spMs(f[1]), i[0]];
        });
        out.push(...spTable(byHour, ['hour', 'work ms', 'freezes', 'frozen ms', 'slow input']));
        return out.join('\n') + '\n';
    }

    /**
     * The two files for a zip (under speed/).
     * @returns {Array<{name: string, text: string}>}
     */
    function speedFiles(record, { sizes = [], machine = null, version = null, now = Date.now() } = {}) {
        const r = speedExpand(record);
        return [
            { name: 'speed.txt', text: speedText(record, { sizes, machine, version, now }) },
            { name: 'speed.json', text: JSON.stringify({ kind: 'torn-archive-speed', v: 1, exportedAt: new Date(now).toISOString(), version, machine: machine || r.machine, sizes: Object.fromEntries(sizes), record: r }) },
        ];
    }

    /* ===== src/platform/perf.js ===== */
    /*
     * The speed log's recorder (3.17.0): the browser side of core/speed.js.
     *
     * It times work that is already happening (perfNow / perfDone around it),
     * listens to what the browser itself reports - long tasks (the tab stuck for
     * 50 ms or more) and slow clicks and key presses (the Event Timing entries
     * over 100 ms) - and is told of every read and write of a stored value
     * (platform/gm.js). Everything goes into counters in memory; the record is
     * written at most once a minute and when the tab goes, added to what the
     * other tabs stored.
     *
     * It reads nothing of the page and sends nothing anywhere: the record leaves
     * only inside a zip the player downloads (Report a problem, Export API usage).
     */




    /** The stored record: every tab adds to it (core/speed.js speedMerge). */
    const SPEED_STORE_KEY = 'speedLog';
    /** A tab writes its counts this often at most. */
    const SPEED_FLUSH_MS = 60 * 1000;

    const perfHasClock = typeof performance !== 'undefined' && typeof performance.now === 'function';
    let perfPending = speedNew();
    let perfTimer = null;
    let perfWhereOf = () => 'page';
    let perfStarted = false;

    function perfWhere() {
        let w = 'page';
        try {
            w = String(perfWhereOf() || 'page');
        } catch {
            w = 'page';
        }
        return typeof document !== 'undefined' && document.visibilityState === 'hidden' ? w + ' (hidden tab)' : w;
    }

    function perfArm() {
        if (!perfTimer && perfStarted) perfTimer = setTimeout(perfFlush, SPEED_FLUSH_MS);
    }

    /** A clock read, to hand back to perfDone. */
    function perfNow() {
        return perfHasClock ? performance.now() : 0;
    }

    /** The work that started at `t0` is done: counted under `kind`. */
    function perfDone(kind, t0) {
        if (!perfHasClock || !perfStarted) return;
        speedAdd(perfPending, 'w', kind, performance.now() - t0, perfWhere());
        perfArm();
    }

    /** Run `fn`, timed under `kind`; its result (or its error) passes through untouched. */
    function perfTimed(kind, fn) {
        if (!perfHasClock || !perfStarted) return fn();
        const t0 = performance.now();
        try {
            return fn();
        } finally {
            speedAdd(perfPending, 'w', kind, performance.now() - t0, perfWhere());
            perfArm();
        }
    }

    /** A change in the rows we watch that we did not make (`records`: how many changes it held). */
    function perfForeign(records) {
        if (!perfStarted) return;
        speedForeign(perfPending, records);
        perfArm();
    }

    /** This page load's start-up marks (ms after the page began to load). */
    function perfStartup(marks) {
        if (!perfStarted) return;
        speedStartup(perfPending, perfWhere(), marks);
        perfArm();
    }

    /** This tab's counts, added to the stored record. */
    function perfFlush() {
        if (perfTimer) clearTimeout(perfTimer);
        perfTimer = null;
        if (!speedHasData(perfPending)) return;
        const p = perfPending;
        perfPending = speedNew();
        try {
            gmSet(SPEED_STORE_KEY, speedMerge(gmGet(SPEED_STORE_KEY, null), p));
        } catch {
            /* a full or refused store: this minute's counts are let go, never an error on the page */
        }
    }

    /** The stored record with this tab's pending counts, for an export (nothing is written). */
    function perfRecord(now = Date.now()) {
        return speedMerge(gmGet(SPEED_STORE_KEY, null), perfPending, now);
    }

    /** What the browser says of the machine - what any page can read, nothing more. */
    function perfMachine() {
        const nav = typeof navigator !== 'undefined' ? navigator : {};
        const scr = typeof screen !== 'undefined' ? screen : null;
        const out = {};
        if (nav.hardwareConcurrency) out['processor threads'] = nav.hardwareConcurrency;
        // The browser rounds this down and stops at 8.
        if (nav.deviceMemory) out['memory (GB, the browser says at least)'] = nav.deviceMemory;
        if (scr) out.screen = scr.width + 'x' + scr.height;
        if (typeof devicePixelRatio === 'number') out['pixel ratio'] = Math.round(devicePixelRatio * 100) / 100;
        if (typeof innerWidth === 'number') out.window = innerWidth + 'x' + innerHeight;
        return out;
    }

    /**
     * Start recording in this tab.
     * @param {object} o
     * @param {function(): string} o.where - the kind of page this tab is on now ("bazaar", "trade", "Torn Archive")
     */
    function perfStart({ where }) {
        if (perfStarted || !perfHasClock || typeof window === 'undefined') return;
        perfStarted = true;
        if (typeof where === 'function') perfWhereOf = where;
        speedMachine(perfPending, perfMachine());
        gmSetProbe((key, write, ms, size) => {
            // Its own record is left out: a write that counted itself would always leave
            // something to write, and every tab would then write once a minute for ever.
            if (key === SPEED_STORE_KEY) return;
            speedStore(perfPending, key, write, ms, size);
            perfArm();
        });
        window.addEventListener('pagehide', perfFlush);
        if (typeof PerformanceObserver !== 'function') return;
        const types = PerformanceObserver.supportedEntryTypes || [];
        // The tab stuck for 50 ms or more: any script on the page, as the browser counts it.
        if (types.includes('longtask')) {
            try {
                new PerformanceObserver((list) => {
                    for (const e of list.getEntries()) speedAdd(perfPending, 'f', 'freeze', e.duration, perfWhere());
                    perfArm();
                }).observe({ type: 'longtask', buffered: true });
            } catch {
                /* not offered here */
            }
        }
        // A click or key press that took over 100 ms to show. One press makes several entries
        // (pointer down, up, click): each press is counted once, at its longest.
        if (types.includes('event')) {
            const seen = new Map();
            try {
                new PerformanceObserver((list) => {
                    for (const e of list.getEntries()) {
                        const id = e.interactionId;
                        if (!id || !(e.duration > 100)) continue;
                        if (seen.has(id)) continue;
                        seen.set(id, true);
                        if (seen.size > 200) seen.delete(seen.keys().next().value);
                        speedAdd(perfPending, 'i', /^key/.test(e.name) ? 'key press' : 'click', e.duration, perfWhere());
                    }
                    perfArm();
                }).observe({ type: 'event', durationThreshold: 104, buffered: true });
            } catch {
                /* not offered here */
            }
        }
    }

    /* ===== src/api/client.js ===== */
    /*
     * The one place that talks to the network.
     *
     * Non-negotiables enforced here rather than by convention:
     *
     *   1. api.torn.com is the ONLY destination. The base URL is a constant and
     *      callers pass a path, never a URL. No third party ever receives a Torn
     *      key, because no third party can be addressed from this client.
     *   2. The key is never logged. Errors are redacted before they are thrown,
     *      so a stack trace pasted into Discord cannot leak it.
     *   3. Every call goes through one rate-limited queue (<=85/min against
     *      Torn's ~100/min ceiling) with request dedup and exponential backoff.
     *      A key that trips abuse detection is a worse outcome than a slow panel.
     *
     * Torn Archive (1.0.0): 85 a minute, because it only runs while Torn Bids is
     * off (core/turns.js) and so has the whole limit to itself; `isPaused` is the
     * hook that keeps it silent while Torn Bids runs; and a missing key is its
     * own error (NoKeyError), never Torn's code 2.
     */



    const TORN_API_BASE = 'https://api.torn.com/';

    /** Torn error codes worth reacting to specifically. */
    const TORN_ERROR_KEY_INVALID = 2;
    const TORN_ERROR_RATE_LIMIT = 5;
    const TORN_ERROR_IP_BLOCK = 8;
    const TORN_ERROR_UNAVAILABLE = 9;
    const TORN_ERROR_KEY_DISABLED = 13;
    const TORN_ERROR_KEY_PAUSED = 18;

    /**
     * Errors that mean "this key must not be used again until the user changes
     * it". Torn's docs: "Multiple requests using invalid keys may result in a
     * temporary IP ban - you must account for this by removing disabled or
     * invalid keys upon error."
     */
    const KEY_DEAD_CODES = new Set([
        TORN_ERROR_KEY_INVALID,
        TORN_ERROR_KEY_DISABLED,
        TORN_ERROR_KEY_PAUSED,
    ]);

    /** Torn's rate block lasts "a small period"; 1-2-4s retries only burn it. */
    const RATE_LIMIT_BACKOFF_MS = 30000;

    /**
     * After these answers EVERY tab stops asking Torn for a while (shared through
     * storage): asking through an IP block (8) only lengthens it, and a disabled
     * API (9) or a rate block (5) will not clear in seconds either.
     */
    const TORN_PAUSE_MS = {
        [TORN_ERROR_RATE_LIMIT]: RATE_LIMIT_BACKOFF_MS,
        [TORN_ERROR_IP_BLOCK]: 10 * 60 * 1000,
        [TORN_ERROR_UNAVAILABLE]: 2 * 60 * 1000,
    };

    /*
     * What Torn's "too many" teaches (the owner, 2026-10-11: "cant it just be smart ... in the way it asks").
     * Torn counts every tool a player runs against one limit, and this client sees only its own requests. So after
     * a "too many" it holds itself to CEIL_LOWER of what it had made in that minute, never under CEIL_MIN, and takes
     * CEIL_BACK more for each quiet stretch: half an hour at first, twice as long for each further "too many" inside
     * a day. Having made fewer than CEIL_LEARN_FROM itself, it learns nothing: the limit was spent elsewhere, and
     * slowing this copy would not have helped. Kept in storage, so every tab holds to the same.
     */
    const CEIL_LOWER = 0.7;
    const CEIL_MIN = 20;
    const CEIL_LEARN_FROM = 30;
    const CEIL_BACK = 10;
    const CEIL_BACK_EVERY_MS = 30 * 60000;
    const CEIL_FORGET_MS = 24 * 60 * 60000;
    const CEIL_SLOWEST = 4;
    /** Several refusals in one go are one "too many". */
    const CEIL_ONCE_MS = 60000;

    const ceilOk = (c) => !!c && typeof c === 'object' && Number.isFinite(c.most) && Number.isFinite(c.at) && Number.isInteger(c.hits) && c.hits > 0 && Number.isFinite(c.struckAt);

    /** A hidden tab waiting for a slot checks again this often. */
    const HIDDEN_POLL_MS = 1000;

    /*
     * Priority lanes (3.15, the friend: "it struggles with the API, it maxes
     * out"). Every tab shares the one window, so each lane leaves room for the
     * lanes above it: a low call (a trader's status, networth, the Ledger
     * catching up) only goes while LOW_RESERVE slots are free, a normal one
     * (the Item Market feed, inventory) while NORMAL_RESERVE are. What you are
     * doing right now (Fill, pricing your bazaar, the item on screen) is never
     * kept waiting behind them, in this tab or another.
     */
    const API_PRIORITY = { low: 0, normal: 1, high: 2 };
    const NORMAL_RESERVE = 5;
    const LOW_RESERVE = 20;
    /* Returned by a wait that gave way to a more urgent call. */
    const YIELDED = Symbol('yielded');

    class TornApiError extends Error {
        constructor(message, { code = null, http = null, paused = false } = {}) {
            super(message);
            this.name = 'TornApiError';
            this.code = code;
            this.http = http;
            /** Refused by this client during a shared pause: nothing was sent. */
            this.paused = paused;
        }
    }

    /**
     * Refused HERE, before anything was sent, because Torn Bids is running and the
     * two scripts take turns (core/turns.js). Not an API error: Torn was never
     * asked, so it has no code, no http status, and is not written to the problem
     * log (onFailed is not called for it).
     */
    class PausedError extends Error {
        constructor(message = 'Paused while Torn Trading runs.') {
            super(message);
            this.name = 'PausedError';
            /** Nothing was sent. */
            this.local = true;
            this.takingTurns = true;
        }
    }

    /**
     * No key to send with. Not Torn's code 2 ("incorrect key"): Torn refused
     * nothing, so nothing may mark a key dead on this.
     */
    class NoKeyError extends Error {
        constructor(message = 'No API key set.') {
            super(message);
            this.name = 'NoKeyError';
            /** Nothing was sent. */
            this.local = true;
            this.noKey = true;
        }
    }

    function apiSleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    /**
     * Strip anything that looks like an API key out of a string before it can
     * reach a console, an alert, or the panel.
     */
    function redactKey(text, key) {
        let out = String(text === null || text === undefined ? '' : text);

        if (key) out = out.split(key).join('<redacted>');

        // Belt and braces: catch a key that arrived from somewhere else.
        return out.replace(/key=[A-Za-z0-9]{8,}/g, 'key=<redacted>');
    }

    class TornApiClient {
        /**
         * @param {object} options
         * @param {function(): string} options.getKey - returns the current API key
         * @param {function} [options.fetchImpl]      - injectable for tests
         * @param {number} [options.maxPerMinute]     - request ceiling
         * @param {number} [options.dedupTtlMs]       - reuse identical responses
         * @param {number} [options.maxRetries]
         * @param {function(): number[]} [options.loadWindow] - shared request
         *   timestamps, so every open Torn tab draws on ONE budget. Torn's limit
         *   is per user across all keys; a per-tab window let two tabs make
         *   140/min against a 100/min ceiling.
         * @param {function(number[])} [options.saveWindow]
         * @param {function(number)} [options.addToWindow] - record one slot of
         *   THIS tab (platform/tab-window.js); preferred over saveWindow, which
         *   writes the whole shared array back and can drop another tab's slot
         * @param {function} [options.loadPause] - () => {until, code} shared by every tab
         * @param {function} [options.savePause] - ({until, code}) => void
         * @param {function} [options.isVisible] - () => boolean; a request never
         *   leaves a hidden tab, even one that was queued while it was visible
         * @param {function} [options.loadCeil] - () => {most, at, hits, struckAt}: the
         *   ceiling learned from Torn's "too many", shared by every tab
         * @param {function} [options.saveCeil] - ({most, at, hits, struckAt}) => void
         * @param {function} [options.turnedAway] - () => boolean; the shared server
         *   does not let this copy in (api/server-link.js): while it holds a
         *   learned ceiling it also keeps under carefulMost
         * @param {number} [options.carefulMost]
         * @param {function} [options.isPaused] - () => boolean; true while Torn
         *   Bids runs: nothing is sent, a queued request is not sent either, and
         *   the call rejects with a PausedError (the two scripts take turns)
         */
        constructor({
            getKey,
            fetchImpl = gmFetch,
            maxPerMinute = 85,
            dedupTtlMs = 5000,
            maxRetries = 3,
            loadWindow = null,
            saveWindow = null,
            rateLimitBackoffMs = RATE_LIMIT_BACKOFF_MS,
            loadPause = null,
            savePause = null,
            isVisible = () => true,
            addToWindow = null,
            onSent = null,
            onFailed = null,
            isPaused = () => false,
            mayCall = null,
            loadCeil = null,
            saveCeil = null,
            turnedAway = null,
            carefulMost = 40,
        } = {}) {
            this.isPaused = isPaused;
            this.loadCeil = loadCeil;
            this.saveCeil = saveCeil;
            this.turnedAway = turnedAway;
            this.carefulMost = carefulMost;
            /** The pace with nothing learned: a ceiling back at it is no ceiling. */
            this.ceilTop = maxPerMinute;
            this.ceil = null;
            /** (now, this tab's calls of the last minute) => boolean: room beside the shared server's part of your limit (core/server.js). */
            this.mayCall = mayCall;
            /** () => void, a call is being held back for it. */
            this.onHeld = null;
            /** ({path, tag, error}) => void, a call that failed for good (not each retry): the problem log (3.15). */
            this.onFailed = onFailed;
            /** ({path, params, tag, priority}) => void, each request that leaves (retries too): the usage record. */
            this.onSent = onSent;
            this.addToWindow = addToWindow;
            this.loadPause = loadPause;
            this.savePause = savePause;
            this.isVisible = isVisible;
            this.pause = { until: 0, code: null };
            this.getKey = getKey;
            this.fetchImpl = fetchImpl;
            this.maxPerMinute = maxPerMinute;
            this.dedupTtlMs = dedupTtlMs;
            this.maxRetries = maxRetries;
            this.loadWindow = loadWindow;
            this.saveWindow = saveWindow;
            this.rateLimitBackoffMs = rateLimitBackoffMs;

            /** Timestamps of recent requests, for the sliding window. */
            this.recent = [];
            /** Waiting calls, most urgent first; one runs at a time, so the window check cannot race. */
            this.queue = [];
            this.pumping = false;
            this.seq = 0;
            /** In-flight and recently-completed requests, keyed without the key. */
            this.inflight = new Map();
            this.cache = new Map();
        }

        /** Requests made in the last 60s, and room remaining. */
        stats(now = Date.now()) {
            this.syncWindow(now);
            const window = this.recent.filter((t) => now - t < 60000);
            return {
                usedLastMinute: window.length,
                remaining: Math.max(0, this.limitNow(now) - window.length),
                /** Held under its pace since a "too many" (null = it is not). */
                ceil: this.ceilNow(now),
            };
        }

        /** The learned ceiling as it was last set: this tab's or storage's, the later. */
        ceilKept() {
            let kept = this.ceil;
            if (this.loadCeil) {
                try {
                    const shared = this.loadCeil();
                    if (ceilOk(shared) && (!kept || shared.struckAt >= kept.struckAt)) kept = shared;
                } catch {
                    // Sharing is best-effort.
                }
            }
            return kept;
        }

        /** The learned ceiling now (null = none): a step up for each quiet stretch, gone once it is back at the pace. */
        ceilNow(now = Date.now()) {
            const kept = this.ceilKept();
            if (!kept) return null;
            const wait = CEIL_BACK_EVERY_MS * 2 ** Math.min(CEIL_SLOWEST, kept.hits - 1);
            const most = kept.most + CEIL_BACK * Math.max(0, Math.floor((now - kept.at) / wait));
            return most >= this.ceilTop ? null : most;
        }

        /** Torn said "too many": hold under what was made in the minute before. */
        learn(now = Date.now()) {
            const had = this.ceilKept();
            if (had && now - had.struckAt < CEIL_ONCE_MS) return;
            this.syncWindow(now);
            const used = this.recent.filter((t) => now - t < 60000).length;
            if (used < CEIL_LEARN_FROM) return;
            this.ceil = {
                most: Math.max(CEIL_MIN, Math.floor(CEIL_LOWER * Math.min(this.ceilNow(now) ?? Infinity, used))),
                at: now,
                hits: had && now - had.struckAt < CEIL_FORGET_MS ? had.hits + 1 : 1,
                struckAt: now,
            };
            if (this.saveCeil) {
                try {
                    this.saveCeil(this.ceil);
                } catch {
                    // This tab still holds to it.
                }
            }
        }

        /** The most requests a minute right now: the share, what Torn's "too many" taught, and the careful pace. */
        limitNow(now = Date.now()) {
            const ceil = this.ceilNow(now);
            if (ceil === null) return this.maxPerMinute;
            let away = false;
            try {
                away = !!(this.turnedAway && this.turnedAway());
            } catch {
                // A hook that throws does not stop the reads.
            }
            return Math.min(this.maxPerMinute, ceil, away ? this.carefulMost : Infinity);
        }

        /**
         * Adopt the shared window: it already holds this tab's own requests,
         * because every slot taken is saved back to it. Replacing rather than
         * merging matters - two requests in the same millisecond are two
         * requests, and a Set of timestamps would count them as one.
         */
        syncWindow(now = Date.now()) {
            if (!this.loadWindow) return;

            let shared;
            try {
                shared = this.loadWindow();
            } catch {
                return;
            }
            if (!Array.isArray(shared)) return;

            this.recent = shared
                .filter((t) => Number.isFinite(t) && now - t < 60000)
                .sort((a, b) => a - b);
        }

        /** How many of the window's slots this lane may fill. */
        laneLimit(priority = API_PRIORITY.normal, now = Date.now()) {
            const reserve = priority >= API_PRIORITY.high ? 0 : priority >= API_PRIORITY.normal ? NORMAL_RESERVE : LOW_RESERVE;
            return Math.max(1, this.limitNow(now) - reserve);
        }

        /**
         * Block until the sliding window has room for one more request of this
         * lane. `shouldYield` (the first attempt only): a more urgent call has
         * arrived - give way to it (returns YIELDED, no slot taken).
         */
        async waitForSlot(priority = API_PRIORITY.high, shouldYield = null) {
            for (;;) {
                if (shouldYield && shouldYield()) return YIELDED;
                const now = Date.now();
                this.syncWindow(now);
                this.recent = this.recent.filter((t) => now - t < 60000);

                // Hidden: take no slot and send nothing until the tab is back.
                if (!this.isVisible()) {
                    await apiSleep(HIDDEN_POLL_MS);
                    continue;
                }

                if (this.mayCall && !this.mayCall(now, this.recent)) {
                    if (this.onHeld) this.onHeld();
                    await apiSleep(HIDDEN_POLL_MS);
                    continue;
                }

                const limit = this.laneLimit(priority, now);
                if (this.recent.length < limit) {
                    this.recent.push(now);
                    if (this.addToWindow) {
                        try {
                            this.addToWindow(now);
                        } catch {
                            // Best-effort, as below.
                        }
                    } else if (this.saveWindow) {
                        try {
                            this.saveWindow(this.recent);
                        } catch {
                            // Sharing the window is best-effort; the local one
                            // still limits this tab.
                        }
                    }
                    return;
                }

                // The slot this lane waits for: the one that brings the window under its limit.
                const frees = this.recent[this.recent.length - limit] || this.recent[0];
                const wait = Math.max(50, 60000 - (now - frees) + 25);
                // Waiting with a lane below: look again each second for a more urgent call.
                await apiSleep(shouldYield ? Math.min(wait, 1000) : wait);
            }
        }

        /**
         * GET a Torn API path.
         *
         * @param {string} path - e.g. "torn" or "user" or "market/123"
         * @param {object} params - query params; `key` is added here and only here
         */
        async get(path, params = {}, { tag = null, priority = 'high' } = {}) {
            const cacheKey = path + '?' + new URLSearchParams(params).toString();
            const prio = API_PRIORITY[priority] ?? API_PRIORITY.high;

            const cached = this.cache.get(cacheKey);
            if (cached && Date.now() - cached.at < this.dedupTtlMs) {
                return cached.data;
            }

            const existing = this.inflight.get(cacheKey);
            if (existing) {
                // Asked again, more urgently: the waiting call moves up.
                const job = this.queue.find((j) => j.cacheKey === cacheKey);
                if (job && prio > job.prio) job.prio = prio;
                return existing;
            }

            // Queued by lane (most urgent first, then in order), then a slot.
            const promise = new Promise((resolve, reject) => {
                this.queue.push({ seq: this.seq++, path, params, cacheKey, tag, prio, resolve, reject });
            });
            this.pump();
            this.inflight.set(cacheKey, promise);

            try {
                const data = await promise;
                this.pruneCache();
                this.cache.set(cacheKey, { at: Date.now(), data });
                return data;
            } finally {
                this.inflight.delete(cacheKey);
            }
        }

        /** The dedup cache is for bursts, not memory; a sweep adds hundreds. */
        pruneCache(now = Date.now()) {
            for (const [k, v] of this.cache) {
                if (now - v.at >= this.dedupTtlMs) this.cache.delete(k);
            }
        }

        /** Run the waiting calls one at a time, the most urgent first. */
        async pump() {
            if (this.pumping) return;
            this.pumping = true;
            try {
                while (this.queue.length) {
                    this.queue.sort((a, b) => b.prio - a.prio || a.seq - b.seq);
                    const job = this.queue[0];
                    const shouldYield = () => this.queue.some((j) => j !== job && j.prio > job.prio);
                    let out;
                    try {
                        out = { value: await this.execute(job.path, job.params, job.cacheKey, job, shouldYield) };
                    } catch (error) {
                        out = { error };
                        // Taking turns is not a failure: nothing was asked.
                        if (this.onFailed && !(error instanceof PausedError)) {
                            try {
                                this.onFailed({ path: job.path, tag: job.tag, error });
                            } catch {
                                // The log is best-effort.
                            }
                        }
                    }
                    if (out.value === YIELDED) continue;
                    this.queue.splice(this.queue.indexOf(job), 1);
                    if ('error' in out) job.reject(out.error);
                    else job.resolve(out.value);
                }
            } finally {
                this.pumping = false;
            }
        }

        /** While Torn Bids runs, nothing goes to Torn (its own error: not a key problem, not an API answer). */
        throwIfTakingTurns() {
            let paused = false;
            try {
                paused = !!(this.isPaused && this.isPaused());
            } catch {
                // A hook that throws does not stop the reads.
            }
            if (paused) throw new PausedError();
        }

        async execute(path, params, cacheKey, job = null, shouldYield = null) {
            const prio = job ? job.prio : API_PRIORITY.high;
            if (!this.fetchImpl) {
                throw new TornApiError('No fetch implementation available.');
            }

            this.throwIfTakingTurns();
            const key = this.getKey ? this.getKey() : '';
            if (!key) {
                // Nothing to send with: not a key Torn refused (no code, so nothing marks a key dead).
                throw new NoKeyError();
            }

            let attempt = 0;
            let lastError = null;
            // A pause this call started itself (a rate block it is waiting out)
            // does not stop its own retry; a longer one from elsewhere does.
            let mine = 0;

            while (attempt <= this.maxRetries) {
                this.throwIfPaused(mine);
                this.throwIfTakingTurns();
                // Only the first wait gives way to a more urgent call (a retry keeps its turn).
                if ((await this.waitForSlot(prio, attempt === 0 ? shouldYield : null)) === YIELDED) return YIELDED;
                // Another tab may have hit a block while this one waited.
                this.throwIfPaused(mine);
                // Torn Bids may have been opened while this one waited: a queued request is not sent either.
                this.throwIfTakingTurns();
                if (this.onSent) {
                    try {
                        this.onSent({ path, params, tag: job ? job.tag : null, priority: prio });
                    } catch {
                        // The usage record is best-effort.
                    }
                }

                try {
                    return await this.requestOnce(path, params, key);
                } catch (error) {
                    lastError = error;
                    mine = Math.max(mine, this.pauseFor(error));

                    if (!this.isRetryable(error) || attempt === this.maxRetries) {
                        throw error;
                    }

                    // Torn's rate block outlasts a quick retry; wait it out.
                    // Otherwise exponential backoff: 1s, 2s, 4s.
                    const rateLimited =
                        error instanceof TornApiError &&
                        (error.code === TORN_ERROR_RATE_LIMIT || error.http === 429);

                    await apiSleep(
                        rateLimited
                            ? this.rateLimitBackoffMs
                            : 1000 * Math.pow(2, attempt),
                    );
                    attempt += 1;
                }
            }

            throw lastError;
        }

        /** The shared pause, the later of this tab's and storage's. */
        currentPause(now = Date.now()) {
            let p = this.pause;
            if (this.loadPause) {
                try {
                    const s = this.loadPause();
                    if (s && Number(s.until) > p.until) p = { until: Number(s.until), code: s.code ?? null };
                } catch {
                    // Sharing is best-effort.
                }
            }
            return now < p.until ? p : null;
        }

        throwIfPaused(ignoreUntil = 0) {
            const p = this.currentPause();
            if (!p || p.until <= ignoreUntil) return;
            const secs = Math.ceil((p.until - Date.now()) / 1000);
            const why = p.code === TORN_ERROR_IP_BLOCK ? 'Torn has blocked this IP for a while' : p.code === TORN_ERROR_UNAVAILABLE ? 'the Torn API is down' : 'Torn asked us to slow down';
            throw new TornApiError('Paused: ' + why + '. Trying again in ' + (secs >= 90 ? Math.ceil(secs / 60) + ' min' : secs + 's') + '.', { code: p.code, paused: true });
        }

        /** Start a shared pause after an answer that asking again cannot fix soon. */
        pauseFor(error) {
            const code = error instanceof TornApiError ? error.code : null;
            // Torn's code 5, or an HTTP 429 (no code): every tab slows down, not just this one.
            const rateLimited = code === TORN_ERROR_RATE_LIMIT || (error instanceof TornApiError && error.http === 429);
            const ms = rateLimited ? this.rateLimitBackoffMs : TORN_PAUSE_MS[code];
            if (!ms || error.paused) return 0;
            if (rateLimited) this.learn();
            const until = Date.now() + ms;
            if (until <= this.pause.until) return until;
            this.pause = { until, code };
            if (this.savePause) {
                try {
                    this.savePause(this.pause);
                } catch {
                    // This tab still pauses.
                }
            }
            return until;
        }

        isRetryable(error) {
            // A shared pause is waited out by the caller, not retried here.
            if (error instanceof TornApiError && error.paused) return false;
            if (error instanceof TornApiError && error.code === TORN_ERROR_UNAVAILABLE) return false;
            if (!(error instanceof TornApiError)) return true;

            if (error.code === TORN_ERROR_RATE_LIMIT) return true;
            if (error.code === TORN_ERROR_UNAVAILABLE) return true;
            if (error.http && error.http >= 500) return true;
            if (error.http === 429) return true;

            // A bad key or an IP block will not fix itself by asking again.
            return false;
        }

        async requestOnce(path, params, key) {
            /*
             * v1 paths take a trailing slash ("torn/?selections=items" is the form
             * verified in game). v2 paths are written without one everywhere they
             * are documented, so they are left exactly as given.
             */
            const clean = String(path).replace(/^\/+/, '');
            const url = new URL(
                /^v2\//.test(clean) ? clean : clean + '/',
                TORN_API_BASE,
            );

            /*
             * A relative path resolves under the base, but an ABSOLUTE one
             * ("https://elsewhere/steal") overrides it entirely — and the key is
             * attached below. The base being a constant is therefore not enough
             * on its own; this is the assertion that actually enforces "one
             * destination".
             */
            if (url.hostname !== 'api.torn.com') {
                throw new TornApiError(
                    'Refusing to send the API key to ' + url.hostname + '.',
                );
            }

            for (const [name, value] of Object.entries(params || {})) {
                if (value === undefined || value === null) continue;
                url.searchParams.set(name, String(value));
            }
            url.searchParams.set('key', key);
            url.searchParams.set('comment', 'TornArchive');

            let response;
            try {
                response = await this.fetchImpl(url.toString());
            } catch (error) {
                throw new TornApiError(
                    'Network error: ' + redactKey(error && error.message, key),
                );
            }

            if (!response.ok) {
                throw new TornApiError('HTTP ' + response.status, {
                    http: response.status,
                });
            }

            let data;
            try {
                data = await response.json();
            } catch {
                throw new TornApiError('Torn API returned invalid JSON.');
            }

            /*
             * Errors arrive as HTTP 200 with { error: { code, error } } - and
             * some v2 endpoints are reported to put { code, error } at the top
             * level instead. Read both, or a v2 error looks like an empty result.
             */
            const err =
                data && data.error && typeof data.error === 'object'
                    ? data.error
                    : data &&
                        Number.isFinite(Number(data.code)) &&
                        typeof data.error === 'string'
                      ? { code: Number(data.code), error: data.error }
                      : null;

            if (err) {
                throw new TornApiError(
                    'Torn API ' + err.code + ': ' + redactKey(err.error, key),
                    { code: Number(err.code) },
                );
            }

            return data;
        }
    }

    /* ===== src/core/ledger.js ===== */
    /*
     * Torn Ledger: what you made, from your own Torn log. Pure - no DOM, no
     * network, no key. main.js reads the log with the Ledger's own Full key
     * (see api/ledger.js) and hands the entries here.
     *
     * Every buy and sell becomes one row: time, item, quantity, price each,
     * where (bazaar, Item Market, trade), with whom, and the fee. Only these
     * derived rows are kept - never the log's own text.
     *
     * Profit is first in, first out: a sale uses up the oldest units you
     * bought of that item, and makes (what you got, after the Item Market's
     * fee) minus (what those units cost). Units sold with no buy on record
     * (bought before the Ledger started) have no known cost: they are counted
     * apart, never guessed.
     *
     * Log types (Torn API v2 /user/log):
     *   1225 Bazaar buy    {seller, items: [{id, qty}], cost_each, cost_total}
     *   1226 Bazaar sell   {buyer,  items, cost_each, cost_total}
     *   1112 Item Market buy  {seller, anonymous, items, cost_each, cost_total}
     *   1113 Item Market sell {buyer, anonymous, items, cost_each, fee, cost_total} - cost_total is AFTER the fee
     *   4210 Item shop sell (to an NPC)  {item, quantity, value_each, total_value}
     *   4200 Item shop buy (a city shop) {item, quantity, cost_total}
     *   4201 Item abroad buy             {item, quantity, cost_total}
     *   8156 Attack mug receive          you were mugged: the amount lost (see mugFromLog)
     * Trades come from /user/trades and /user/{id}/trade (typed items and money
     * for each side).
     *
     * Buying on the Item Market or in a bazaar under the NPC price and selling to
     * the NPC is the overlay's whole job: an NPC sale is matched to what its units
     * cost like any other, so it shows its profit and whom they were bought from.
     *
     * Cut for Torn Archive from Torn Bids 3.24.0 (core/ledger.js): the rows (from
     * the log, from a trade), the muggings, first in first out, and the store's
     * shape. Price records of accepted trades, the filters, totals, receipts and
     * the Sold view are left behind.
     */

    const LEDGER_VERSION = 1;

    const LOG_BAZAAR_BUY = 1225;
    const LOG_BAZAAR_SELL = 1226;
    const LOG_MARKET_BUY = 1112;
    const LOG_MARKET_SELL = 1113;
    const LOG_SHOP_SELL = 4210;
    const LOG_SHOP_BUY = 4200;
    const LOG_ABROAD_BUY = 4201;
    const LOG_MUGGED = 8156;
    const LEDGER_LOG_TYPES = [LOG_BAZAAR_BUY, LOG_BAZAAR_SELL, LOG_MARKET_BUY, LOG_MARKET_SELL, LOG_SHOP_SELL, LOG_SHOP_BUY, LOG_ABROAD_BUY, LOG_MUGGED];

    const VENUE_NAMES = { bazaar: 'Bazaar', market: 'Item Market', trade: 'Trade', npc: 'NPC shop', shop: 'City shop', abroad: 'Abroad' };

    function emptyLedger() {
        return { version: LEDGER_VERSION, rows: [], mugs: [], mugKeys: [], newestAt: 0, oldestAt: 0, backfilled: false, tradesAt: 0, tradeIds: [], logCount: 0, readAt: 0 };
    }

    /** A stored ledger, or a fresh one when missing or from another version. */
    function readLedger(stored) {
        if (!stored || typeof stored !== 'object' || stored.version !== LEDGER_VERSION || !Array.isArray(stored.rows)) return emptyLedger();
        return { ...emptyLedger(), ...stored };
    }

    const ledgerNum = (v) => {
        const n = Number(v);
        return Number.isFinite(n) ? n : 0;
    };

    /**
     * The rows one log entry makes (none for a type the Ledger does not count).
     * @param {{id, timestamp, details: {id}, data}} entry
     */
    function rowsFromLog(entry) {
        if (!entry || !entry.details || !entry.data) return [];
        const type = Number(entry.details.id);
        const d = entry.data;
        const t = ledgerNum(entry.timestamp) * 1000;
        // One item each: selling to an NPC shop, buying in a city shop or abroad.
        if (type === LOG_SHOP_SELL || type === LOG_SHOP_BUY || type === LOG_ABROAD_BUY) {
            const itemId = ledgerNum(d.item);
            const qty = ledgerNum(d.quantity) || 1;
            if (!t || !(itemId > 0) || !(qty > 0)) return [];
            const total = type === LOG_SHOP_SELL ? ledgerNum(d.total_value) : ledgerNum(d.cost_total);
            const each = total ? total / qty : ledgerNum(type === LOG_SHOP_SELL ? d.value_each : d.cost_each);
            return [{
                id: String(entry.id) + ':0',
                t,
                itemId: String(itemId),
                qty,
                each,
                fee: 0,
                side: type === LOG_SHOP_SELL ? 'sell' : 'buy',
                venue: type === LOG_SHOP_SELL ? 'npc' : type === LOG_SHOP_BUY ? 'shop' : 'abroad',
                who: null,
                whoName: null,
            }];
        }
        const items = Array.isArray(d.items) ? d.items : [];
        const venue = type === LOG_BAZAAR_BUY || type === LOG_BAZAAR_SELL ? 'bazaar' : type === LOG_MARKET_BUY || type === LOG_MARKET_SELL ? 'market' : null;
        if (!venue || !t || !items.length) return [];
        const side = type === LOG_BAZAAR_BUY || type === LOG_MARKET_BUY ? 'buy' : 'sell';
        const who = side === 'buy' ? d.seller : d.buyer;
        const totalQty = items.reduce((a, it) => a + Math.max(0, ledgerNum(it && it.qty)), 0) || 1;
        // The fee (Item Market sales) is shared across the entry's units.
        const feeEach = type === LOG_MARKET_SELL ? ledgerNum(d.fee) / totalQty : 0;
        let each = ledgerNum(d.cost_each);
        if (!each && ledgerNum(d.cost_total)) each = (ledgerNum(d.cost_total) + ledgerNum(d.fee)) / totalQty;
        return items
            .filter((it) => it && ledgerNum(it.id) > 0 && ledgerNum(it.qty) > 0)
            .map((it, i) => ({
                id: String(entry.id) + ':' + i,
                t,
                itemId: String(it.id),
                qty: ledgerNum(it.qty),
                each,
                fee: Math.round(feeEach * ledgerNum(it.qty)),
                side,
                venue,
                who: who ? String(who) : null,
                whoName: null,
            }));
    }

    /**
     * The rows one finished trade makes. Money you gave buys what you got;
     * money you got pays for what you gave. Several items on one side share the
     * money by their Item Market Average. Items you got for no money are bought
     * at $0; items you gave for no money are "given" (they leave your stock,
     * with no sale counted).
     *
     * @param {object} trade - /user/{id}/trade: {id, completed_at|timestamp, trader: {id, name}, user, items: [{user_id, type, details}]}
     * @param {string} selfId - your Torn id
     * @param {function} valueOf - (itemId) => the Item Market Average, for sharing money
     */
    /**
     * @param {function} [priceOf] - (itemId) => what the trader agreed to pay for one (their accepted
     *   prices), or 0. When every item you gave has one, the money they paid is split by those, and
     *   the rows say `split: 'price'`; otherwise by Item Market Average (`split: 'value'`).
     */
    function rowsFromTrade(trade, selfId, valueOf = () => 1, priceOf = null) {
        if (!trade || !Array.isArray(trade.items) || !selfId) return [];
        const self = String(selfId);
        const t = ledgerNum(trade.completed_at || trade.timestamp || trade.modified_at) * 1000;
        if (!t) return [];
        const other = [trade.trader, trade.user].find((p) => p && String(p.id) !== self) || null;
        const mine = trade.items.filter((x) => x && String(x.user_id) === self);
        const theirs = trade.items.filter((x) => x && String(x.user_id) !== self);
        const money = (list) => list.filter((x) => x.type === 'Money').reduce((a, x) => a + ledgerNum(x.details && x.details.amount), 0);
        const goods = (list) => list.filter((x) => x.type === 'Item' && x.details && ledgerNum(x.details.id) > 0 && ledgerNum(x.details.amount) > 0).map((x) => ({ itemId: String(x.details.id), qty: ledgerNum(x.details.amount) }));
        const gave = goods(mine);
        const got = goods(theirs);
        const paid = money(mine);
        const received = money(theirs);
        const rows = [];
        const share = (list, total) => {
            const weights = list.map((g) => Math.max(1, ledgerNum(valueOf(g.itemId))) * g.qty);
            const sum = weights.reduce((a, w) => a + w, 0) || 1;
            return list.map((g, i) => (total * weights[i]) / sum / g.qty);
        };
        const base = {
            venue: 'trade',
            who: other && other.id ? String(other.id) : null,
            whoName: other && other.name ? String(other.name) : null,
            fee: 0,
            t,
        };
        // Items for items with no money either way: a swap, not priced.
        if (gave.length && got.length && !paid && !received) return [];
        if (got.length) {
            const eachs = share(got, gave.length ? 0 : paid);
            got.forEach((g, i) => rows.push({ ...base, id: 'trade:' + trade.id + ':in:' + i, itemId: g.itemId, qty: g.qty, each: eachs[i], side: 'buy' }));
        }
        if (gave.length) {
            // What they agreed to pay for each, when known for every item: the split follows it.
            const agreed = priceOf && received > 0 ? gave.map((g) => ledgerNum(priceOf(g.itemId))) : null;
            const byPrice = Boolean(agreed && agreed.every((p) => p > 0));
            const eachs = byPrice ? (() => {
                const sum = gave.reduce((a, g, i) => a + agreed[i] * g.qty, 0);
                return gave.map((g, i) => (received * agreed[i]) / sum);
            })() : share(gave, received);
            // What they agreed to pay for each is kept with the row: "did they pay their
            // list" survives the accepted prices being forgotten (review L9).
            gave.forEach((g, i) => rows.push({ ...base, id: 'trade:' + trade.id + ':out:' + i, itemId: g.itemId, qty: g.qty, each: eachs[i], side: received > 0 ? 'sell' : 'give', ...(received > 0 ? { split: byPrice ? 'price' : 'value' } : {}), ...(byPrice ? { agreed: agreed[i] } : {}) }));
        }
        return rows;
    }

    /**
     * A mugging you suffered (8156), or null. Torn's docs do not type this
     * entry's fields, so the amount is read from the names Torn uses for mugging
     * money (money_mugged, money, amount...); one it cannot read is kept with
     * amount null and counted apart - never guessed. `keys` lists the field names
     * seen (names only), so an unread shape can be fixed.
     */
    function mugFromLog(entry) {
        if (!entry || !entry.details || Number(entry.details.id) !== LOG_MUGGED) return null;
        const d = entry.data || {};
        const t = ledgerNum(entry.timestamp) * 1000;
        if (!t) return null;
        let amount = null;
        for (const k of ['money_mugged', 'money', 'amount', 'mugged', 'money_lost', 'value', 'total']) {
            const n = Number(d[k]);
            if (Number.isFinite(n) && n > 0) {
                amount = n;
                break;
            }
        }
        const who = d.attacker || d.attacker_id || d.user || d.mugger || null;
        return {
            id: String(entry.id),
            t,
            amount,
            who: who && typeof who !== 'object' ? String(who) : who && who.id ? String(who.id) : null,
            anonymous: Boolean(d.anonymous) || !who,
            keys: Object.keys(d).sort(),
        };
    }

    /** New muggings into the ledger, each once (by id). Returns how many were new. */
    function addMugs(ledger, mugs) {
        if (!Array.isArray(ledger.mugs)) ledger.mugs = [];
        const have = new Set(ledger.mugs.map((m) => m.id));
        const keys = new Set(ledger.mugKeys || []);
        let added = 0;
        for (const m of mugs) {
            if (!m || have.has(m.id)) continue;
            have.add(m.id);
            const { keys: k, ...rest } = m;
            for (const name of k || []) keys.add(name);
            ledger.mugs.push(rest);
            added += 1;
        }
        if (added) ledger.mugs.sort((a, b) => a.t - b.t);
        ledger.mugKeys = [...keys].sort().slice(0, 30);
        return added;
    }

    /** What muggings took in a time range: {lost, count, unknown, biggest}. */
    function mugTotals(mugs, { from = null, to = null } = {}) {
        const out = { lost: 0, count: 0, unknown: 0, biggest: 0 };
        for (const m of mugs || []) {
            if (from && m.t < from) continue;
            if (to && m.t > to) continue;
            out.count += 1;
            if (m.amount > 0) {
                out.lost += m.amount;
                if (m.amount > out.biggest) out.biggest = m.amount;
            } else out.unknown += 1;
        }
        return out;
    }

    /** New rows into the ledger, each once (by id), oldest first. Returns how many were new. */
    function addLedgerRows(ledger, rows) {
        const have = new Set(ledger.rows.map((r) => r.id));
        let added = 0;
        for (const r of rows) {
            if (!r || have.has(r.id)) continue;
            have.add(r.id);
            ledger.rows.push(r);
            added += 1;
        }
        if (added) ledger.rows.sort((a, b) => a.t - b.t || String(a.id).localeCompare(String(b.id)));
        return added;
    }

    /**
     * First in, first out, over EVERY row (a filter must not change what a sale
     * cost). Each sale gets `cost` (null for units with no buy on record),
     * `profit`, `net` (after the fee) and where its units came from.
     *
     * @returns {Map<string, object>} row id -> {net, cost, profit, unknownQty, from: [{who, whoName, venue, qty, each}]}
     */
    function matchFifo(rows) {
        const lots = new Map();
        const out = new Map();
        for (const r of rows) {
            let q = lots.get(r.itemId);
            if (!q) {
                q = [];
                lots.set(r.itemId, q);
            }
            if (r.side === 'buy') {
                q.push({ qty: r.qty, each: r.each, who: r.who, whoName: r.whoName, venue: r.venue });
                continue;
            }
            let left = r.qty;
            let cost = 0;
            const from = [];
            while (left > 0 && q.length) {
                const lot = q[0];
                const n = Math.min(left, lot.qty);
                cost += n * lot.each;
                from.push({ who: lot.who, whoName: lot.whoName, venue: lot.venue, qty: n, each: lot.each });
                lot.qty -= n;
                left -= n;
                if (lot.qty <= 0) q.shift();
            }
            if (r.side === 'give') continue;
            const matched = r.qty - left;
            const net = r.each * r.qty - (r.fee || 0);
            // Profit only on units whose cost is known: their share of the net.
            const netMatched = r.qty ? (net * matched) / r.qty : 0;
            out.set(r.id, {
                net,
                cost: matched ? cost : null,
                profit: matched ? netMatched - cost : null,
                unknownQty: left,
                from,
            });
        }
        return out;
    }

    /** The oldest and newest log time among entries, for the next incremental read. */
    function logSpan(entries) {
        let min = Infinity;
        let max = 0;
        for (const e of entries || []) {
            const t = ledgerNum(e && e.timestamp);
            if (!t) continue;
            if (t < min) min = t;
            if (t > max) max = t;
        }
        return { min: min === Infinity ? 0 : min, max };
    }

    /* ===== src/api/ledger.js ===== */
    /*
     * The Torn Ledger's API client: a Full key, used for nothing but your own
     * log and trades.
     *
     * The Full key can read everything on the account, so this client is walled
     * in by code, not by care: its URL check allows only these api.torn.com
     * paths, and any other is refused before the key is attached - a bug
     * elsewhere cannot spend it on anything else.
     *
     *   /v2/key/info          - to check the key is Full, and whose it is
     *   /v2/user/log          - bazaar and Item Market buys and sells
     *   /v2/user/trades       - your finished trades, and (3.24.0, Sets) the ones open now
     *   /v2/user/{id}/trade   - one trade's items and money
     *
     * It shares the one request window (85 a minute across every tab) with the
     * other clients. Torn Bids makes one - and, since 3.16.3, so does the Torn
     * page you are viewing, for ONE question only: did a trade you accepted go
     * through (/v2/user/trades and that trade), asked there only while no Torn
     * Bids tab is open to ask it, and only from the tab in view. The panel on
     * torn.com reads the Ledger's key for nothing else: never your log.
     */




    /** The only paths the Ledger's key is ever sent to. */
    const LEDGER_PATHS = [/^\/v2\/key\/info$/, /^\/v2\/user\/log$/, /^\/v2\/user\/trades$/, /^\/v2\/user\/\d+\/trade$/];

    /** The only query parameters each path may carry (the key and comment are added by the client). */
    const LEDGER_PARAMS = [
        [/^\/v2\/key\/info$/, []],
        [/^\/v2\/user\/log$/, ['log', 'from', 'to', 'limit']],
        [/^\/v2\/user\/trades$/, ['cat', 'from', 'limit', 'sort']],
        [/^\/v2\/user\/\d+\/trade$/, []],
    ];

    function ledgerParamsAllowed(path, params = {}) {
        let pathname;
        try {
            pathname = new URL(String(path).replace(/^\/+/, ''), TORN_API_BASE).pathname;
        } catch {
            return false;
        }
        const rule = LEDGER_PARAMS.find(([re]) => re.test(pathname));
        if (!rule) return false;
        return Object.keys(params || {}).every((k) => rule[1].includes(k));
    }

    function ledgerPathAllowed(path) {
        // A path carries no query or fragment of its own: parameters go through params, which are checked.
        if (/[?#]/.test(String(path))) return false;
        try {
            const clean = String(path).replace(/^\/+/, '');
            const url = new URL(clean, TORN_API_BASE);
            return url.hostname === 'api.torn.com' && LEDGER_PATHS.some((re) => re.test(url.pathname));
        } catch {
            return false;
        }
    }

    class LedgerClient extends TornApiClient {
        /** The Ledger is never urgent (3.15): the low lane, unless a call says otherwise (checking a key you just saved). */
        get(path, params = {}, use = {}) {
            return super.get(path, params, { tag: 't.ledger', priority: 'low', ...use });
        }

        async requestOnce(path, params, key) {
            if (!ledgerPathAllowed(path) || !ledgerParamsAllowed(path, params)) {
                throw new TornApiError('The Ledger key is only for your log and trades; refused ' + String(path).split('?')[0] + '.');
            }
            return super.requestOnce(path, params, key);
        }
    }

    /**
     * Whose key it is and what it may read (v2 key/info).
     * @returns {{level: number|null, type: string|null, userId: string|null}}
     */
    async function fetchLedgerKeyInfo(client) {
        const data = await client.get('v2/key/info', {}, { priority: 'high' });
        const info = (data && data.info) || {};
        const access = info.access || {};
        const level = Number(access.level);
        return {
            level: Number.isFinite(level) ? level : null,
            type: typeof access.type === 'string' ? access.type : null,
            userId: info.user && info.user.id ? String(info.user.id) : null,
        };
    }

    /** A Full key: level 4, or Torn's own words for it. */
    function isFullKey(info) {
        return Boolean(info && (info.level === 4 || /^full/i.test(String(info.type || ''))));
    }

    /**
     * One page of your log (newest first, at most 100): the four trade types.
     * `from` / `to` are Torn timestamps (seconds), both inclusive.
     */
    async function fetchLogPage(client, { from = null, to = null, types = LEDGER_LOG_TYPES, use = undefined } = {}) {
        const params = { log: types.join(','), limit: 100 };
        if (from) params.from = from;
        if (to) params.to = to;
        const data = await client.get('v2/user/log', params, use);
        return Array.isArray(data && data.log) ? data.log : [];
    }

    /** Your finished trades since `from` (seconds), oldest first, at most 100. */
    async function fetchTradesPage(client, { from = null, use = undefined } = {}) {
        const params = { cat: 'finished', limit: 100, sort: 'ASC' };
        if (from) params.from = from;
        const data = await client.get('v2/user/trades', params, use);
        return Array.isArray(data && data.trades) ? data.trades : [];
    }

    /**
     * Your trades that are open now (3.24.0, Sets: the note when a trade is opened with you), newest first.
     * The same path and parameters as the finished ones; Torn's word for the category is "ongoing".
     */
    async function fetchTradesOpen(client, { use = undefined } = {}) {
        const data = await client.get('v2/user/trades', { cat: 'ongoing', limit: 20, sort: 'DESC' }, use);
        return Array.isArray(data && data.trades) ? data.trades : [];
    }

    /** One trade: both sides' items and money. */
    async function fetchTrade(client, tradeId, use = undefined) {
        const id = String(tradeId).replace(/\D/g, '');
        if (!id) return null;
        const data = await client.get('v2/user/' + id + '/trade', {}, use);
        return (data && data.trade) || null;
    }

    /* ===== src/api/w3b.js ===== */
    /*
     * TornW3B (weav3r.dev) - the crowd-sourced bazaar price feed.
     *
     * Torn's API has no per-listing bazaar prices a Public key can trust (the
     * `user -> bazaar` selection can be served days old on a Public key, and the
     * `market -> bazaar` selection is a directory with no prices). TornW3B polls
     * bazaars with keys their SELLERS donated, for their own bazaar only, and
     * publishes the result. TornTools, TornPDA and Weav3r's own script read it.
     *
     * Non-negotiables, enforced here rather than by convention:
     *
     *   1. This client NEVER sees a Torn API key - nor any key at all. It has no
     *      key parameter, no getKey, and the only query it ever sends is `comment`
     *      and, since 3.23.0, the whole numbers of W3B_QUERY (one: a count of
     *      hours) - a name not in that list, or a value that is not a whole number
     *      within its range, is dropped. The Torn client and this one share nothing.
     *   2. weav3r.dev is the only destination - asserted on the resolved URL, not
     *      just implied by a constant, exactly as client.js does for api.torn.com.
     *   3. Its own sliding windows, under TornW3B's published limits, and a hard
     *      cooldown on 429 or a non-JSON (Cloudflare challenge) body.
     *
     * TornW3B's published limits (read 2026-10-10), per IP, without a key:
     *
     *   GET /marketplace/{itemId} (an item's full listing)   10 a minute, 1,000 a day
     *   every route together                                 300 a minute
     *   Cloudflare, in front of all of it                    100 a minute
     *   a 429 carries Retry-After
     *
     * So (Torn Archive 1.0.0) there are TWO windows: the one every request draws
     * on (80 a minute, as before), and a second one for the item-listing route
     * alone (9 a minute, 950 a day). The first WAITS for room, as it always has.
     * The second does not: requests go one at a time, so waiting there would hold
     * the summary and the /traders reads behind it - a listing asked for with no
     * room left is refused here, with the time there will be room (`retryAt`).
     *
     * A request refused HERE (the cooldown, the pause while Torn Bids runs, the
     * listing window or day full) throws a W3bError with `local: true`: nothing
     * was sent, so it is not an HTTP error and is never reported through onFailed
     * (onLocal hears of it instead).
     *
     * Responses are cached server-side for 60s, so asking faster is pointless.
     */



    const W3B_API_BASE = 'https://weav3r.dev/api/';
    const W3B_HOST = 'weav3r.dev';
    const W3B_TERMS_URL = 'https://weav3r.dev/terms-of-service';
    const W3B_SITE_URL = 'https://weav3r.dev';

    /** TornW3B's Cloudflare enforces 100/min per IP; leave 20 for TornTools and friends. */
    const W3B_MAX_PER_MINUTE = 80;

    /**
     * Every tab together: each client's own ceiling only limits itself, so two of
     * them made 84/min against TornW3B's 100 per IP before TornTools asked for
     * anything.
     */
    const W3B_SHARED_PER_MINUTE = 80;

    /** After a 429 with no Retry-After, or a challenge page, stop asking for this long. */
    const W3B_COOLDOWN_MS = 60000;

    /** An item's full listing (GET /marketplace/{itemId}): TornW3B allows 10 a minute and 1,000 a day; one and fifty are left spare. */
    const W3B_LISTING_PER_MINUTE = 9;
    const W3B_LISTING_PER_DAY = 950;

    /** A Retry-After is believed between these: never a wait of nothing, never one past a day. */
    const W3B_RETRY_AFTER_MIN_MS = 1000;
    const W3B_RETRY_AFTER_MAX_MS = 24 * 60 * 60 * 1000;

    const W3B_HOUR_MS = 60 * 60 * 1000;
    /* The day is counted by the hour, over the last 24 whole hours and this one: never less than TornW3B's day, whichever way it counts. */
    const W3B_DAY_HOURS = 24;

    /*
     * What may ride in a query besides `comment` (3.23.0): an option of TornW3B's
     * own API, a whole number within the range the service takes. Checked on the
     * way out (buildUrl): nothing else can be put in, whoever calls.
     *
     *   tradedWithinHours  /marketplace/{id}/traders: only buyers who traded in
     *                      the last N hours (1-168)
     *
     * `maxPrice` on /marketplace/{id} (only the listings at or under a price) was
     * tried for 3.23.0 and is NOT sent. Measured on the bench (the scene "400
     * items read in turn", with their dearer rows and without): about 12 ms of a
     * 100-140 ms redraw with the processor slowed four times, less than two runs
     * of the same thing differ by - a read "in turn" already keeps only its 10
     * cheapest rows, and the redraw's time is the page, not the rows. And an item
     * with nothing under the trader's price would lose its lowest bazaar price.
     */
    const W3B_QUERY = { tradedWithinHours: [1, 168] };

    /** A whole number within [min, max], or null. */
    function w3bWhole(value, min, max) {
        return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max ? value : null;
    }

    class W3bError extends Error {
        /**
         * @param {string} message
         * @param {object} [options]
         * @param {number|null} [options.http]   - the status TornW3B answered with
         * @param {boolean} [options.blocked]    - TornW3B is refusing us (a 429, a challenge page, or the wait after one)
         * @param {boolean} [options.local]      - refused by THIS client: nothing was sent
         * @param {string|null} [options.reason] - of a local refusal: 'cooldown' | 'paused' | 'listing-minute' | 'listing-day'
         * @param {number|null} [options.retryAt] - when asking again can work (ms), where that is known
         */
        constructor(message, { http = null, blocked = false, local = false, reason = null, retryAt = null } = {}) {
            super(message);
            this.name = 'W3bError';
            this.http = http;
            this.blocked = blocked;
            this.local = local;
            this.reason = reason;
            this.retryAt = retryAt;
            /** Refused because Torn Bids is running (the two scripts take turns). */
            this.takingTurns = reason === 'paused';
        }
    }

    function w3bSleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    /** Is this the item-listing route (marketplace/{itemId})? Not the summary (marketplace), not marketplace/{id}/traders. */
    function isW3bListingPath(path) {
        return /^marketplace\/[^/?#]+\/?$/.test(String(path).replace(/^\/+/, ''));
    }

    /**
     * How long a Retry-After asks us to wait, in ms: a number of seconds, or an
     * HTTP date. Null when there is none or it cannot be read (the caller then
     * waits W3B_COOLDOWN_MS).
     */
    function w3bRetryAfterMs(value, now = Date.now()) {
        const text = String(value ?? '').trim();
        if (!text) return null;
        let ms = null;
        if (/^\d+(\.\d+)?$/.test(text)) {
            ms = Number(text) * 1000;
        } else if (/[A-Za-z]{3}/.test(text) && /\d{4}/.test(text)) {
            // An HTTP date ("Wed, 21 Oct 2026 07:28:00 GMT"): nothing looser is taken for one.
            const at = Date.parse(text);
            if (Number.isFinite(at)) ms = at - now;
        }
        if (ms === null || !Number.isFinite(ms)) return null;
        return Math.min(W3B_RETRY_AFTER_MAX_MS, Math.max(W3B_RETRY_AFTER_MIN_MS, Math.ceil(ms)));
    }

    /** One answer header: gmFetch's `header(name)`, or a fetch Response's `headers.get(name)`. */
    function w3bHeader(response, name) {
        try {
            if (response && typeof response.header === 'function') return response.header(name);
            if (response && response.headers && typeof response.headers.get === 'function') return response.headers.get(name);
        } catch {
            // No header to read: the caller falls back.
        }
        return null;
    }

    class W3bClient {
        /**
         * @param {object} [options]
         * @param {function} [options.fetchImpl] - injectable for tests
         * @param {number} [options.maxPerMinute]
         * @param {function} [options.perMinute] - () => number: the ceiling right
         *   now, when it is lower than maxPerMinute
         * @param {function} [options.now]
         * @param {function} [options.loadShared] - () => {recent: number[], cooldownUntil}
         *   stored for every tab: one window across all of them, and a 429 seen
         *   by one tab stops them all.
         * @param {function} [options.saveShared] - (state) => void
         * @param {function} [options.addShared] - (at) => void: record one slot of
         *   THIS tab only (platform/tab-window.js), so tabs never overwrite each
         *   other's; without it the whole window is written back through saveShared
         * @param {number} [options.sharedPerMinute]
         * @param {function} [options.sleep] - (ms) => Promise; injectable for tests
         * @param {function} [options.isVisible] - () => boolean; nothing is sent
         *   from a hidden tab, even a request queued while it was visible
         * @param {function} [options.isPaused] - () => boolean; true while Torn
         *   Bids runs: nothing is sent, a queued request is not sent either
         * @param {number} [options.listingPerMinute] - the item-listing route's own window
         * @param {number} [options.listingPerDay]
         * @param {function} [options.loadListing] - () => number[]: every tab's
         *   item-listing requests of the last minute (platform/tab-window.js)
         * @param {function} [options.addListing] - (at) => void: record one of THIS tab's
         * @param {function} [options.loadListingDay] - () => {[hour]: count}, hour = floor(ms / 3,600,000)
         * @param {function} [options.saveListingDay] - (counts) => void
         *   Without these four the counts live in this tab's memory only.
         */
        constructor({
            fetchImpl = gmFetch,
            maxPerMinute = W3B_MAX_PER_MINUTE,
            now = () => Date.now(),
            loadShared = null,
            saveShared = null,
            sharedPerMinute = W3B_SHARED_PER_MINUTE,
            sleep = w3bSleep,
            isVisible = () => true,
            addShared = null,
            onSent = null,
            // ({ path, tag, how: 'ok' | '429' | 'fail' }): how a request that left was answered (the usage record).
            onAnswered = null,
            onFailed = null,
            perMinute = null,
            onOver = null,
            isPaused = () => false,
            onLocal = null,
            listingPerMinute = W3B_LISTING_PER_MINUTE,
            listingPerDay = W3B_LISTING_PER_DAY,
            loadListing = null,
            addListing = null,
            loadListingDay = null,
            saveListingDay = null,
            loadListingOther = null,
        } = {}) {
            this.perMinute = perMinute;
            /**
             * ({count, limit, own}) => void (3.23.0): the minute every tab shares was found OVER
             * sharedPerMinute - tabs learn of each other's requests late, so two can take the same
             * last slot. This tab waits, as always; the report is for the problem log.
             */
            this.onOver = onOver;
            /** ({path, tag}) => void, each request that leaves: the usage record (3.15). */
            this.onSent = onSent;
            this.onAnswered = onAnswered;
            /** ({path, tag, error}) => void, a request that failed: the problem log (3.15). Never a local refusal. */
            this.onFailed = onFailed;
            /** ({path, tag, error}) => void, a request refused here (error.local): nothing was sent. */
            this.onLocal = onLocal;
            this.isPaused = isPaused;
            this.listingPerMinute = listingPerMinute;
            this.listingPerDay = listingPerDay;
            this.loadListing = loadListing;
            this.addListing = addListing;
            this.loadListingDay = loadListingDay;
            this.saveListingDay = saveListingDay;
            /** () => {m: number[], d: {[hour]: count}} | null: the item-listing requests another app on this PC made (Torn Bids), counted with ours. */
            this.loadListingOther = loadListingOther;
            /** This tab's own item-listing requests: the last minute's times, and a count for each hour. */
            this.listingRecent = [];
            this.listingDay = {};
            this.addShared = addShared;
            this.sleep = sleep;
            this.isVisible = isVisible;
            this.fetchImpl = fetchImpl;
            this.maxPerMinute = maxPerMinute;
            this.now = now;
            this.loadShared = loadShared;
            this.saveShared = saveShared;
            this.sharedPerMinute = sharedPerMinute;
            this.recent = [];
            this.chain = Promise.resolve();
            this.cooldownUntil = 0;
        }

        /** What every tab has used, and any wait one of them was told to make. */
        readShared(t) {
            const out = { recent: [], cooldownUntil: 0 };
            if (!this.loadShared) return out;
            let s;
            try {
                s = this.loadShared();
            } catch {
                return out;
            }
            if (!s || typeof s !== 'object') return out;
            if (Array.isArray(s.recent)) out.recent = s.recent.filter((x) => Number.isFinite(x) && t - x < 60000).sort((a, b) => a - b);
            if (Number.isFinite(Number(s.cooldownUntil))) out.cooldownUntil = Number(s.cooldownUntil);
            return out;
        }

        writeShared(state) {
            if (!this.saveShared) return;
            try {
                this.saveShared(state);
            } catch {
                // Sharing is best-effort; this tab still limits itself.
            }
        }

        /** The later of this tab's wait and any other tab's. */
        blockedUntil(t = this.now()) {
            return Math.max(this.cooldownUntil, this.readShared(t).cooldownUntil);
        }

        /** This tab's ceiling now: maxPerMinute, or less while perMinute() says so. Never under 1. */
        limit() {
            if (!this.perMinute) return this.maxPerMinute;
            let n;
            try {
                n = Number(this.perMinute());
            } catch {
                return this.maxPerMinute;
            }
            return Number.isFinite(n) ? Math.max(1, Math.min(this.maxPerMinute, Math.floor(n))) : this.maxPerMinute;
        }

        /** The hour counts worth keeping (the last 24 whole hours and this one), as {[hour]: count}. */
        listingDayCounts(source, t) {
            const out = {};
            if (!source || typeof source !== 'object') return out;
            const hour = Math.floor(t / W3B_HOUR_MS);
            for (const [h, n] of Object.entries(source)) {
                const at = Number(h);
                const count = Math.floor(Number(n));
                if (Number.isInteger(at) && at <= hour && at >= hour - W3B_DAY_HOURS && count > 0) out[at] = count;
            }
            return out;
        }

        /**
         * The item-listing route's two counts (every tab's, where they are shared)
         * and when each has room again.
         * @returns {{minute: number, day: number, minuteFreeAt: number, dayFreeAt: number}} *FreeAt: 0 while there is room
         */
        listingUse(t = this.now()) {
            this.listingRecent = this.listingRecent.filter((x) => t - x < 60000);
            let recent = this.listingRecent;
            if (this.loadListing) {
                try {
                    const s = this.loadListing();
                    const all = Array.isArray(s) ? s.filter((x) => Number.isFinite(x) && t - x < 60000 && x <= t).sort((a, b) => a - b) : [];
                    if (all.length > recent.length) recent = all;
                } catch {
                    // Sharing is best-effort; this tab still counts its own.
                }
            }

            this.listingDay = this.listingDayCounts(this.listingDay, t);
            let day = this.listingDay;
            if (this.loadListingDay) {
                try {
                    const stored = this.listingDayCounts(this.loadListingDay(), t);
                    if (w3bSum(stored) > w3bSum(day)) day = stored;
                } catch {
                    // As above.
                }
            }

            // TornW3B counts by address: what another app on this PC asked is in the same minute and day.
            if (this.loadListingOther) {
                try {
                    const other = this.loadListingOther();
                    const theirs = other && Array.isArray(other.m) ? other.m.filter((x) => Number.isFinite(x) && t - x < 60000 && x <= t) : [];
                    if (theirs.length) recent = [...recent, ...theirs].sort((a, b) => a - b);
                    const theirDay = this.listingDayCounts(other ? other.d : null, t);
                    if (w3bSum(theirDay)) {
                        day = { ...day };
                        for (const [h, n] of Object.entries(theirDay)) day[h] = (day[h] || 0) + n;
                    }
                } catch {
                    // As above.
                }
            }

            const perMinute = Math.max(1, Math.floor(Number(this.listingPerMinute)) || 1);
            const perDay = Math.max(1, Math.floor(Number(this.listingPerDay)) || 1);
            const dayCount = w3bSum(day);
            const hours = Object.keys(day).map(Number).sort((a, b) => a - b);
            return {
                minute: recent.length,
                day: dayCount,
                // The slot that brings the minute back under its limit, a minute after it was taken.
                minuteFreeAt: recent.length >= perMinute ? recent[recent.length - perMinute] + 60000 : 0,
                // The oldest counted hour leaves the day when the hour after its 24 have passed begins.
                dayFreeAt: dayCount >= perDay && hours.length ? (hours[0] + W3B_DAY_HOURS + 1) * W3B_HOUR_MS : 0,
            };
        }

        /** Count one item-listing request that is about to leave. */
        noteListing(t = this.now()) {
            this.listingRecent.push(t);
            if (this.addListing) {
                try {
                    this.addListing(t);
                } catch {
                    // Best-effort; this tab still limits itself.
                }
            }

            const hour = Math.floor(t / W3B_HOUR_MS);
            this.listingDay[hour] = (this.listingDay[hour] || 0) + 1;
            if (this.saveListingDay) {
                try {
                    const stored = this.listingDayCounts(this.loadListingDay ? this.loadListingDay() : null, t);
                    stored[hour] = (stored[hour] || 0) + 1;
                    this.saveListingDay(stored);
                } catch {
                    // As above.
                }
            }
        }

        stats() {
            const t = this.now();
            const used = this.recent.filter((x) => t - x < 60000).length;
            const listing = this.listingUse(t);
            return {
                usedLastMinute: used,
                remaining: Math.max(0, this.limit() - used),
                coolingDown: t < this.blockedUntil(t),
                sharedLastMinute: this.loadShared ? this.readShared(t).recent.length : used,
                // The item-listing route (marketplace/{itemId}): its own minute and day.
                listingLastMinute: listing.minute,
                listingRemaining: Math.max(0, this.listingPerMinute - listing.minute),
                listingToday: listing.day,
                listingDayRemaining: Math.max(0, this.listingPerDay - listing.day),
                // When a listing can next be asked for: 0 = now.
                listingFreeAt: Math.max(listing.minuteFreeAt, listing.dayFreeAt),
            };
        }

        async waitForSlot() {
            for (;;) {
                // Hidden: take no slot and send nothing until the tab is back.
                if (!this.isVisible()) {
                    await this.sleep(1000);
                    continue;
                }
                const t = this.now();
                this.recent = this.recent.filter((x) => t - x < 60000);
                const shared = this.readShared(t);
                const sharedFull = this.loadShared && shared.recent.length >= this.sharedPerMinute;
                const limit = this.limit();
                if (this.onOver && this.loadShared && shared.recent.length > this.sharedPerMinute) {
                    try {
                        this.onOver({ count: shared.recent.length, limit: this.sharedPerMinute, own: this.recent.length });
                    } catch {
                        // The report is best-effort.
                    }
                }

                if (this.recent.length < limit && !sharedFull) {
                    this.recent.push(t);
                    if (this.addShared) {
                        try {
                            this.addShared(t);
                        } catch {
                            // Best-effort; this tab still limits itself.
                        }
                    } else if (this.loadShared) {
                        this.writeShared({ ...shared, recent: [...shared.recent, t] });
                    }
                    return;
                }

                // Wait until every full window has a slot again.
                const frees = [];
                if (this.recent.length >= limit) frees.push(this.recent[this.recent.length - limit]);
                if (sharedFull) frees.push(shared.recent[shared.recent.length - this.sharedPerMinute]);
                await this.sleep(Math.max(50, 60000 - (t - Math.max(...frees)) + 25));
            }
        }

        /** Stop asking - this tab and, through storage, every other. `ms`: what a Retry-After asked for; else the usual minute. */
        coolDown(ms = W3B_COOLDOWN_MS) {
            const t = this.now();
            this.cooldownUntil = t + (Number(ms) > 0 ? Number(ms) : W3B_COOLDOWN_MS);
            if (this.loadShared) this.writeShared({ ...this.readShared(t), cooldownUntil: this.cooldownUntil });
            return this.cooldownUntil;
        }

        /** Build and check a URL. Exposed for tests. `query`: W3B_QUERY's options only. */
        buildUrl(path, query = null) {
            const url = new URL(String(path).replace(/^\/+/, ''), W3B_API_BASE);

            if (url.hostname !== W3B_HOST) {
                throw new W3bError('Refusing to contact ' + url.hostname + '.');
            }

            // Nothing but an attribution comment ever goes in the query - and the whole number of W3B_QUERY.
            url.search = '';
            url.searchParams.set('comment', 'TornArchive');
            for (const [name, [min, max]] of Object.entries(W3B_QUERY)) {
                const n = query && Object.prototype.hasOwnProperty.call(query, name) ? w3bWhole(query[name], min, max) : null;
                if (n !== null) url.searchParams.set(name, String(n));
            }

            return url;
        }

        /** GET one TornW3B path. Serialised, rate-limited, never keyed. `tag`: what it is for (the usage record). */
        get(path, { tag = null, query = null } = {}) {
            const run = () => this.execute(path, tag, query).catch((error) => {
                // Refused here, nothing sent: not a failure of TornW3B's, so not the problem log's.
                const hook = error && error.local ? this.onLocal : this.onFailed;
                if (hook) {
                    try {
                        hook({ path, tag, error });
                    } catch {
                        // The log is best-effort.
                    }
                }
                throw error;
            });
            const promise = this.chain.catch(() => {}).then(run);
            this.chain = promise.catch(() => {});
            return promise;
        }

        /**
         * Why this request may not leave right now, as the error to throw; null
         * when it may. Every one of these is local: nothing was sent.
         */
        refusal(path) {
            let paused = false;
            try {
                paused = !!(this.isPaused && this.isPaused());
            } catch {
                // A hook that throws does not stop the reads.
            }
            if (paused) return new W3bError('Paused while Torn Trading runs.', { local: true, reason: 'paused' });

            const t = this.now();
            const until = this.blockedUntil(t);
            if (t < until) {
                return new W3bError('TornW3B is rate limiting us; paused briefly.', { blocked: true, local: true, reason: 'cooldown', retryAt: until });
            }

            if (isW3bListingPath(path)) {
                const use = this.listingUse(t);
                if (use.dayFreeAt) {
                    return new W3bError("TornW3B item listings: today's " + this.listingPerDay + ' are used.', { local: true, reason: 'listing-day', retryAt: use.dayFreeAt });
                }
                if (use.minuteFreeAt) {
                    return new W3bError("TornW3B item listings: this minute's " + this.listingPerMinute + ' are used.', { local: true, reason: 'listing-minute', retryAt: use.minuteFreeAt });
                }
            }
            return null;
        }

        async execute(path, tag = null, query = null) {
            let refused = this.refusal(path);
            if (refused) throw refused;

            const url = this.buildUrl(path, query);
            await this.waitForSlot();
            // Another tab may have been blocked, or Torn Bids opened, while this one waited for a slot.
            refused = this.refusal(path);
            if (refused) throw refused;
            if (isW3bListingPath(path)) this.noteListing();

            if (this.onSent) {
                try {
                    this.onSent({ path, tag });
                } catch {
                    // The usage record is best-effort.
                }
            }

            const answered = (how) => {
                if (!this.onAnswered) return;
                try { this.onAnswered({ path, tag, how }); } catch { /* the usage record is best-effort */ }
            };
            let response;
            try {
                response = await this.fetchImpl(url.toString());
            } catch (error) {
                answered('fail');
                throw new W3bError(
                    'TornW3B network error: ' + ((error && error.message) || error),
                );
            }

            if (response.status === 429) {
                // TornW3B says how long to stay away (Retry-After); without it, the usual minute.
                const until = this.coolDown(w3bRetryAfterMs(w3bHeader(response, 'retry-after'), this.now()) ?? W3B_COOLDOWN_MS);
                answered('429');
                throw new W3bError('TornW3B rate limit (429).', {
                    http: 429,
                    blocked: true,
                    retryAt: until,
                });
            }

            if (!response.ok) {
                answered('fail');
                throw new W3bError('TornW3B HTTP ' + response.status, {
                    http: response.status,
                });
            }

            try {
                const json = await response.json();
                answered('ok');
                return json;
            } catch {
                // Cloudflare answers a challenge page with HTML, not JSON.
                this.coolDown();
                answered('429');
                throw new W3bError('TornW3B returned a non-JSON page (blocked?).', {
                    blocked: true,
                });
            }
        }
    }

    function w3bSum(counts) {
        let n = 0;
        for (const v of Object.values(counts)) n += Number(v) || 0;
        return n;
    }

    /**
     * Cheapest bazaar price for every item, in one request.
     *
     * @returns {Promise<Array<{itemId: string, name: string, lowestPrice: number|null,
     *   marketPrice: number|null, bazaarAverage: number|null, totalBazaars: number}>>}
     */
    async function fetchW3bSummary(client, { tag = 'w.summary' } = {}) {
        const data = await client.get('marketplace', { tag });
        const items = data && Array.isArray(data.items) ? data.items : null;

        if (!items) throw new W3bError('TornW3B returned no item summary.');

        return items
            .filter((i) => i && Number.isFinite(Number(i.item_id)))
            .map((i) => ({
                itemId: String(i.item_id),
                name: i.item_name || '',
                lowestPrice: positiveOrNull(i.lowest_price),
                marketPrice: positiveOrNull(i.market_price),
                bazaarAverage: positiveOrNull(i.bazaar_average),
                totalBazaars: Number(i.total_bazaars) || 0,
            }));
    }

    /**
     * Every bazaar listing TornW3B knows for one item.
     *
     * Retries once when the payload says there are listings but sends none - a
     * known mid-scan glitch. `maxPrice` is deliberately NOT sent (see W3B_QUERY:
     * measured for 3.23.0, it did not help) - every listing is asked for.
     *
     * @returns {Promise<{listings: Array, total: number}>} raw listing objects
     */
    async function fetchW3bListings(client, itemId, { tag = null } = {}) {
        const path = 'marketplace/' + encodeURIComponent(String(itemId));

        let data = await client.get(path, { tag });

        const empty = (d) =>
            d &&
            Number(d.total_listings) > 0 &&
            Array.isArray(d.listings) &&
            d.listings.length === 0;

        if (empty(data)) data = await client.get(path, { tag });

        return {
            listings: data && Array.isArray(data.listings) ? data.listings : [],
            total: Number(data && data.total_listings) || 0,
        };
    }

    /**
     * Every TornW3B buyer of one item (3.15): GET /api/marketplace/{id}/traders,
     * highest price first, at most 100 (`total_count` says how many there are:
     * 412 for Xanax on 2026-09-29, against ~290 lists we had read). Each comes
     * with their rating and when they were last active - free, where a Torn
     * profile call per trader cost the shared 70/min.
     *
     * `withinHours` (3.23.0): only those who traded in the last N hours are
     * asked for (`tradedWithinHours`) - the 100 of the answer are then not spent
     * on lists nobody trades on. `withinHours` in the answer says what was asked.
     *
     * @returns {Promise<{total: number, withinHours: number|null, traders: Array<{id, name, price, up, down, lastAction, lastTrade, listAt}>}>}
     */
    async function fetchW3bItemTraders(client, itemId, { tag = 'w.buyers', withinHours = null } = {}) {
        const hours = w3bWhole(withinHours, ...W3B_QUERY.tradedWithinHours);
        const data = await client.get('marketplace/' + encodeURIComponent(String(itemId)) + '/traders', { tag, query: hours ? { tradedWithinHours: hours } : null });
        const rows = data && Array.isArray(data.traders) ? data.traders : [];
        const sec = (x) => (Number(x) > 0 ? Number(x) * 1000 : null);
        return {
            total: Number(data && data.total_count) || rows.length,
            withinHours: hours,
            traders: rows
                .filter((t) => t && Number(t.player_id) > 0 && Number(t.price) > 0)
                .map((t) => ({
                    id: String(t.player_id),
                    name: t.player_name ? String(t.player_name) : null,
                    price: Number(t.price),
                    up: t.rating && Number.isFinite(Number(t.rating.upvotes)) ? Number(t.rating.upvotes) : null,
                    down: t.rating && Number.isFinite(Number(t.rating.downvotes)) ? Number(t.rating.downvotes) : null,
                    lastAction: sec(t.last_action),
                    lastTrade: sec(t.last_trade),
                    listAt: sec(t.pricelist_updated),
                })),
        };
    }

    /** A trader's price list, as a person sees it on TornW3B. */
    function w3bPriceListUrl(traderId) {
        return W3B_SITE_URL + '/pricelist/' + encodeURIComponent(String(traderId));
    }

    /**
     * One trader's TornW3B price list: GET /api/pricelist/{tornId}, which returns
     * [{itemId, name, buyPrice, ...}] (buyPrice 0 = not buying). A player with no
     * list gets [] or a 404; both come back as an empty body, not an error.
     *
     * @returns {Promise<Array>} the raw rows (see parseW3bPriceList)
     */
    async function fetchW3bPriceList(client, traderId) {
        const id = String(traderId).replace(/\D/g, '');
        if (!id) throw new W3bError('No trader id.');
        try {
            const body = await client.get('pricelist/' + id);
            return Array.isArray(body) ? body : [];
        } catch (error) {
            if (error && error.http === 404) return [];
            throw error;
        }
    }

    function positiveOrNull(value) {
        const n = Number(value);
        return Number.isFinite(n) && n > 0 ? n : null;
    }

    /* ===== src/api/tw3b-own.js ===== */
    // Your own price list on TornW3B, and its receipts: the only calls that carry the key you registered there.
    // The key rides in the `X-API-Key` header, never in an address. Nothing here is ever asked of Torn, and nothing
    // here runs on a server: TornW3B is asked from your own browser only. What to send and what came back is worked
    // out in core/tw3b-list.js; this file only sends.




    /** Writes are few and yours alone: never more than this many a minute, whatever asks. */
    const TW3B_OWN_PER_MINUTE = 6;

    class Tw3bOwnError extends Error {
        constructor(message, { http = null, local = false } = {}) {
            super(message);
            this.name = 'Tw3bOwnError';
            this.http = http;
            this.local = local;
        }
    }

    const ownId = (v) => String(v == null ? '' : v).replace(/\D/g, '');

    /**
     * @param getKey   () => the key registered on TornW3B, or ''
     * @param getUser  () => your Torn id
     * @param send     gmSend, or a stand-in for tests
     * @param isPaused () => true while Torn Trading runs: nothing is sent
     */
    class Tw3bOwnClient {
        constructor({ getKey, getUser, send = gmSend, now = () => Date.now(), isPaused = () => false, onSent = null, onFailed = null, perMinute = TW3B_OWN_PER_MINUTE } = {}) {
            this.getKey = getKey;
            this.getUser = getUser;
            this.send = send;
            this.now = now;
            this.isPaused = isPaused;
            this.onSent = onSent;
            this.onFailed = onFailed;
            this.perMinute = perMinute;
            this.recent = [];
        }

        url(path) {
            const user = ownId(this.getUser && this.getUser());
            if (!user) throw new Tw3bOwnError('Your Torn id is not known yet.', { local: true });
            return W3B_API_BASE + path.replace('{user}', user);
        }

        async ask(method, path, { body = null, key = true, tag = 'w.own' } = {}) {
            let paused = false;
            try { paused = !!this.isPaused(); } catch { paused = false; }
            if (paused) throw new Tw3bOwnError('Paused while Torn Trading runs.', { local: true });
            const k = key ? String((this.getKey && this.getKey()) || '').trim() : '';
            if (key && !k) throw new Tw3bOwnError('The key you registered on TornW3B is not set.', { local: true });
            const t = this.now();
            this.recent = this.recent.filter((x) => t - x < 60000);
            if (this.recent.length >= this.perMinute) throw new Tw3bOwnError('Too many requests to TornW3B in a minute: waited.', { local: true });
            const url = this.url(path);
            this.recent.push(t);
            let res;
            try {
                res = await this.send(url, { method, headers: k ? { 'X-API-Key': k } : {}, body });
            } catch (error) {
                const e = new Tw3bOwnError(String((error && error.message) || error));
                if (this.onFailed) this.onFailed({ path, tag, error: e });
                throw e;
            }
            if (this.onSent) this.onSent({ path, tag });
            if (!res.ok) {
                const words = res.status === 401 ? 'TornW3B does not know this key (401).' : res.status === 429 ? 'TornW3B asked to wait (429).' : 'TornW3B answered ' + res.status + '.';
                const e = new Tw3bOwnError(words, { http: res.status });
                // What TornW3B said with it, for the problem log: a refusal with no reason cannot be told from a blocked page.
                try { e.said = res.text ? String(await res.text()).replace(/\s+/g, ' ').replace(/[A-Za-z0-9]{16,}/g, '[…]').trim().slice(0, 140) : ''; } catch { e.said = ''; }
                if (this.onFailed) this.onFailed({ path, tag, error: e });
                throw e;
            }
            try { return await res.json(); } catch { return null; }
        }

        /** Your list as TornW3B has it. */
        readList() { return this.ask('GET', 'pricelist/{user}', { key: false, tag: 'w.own' }); }

        /** Set and remove prices (core/tw3b-list.js putBody). */
        putList(body) { return this.ask('PUT', 'pricelist/{user}', { body, tag: 'w.own' }); }

        /** A receipt for one trade, made from your list (core/tw3b-list.js receiptBody). */
        makeReceipt(body) { return this.ask('POST', 'pricelist/{user}', { body, key: false, tag: 'w.own' }); }

        /** Your newest receipts: [{ id, name, value }]. */
        async receipts() {
            const json = await this.ask('GET', 'trades/{user}', { tag: 'w.own' });
            const rows = (json && (json.trades || json.receipts || json.data)) || json;
            return Array.isArray(rows) ? rows : [];
        }

        /** One receipt in full: { id, trade_id, total_value, created_at, ... }. */
        receipt(id) { return this.ask('GET', 'trades/{user}/' + encodeURIComponent(String(id)), { tag: 'w.own' }); }
    }

    /* ===== src/core/usage.js ===== */
    /*
     * API use (3.15, the owner: "I need to see the usage with a graph, so we're
     * able to analyse what needs more priority and what needs less").
     *
     * Every request that leaves - Torn, TornW3B, any tab - is
     * counted under what it was for (its tag), per minute. Each tab keeps its
     * counts in memory and adds them to the stored record every few seconds; a
     * day of minutes is kept, then folded into hours, kept a week. Two tabs
     * writing in the same instant can lose a few counts: this is a record to
     * read trends from, not the limiter (the limiters count exactly).
     */

    /* Minutes kept one by one; older ones are folded into their hour. */
    const USAGE_MINUTES_KEPT = 24 * 60;
    /* Hours kept. */
    const USAGE_HOURS_KEPT = 7 * 24;

    /** Each service: its name and how many a minute we allow ourselves (the meter's 100%). */
    const USAGE_SERVICES = {
        t: { name: 'Torn API', perMin: 85, note: 'every tab together; Torn allows 100' },
        w: { name: 'TornW3B', perMin: 80, note: 'every tab together; TornW3B allows about 100' },
    };

    /** What each tag means, and its lane (Torn only: high goes first, low waits for room). */
    const USAGE_LABELS = {
        't.setup': { name: 'Items list, key, you', lane: 'high' },
        't.inventory': { name: 'Your inventory', lane: 'normal' },
        't.sets': { name: 'Points market, your money, sellers\' bazaars, the Item Market, your threads', lane: 'low' },
        't.setslog': { name: 'Your log and your trades', lane: 'low' },
        't.ledger': { name: 'Your log (Full key)', lane: 'low' },
        't.other': { name: 'Other', lane: 'high' },
        'w.summary': { name: 'Bazaar summary' },
        'w.sets': { name: 'A set piece: its full listing' },
        'w.buyers': { name: 'Buyers per item' },
        'w.own': { name: 'Your price list and receipts' },
        'w.other': { name: 'Other' },
        // Not requests: how TornW3B answered them (1.2.0, as Torn Trading counts them). In the export and in what the
        // shared server is told - their letter is no service's, so no chart, total or limit counts them.
        'r.w.ok': { name: 'Answered', service: 'w' },
        'r.w.429': { name: 'Refused (429 or a blocked page)', service: 'w' },
        'r.w.fail': { name: 'Failed', service: 'w' },
    };

    /** A tag that is not in the list is counted as its service's Other. */
    function usageLabel(tag) {
        const t = String(tag || '');
        if (USAGE_LABELS[t]) return t;
        const svc = t.charAt(0);
        return USAGE_SERVICES[svc] ? svc + '.other' : 't.other';
    }

    /** One request, counted in this tab's pending counts. */
    function usageAdd(pending, tag, at = Date.now()) {
        const m = Math.floor(at / 60000);
        const label = usageLabel(tag);
        const row = pending[m] || (pending[m] = {});
        row[label] = (row[label] || 0) + 1;
        return pending;
    }

    function cleanStore(stored) {
        const s = stored && typeof stored === 'object' ? stored : {};
        return {
            m: s.m && typeof s.m === 'object' ? { ...s.m } : {},
            h: s.h && typeof s.h === 'object' ? { ...s.h } : {},
        };
    }

    function addInto(target, key, counts) {
        const row = { ...(target[key] || {}) };
        for (const [label, n] of Object.entries(counts || {})) {
            if (Number(n) > 0) row[label] = (row[label] || 0) + Number(n);
        }
        target[key] = row;
    }

    /**
     * The stored record with this tab's pending counts added: minutes over a day
     * old folded into their hour, hours over a week dropped.
     */
    function usageMerge(stored, pending, now = Date.now()) {
        const out = cleanStore(stored);
        for (const [minute, counts] of Object.entries(pending || {})) addInto(out.m, minute, counts);
        const nowMin = Math.floor(now / 60000);
        for (const minute of Object.keys(out.m)) {
            if (nowMin - Number(minute) >= USAGE_MINUTES_KEPT) {
                addInto(out.h, String(Math.floor(Number(minute) / 60)), out.m[minute]);
                delete out.m[minute];
            }
        }
        const nowHour = Math.floor(now / 3600000);
        for (const hour of Object.keys(out.h)) if (nowHour - Number(hour) >= USAGE_HOURS_KEPT) delete out.h[hour];
        return out;
    }

    /*
     * This PC's counts for the shared server (1.2.0; the owner, 2026-10-11: "track in the server all tornw3b
     * and torn exchange calls in every laptop so we can optimise it that way" - and Torn Archive told it none).
     * With each exchange the PC says how many requests it made of TornW3B and Torn since the last one the server
     * answered, by what for - the tags above, and how TornW3B answered. Counts only: no item, no player, no
     * price, no key. The counts wait in one stored sum; the tab that talks to the server sends it, and takes off
     * what was sent once the server has answered. What could not be sent for an hour is let go, so an old sum
     * never lands on the wrong hour of the server's record. The same as Torn Trading's (its core/usage.js): the
     * server adds both apps' counts of one person under the same tags.
     */
    const USAGE_CALLS_TAGS_MAX = 60;
    const USAGE_CALLS_COUNT_MAX = 5000;
    const USAGE_CALLS_KEEP_MS = 60 * 60000;
    /** A service's own tag (w, e, t) or how one answered (r.w.429): the only names the server takes. */
    const USAGE_CALLS_TAG = /^(?:[wet]\.[a-z0-9]{1,12}|r\.[wet]\.[a-z0-9]{1,12})$/;

    function usageCallsKept(stored, now) {
        const s = stored && typeof stored === 'object' && !Array.isArray(stored) ? stored : {};
        const since = Number.isFinite(s.since) && s.since > 0 && s.since <= now ? s.since : null;
        const n = {};
        if (since !== null && now - since <= USAGE_CALLS_KEEP_MS && s.n && typeof s.n === 'object') {
            for (const [tag, count] of Object.entries(s.n)) {
                if (USAGE_CALLS_TAG.test(tag) && Number.isFinite(count) && count >= 1) n[tag] = Math.floor(count);
            }
        }
        return { since: Object.keys(n).length ? since : null, n };
    }

    /** The sum waiting to be sent, with a tab's pending counts (usageAdd's, by minute) added: {since, n: {tag: count}}. */
    function usageCallsAdd(stored, pending, now = Date.now()) {
        const kept = usageCallsKept(stored, now);
        for (const counts of Object.values(pending || {})) {
            for (const [tag, count] of Object.entries(counts || {})) {
                if (!USAGE_CALLS_TAG.test(tag) || !(Number(count) >= 1)) continue;
                kept.n[tag] = (kept.n[tag] || 0) + Math.floor(Number(count));
            }
        }
        if (kept.since === null && Object.keys(kept.n).length) kept.since = now;
        return kept;
    }

    /** What goes with this exchange: {tag: count}, 60 tags at most (the biggest first), none over 5,000. {} = nothing was asked. */
    function usageCallsOut(stored, now = Date.now()) {
        const out = {};
        const all = Object.entries(usageCallsKept(stored, now).n).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
        for (const [tag, count] of all.slice(0, USAGE_CALLS_TAGS_MAX)) out[tag] = Math.min(USAGE_CALLS_COUNT_MAX, count);
        return out;
    }

    /** The server answered: what was sent comes off the sum; what was added meanwhile, and what did not fit, stays. */
    function usageCallsSent(stored, sent, now = Date.now()) {
        const kept = usageCallsKept(stored, now);
        for (const [tag, count] of Object.entries(sent || {})) {
            if (!(tag in kept.n)) continue;
            const left = kept.n[tag] - (Number(count) > 0 ? Math.floor(Number(count)) : 0);
            if (left >= 1) kept.n[tag] = left;
            else delete kept.n[tag];
        }
        // What is left was counted while the answer was awaited, or did not fit: it is young again.
        return { since: Object.keys(kept.n).length ? now : null, n: kept.n };
    }

    /** The ranges the chart offers: how far back, and how wide each bar is. */
    const USAGE_RANGES = {
        '1h': { name: 'Last hour', bars: 60, barMs: 60000, barName: 'minute' },
        '24h': { name: 'Last 24 hours', bars: 24, barMs: 3600000, barName: 'hour' },
        '7d': { name: 'Last 7 days', bars: 7, barMs: 86400000, barName: 'day' },
    };

    /**
     * One service's use over a range: a bar each minute / hour / day, split by
     * tag, and each tag's total (biggest first).
     *
     * @param {object} stored - usageMerge output (already holding pending counts)
     * @param {{service: 't'|'w', range: '1h'|'24h'|'7d', now?: number}} opts
     * @returns {{bars: Array<{start: number, counts: object, total: number}>, labels: Array<{id, name, total, share}>, total: number, peak: number, perMinute: number}}
     */
    function usageSeries(stored, { service = 't', range = '1h', now = Date.now() } = {}) {
        const r = USAGE_RANGES[range] || USAGE_RANGES['1h'];
        const s = cleanStore(stored);
        // The day bars start at local midnight, the others on the minute / hour.
        const end = range === '7d'
            ? (() => { const d = new Date(now); d.setHours(24, 0, 0, 0); return d.getTime(); })()
            : (Math.floor(now / r.barMs) + 1) * r.barMs;
        const start = end - r.bars * r.barMs;
        const bars = Array.from({ length: r.bars }, (_, i) => ({ start: start + i * r.barMs, counts: {}, total: 0 }));
        const put = (at, counts) => {
            if (at < start || at >= end) return;
            const bar = bars[Math.floor((at - start) / r.barMs)];
            for (const [label, n] of Object.entries(counts)) {
                if (label.charAt(0) !== service || !(Number(n) > 0)) continue;
                bar.counts[label] = (bar.counts[label] || 0) + Number(n);
                bar.total += Number(n);
            }
        };
        for (const [minute, counts] of Object.entries(s.m)) put(Number(minute) * 60000, counts);
        // Hours only where minutes are gone (older than a day): never both.
        if (r.barMs >= 3600000) for (const [hour, counts] of Object.entries(s.h)) put(Number(hour) * 3600000, counts);
        const totals = {};
        for (const b of bars) for (const [label, n] of Object.entries(b.counts)) totals[label] = (totals[label] || 0) + n;
        const total = Object.values(totals).reduce((a, n) => a + n, 0);
        const labels = Object.entries(totals)
            .map(([id, n]) => ({ id, name: (USAGE_LABELS[id] || { name: id }).name, lane: (USAGE_LABELS[id] || {}).lane || null, total: n, share: total ? n / total : 0 }))
            .sort((a, b) => b.total - a.total);
        // Per minute over the time the range has really covered (up to now, not the empty end of the last bar).
        const covered = Math.max(60000, Math.min(now, end) - start);
        return { bars, labels, total, peak: Math.max(0, ...bars.map((b) => b.total)), perMinute: total / (covered / 60000) };
    }

    /**
     * The record as CSV rows, one per minute (or hour) per use - for a
     * spreadsheet (3.15, the export's by-minute.csv / by-hour.csv). Local time.
     */
    function usageCsv(stored, { by = 'minute' } = {}) {
        const s = cleanStore(stored);
        const rows = [['time', 'service', 'what for', 'tag', 'requests']];
        const pad = (n) => String(n).padStart(2, '0');
        const local = (ms) => {
            const d = new Date(ms);
            return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
        };
        const bucket = new Map();
        const put = (at, counts) => {
            const key = by === 'hour' ? Math.floor(at / 3600000) * 3600000 : at;
            const row = bucket.get(key) || {};
            for (const [label, n] of Object.entries(counts || {})) row[label] = (row[label] || 0) + Number(n || 0);
            bucket.set(key, row);
        };
        for (const [minute, counts] of Object.entries(s.m)) put(Number(minute) * 60000, counts);
        if (by === 'hour') for (const [hour, counts] of Object.entries(s.h)) put(Number(hour) * 3600000, counts);
        for (const at of [...bucket.keys()].sort((a, b) => a - b)) {
            for (const [label, n] of Object.entries(bucket.get(at)).sort()) {
                if (!(n > 0)) continue;
                const svc = USAGE_SERVICES[(USAGE_LABELS[label] || {}).service || label.charAt(0)];
                rows.push([local(at), svc ? svc.name : '?', (USAGE_LABELS[label] || { name: label }).name, label, n]);
            }
        }
        return rows.map((r) => r.map((c) => (/[",\n]/.test(String(c)) ? '"' + String(c).replace(/"/g, '""') + '"' : String(c))).join(',')).join('\n') + '\n';
    }

    /* ===== src/core/server.js ===== */
    /*
     * The shared server, Torn Archive's side. Pure: no clock, no storage, no network.
     *
     * The server (a folder of the owner's, deployed by him; Torn Trading talks to the same one) reads other players'
     * bazaars from Torn with a key of each of us and hands every PC what changed. Every 30 s Torn Archive tells it
     * how much of your Torn limit it is using and which bazaars and pieces matter to it; it answers with its part of
     * the limit and with every bazaar that changed. The server keeps what each app says apart, so Torn Archive and
     * Torn Trading never overwrite each other there - which is why an older server, that keeps one list a person,
     * is never synced with (serverKnowsApps).
     *
     * What may be sent is made here and checked here on the way out: player ids, item ids, prices, counts and ages.
     * No name, no key, nothing about your inventory, your money or your books. And, since 1.2.0, how many requests this
     * PC made of TornW3B and Torn since the last exchange, by what for (`calls`: counts only - core/usage.js).
     *
     * With no address and password saved none of this runs. With the server silent, what it said ages out and
     * Torn Archive works alone, as before.
     */



    /** The name Torn Archive gives itself: the server keeps each app's lists under it. */
    const SERVER_APP = 'torn-archive';
    const SERVER_SYNC_MS = 30000;
    /** Of Torn's 100 calls a minute per person, 20 are never used by the server or a PC (the server's budget.js). */
    const SV_USABLE = 80;
    /** No answer for this long: Torn Archive is on its own again. */
    const SERVER_GRANT_STALE_MS = 5 * 60000;
    /** A bazaar the server has not confirmed for this long is forgotten here. */
    const SERVER_KEEP_MS = 3 * 60 * 60000;
    /** Another PC's read of a TornW3B list counts for this long, and a buy is passed on this long. */
    const SERVER_DIR_KEEP_MS = 30 * 60000;
    const SERVER_BOUGHT_MS = 30 * 60000;
    /** A list that is another PC's to read first: waited for this long past due, then read here. */
    const SERVER_TURN_WAIT_MS = 45000;
    /** The server sends at most this many bazaars in one answer; a full answer means there are more. */
    const SERVER_PAGE = 400;
    /** The server silent this long: said as "no answer". */
    const SERVER_QUIET_MS = 2 * 60000;
    const SV_MAX_SELLERS = 3000;
    const SV_MAX_NEAR = 200;
    const SV_MAX_BOUGHT = 200;
    const SV_MAX_DIR = 300;
    const SV_BODY_KEYS = ['app', 'ver', 'used', 'waiting', 'sellers', 'trades', 'looking', 'worth', 'since', 'seen', 'going', 'bought', 'dir', 'need', 'calls'];
    /** The server's read of the points market or of a piece's Item Market is used while it is no older than this. */
    const SERVER_MARKET_FRESH_MS = 3 * 60000;
    const SV_MAX_ROWS = 20;
    const SV_MAX_POINT_ROWS = 150;

    /** The server's address as typed, or null: https and a workers.dev name only (the one host the script may reach). */
    function serverAddress(typed) {
        const text = String(typed ?? '').trim();
        if (!text) return null;
        let url;
        try { url = new URL(/^https?:\/\//i.test(text) ? text : `https://${text}`); } catch { return null; }
        if (url.protocol !== 'https:' || !/^[a-z0-9-]+(\.[a-z0-9-]+)*\.workers\.dev$/.test(url.hostname)) return null;
        return url.origin;
    }

    /** A password as the server's set-up makes them: letters and digits, 24 or more. */
    const serverPassOk = (pass) => typeof pass === 'string' && /^[A-Za-z0-9]{24,200}$/.test(pass);

    /** A word this copy made for itself, once (48 hex): what the server knows the copy by after it was let in. */
    const serverDeviceOk = (device) => typeof device === 'string' && /^[0-9a-f]{48}$/.test(device);

    /**
     * What Torn Archive says to the server built into it when nothing was typed: whose copy this is. Torn Archive
     * holds no Public key, so it cannot say a key's word as Torn Trading does. This is no secret: the server lets it
     * in only from an address it has seen that person at, and only for Torn Archive's own exchange (the server's
     * ARCHIVE_CLAIM). With `device`, the copy's own word goes after the id: a copy the server let in once is known
     * by it afterwards wherever it asks from - an address changes, the copy is the same.
     */
    function serverClaim(id, device = '') {
        const n = /^\d{1,10}$/.test(String(id ?? '')) ? Number(id) : 0;
        return n > 0 ? 'TornArchiveSameAddress' + String(n).padStart(10, '0') + (serverDeviceOk(device) ? 'x' + device : '') : null;
    }

    /**
     * Turned away by the server, and Torn has said "too many": the most Torn Archive lets itself make a minute, so
     * that it and the server's careful part of the same key fit in Torn's limit. It says what it uses meanwhile, this
     * often, and the server takes that much less (the server's HINT_MOST is this number: budget.js).
     */
    const SERVER_CAREFUL_MOST = 40;
    const SERVER_HINT_MS = 60000;

    /** What a turned-away copy says: how much of your Torn limit it uses. Nothing else. */
    function serverHint({ ver = '', used = 0, waiting = 0 } = {}) {
        const count = (n) => (Number.isFinite(n) && n > 0 ? Math.min(1000, Math.floor(n)) : 0);
        const body = { app: SERVER_APP, used: count(used), waiting: count(waiting) };
        if (serverVersion(ver)) body.ver = serverVersion(ver);
        return body;
    }

    /** A version as the server takes it. */
    const serverVersion = (v) => (typeof v === 'string' && /^[0-9A-Za-z.+-]{1,40}$/.test(v) ? v : '');

    const svId = (value) => {
        const n = typeof value === 'string' && /^\d{1,10}$/.test(value) ? Number(value) : value;
        return Number.isInteger(n) && n > 0 && n < 1e10 ? n : null;
    };
    const svWhole = (n, max) => (Number.isInteger(n) && n >= 0 && n <= max ? n : null);

    function svIds(lists, max) {
        const out = new Set();
        for (const list of lists) {
            for (const value of Array.isArray(list) ? list : []) {
                const id = svId(value);
                if (id !== null) out.add(id);
                if (out.size >= max) return [...out];
            }
        }
        return [...out];
    }

    /**
     * May Torn Archive make one Torn call now? Its own calls of the last minute, one more, and the server's part
     * must fit in what is usable. No grant, or one too old to trust: it is on its own.
     * @param grant {at, need, serverShare, serverTimes} in this PC's time (serverGrantIn)
     */
    function serverMayCall(grant, pcTimes, now) {
        if (!grant || !Number.isFinite(grant.at) || now - grant.at > SERVER_GRANT_STALE_MS) return true;
        let mine = 0;
        for (const t of pcTimes || []) if (now - t < 60000) mine += 1;
        let lingering = 0;
        for (const t of Array.isArray(grant.serverTimes) ? grant.serverTimes : []) if (now - t < 60000) lingering += 1;
        const share = Number.isFinite(grant.serverShare) ? Math.max(0, grant.serverShare) : 0;
        return mine + 1 + Math.max(lingering, share) <= SV_USABLE;
    }

    /** Torn Trading's name on the server, and how long "it reports there too" is believed after an answer said so. */
    const SERVER_TRADING_APP = 'torn-bids';
    const SERVER_BESIDE_FRESH_MS = 2 * 60000;
    /** Everything the server may split of one person's limit (its budget.js: 100 less the 20 nobody uses). */
    const SERVER_WHOLE = 80;

    /**
     * What this PC uses of your Torn limit, as the server is told. Torn Archive counts only its own calls. A Torn
     * Trading running on this PC that does not report to the server itself (every release from before it learned to)
     * keeps its whole limit and makes room for nobody - so the whole limit is reported for it, and the server leaves
     * your key alone for as long as it runs. One that reports is counted by the server from its own words.
     * @param own { used, waiting } - Torn Archive's own
     * @param o { tradingOn, beside: [app names the server last said report from this PC], besideAt, now }
     * @returns { used, waiting, whole } - whole: the limit was reported for Torn Trading
     */
    function serverUse(own, { tradingOn = false, beside = [], besideAt = 0, now = 0 } = {}) {
        const used = Number.isFinite(own && own.used) && own.used > 0 ? own.used : 0;
        const waiting = Number.isFinite(own && own.waiting) && own.waiting > 0 ? own.waiting : 0;
        const reports = Array.isArray(beside) && beside.includes(SERVER_TRADING_APP) && besideAt > 0 && now - besideAt < SERVER_BESIDE_FRESH_MS;
        if (!tradingOn || reports) return { used, waiting, whole: false };
        return { used: Math.max(used, SERVER_WHOLE), waiting, whole: true };
    }

    /**
     * What Torn Archive sends.
     * @param o.want  { sellers: [bazaar], looking: [bazaar], worth: { piece: dollars }, bought: [{ whoId, id, qty, price, t }], dir: [[piece, read at]] }
     * @param o.pieces  the piece ids (strings): nothing else is ever named in `worth`, `bought` or `dir`
     * `worth` is left out unless sendWorth: the server keeps the last one said.
     * @param o.calls  { tag: n } - this PC's requests since the last answered exchange (usageCallsOut); {} = on and
     *   nothing asked; null = not said with this message
     */
    function serverBody({ ver = '', used = 0, waiting = 0, want = {}, pieces = [], since = 0, seen = 0, sendWorth = true, now = 0, calls = null } = {}) {
        const count = (n) => (Number.isFinite(n) && n > 0 ? Math.min(1000, Math.floor(n)) : 0);
        const mine = new Set((pieces || []).map(String));
        const w = want && typeof want === 'object' ? want : {};
        const looking = svIds([w.looking], SV_MAX_NEAR);
        // The near ones first, so a full list never pushes them out.
        const sellers = svIds([looking, w.sellers], SV_MAX_SELLERS);
        const age = (at) => Math.max(0, Math.floor(now - at));
        const body = {
            app: SERVER_APP, used: count(used), waiting: count(waiting), sellers, trades: [], looking,
            since: Number.isInteger(since) && since > 0 ? since : 0,
            seen: Number.isFinite(seen) && seen > 0 ? Math.floor(seen) : 0,
            going: [], bought: [],
        };
        if (serverVersion(ver)) body.ver = ver;
        const bought = new Map();
        for (const b of Array.isArray(w.bought) ? w.bought : []) {
            const seller = svId(b && b.whoId);
            const item = svId(b && b.id);
            const qty = svWhole(b && b.qty, 1e9);
            const price = svWhole(Math.round(Number(b && b.price) || 0), 1e13);
            const at = b && b.t;
            if (seller === null || item === null || !mine.has(String(item)) || !qty || price === null) continue;
            if (!Number.isFinite(at) || at > now + 5000 || now - at >= SERVER_BOUGHT_MS) continue;
            if (bought.size >= SV_MAX_BOUGHT) break;
            bought.set([seller, item, qty, price, Math.floor(at)].join('|'), [seller, item, qty, price, age(at)]);
        }
        body.bought = [...bought.values()];
        const dir = new Map();
        for (const entry of Array.isArray(w.dir) ? w.dir : []) {
            const item = svId(Array.isArray(entry) ? entry[0] : null);
            const at = Array.isArray(entry) ? entry[1] : null;
            if (item === null || !mine.has(String(item)) || !Number.isFinite(at) || at <= 0 || at > now + 5000 || now - at >= SERVER_DIR_KEEP_MS) continue;
            if (!(dir.get(item) >= at)) dir.set(item, at);
        }
        if (dir.size) body.dir = [...dir].sort((a, b) => b[1] - a[1]).slice(0, SV_MAX_DIR).map(([item, at]) => [item, age(at)]);
        // The pieces still to buy: the server reads their Item Market every minute, the others every ten.
        const need = svIds([w.need], mine.size).filter((id) => mine.has(String(id)));
        if (need.length) body.need = need;
        if (sendWorth) {
            const worth = {};
            for (const [key, value] of Object.entries(w.worth && typeof w.worth === 'object' ? w.worth : {})) {
                const item = svId(key);
                if (item === null || !mine.has(String(item)) || !Number.isFinite(value) || !(value > 0)) continue;
                worth[item] = Math.max(1, Math.round(value));
            }
            body.worth = worth;
        }
        if (calls && typeof calls === 'object' && !Array.isArray(calls)) {
            body.calls = {};
            for (const [tag, n] of Object.entries(calls).slice(0, USAGE_CALLS_TAGS_MAX)) {
                if (USAGE_CALLS_TAG.test(tag) && Number.isFinite(n) && n >= 1) body.calls[tag] = Math.min(USAGE_CALLS_COUNT_MAX, Math.floor(n));
            }
        }
        return body;
    }

    /**
     * The check on the way out: is this exactly a body serverBody() makes? The app's name, a version, and numbers
     * and lists of numbers - no other text, no key, nothing about an inventory. `worth` may name the pieces only.
     */
    function serverOutgoingOk(body, pieces = []) {
        if (!body || typeof body !== 'object' || Array.isArray(body)) return false;
        const mine = new Set((pieces || []).map(String));
        const whole = (n) => Number.isInteger(n) && n >= 0 && n < 1e13;
        if (body.app !== SERVER_APP) return false;
        for (const [key, value] of Object.entries(body)) {
            if (!SV_BODY_KEYS.includes(key)) return false;
            if (key === 'app') continue;
            if (key === 'ver') {
                if (!serverVersion(value)) return false;
            } else if (key === 'sellers' || key === 'trades' || key === 'looking') {
                if (!Array.isArray(value) || !value.every((id) => Number.isInteger(id) && id > 0 && id < 1e10)) return false;
            } else if (key === 'going') {
                if (!Array.isArray(value) || value.length) return false;
            } else if (key === 'need') {
                if (!Array.isArray(value) || !value.every((id) => Number.isInteger(id) && mine.has(String(id)))) return false;
            } else if (key === 'dir') {
                if (!Array.isArray(value) || !value.every((m) => Array.isArray(m) && m.length === 2 && m.every(whole) && mine.has(String(m[0])))) return false;
            } else if (key === 'bought') {
                if (!Array.isArray(value) || !value.every((m) => Array.isArray(m) && m.length === 5 && m.every(whole) && m[0] > 0 && mine.has(String(m[1])) && m[2] > 0)) return false;
            } else if (key === 'calls') {
                if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).length > USAGE_CALLS_TAGS_MAX) return false;
                for (const [tag, n] of Object.entries(value)) if (!USAGE_CALLS_TAG.test(tag) || !Number.isInteger(n) || n < 1 || n > USAGE_CALLS_COUNT_MAX) return false;
            } else if (key === 'worth') {
                if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
                for (const [item, price] of Object.entries(value)) if (!mine.has(item) || !Number.isInteger(price) || price <= 0) return false;
            } else if (!whole(value)) {
                return false;
            }
        }
        return true;
    }

    /** Does GET /state say this server keeps each app's lists apart? An older one does not, and is never synced with. */
    const serverKnowsApps = (state) => !!state && typeof state === 'object' && state.apps === true;
    /** Does this server know a copy by its own word (serverClaim's `device`)? One that does not would turn the longer claim away. */
    const serverKnowsCopies = (state) => !!state && typeof state === 'object' && state.copies === true;

    /**
     * The server's part of your limit from its answer, with its clock turned into this PC's.
     * @param got when the answer arrived, by this PC's clock
     */
    function serverGrantIn(answer, got) {
        const g = answer && answer.grant;
        if (!g || typeof g !== 'object') return null;
        const skew = got - (Number.isFinite(g.at) ? g.at : got);
        return {
            at: got,
            need: Number.isFinite(g.need) ? g.need : null,
            serverShare: Number.isFinite(g.serverShare) ? g.serverShare : 0,
            serverTimes: (Array.isArray(g.serverTimes) ? g.serverTimes : []).filter(Number.isFinite).map((t) => t + skew).slice(-200),
        };
    }

    /**
     * The server's reads, taken into what is kept: sellerId -> [changed at, seen at, [[piece, price, qty], ...]],
     * times by this PC's clock. Only set pieces are kept. A bazaar with none of them is kept only when it is
     * `known` (a seller of a piece as far as Torn Archive knows) or was kept before: that is how "sold out" is seen.
     * @param kept    the record (changed in place)
     * @param pieces  Set of piece ids, as strings
     * @param known   (sellerId as text) => boolean
     * @param got     when the answer arrived, by this PC's clock
     * @returns true when anything changed
     */
    function serverTake(kept, answer, pieces, known, got) {
        let changed = false;
        const skew = got - (answer && Number.isFinite(answer.now) ? answer.now : got);
        const mine = (at) => Math.min(got, Math.floor(at + skew));
        for (const read of answer && Array.isArray(answer.reads) ? answer.reads : []) {
            const id = svId(read && read.id);
            if (id === null || !Array.isArray(read.items)) continue;
            const at = Number.isFinite(read.at) && read.at > 0 ? mine(read.at) : got;
            const best = new Map();
            for (const entry of read.items) {
                const item = svId(entry && entry.id);
                const price = entry && entry.price;
                const qty = entry && entry.qty;
                if (item === null || !pieces.has(String(item))) continue;
                // A price of $1 or less is a locked listing: not for sale.
                if (!Number.isFinite(price) || !(price > 1) || !Number.isInteger(qty) || qty <= 0) continue;
                // One item at two prices: the cheaper one is what you would be buying.
                const had = best.get(item);
                if (!had || price < had[1]) best.set(item, [item, Math.round(price), qty]);
            }
            const prev = kept[id];
            if (!best.size && !prev && !(known && known(String(id)))) continue;
            kept[id] = [at, Math.max(at, prev ? prev[1] : 0), [...best.values()]];
            changed = true;
        }
        // Read again by the server and found the same: still true as of then.
        for (const pair of answer && Array.isArray(answer.seen) ? answer.seen : []) {
            const id = svId(Array.isArray(pair) ? pair[0] : null);
            const at = Array.isArray(pair) ? pair[1] : null;
            if (id === null || !Number.isFinite(at) || !kept[id]) continue;
            const seen = mine(at);
            if (seen > kept[id][1]) { kept[id][1] = seen; changed = true; }
        }
        return changed;
    }

    /** Drops what the server has not confirmed for SERVER_KEEP_MS. @returns true when anything went */
    function serverPrune(kept, now) {
        let changed = false;
        for (const id of Object.keys(kept)) {
            const e = kept[id];
            if (!Array.isArray(e) || !(now - e[1] <= SERVER_KEEP_MS)) { delete kept[id]; changed = true; }
        }
        return changed;
    }

    /** What was stored, read back strictly: anything not in shape is left out. */
    function serverReadKept(stored) {
        const out = {};
        if (!stored || typeof stored !== 'object' || Array.isArray(stored)) return out;
        for (const [id, entry] of Object.entries(stored)) {
            if (!/^\d{1,10}$/.test(id) || !Array.isArray(entry) || entry.length !== 3) continue;
            const [at, seen, items] = entry;
            if (!Number.isFinite(at) || !Number.isFinite(seen) || !Array.isArray(items)) continue;
            if (!items.every((i) => Array.isArray(i) && i.length === 3 && Number.isInteger(i[0]) && Number.isFinite(i[1]) && Number.isInteger(i[2]))) continue;
            out[id] = entry;
        }
        return out;
    }

    /** One bazaar as the server last had it: { at: when it was last seen so, items: { piece: { price, qty } } }, or null. */
    function serverShop(kept, whoId) {
        const e = kept && kept[String(whoId)];
        if (!e) return null;
        const items = {};
        for (const [item, price, qty] of e[2]) items[String(item)] = { price, qty };
        return { at: e[1], changedAt: e[0], items };
    }

    /** Every bazaar the server has holding a piece: [{ whoId, price, qty, at }], cheapest first. */
    function serverSellersOf(kept, pieceId) {
        const want = Number(pieceId);
        const out = [];
        for (const [whoId, e] of Object.entries(kept || {})) {
            for (const [item, price, qty] of e[2]) if (item === want) out.push({ whoId, price, qty, at: e[1] });
        }
        return out.sort((a, b) => a.price - b.price);
    }

    const SV_ALONE = { of: 1, me: 0 };

    /**
     * The other PCs' reads of TornW3B's lists, from the answer, added to what was kept: piece -> when, by this PC's
     * clock (the answer carries ages). And this PC's place among the PCs that are on.
     */
    function serverDirIn(answer, had, now) {
        const reads = {};
        for (const [item, at] of Object.entries(had && had.reads && typeof had.reads === 'object' ? had.reads : {})) {
            if (/^\d{1,10}$/.test(item) && Number.isFinite(at) && now - at < SERVER_DIR_KEEP_MS) reads[item] = at;
        }
        for (const entry of answer && Array.isArray(answer.dir) ? answer.dir : []) {
            if (!Array.isArray(entry)) continue;
            const item = svId(entry[0]);
            const age = entry[1];
            if (item === null || !Number.isFinite(age) || age < 0 || age >= SERVER_DIR_KEEP_MS) continue;
            const at = Math.floor(now - age);
            if (!(reads[item] >= at)) reads[item] = at;
        }
        const t = answer && answer.turn;
        const turn = t && Number.isInteger(t.of) && t.of >= 1 && t.of <= 50 && Number.isInteger(t.me) && t.me >= 0 && t.me < t.of ? { of: t.of, me: t.me } : { ...SV_ALONE };
        return { reads, turn };
    }

    /**
     * When a piece's TornW3B list was last read by anyone of us, as far as this PC should count it: its own read,
     * or another PC's. With several PCs on, a list that is another PC's to read first counts as read a little longer.
     * @param dir serverDirIn()'s result, or null with the server off
     */
    function serverListReadAt(ownAt, pieceId, dir) {
        if (!dir) return { at: ownAt || 0, wait: 0 };
        const friendAt = Number(dir.reads && dir.reads[String(pieceId)]) || 0;
        const turn = dir.turn || SV_ALONE;
        const mine = !(turn.of > 1) || Number(pieceId) % turn.of === turn.me;
        return { at: Math.max(ownAt || 0, friendAt), wait: mine ? 0 : SERVER_TURN_WAIT_MS };
    }

    // A Torn name as Torn makes them. The server sends each person's own, asked of Torn for their key: no person's
    // name is written in this script, and anything that is not one is not shown.
    const SV_TORN_NAME = /^[A-Za-z0-9_-]{1,32}$/;

    /** { id, name } as the server sent it, checked: a Torn id and a Torn name, or nulls. */
    function serverPerson(sent) {
        const id = sent && Number.isInteger(sent.id) && sent.id > 0 && sent.id < 1e10 ? sent.id : null;
        const name = sent && typeof sent.name === 'string' && SV_TORN_NAME.test(sent.name) ? sent.name : null;
        return { id, name };
    }

    function svOnNow(on) {
        const names = on.map((p) => p && p.name).filter(Boolean);
        if (!on.length) return 'nobody else is on now';
        if (names.length < on.length) return on.length === 1 ? '1 other is on now' : on.length + ' others are on now';
        return names.length === 1 ? names[0] + ' is on now' : names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1] + ' are on now';
    }

    const svClock = (at) => { const d = new Date(at); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };

    /**
     * What Settings says of the server, in words. Only what is known.
     * @param st the link's status()
     * @returns { on, level: 'off' | 'ok' | 'idle' | 'warn' | 'bad', now, key: { level, text }, split: { pc, server, free } | null, bazaars }
     */
    function serverLines(st, now) {
        const off = { on: false, level: 'off', now: st && (st.typed || st.hasPass) ? 'Off until the address and the password are both saved. Torn Archive works alone.' : 'Off. Torn Archive works alone.', key: null, split: null, bazaars: 0 };
        // Built in, nothing to type: it waits only for Torn to say who you are.
        if (st && !st.on && st.builtIn) return { ...off, level: 'idle', now: 'Asks the server once Torn has said who you are.' };
        if (!st || !st.on) return off;
        // Not one of the server's PCs (or not yet): no fault of yours, and nothing for you to do.
        if (st.why === 'address') {
            return { ...off, level: 'alone', now: st.careful
                ? `Working alone, and carefully: Torn said "too many", so Torn Archive keeps to ${SERVER_CAREFUL_MOST} requests a minute at most for now and tells the server what it uses. It asks again by itself.`
                : 'Working alone. The shared server serves the people its owner added, on a PC it has seen them at. Torn Archive asks again by itself.' };
        }
        const out = { on: true, level: 'ok', now: '', key: null, split: null, bazaars: st.bazaars || 0 };
        const alone = ' · working alone';
        if (st.why === 'password') return { ...out, level: 'bad', now: 'The server does not know this password. Ask whoever runs your server for yours.' };
        if (st.why === 'old') return { ...out, level: 'bad', now: 'This server has to be updated first: as it is, Torn Archive would overwrite what Torn Trading tells it. Nothing is sent to it.' };
        if (st.why === 'update') return { ...out, level: 'bad', now: 'The server asks for a newer Torn Archive' + (st.needVer ? ' (' + st.needVer + ' or later)' : '') + '. Nothing is sent to it until you update.' };
        if (!st.okAt) return { ...out, level: st.error ? 'warn' : 'idle', now: st.error ? 'No answer yet' + alone : 'Connecting…' };
        if (st.error || now - st.okAt > SERVER_QUIET_MS) return { ...out, level: 'warn', now: 'No answer since ' + svClock(st.okAt) + alone };
        const parts = ['Connected'];
        if (st.people) parts.push(st.people + (st.people === 1 ? ' person' : ' people'));
        if (st.people > 1) parts.push(svOnNow(st.peopleOn || []));
        parts.push('last exchange ' + Math.max(0, Math.floor((now - st.okAt) / 1000)) + ' s ago');
        const rests = { blocked: 'Torn has blocked the server for now', paused: 'the server is waiting on Torn', stopped: 'reading is stopped on the server', resting: 'the server rests until midnight UTC' };
        if (rests[st.reading]) { parts.push(rests[st.reading]); out.level = 'warn'; }
        if (st.whole) parts.push('Torn Trading is on here and keeps your whole limit, so the server leaves your key alone');
        out.now = parts.join(' · ');
        // Whose key the server holds for this password, as Torn says: so a key put under the wrong person shows.
        const whose = st.you && st.you.name ? st.you.name + (st.you.id ? ' [' + st.you.id + ']' : '') : null;
        if (st.key === 'working') out.key = { level: 'ok', text: whose ? 'Working · the key of ' + whose : 'Working' };
        else if (st.key) {
            const code = /\((\d+)\)/.exec(st.key);
            out.key = { level: 'bad', text: 'Torn refused your key on the server' + (code ? ' (code ' + code[1] + ')' : '') + '. Whoever runs your server needs a new Public Only key from you.' };
        }
        if (now - st.okAt <= SERVER_GRANT_STALE_MS && Number.isFinite(st.need) && Number.isFinite(st.serverShare)) {
            const pc = Math.max(0, Math.min(100, Math.round(st.need)));
            const server = Math.max(0, Math.min(100 - pc, Math.round(st.serverShare)));
            out.split = { pc, server, free: 100 - pc - server };
        }
        return out;
    }

    /**
     * The two markets as the server read them from Torn (its market.js): the points market, and the Item Market's
     * cheapest rows of the pieces. Public data of Torn's, the same for everyone. Times come in the server's clock
     * and go out in this PC's; a read older than SERVER_MARKET_FRESH_MS, or one that is not what it should be, is left out.
     * @returns {{ points: { at, json } | null, market: [{ id, at, listings: [{ price, amount }] }] }}
     *   `json` is in the shape Torn's own answer has (core/points.js parsePointsMarket)
     */
    function serverMarketIn(answer, pieces, got) {
        const out = { points: null, market: [] };
        if (!answer || typeof answer !== 'object' || !Number.isFinite(answer.now)) return out;
        const mine = pieces instanceof Set ? pieces : new Set((pieces || []).map(String));
        const skew = got - answer.now;
        const here = (at) => (Number.isFinite(at) && at > 0 ? Math.min(got, Math.floor(at + skew)) : null);
        const fresh = (at) => at !== null && got - at < SERVER_MARKET_FRESH_MS;
        const p = answer.points;
        if (p && typeof p === 'object' && Array.isArray(p.rows) && fresh(here(p.at))) {
            const book = {};
            let n = 0;
            for (const row of p.rows.slice(0, SV_MAX_POINT_ROWS)) {
                if (!Array.isArray(row)) continue;
                const cost = svWhole(row[1], 1e6);
                const qty = svWhole(row[2], 1e12);
                if (!cost || !qty) continue;
                book[String(row[0]).replace(/[^0-9A-Za-z_-]/g, '').slice(0, 20) || 'r' + n] = { cost, quantity: qty };
                n += 1;
            }
            if (n) out.points = { at: here(p.at), json: { pointsmarket: book } };
        }
        for (const m of Array.isArray(answer.market) ? answer.market.slice(0, 100) : []) {
            const id = svId(m && m.id);
            const at = here(m && m.at);
            if (id === null || !mine.has(String(id)) || !fresh(at) || !Array.isArray(m.rows)) continue;
            const listings = [];
            for (const row of m.rows.slice(0, SV_MAX_ROWS)) {
                const price = Array.isArray(row) ? svWhole(row[0], 1e13) : null;
                const amount = Array.isArray(row) ? svWhole(row[1], 1e9) : null;
                if (price > 1 && amount) listings.push({ price, amount });
            }
            out.market.push({ id: String(id), at, listings });
        }
        return out;
    }

    /* ===== src/api/server-link.js ===== */
    /*
     * The exchange with the shared server (core/server.js says what it is and what may be sent).
     *
     * One tab does it - the one that reads, Torn Archive's own page - every 30 s. Before the first exchange, and
     * again whenever the server says it started afresh, the server is asked what it is (GET /state, which changes
     * nothing): an older server keeps one list a person, and a sync from Torn Archive would overwrite what Torn
     * Trading told it. Such a server is never synced with.
     *
     * The server's address is built into the released copy (build.mjs), and with nothing typed Torn Archive says
     * whose copy it is instead of a password (core/server.js serverClaim): the server lets it in on the PC where
     * that person's Torn Trading runs, and turns everyone else away - they are asked again a few times a day, and
     * nothing but the Torn id was said. Once the server has said it knows copies, a word this copy made for itself
     * goes with the id (SERVER_DEVICE_KEY): a copy that was let in once is known by it afterwards, wherever it asks from.
     *
     * Turned away, and Torn has said "too many" (the client's learned ceiling): Torn Archive keeps itself to a
     * careful pace (the client, core/server.js SERVER_CAREFUL_MOST) and says once a minute what it uses. The server
     * answers that as it answers any stranger - not found - and, where it holds this person's key, takes that much
     * less of it. Nothing is said while Torn Archive asks Torn nothing.
     *
     * An address and password typed in an older copy still go first. The password
     * is kept in Tampermonkey's storage like a key: it goes to that one address in a header, is never shown again,
     * and is in no log and no zip.
     *
     * Everything it touches is passed in (storage, the request, the clock), so it runs whole in the tests against
     * the server's own code.
     */




    const SERVER_CONFIG_KEY = 'server.config';
    const SERVER_STATE_KEY = 'server.state';
    const SERVER_GRANT_KEY = 'server.grant';
    /** This PC's request counts waiting to be sent (core/usage.js usageCallsAdd). */
    const SERVER_CALLS_KEY = 'server.calls';
    /** This copy's own word (core/server.js serverClaim). Made once and kept: it is what the server knows the copy by. */
    const SERVER_DEVICE_KEY = 'server.device';
    /** true once the server has said it knows a copy by its word: until then the id is said alone, as an older server expects. */
    const SERVER_COPIES_KEY = 'server.copies';
    const SL_MAX_PAGES = 5;
    /** What the pieces are worth is said again when it changed, and at least this often. */
    const SL_WORTH_EVERY_MS = 10 * 60000;
    /** The server is asked what it is this often, besides at the start and after it started afresh. */
    const SL_HELLO_EVERY_MS = 6 * 60 * 60000;
    /** A server that turned Torn Archive away (password, too old, wants an update) is tried again this often. */
    const SERVER_RETRY_MS = 5 * 60000;
    /** A server that does not know this PC (core/server.js serverClaim) is asked again after this long: each time later. */
    const SERVER_ADDRESS_RETRY_MS = [5 * 60000, 15 * 60000, 60 * 60000, 6 * 60 * 60000];
    /** Calls held back for the server's part: an exchange is asked for sooner, but never closer than this. */
    const SL_SOON_MS = 6000;

    const slWhy = (why, message, more = {}) => Object.assign(new Error(message), { why }, more);

    class ServerLink {
        /**
         * @param {object} d
         * @param {(key: string) => *} d.load
         * @param {(key: string, value: *) => void} d.save
         * @param {(key: string) => void} d.del
         * @param {(url: string, options: object) => Promise<{ok, status, json}>} d.send - platform/gm.js gmSend
         * @param {string} d.version
         * @param {string[]} d.pieces - the piece ids: nothing else is named to the server
         * @param {() => {used: number, waiting: number}} d.getUse - Torn calls of the last minute, and waiting
         * @param {() => boolean} [d.tradingOn] - is Torn Trading running on this PC now (core/turns.js)
         * @param {() => object} d.getWant - { sellers, looking, worth, bought, dir } (the engine's serverWant)
         * @param {() => {seq: number, seenAt: number}} d.getMark - how far the server's reads were taken
         * @param {(answer: object, got: number) => void} d.take - one answer, for the engine to fold in
         * @param {() => void} d.forget - what was kept of the server goes (its address or password changed)
         * @param {string} [d.home] - the server's address built into this copy ('' = none: the boxes in Settings)
         * @param {() => string} [d.getId] - your Torn id, once Torn has said it
         * @param {() => string} [d.random] - 48 hex characters nobody could guess, for this copy's own word
         * @param {() => boolean} [d.lowered] - has Torn said "too many", so that the client holds itself under its pace
         * @param {() => void} [d.onChange]
         * @param {() => number} [d.now]
         */
        constructor(d) {
            this.d = d;
            this.now = d.now || (() => Date.now());
            this.busy = false;
            this.soon = false;
            this.again = false;
            this.grantKept = undefined;
            this.worthJson = '';
            this.worthAt = 0;
        }

        /** { address, pass, own }, or null when the server is off. own: nothing was typed - the built-in address, as whoever Torn says you are. */
        config() {
            const c = this.d.load(SERVER_CONFIG_KEY);
            const address = c ? serverAddress(c.address) : null;
            if (address && serverPassOk(c.pass)) return { address, pass: c.pass, own: false };
            const home = serverAddress(this.d.home);
            const claim = home ? serverClaim(this.d.getId ? this.d.getId() : '', this.device()) : null;
            return claim ? { address: home, pass: claim, own: true } : null;
        }

        /** This copy's own word: made the first time it is needed, then always the same. '' = none could be made, or the server has not said it knows copies. */
        device() {
            if (this.d.load(SERVER_COPIES_KEY) !== true) return '';
            if (this.deviceKept === undefined) {
                let device = this.d.load(SERVER_DEVICE_KEY);
                if (!serverDeviceOk(device)) {
                    device = this.d.random ? this.d.random() : '';
                    if (serverDeviceOk(device)) this.d.save(SERVER_DEVICE_KEY, device);
                    else device = '';
                }
                this.deviceKept = device;
            }
            return this.deviceKept;
        }

        /** Not one of the server's PCs as far as it says: Torn Archive works alone. */
        turnedAway() {
            const cfg = this.config();
            return Boolean(cfg && cfg.own && this.state().why === 'address');
        }

        /** Turned away, and Torn has said "too many": the careful pace, and the server is told what is used. */
        careful() {
            return this.turnedAway() && Boolean(this.d.lowered && this.d.lowered());
        }

        /** What Torn Archive uses, said to a server that does not let it in. Answered "not found" unless that changed. */
        async hint(cfg, before, now) {
            if (now - (before.hintAt || 0) < SERVER_HINT_MS || !this.careful()) return false;
            const use = this.d.getUse() || {};
            const body = serverHint({ ver: this.d.version, used: use.used, waiting: use.waiting });
            if (!(body.used + body.waiting > 0)) return false;
            this.busy = true;
            this.d.save(SERVER_STATE_KEY, { ...before, hintAt: now });
            try {
                const response = await this.d.send(`${cfg.address}/sync`, { method: 'POST', headers: { Authorization: `Bearer ${cfg.pass}` }, body });
                // Let in after all: the whole exchange at the next look, not at the next try hours on.
                if (response.status === 200) this.again = true;
            } catch {
                // Said again a minute on.
            } finally {
                this.busy = false;
            }
            return true;
        }

        /** Is this PC one of the server's - so that what it asks is counted for it? Not while the server turns it away. */
        on() {
            const cfg = this.config();
            return Boolean(cfg) && !(cfg.own && this.state().why === 'address');
        }

        /** Something changed that may let a turned-away copy in (this page just opened, Torn Trading came on): ask now, not at the next try. */
        wake() { this.again = true; }

        /** Your part of your Torn limit as the server last gave it (null = on its own). */
        grant() {
            if (this.grantKept === undefined) this.grantKept = (this.config() && this.d.load(SERVER_GRANT_KEY)) || null;
            return this.grantKept;
        }

        state() {
            const s = this.d.load(SERVER_STATE_KEY);
            return s && typeof s === 'object' ? s : {};
        }

        /**
         * The address and the password, as typed. Either may be left empty to keep what is saved.
         * @returns {{ ok: boolean, why: '' | 'address' | 'password' }}
         */
        saveConfig(address, pass) {
            const had = this.d.load(SERVER_CONFIG_KEY) || {};
            const typedAddress = String(address ?? '').trim();
            const typedPass = String(pass ?? '').trim();
            const nextAddress = typedAddress ? serverAddress(typedAddress) : serverAddress(had.address);
            if (!nextAddress) return { ok: false, why: 'address' };
            const nextPass = typedPass || had.pass || '';
            if (!serverPassOk(nextPass)) return { ok: false, why: 'password' };
            if (nextAddress !== serverAddress(had.address) || nextPass !== had.pass) this.forget();
            this.d.save(SERVER_CONFIG_KEY, { address: nextAddress, pass: nextPass });
            return { ok: true, why: '' };
        }

        /** The server is switched off, or its address or password changed: what was kept under the old one goes. */
        forget() {
            for (const key of [SERVER_CONFIG_KEY, SERVER_STATE_KEY, SERVER_GRANT_KEY, SERVER_CALLS_KEY]) this.d.del(key);
            this.grantKept = null;
            this.worthJson = '';
            this.worthAt = 0;
            this.d.forget();
        }

        /** Torn calls are waiting on the server's part: an exchange is wanted soon, to ask for room. */
        askSoon() { this.soon = true; }

        /** Call every few seconds; it exchanges every SERVER_SYNC_MS. */
        async tick() {
            const cfg = this.config();
            if (!cfg || this.busy) return false;
            const now = this.now();
            const before = this.state();
            if (before.retryAt && now < before.retryAt && !(this.again && before.why === 'address')) {
                if (cfg.own && before.why === 'address') await this.hint(cfg, before, now);
                return false;
            }
            const since = now - (before.syncAt || 0);
            if (since < SERVER_SYNC_MS && !(this.soon && since >= SL_SOON_MS)) return false;
            this.busy = true;
            this.soon = false;
            this.again = false;
            try {
                await this.exchange(cfg, before);
            } finally {
                this.busy = false;
            }
            return true;
        }

        keepGrant(answer, got) {
            const grant = serverGrantIn(answer, got);
            if (!grant) return null;
            this.grantKept = grant;
            this.d.save(SERVER_GRANT_KEY, grant);
            return grant;
        }

        async exchange(cfg, before) {
            const startedAt = this.now();
            const auth = { Authorization: `Bearer ${cfg.pass}` };
            const state = { ...before, syncAt: startedAt, error: null, why: null, needVer: null, retryAt: 0 };
            let born = before.born ?? null;
            try {
                // What is this server? Asked before anything is told to it.
                if (!before.helloOk || !(startedAt - (before.helloAt || 0) < SL_HELLO_EVERY_MS)) {
                    state.helloOk = false;
                    const hello = await this.d.send(`${cfg.address}/state`, { method: 'GET', headers: auth });
                    if (hello.status === 404) throw this.unknown(cfg);
                    if (!hello.ok) throw new Error(`The server answered with status ${hello.status}.`);
                    const what = await hello.json();
                    if (!serverKnowsApps(what)) throw slWhy('old', 'This server keeps one list a person: it has to be updated first.');
                    // From the next look on this copy says its own word with its id.
                    if (cfg.own && serverKnowsCopies(what) && this.d.load(SERVER_COPIES_KEY) !== true) this.d.save(SERVER_COPIES_KEY, true);
                    state.helloOk = true;
                    state.helloAt = startedAt;
                }
                for (let page = 0; page < SL_MAX_PAGES; page += 1) {
                    const now = this.now();
                    // A Torn Trading here that tells the server nothing: its whole limit is said for it (core/server.js serverUse).
                    const use = serverUse(this.d.getUse() || {}, { tradingOn: !!(this.d.tradingOn && this.d.tradingOn()), beside: state.beside, besideAt: state.besideAt, now });
                    const want = this.d.getWant() || {};
                    const mark = this.d.getMark() || {};
                    const worthJson = JSON.stringify(serverBody({ want, pieces: this.d.pieces, sendWorth: true }).worth);
                    const sendWorth = page === 0 && (worthJson !== this.worthJson || now - this.worthAt >= SL_WORTH_EVERY_MS || born === null);
                    // What this PC asked of TornW3B and Torn since the last answered exchange: with the first page only.
                    const callsOut = page === 0 ? usageCallsOut(this.d.load(SERVER_CALLS_KEY), now) : null;
                    const body = serverBody({ ver: this.d.version, used: use.used, waiting: use.waiting, want, pieces: this.d.pieces, since: mark.seq, seen: mark.seenAt, sendWorth, now, calls: callsOut });
                    if (!serverOutgoingOk(body, this.d.pieces)) throw new Error('Not sent: the message was not in the agreed shape.');

                    const response = await this.d.send(`${cfg.address}/sync`, { method: 'POST', headers: auth, body });
                    if (response.status === 404) throw this.unknown(cfg);
                    if (response.status === 426) {
                        // Turned away until Torn Archive is updated. Its Torn use is still counted there, so its part still holds.
                        const said = await response.json().catch(() => null);
                        this.keepGrant(said, this.now());
                        throw slWhy('update', 'The server asks for a newer Torn Archive.', { needVer: said && typeof said.need === 'string' ? said.need.slice(0, 20) : null });
                    }
                    if (!response.ok) throw new Error(`The server answered with status ${response.status}.`);
                    const answer = await response.json();
                    const got = this.now();
                    const grant = this.keepGrant(answer, got);
                    if (!answer || typeof answer !== 'object' || !grant) throw new Error('The server answered with something else.');

                    if (body.calls) {
                        // Answered: what was sent comes off the sum. Not answered, it stays and goes with the next one.
                        const sum = Object.values(body.calls).reduce((a, n) => a + n, 0);
                        if (sum) this.d.save(SERVER_CALLS_KEY, usageCallsSent(this.d.load(SERVER_CALLS_KEY), body.calls, got));
                        state.callsOut = (Number.isInteger(state.callsOut) ? state.callsOut : 0) + sum;
                        state.callsSyncs = (Number.isInteger(state.callsSyncs) ? state.callsSyncs : 0) + 1;
                    }
                    if (sendWorth) {
                        this.worthJson = worthJson;
                        this.worthAt = now;
                    }
                    // A server that started afresh has forgotten what the pieces are worth, and may be another one: asked again.
                    if (answer.born !== undefined && answer.born !== born) {
                        if (born !== null) { this.worthJson = ''; state.helloOk = false; }
                        born = answer.born;
                    }
                    this.d.take(answer, got);
                    state.okAt = got;
                    state.reading = typeof answer.state === 'string' ? answer.state.slice(0, 20) : null;
                    state.key = typeof answer.key === 'string' ? answer.key.slice(0, 60) : null;
                    state.need = grant.need;
                    state.serverShare = grant.serverShare;
                    state.serverUsed = grant.serverTimes.length;
                    state.people = Number.isInteger(answer.people) && answer.people > 0 ? answer.people : null;
                    state.on = (Array.isArray(answer.on) ? answer.on : []).slice(0, 20).map(serverPerson);
                    state.you = serverPerson(answer.you);
                    state.beside = (Array.isArray(answer.beside) ? answer.beside : []).filter((name) => typeof name === 'string' && /^[a-z][a-z0-9-]{1,23}$/.test(name)).slice(0, 8);
                    state.besideAt = got;
                    state.whole = use.whole;
                    state.turned = 0;
                    if (!Array.isArray(answer.reads) || answer.reads.length < SERVER_PAGE) break;
                }
            } catch (error) {
                state.error = String(error && error.message ? error.message : error).slice(0, 160);
                state.why = (error && error.why) || null;
                state.needVer = (error && error.needVer) || null;
                if (state.why === 'address') {
                    // Not one of the server's PCs: asked again later each time, a few times a day in the end.
                    state.turned = Math.min(99, (Number.isInteger(before.turned) ? before.turned : 0) + 1);
                    state.retryAt = startedAt + SERVER_ADDRESS_RETRY_MS[Math.min(state.turned, SERVER_ADDRESS_RETRY_MS.length) - 1];
                } else if (state.why) state.retryAt = startedAt + SERVER_RETRY_MS;
            }
            state.born = born;
            this.d.save(SERVER_STATE_KEY, state);
            if (this.d.onChange) this.d.onChange();
        }

        /** The server said 404: a typed password it does not know, or - with nothing typed - a PC it does not serve. */
        unknown(cfg) {
            return cfg.own ? slWhy('address', 'The server does not serve this PC.') : slWhy('password', 'The server does not know this password.');
        }

        /** For Settings (core/server.js serverLines). The password is not in it, nor the built-in address. */
        status(now = this.now()) {
            const cfg = this.config();
            const typed = this.d.load(SERVER_CONFIG_KEY) || {};
            const state = cfg ? this.state() : {};
            return {
                on: Boolean(cfg),
                own: Boolean(cfg && cfg.own),
                builtIn: Boolean(serverAddress(this.d.home)),
                address: cfg && !cfg.own ? cfg.address : null,
                typed: String(typed.address || ''),
                hasPass: serverPassOk(typed.pass),
                okAt: state.okAt || null,
                syncAt: state.syncAt || null,
                error: state.error || null,
                why: state.why || null,
                careful: this.careful(),
                needVer: state.needVer || null,
                reading: state.reading || null,
                key: state.key || null,
                need: Number.isFinite(state.need) ? state.need : null,
                serverShare: Number.isFinite(state.serverShare) ? state.serverShare : null,
                serverUsed: Number.isFinite(state.serverUsed) ? state.serverUsed : null,
                beside: Array.isArray(state.beside) ? state.beside : [],
                whole: state.whole === true,
                people: Number.isInteger(state.people) ? state.people : null,
                peopleOn: Array.isArray(state.on) ? state.on : [],
                you: state.you || null,
                callsOut: Number.isInteger(state.callsOut) ? state.callsOut : 0,
                callsSyncs: Number.isInteger(state.callsSyncs) ? state.callsSyncs : 0,
                now,
            };
        }
    }

    /* ===== src/core/sets.js ===== */
    // Sets: plushies and flowers, swapped at the museum for points.
    // Pure working-out, no page and no storage: what you hold of each piece, how many more a set needs, what a piece is
    // worth to you at a points price, what you pay a seller at your rate, and the words for a trade and a forum thread.
    // The points market and the points book are in points.js.

    const setPiece = (id, name) => ({ id, name });

    /** The two museum sets Torn Archive trades. Ids are Torn's item ids; names are matched too, in case one ever moves. */
    const SETS = [
        {
            key: 'plushie', name: 'Plushie Set', short: 'plushie', museum: 'Plushie Set', hash: 'plushie', points: 10, w3bId: -2,
            pieces: [
                setPiece(186, 'Sheep Plushie'), setPiece(187, 'Teddy Bear Plushie'), setPiece(215, 'Kitten Plushie'), setPiece(258, 'Jaguar Plushie'),
                setPiece(261, 'Wolverine Plushie'), setPiece(266, 'Nessie Plushie'), setPiece(268, 'Red Fox Plushie'), setPiece(269, 'Monkey Plushie'),
                setPiece(273, 'Chamois Plushie'), setPiece(274, 'Panda Plushie'), setPiece(281, 'Lion Plushie'), setPiece(384, 'Camel Plushie'),
                setPiece(618, 'Stingray Plushie'),
            ],
        },
        {
            key: 'flower', name: 'Flower Set', short: 'flower', museum: 'Exotic Flower Set', hash: 'flower', points: 10, w3bId: -1,
            pieces: [
                setPiece(260, 'Dahlia'), setPiece(263, 'Crocus'), setPiece(264, 'Orchid'), setPiece(267, 'Heather'), setPiece(271, 'Ceibo Flower'),
                setPiece(272, 'Edelweiss'), setPiece(276, 'Peony'), setPiece(277, 'Cherry Blossom'), setPiece(282, 'African Violet'),
                setPiece(385, 'Tribulus Omanense'), setPiece(617, 'Banana Orchid'),
            ],
        },
    ];

    const SET_BY_ITEM = new Map();
    for (const set of SETS) for (const p of set.pieces) SET_BY_ITEM.set(String(p.id), set);

    const setByKey = (key) => SETS.find((s) => s.key === key) || null;
    /** The set an item is a piece of, or null. */
    const setOfItem = (itemId) => SET_BY_ITEM.get(String(itemId)) || null;
    const isSetItem = (itemId) => SET_BY_ITEM.has(String(itemId));
    /** A piece's name without the set's word, for a tight tile: "Panda Plushie" -> "Panda". */
    const shortName = (name) => String(name || '').replace(/\s+Plushie$/i, '');

    const setNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const setWhole = (v) => Math.max(0, Math.floor(setNum(v)));

    /** The sets switched on in the settings: `which` is { plushie: true, flower: true }. */
    function setsOn(settings) {
        if (!settings || !settings.on) return [];
        const which = settings.which || {};
        return SETS.filter((s) => which[s.key] !== false);
    }

    /** While Sets is on, a plushie or flower of a chosen set is kept for sets: never To sell, never offered, never filled. */
    function keptForSets(itemId, settings) {
        const set = setOfItem(itemId);
        return !!set && setsOn(settings).includes(set);
    }

    /**
     * What you hold of one set, against the number of sets you are building.
     * @param held   itemId -> how many you hold (object or Map)
     * @param target sets being built at once; a piece under it says "need", over it "ahead"
     * `full` is how many whole sets you could swap now; `top` is the piece holding the next set back.
     */
    function setStock(set, held, target) {
        const get = setHeldOf(held);
        const counts = set.pieces.map((p) => get(p.id));
        const full = counts.length ? Math.min(...counts) : 0;
        const most = counts.length ? Math.max(...counts) : 0;
        const aim = Math.max(setWhole(target), full);
        const pieces = set.pieces.map((p, i) => {
            const have = counts[i];
            const need = Math.max(0, aim - have);
            const ahead = Math.max(0, have - aim);
            return { id: p.id, name: p.name, held: have, need, ahead, state: need ? 'need' : ahead ? 'ahead' : 'ok', top: false, rank: 0 };
        });
        // Rank by need: 1 is the piece you hold least of. It is "top" only while it holds a set back.
        const order = [...pieces].sort((a, b) => a.held - b.held || a.name.localeCompare(b.name));
        order.forEach((p, i) => { p.rank = i + 1; });
        const short = order.length && order[0].need > 0 ? order[0] : null;
        if (short) short.top = true;
        return { key: set.key, name: set.name, points: set.points, full, most, target: aim, pieces, short };
    }

    const setHeldOf = (held) => (id) => setWhole(held instanceof Map ? (held.get(String(id)) ?? held.get(Number(id))) : (held || {})[id]);

    /** What it costs to bring every piece of a set up to `target`, paying payOf(id) for a unit: what is held is not bought again. */
    function fillCost(set, held, target, payOf) {
        const get = setHeldOf(held);
        let cost = 0;
        for (const p of set.pieces) cost += Math.max(0, setWhole(target) - get(p.id)) * setWhole(payOf(p.id));
        return cost;
    }

    /**
     * How many sets to build at once when the owner types no number: the sets he already holds, and as many more as
     * the money pays for - counting every piece he holds, so a piece he has plenty of costs nothing more (the owner's
     * rule, 2026-10-10). A pile of one piece does not raise it past what the money reaches.
     * While the money or a piece's price is not known, it is the piece he holds most of: those wait for the others.
     * @param budget what may be spent on this set's pieces (null = not known)
     * @param payOf  itemId -> what one unit costs him
     */
    function autoTarget(set, held, budget, payOf) {
        const st = setStock(set, held, 0);
        const pays = typeof payOf === 'function' ? set.pieces.map((p) => setWhole(payOf(p.id))) : [];
        if (budget == null || !Number.isFinite(Number(budget)) || !pays.length || pays.some((v) => !v)) return st.most;
        const money = Math.max(0, setNum(budget));
        // cost(T) only grows with T, and past the largest pile every set more costs a whole set.
        let lo = st.full;
        let hi = st.most + Math.floor(money / pays.reduce((a, b) => a + b, 0));
        while (lo < hi) {
            const mid = Math.ceil((lo + hi) / 2);
            if (fillCost(set, held, mid, payOf) <= money) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }

    /**
     * The same for every set traded, from ONE purse: the money is split evenly between the sets, and what one of them
     * cannot use (too little for its next set) is offered to the others, in order.
     * @param heldOf set -> what is held of it (object or Map)
     * @returns { key: sets to build }
     */
    function autoTargets(sets, heldOf, budget, payOf) {
        const out = {};
        const known = budget != null && Number.isFinite(Number(budget));
        const priced = sets.filter((s) => s.pieces.every((p) => setWhole(payOf(p.id)) > 0));
        for (const s of sets) if (!known || !priced.includes(s)) out[s.key] = autoTarget(s, heldOf(s), null, payOf);
        if (!known || !priced.length) return out;
        let left = Math.max(0, setNum(budget));
        const part = Math.floor(left / priced.length);
        const spent = {};
        for (const s of priced) {
            out[s.key] = autoTarget(s, heldOf(s), part, payOf);
            spent[s.key] = fillCost(s, heldOf(s), out[s.key], payOf);
            left -= spent[s.key];
        }
        for (const s of priced) {
            const more = autoTarget(s, heldOf(s), spent[s.key] + left, payOf);
            if (more <= out[s.key]) continue;
            const cost = fillCost(s, heldOf(s), more, payOf);
            left -= cost - spent[s.key];
            spent[s.key] = cost;
            out[s.key] = more;
        }
        return out;
    }

    /** A set's pieces at Torn's market value, summed. 0 when a piece has none yet. */
    function setMarketValue(set, mv) {
        let sum = 0;
        for (const p of set.pieces) {
            const v = setWhole(mv(p.id));
            if (!v) return 0;
            sum += v;
        }
        return sum;
    }

    /** What a set brings at a points price. */
    const setValue = (set, pointsPrice) => set.points * setWhole(pointsPrice);

    /**
     * What one piece is worth to you: the set's value at the points price, shared over its pieces by market value.
     * A piece listed under this is profit for the set. Returns itemId -> dollars (0 when it cannot be worked out).
     */
    function pieceWorths(set, mv, pointsPrice) {
        const total = setMarketValue(set, mv);
        const value = setValue(set, pointsPrice);
        const out = new Map();
        for (const p of set.pieces) out.set(String(p.id), total && value ? Math.floor(value * setWhole(mv(p.id)) / total) : 0);
        return out;
    }

    /** What you pay a seller for one unit: your percentage of its market value. */
    const ratePrice = (marketValue, pct) => Math.round(setWhole(marketValue) * setNum(pct) / 100);

    /**
     * Your rate, against the points price: what a set bought at it costs, what it leaves, and the highest rate that
     * still keeps your least profit (a percentage of what you spend - the same setting flips use).
     */
    function rateSet(set, mv, pct, pointsPrice, leastProfitPct = 0) {
        const market = setMarketValue(set, mv);
        const value = setValue(set, pointsPrice);
        let cost = 0;
        for (const p of set.pieces) cost += ratePrice(mv(p.id), pct);
        const profit = value - cost;
        const kept = cost > 0 ? profit / cost * 100 : 0;
        // cost <= value / (1 + least/100), and cost = market * pct / 100: rounded DOWN to a tenth, so the cap itself still pays.
        const cap = market > 0 && value > 0 ? Math.floor(value / (1 + Math.max(0, setNum(leastProfitPct)) / 100) / market * 1000) / 10 : 0;
        return { market, value, cost, profit, kept, cap, ok: value > 0 && market > 0 && setNum(pct) <= cap };
    }

    /**
     * What the pieces of your full sets cost you, cheapest-paid units first.
     * @param lots itemId -> [{ qty, each }] of what you paid for units you still hold (any order). Units with no
     *             record are counted at `fallback(id)` (market value) and `known` turns false.
     * @returns { sets, total, perSet, least, known } - `least` is the points price a point must sell OVER.
     */
    function setsCost(set, sets, lots, fallback) {
        const n = setWhole(sets);
        let total = 0;
        let known = true;
        for (const p of set.pieces) {
            const mine = [...((lots && lots(p.id)) || [])].filter((l) => setWhole(l.qty) > 0 && setNum(l.each) > 0).sort((a, b) => a.each - b.each);
            let left = n;
            for (const l of mine) {
                if (left <= 0) break;
                const take = Math.min(left, setWhole(l.qty));
                total += take * setNum(l.each);
                left -= take;
            }
            if (left > 0) {
                known = false;
                total += left * setWhole(fallback ? fallback(p.id) : 0);
            }
        }
        total = Math.round(total);
        const perSet = n ? Math.round(total / n) : 0;
        return { sets: n, total, perSet, least: n ? Math.floor(perSet / set.points) : 0, known };
    }

    /** The least price a point may be typed at and still be a profit: one dollar over what it cost. */
    const leastPointPrice = (costPerPoint) => Math.floor(setNum(costPerPoint)) + 1;

    /**
     * Where to buy the pieces you need, now. A unit is worth buying while its price is UNDER the piece's worth.
     * @param offers itemId -> [{ price, qty, src: 'bazaar' | 'market', who, whoId }]
     * Each row has the cheapest bazaars and the cheapest Item Market listing side by side, the better one marked,
     * and the units to buy (cheapest first, up to what you need).
     */
    function buyPlan(set, stock, worths, offers) {
        const rows = [];
        const sellers = new Set();
        let count = 0;
        let cost = 0;
        let gain = 0;
        let market = 0;
        const after = new Map(stock.pieces.map((p) => [String(p.id), p.held]));
        for (const p of stock.pieces) {
            const worth = setWhole(worths.get(String(p.id)));
            const all = [...((offers && offers(p.id)) || [])].filter((o) => setWhole(o.price) > 0 && setWhole(o.qty) > 0).sort((a, b) => a.price - b.price);
            const bazaar = all.filter((o) => o.src !== 'market');
            const im = all.filter((o) => o.src === 'market');
            const row = {
                id: p.id, name: p.name, held: p.held, need: p.need, ahead: p.ahead, state: p.state, top: p.top, rank: p.rank, worth,
                bazaar: bazaar.slice(0, 2), market: im[0] || null, best: null, units: [], count: 0, cost: 0, gain: 0, over: false,
            };
            const b = bazaar[0];
            const m = im[0];
            if (b && m) row.best = m.price < b.price ? 'market' : 'bazaar';
            else if (b || m) row.best = b ? 'bazaar' : 'market';
            if (p.need > 0 && worth > 0) {
                let left = p.need;
                for (const o of all) {
                    if (left <= 0 || o.price >= worth) break;
                    const take = Math.min(left, setWhole(o.qty));
                    row.units.push({ ...o, take });
                    row.count += take;
                    row.cost += take * o.price;
                    row.gain += take * (worth - o.price);
                    left -= take;
                    if (o.src === 'market') market += take;
                    else if (o.whoId != null || o.who) sellers.add(String(o.whoId ?? o.who));
                }
                // Needed, something is listed, and the cheapest of it is at or over its worth: wait.
                row.over = !row.count && all.length > 0;
            }
            after.set(String(p.id), p.held + row.count);
            count += row.count;
            cost += row.cost;
            gain += row.gain;
            rows.push(row);
        }
        rows.sort((a, b) => (b.count > 0) - (a.count > 0) || (b.need > 0) - (a.need > 0) || a.rank - b.rank);
        const fullAfter = after.size ? Math.min(...after.values()) : 0;
        return { key: set.key, name: set.name, rows, count, cost, gain, bazaars: sellers.size, market, full: stock.full, fullAfter };
    }

    /**
     * Whole sets bought fresh in one run: the k-th set takes the k-th cheapest unit of every piece. Sets are added
     * while one still leaves the least profit and the cash lasts.
     * @returns null when not even one set pays, else { sets, pieces, bazaars, cost, perSet, value, gain }
     */
    function setRun(set, offers, value, { cash = Infinity, leastProfitPct = 0, most = 500 } = {}) {
        if (!(value > 0)) return null;
        const ladders = set.pieces.map((p) => {
            const units = [];
            const all = [...((offers && offers(p.id)) || [])].filter((o) => setWhole(o.price) > 0 && setWhole(o.qty) > 0).sort((a, b) => a.price - b.price);
            for (const o of all) {
                for (let i = 0; i < setWhole(o.qty) && units.length < most; i++) units.push(o);
                if (units.length >= most) break;
            }
            return units;
        });
        const depth = Math.min(...ladders.map((l) => l.length));
        const sellers = new Set();
        let sets = 0;
        let cost = 0;
        let market = 0;
        for (let k = 0; k < depth; k++) {
            const one = ladders.reduce((s, l) => s + l[k].price, 0);
            if (value - one < one * Math.max(0, setNum(leastProfitPct)) / 100 || value <= one) break;
            if (cost + one > cash) break;
            cost += one;
            sets++;
            for (const l of ladders) {
                if (l[k].src === 'market') market++;
                else sellers.add(String(l[k].whoId ?? l[k].who));
            }
        }
        if (!sets) return null;
        return { key: set.key, name: set.name, sets, pieces: sets * set.pieces.length, bazaars: sellers.size, market, cost, perSet: Math.round(cost / sets), value, gain: sets * value - cost };
    }

    const setMoney = (n) => '$' + Math.round(setNum(n)).toLocaleString('en-US');

    /**
     * Someone's items in a trade, priced at your rate.
     * @param items  [{ id, name, qty }] - their side of the trade
     * @param ctx    { settings, stockOf(set) -> setStock result, mv(id), pct, pay(id) } - `pay`, when given, is the
     *               price of one unit as it stands now; without it a unit is `pct` of its market value
     * Rows of a chosen set get a price and one word: need, ok ("enough for now") or ahead. Anything else gets none.
     * Of a row that holds more than you need, `take` units are the ones you need and `extra` the rest: the total for
     * what you need counts only the first.
     */
    function tradeOffer(items, ctx) {
        const on = setsOn(ctx.settings);
        const rows = [];
        const need = { items: 0, total: 0 };
        const all = { items: 0, total: 0 };
        for (const it of items || []) {
            const qty = setWhole(it.qty);
            if (!qty) continue;
            const set = setOfItem(it.id);
            if (!set || !on.includes(set)) {
                rows.push({ id: it.id, name: it.name, qty, each: 0, total: 0, state: 'other', need: 0, ahead: 0, take: 0, extra: 0, top: false });
                continue;
            }
            const pc = ctx.stockOf(set).pieces.find((p) => String(p.id) === String(it.id));
            // What you pay for it now (core/sellrate.js: your rate, or the set's ceiling when that is lower).
            const each = ctx.pay ? setWhole(ctx.pay(it.id)) : ratePrice(ctx.mv(it.id), ctx.pct);
            const take = pc.state === 'need' ? Math.min(qty, pc.need) : 0;
            const row = { id: it.id, name: it.name || pc.name, qty, each, total: each * qty, take, extra: qty - take, state: pc.state, need: pc.need, ahead: pc.ahead, held: pc.held, target: pc.held + pc.need - pc.ahead, top: pc.top };
            rows.push(row);
            if (!each) continue;
            all.items += qty;
            all.total += row.total;
            need.items += take;
            need.total += take * each;
        }
        return { rows, need, all };
    }

    const setListWords = (parts) => (parts.length <= 1 ? parts.join('') : parts.slice(0, -1).join(', ') + ' and ' + parts[parts.length - 1]);

    /** The message to copy into Torn's trade chat. `everything` prices every piece, not only the ones you need. */
    function tradeMessage(offer, { open = true, everything = false } = {}) {
        const priced = offer.rows.filter((r) => r.each > 0);
        const wanted = priced.filter((r) => r.take > 0);
        const rest = priced.filter((r) => r.extra > 0);
        const others = offer.rows.filter((r) => r.state === 'other');
        const each = (r) => `${r.qty} ${r.name} (${setMoney(r.each)} each)`;
        const needed = (r) => `${r.take} ${r.name} (${setMoney(r.each)} each)`;
        const out = [];
        if (!open) out.push('I am closed for buying right now.');
        if (everything && priced.length) {
            out.push(`I can pay ${setMoney(offer.all.total)} for ${setListWords(priced.map(each))}.`);
        } else if (wanted.length) {
            out.push(`I can pay ${setMoney(offer.need.total)} for ${setListWords(wanted.map(needed))}.`);
            if (rest.length) out.push(`${setListWords(rest.map((r) => `${r.take > 0 ? r.extra + ' more ' : ''}${shortName(r.name)} (${setMoney(r.each)})`))} I have enough of for now; same price if you want them gone.`);
        } else if (rest.length) {
            out.push(`I have enough of these for now: ${setListWords(rest.map((r) => `${shortName(r.name)} (${setMoney(r.each)} each)`))}. Same price if you want them gone: ${setMoney(offer.all.total)} for all.`);
        }
        if (others.length) out.push(`${setListWords(others.map((r) => r.name))} I do not buy.`);
        return out.join(' ');
    }

    const setPctText = (pct) => String(Math.round(setNum(pct) * 10) / 10);

    /** The pieces to name in the thread: the ones holding sets back, a few of each set. */
    function mostWanted(stocks, perSet = 3) {
        return stocks.map((st) => st.pieces.filter((p) => p.need > 0).sort((a, b) => a.rank - b.rank).slice(0, perSet).map((p) => shortName(p.name)).join(', ')).filter(Boolean).join(' · ');
    }

    /** Title and post for your buying thread. Written for you to copy: Torn Archive never posts. */
    function forumText({ open, pct, stocks = [], sets = SETS }) {
        const what = sets.length === 1 ? (sets[0].key === 'plushie' ? 'Plushies' : 'Flowers') : 'Plushies & Flowers';
        const every = sets.length === 1 ? (sets[0].key === 'plushie' ? 'plushie' : 'flower') : 'plushie and flower';
        if (!open) {
            return {
                title: `[CLOSED] Buying ${what} · back soon`,
                post: `Closed for now: not buying until this thread says OPEN again.\nWhen I am open I pay ${setPctText(pct)}% of market value for every ${every}.`,
            };
        }
        const wanted = mostWanted(stocks);
        return {
            title: `[OPEN] Buying ${what} · ${setPctText(pct)}% of market value`,
            post: [
                `Buying every ${every}, any amount.`,
                `I pay ${setPctText(pct)}% of market value, paid in the trade.`,
                wanted ? `Most wanted now: ${wanted}.` : '',
                'Start a trade with me and add your items. I answer with the total.',
            ].filter(Boolean).join('\n'),
        };
    }

    /** What a thread's title says: open or closed, and the rate, each null when the title does not say. */
    function readThreadTitle(title) {
        const t = String(title || '');
        const open = /\bclosed\b/i.test(t) ? false : /\bopen\b/i.test(t) ? true : null;
        const m = t.match(/(\d{2,3}(?:\.\d+)?)\s*%/);
        return { open, pct: m ? Number(m[1]) : null };
    }

    /** A thread you started that reads like a buying thread for sets. */
    const isBuyingTitle = (title) => /\b(open|closed)\b/i.test(String(title || '')) && /plush|flower/i.test(String(title || ''));

    /**
     * Does your thread still say what Torn Archive says?
     * @param paid [{ label, pct }] what you really pay each set today (core/sellrate.js), when it is known
     * @returns { state: 'match' | 'open' | 'closed' | 'rate' | 'under', says: { open, pct }, paid }
     *   'open' = Torn Archive is open and the title says closed; 'closed' = the other way; 'rate' = the rate moved;
     *   'under' = the title names your rate - the most you pay - and today you pay less, to keep your least profit.
     */
    function threadCheck(title, { open, pct, paid = [] }) {
        const says = readThreadTitle(title);
        const rows = (paid || []).filter((r) => r && r.pct > 0);
        let state = 'match';
        if (says.open !== null && says.open !== !!open) state = open ? 'open' : 'closed';
        else if (open && says.pct !== null && Math.abs(says.pct - setNum(pct)) > 0.049) state = 'rate';
        else if (open && says.pct !== null && rows.some((r) => says.pct - setNum(r.pct) > 0.049)) state = 'under';
        return { state, says, paid: rows };
    }

    /**
     * How much of your money sits in sets and points, as a share.
     * @returns { inSets, total, share } - share is 0..100
     */
    function moneyShare({ pieces = 0, points = 0, cash = 0, vault = 0 }) {
        const inSets = setWhole(pieces) + setWhole(points);
        const total = inSets + setWhole(cash) + setWhole(vault);
        return { inSets, total, share: total ? inSets / total * 100 : 0 };
    }

    /* ===== src/core/books.js ===== */
    // The books: what pieces cost, the points book at its average cost, buy-mugs, and the only profit there is.
    // A piece is never sold: it becomes a set, the set becomes points. So what you pay for pieces goes into a pool, a
    // set swapped at the museum puts its points into the book at what its pieces cost, and a points sale takes them out
    // at the book's average. Profit = what the points sold for, less that cost, less buy-mugs. Pure working-out.

    const bkNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const bkWhole = (v) => Math.max(0, Math.floor(bkNum(v)));
    const BK_DAY_MS = 86400000;

    // ---- What the pieces cost --------------------------------------------------------------------------------------------

    /**
     * Units into the pool at what was paid for them. The pool is { itemId: { n, cost, est } }: `est` counts the units
     * whose cost was not seen (held before Torn Archive) and stand at the market value of the day they were counted.
     */
    function poolAdd(pool, itemId, units, paid, est = false) {
        const n = bkWhole(units);
        if (!n) return pool || {};
        const id = String(itemId);
        const cur = (pool && pool[id]) || { n: 0, cost: 0, est: 0 };
        return { ...(pool || {}), [id]: { n: cur.n + n, cost: cur.cost + Math.max(0, bkNum(paid)), est: cur.est + (est ? n : 0) } };
    }

    /**
     * Units out of the pool at its average.
     * @returns { pool, cost, units, est } - units may be fewer than asked; est: how much of that cost rests on an
     *   estimate, as a share (0 to 1): the average is of every unit in the pool, the estimated ones with the rest
     */
    function poolTake(pool, itemId, units) {
        const id = String(itemId);
        const cur = pool && pool[id];
        const n = Math.min(bkWhole(units), cur ? cur.n : 0);
        if (!n) return { pool: pool || {}, cost: 0, units: 0, est: 0 };
        const cost = cur.cost * n / cur.n;
        const left = cur.n - n;
        const next = { ...pool };
        if (left) next[id] = { n: left, cost: cur.cost - cost, est: Math.min(cur.est, left) };
        else delete next[id];
        return { pool: next, cost, units: n, est: cur.n ? Math.min(1, cur.est / cur.n) : 0 };
    }

    /** The pool brought to what you hold: units with no cost on record come in at `eachOf(id)`, units gone leave at the average. */
    function poolMatch(pool, heldOf, eachOf, ids) {
        let out = pool || {};
        for (const id of ids || []) {
            const have = bkWhole(heldOf(id));
            const cur = out[String(id)] ? out[String(id)].n : 0;
            if (have > cur) out = poolAdd(out, id, have - cur, (have - cur) * bkNum(eachOf(id)), true);
            else if (have < cur) out = poolTake(out, id, cur - have).pool;
        }
        return out;
    }

    const poolEach = (pool, itemId) => { const c = pool && pool[String(itemId)]; return c && c.n ? c.cost / c.n : 0; };

    /** Everything in the pool: { units, cost, est }. */
    function poolSum(pool) {
        let units = 0;
        let cost = 0;
        let est = 0;
        for (const c of Object.values(pool || {})) { units += c.n; cost += c.cost; est += c.est; }
        return { units, cost: Math.round(cost), est };
    }

    /** What one set costs you now: each piece at its average in the pool. 0 while a piece has no cost on record. */
    function poolSetCost(pool, set) {
        let cost = 0;
        for (const p of set.pieces) {
            const each = poolEach(pool, p.id);
            if (!each) return 0;
            cost += each;
        }
        return Math.round(cost);
    }

    /**
     * Sets swapped at the museum: one of each piece leaves the pool, per set.
     * @returns { pool, cost, sets } - `sets` is how many the pool could give (it may hold fewer than Torn says)
     */
    function poolSwap(pool, set, sets) {
        let out = pool || {};
        let cost = 0;
        const n = Math.min(bkWhole(sets), ...set.pieces.map((p) => (out[String(p.id)] ? out[String(p.id)].n : 0)));
        if (!n) return { pool: out, cost: 0, sets: 0 };
        for (const p of set.pieces) {
            const took = poolTake(out, p.id, n);
            out = took.pool;
            cost += took.cost;
        }
        return { pool: out, cost: Math.round(cost), sets: n };
    }

    // ---- The points book, at its average ---------------------------------------------------------------------------------

    /**
     * The book worked out. Entries are points.js's: { id, t, kind: 'made' | 'sold' | 'used', points, each }.
     *   made: `each` = what a point cost you;  sold: the price it went for;  used: not a price, the points leave at cost.
     * Points sold or used beyond what the book holds were yours before: they count for nothing here.
     * @param before { points, each } the points you had before, if you typed a cost for them: they open the book
     * @returns { rows (newest first: + mine, cost (the average then), gain), made, madeCost, sold, soldGot, soldCost,
     *            used, usedCost, left, cost, each, least, profitSold, value }
     */
    /** Profit is "about" when at least this share of the cost behind it is an estimate (one dollar in a hundred). */
    const BOOK_ABOUT = 0.01;

    function avgBook(entries, priceNow = 0, before = null) {
        let left = bkWhole(before && before.points) && bkNum(before.each) > 0 ? bkWhole(before.points) : 0;
        let cost = left * bkNum(before && before.each);
        // Dollars of `cost` that rest on an estimate (pieces never seen bought): they leave with the points, share for share.
        let est = 0;
        const rows = [];
        const sum = { made: 0, madeCost: 0, sold: 0, soldGot: 0, soldCost: 0, used: 0, usedCost: 0, profitSold: 0, about: false };
        for (const e of [...(entries || [])].sort((a, b) => a.t - b.t)) {
            const points = bkWhole(e.points);
            if (!points) continue;
            if (e.kind === 'made') {
                left += points;
                cost += points * bkNum(e.each);
                est += points * bkNum(e.each) * Math.min(1, Math.max(0, bkNum(e.est)));
                sum.made += points;
                sum.madeCost += points * bkNum(e.each);
                rows.push({ ...e, mine: points, cost: bkNum(e.each), gain: 0 });
                continue;
            }
            const avg = left ? cost / left : 0;
            const mine = Math.min(points, left);
            const out = mine * avg;
            const share = cost > 0 ? Math.min(1, est / cost) : 0;
            left -= mine;
            cost = left ? cost - out : 0;
            est = left ? Math.max(0, est - out * share) : 0;
            if (e.kind === 'sold') {
                const got = mine * bkNum(e.each);
                sum.sold += mine;
                sum.soldGot += got;
                sum.soldCost += out;
                sum.profitSold += got - out;
                if (share >= BOOK_ABOUT && mine > 0) sum.about = true;
                rows.push({ ...e, mine, cost: avg, gain: Math.round(got - out), est: share });
            } else {
                sum.used += mine;
                sum.usedCost += out;
                rows.push({ ...e, mine, cost: avg, gain: 0 });
            }
        }
        const each = left ? cost / left : 0;
        return {
            rows: rows.reverse(),
            made: sum.made, madeCost: Math.round(sum.madeCost),
            sold: sum.sold, soldGot: Math.round(sum.soldGot), soldCost: Math.round(sum.soldCost),
            used: sum.used, usedCost: Math.round(sum.usedCost),
            left, cost: Math.round(cost), each,
            // est: the share of what is left that rests on an estimate; about: a sale's profit did.
            est: cost > 0 ? Math.min(1, est / cost) : 0, about: sum.about,
            // The lowest whole price a point may sell for and not be a loss.
            least: left ? Math.floor(each) + 1 : 0,
            profitSold: Math.round(sum.profitSold),
            value: left * bkWhole(priceNow),
        };
    }

    /** Points held from sets, at the end of each of the last `days` days: [{ day, left }]. */
    function heldByDay(entries, now, days = 14) {
        const list = [...(entries || [])].sort((a, b) => a.t - b.t);
        const out = [];
        for (let i = days - 1; i >= 0; i--) {
            const end = bkDayStart(now - i * BK_DAY_MS) + BK_DAY_MS;
            out.push({ day: bkDay(end - 1), left: avgBook(list.filter((e) => e.t < end)).left });
        }
        return out;
    }

    // ---- Buy-mugs --------------------------------------------------------------------------------------------------------

    /**
     * Which mugs took points money. Money from a points sale is "on hand" until it is banked or spent; a mug counts
     * against profit for as much of what it took as was such money. Any other mug is listed and left out.
     * @param sales [{ id, t, got }]            points sales, what each put on hand
     * @param mugs  [{ id, t, by, taken }]
     * @param outs  [{ t, amount }]             money that left your hand: a vault or bank deposit, a buy, a trade paid
     * @param from  the money that left your hand is on record only from this time on (older rows are let go): a sale
     *              before it is taken as banked or spent long since - with no row left to say so it would otherwise
     *              stand "on hand" for good, and the next mug, any mug, would count against it
     * A mug that carries `kept` ({ counted, onHand, saleId, after }) was judged while every row around it was on record:
     * that judgement stands.
     * @returns { rows (newest first: + counted, onHand, saleId, after), counted, left }
     */
    function mugCheck(sales, mugs, outs, from = 0) {
        const ev = [
            ...(sales || []).filter((s) => !(from > 0 && bkNum(s.t) < from)).map((s) => ({ t: bkNum(s.t), k: 0, s })),
            ...(outs || []).map((o) => ({ t: bkNum(o.t), k: 1, o })),
            ...(mugs || []).map((m) => ({ t: bkNum(m.t), k: 2, m })),
        ].sort((a, b) => a.t - b.t || a.k - b.k);
        let onHand = 0;
        let last = null;
        const rows = [];
        for (const e of ev) {
            if (e.k === 0) { onHand += Math.max(0, bkNum(e.s.got)); last = e.s; }
            else if (e.k === 1) { onHand = Math.max(0, onHand - Math.max(0, bkNum(e.o.amount))); if (!onHand) last = null; }
            else if (e.m.kept) {
                const taken = Math.max(0, bkNum(e.m.taken));
                const k = e.m.kept;
                rows.push({ ...e.m, taken, counted: Math.min(taken, Math.max(0, bkNum(k.counted))), onHand: bkNum(k.onHand), saleId: k.saleId || null, after: bkNum(k.after) });
                onHand = Math.max(0, onHand - Math.max(0, bkNum(k.counted)));
                if (!onHand) last = null;
            } else {
                const taken = Math.max(0, bkNum(e.m.taken));
                const counted = Math.min(taken, onHand);
                rows.push({ ...e.m, taken, counted, onHand, saleId: counted && last ? last.id : null, after: counted && last ? e.t - last.t : 0 });
                onHand -= counted;
                if (!onHand) last = null;
            }
        }
        return {
            rows: rows.reverse(),
            counted: rows.reduce((s, r) => s + r.counted, 0),
            left: rows.filter((r) => !r.counted).length,
        };
    }

    // ---- Profit ----------------------------------------------------------------------------------------------------------

    const bkDayStart = (t) => Math.floor(t / BK_DAY_MS) * BK_DAY_MS;
    const bkDay = (t) => new Date(t).toISOString().slice(0, 10);
    // Weeks run Monday to Sunday, Torn's time (UTC). 1 Jan 1970 was a Thursday.
    const bkWeekStart = (t) => bkDayStart(t) - ((Math.floor(t / BK_DAY_MS) + 3) % 7) * BK_DAY_MS;
    const bkMonthStart = (t) => { const d = new Date(t); return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1); };
    const BK_START = { day: bkDayStart, week: bkWeekStart, month: bkMonthStart };
    const bkBack = (start, unit) => (unit === 'month' ? bkMonthStart(start - 1) : start - (unit === 'week' ? 7 : 1) * BK_DAY_MS);

    /**
     * Profit in buckets of Torn's time, oldest first, the one holding `now` last. Empty buckets are there, at 0.
     * @param soldRows avgBook().rows (only 'sold' rows count)
     * @param mugRows  mugCheck().rows
     * @param directRows (optional) pieces sold as themselves: [{ t, gain, est }] (state.js books them)
     * @returns [{ start, day, sold, mug, direct, profit, points, got, about }] - mug is 0 or negative; about: a part of
     *   the profit rests on an estimated cost
     */
    function profitBuckets(soldRows, mugRows, now, unit = 'day', n = 14, directRows = null) {
        const startOf = BK_START[unit] || bkDayStart;
        const out = [];
        let start = startOf(now);
        for (let i = 0; i < n; i++) { out.unshift({ start, day: bkDay(start), sold: 0, mug: 0, direct: 0, profit: 0, points: 0, got: 0, about: false }); start = bkBack(start, unit); }
        const at = new Map(out.map((b) => [b.start, b]));
        for (const r of soldRows || []) {
            const b = r.kind === 'sold' ? at.get(startOf(r.t)) : null;
            if (!b) continue;
            b.sold += r.gain;
            b.points += r.mine;
            b.got += Math.round(r.mine * bkNum(r.each));
            if (bkNum(r.est) >= BOOK_ABOUT && r.mine > 0) b.about = true;
        }
        for (const d of directRows || []) {
            const b = at.get(startOf(d.t));
            if (!b) continue;
            b.direct += Math.round(bkNum(d.gain));
            if (bkNum(d.est) >= BOOK_ABOUT) b.about = true;
        }
        for (const m of mugRows || []) {
            const b = m.counted ? at.get(startOf(m.t)) : null;
            if (b) b.mug -= m.counted;
        }
        for (const b of out) b.profit = b.sold + b.mug + b.direct;
        return out;
    }

    /** The buckets summed: { sold, mug, direct, profit, points, got, cost, about }. */
    function profitSum(buckets) {
        const s = { sold: 0, mug: 0, direct: 0, profit: 0, points: 0, got: 0 };
        for (const b of buckets || []) for (const k of Object.keys(s)) s[k] += b[k] || 0;
        return { ...s, cost: s.got - s.sold, about: (buckets || []).some((b) => b.about) };
    }

    /** A running total over the buckets: [n, n, ...]. */
    function runningTotal(buckets) {
        let t = 0;
        return (buckets || []).map((b) => (t += b.profit));
    }

    /* ===== src/core/stock.js ===== */
    // What you hold of each piece, kept right between Torn's inventory reads, and what those units cost.
    // Torn counts your inventory once an hour for each category (its API's own words: "cached selection, 1 hour per
    // category"), so the count is carried by what happened: a buy in Torn's log, a buy seen on the page, a trade
    // finished, a set swapped at the museum. Torn's own count is taken for a piece when Torn counted AFTER the last
    // thing that happened to it: its answer says when it counted. (Until that time has been seen to stand still
    // between two reads it is not trusted, and the older rule holds: nothing happened to the piece in the hour before
    // the read.) A buy seen on the page counts at once; with your log read it leaves again when the log has been read
    // past it (the log has it then), without one it is counted itself. Pure working-out.




    const skNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const skWhole = (v) => Math.max(0, Math.floor(skNum(v)));
    // Torn says its inventory may be an hour old; five minutes on top for clocks and a slow read.
    const SK_STALE_MS = 65 * 60000;
    // A buy seen on the page stays counted until the log has been read this far past it: Torn's log may lag.
    const SK_LAG_MS = 60000;
    const SK_KEYS = 6000;
    /** Torn counts your inventory anew this long after it last did. */
    const SK_TORN_EVERY_MS = 60 * 60000;
    // Torn's count is taken for a piece when Torn counted this long after the last thing we saw happen to it: a buy
    // seen on the page is timed by this PC's clock, Torn's count by Torn's.
    const SK_CLOCKS_MS = 2 * 60000;
    // The time in Torn's answer is when Torn counted once two reads this far apart carried the same one.
    const SK_SAME_STAMP_MS = 60000;

    const STOCK_EMPTY = Object.freeze({ held: {}, last: {}, pool: {}, done: [], floor: 0, invAt: 0 });

    /**
     * What happened, applied once each (by key).
     * @param events [{ key, t, id, d, paid }]            units of one item in (d > 0, `paid` for all of them) or out (d < 0)
     *            or [{ key, t, swap: setKey, sets }]      sets swapped at the museum
     * @param eachOf id -> what a unit with no cost on record stands at (Torn's market value)
     * @returns { state, made: [{ key, t, set, sets, points, cost, est }], out: [{ key, t, id, units, cost, est }] }
     *   made = the swaps, with what their pieces cost; out = units that left as themselves, with what they had cost
     */
    function stockApply(state, events, eachOf = () => 0) {
        const s = state && state.held ? state : STOCK_EMPTY;
        const done = new Set(s.done);
        let held = s.held;
        let last = s.last;
        let pool = s.pool;
        const made = [];
        const out = [];
        const fresh = [];
        const base = s.base || {};
        const move = (id, d, t) => {
            // Torn counted this piece after it happened: its count had it already.
            if (t <= skNum(base[id])) return;
            held = { ...held, [id]: Math.max(0, skWhole(held[id]) + d) };
            if (t > skNum(last[id])) last = { ...last, [id]: t };
        };
        for (const e of [...(events || [])].sort((a, b) => a.t - b.t)) {
            if (!e || !e.key || done.has(e.key) || !(e.t > s.floor)) continue;
            done.add(e.key);
            fresh.push(e.key);
            if (e.swap) {
                const set = setByKey(e.swap);
                const n = skWhole(e.sets);
                if (!set || !n) continue;
                let cost = 0;
                let est = 0;
                for (const p of set.pieces) {
                    const id = String(p.id);
                    // Units the pool never saw bought stand at the market value: a set's cost is never left at nothing.
                    const have = pool[id] ? pool[id].n : 0;
                    if (have < n) pool = poolAdd(pool, id, n - have, (n - have) * skNum(eachOf(id)), true);
                    const took = poolTake(pool, id, n);
                    pool = took.pool;
                    cost += took.cost;
                    est += took.cost * took.est;
                    move(id, -n, e.t);
                }
                // `est`: the share of that cost that rests on an estimate (units never seen bought).
                made.push({ key: e.key, t: e.t, set: set.key, sets: n, points: n * set.points, cost: Math.round(cost), est: cost > 0 ? Math.round(est / cost * 1000) / 1000 : 0 });
                continue;
            }
            const id = String(e.id);
            const d = Math.trunc(skNum(e.d));
            if (!d) continue;
            if (d > 0) pool = poolAdd(pool, id, d, Math.max(0, skNum(e.paid)));
            else {
                // Units that left as themselves (sold or given away): what they cost you goes with them (state.js books it).
                const took = poolTake(pool, id, -d);
                pool = took.pool;
                out.push({ key: e.key, t: e.t, id, units: took.units, cost: Math.round(took.cost), est: took.est });
            }
            move(id, d, e.t);
        }
        if (!fresh.length) return { state: s, made, out };
        // The keys kept are the newest; the engine hands in only rows it has not handed in before, and `floor` (set
        // when the books are started over) shuts out everything older.
        const list = [...s.done, ...fresh].slice(-SK_KEYS);
        return { state: { ...s, held, last, pool, done: list }, made, out };
    }

    /**
     * Torn's inventory, read just now. A piece nothing happened to in the last hour takes Torn's count; the pool is
     * brought to it (units never seen bought come in at the market value, units gone leave at the average).
     * @param inv  itemId -> how many, or a function
     * @param ids  the pieces to keep count of
     * @param tornAt the time in Torn's answer, when it has one (ms)
     */
    function stockInventory(state, inv, invAt, ids, eachOf = () => 0, tornAt = 0) {
        const s = state && state.held ? state : STOCK_EMPTY;
        const get = typeof inv === 'function' ? inv : (id) => (inv || {})[id];
        const held = { ...s.held };
        const stamp = skNum(tornAt);
        // A time that only ever said "now" would move with every read: one that stood still is when Torn counted.
        const stampOk = !!s.stampOk || (stamp > 0 && stamp === skNum(s.tornAt) && invAt - skNum(s.invAt) >= SK_SAME_STAMP_MS);
        const at = stampOk ? stamp : 0;
        const base = { ...(s.base || {}) };
        for (const raw of ids || []) {
            const id = String(raw);
            const last = skNum(s.last[id]);
            const newer = at ? at > last + SK_CLOCKS_MS : last <= invAt - SK_STALE_MS;
            // With no time from Torn to trust, its count is still no more than an hour old: what happened before that
            // is in it, and is not added again when it is learned of later (a trade finished while the hub was closed).
            const floor = Math.max(skNum(base[id]), invAt - SK_STALE_MS);
            if (!newer) { if (held[id] == null) { held[id] = skWhole(get(id)); if (!at) base[id] = floor; } continue; }
            held[id] = skWhole(get(id));
            base[id] = at || floor;
        }
        const pool = poolMatch(s.pool, (id) => held[String(id)], eachOf, (ids || []).map(String));
        return { ...s, held, pool, base, invAt, tornAt: stamp, stampOk };
    }

    /**
     * How old the count is, for the screen and for when to ask Torn again.
     * @returns { readAt, tornAt, nextAt, since } - tornAt: when Torn counted (0 = not known); nextAt: when Torn counts
     *   anew (0 = not known); since: pieces something happened to after Torn counted (their count is carried by us)
     */
    function stockAge(state) {
        const s = state && state.held ? state : STOCK_EMPTY;
        const tornAt = s.stampOk ? skNum(s.tornAt) : 0;
        const from = tornAt || skNum(s.invAt) - SK_TORN_EVERY_MS;
        const since = Object.values(s.last || {}).filter((t) => skNum(t) > from).length;
        return { readAt: skNum(s.invAt), tornAt, nextAt: tornAt ? tornAt + SK_TORN_EVERY_MS : 0, since };
    }

    /**
     * How many you hold now: the count, plus buys and swaps seen on the page that the log has not been read past.
     * @param seen  [{ t, id, qty }] bazaar buys seen as they happened
     * @param swaps [{ t, set, sets }] presses of EXCHANGE
     * @param until the time the log has been read up to (0 = not read)
     * @returns itemId -> units (a function)
     */
    function stockHeld(state, seen, swaps, until = 0) {
        const s = state && state.held ? state : STOCK_EMPTY;
        const extra = {};
        const add = (id, d) => { extra[id] = (extra[id] || 0) + d; };
        // Torn counted the piece after it happened (by more than two clocks can differ): its count has it already.
        const base = s.base || {};
        const inCount = (id, t) => t + SK_CLOCKS_MS <= skNum(base[String(id)]);
        for (const b of seenWaiting(seen, until)) if (!inCount(b.id, b.t)) add(String(b.id), skWhole(b.qty));
        for (const p of seenWaiting(swaps, until)) {
            const set = setByKey(p.set);
            if (set) for (const pc of set.pieces) if (!inCount(pc.id, p.t)) add(String(pc.id), -skWhole(p.sets));
        }
        return (id) => Math.max(0, skWhole(s.held[String(id)]) + (extra[String(id)] || 0));
    }

    /** What was seen on the page and is not in the log yet. With `until` 0 the log is not read: everything waits. */
    function seenWaiting(list, until = 0) {
        // `counted`: already in the count itself (stockApply), with no log to wait for.
        // `logged`: its row in Torn's log is in the count - the same buy, not a second one.
        // `no`: Torn's log, read past it, has no such buy: it was not one (state.js judgeSeen).
        return (list || []).filter((x) => x && x.t > 0 && !x.counted && !x.logged && !x.no && !(until > 0 && x.t + SK_LAG_MS < until));
    }

    /** A buy seen on the page as a stock event, for when no log is read: [{ key, t, id, d, paid }]. */
    function eventFromSeen(buy) {
        const qty = skWhole(buy && buy.qty);
        if (!buy || !qty || !(buy.t > 0)) return [];
        return [{ key: 'seen:' + buy.t + ':' + buy.id + ':' + (buy.whoId || ''), t: buy.t, id: String(buy.id), d: qty, paid: qty * skWhole(buy.price) }];
    }

    /** Is the count fit to show? Not before Torn's inventory has been read once. */
    const stockReady = (state) => !!state && state.invAt > 0;

    /**
     * The Ledger's rows (core/ledger.js) and museum swaps as stock events.
     * @param rows  [{ id, t, itemId, qty, each, side }] buys, sales, gifts - of any item; only `ids` are counted
     * @param ids   Set of the pieces' ids (strings)
     */
    function eventsFromRows(rows, ids) {
        const out = [];
        for (const r of rows || []) {
            if (!r || !ids.has(String(r.itemId)) || !(r.qty > 0)) continue;
            if (r.side === 'buy') out.push({ key: 'row:' + r.id, t: r.t, id: String(r.itemId), d: skWhole(r.qty), paid: skWhole(r.qty) * skNum(r.each) });
            else out.push({ key: 'row:' + r.id, t: r.t, id: String(r.itemId), d: -skWhole(r.qty), paid: 0 });
        }
        return out;
    }

    /* ===== src/core/points.js ===== */
    // Points: the points market's listings, the price to list at, the lot, what is usual, and the points book.
    // Pure working-out. The sets that make the points are in sets.js.

    const ptNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const ptWhole = (v) => Math.max(0, Math.floor(ptNum(v)));

    /** Torn's own ceiling for a points listing ("Maximum price each is $100,000"); a parsed price over it is not a price. */
    const POINT_PRICE_MAX = 100000;

    /**
     * Torn's /v2/market/pointsmarket (or v1 market/?selections=pointsmarket): { pointsmarket: { id: { cost, quantity } } }.
     * @returns [{ id, cost, qty }] cheapest first
     */
    function parsePointsMarket(json) {
        const raw = json && (json.pointsmarket || json.pointsMarket || json.listings);
        if (!raw || typeof raw !== 'object') return [];
        const rows = Array.isArray(raw) ? raw.map((r, i) => [r && (r.id ?? i), r]) : Object.entries(raw);
        const out = [];
        for (const [id, r] of rows) {
            if (!r) continue;
            const cost = ptWhole(r.cost ?? r.price ?? r.cost_each);
            const qty = ptWhole(r.quantity ?? r.amount ?? r.points);
            if (cost > 0 && cost <= POINT_PRICE_MAX && qty > 0) out.push({ id: String(id), cost, qty });
        }
        return out.sort((a, b) => a.cost - b.cost || (a.id < b.id ? -1 : 1));
    }

    /** Listings folded by price: [{ price, qty, lots }] cheapest first. */
    function priceLevels(listings) {
        const by = new Map();
        for (const l of listings || []) {
            const lv = by.get(l.cost) || { price: l.cost, qty: 0, lots: 0 };
            lv.qty += l.qty;
            lv.lots += 1;
            by.set(l.cost, lv);
        }
        return [...by.values()].sort((a, b) => a.price - b.price);
    }

    /**
     * The first wall: the first price level, from the bottom of the book, that holds several times more points than
     * everything listed cheaper than it together. A few cheap points sit under it; the bulk of the market starts there,
     * and a lot priced just under it sells before the wall does. Null when no level stands out (the book fills evenly),
     * or the cheapest level is itself the bulk.
     * No dollar figure and no point count in the rule: a level is "a wall" against the points under it in the same book.
     */
    const WALL_TIMES = 3;

    function firstWall(levels, { depth = 12, times = WALL_TIMES } = {}) {
        const near = (levels || []).slice(0, depth);
        let ahead = 0;
        for (let i = 0; i < near.length; i++) {
            if (i > 0 && near[i].qty >= ahead * times) return { price: near[i].price, ahead, index: i };
            ahead += near[i].qty;
        }
        return null;
    }

    /**
     * The price to type for your points.
     * @param rule 'wall' = $1 under the first wall (the default); 'lowest' = $1 under the lowest listing
     * @returns null with no listings, else { price, ahead, rule, lowest, wall }; `ahead` = points listed at your price or cheaper
     */
    function listPrice(listings, rule = 'wall') {
        const levels = priceLevels(listings);
        if (!levels.length) return null;
        const lowest = levels[0].price;
        const wall = firstWall(levels);
        const useWall = rule !== 'lowest' && !!wall;
        const price = Math.max(1, (useWall ? wall.price : lowest) - 1);
        let ahead = 0;
        // At your price or under it: a listing already there at the same price sells before yours (as the box on the
        // points market counts it).
        for (const lv of levels) if (lv.price <= price) ahead += lv.qty;
        return { price, ahead, rule: useWall ? 'wall' : 'lowest', lowest, wall: wall ? wall.price : null };
    }

    /** Lots that were listed at the last read and are not now: sold or taken down, Torn does not say which. */
    function goneLots(prev, next, now) {
        const still = new Set((next || []).map((l) => l.id));
        return (prev || []).filter((l) => !still.has(l.id)).map((l) => ({ cost: l.cost, qty: l.qty, t: now }));
    }

    const PT_DAY_MS = 86400000;

    /**
     * In what lots to list. One lot, unless small lots are what has been leaving the market near your price.
     * @param gone lots seen leaving ({ cost, qty, t }), any age - only the last day near your price is counted
     * @returns { lots: [n, ...], size, seen: { count, lo, hi } | null, split: boolean }
     */
    function lotAdvice(points, gone, price, now = Date.now()) {
        const total = ptWhole(points);
        const near = (gone || []).filter((g) => now - ptNum(g.t) < PT_DAY_MS && g.qty > 0 && g.cost <= price * 1.01);
        const sizes = near.map((g) => g.qty).sort((a, b) => a - b);
        const seen = sizes.length ? { count: sizes.length, lo: sizes[0], hi: sizes[sizes.length - 1] } : null;
        const one = { lots: total ? [total] : [], size: total, seen, split: false };
        if (sizes.length < 5 || !total) return one;
        const median = sizes[Math.floor((sizes.length - 1) / 2)];
        if (median * 2 > total) return one;
        const lots = [];
        for (let left = total; left > 0; left -= median) lots.push(Math.min(median, left));
        return { lots, size: median, seen, split: true };
    }

    const ptDayOf = (t) => new Date(t).toISOString().slice(0, 10);

    /** One read of the points price into the day's line. Kept: the last `keep` days. */
    function recordPrice(days, now, price, keep = 40) {
        const p = ptWhole(price);
        if (!p) return days || [];
        const day = ptDayOf(now);
        const out = (days || []).filter((d) => d && d.day !== day);
        const cur = (days || []).find((d) => d && d.day === day) || { day, n: 0, sum: 0, lo: p, hi: p };
        out.push({ day, n: cur.n + 1, sum: cur.sum + p, lo: Math.min(cur.lo, p), hi: Math.max(cur.hi, p) });
        return out.sort((a, b) => (a.day < b.day ? -1 : 1)).slice(-keep);
    }

    /** Days of its own it takes before Torn Archive says what a usual points price is. */
    const USUAL_DAYS = 5;

    /**
     * The usual level of the points price: the range of the daily averages of the last month, today left out.
     * @returns { lo, hi, days } or { days } while there are too few days to say
     */
    function usualLevel(days, now = Date.now(), window = 30) {
        const today = ptDayOf(now);
        const from = ptDayOf(now - window * PT_DAY_MS);
        const avgs = (days || []).filter((d) => d && d.day < today && d.day >= from && d.n > 0).map((d) => Math.round(d.sum / d.n));
        if (avgs.length < USUAL_DAYS) return { days: avgs.length };
        return { lo: Math.min(...avgs), hi: Math.max(...avgs), days: avgs.length };
    }

    /** Cheap = under the whole usual range. A price against its own level, never a dollar cut-off. */
    const pointsCheap = (price, level) => !!(level && level.lo && ptWhole(price) > 0 && ptWhole(price) < level.lo);

    // ---- The points book ---------------------------------------------------------------------------------------------

    const PT_MERGE_MS = 5 * 60000;

    /**
     * Add one entry: { id, t, kind: 'made' | 'sold' | 'used', points, each, set, src }.
     *   made: `each` = what one point cost you (the set's cost / its points);  sold: the price a point went for;
     *   used: what a point cost on the market that moment.
     * The same id is never added twice. A 'made' entry read from Torn's log takes the place of the one Torn Archive wrote
     * when you pressed EXCHANGE (same points, within five minutes), keeping the cost worked out at the press.
     */
    function bookAdd(entries, entry) {
        const list = entries || [];
        const points = ptWhole(entry && entry.points);
        if (!entry || !points || !entry.id) return list;
        if (list.some((e) => e.id === entry.id)) return list;
        // `est` (made): the share of the cost that rests on an estimate, where it was worked out (stock.js stockApply).
        const e = { id: String(entry.id), t: ptNum(entry.t), kind: entry.kind, points, each: ptNum(entry.each), set: entry.set || null, src: entry.src || 'log', ...(entry.est != null ? { est: ptNum(entry.est) } : {}) };
        if (e.kind === 'made') {
            const other = e.src === 'log' ? 'page' : 'log';
            const twin = list.find((x) => x.kind === 'made' && x.src === other && x.points === points && Math.abs(x.t - e.t) < PT_MERGE_MS && !x.twin);
            if (twin) {
                // One exchange, seen twice: keep the log's id (so it is not added again) and the page's cost.
                const page = e.src === 'page' ? e : twin;
                const log = e.src === 'log' ? e : twin;
                const est = log.est != null ? log.est : page.est;
                const merged = { ...log, each: page.each || log.each, set: page.set || log.set, twin: page.id, ...(est != null ? { est } : {}) };
                return list.map((x) => (x === twin ? merged : x)).sort((a, b) => a.t - b.t);
            }
        }
        return [...list, e].sort((a, b) => a.t - b.t);
    }

    /**
     * The book, worked out: points made carry their cost; sold and used points come off the oldest made first.
     * Points sold or used beyond what was made were yours before (no cost on record): they count for nothing here.
     * @returns { rows, made, sold, used, left, cost, each, least, profitSold, saved, value }
     */
    function bookState(entries, priceNow = 0) {
        const lots = [];
        const rows = [];
        let made = 0;
        let madeCost = 0;
        let sold = 0;
        let used = 0;
        let profitSold = 0;
        let saved = 0;
        for (const e of [...(entries || [])].sort((a, b) => a.t - b.t)) {
            if (e.kind === 'made') {
                lots.push({ left: e.points, each: e.each });
                made += e.points;
                madeCost += e.points * e.each;
                rows.push({ ...e, mine: e.points, gain: 0 });
                continue;
            }
            let left = e.points;
            let cost = 0;
            let mine = 0;
            for (const lot of lots) {
                if (left <= 0) break;
                const take = Math.min(left, lot.left);
                lot.left -= take;
                left -= take;
                mine += take;
                cost += take * lot.each;
            }
            // Points used with no price on record (the market was not read): no saving is claimed, and no loss.
            const gain = e.each > 0 ? Math.round(mine * e.each - cost) : 0;
            if (e.kind === 'sold') { sold += mine; profitSold += gain; } else { used += mine; saved += gain; }
            rows.push({ ...e, mine, gain });
        }
        const leftLots = lots.filter((l) => l.left > 0);
        const left = leftLots.reduce((s, l) => s + l.left, 0);
        const cost = Math.round(leftLots.reduce((s, l) => s + l.left * l.each, 0));
        const each = left ? cost / left : 0;
        return {
            rows: rows.reverse(), made, madeCost: Math.round(madeCost), sold, used, left, cost, each,
            least: left ? Math.floor(each) + 1 : 0, profitSold, saved, value: left * ptWhole(priceNow),
        };
    }

    /**
     * A 'made' entry written at a press of EXCHANGE that Torn's log never showed (the press did not go through, or
     * the box was changed): it comes off once the log has been read past it. Only when the log can say - `until` is
     * the time the log has been read up to, and 0 (the log is not read) keeps everything.
     */
    function bookSettle(entries, until, wait = PT_MERGE_MS) {
        const list = entries || [];
        if (!(until > 0)) return list;
        const out = list.filter((e) => !(e.kind === 'made' && e.src === 'page' && !e.twin && e.t + wait < until));
        return out.length === list.length ? list : out;
    }

    // ---- Torn's log --------------------------------------------------------------------------------------------------

    /**
     * Which of Torn's log types are a museum exchange, a points sale and points used. Read from Torn's own list of
     * log types (torn/?selections=logtypes -> { logtypes: { id: title } }) by their titles, so no id is written here.
     */
    function pointsLogTypes(json) {
        const raw = json && (json.logtypes || json);
        const out = { made: [], sold: [], used: [], titles: {} };
        if (!raw || typeof raw !== 'object') return out;
        const rows = Array.isArray(raw) ? raw.map((r) => [r && r.id, r && r.title]) : Object.entries(raw);
        for (const [id, t] of rows) {
            const title = String((t && t.title) || t || '');
            if (!title || id == null) continue;
            let kind = null;
            if (/museum/i.test(title)) kind = 'made';
            else if (/points?\s*market/i.test(title) && /\b(sell|sold|sale)\b/i.test(title)) kind = 'sold';
            else if (/\bpoints?\b/i.test(title) && /\b(refill|use|used|spend|spent)\b/i.test(title) && !/market|faction|company|job/i.test(title)) kind = 'used';
            if (!kind) continue;
            out[kind].push(Number(id));
            out.titles[id] = title;
        }
        return out;
    }

    const ptPick = (data, keys) => {
        for (const k of keys) {
            const v = data && data[k];
            if (v != null && Number.isFinite(Number(v)) && Number(v) > 0) return Number(v);
        }
        return 0;
    };

    /**
     * One row of Torn's log as a points-book entry, or null when it cannot be read with certainty.
     * @param row  Torn's v2 row { id, timestamp, details: { id, title }, data } (v1's { log, title, ... } is read too)
     * @param types pointsLogTypes()
     * @param ctx  { costOf(setKey, sets) -> cost of one point, priceNow }
     */
    function entryFromLog(id, row, types, ctx = {}) {
        if (!row) return null;
        const details = row.details && typeof row.details === 'object' ? row.details : {};
        const type = Number(details.id ?? row.log);
        const kind = types.made.includes(type) ? 'made' : types.sold.includes(type) ? 'sold' : types.used.includes(type) ? 'used' : null;
        if (!kind) return null;
        const data = row.data || {};
        const t = ptNum(row.timestamp) * 1000;
        const text = (String(details.title || row.title || '') + ' ' + JSON.stringify(data)).toLowerCase();
        if (kind === 'made') {
            const points = ptWhole(ptPick(data, ['points', 'points_gained', 'points_received', 'points_increased']));
            if (!points) return null;
            const set = /plush/.test(text) ? 'plushie' : /flower/.test(text) ? 'flower' : null;
            return { id: 'log:' + id, t, kind, points, each: ctx.costOf ? ptNum(ctx.costOf(set, points)) : 0, set, src: 'log' };
        }
        if (kind === 'sold') {
            const points = ptWhole(ptPick(data, ['quantity', 'points', 'amount']));
            if (!points) return null;
            let each = ptPick(data, ['cost_each', 'price_each', 'price', 'each']);
            if (!each) {
                const total = ptPick(data, ['cost_total', 'total_cost', 'total', 'money_gained', 'value', 'cost']);
                each = total ? total / points : 0;
            }
            if (!(each > 0) || each > POINT_PRICE_MAX) return null;
            return { id: 'log:' + id, t, kind, points, each: Math.round(each), set: null, src: 'log' };
        }
        const points = ptWhole(ptPick(data, ['points', 'points_used', 'points_spent']));
        if (!points) return null;
        return { id: 'log:' + id, t, kind, points, each: ptWhole(ctx.priceNow), set: null, src: 'log' };
    }

    // ---- A listing as you type it on Torn's page (mockup Z7) -----------------------------------------------------------

    /**
     * One row of Torn's points list, from its words ("... 405 $30,893 $12,511,665"): the count, the price each and the
     * total. Null unless count x price is the total, so a row that is something else is never taken for a listing.
     */
    function parsePointsRow(text) {
        const s = String(text || '');
        const money = [...s.matchAll(/\$\s?(\d[\d,]*)/g)].map((m) => ({ n: Number(m[1].replace(/,/g, '')), at: m.index }));
        for (let k = 0; k + 1 < money.length; k += 1) {
            const each = money[k].n;
            const total = money[k + 1].n;
            if (!each || each > POINT_PRICE_MAX || total < each || total % each) continue;
            const points = total / each;
            const before = s.slice(0, money[k].at).replace(/\$\s?\d[\d,]*/g, ' ');
            if ([...before.matchAll(/\d[\d,]*/g)].some((m) => Number(m[0].replace(/,/g, '')) === points)) return { points, each, total };
        }
        return null;
    }

    /** The first row at or over `price`, when some rows are under it (else null: no line to draw). */
    const ptFirstAtOrOver = (rows, price) => {
        if (!price) return null;
        const i = rows.findIndex((r) => r.each >= price);
        return i > 0 ? i : null;
    };

    /**
     * The lines in a list of points, cheapest first: the rows above `lossAt` are under your least price, the rows above
     * `cheapAt` are under the usual level. Null where no row is under it, or every row is.
     */
    function listLines(rows, o = {}) {
        const list = rows || [];
        return { lossAt: ptFirstAtOrOver(list, ptWhole(o.least)), cheapAt: ptFirstAtOrOver(list, ptWhole(o.level && o.level.lo)) };
    }

    /**
     * A price typed into Torn's "Price each" box, against the list and against what your points cost.
     * @param rows [{ points, each }] the list, cheapest first
     * @param o { price, amount, least, level } - least: the least price that is a profit (0 = no cost on record)
     * @returns null with no price, else
     *   ahead   points listed at your price or under it: they sell before yours
     *   at      the row your listing would sit above (null and `past`: under every row here)
     *   state   'loss' | 'cheap' | 'good' | '' (no cost on record, and not cheap)
     *   by      dollars a point over (+) or under (-) what they cost you; null with no cost on record
     *   under   dollars under what it takes to be first ($1 under the lowest): given away on every point
     */
    function typedListing(rows, o = {}) {
        const price = ptWhole(o.price);
        if (!price || price > POINT_PRICE_MAX) return null;
        const list = rows || [];
        const amount = ptWhole(o.amount);
        let ahead = 0;
        let at = 0;
        while (at < list.length && list[at].each <= price) { ahead += list[at].points; at += 1; }
        const lowest = list.length ? list[0].each : 0;
        const least = ptWhole(o.least);
        const lo = ptWhole(o.level && o.level.lo);
        const state = least && price < least ? 'loss' : lo && price < lo ? 'cheap' : least ? 'good' : '';
        const under = lowest && price < lowest - 1 ? lowest - 1 - price : 0;
        return {
            price, amount, ahead, at: at < list.length ? at : null, past: list.length > 0 && at >= list.length, lowest, state,
            least, by: least ? price - (least - 1) : null, under, given: under * amount,
        };
    }

    /* ===== src/core/lots.js ===== */
    // Which lot size sells: the points market read again and again, a lot that was there and is gone.
    // A lot that leaves may have been taken down, Torn does not say; so your own sales (from Torn's log) are shown
    // beside it. Sizes are counted against sizes: no dollar figure in any rule here. Pure working-out.

    const ltNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const ltWhole = (v) => Math.max(0, Math.floor(ltNum(v)));
    const LT_DAY_MS = 86400000;
    // Two reads further apart than this did not watch the market between them: a lot gone meanwhile has no wait to tell.
    const LT_GAP_MS = 5 * 60000;
    const LT_KEEP = 4000;

    const LOT_BUCKETS = [[1, 100], [101, 250], [251, 500], [501, 1000], [1001, Infinity]];

    const ltFmt = (n) => n.toLocaleString('en-US');
    const lotLabel = ([lo, hi]) => (hi === Infinity ? 'Over ' + ltFmt(lo - 1) : lo <= 1 ? 'Up to ' + ltFmt(hi) : ltFmt(lo) + ' to ' + ltFmt(hi));
    const lotBucket = (points) => LOT_BUCKETS.findIndex(([lo, hi]) => points >= lo && points <= hi);

    const LOTS_EMPTY = Object.freeze({ seen: {}, gone: [], t: 0 });

    /**
     * One read of the points market into the record.
     * @param state     { seen: { id: { cost, qty, t0, old } }, gone: [{ cost, qty, t, wait, front, part }], t }
     * @param listings  points.js's parsePointsMarket(): [{ id, cost, qty }]
     * @param wallPrice the first wall's price at this read (0 = not known): a lot at or under it was at the front
     * @returns the next state. `wait` is null when the lot was there before the watch began, or the watch had a gap.
     */
    function lotsRead(state, listings, now, wallPrice = 0) {
        const prev = state && state.seen ? state : LOTS_EMPTY;
        const first = !prev.t;
        const gap = !first && now - prev.t > LT_GAP_MS;
        const seen = {};
        const gone = [];
        const here = new Map((listings || []).map((l) => [String(l.id), l]));
        const leave = (was, qty, part) => gone.push({
            cost: was.cost, qty, t: now, wait: was.old || gap ? null : now - was.t0,
            front: !(wallPrice > 0) || was.cost <= wallPrice, ...(part ? { part: true } : {}),
        });
        for (const [id, was] of Object.entries(prev.seen)) {
            const l = here.get(id);
            if (!l) { leave(was, was.qty, false); continue; }
            // Less of it than before: part of the lot sold. The rest stays, counted from when the lot was first seen.
            if (l.qty < was.qty) leave(was, was.qty - l.qty, true);
        }
        for (const [id, l] of here) {
            const was = prev.seen[id];
            seen[id] = was ? { ...was, cost: l.cost, qty: l.qty } : { cost: l.cost, qty: l.qty, t0: now, ...(first || gap ? { old: true } : {}) };
        }
        const keepFrom = now - 8 * LT_DAY_MS;
        return { seen, gone: [...prev.gone.filter((g) => g.t >= keepFrom), ...gone].slice(-LT_KEEP), t: now };
    }

    const ltMedian = (xs) => { const s = [...xs].sort((a, b) => a - b); return s.length ? s[Math.floor((s.length - 1) / 2)] : null; };

    /**
     * The table: per lot size, how many left the market, the points in them, the usual wait at the front, and yours.
     * @param gone lotsRead().gone
     * @param mine [{ points, wait }] your own lots, from Torn's log (wait in ms, or null)
     * @returns [{ lo, hi, label, lots, points, wait (ms | null), waits, mine: { n, lo, hi } | null }]
     */
    function lotTable(gone, mine, now, days = 7) {
        const from = now - days * LT_DAY_MS;
        const rows = LOT_BUCKETS.map((b) => ({ lo: b[0], hi: b[1], label: lotLabel(b), lots: 0, points: 0, wait: null, waits: 0, mine: null, w: [], m: [] }));
        for (const g of gone || []) {
            if (g.t < from) continue;
            const r = rows[lotBucket(ltWhole(g.qty))];
            if (!r) continue;
            r.lots += 1;
            r.points += ltWhole(g.qty);
            if (g.front && g.wait != null) r.w.push(g.wait);
        }
        for (const s of mine || []) {
            const r = rows[lotBucket(ltWhole(s.points))];
            if (r) r.m.push(s.wait);
        }
        return rows.map(({ w, m, ...r }) => {
            const known = m.filter((x) => x != null);
            return { ...r, wait: ltMedian(w), waits: w.length, mine: m.length ? { n: m.length, lo: known.length ? Math.min(...known) : null, hi: known.length ? Math.max(...known) : null } : null };
        });
    }

    /**
     * How to list your points: all at once, or in the size that leaves quickest. Lots of one size are taken one after
     * the other, so the wait of a split is the size's usual wait, once per lot.
     * @returns { one: { lots: [n], wait }, quick: { lots, size, wait } | null } - quick is null when one lot is quickest,
     *          or no wait is known yet
     */
    function sellPlan(points, table) {
        const total = ltWhole(points);
        const waitOf = (n) => { const r = (table || [])[lotBucket(n)]; return r ? r.wait : null; };
        const one = { lots: total ? [total] : [], wait: total ? waitOf(total) : null };
        let quick = null;
        for (const r of table || []) {
            if (r.wait == null || !total) continue;
            const size = Math.min(total, r.hi === Infinity ? total : r.hi);
            if (size >= total) continue;
            const lots = [];
            for (let left = total; left > 0; left -= size) lots.push(Math.min(size, left));
            const wait = lots.length * r.wait;
            if (!quick || wait < quick.wait) quick = { lots, size, wait };
        }
        if (quick && one.wait != null && one.wait <= quick.wait) quick = null;
        return { one, quick };
    }

    /** "4 lots of 100 and 1 of 20". */
    function lotsWords(lots) {
        const by = new Map();
        for (const n of lots || []) by.set(n, (by.get(n) || 0) + 1);
        const parts = [...by].sort((a, b) => b[0] - a[0]).map(([n, c], i) => (i ? c + ' of ' + ltFmt(n) : c + (c === 1 ? ' lot of ' : ' lots of ') + ltFmt(n)));
        return parts.join(' and ');
    }

    /** A wait in words: "6 min", "2 h 10 min", "under a minute". */
    function waitWords(ms) {
        if (ms == null) return '';
        const min = Math.round(ms / 60000);
        if (min < 1) return 'under a minute';
        if (min < 60) return min + ' min';
        const h = Math.floor(min / 60);
        return h + ' h' + (min % 60 ? ' ' + (min % 60) + ' min' : '');
    }

    /* ===== src/core/trades.js ===== */
    // The trades open with you: one row each, whose turn it is, and which of them is new.
    // Read from Torn's API (v2 user/trades and user/{id}/trade, a Limited key). Nothing is accepted or sent for you.
    // Pure working-out.

    const trNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const trWhole = (v) => Math.max(0, Math.floor(trNum(v)));

    /** Torn's list of trades: [{ id, who, whoId, modified, expires, completed, note }]. `myId` tells the two sides apart. */
    function parseTradeList(json, myId) {
        const rows = (json && json.trades) || [];
        const out = [];
        for (const t of Array.isArray(rows) ? rows : []) {
            if (!t || t.id == null) continue;
            const other = trOther(t, myId);
            out.push({
                id: String(t.id), who: other.name || '', whoId: other.id != null ? String(other.id) : '',
                modified: trNum(t.modified_at) * 1000, expires: trNum(t.expires_at) * 1000, completed: trNum(t.completed_at ?? t.timestamp) * 1000,
                note: String(t.description || ''),
            });
        }
        return out;
    }

    function trOther(t, myId) {
        const a = t.user || {};
        const b = t.trader || {};
        return String(a.id) === String(myId) ? b : String(b.id) === String(myId) ? a : b;
    }

    /**
     * One trade read in full: what they put in, what you put in.
     * @returns { id, who, whoId, modified, theirs: [{ id, qty }], theirMoney, mine: [{ id, qty }], myMoney, other } -
     *          `other` counts what is in it that is neither an item nor money (a property, a company...)
     */
    function parseTrade(json, myId) {
        const t = json && json.trade;
        if (!t || t.id == null) return null;
        const head = parseTradeList({ trades: [t] }, myId)[0];
        const out = { ...head, theirs: [], theirMoney: 0, mine: [], myMoney: 0, other: 0 };
        const add = (list, id, qty) => { const row = list.find((r) => r.id === id); if (row) row.qty += qty; else list.push({ id, qty }); };
        for (const it of Array.isArray(t.items) ? t.items : []) {
            if (!it || !it.details) continue;
            const me = String(it.user_id) === String(myId);
            if (it.type === 'Money') { if (me) out.myMoney += trWhole(it.details.amount); else out.theirMoney += trWhole(it.details.amount); }
            else if (it.type === 'Item') add(me ? out.mine : out.theirs, Number(it.details.id), trWhole(it.details.amount));
            else out.other += 1;
        }
        return out;
    }

    /**
     * Whose turn it is.
     *   'new'  they have put no set piece in yet
     *   'you'  pieces are in and your money is not (or not all of it)
     *   'them' your money covers it: nothing to do until they accept
     * @param total what the trade comes to at your prices (everything priced in it)
     */
    function tradeTurn(trade, total) {
        if (!trade || !(total > 0)) return 'new';
        return trade.myMoney >= total ? 'them' : 'you';
    }

    const TURN_WORDS = { you: 'your turn to pay', them: 'paid · waiting for them', new: 'new · still adding' };

    /**
     * Which trades are new since the last look. The first look ever tells of nothing: every trade is "seen".
     * @param seen  { ids: [..], began } the ids known, newest last
     * @param trades parseTradeList()
     * @returns { seen, fresh: [trade] }
     */
    function tradesSeen(seen, trades) {
        const known = new Set((seen && seen.ids) || []);
        const first = !(seen && seen.began);
        const fresh = first ? [] : (trades || []).filter((t) => !known.has(t.id));
        const ids = [...new Set([...known, ...(trades || []).map((t) => t.id)])].slice(-400);
        return { seen: { ids, began: true }, fresh };
    }

    /** A trade that was open at the last look and is not now: finished or cancelled, the finished list says which. */
    function tradesClosed(prevOpen, nowOpen) {
        const still = new Set((nowOpen || []).map((t) => t.id));
        return (prevOpen || []).filter((t) => !still.has(t.id));
    }

    /** "4 min ago", "just now", "2 h ago", "3 days ago". */
    function agoWords(t, now) {
        if (!(t > 0)) return '';
        const s = Math.max(0, Math.round((now - t) / 1000));
        if (s < 60) return 'just now';
        if (s < 3600) return Math.floor(s / 60) + ' min ago';
        if (s < 86400) return Math.floor(s / 3600) + ' h ago';
        const d = Math.floor(s / 86400);
        return d === 1 ? 'yesterday' : d + ' days ago';
    }

    /** The words of the notice for a new trade. */
    function tradeNotice(trade, items, total) {
        const n = trWhole(items);
        return {
            title: (trade.who || 'Someone') + ' opened a trade with you',
            body: n ? n + (n === 1 ? ' item' : ' items') + (total > 0 ? ' · $' + trWhole(total).toLocaleString('en-US') + ' at your prices' : '') : 'Nothing in it yet',
        };
    }

    /* ===== src/core/shopping.js ===== */
    // The shopping list and the buying run.
    // The list is what you decided to buy: one line per piece per place (a bazaar, or the Item Market). The run walks it
    // one place at a time; Next counts only what you took. Pure working-out on plain objects, so the list can be stored
    // and every tab shows the same one.

    const shNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const shWhole = (v) => Math.max(0, Math.floor(shNum(v)));

    /** The Item Market is one place; a bazaar is its owner. */
    const IM_PLACE = 'im';
    const placeOf = (offer) => (offer && offer.src === 'market' ? IM_PLACE : 'b:' + String(offer && (offer.whoId ?? offer.who ?? '')));
    const lineKey = (itemId, place) => String(itemId) + '|' + place;

    /** How many of a piece are on the list, over every place. */
    function onList(cart, itemId) {
        let n = 0;
        for (const l of cart || []) if (String(l.id) === String(itemId)) n += shWhole(l.q);
        return n;
    }

    const shLine = (piece, offer, q) => ({
        key: lineKey(piece.id, placeOf(offer)), id: piece.id, name: piece.name, set: piece.set || null, place: placeOf(offer),
        im: offer.src === 'market', who: offer.who || null, whoId: offer.whoId ?? null, price: shWhole(offer.price), q,
    });

    /**
     * "Fill my stock": the cheapest way to what you need, taking a unit only while its price is under the piece's
     * safe worth (what it brings less your least profit).
     * @param pieces   [{ id, name, set, need, worth }] - worth is the SAFE worth
     * @param offersOf id -> [{ price, qty, src, who, whoId }]
     */
    function fillPlan(pieces, offersOf) {
        const out = [];
        for (const p of pieces || []) {
            let left = shWhole(p.need);
            if (!left || !(p.worth > 0)) continue;
            const all = [...((offersOf && offersOf(p.id)) || [])].filter((o) => shWhole(o.price) > 0 && shWhole(o.qty) > 0).sort((a, b) => a.price - b.price);
            const seen = new Set();
            // The Item Market's rows, cheapest first with everything else: what falls to them is one line.
            let imQ = 0;
            let imCost = 0;
            let imRow = null;
            let imAt = 0;
            for (const o of all) {
                if (!left || o.price >= p.worth) break;
                const q = Math.min(left, shWhole(o.qty));
                if (placeOf(o) === IM_PLACE) { if (!imRow) { imRow = o; imAt = out.length; } imQ += q; imCost += q * shWhole(o.price); left -= q; continue; }
                // One line per place: a second listing of the same seller at another price is left for the next read.
                if (seen.has(placeOf(o))) continue;
                seen.add(placeOf(o));
                out.push(shLine(p, o, q));
                left -= q;
            }
            if (imQ) out.splice(imAt, 0, shLine(p, { ...imRow, price: Math.ceil(imCost / imQ) }, imQ));
        }
        return out;
    }

    /**
     * Fewer stops for the same pieces. A stop is dropped when everything it has for you can also be had at bazaars you
     * are going to anyway - each unit still under the piece's worth. The smallest stops are tried first, so the list
     * gathers at the bazaars that hold a lot of what you need. (The owner, 2026-10-11: "prioritize for example a bazaar
     * has a lot of things i need instead of just 1 bazaar 1 bazaar".) The price of it: those units at the other
     * bazaar's price, which is the dearer one - never over the worth. The Item Market's line is left as it is.
     *
     * 1.3.0: each stop is tried once, the smallest first, and a piece's listings are sorted by place once. A stop
     * that could not be emptied never can be later (the others only fill up), so trying it again changes nothing -
     * until then every stop was tried again after each one dropped, and the time grew about with the stops cubed
     * (his own state, 2026-10-11: 182 to 1,195 ms a list, the page frozen meanwhile; now 21 to 31 ms, the same list).
     * test/fewer-stops.test.js holds the old working-out beside this one on made-up lists.
     * @param plan     fillPlan's lines
     * @param pieces   [{ id, worth }] as given to fillPlan
     * @param offersOf id -> [{ price, qty, src, who, whoId }]
     */
    function fewerStops(plan, pieces, offersOf) {
        const worth = new Map((pieces || []).map((p) => [String(p.id), shWhole(p.worth)]));
        let cart = (plan || []).map((l) => ({ ...l }));
        const byPlace = new Map();
        const rows = new Map();
        const rowAt = (id, place) => {
            const k = String(id);
            if (!byPlace.has(k)) {
                const by = new Map();
                for (const o of (offersOf && offersOf(id)) || []) { const p = placeOf(o); if (!by.has(p)) by.set(p, []); by.get(p).push(o); }
                byPlace.set(k, by);
                rows.set(k, new Map());
            }
            const known = rows.get(k);
            if (!known.has(place)) {
                const w = worth.get(k) || 0;
                const o = placeOffer(byPlace.get(k).get(place) || [], place, w);
                known.set(place, o && w > 0 && shWhole(o.price) < w ? o : null);
            }
            return known.get(place);
        };
        const stuck = new Set();
        for (;;) {
            const units = new Map();
            for (const l of cart) if (!l.im) units.set(l.place, (units.get(l.place) || 0) + l.q);
            if (units.size < 2) return cart;
            const order = [...units].sort((a, b) => a[1] - b[1] || (a[0] < b[0] ? -1 : 1)).map(([place]) => place);
            const from = order.find((place) => !stuck.has(place));
            if (from === undefined) return cart;
            const next = cart.filter((l) => l.place !== from).map((l) => ({ ...l }));
            const at = new Map();
            for (const l of next) { const k = lineKey(l.id, l.place); if (!at.has(k)) at.set(k, l); }
            let fits = true;
            for (const line of cart.filter((l) => l.place === from)) {
                let left = line.q;
                const spots = order.filter((place) => place !== from).map((place) => ({ place, o: rowAt(line.id, place) })).filter((s) => s.o).sort((a, b) => a.o.price - b.o.price || (a.place < b.place ? -1 : 1));
                for (const s of spots) {
                    if (!left) break;
                    const have = at.get(lineKey(line.id, s.place));
                    const free = shWhole(s.o.qty) - (have ? have.q : 0);
                    const q = Math.min(left, free);
                    if (q <= 0) continue;
                    if (have) have.q += q;
                    else { const made = shLine({ id: line.id, name: line.name, set: line.set }, s.o, q); next.push(made); at.set(lineKey(made.id, made.place), made); }
                    left -= q;
                }
                if (left) { fits = false; break; }
            }
            if (fits) cart = next; else stuck.add(from);
        }
    }

    /** The list as it is made: the cheapest way to what you need (fillPlan), then gathered at fewer bazaars (fewerStops). */
    const fillList = (pieces, offersOf) => fewerStops(fillPlan(pieces, offersOf), pieces, offersOf);

    /**
     * The pieces as "Do now" counts them: a unit is worth buying only under what you pay your sellers AND under its
     * safe worth. The list made from them is the one its line names - the same pieces, the same stops.
     */
    const cheapPieces = (pieces) => (pieces || []).map((p) => ({ ...p, worth: Math.min(shWhole(p.worth), shWhole(p.pay)) }));

    /**
     * What one place has of a piece for you. A bazaar: its cheapest listing. The Item Market: it is one page with a
     * row for every price, so it is its rows under the piece's worth taken together - `qty` all of them, `price`
     * what each of the cheapest `want` costs on average (none under the worth: its cheapest row, which is then dear).
     * @returns null when the place lists none
     */
    function placeOffer(offers, place, worth, want = 0) {
        const rows = (offers || []).filter((o) => placeOf(o) === place && shWhole(o.qty) > 0 && shWhole(o.price) > 0).sort((a, b) => a.price - b.price);
        if (!rows.length) return null;
        if (place !== IM_PLACE) return rows[0];
        const under = rows.filter((o) => worth > 0 && o.price < worth);
        if (!under.length) return rows[0];
        const qty = under.reduce((s, o) => s + shWhole(o.qty), 0);
        let left = Math.min(qty, shWhole(want) || qty);
        const units = left;
        let cost = 0;
        for (const o of under) { const q = Math.min(left, shWhole(o.qty)); cost += q * shWhole(o.price); left -= q; if (!left) break; }
        return { ...under[0], price: Math.ceil(cost / units), qty };
    }

    /**
     * `units` of a piece spread over the Item Market's rows under its worth, cheapest first: how many fall to each
     * of `rows` (in the order given; a row over the worth gets none).
     */
    function imShares(rows, worth, units) {
        const order = (rows || []).map((o, i) => ({ o, i })).filter((x) => worth > 0 && x.o.price < worth && shWhole(x.o.qty) > 0).sort((a, b) => a.o.price - b.o.price || a.i - b.i);
        const out = (rows || []).map(() => 0);
        let left = shWhole(units);
        for (const { o, i } of order) { const q = Math.min(left, shWhole(o.qty)); out[i] = q; left -= q; if (!left) break; }
        return out;
    }

    /** One listing put on the list (as many as you still need of it), or taken off when it is already there. */
    function toggleLine(cart, piece, offer) {
        const key = lineKey(piece.id, placeOf(offer));
        const list = cart || [];
        if (list.some((l) => l.key === key)) return list.filter((l) => l.key !== key);
        const want = shWhole(piece.need) - onList(list, piece.id);
        // The Item Market: whichever of its rows was pressed, the line is its rows under the worth, cheapest first.
        const o = placeOf(offer) === IM_PLACE ? placeOffer(piece.offers || [offer], IM_PLACE, piece.worth, want) || offer : offer;
        const q = Math.min(shWhole(o.qty), want);
        return q > 0 ? [...list, shLine(piece, o, q)] : list;
    }

    const dropLine = (cart, key) => (cart || []).filter((l) => l.key !== key);

    /**
     * Every listing of ONE piece under its worth put on the list in one press: the cheapest first, as many as you still
     * need, one line per place. A place already on the list for this piece keeps its line as it is.
     * @param piece  { id, name, set, need, worth }
     * @param offers the piece's listings that count: [{ price, qty, src, who, whoId }]
     */
    function addAll(cart, piece, offers) {
        const list = cart || [];
        if (!piece) return list;
        const want = shWhole(piece.need) - onList(list, piece.id);
        if (want <= 0) return list;
        const have = new Set(list.filter((l) => String(l.id) === String(piece.id)).map((l) => l.place));
        const rows = (offers || []).filter((o) => !have.has(placeOf(o)));
        return [...list, ...fillPlan([{ ...piece, need: want }], () => rows)];
    }

    /** A piece taken off the list, every place of it. */
    const dropPiece = (cart, itemId) => (cart || []).filter((l) => String(l.id) !== String(itemId));

    /** The list without the lines of a place you no longer buy from. `keep(line)` true: the line stays whatever its place. */
    const dropPlaces = (cart, allowed, keep = null) => (cart || []).filter((l) => allowed({ src: l.im ? 'market' : 'bazaar' }) || (keep && keep(l)));

    /**
     * The list checked against a fresh read: a line whose listing is gone, or no longer under its worth, comes off;
     * one with less stock or less need shrinks. Nothing is ever added here.
     *
     * `tookOf` (a run is on): line key -> units you took on that line since the run began. They are in your stock
     * now, so the piece's need and the listing's stock both fell by them; the line keeps them, and says "took 5 of
     * 5" until Next - it does not shrink to nothing under you. A line you took from stays even when its listing is
     * gone or dear now: what is left of it is then nothing more to buy.
     * @returns { cart, dropped: [{ key, name, why: 'gone' | 'dear' | 'enough' }] }
     */
    function refreshList(cart, pieces, offersOf, tookOf = null) {
        const byId = new Map((pieces || []).map((p) => [String(p.id), p]));
        const out = [];
        const dropped = [];
        const taken = new Map();
        for (const l of cart || []) {
            const p = byId.get(String(l.id));
            const took = Math.min(shWhole(l.q), shWhole(tookOf ? tookOf(l.key) : 0));
            const had = taken.get(String(l.id)) || 0;
            const need = p ? shWhole(p.need) - had : 0;
            const offer = placeOffer((offersOf && offersOf(l.id)) || [], l.place, p ? p.worth : 0, Math.min(shWhole(l.q) - took, Math.max(0, need)));
            const dear = !p || !(p.worth > 0) || (offer && offer.price >= p.worth);
            if (took && (!offer || dear || need <= 0)) { out.push({ ...l, q: took }); continue; }
            if (!offer) dropped.push({ key: l.key, name: l.name, why: 'gone' });
            else if (dear) dropped.push({ key: l.key, name: l.name, why: 'dear' });
            else if (need <= 0) dropped.push({ key: l.key, name: l.name, why: 'enough' });
            else {
                const more = Math.min(shWhole(l.q) - took, shWhole(offer.qty), need);
                taken.set(String(l.id), had + more);
                out.push({ ...l, price: shWhole(offer.price), q: took + more, who: offer.who || l.who, whoId: offer.whoId ?? l.whoId });
            }
        }
        return { cart: out, dropped };
    }

    /**
     * The list as stops: one per place, everything that place has for you. Bazaars first, the one that saves most
     * first; the Item Market last (it is one page for every piece).
     * @param worthOf id -> the piece's safe worth
     * @returns [{ place, im, who, whoId, lines, units, cost, gain }]
     */
    function stopsOf(cart, worthOf) {
        const by = new Map();
        for (const l of cart || []) {
            if (!by.has(l.place)) by.set(l.place, []);
            by.get(l.place).push(l);
        }
        const stops = [...by].map(([place, lines]) => ({
            place, im: place === IM_PLACE, who: lines[0].who, whoId: lines[0].whoId, lines,
            units: lines.reduce((s, l) => s + l.q, 0),
            cost: lines.reduce((s, l) => s + l.q * l.price, 0),
            gain: lines.reduce((s, l) => s + l.q * (shWhole(worthOf ? worthOf(l.id) : 0) - l.price), 0),
        }));
        return stops.sort((a, b) => (a.im - b.im) || b.gain - a.gain || (a.place < b.place ? -1 : 1));
    }

    /** A run not started. `took` is line key -> units you took, as seen on the page or in Torn's log. */
    const RUN_IDLE = Object.freeze({ on: false, at: 0, took: {}, place: null });

    function runStart(stops) {
        return stops && stops.length ? { on: true, at: 0, took: {}, place: stops[0].place, order: stops.map((s) => s.place) } : { ...RUN_IDLE };
    }

    /**
     * The stops in the order the run began in. They are sorted by what they save, and that moves with every read (a
     * listing partly sold, a price changed): a stop that slid ahead of the one you stand on would read "skipped" and
     * never be reached. A place new to the list goes last.
     */
    function runOrder(stops, run) {
        if (!run || !run.on || !Array.isArray(run.order)) return stops || [];
        const at = new Map(run.order.map((place, i) => [place, i]));
        const rank = (s) => (at.has(s.place) ? at.get(s.place) : run.order.length);
        return (stops || []).map((s, i) => [s, i]).sort((a, b) => rank(a[0]) - rank(b[0]) || a[1] - b[1]).map((x) => x[0]);
    }

    /** The stop the run stands on, found again by its place: the list may have been re-sorted by a fresh read. */
    function runAt(run, stops) {
        if (!run || !run.on) return -1;
        const i = (stops || []).findIndex((s) => s.place === run.place);
        return i >= 0 ? i : Math.min(shWhole(run.at), (stops || []).length - 1);
    }

    /** Next: the stop after this one, or the run is over. Nothing is counted here: `took` says what was bought. */
    function runNext(run, stops) {
        if (!run || !run.on) return run || { ...RUN_IDLE };
        const at = runAt(run, stops) + 1;
        if (at >= (stops || []).length) return { ...run, on: false, at, place: null, done: true };
        return { ...run, at, place: stops[at].place };
    }

    /** Units of a line seen bought. The larger count wins: a log that lags never un-buys what the page saw. */
    function runTook(run, key, units) {
        const had = shWhole(run && run.took && run.took[key]);
        const n = Math.max(had, shWhole(units));
        return n === had ? run : { ...run, took: { ...((run && run.took) || {}), [key]: n } };
    }

    const tookAt = (run, stop) => (stop ? stop.lines.reduce((s, l) => s + Math.min(l.q, shWhole(run && run.took && run.took[l.key])), 0) : 0);

    /**
     * A press of Start, Next or Stop in the box on a Torn page, applied to the run as the view has it (runView's
     * answer) - at once, before the hub's tab has taken the press. Until 1.3.0 the box showed nothing until the hub
     * answered, and a busy hub answered after up to 42 s ("i press stop the run but nothing happens").
     * As the engine does it (engine.js act run): Next from a bazaar of the list that is not the stop the run is on
     * goes on from that bazaar; the stops passed over stay on the list.
     * @param run   { stops: [{ place, units, took, state }], at, took }; the answer adds `over`: the press passed the last stop
     * @param op    'start' | 'next' | 'stop'
     * @param place where you stand ('b:' + id, or 'im'), for Next
     */
    function runLocal(run, op, place = null) {
        const stops = (run && run.stops) || [];
        if (op === 'stop') return { ...run, stops: stops.map((s) => ({ ...s, state: '', took: 0 })), at: -1, began: false, over: false, took: {}, got: 0, skipped: 0 };
        if (op === 'start') return { ...run, stops: stops.map((s, i) => ({ ...s, took: 0, state: i === 0 ? 'cur' : '' })), at: stops.length ? 0 : -1, began: true, over: false, took: {}, got: 0, skipped: 0 };
        if (op !== 'next') return run;
        const cur = stops.findIndex((s) => s.state === 'cur');
        if (cur < 0) return run;
        const here = place ? stops.findIndex((s) => s.place === place) : -1;
        const next = (here >= 0 ? here : cur) + 1;
        const past = (s) => (s.took >= s.units ? 'done' : s.took ? 'part' : 'skip');
        const rows = stops.map((s, i) => ({ ...s, state: i === next ? 'cur' : i < next ? past(s) : '' }));
        return { ...run, stops: rows, at: next < stops.length ? next : -1, over: next >= stops.length, skipped: rows.filter((r) => r.state === 'skip').length };
    }

    /**
     * What each stop says while a run is on, and after it.
     * @returns { stops: [{ ...stop, took, state: '' | 'cur' | 'done' | 'part' | 'skip' }], at, units, cost, gain, got, skipped, began }
     */
    function runView(run, stops) {
        const list = stops || [];
        // Over, and summed when it ended: what was taken has left the list, so the lines are what is still to buy.
        if (run && run.done && run.sum) {
            const rows = list.map((s) => ({ ...s, took: 0, state: '' }));
            return {
                stops: rows, at: -1, began: true,
                units: shWhole(run.sum.units), cost: rows.reduce((s, r) => s + r.cost, 0), gain: rows.reduce((s, r) => s + r.gain, 0),
                got: shWhole(run.sum.got), skipped: shWhole(run.sum.skipped),
            };
        }
        const at = runAt(run, list);
        const began = !!(run && (run.on || run.done));
        const past = (i) => began && (run.done || i < at);
        const rows = list.map((s, i) => {
            const took = tookAt(run, s);
            const state = run && run.on && i === at ? 'cur' : !past(i) ? '' : took >= s.units ? 'done' : took ? 'part' : 'skip';
            return { ...s, took, state };
        });
        return {
            stops: rows, at, began,
            units: rows.reduce((s, r) => s + r.units, 0),
            cost: rows.reduce((s, r) => s + r.cost, 0),
            gain: rows.reduce((s, r) => s + r.gain, 0),
            got: rows.reduce((s, r) => s + r.took, 0),
            skipped: rows.filter((r) => r.state === 'skip').length,
        };
    }

    /** After a run: what was taken leaves the list, what was skipped stays on it. */
    function listAfterRun(cart, run) {
        const out = [];
        for (const l of cart || []) {
            const left = l.q - Math.min(l.q, shWhole(run && run.took && run.took[l.key]));
            if (left > 0) out.push({ ...l, q: left });
        }
        return out;
    }

    /* ===== src/core/feed.js ===== */
    /*
     * Listings made usable. Pure - no DOM, no network, no storage.
     *
     * Cut for Torn Archive from Torn Bids 3.24.0 (core/feed.js): only what turns
     * TornW3B's and the Item Market's rows into ours, and the link to a bazaar.
     * The live feed itself (candidates, snapshots, expiry) is left behind.
     *
     * The rule the rows keep, learned the hard way: a listing is only as live as
     * the data behind it. `dataAt` is when the SOURCE last saw it (TornW3B's
     * last_checked), never when we asked.
     */

    /** Seconds, milliseconds, or nothing -> ms or null. Unknown is not "old". */
    function toMs(value) {
        const n = Number(value);
        if (!Number.isFinite(n) || n <= 0) return null;
        return n < 1e12 ? n * 1000 : n;
    }

    /**
     * TornW3B listings -> feed rows. Rows with no seller are dropped: there is
     * nowhere to send the user, and "bazaar.php?userId=null" is not a link.
     * Sorted by price ourselves - TornW3B puts sponsored rows first.
     */
    function normalizeW3bListings(raw) {
        const rows = [];

        for (const l of raw || []) {
            if (!l) continue;

            const sellerId = Number(l.player_id);
            const price = Number(l.price);
            const qty = Number(l.quantity);

            if (!Number.isFinite(sellerId) || sellerId <= 0) continue;
            if (!Number.isFinite(price) || price <= 0) continue;
            if (!Number.isFinite(qty) || qty <= 0) continue;
            /*
             * $1 is Torn's locked "Dollar Sale" price: buyable by a random few
             * percent of players, and the usual price of a target trade meant for
             * one person. TornW3B cannot say which, so none are offered from the
             * feed. (On the page itself, an unlocked $1 card IS yours to buy and
             * is read normally.)
             */
            if (price <= 1) continue;

            rows.push({
                sellerId: String(sellerId),
                sellerName: l.player_name ? String(l.player_name) : null,
                price,
                qty: Math.floor(qty),
                dataAt: toMs(l.last_checked) || toMs(l.content_updated),
                changedAt: toMs(l.content_updated),
                // A paid spot on TornW3B: never the listing Fill undercuts.
                sponsored: Boolean(l.sponsored),
            });
        }

        rows.sort((a, b) => a.price - b.price);
        return rows;
    }

    /** Item Market rows are anonymous; identical prices are merged. */
    function normalizeItemMarketRows(listings) {
        const byPrice = new Map();

        for (const l of listings || []) {
            const price = Number(l && l.price);
            const amount = Number(l && l.amount);
            if (!(price > 0) || !(amount > 0)) continue;
            byPrice.set(price, (byPrice.get(price) || 0) + amount);
        }

        return [...byPrice.entries()]
            .sort((a, b) => a[0] - b[0])
            .map(([price, qty]) => ({ price, qty }));
    }

    /** Deep link to one seller's bazaar, carrying what to highlight there. */
    function bazaarUrl(sellerId, itemId, price) {
        const params = new URLSearchParams({ userId: String(sellerId) });
        if (itemId) params.set('ttItem', String(itemId));
        if (price) params.set('ttPrice', String(price));
        return 'https://www.torn.com/bazaar.php?' + params.toString() + '#/';
    }

    /* ===== src/core/inventory.js ===== */
    /*
     * Your inventory, from GET /v2/user/inventory (Limited key). Pure.
     *
     * Torn returns one entry per stack: the same item can appear several times
     * (different uids, an equipped copy, a faction-owned copy). The selling page
     * wants one line per item with the quantity you could actually hand over,
     * so stacks are merged by item id, and equipped and faction-owned copies are
     * left out: you cannot trade what you are wearing or what is the faction's.
     */

    const INVENTORY_CACHE_VERSION = 1;

    /** Torn caches the selection for an hour; re-asking sooner returns the same. */
    const INVENTORY_TTL_MS = 60 * 60 * 1000;

    /**
     * One response page -> plain rows. Bad rows are dropped, never guessed.
     * @returns {Array<{id: string, name: string, amount: number, equipped: boolean, factionOwned: boolean}>}
     */
    function parseInventoryPage(body) {
        const inv = body && body.inventory;
        const items = inv && Array.isArray(inv.items) ? inv.items : null;
        if (!items) throw new Error('Torn API returned no inventory.');

        const out = [];
        for (const raw of items) {
            if (!raw) continue;
            const id = Number(raw.id);
            const amount = Number(raw.amount);
            if (!Number.isFinite(id) || id <= 0) continue;
            if (!Number.isFinite(amount) || amount <= 0) continue;

            out.push({
                id: String(id),
                name: typeof raw.name === 'string' ? raw.name : '',
                amount: Math.floor(amount),
                equipped: Boolean(raw.equipped),
                factionOwned: Boolean(raw.faction_owned),
            });
        }
        return out;
    }

    /**
     * Merge stacks by item id; equipped and faction-owned copies are excluded.
     * @returns {Array<{id: string, name: string, qty: number}>} sorted by id
     */
    function mergeInventory(rows) {
        const byId = new Map();

        for (const r of rows || []) {
            if (!r || r.equipped || r.factionOwned) continue;
            if (!(r.amount > 0)) continue;

            const cur = byId.get(r.id);
            if (cur) {
                cur.qty += r.amount;
                if (!cur.name && r.name) cur.name = r.name;
            } else {
                byId.set(r.id, { id: r.id, name: r.name || '', qty: r.amount });
            }
        }

        return [...byId.values()].sort((a, b) => Number(a.id) - Number(b.id));
    }

    /** The `_metadata.links.next` offset, or null when this was the last page. */
    function nextInventoryOffset(body) {
        const next = body && body._metadata && body._metadata.links && body._metadata.links.next;
        if (!next) return null;
        try {
            const offset = Number(new URL(String(next), 'https://api.torn.com/').searchParams.get('offset'));
            return Number.isFinite(offset) && offset > 0 ? offset : null;
        } catch {
            return null;
        }
    }

    /** A failed inventory read is not asked again sooner than this. */
    const INVENTORY_RETRY_MS = 5 * 60 * 1000;

    /**
     * Whether the inventory should be read again now, on the timer: it is old,
     * the last failure's wait is over, and the key is not one Torn rejected
     * (that waits for a new key, not for time).
     */
    function inventoryRefreshDue({ inventoryAt, retryAt = 0, keyDead = false, now = Date.now(), refreshMs = INVENTORY_TTL_MS }) {
        if (keyDead) return false;
        if (now < (Number(retryAt) || 0)) return false;
        const at = Number(inventoryAt) || 0;
        return now - at >= refreshMs;
    }

    function makeInventoryCacheEntry(items, now = Date.now()) {
        return { version: INVENTORY_CACHE_VERSION, fetchedAt: now, items };
    }

    /** @returns {{fetchedAt: number, items: Array}|null} */
    function readInventoryCacheEntry(entry, now = Date.now(), ttl = INVENTORY_TTL_MS) {
        if (!entry || entry.version !== INVENTORY_CACHE_VERSION || !Array.isArray(entry.items)) return null;
        const at = Number(entry.fetchedAt);
        if (!Number.isFinite(at) || now - at > ttl) return null;
        return { fetchedAt: at, items: entry.items };
    }

    /* ===== src/core/tw3b-list.js ===== */
    // Your price list on TornW3B, and its receipts.
    // Sellers find a buyer on TornW3B by its price list, and a buyer stays on TornW3B's lists only with a receipt in
    // the last 7 days. So the Archive keeps your 24 pieces on your list at your rate, and makes a receipt per trade.
    // "Closed" = the pieces are taken off your list. TornW3B's own Open / Closed button is on its website and stays
    // yours. Pure working-out: what to send, and what came back. Sending is src/api/tw3b-own.js.

    const twNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const twWhole = (v) => Math.max(0, Math.floor(twNum(v)));

    /** What your list should say: every piece of the sets you trade at a fixed price, or nothing when closed. */
    function desiredList(pieces, open) {
        if (!open) return [];
        return (pieces || []).filter((p) => p.pay > 0).map((p) => ({ itemID: Number(p.id), price: twWhole(p.pay) }));
    }

    /**
     * Your list as TornW3B has it: itemId -> { type, value }. Read loosely: the shape of the answer was never seen
     * from a script, only its documentation.
     */
    function parseOwnList(json) {
        const raw = json && (json.items || json.pricelist || json.priceList || json.data || json);
        const out = new Map();
        const rows = Array.isArray(raw) ? raw : raw && typeof raw === 'object' ? Object.values(raw) : [];
        for (const r of rows) {
            if (!r || typeof r !== 'object') continue;
            const id = twWhole(r.itemID ?? r.itemId ?? r.item_id ?? r.id);
            const value = r.pricingValue ?? r.pricing_value ?? r.price ?? r.value;
            if (!id || value == null || value === '') continue;
            out.set(String(id), { type: String(r.pricingType ?? r.pricing_type ?? 'fixed'), value: twNum(value) });
        }
        return out;
    }

    /**
     * What differs between TornW3B's list and yours. Only the Archive's own pieces are ever touched: `ids` are the 24
     * (or the sets you trade); anything else on your list is left exactly as it is.
     * @param current parseOwnList()
     * @param desired desiredList()
     * @param ids     every piece id the Archive may put on or take off
     * @returns { set: [{ itemID, price, was }], remove: [{ itemID, was }], same }
     */
    function listDiff(current, desired, ids) {
        const want = new Map((desired || []).map((d) => [String(d.itemID), d.price]));
        const set = [];
        const remove = [];
        let same = 0;
        for (const id of (ids || []).map(String)) {
            const cur = current && current.get(id);
            const price = want.get(id);
            if (price == null) { if (cur) remove.push({ itemID: Number(id), was: cur.value }); continue; }
            if (cur && cur.type === 'fixed' && cur.value === price) same += 1;
            else set.push({ itemID: Number(id), price, was: cur ? cur.value : null });
        }
        return { set, remove, same };
    }

    const listMatches = (diff) => !diff.set.length && !diff.remove.length;

    /** The body of `PUT /api/pricelist/{userID}`. An item sent with no price is taken off the list. */
    function putBody(diff) {
        return {
            items: [
                ...diff.set.map((s) => ({ itemID: s.itemID, pricingType: 'fixed', pricingValue: s.price, inflationProtectionEnabled: false, roundToPlace: 0, bulkType: 'none' })),
                ...diff.remove.map((r) => ({ itemID: r.itemID })),
            ],
        };
    }

    /**
     * The body of `POST /api/pricelist/{userID}`: a receipt for one trade, from your list.
     * @param rows [{ id, qty }] the set pieces of the trade
     */
    function receiptBody(tradeId, rows, sellerId) {
        const by = new Map();
        for (const r of rows || []) if (twWhole(r.qty)) by.set(Number(r.id), (by.get(Number(r.id)) || 0) + twWhole(r.qty));
        return {
            items: [...by].map(([itemID, quantity]) => ({ itemID, quantity })),
            tradeID: String(tradeId),
            ...(sellerId ? { buyerPlayerId: Number(sellerId) } : {}),
            includeMessage: true,
        };
    }

    /**
     * TornW3B's receipt set against the Archive's own sum for the same trade.
     * @param json  the POST's answer
     * @param total what the Archive worked out
     * @returns { ok, total, url, message, missing: [names], differs } - ok = same total and nothing missing
     */
    function readReceipt(json, total) {
        const rec = (json && json.receipt) || {};
        const theirs = twNum(rec.total_value ?? rec.totalValue);
        const w = (json && json.warnings) || {};
        const missing = [...(w.notFound || []), ...(w.notPriced || [])].map((x) => (typeof x === 'string' ? x : String((x && (x.name || x.itemID || x.id)) || '')));
        return {
            ok: theirs > 0 && theirs === twWhole(total) && !missing.length,
            total: theirs,
            url: (json && (json.receiptURL || json.receiptUrl)) || '',
            message: (json && json.message) || '',
            missing,
            differs: theirs - twWhole(total),
            id: rec.id ?? null,
        };
    }

    /** TornW3B's receipts (`GET /api/trades/{userID}/{receiptId}`) by Torn's trade id: tradeId -> { id, total, at }. */
    function receiptsByTrade(list) {
        const out = new Map();
        for (const r of list || []) {
            const tid = r && (r.trade_id ?? r.tradeId ?? r.tradeID);
            if (tid == null) continue;
            out.set(String(tid), { id: r.id, total: twNum(r.total_value ?? r.value), at: r.created_at ?? null });
        }
        return out;
    }

    /** The newest receipt is how long TornW3B keeps listing you as a buyer: 7 days from it. */
    const RECEIPT_KEEPS_MS = 7 * 86400000;
    function listedUntil(lastReceiptAt) {
        return lastReceiptAt > 0 ? lastReceiptAt + RECEIPT_KEEPS_MS : 0;
    }

    /* ===== src/engine/state.js ===== */
    // What Torn Archive has learned, and how each read is folded into it. Pure: no page, no storage, no clock.
    // The engine (engine.js) asks Torn and TornW3B, hands every answer to one of these folds, stores the parts that
    // changed, and gives the whole thing to the view (core/view.js) through engineInput().














    const enNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const enWhole = (v) => Math.max(0, Math.floor(enNum(v)));
    const enDay = (t) => new Date(t).toISOString().slice(0, 10);
    const EN_MIN = 60000;
    const EN_HOUR = 3600000;
    const EN_DAY = 86400000;

    /** Every piece of both sets, as strings: what the stock count, the prices and the books are kept for. */
    const ENGINE_PIECES = SETS.flatMap((s) => s.pieces.map((p) => String(p.id)));
    const EN_PIECE_SET = new Set(ENGINE_PIECES);

    /** A bazaar listing TornW3B has not looked at for this long is most likely gone: not advice to act on. */
    const LISTING_FRESH_MS = 30 * EN_MIN;
    /** A piece's bazaar listings are dropped when they were read this long ago and never since. */
    const LISTINGS_KEEP_MS = 3 * EN_HOUR;
    /** Torn's own read of one bazaar stands for this long. */
    const SHOP_KEEP_MS = EN_HOUR;
    /** The Item Market's listings of a piece stand for this long. */
    const MARKET_KEEP_MS = 30 * EN_MIN;
    /** How far back the log and the finished trades are read at the first start. */
    const BACKFILL_MS = 14 * EN_DAY;
    const EN_ROWS_KEPT = 4000;
    const EN_OUTS_KEPT = 1500;
    const EN_BOOK_KEPT = 1500;
    const EN_FINISHED_KEPT = 200;
    const EN_NAMES_KEPT = 1500;
    const EN_LOTS_READ = 300;

    /** The parts of the state, each stored under its own name: only what changed is written. */
    const ENGINE_PARTS = ['self', 'items', 'stock', 'seen', 'swaps', 'offers', 'summary', 'shops', 'bids', 'points', 'money', 'book', 'types', 'log', 'ledger', 'outs', 'trades', 'cart', 'plan', 'run', 'hot', 'thread', 'w3b', 'rate', 'hist', 'names', 'server'];

    function engineEmpty() {
        return {
            self: { id: '', name: '' },
            items: { at: 0, list: {} },
            stock: { ...STOCK_EMPTY },
            seen: [],
            swaps: [],
            offers: {},
            summary: { at: 0, low: {} },
            shops: {},
            // What a bazaar's own page showed in one of your Torn tabs: { whoId: { at, items: { id: { price, qty } } } }.
            // Only the pieces that were on the screen (a bazaar draws its list as you scroll). Not kept over a reload.
            pages: {},
            // "Read now" was pressed then: a row looked at before it does not count until it is looked at again.
            fresh: { since: 0 },
            // The in-between layer (pileOf): each piece's listings sorted once, and again only when an answer changed
            // them. `all` and `by` count the changes; not stored.
            lay: { all: 0, by: {}, piles: new Map() },
            bids: {},
            points: { listings: [], at: 0, days: [], wallDays: [], lots: { ...LOTS_EMPTY } },
            money: { points: null, onHand: null, vault: null, at: 0 },
            book: [],
            types: { at: 0, made: [], sold: [], used: [], out: [], titles: {} },
            log: { from: 0, until: 0, at: 0, backfilled: false, madeRead: false },
            // direct: pieces sold or given away as themselves, each with what it had cost (1.3.0). repriced: the old
            // trade rows were looked through once for a piece priced with a whole trade's money (foldTradeReprice).
            ledger: { rows: [], mugs: [], tradeIds: [], tradesFrom: 0, tradesAt: 0, tradesBackfilled: false, direct: [], repriced: false },
            outs: [],
            trades: { open: [], at: 0, seen: null, finished: [], full: {}, told: null },
            cart: [],
            // How many sets the list on hand was made for ("from my cash"): kept while the list is, see engine planKeep.
            plan: { targets: null, at: 0, key: '' },
            run: { ...RUN_IDLE },
            hot: {},
            thread: null,
            w3b: { list: null, listAt: 0, receipts: [], receiptsAt: 0, lastReceiptAt: 0, error: '', receiptsError: '', tried: {} },
            // What you pay your sellers, fixed for the hour (core/sellrate.js fixTable; engine rateKeep). `sent`: the
            // table's `rev` as it was last brought to TornW3B - kept over a reload, so a reload keeps the hour.
            rate: { table: null, sent: 0 },
            hist: { low: {}, pays: [], share: [] },
            names: {},
            server: serverEmpty(),
        };
    }

    /** What the shared server said, when nothing has been heard from it (core/server.js). */
    function serverEmpty() {
        return { at: 0, seq: 0, seenAt: 0, shops: {}, dir: { reads: {}, turn: { of: 1, me: 0 } } };
    }

    /** What was stored, laid over a fresh state: a part of the wrong kind is left out. */
    /** The mark on a buy seen by a copy that reads Torn's open buy form (1.2.2 on). */
    const EN_SEEN_V = 2;

    function engineLoad(stored) {
        const S = engineEmpty();
        for (const part of ENGINE_PARTS) {
            const v = stored && stored[part];
            if (v == null) continue;
            if (Array.isArray(S[part]) ? Array.isArray(v) : typeof v === 'object') S[part] = Array.isArray(v) ? v : { ...S[part], ...v };
        }
        if (!S.thread || !S.thread.title) S.thread = null;
        // 1.2.0 and 1.2.1 took the opening of a listing's Buy box for a buy. What those copies "saw" and was still
        // waiting beside the count is not kept: a real buy is in Torn's log and in its inventory count.
        S.seen = S.seen.filter((b) => b && (b.counted || b.v === EN_SEEN_V));
        // A run that ended under 1.2.1 kept its counts beside a list already made shorter by them: it is let go.
        if (S.run && S.run.done && !S.run.sum) S.run = { on: false, at: 0, took: {}, place: null };
        S.server = { ...S.server, shops: serverReadKept(S.server.shops) };
        if (!Array.isArray(S.ledger.direct)) S.ledger = { ...S.ledger, direct: [] };
        // A day's low of $1 was a locked listing, never a price (kept by copies before 1.3.0).
        const low = {};
        for (const [id, days] of Object.entries((S.hist && S.hist.low) || {})) low[id] = (Array.isArray(days) ? days : []).filter((d) => d && d.low > 1);
        S.hist = { ...S.hist, low };
        return S;
    }

    // ---- Items ---------------------------------------------------------------------------------------------------------

    /** Torn's item database (api/torn.js fetchItems): each item's name and market value. */
    function foldItems(S, raw, now) {
        const list = {};
        for (const [id, item] of Object.entries(raw || {})) {
            if (!item || typeof item.name !== 'string') continue;
            list[id] = [item.name, enWhole(item.market_value)];
        }
        if (!ENGINE_PIECES.some((id) => list[id] && list[id][1] > 0)) return false;
        S.items = { at: now, list };
        return true;
    }

    const mvOf = (S) => (id) => { const it = S.items.list[String(id)]; return it ? enWhole(it[1]) : 0; };
    const nameOf = (S) => (id) => { const it = S.items.list[String(id)]; return it ? it[0] : ''; };

    function enName(S, id, name) {
        if (!id || !name || S.names[id] === name) return;
        enBump(S, null);
        const keys = Object.keys(S.names);
        if (keys.length >= EN_NAMES_KEPT) { const next = {}; for (const k of keys.slice(-Math.floor(EN_NAMES_KEPT / 2))) next[k] = S.names[k]; S.names = next; }
        S.names = { ...S.names, [id]: String(name) };
    }

    // ---- The in-between layer: what changed -------------------------------------------------------------------------------

    /**
     * A piece's listings changed (`ids`), or everything did (null): its pile is sorted again at the next look (pileOf).
     * Every fold that can move a row says so here; a fold that forgot would show an old row for PILE_MAX_MS at most.
     */
    function enBump(S, ids) {
        const lay = S.lay || (S.lay = { all: 0, by: {}, piles: new Map() });
        if (ids == null) { lay.all += 1; return; }
        for (const id of ids) lay.by[String(id)] = (lay.by[String(id)] || 0) + 1;
    }

    const EN_REV = new WeakMap();
    /** The pieces TornW3B's lists name a bazaar for: whoId -> [piece id]. Worked out once per record of the lists. */
    function enRev(S) {
        let rev = EN_REV.get(S.offers);
        if (!rev) {
            rev = new Map();
            for (const [id, o] of Object.entries(S.offers)) for (const r of o.baz || []) { const k = String(r.whoId); if (!rev.has(k)) rev.set(k, []); rev.get(k).push(id); }
            EN_REV.set(S.offers, rev);
        }
        return rev;
    }

    /** The pieces one bazaar's rows are in: what it held, what it holds, and the lists that name it. */
    function enShopPieces(S, whoId, ...items) {
        const out = new Set(enRev(S).get(String(whoId)) || []);
        for (const it of items) for (const id of Object.keys(it || {})) out.add(id);
        const sv = S.server.shops[String(whoId)];
        if (sv) for (const [item] of sv[2]) out.add(String(item));
        return out;
    }

    // ---- Prices of the pieces ------------------------------------------------------------------------------------------

    /** TornW3B's summary: the cheapest bazaar price of every piece, in one request. */
    function foldSummary(S, rows, now) {
        const low = {};
        for (const r of rows || []) if (r && EN_PIECE_SET.has(String(r.itemId)) && r.lowestPrice > 0) low[String(r.itemId)] = r.lowestPrice;
        S.summary = { at: now, low };
    }

    /** One piece's bazaar listings from TornW3B (the raw rows). Your own bazaar and listings long unseen are left out. */
    function foldListings(S, id, raw, now) {
        const rows = normalizeW3bListings(raw)
            // A price of $1 or less is a locked listing, never a price (1.3.0: a $1 Teddy Bear stood as the day's low).
            .filter((r) => r.sellerId !== String(S.self.id) && r.price > 1 && !(r.dataAt && now - r.dataAt > LISTING_FRESH_MS))
            .slice(0, 40);
        for (const r of rows) enName(S, r.sellerId, r.sellerName);
        const prev = S.offers[id] || {};
        S.offers = { ...S.offers, [id]: { ...prev, baz: rows.map((r) => ({ price: r.price, qty: r.qty, whoId: r.sellerId, at: r.dataAt || now, ch: r.changedAt || 0 })), bazAt: now, bazLow: enWhole(S.summary.low[id]) } };
        enBump(S, [id]);
    }

    /** One piece's Item Market listings (api/torn.js fetchItemMarket's `listings`). */
    function foldMarket(S, id, listings, now) {
        const prev = S.offers[id] || {};
        S.offers = { ...S.offers, [id]: { ...prev, im: normalizeItemMarketRows(listings).filter((l) => l.price > 1).slice(0, 20), imAt: now } };
        enBump(S, [id]);
    }

    /**
     * One player's bazaar as Torn itself has it (v2 user?selections=bazaar&id=): fresher than any list of listings.
     * @returns false when the answer has no bazaar in it (nothing is changed)
     */
    function foldShop(S, whoId, json, now) {
        // An empty bazaar has been seen as an empty list. Should Torn ever answer it with nothing under the name, or
        // with a record by id, that is read too: a bazaar with nothing in it is a read, not a failed one.
        const raw = json && typeof json === 'object' && !json.error && 'bazaar' in json ? json.bazaar : undefined;
        const rows = Array.isArray(raw) ? raw : raw === null ? [] : raw && typeof raw === 'object' ? Object.values(raw) : null;
        if (!rows) return false;
        const items = {};
        for (const r of rows) {
            const id = String(enWhole(r && (r.ID ?? r.id ?? r.item_id)));
            const price = enWhole(r && r.price);
            const qty = enWhole(r && (r.quantity ?? r.amount));
            if (!EN_PIECE_SET.has(id) || !(price > 1) || !qty) continue;
            // A bazaar may list one item at two prices: the cheaper one is what you would be buying.
            if (!items[id] || price < items[id].price) items[id] = { price, qty };
        }
        const shops = {};
        for (const [k, v] of Object.entries(S.shops)) if (now - v.at < SHOP_KEEP_MS) shops[k] = v;
        enBump(S, enShopPieces(S, whoId, items, (S.shops[String(whoId)] || {}).items));
        shops[String(whoId)] = { at: now, items };
        S.shops = shops;
        return true;
    }

    /** The best any other buyer pays for a piece (TornW3B's buyers of an item, highest first). */
    function foldBids(S, id, traders, now) {
        const best = (traders || []).find((t) => t && t.id !== String(S.self.id) && t.price > 0) || null;
        S.bids = { ...S.bids, [id]: { at: now, price: best ? best.price : 0, name: best ? best.name || '' : '' } };
    }

    // ---- The shared server ---------------------------------------------------------------------------------------------

    /**
     * One answer of the shared server (core/server.js): the bazaars it read from Torn since the last one, the ones it
     * read again and found the same, and which of TornW3B's lists the other PCs read.
     * @param got when the answer arrived, by this PC's clock
     */
    function foldServer(S, answer, got) {
        const known = new Set(Object.keys(S.shops));
        for (const o of Object.values(S.offers)) for (const r of o.baz || []) known.add(String(r.whoId));
        // A new record each time: what is worked out from it (svIndex) is kept per record.
        const shops = { ...S.server.shops };
        // Your own bazaar is not a place to buy.
        const reads = (answer && Array.isArray(answer.reads) ? answer.reads : []).filter((r) => !r || String(r.id) !== String(S.self.id));
        // The pieces whose rows this answer can move: of every bazaar it names, what it held and what it holds now.
        const named = [...reads.map((r) => r && r.id), ...(answer && Array.isArray(answer.seen) ? answer.seen : []).map((p) => (Array.isArray(p) ? p[0] : null))].filter((id) => id != null).map(String);
        const moved = new Set();
        for (const id of named) for (const p of enShopPieces(S, id)) moved.add(p);
        serverTake(shops, { ...answer, reads }, EN_PIECE_SET, (id) => known.has(id), got);
        for (const id of named) if (shops[id]) for (const [item] of shops[id][2]) moved.add(String(item));
        enBump(S, moved);
        serverPrune(shops, got);
        S.server = {
            at: got, shops,
            seq: answer && Number.isInteger(answer.seq) ? answer.seq : S.server.seq,
            seenAt: answer && Number.isFinite(answer.now) ? answer.now : S.server.seenAt,
            dir: serverDirIn(answer, S.server.dir, got),
        };
    }

    const EN_SV_INDEX = new WeakMap();
    /** The server's bazaars by piece: piece id -> [{ whoId, at }]. Worked out once per record. */
    function svIndex(S) {
        const shops = S.server.shops;
        let index = EN_SV_INDEX.get(shops);
        if (!index) {
            index = new Map();
            for (const [whoId, e] of Object.entries(shops)) {
                for (const [item] of e[2]) {
                    const key = String(item);
                    if (!index.has(key)) index.set(key, []);
                    index.get(key).push({ whoId, at: e[1] });
                }
            }
            EN_SV_INDEX.set(shops, index);
        }
        return index;
    }

    /** One bazaar as Torn itself last had it, read by you or by the server, whichever is newer: { at, items } or null. */
    function shopNow(S, whoId, now) {
        const own = S.shops[String(whoId)] || null;
        const theirs = serverShop(S.server.shops, whoId);
        const best = own && theirs ? (theirs.at > own.at ? theirs : own) : own || theirs;
        return best && now - best.at < SHOP_KEEP_MS ? best : null;
    }

    /** Your own buys at a bazaar (seen on its page, or read in your log) are held against its listing for this long. */
    const OWN_KEEP_MS = 3 * EN_HOUR;
    /**
     * A look at a bazaar counts as made after your buy only when it is over a minute later: TornW3B's answer is a copy
     * one to three minutes old, and Torn's own is some seconds old. (Measured for Torn Trading, 3.16.4.)
     */
    const OWN_MARGIN_MS = EN_MIN;

    const EN_OWN_INDEX = new WeakMap();
    /**
     * Your bazaar buys of the last hours, each of them once: Map 'item:who' -> [{ t, qty }]. A buy seen on the page
     * stands until its row in Torn's log is in; from then on the row does (a buy made with no Torn tab of ours open -
     * on a phone, or with the hub closed - is known from the log alone, and until 1.2.3 never came off a listing).
     */
    function ownBuys(S, now) {
        const hit = EN_OWN_INDEX.get(S.ledger.rows);
        if (hit && hit.seen === S.seen && now - hit.at < EN_MIN && now >= hit.at) return hit.by;
        const by = new Map();
        const put = (item, who, t, qty) => { const k = item + ':' + who; if (!by.has(k)) by.set(k, []); by.get(k).push({ t, qty }); };
        const claimed = new Set();
        for (const b of S.seen) {
            if (b.logged) claimed.add(b.logged);
            // `no`: Torn's log has no such buy (judgeSeen): nothing came off that listing.
            else if (b.whoId && !b.im && !b.no && now - b.t < OWN_KEEP_MS) put(String(b.id), String(b.whoId), b.t, enWhole(b.qty));
        }
        const rows = S.ledger.rows;
        for (let k = rows.length - 1; k >= 0 && now - rows[k].t < OWN_KEEP_MS; k--) {
            const r = rows[k];
            if (r.side === 'buy' && r.venue === 'bazaar' && r.who) put(String(r.itemId), String(r.who), r.t, enWhole(r.qty));
        }
        EN_OWN_INDEX.set(S.ledger.rows, { seen: S.seen, at: now, by });
        return by;
    }

    /**
     * Was this look at a bazaar made after `t` - so that it shows what happened then?
     * Torn's own read: over a minute later. TornW3B's row: its check over a minute later AND that check found the bazaar
     * changed since (`ch`, TornW3B's content_updated: its last check that found a change). Its "last checked" alone
     * moves on while its copy is still the old one - so a listing you bought out came back, with your buy in it.
     * (A row kept from before 1.2.3 has no `ch`: its check time alone decides, with the margin.)
     */
    function lookedSince(at, ch, from, t) {
        // The bazaar's own page, in front of you: what it shows after your buy is the bazaar after your buy.
        if (from === 'page') return at >= t;
        if (!(at - t > OWN_MARGIN_MS)) return false;
        return from !== 'w3b' || !ch || ch > t;
    }

    /**
     * A listing COUNTS - goes on a list, into "Do now", is called the cheapest - only when it was looked at this lately.
     * An older row is still shown, apart, as "not checked": it is asked of Torn before anything is made of it.
     * (Torn Trading shows nothing it has not confirmed within two minutes; that is why its finds are true. Here a list
     * of bazaars takes longer to walk than a flip, so the time is longer - and every stop of a list is asked again each
     * minute.)
     */
    const COUNT_MS = 5 * EN_MIN;

    /** No row is offered that nobody has looked at for this long: it is most likely gone (1.3.0; a TornW3B row stood up to 3.5 h). */
    const OFFER_KEEP_MS = EN_HOUR;
    /**
     * What a bazaar's own page showed stands against a read of Torn's API made less than this long after it: the API
     * is 20 to 40 seconds behind the page (measured 2026-10-10), so a read that close may still be the bazaar as it was.
     */
    const PAGE_STANDS_MS = EN_MIN;

    /**
     * What a bazaar's page showed in a Torn tab of yours (the tab's note 'shop'): the pieces on the screen, their price
     * and stock. The newest look there is; a piece NOT on the screen says nothing (the page draws as you scroll).
     * A piece the page PROVED gone - its listing was on the screen and is not, or you said so - comes as `gone`, and
     * a bazaar whose page shows no listing at all as `empty`: every piece of it is gone.
     * @returns false when there was nothing to take
     */
    function notePage(S, what, now) {
        const whoId = String((what && what.whoId) || '');
        const at = Math.min(enNum(what && what.t) || now, now);
        if (!whoId || whoId === String(S.self.id) || !Array.isArray(what.items)) return false;
        const items = {};
        for (const r of what.items) {
            const id = String(r && r.id);
            const price = enWhole(r && r.price);
            const qty = enWhole(r && r.qty);
            if (!EN_PIECE_SET.has(id)) continue;
            if (r && r.gone) { if (!items[id]) items[id] = { price: 0, qty: 0, at }; continue; }
            if (!(price > 1) || !qty) continue;
            if (!items[id] || !items[id].qty || price < items[id].price) items[id] = { price, qty, at };
        }
        const empty = what.empty === true;
        if (!Object.keys(items).length && !empty) return false;
        const pages = {};
        for (const [k, v] of Object.entries(S.pages || {})) if (now - v.at < SHOP_KEEP_MS) pages[k] = v;
        const prev = pages[whoId];
        if (prev && prev.at >= at) return false;
        enBump(S, enShopPieces(S, whoId, items, prev ? prev.items : null));
        // A piece that was on the screen a moment ago and is not now (you scrolled on): its look stays, as old as it is.
        pages[whoId] = empty ? { at, items: {}, empty: true } : { at, items: { ...(prev && !prev.empty ? prev.items : {}), ...items } };
        S.pages = pages;
        return true;
    }

    /**
     * A piece's listings as the view takes them: its bazaars (Torn's own read of a bazaar, yours or the server's, wins
     * when newer than TornW3B's list; the bazaar's own page in a tab of yours wins over both), the bazaars only the
     * server knows of, and the Item Market.
     * Each row: `at` when it was looked at, `from` by whom, `ok` whether it counts (COUNT_MS, and "Read now").
     * @param ex (optional) { at }: set to the first moment the answer would be another one though nothing was read
     *           (a row grows too old to count, or to be kept): pileOf sorts the piece again then.
     */
    function offersOf(S, id, now, ex = null) {
        const key = String(id);
        const o = S.offers[key] || {};
        const out = [];
        const done = new Set();
        const own = ownBuys(S, now);
        const floor = Math.max(now - COUNT_MS, enNum(S.fresh && S.fresh.since));
        const soon = (t) => { if (ex && t < ex.at) ex.at = t; };
        const shopAt = (whoId) => { const shop = shopNow(S, whoId, now); if (shop) soon(shop.at + SHOP_KEEP_MS); return shop; };
        // `at`: when the bazaar was last looked at, and `from` by whom - 'torn' (Torn itself, by you or the server),
        // 'page' (its own page in a tab of yours) or 'w3b' (TornW3B's copy). The screen says both: a row is never shown
        // as newer than it is.
        const push = (whoId, price, units, at, from, ch) => {
            // Nobody has looked at it for an hour, or it is locked at $1: not offered.
            if (!(now - at < OFFER_KEEP_MS) || !(price > 1)) return;
            soon(at + OFFER_KEEP_MS);
            let qty = units;
            // What you bought there comes off, until a look that can have seen the buy shows the bazaar as it is.
            for (const b of own.get(key + ':' + whoId) || []) if (!lookedSince(at, ch, from, b.t)) { qty -= b.qty; soon(b.t + OWN_KEEP_MS); }
            if (!(qty > 0)) return;
            const ok = at >= floor;
            if (ok) soon(at + COUNT_MS + 1);
            out.push({ price, qty, src: 'bazaar', who: S.names[whoId] || null, whoId, at, from, ok });
        };
        const add = (whoId, price, units, at, from, ch = 0) => {
            const page = (S.pages || {})[whoId];
            let it = page ? page.items[key] : null;
            if (!it && page && page.empty) it = { price: 0, qty: 0, at: page.at };
            if (it && now - it.at < SHOP_KEEP_MS) soon(it.at + SHOP_KEEP_MS);
            // The page in front of you stands against a read of Torn made less than a minute after it - and against
            // TornW3B's copy until TornW3B found the bazaar changed that long after it (its "checked" alone moves on
            // while its copy is still the old one).
            const newer = (from === 'w3b' && ch > 0 ? ch : at) > (it ? it.at : 0) + PAGE_STANDS_MS;
            if (it && !newer && now - it.at < SHOP_KEEP_MS) push(whoId, it.price, it.qty, it.at, 'page', 0);
            else if (units > 0) push(whoId, price, units, at, from, ch);
        };
        if (o.bazAt && now - o.bazAt < LISTINGS_KEEP_MS) {
            soon(o.bazAt + LISTINGS_KEEP_MS);
            for (const r of o.baz || []) {
                done.add(String(r.whoId));
                const shop = shopAt(r.whoId);
                // TornW3B's row is as old as TornW3B's own last look at that bazaar, not as new as our asking for its
                // list: Torn's own read wins whenever it is the newer of the two (until 1.2.2 a list asked for after
                // Torn's read brought a sold-out listing back, and a buy of yours with it).
                const rowAt = Math.min(enNum(r.at) || o.bazAt, o.bazAt);
                // ... and TornW3B's later check counts as newer only when it found the bazaar changed since Torn's read:
                // a check that found nothing new has nothing to say against what Torn itself showed.
                if (shop && (shop.at > rowAt || (r.ch > 0 && !(r.ch > shop.at)))) {
                    const it = shop.items[key];
                    // Torn says this bazaar no longer has it: sold out or taken down (unless its page showed it since).
                    add(String(r.whoId), it ? it.price : 0, it ? it.qty : 0, shop.at, 'torn');
                } else {
                    add(String(r.whoId), r.price, r.qty, rowAt, 'w3b', enNum(r.ch));
                }
            }
        }
        // Bazaars you read from Torn yourself that TornW3B's list no longer names (its row grew old, or forty cheaper
        // ones came): they are still there, as Torn last showed them - for as long as a row of TornW3B's would count.
        for (const whoId of Object.keys(S.shops)) {
            if (done.has(whoId) || whoId === String(S.self.id)) continue;
            const shop = shopAt(whoId);
            const fresh = shop && now - shop.at < LISTING_FRESH_MS;
            if (fresh) soon(shop.at + LISTING_FRESH_MS);
            const it = fresh ? shop.items[key] : null;
            if (!it) continue;
            done.add(whoId);
            add(whoId, it.price, it.qty, shop.at, 'torn');
        }
        // Bazaars TornW3B's list does not name, read from Torn by the server.
        for (const s of svIndex(S).get(key) || []) {
            if (done.has(s.whoId) || s.whoId === String(S.self.id)) continue;
            done.add(s.whoId);
            const shop = shopAt(s.whoId);
            const it = shop && shop.items[key];
            if (it) add(s.whoId, it.price, it.qty, shop.at, 'torn');
        }
        // Bazaars known from their own page alone.
        for (const whoId of Object.keys(S.pages || {})) {
            if (done.has(whoId) || whoId === String(S.self.id)) continue;
            add(whoId, 0, 0, 0, 'page');
        }
        if (o.imAt && now - o.imAt < MARKET_KEEP_MS) {
            soon(o.imAt + MARKET_KEEP_MS);
            const ok = o.imAt >= floor;
            if (ok) soon(o.imAt + COUNT_MS + 1);
            for (const l of o.im || []) if (l.price > 1 && l.qty > 0) out.push({ price: l.price, qty: l.qty, src: 'market', at: o.imAt, from: 'torn', ok });
        }
        return out;
    }

    /** A pile is sorted again after this long whatever happened: no row can stand longer than this through a change the layer was not told of. */
    const PILE_MAX_MS = 30000;

    /**
     * The in-between layer: a piece's listings, cheapest first, sorted once and kept until an answer changes them
     * (enBump) or time does (a row too old to count). The rows are shared: nothing may write on them.
     * The owner, 2026-10-11: "we need some sort of intermediary state ... the one that does the hard filtering" - the
     * view's lists read from these through a shortlist (core/shortlist.js) and never sort the whole pile again.
     */
    function pileOf(S, id, now) {
        const key = String(id);
        const lay = S.lay || (S.lay = { all: 0, by: {}, piles: new Map() });
        const ver = lay.all + ':' + (lay.by[key] || 0);
        const had = lay.piles.get(key);
        if (had && had.ver === ver && now >= had.at && now < had.exp && now - had.at < PILE_MAX_MS) return had.rows;
        const ex = { at: Infinity };
        const rows = offersOf(S, id, now, ex).sort((a, b) => a.price - b.price);
        lay.piles.set(key, { ver, at: now, exp: ex.at, rows });
        lay.made = (lay.made || 0) + 1;
        return rows;
    }

    // ---- The points market, your money ----------------------------------------------------------------------------------

    /** @returns false when the answer held no listing that could be read */
    function foldPoints(S, json, now) {
        const listings = parsePointsMarket(json);
        if (!listings.length) return false;
        const price = listPrice(listings, 'wall');
        const near = listings.slice(0, EN_LOTS_READ);
        S.points = {
            listings: listings.slice(0, 150),
            at: now,
            days: recordPrice(S.points.days, now, price.lowest),
            wallDays: recordPrice(S.points.wallDays, now, price.wall || price.lowest),
            lots: lotsRead(S.points.lots, near, now, price.wall || 0),
        };
        return true;
    }

    /** @returns false when the answer had none of the names known for points, cash and vault */
    function foldMoney(S, m, now) {
        if (!m || (m.points == null && m.onHand == null && m.vault == null)) return false;
        S.money = { points: m.points, onHand: m.onHand, vault: m.vault, at: now };
        return true;
    }

    // ---- Stock ---------------------------------------------------------------------------------------------------------

    /**
     * Torn's inventory (api/torn.js fetchInventory's rows). The first read starts the count: what happened before it is
     * history, and the units held stand at what your newest buys of them cost (the rest at the market value).
     */
    function foldInventory(S, rows, now, tornAt = 0) {
        const inv = {};
        for (const r of mergeInventory(rows)) inv[String(r.id)] = r.qty;
        const mv = mvOf(S);
        const first = !(S.stock.invAt > 0);
        let stock = stockInventory(S.stock, inv, now, ENGINE_PIECES, mv, tornAt);
        if (first) {
            const pool = {};
            for (const id of ENGINE_PIECES) {
                const n = enWhole(stock.held[id]);
                if (!n) continue;
                let left = n;
                let cost = 0;
                for (let k = S.ledger.rows.length - 1; k >= 0 && left > 0; k--) {
                    const r = S.ledger.rows[k];
                    if (r.side !== 'buy' || String(r.itemId) !== id) continue;
                    const take = Math.min(left, enWhole(r.qty));
                    cost += take * enNum(r.each);
                    left -= take;
                }
                pool[id] = { n, cost: cost + left * mv(id), est: left };
            }
            stock = { ...stock, pool, floor: now };
            // The history is in now. A set swapped before the count began was costed, as its log row was read, at the
            // market value of its pieces (your buys of them may not have been read yet): now it takes what your own buys
            // on record say a set cost you then.
            const buys = enBuysByPiece(S);
            const book = S.book.map((e) => {
                const set = e.kind === 'made' && e.src === 'log' && !e.twin && e.set ? setByKey(e.set) : null;
                const cost = set ? enSetCostAt(set, e.t, buys, mv) : 0;
                return cost > 0 && set.points > 0 ? { ...e, each: cost / set.points } : e;
            });
            if (book.some((e, k) => e !== S.book[k])) S.book = book;
        }
        S.stock = stock;
    }

    /** Your buys of each piece on record: { itemId: [{ t, qty, each }] }. */
    function enBuysByPiece(S) {
        const by = {};
        for (const r of S.ledger.rows) {
            if (r.side !== 'buy' || !(enWhole(r.qty) > 0) || !(enNum(r.each) > 0)) continue;
            (by[String(r.itemId)] = by[String(r.itemId)] || []).push({ t: enNum(r.t), qty: enWhole(r.qty), each: enNum(r.each) });
        }
        return by;
    }

    /**
     * What a set cost you at a time in the history: each piece at the average of your buys of it up to then - or, with
     * none on record before then, of all your buys of it on record - and at its market value when you bought none.
     */
    function enSetCostAt(set, t, buys, mv) {
        const avg = (rows) => { const n = rows.reduce((s, r) => s + r.qty, 0); return n ? rows.reduce((s, r) => s + r.qty * r.each, 0) / n : 0; };
        return set.pieces.reduce((s, p) => {
            const rows = buys[String(p.id)] || [];
            return s + (avg(rows.filter((r) => r.t <= t)) || avg(rows) || mv(p.id));
        }, 0);
    }

    /**
     * A buy you were seen making on a bazaar page: counted at once.
     * While your log is read it waits beside the count until the log has been read past it (the log has it then).
     * `noLog` (no Full key, so no log): it goes into the count itself, once, as a log row would - Torn's inventory
     * may be an hour behind, and adding it on top for hours would count it twice once the inventory has it.
     * @returns false when it was not taken (not a piece, nothing bought, or told twice)
     */
    function noteSeenBuy(S, buy, now, { noLog = false } = {}) {
        if (!buy || !EN_PIECE_SET.has(String(buy.id)) || !(enWhole(buy.qty) > 0)) return false;
        const row = { t: enNum(buy.t) || now, id: String(buy.id), qty: enWhole(buy.qty), whoId: buy.whoId ? String(buy.whoId) : '', price: enWhole(buy.price), v: EN_SEEN_V, ...(buy.im ? { im: true } : {}) };
        if (S.seen.some((b) => b.t === row.t && b.id === row.id && b.whoId === row.whoId && b.qty === row.qty)) return false;
        if (noLog && enCounting(S)) {
            S.stock = stockApply(S.stock, eventFromSeen(row), mvOf(S)).state;
            row.counted = true;
        } else if (!noLog) {
            // The log was read between the buy and the page's look: its row is in the count already.
            const claimed = new Set(S.seen.map((b) => b.logged).filter(Boolean));
            const r = S.ledger.rows.find((x) => x.side === 'buy' && !claimed.has(x.id) && enSameBuy(row, x, EN_SAME_NOW_MS) && enWhole(x.qty) === row.qty);
            if (r) row.logged = r.id;
        }
        S.seen = [...S.seen.filter((b) => now - b.t < 6 * EN_HOUR), row].slice(-200);
        enBump(S, [row.id]);
        return true;
    }

    /** Torn's log has a buy at once; a buy a page told of is judged when the log was read this far past it. */
    const SEEN_JUDGE_MS = EN_MIN;

    /**
     * Torn's log is the judge of what a page saw (1.3.0). On 2026-10-11 ten of the 56 buys the page told of were not
     * buys at all (134 African Violets four times over): Torn's form had changed after its Buy and nothing was sold.
     * A buy seen on a page whose row is not in the log, though the log has been read a minute past it, is taken back:
     * `no` - out of the stock count, the run, the list and the seller's listing, everywhere at once. Before that it is
     * tied to its row where one is on record after all (a row read while the page's note was on its way).
     * Only with your log read (a Full key); a buy counted with no log to wait for (`counted`) is never judged.
     * @returns the buys taken back
     */
    function judgeSeen(S, now) {
        const until = enNum(S.log.until);
        if (!(until > 0)) return [];
        const open = new Set(S.seen.filter((b) => !b.counted && !b.logged && !b.no && b.t + SEEN_JUDGE_MS < until));
        if (!open.size) return [];
        const claimed = new Set(S.seen.map((b) => b.logged).filter(Boolean));
        const from = Math.min(...[...open].map((b) => b.t)) - EN_SAME_BUY_MS;
        const rows = S.ledger.rows.filter((r) => r.side === 'buy' && r.t >= from && (r.venue === 'bazaar' || r.venue === 'market'));
        const back = [];
        S.seen = S.seen.map((b) => {
            if (!open.has(b)) return b;
            let best = null;
            for (const r of rows) {
                if (claimed.has(r.id) || (r.venue === 'market') !== !!b.im || !enSameBuy(b, r, EN_SAME_BUY_MS)) continue;
                const same = enWhole(r.qty) === b.qty;
                if (!best || same > (enWhole(best.qty) === b.qty) || (same === (enWhole(best.qty) === b.qty) && Math.abs(b.t - r.t) < Math.abs(b.t - best.t))) best = r;
            }
            if (best) { claimed.add(best.id); return { ...b, logged: best.id }; }
            back.push(b);
            return { ...b, no: true, noAt: now };
        });
        enBump(S, back.map((b) => b.id));
        return back;
    }

    /**
     * A press of EXCHANGE on the museum page: the sets come off the count and their points go into the book at cost.
     * `noLog`: as for a buy seen on a page - with no log to confirm it, the count itself is moved, once.
     */
    function noteSwap(S, press, now, { noLog = false } = {}) {
        const set = press && setByKey(press.set);
        const sets = enWhole(press && press.sets);
        if (!set || !sets) return;
        const t = enNum(press.t) || now;
        const cost = enSetCost(S, set);
        const row = { t, set: set.key, sets };
        if (noLog && enCounting(S)) {
            S.stock = stockApply(S.stock, [{ key: 'seen-swap:' + t + ':' + set.key, t, swap: set.key, sets }], mvOf(S)).state;
            row.counted = true;
        }
        S.swaps = [...S.swaps.filter((p) => now - p.t < 6 * EN_HOUR), row].slice(-60);
        S.book = bookAdd(S.book, { id: 'page:' + t, t, kind: 'made', points: sets * set.points, each: cost > 0 ? cost / set.points : 0, set: set.key, src: 'page' }).slice(-EN_BOOK_KEPT);
    }

    /** A buy seen on a page and counted there is not counted again when the log brings the same buy later. */
    const EN_SAME_BUY_MS = 5 * EN_MIN;
    /** A buy told by the page after its log row was read: the row is its own only this close to it, with the same number. */
    const EN_SAME_NOW_MS = 2 * EN_MIN;
    const enSameBuy = (b, r, within) => b.id === String(r.itemId) && Math.abs(b.t - r.t) < within && (!b.whoId || !r.who || b.whoId === String(r.who));

    /**
     * A buy seen on a page waits beside the count for its row in Torn's log. The moment that row is in, the row is the
     * buy: what the page saw of it is no longer added on top. (Until 1.2.2 it stayed until the log had been read a
     * minute past it - with the log asked 20 seconds after a buy and then every two minutes, the same buy stood in the
     * count twice for two minutes: "need 141", bought, "141 ahead".) The log's number stands where the page's differs.
     */
    function enSeenInLog(S, rows) {
        let seen = S.seen;
        for (const r of rows) {
            if (!r || r.side !== 'buy') continue;
            let k = -1;
            seen.forEach((b, i) => {
                if (b.counted || b.logged || !enSameBuy(b, r, EN_SAME_BUY_MS)) return;
                const better = k < 0 || (b.qty === enWhole(r.qty)) > (seen[k].qty === enWhole(r.qty)) || ((b.qty === enWhole(r.qty)) === (seen[k].qty === enWhole(r.qty)) && Math.abs(b.t - r.t) < Math.abs(seen[k].t - r.t));
                if (better) k = i;
            });
            if (k >= 0) seen = seen.map((b, i) => (i === k ? { ...b, logged: r.id } : b));
        }
        S.seen = seen;
    }
    function enNotCounted(S, events) {
        const used = new Set();
        return events.filter((e) => {
            if (!(e.d > 0)) return true;
            const k = S.seen.findIndex((b, i) => b.counted && !used.has(i) && b.id === String(e.id) && b.qty === e.d && Math.abs(b.t - e.t) < EN_SAME_BUY_MS);
            if (k < 0) return true;
            used.add(k);
            return false;
        });
    }

    // ---- Your log ------------------------------------------------------------------------------------------------------

    /** The log types where money leaves your hand for somewhere safe, by their titles (no id is written here). */
    function outLogTypes(json) {
        const raw = json && (json.logtypes || json);
        const out = [];
        if (!raw || typeof raw !== 'object') return out;
        const rows = Array.isArray(raw) ? raw.map((r) => [r && r.id, r && r.title]) : Object.entries(raw);
        for (const [id, t] of rows) {
            const title = String((t && t.title) || t || '');
            if (id == null || !title) continue;
            if ((/\b(vault|bank)\b/i.test(title) && /\b(deposit|invest)/i.test(title)) || (/\btrade\b/i.test(title) && /\bmoney\b/i.test(title) && /\b(add|added|outgoing)\b/i.test(title))) out.push(Number(id));
        }
        return out;
    }

    const enCounting = (S) => S.stock.invAt > 0;
    /** What a set costs you (the cost pool), or its pieces' market value while the pool has not seen them all. */
    function enSetCost(S, set) {
        const own = poolSetCost(S.stock.pool, set);
        if (own > 0) return own;
        const mv = mvOf(S);
        return set.pieces.reduce((s, p) => s + mv(p.id), 0);
    }

    const EN_LEDGER_TYPES = [LOG_BAZAAR_BUY, LOG_MARKET_BUY, LOG_BAZAAR_SELL, LOG_MARKET_SELL];

    /** Every log type the engine asks for: buys and sales of items, mugs, points made / sold / used, money put away. */
    function logTypesAsked(types) {
        return [...new Set([...EN_LEDGER_TYPES, LOG_MUGGED, ...(types.made || []), ...(types.sold || []), ...(types.used || []), ...(types.out || [])])];
    }

    /** Torn's log is asked for this many kinds in one request, at most. */
    const LOG_TYPES_AT_ONCE = 8;

    /**
     * The same kinds, as the requests they are asked in: each sort by itself, and never more than LOG_TYPES_AT_ONCE.
     * On the owner's PC (2026-10-11, 1.1.0) one request naming all 18 kinds came back with no row at all for 14
     * days - with a working Full key and hundreds of bazaar buys that day - while Torn Trading, which names 8,
     * gets its rows. That the number was the cause is not proven; asked like this, the log says what each sort
     * brought (engine readLog).
     * @returns [{ name, ids }]
     */
    function logTypeGroups(types) {
        const sorts = [
            ['buys and sales', [...EN_LEDGER_TYPES, LOG_MUGGED]],
            ['points', [...(types.made || []), ...(types.sold || []), ...(types.used || [])]],
            ['money put away', types.out || []],
        ];
        const out = [];
        for (const [name, all] of sorts) {
            const ids = [...new Set(all)];
            for (let i = 0; i < ids.length; i += LOG_TYPES_AT_ONCE) out.push({ name, ids: ids.slice(i, i + LOG_TYPES_AT_ONCE) });
        }
        return out;
    }

    function enAddRows(S, rows) {
        const have = new Set(S.ledger.rows.map((r) => r.id));
        const fresh = rows.filter((r) => r && !have.has(r.id));
        if (!fresh.length) return [];
        const all = [...S.ledger.rows, ...fresh].sort((a, b) => a.t - b.t || String(a.id).localeCompare(String(b.id))).slice(-EN_ROWS_KEPT);
        S.ledger = { ...S.ledger, rows: all };
        // A buy of yours comes off its seller's listing (ownBuys).
        enBump(S, fresh.filter((r) => r.side === 'buy' && r.venue === 'bazaar').map((r) => r.itemId));
        return fresh;
    }

    const EN_DIRECT_KEPT = 400;
    /**
     * Pieces that left as themselves - sold in your bazaar, on the Item Market or in a trade, or given away - booked
     * with what they had cost you (the pool's average then). Until 1.3.0 they left the pool and the money was nowhere.
     * @param rows the Ledger rows just added
     * @param outs stockApply's `out`
     */
    function enAddDirect(S, rows, outs) {
        const by = new Map((rows || []).map((r) => ['row:' + r.id, r]));
        const add = [];
        for (const o of outs || []) {
            const r = by.get(o.key);
            if (!r || !(o.units > 0)) continue;
            const sold = r.side === 'sell';
            add.push({ id: r.id, t: r.t, itemId: String(r.itemId), qty: o.units, got: sold ? Math.round(o.units * enNum(r.each) - enNum(r.fee) * o.units / Math.max(1, enNum(r.qty))) : 0, cost: o.cost, venue: r.venue, give: !sold, est: Math.round(enNum(o.est) * 1000) / 1000 });
        }
        if (add.length) S.ledger = { ...S.ledger, direct: [...(S.ledger.direct || []), ...add].sort((a, b) => a.t - b.t).slice(-EN_DIRECT_KEPT) };
    }

    /**
     * A mug's verdict (did it take points money, and how much) is kept once it can no longer change: an hour old, the
     * log read past it, and every money row around it still on record. The rows it was judged by are let go later.
     * @param rows the view's ledger.mugs.rows
     * @returns true when a verdict was kept
     */
    function settleMugs(S, rows, now) {
        const from = S.outs.length >= EN_OUTS_KEPT ? enNum(S.outs[0].t) : 0;
        const by = new Map((rows || []).map((r) => [r.id, r]));
        let any = false;
        const mugs = S.ledger.mugs.map((m) => {
            const r = by.get(m.id);
            if (m.kept || !r || !(m.t < now - EN_HOUR) || !(S.log.until >= m.t) || m.t < from) return m;
            any = true;
            return { ...m, kept: { counted: enWhole(r.counted), onHand: enWhole(r.onHand), saleId: r.saleId || null, after: enNum(r.after) } };
        });
        if (any) S.ledger = { ...S.ledger, mugs };
        return any;
    }

    function enAddOuts(S, outs) {
        if (!outs.length) return;
        const have = new Set(S.outs.map((o) => o.id));
        const fresh = outs.filter((o) => o.amount > 0 && !have.has(o.id));
        if (fresh.length) S.outs = [...S.outs, ...fresh].sort((a, b) => a.t - b.t).slice(-EN_OUTS_KEPT);
    }

    const enAmount = (data) => {
        for (const k of ['deposited', 'money', 'amount', 'value', 'cost', 'total']) {
            const n = Number(data && data[k]);
            if (Number.isFinite(n) && n > 0) return n;
        }
        return 0;
    };

    /**
     * One page of your log (Torn's v2 rows, any order).
     * @param ctx { now, priceNow } - priceNow = the points price, for points used
     * @returns { unread: [{ type, title, keys }], newest (s), oldest (s), rows: how many were new to the books }
     */
    function foldLog(S, logRows, ctx) {
        const types = S.types;
        const out = { unread: [], newest: 0, oldest: 0, rows: 0 };
        const pieceRows = [];
        const outs = [];
        const mugs = [];
        const events = [];
        const swaps = [];
        let book = S.book;
        let madeRead = S.log.madeRead;
        for (const row of [...(logRows || [])].sort((a, b) => enNum(a && a.timestamp) - enNum(b && b.timestamp))) {
            if (!row || !row.details) continue;
            const ts = enNum(row.timestamp);
            if (ts) { out.newest = Math.max(out.newest, ts); out.oldest = out.oldest ? Math.min(out.oldest, ts) : ts; }
            const type = Number(row.details.id);
            if (EN_LEDGER_TYPES.includes(type)) {
                const rows = rowsFromLog(row);
                // Money that left your hand: whatever you bought, a set piece or not.
                for (const r of rows) if (r.side === 'buy') outs.push({ id: 'buy:' + r.id, t: r.t, amount: Math.round(r.qty * r.each) });
                pieceRows.push(...rows.filter((r) => isSetItem(r.itemId)));
                continue;
            }
            if (type === LOG_MUGGED) { const m = mugFromLog(row); if (m) mugs.push(m); continue; }
            if ((types.out || []).includes(type)) {
                const amount = enAmount(row.data);
                if (amount) outs.push({ id: 'log:' + row.id, t: ts * 1000, amount });
                else out.unread.push({ type, title: String(row.details.title || ''), keys: Object.keys(row.data || {}).slice(0, 12) });
                continue;
            }
            const entry = entryFromLog(row.id, row, types, { priceNow: ctx.priceNow });
            if (!entry) {
                if ([...types.made, ...types.sold, ...types.used].includes(type)) out.unread.push({ type, title: String(row.details.title || ''), keys: Object.keys(row.data || {}).slice(0, 12) });
                continue;
            }
            if (entry.kind !== 'made') { book = bookAdd(book, entry); continue; }
            madeRead = true;
            const set = entry.set ? setByKey(entry.set) : null;
            if (!set) { out.unread.push({ type, title: String(row.details.title || ''), keys: Object.keys(row.data || {}).slice(0, 12) }); continue; }
            swaps.push({ entry, set });
            events.push({ key: entry.id, t: entry.t, swap: set.key, sets: Math.round(entry.points / set.points) });
        }
        const fresh = enAddRows(S, pieceRows);
        out.rows = fresh.length;
        if (enCounting(S)) enSeenInLog(S, fresh);
        enAddOuts(S, outs);
        if (mugs.length) {
            const have = new Set(S.ledger.mugs.map((m) => m.id));
            const add = mugs.filter((m) => !have.has(m.id)).map((m) => ({ id: m.id, t: m.t, who: m.who, taken: enWhole(m.amount) }));
            if (add.length) S.ledger = { ...S.ledger, mugs: [...S.ledger.mugs, ...add].sort((a, b) => a.t - b.t).slice(-300) };
        }
        // Buys, sales and swaps move the stock count and the cost pool; a swap's points take what its pieces cost.
        // Not before Torn's inventory has been read once: until then the log is history, and the count starts there.
        const applied = enCounting(S) ? stockApply(S.stock, [...enNotCounted(S, eventsFromRows(fresh, EN_PIECE_SET)), ...events], mvOf(S)) : { state: S.stock, made: [], out: [] };
        S.stock = applied.state;
        enAddDirect(S, fresh, applied.out);
        const costBy = new Map(applied.made.map((m) => [m.key, m]));
        for (const { entry, set } of swaps) {
            const made = costBy.get(entry.id);
            // A swap from before the count began: its cost is what a set of it costs you now, or its market value.
            const each = made && made.points ? made.cost / made.points : enSetCost(S, set) / set.points;
            book = bookAdd(book, { ...entry, each: each > 0 ? each : 0, ...(made && made.points ? { est: made.est } : {}) });
        }
        const until = out.newest ? Math.max(S.log.until, out.newest * 1000) : S.log.until;
        book = bookSettle(book, madeRead ? Math.max(until, ctx.now - EN_MIN) : 0);
        if (book !== S.book) S.book = book.slice(-EN_BOOK_KEPT);
        S.log = { ...S.log, madeRead };
        return out;
    }

    /** Torn's list of log types, kept for a week (core/points.js pointsLogTypes plus the money-out types). */
    function foldLogTypes(S, pointsTypes, outTypes, now) {
        S.types = { at: now, made: pointsTypes.made || [], sold: pointsTypes.sold || [], used: pointsTypes.used || [], out: outTypes || [], titles: pointsTypes.titles || {} };
    }

    // ---- Trades --------------------------------------------------------------------------------------------------------

    /**
     * Your open trades, as Torn lists them.
     * @returns { fresh: [trade] new since the last look, closed: [trade] open before and not now, read: [id] to read in full }
     */
    function foldTradeList(S, trades, now) {
        const list = parseTradeList({ trades }, S.self.id);
        for (const t of list) enName(S, t.whoId, t.who);
        const { seen, fresh } = tradesSeen(S.trades.seen, list);
        const closed = tradesClosed(S.trades.open, list);
        const by = new Map(S.trades.open.map((t) => [t.id, t]));
        const full = {};
        const open = [];
        for (const t of list) {
            const had = by.get(t.id);
            open.push(had ? { ...had, modified: t.modified, expires: t.expires } : { ...t, theirs: [], theirMoney: 0, mine: [], myMoney: 0, other: 0 });
            if (had && S.trades.full[t.id] != null) full[t.id] = S.trades.full[t.id];
        }
        // Every open trade is read in full again each round, the one read longest ago first. Torn's `modified_at`
        // does not move when items are put in: the owner's trade of 2026-10-11 was read once, seconds after it was
        // opened and still empty, and - its time never changing - not again for as long as it was open.
        const read = list.map((t) => t.id).sort((a, b) => (full[a] || 0) - (full[b] || 0));
        S.trades = { ...S.trades, open, at: now, seen, full };
        return { fresh, closed, read };
    }

    /** One open trade read in full (Torn's `trade` object). `full` keeps when: the list above reads the oldest first. */
    function foldTradeOpen(S, trade, now = 0) {
        const t = parseTrade({ trade }, S.self.id);
        if (!t) return null;
        if (!S.trades.open.some((x) => x.id === t.id)) return null;
        S.trades = { ...S.trades, open: S.trades.open.map((x) => (x.id === t.id ? t : x)), full: { ...S.trades.full, [t.id]: now || t.modified || 1 } };
        return t;
    }

    /** Trades with a piece of your sets on their side: the ones the Archive shows and tells you of. */
    const tradeHasPieces = (t) => !!t && (t.theirs || []).some((x) => isSetItem(x.id));

    /** A finished trade read in full: its buys go to the books, the trade to the finished list. */
    function foldTradeFinished(S, trade, now) {
        if (!trade || trade.id == null) return false;
        const id = String(trade.id);
        if (S.ledger.tradeIds.includes(id)) return false;
        S.ledger = { ...S.ledger, tradeIds: [...S.ledger.tradeIds, id].slice(-600) };
        const mv = mvOf(S);
        const rows = enTradeRows(S, trade);
        const t = parseTrade({ trade }, S.self.id);
        if (!t) return false;
        const done = enNum(trade.completed_at || trade.timestamp || trade.modified_at) * 1000 || now;
        if (t.myMoney > 0) enAddOuts(S, [{ id: 'trade:' + id, t: done, amount: t.myMoney }]);
        const fresh = enAddRows(S, rows);
        if (enCounting(S)) {
            const applied = stockApply(S.stock, eventsFromRows(fresh, EN_PIECE_SET), mv);
            S.stock = applied.state;
            enAddDirect(S, fresh, applied.out);
        }
        const got = t.theirs.filter((x) => isSetItem(x.id));
        if (got.length && t.myMoney > 0) {
            enName(S, t.whoId, t.who);
            // What of your money went to the pieces: all of it, unless the trade held other things too.
            const paid = Math.round(rows.filter((r) => r.side === 'buy').reduce((s, r) => s + r.qty * r.each, 0));
            const entry = { id, who: t.who, whoId: t.whoId, t: done, units: got.reduce((s, x) => s + x.qty, 0), paid, mv: got.reduce((s, x) => s + x.qty * mv(x.id), 0), rows: got.map((x) => ({ id: x.id, qty: x.qty })) };
            S.trades = { ...S.trades, finished: [entry, ...S.trades.finished.filter((f) => f.id !== id)].sort((a, b) => b.t - a.t).slice(0, EN_FINISHED_KEPT) };
        }
        return true;
    }

    /**
     * A trade's rows of set pieces. The money is shared over everything in the trade by Torn's market value. Until
     * 1.3.0 anything that was not a set piece took none of it: a trade for other things with one flower in it priced
     * that flower with the whole trade (the owner's trade of 2026-10-03: one Ceibo Flower at $279,918,109).
     */
    function enTradeRows(S, trade) {
        const mv = mvOf(S);
        return rowsFromTrade(trade, S.self.id, (itemId) => Math.max(1, mv(itemId))).filter((r) => isSetItem(r.itemId));
    }

    /** A trade row prices a piece at over this many times its market value: its trade is read again (enTradeRows). */
    const TRADE_ODD_TIMES = 3;

    /** The trades on record that priced a piece far over its market value: their ids, the newest first. */
    function tradesOdd(S) {
        const mv = mvOf(S);
        const ids = new Set();
        for (let k = S.ledger.rows.length - 1; k >= 0; k--) {
            const r = S.ledger.rows[k];
            if (r.venue !== 'trade' || r.side !== 'buy' || r.fixed) continue;
            const v = mv(r.itemId);
            if (v > 0 && enNum(r.each) > v * TRADE_ODD_TIMES) ids.add(String(r.id).split(':')[1]);
        }
        return [...ids];
    }

    /**
     * A finished trade read again: its rows on record take the price worked out now. Nothing is added and the count
     * is not moved - only what a unit is said to have cost. `fixed` marks a row looked at, right or not.
     * @returns how many rows changed their price
     */
    function foldTradeReprice(S, tradeId, trade) {
        const by = new Map((trade ? enTradeRows(S, trade) : []).map((r) => [r.id, r]));
        const head = 'trade:' + tradeId + ':';
        let n = 0;
        const rows = S.ledger.rows.map((r) => {
            if (!String(r.id).startsWith(head)) return r;
            const now = by.get(r.id);
            if (now && Math.round(now.each) !== Math.round(r.each)) n += 1;
            return { ...r, ...(now ? { each: now.each } : {}), fixed: true };
        });
        S.ledger = { ...S.ledger, rows };
        if (n) {
            const paid = Math.round(rows.filter((r) => String(r.id).startsWith(head) && r.side === 'buy').reduce((s, r) => s + r.qty * r.each, 0));
            S.trades = { ...S.trades, finished: S.trades.finished.map((f) => (f.id === String(tradeId) ? { ...f, paid } : f)) };
        }
        return n;
    }

    // ---- Your thread, your TornW3B list --------------------------------------------------------------------------------

    /** Your own forum threads (v2 user/forumthreads): the newest whose title reads as a buying thread for sets. */
    function foldThreads(S, json, now) {
        const rows = (json && (json.forumThreads || json.forumthreads || json.threads)) || [];
        const mine = (Array.isArray(rows) ? rows : Object.values(rows)).filter((t) => t && t.title && isBuyingTitle(t.title));
        mine.sort((a, b) => enNum(b.last_post_time ?? b.first_post_time) - enNum(a.last_post_time ?? a.first_post_time));
        S.thread = mine.length ? { id: mine[0].id, title: String(mine[0].title), at: now, forum: mine[0].forum_id ?? null } : null;
    }

    /** The thread's title as read on its own page: newer than the API's. */
    function noteThread(S, thread, now) {
        if (!thread || !thread.title || !isBuyingTitle(thread.title)) return;
        S.thread = { ...(S.thread || {}), id: thread.id ?? (S.thread && S.thread.id) ?? null, title: String(thread.title), at: now };
    }

    function foldOwnList(S, json, now) {
        const list = parseOwnList(json);
        S.w3b = { ...S.w3b, list: [...list], listAt: now, error: '' };
    }

    function foldReceipt(S, tradeId, receipt, now) {
        const rest = S.w3b.receipts.filter(([id]) => id !== String(tradeId));
        S.w3b = { ...S.w3b, receipts: [...rest, [String(tradeId), { id: receipt.id ?? null, total: enWhole(receipt.total), url: receipt.url || '', at: now }]].slice(-300), lastReceiptAt: Math.max(S.w3b.lastReceiptAt, now) };
    }

    // ---- What is kept by day -------------------------------------------------------------------------------------------

    /** One look at the view into the day's lines: each piece's cheapest, what a set pays, your money's share in sets. */
    function recordDay(S, view, now) {
        const day = enDay(now);
        const low = { ...S.hist.low };
        for (const p of view.pieces || []) {
            // The cheapest anywhere, not only where you buy: the record is of the price.
            const lo = p.lowAll || p.low;
            // $1 or less is a locked listing, never a price.
            if (!lo || !(lo.price > 1)) continue;
            const list = (low[p.id] || []).filter((d) => d.day !== day);
            const cur = (low[p.id] || []).find((d) => d.day === day);
            low[p.id] = [...list, { day, low: cur ? Math.min(cur.low, lo.price) : lo.price }].slice(-14);
        }
        let pays = S.hist.pays;
        const paid = {};
        for (const s of view.sets || []) if (s.pays != null) paid[s.key] = s.pays;
        if (Object.keys(paid).length) pays = [...pays.filter((d) => d.day !== day), { ...(pays.find((d) => d.day === day) || {}), day, ...paid }].slice(-40);
        let share = S.hist.share;
        if (view.share && view.share.total > 0) share = [...share.filter((d) => d.day !== day), { day, share: Math.round(view.share.share * 10) / 10 }].slice(-40);
        S.hist = { low, pays, share };
    }

    // ---- The view's input ----------------------------------------------------------------------------------------------

    /** Everything core/view.js's archiveView() takes, from the state. */
    function engineInput(S, settings, now, { logRead = false } = {}) {
        const mv = mvOf(S);
        const itemName = nameOf(S);
        const full = S.trades.full || {};
        return {
            now, settings,
            held: stockHeld(S.stock, S.seen, S.swaps, S.log.until),
            stockAt: S.stock.invAt || 0,
            // How old Torn's own count is, and whether your log carries what happened since.
            stock: { ...stockAge(S.stock), log: !!logRead },
            mv,
            // The in-between layer: every listing of a piece, cheapest first, sorted only when an answer moved it.
            // The rows are shared with the layer: the view reads them and never writes on one.
            offers: (id) => pileOf(S, id, now),
            // Buys a page told of that Torn's log does not have (judgeSeen), for a few minutes: said once on the screen.
            back: S.seen.filter((b) => b.no && now - enNum(b.noAt) < 10 * EN_MIN).map((b) => ({ id: b.id, qty: b.qty, whoId: b.whoId || '', im: !!b.im, t: b.t })),
            direct: S.ledger.direct || [],
            priced: (id) => { const o = S.offers[String(id)]; return !!(o && (o.imAt || o.bazAt)) || svIndex(S).has(String(id)); },
            pricesAt: Math.max(S.summary.at || 0, ...Object.values(S.offers).map((o) => Math.max(o.bazAt || 0, o.imAt || 0)), 0),
            topBid: (id) => { const b = S.bids[String(id)]; const v = mv(id); return b && b.price > 0 && v > 0 ? { pct: Math.round(b.price / v * 1000) / 10, name: b.name, price: b.price, at: b.at } : null; },
            // What you pay your sellers, fixed for the hour (core/sellrate.js): null while nothing is fixed.
            rate: (S.rate && S.rate.table) || null, rateSent: (S.rate && S.rate.sent) || 0,
            listings: S.points.listings, pointsAt: S.points.at, days: S.points.days, wallDays: S.points.wallDays,
            lots: S.points.lots, mineLots: [],
            pool: S.stock.pool, book: S.book,
            mugs: S.ledger.mugs.map((m) => ({ id: m.id, t: m.t, by: (m.who && S.names[m.who]) || '', taken: m.taken, ...(m.kept ? { kept: m.kept } : {}) })),
            outs: S.outs,
            // Money rows are kept EN_OUTS_KEPT deep: once that many are held, the oldest is where the record begins.
            outsFrom: S.outs.length >= EN_OUTS_KEPT ? enNum(S.outs[0].t) : 0,
            money: { points: S.money.points, onHand: S.money.onHand, vault: S.money.vault },
            // Only trades read in full, with a piece of your sets on their side.
            trades: S.trades.open.filter((t) => full[t.id] != null && tradeHasPieces(t)).map((t) => ({ ...t, readAt: enNum(full[t.id]) })),
            finished: S.trades.finished,
            rows: S.ledger.rows,
            cart: S.cart, run: S.run, hotSince: S.hot,
            kept: settings.targetMode !== 'number' && S.cart.length && S.plan && S.plan.targets ? S.plan.targets : null,
            thread: S.thread,
            w3b: { list: S.w3b.list ? new Map(S.w3b.list) : null, listAt: S.w3b.listAt, receipts: new Map(S.w3b.receipts), lastReceiptAt: S.w3b.lastReceiptAt, error: S.w3b.error, receiptsError: S.w3b.receiptsError || '' },
            hist: S.hist,
            names: (id) => S.names[String(id)] || '',
            itemName,
            me: S.self.id,
        };
    }

    /** The item a set piece belongs to, for callers outside this file. */
    const pieceSet = (id) => setOfItem(id);

    /* ===== src/core/settings.js ===== */
    // Torn Archive's settings: what is stored, made safe. Pure.

    const stNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const stWhole = (v) => Math.max(0, Math.floor(stNum(v)));
    const stOne = (v, choices, fallback) => (choices.includes(v) ? v : fallback);

    /** How often the pieces' prices are read, in minutes. */
    const READ_CHOICES = [1, 2, 5, 10];
    const NOTIFY_CHOICES = ['browser', 'app', 'off'];

    /** A new install buys nothing and says nothing: the shop starts closed. */
    const ARCHIVE_DEFAULTS = Object.freeze({
        which: Object.freeze({ plushie: true, flower: true }),
        open: false,
        pct: 101,
        least: 2,
        targetMode: 'cash',
        target: 40,
        shareMax: 30,
        readMin: 1,
        pointsRule: 'wall',
        cheapRule: 'hold',
        fillMuseum: true,
        fillPoints: true,
        notify: 'browser',
        sound: false,
        beforeEach: 0,
        w3bSync: false,
        from: Object.freeze({ bazaar: true, market: true }),
    });

    /** Stored settings made safe: unknown keys dropped, numbers inside their range. */
    function archiveSettings(stored) {
        const s = stored && typeof stored === 'object' ? stored : {};
        const d = ARCHIVE_DEFAULTS;
        const which = s.which && typeof s.which === 'object' ? s.which : {};
        const from = s.from && typeof s.from === 'object' ? s.from : {};
        const pct = stNum(s.pct);
        const least = Number(s.least);
        const share = Number(s.shareMax);
        const out = {
            which: { plushie: which.plushie !== false, flower: which.flower !== false },
            open: s.open === true,
            pct: pct >= 50 && pct <= 200 ? Math.round(pct * 10) / 10 : d.pct,
            least: Number.isFinite(least) && least >= 0 && least <= 50 ? Math.round(least * 10) / 10 : d.least,
            targetMode: s.targetMode === 'number' ? 'number' : 'cash',
            target: stWhole(s.target) >= 1 ? Math.min(100000, stWhole(s.target)) : d.target,
            // 0 = no limit on the share of your money in sets and points.
            shareMax: Number.isFinite(share) && share >= 0 && share <= 100 ? Math.round(share) : d.shareMax,
            readMin: stOne(Number(s.readMin), READ_CHOICES, d.readMin),
            pointsRule: s.pointsRule === 'lowest' ? 'lowest' : 'wall',
            cheapRule: s.cheapRule === 'tell' ? 'tell' : 'hold',
            fillMuseum: s.fillMuseum !== false,
            fillPoints: s.fillPoints !== false,
            notify: stOne(s.notify, NOTIFY_CHOICES, d.notify),
            sound: s.sound === true,
            // What a point you held before Torn Archive stands at, if you typed it (0 = left alone).
            beforeEach: stNum(s.beforeEach) > 0 ? stWhole(s.beforeEach) : 0,
            // Keep your TornW3B price list at your rate by itself (needs the key you registered there).
            w3bSync: s.w3bSync === true,
            // Where a list may send you to buy: bazaars, the Item Market, or both.
            from: { bazaar: from.bazaar !== false, market: from.market !== false },
        };
        // Both sets off is no shop at all: the last one stays on.
        if (!out.which.plushie && !out.which.flower) out.which = { ...d.which };
        // Nowhere to buy is no list at all: both stay on.
        if (!out.from.bazaar && !out.from.market) out.from = { ...d.from };
        return out;
    }

    /** The settings as sets.js reads them (its `on` switch is Torn Bids'; here Sets is the whole app). */
    const setsCtx = (settings) => ({ on: true, which: settings.which });

    /** Whether a listing is in a place you buy from (settings.from): the Item Market, or a bazaar. */
    const buysFrom = (settings) => {
        const from = (settings && settings.from) || {};
        return (o) => (o && o.src === 'market' ? from.market !== false : from.bazaar !== false);
    };

    /* ===== src/core/margin.js ===== */
    // Margins: one rule for "safe", used everywhere a price is judged.
    // A buy is safe when it still leaves your least profit at the points price now. A piece's share of that is its
    // market value's share of the set, so a trade of loose pieces and a whole set are judged by the same sum.
    // Pure working-out: no page, no storage. The points market takes no fee: nothing is taken off for one.



    const mgNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const mgWhole = (v) => Math.max(0, Math.floor(mgNum(v)));

    /** What one unit of a piece brings at the points price: the set's value shared by market value. Not rounded. */
    function pieceBrings(itemId, mv, pointsPrice) {
        const set = setOfItem(itemId);
        if (!set) return 0;
        const total = setMarketValue(set, mv);
        const value = setValue(set, pointsPrice);
        return total && value ? value * mgWhole(mv(itemId)) / total : 0;
    }

    /**
     * The most a unit may cost and still leave your least profit: what it brings, less that share.
     * A listing is taken only while its price is UNDER this. Whole dollars, rounded down.
     */
    function safeWorth(itemId, mv, pointsPrice, leastPct = 0) {
        const brings = pieceBrings(itemId, mv, pointsPrice);
        return brings ? Math.floor(brings / (1 + Math.max(0, mgNum(leastPct)) / 100)) : 0;
    }

    /** Every piece of a set at its safe worth: itemId -> dollars (0 when it cannot be worked out). */
    function safeWorths(set, mv, pointsPrice, leastPct = 0) {
        const out = new Map();
        for (const p of set.pieces) out.set(String(p.id), safeWorth(p.id, mv, pointsPrice, leastPct));
        return out;
    }

    /**
     * What a handful of units leaves at the points price now.
     * @param lines [{ id, qty, each }] set pieces only; a line that is no set piece, or has no price, is passed over
     * @returns { units, paid, brings, leaves, pct, ok } - pct is leaves as a share of what is paid; ok = it keeps `leastPct`
     */
    function leavesOf(lines, mv, pointsPrice, leastPct = 0) {
        let units = 0;
        let paid = 0;
        let brings = 0;
        for (const l of lines || []) {
            const qty = mgWhole(l && l.qty);
            const each = mgNum(l && l.each);
            const one = l ? pieceBrings(l.id, mv, pointsPrice) : 0;
            if (!qty || !(each > 0) || !one) continue;
            units += qty;
            paid += qty * each;
            brings += qty * one;
        }
        paid = Math.round(paid);
        const leaves = Math.round(brings - paid);
        const pct = paid > 0 ? leaves / paid * 100 : 0;
        return { units, paid, brings: Math.round(brings), leaves, pct, ok: paid > 0 && pct >= Math.max(0, mgNum(leastPct)) - 1e-9 };
    }

    /**
     * The highest rate (percent of market value, one decimal, rounded down) at which these sets still keep the least
     * profit: the lowest of the caps of the sets named. 0 when it cannot be said.
     */
    function mendRate(sets, mv, pointsPrice, leastPct = 0) {
        let cap = Infinity;
        for (const set of sets || []) {
            const market = setMarketValue(set, mv);
            const value = setValue(set, pointsPrice);
            if (!market || !value) return 0;
            cap = Math.min(cap, Math.floor(value / (1 + Math.max(0, mgNum(leastPct)) / 100) / market * 1000) / 10);
        }
        return Number.isFinite(cap) ? cap : 0;
    }

    /**
     * The margin line of a trade.
     * @param offer tradeOffer()'s result
     * @returns {
     *   all, need   leavesOf() for everything priced in the trade, and for only the units you need
     *   held        dollars paid for units you do not need yet: they pay only when the rest of their set arrives
     *   others      names in the trade that are no set piece: not priced, the total does not cover them
     *   mend        the rate that would bring the trade back to your least profit (0 when it is already kept)
     *   state       'ok' | 'under' (under your least profit: the points price fell) | 'loss' | 'none' (nothing priced)
     * }
     */
    function tradeMargin(offer, { mv, pointsPrice, leastPct = 0 }) {
        const priced = ((offer && offer.rows) || []).filter((r) => r.each > 0 && r.state !== 'other');
        const all = leavesOf(priced.map((r) => ({ id: r.id, qty: r.qty, each: r.each })), mv, pointsPrice, leastPct);
        const need = leavesOf(priced.filter((r) => r.take > 0).map((r) => ({ id: r.id, qty: r.take, each: r.each })), mv, pointsPrice, leastPct);
        const held = priced.reduce((s, r) => s + mgWhole(r.extra) * r.each, 0);
        const others = ((offer && offer.rows) || []).filter((r) => r.state === 'other').map((r) => r.name || ('item ' + r.id));
        const sets = [...new Set(priced.map((r) => setOfItem(r.id)).filter(Boolean))];
        let state = 'none';
        if (all.units) state = all.ok ? 'ok' : all.leaves < 0 ? 'loss' : 'under';
        return { all, need, held, others, mend: state === 'ok' || state === 'none' ? 0 : mendRate(sets, mv, pointsPrice, leastPct), state };
    }

    /**
     * The margin line of one place that sells (a bazaar, or the Item Market): what you would take there.
     * @param takes [{ id, take, price }]
     */
    function placeMargin(takes, { mv, pointsPrice, leastPct = 0 }) {
        return leavesOf((takes || []).map((t) => ({ id: t.id, qty: t.take, each: t.price })), mv, pointsPrice, leastPct);
    }

    /** The words of a margin line: "leaves +$1,234, 2.4%". The sign is always shown. */
    function marginWords(m) {
        if (!m || !m.units) return '';
        const sign = m.leaves < 0 ? '-' : '+';
        return 'leaves ' + sign + '$' + Math.abs(m.leaves).toLocaleString('en-US') + ', ' + (Math.round(m.pct * 10) / 10).toFixed(1) + '%';
    }

    /* ===== src/core/setjudge.js ===== */
    // A listing judged on the SET it would finish, not on the piece alone. Pure working-out.
    //
    // The owner, 2026-10-11: "yes whole set is how i think about it" - a Kitten $100 over its share is nothing, a Camel
    // at 75k where its share is 70k is a lot. So the sets you are still to finish are walked in turn, the cheapest
    // units first. A set has room: what its other pieces are UNDER their share by - the pieces you already hold at
    // what they cost you, the pieces still to buy at their cheapest listing. A unit at or under its own share is always
    // worth buying (it can never be what breaks a set). A unit over its share is
    //   Buy        while the set's room covers it: the set still pays at today's points price with your least profit;
    //   Stretch    when it only pays at the price you usually sell points for;
    //   No thanks  when it is over even that.
    // Nothing here is a typed money figure: every line is the set's own value against what its pieces cost.

    const sjNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const sjWhole = (v) => Math.max(0, Math.floor(sjNum(v)));

    /**
     * The price you usually sell points for: your own sales of the last two weeks, each lot by its size. With none on
     * record, the middle of the market's usual range (points.js usualLevel). 0 when neither says.
     * @param entries the points book's entries [{ kind, t, points, each }]
     * @param level   { lo, hi } | { days }
     */
    function usualSell(entries, level, now, days = 14) {
        let points = 0;
        let got = 0;
        for (const e of entries || []) {
            if (!e || e.kind !== 'sold' || !(e.each > 0) || !(now - e.t < days * 86400000)) continue;
            points += sjWhole(e.points);
            got += sjWhole(e.points) * sjNum(e.each);
        }
        if (points > 0) return { price: Math.round(got / points), from: 'sales', points };
        if (level && level.lo > 0 && level.hi > 0) return { price: Math.round((level.lo + level.hi) / 2), from: 'market', points: 0 };
        return { price: 0, from: '', points: 0 };
    }

    /**
     * One set's listings sorted into the three groups.
     * @param set { points, pieces: [{ id }] }
     * @param o {
     *   target        sets you build
     *   held(id)      units you hold
     *   avg(id)       what a unit you hold cost you (the pool's average); 0 = none on record: it counts for nothing
     *   guide(id)     the piece's share of the set with your least profit taken off (margin.js safeWorth): a unit is
     *                 worth buying by itself while its price is UNDER this
     *   rows(id)      the listings that count, cheapest first: [{ price, qty }]
     *   more          dollars a set may cost on top at the price you usually sell points for (0: no Stretch group)
     *   perMore       dollars of `more` that one dollar of points price buys (set.points / (1 + least)): to say the
     *                 points price a Stretch unit needs
     *   priceNow      today's points price
     * }
     * @returns {
     *   pieces: Map id -> { buy, line, stretch, lineS, fin, takeLine, needs }
     *     buy / stretch  units in each group, the cheapest first (No thanks is the rest)
     *     line           a unit is Buy while its price is UNDER this (never under the guide)
     *     lineS          ... Buy or Stretch while under this
     *     fin            Stretch units that finish a set no Buy listing finishes: the ones a list takes
     *     takeLine       the line of what a list takes (buy + fin units)
     *     needs          the points price the dearest Stretch unit needs (0 with none)
     *   next: { k, room, perPoint } | null   the next set to finish: what it still has to spare, in all and a point
     * }
     */
    function judgeSet(set, o) {
        const ids = set.pieces.map((p) => String(p.id));
        const target = sjWhole(o.target);
        const more = Math.max(0, sjNum(o.more));
        const st = new Map();
        for (const id of ids) {
            const guide = sjWhole(o.guide(id));
            st.set(id, { id, guide, held: sjWhole(o.held(id)), avg: sjNum(o.avg(id)), rows: o.rows(id) || [], at: 0, used: 0, buy: 0, stretch: 0, fin: 0, last: 0, lastS: 0, lastFin: 0, offB: false, offS: false, needs: 0 });
        }
        // The k-th unit of a piece's listings, taken once each: a pointer walks the rows.
        const unit = (p) => {
            while (p.at < p.rows.length && p.used >= sjWhole(p.rows[p.at].qty)) { p.at += 1; p.used = 0; }
            if (p.at >= p.rows.length) return 0;
            p.used += 1;
            return sjWhole(p.rows[p.at].price);
        };
        let next = null;
        const first = Math.min(...ids.map((id) => st.get(id).held)) + 1;
        for (let k = first; k <= target; k++) {
            let room = 0;
            let finish = true;
            const over = [];
            for (const id of ids) {
                const p = st.get(id);
                if (!(p.guide > 0)) { finish = false; continue; }
                if (p.held >= k) { if (p.avg > 0) room += p.guide - 1 - p.avg; continue; }
                if (p.offS) { finish = false; continue; }
                const price = unit(p);
                if (!price) { p.offB = true; p.offS = true; finish = false; continue; }
                if (price < p.guide) { room += p.guide - 1 - price; p.buy += 1; p.last = price; continue; }
                over.push({ p, price, by: price - (p.guide - 1) });
            }
            if (!next) next = { k, room: Math.round(room), perPoint: set.points ? Math.round(room / set.points) : 0 };
            // The smallest overpay first: the room goes to as many units as it covers.
            over.sort((a, b) => a.by - b.by);
            const fins = [];
            for (const c of over) {
                const p = c.p;
                if (!p.offB && room >= c.by) { room -= c.by; p.buy += 1; p.last = c.price; continue; }
                p.offB = true;
                if (more > 0 && room + more >= c.by) {
                    room -= c.by;
                    p.stretch += 1;
                    p.lastS = c.price;
                    // What the set is short of at today's price, as the points price that would cover it.
                    if (o.perMore > 0) p.needs = Math.max(p.needs, Math.ceil(sjNum(o.priceNow) + -room / o.perMore));
                    fins.push(p);
                    continue;
                }
                p.offS = true;
                finish = false;
            }
            // A set every missing piece of which has a listing, and that only a Stretch finishes: its Stretch units
            // are the ones a list takes (a piece bought dear for a set that cannot be finished yet only waits).
            if (finish) for (const p of fins) { p.fin = p.stretch; p.lastFin = p.lastS; }
            if (ids.every((id) => { const p = st.get(id); return p.held >= target || p.offS; })) break;
        }
        const pieces = new Map();
        for (const id of ids) {
            const p = st.get(id);
            const line = Math.max(p.guide, p.buy ? p.last + 1 : 0);
            const lineS = Math.max(line, p.stretch ? p.lastS + 1 : 0);
            pieces.set(id, { buy: p.buy, line, stretch: p.stretch, lineS, fin: p.fin, takeLine: p.fin ? Math.max(line, p.lastFin + 1) : line, needs: p.stretch ? p.needs : 0 });
        }
        return { pieces, next };
    }

    /* ===== src/core/sellrate.js ===== */
    // What you pay your sellers, worked out from your least profit. Pure working-out: no page, no storage, no clock.
    //
    // The owner, 2026-10-12. You type two things: the most you pay (a percent of market value) and your least profit.
    // What you really pay a set is the lower of that rate and the set's ceiling - the highest rate at which ten points
    // still leave your least profit - at a cautious points price: the lower of today's and what you usually sell
    // points for. The whole price table is fixed once an hour while your shop is open ("maybe it checks the points
    // every hour"), and inside the hour it only ever comes down: when the points price falls under your least profit.
    // The points market takes no fee (his word), so nothing is taken off for one.



    const srNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const srWhole = (v) => Math.max(0, Math.floor(srNum(v)));

    /** How long a fixed price table stands. A wait, not a price. */
    const RATE_HOUR_MS = 3600000;
    /** Another buyer's price read longer ago than this counts for nothing. */
    const BID_KEEPS_MS = 24 * 3600000;
    /** ... and is said with its age from here on. */
    const BID_OLD_MS = 3600000;

    /**
     * One idea of what a point is worth: the lower of today's points price and the price you usually sell at. With no
     * usual price known, today's.
     * @returns { price, from: 'today' | 'usual' | '', today, usual, high } - `high` is the other, higher one of the two
     */
    function cautiousPrice(today, usual) {
        const t = srWhole(today);
        const u = srWhole(usual);
        if (!t) return { price: 0, from: '', today: 0, usual: u, high: 0 };
        if (!u || u >= t) return { price: t, from: 'today', today: t, usual: u, high: u > t ? u : t };
        return { price: u, from: 'usual', today: t, usual: u, high: t };
    }

    /** The highest rate (percent of market value, a tenth, rounded DOWN) that still leaves the least profit. 0: not known. */
    function rateCeiling(market, value, leastPct = 0) {
        return market > 0 && value > 0 ? Math.floor(value / (1 + Math.max(0, srNum(leastPct)) / 100) / market * 1000) / 10 : 0;
    }

    /** What you pay: the lower of the most you pay and the ceiling. With no ceiling known, the most you pay. */
    const paidRate = (typed, cap) => (cap > 0 ? Math.min(srNum(typed), cap) : srNum(typed));

    /** The settings a price table rests on: changed by your own press, the table is fixed anew at once. */
    const rateKey = (settings) => JSON.stringify([settings.pct, settings.least, settings.which.plushie !== false, settings.which.flower !== false]);

    /**
     * The price table as it would be fixed now: each set at the lower of your rate and its own ceiling.
     * @param sets  the sets you trade
     * @param caut  cautiousPrice()
     * @returns { ok, price, from, today, usual, pct, least, sets: { key: { pct, cap, market } }, pay: { id: $ }, mv: { id: $ } }
     *   ok = every set has a ceiling (a points price and every market value are read)
     */
    function liveTable(sets, mv, typed, leastPct, caut) {
        const out = { ok: (sets || []).length > 0, price: caut.price, from: caut.from, today: caut.today, usual: caut.usual, pct: srNum(typed), least: srNum(leastPct), sets: {}, pay: {}, mv: {} };
        for (const set of sets || []) {
            const market = setMarketValue(set, mv);
            const cap = rateCeiling(market, setValue(set, caut.price), leastPct);
            if (!cap) out.ok = false;
            const pct = paidRate(typed, cap);
            out.sets[set.key] = { pct, cap, market };
            for (const p of set.pieces) {
                const v = srWhole(mv(p.id));
                out.mv[p.id] = v;
                out.pay[p.id] = ratePrice(v, pct);
            }
        }
        return out;
    }

    /** A table fixed for the hour. `rev` moves whenever its prices do: what was last written to TornW3B is told by it. */
    function fixTable(live, key, now) {
        return { ...live, key, at: now, until: now + RATE_HOUR_MS, rev: now, held: false };
    }

    /**
     * The one safety: a set whose fixed rate is over its ceiling at the cautious price now comes down to it, at once.
     * Never up. The ceiling is worked out on the table's own market values - what its prices were made from.
     * @returns the table itself when nothing is over, else a new one (`down` on each set that came down)
     */
    function safeTable(table, sets, cautPrice, now) {
        if (!table || !(cautPrice > 0)) return table;
        let out = table;
        for (const set of sets || []) {
            const row = table.sets[set.key];
            if (!row) continue;
            let market = 0;
            for (const p of set.pieces) market += srWhole(table.mv[p.id]);
            const cap = rateCeiling(market, setValue(set, cautPrice), table.least);
            if (!cap || row.pct <= cap) continue;
            if (out === table) out = { ...table, sets: { ...table.sets }, pay: { ...table.pay }, rev: now };
            out.sets[set.key] = { ...row, pct: cap, cap, down: { at: now, from: row.down ? row.down.from : row.pct, price: srWhole(cautPrice) } };
            for (const p of set.pieces) out.pay[p.id] = ratePrice(table.mv[p.id], cap);
        }
        return out;
    }

    /**
     * What the best other buyers pay for a whole set: each piece at its best other buyer, summed, against the same
     * pieces' market value. (A $500 piece at 126% moves a $300,000 set by a few dollars: the set is what counts.)
     * @param bidOf id -> { price, pct, name, at } | null
     * @returns null with no price read in the last day, else { pct, pieces, of, at } - `at`: the oldest read counted
     */
    function othersPay(set, mv, bidOf, now) {
        let paid = 0;
        let market = 0;
        let pieces = 0;
        let at = Infinity;
        for (const p of set.pieces) {
            const b = bidOf ? bidOf(p.id) : null;
            const v = srWhole(mv(p.id));
            if (!b || !(b.price > 0) || !v || !(b.at > 0) || now - b.at > BID_KEEPS_MS) continue;
            paid += srNum(b.price);
            market += v;
            pieces += 1;
            at = Math.min(at, b.at);
        }
        return pieces ? { pct: Math.round(paid / market * 1000) / 10, pieces, of: set.pieces.length, at } : null;
    }

    const srPct = (pct) => String(Math.round(srNum(pct) * 10) / 10);
    const srMany = (label) => String(label || '').toLowerCase() + 's';

    /**
     * The rate as a sentence's part: "101% of market value", or - the sets differing -
     * "100.6% of market value for plushies and 101% for flowers".
     * @param rows [{ label, pct }]
     */
    function rateWords(rows) {
        const rs = (rows || []).filter((r) => r && r.pct > 0);
        if (!rs.length) return '';
        if (rs.every((r) => srPct(r.pct) === srPct(rs[0].pct))) return srPct(rs[0].pct) + '% of market value';
        return rs.map((r, k) => srPct(r.pct) + '%' + (k ? '' : ' of market value') + ' for ' + srMany(r.label)).join(' and ');
    }

    /** The same, short: "101%" or "100.6% to 101%". */
    function rateShort(rows) {
        const ps = (rows || []).filter((r) => r && r.pct > 0).map((r) => srNum(r.pct));
        if (!ps.length) return '';
        const lo = Math.min(...ps);
        const hi = Math.max(...ps);
        return srPct(lo) === srPct(hi) ? srPct(lo) + '%' : srPct(lo) + '% to ' + srPct(hi) + '%';
    }

    /* ===== src/core/shortlist.js ===== */
    // The shortlist: of everything that lists a piece, the few rows a list, a deal or the "Sold by" table can ever use.
    //
    // The owner, 2026-10-11: "we need some sort of intermediary state ... the one that does the hard filtering". The
    // whole pile of listings (thousands of rows with the shared server on) is kept as it was read, sorted once a piece
    // when an answer changes it (engine/state.js pileOf). From it, for every piece, this keeps:
    //   - the cheapest rows that count, up to a few times what you need of the piece;
    //   - its rows at every bazaar a list would go to anyway (so stops can still be gathered: shopping.js fewerStops);
    //   - the rows of your list as it stands;
    //   - the cheapest rows not checked lately that a list would use (they are asked of Torn next);
    //   - the cheap rows of a place you do not buy from, and the first rows over the line, to show where the line is.
    // What is left out is counted, and said once. A list made from the shortlists is the same list the whole pile
    // makes: test/shortlist.test.js holds both against each other.
    // Pure working-out on plain rows. The pile's rows are shared with the layer: none is written on here.



    const slWhole = (v) => Math.max(0, Math.floor(Number(v) || 0));

    /** The cheapest rows that count are kept until they hold this many times what you need of the piece. */
    const SHORT_TIMES = 3;
    /** ... and never fewer rows than this where you buy: a piece you have enough of still shows who sells it. */
    const SHORT_ROWS = 14;
    /** Rows over the line that are kept, to show where the line is. */
    const SHORT_OVER = 2;
    /** Rows of a place you do not buy from that are kept whatever they cost. */
    const SHORT_OUT = 3;

    const slRank = (o) => (o.ok === false ? 2 : o.out ? 1 : 0);

    /**
     * @param pieces [{ id, need, take, takeLine, line, lineS, worth }]
     *   take / takeLine   what a list takes of the piece: so many units, each under that price (core/setjudge.js)
     *   line / lineS      a row under `line` is Buy, under `lineS` Stretch, at or over it "No thanks"
     * @param pileOf  id -> every listing of the piece, cheapest first: [{ price, qty, src, whoId, ok }]
     * @param cartPlaces id -> Set of the places your list has a line for the piece at (or null)
     * @param isOut   row -> true when it is in a place you do not buy from (settings.from)
     * @returns Map id -> {
     *   rows     the shortlist: the rows that count first, then the places you do not buy from (`out: true`), then
     *            the rows not checked lately; cheapest first in each
     *   all      rows in the pile
     *   under    { units, places } rows that count under the piece's own worth
     *   good     { units, places } rows that count under its line (Buy)
     *   left     { over, more, old, out } rows left out: over the line (sellers), under it beyond the shortlist,
     *            not checked lately, in a place you do not buy from
     *   lowAll   the cheapest row anywhere, a checked one first (the day's record of the price)
     *   lowBazaar the cheapest bazaar's price as the table has it, or 0
     * }
     */
    function shortlists(pieces, pileOf, cartPlaces = null, isOut = null) {
        const list = pieces || [];
        const piles = new Map();
        const outOf = (o) => !!(isOut ? isOut(o) : o.out);
        // What a list would go to: the places of the cheapest rows that fill what it takes of each piece.
        const places = new Set();
        for (const p of list) {
            const pile = (pileOf && pileOf(p.id)) || [];
            piles.set(String(p.id), pile);
            let left = slWhole(p.take);
            for (let k = 0; k < pile.length && left > 0; k++) {
                const o = pile[k];
                if (o.price >= p.takeLine) break;
                if (o.ok === false || outOf(o)) continue;
                places.add(placeOf(o));
                left -= slWhole(o.qty);
            }
        }
        const out = new Map();
        for (const p of list) {
            const id = String(p.id);
            const pile = piles.get(id);
            const mine = cartPlaces ? cartPlaces(id) : null;
            const most = SHORT_TIMES * Math.max(1, slWhole(p.need));
            const rows = [];
            const under = { units: 0, places: 0 };
            const good = { units: 0, places: 0 };
            const left = { over: 0, more: 0, old: 0, out: 0 };
            // Units seen so far under the line: that count, of every row where you buy, and where you do not.
            let units = 0;
            let unitsAll = 0;
            let unitsOut = 0;
            let kept = 0;
            let over = 0;
            let outs = 0;
            let lowAll = null;
            let lowOld = null;
            let lowBazaar = 0;
            let lowBazaarRank = 3;
            for (const o of pile) {
                if (!(o.price > 0) || !(o.qty > 0)) continue;
                const q = slWhole(o.qty);
                const old = o.ok === false;
                const away = outOf(o);
                const place = placeOf(o);
                const onList = !away && !!(mine && mine.has(place));
                const rank = old ? 2 : away ? 1 : 0;
                if (!old && !lowAll) lowAll = o;
                if (old && !lowOld) lowOld = o;
                if (o.src !== 'market' && rank < lowBazaarRank) { lowBazaarRank = rank; lowBazaar = o.price; }
                const counts = !old && !away;
                if (counts && o.price < p.worth) { under.units += q; under.places += 1; }
                if (counts && o.price < p.line) { good.units += q; good.places += 1; }
                let keep = onList;
                if (away) {
                    // A place you do not buy from: its checked rows under the line are still a price (a deal anyone can
                    // take, the day's low), up to as many as you could use; a few more whatever they cost.
                    if (!old && o.price < p.lineS && unitsOut < most) keep = true;
                    else if (outs < SHORT_OUT) keep = true;
                    if (!old && o.price < p.lineS) unitsOut += q;
                    if (keep) outs += 1; else left.out += 1;
                } else if (o.price >= p.lineS) {
                    // Over the line: the first few, checked or not, show where it is.
                    if (!keep && (over < SHORT_OVER || kept < SHORT_ROWS)) keep = true;
                    if (keep) over += 1; else if (old) left.old += 1; else left.over += 1;
                } else if (old) {
                    // Not checked lately: kept while a list made of every row shown would still reach it.
                    if (!keep && (unitsAll < most || kept < SHORT_ROWS)) keep = true;
                    if (!keep) left.old += 1;
                } else {
                    if (!keep && (units < most || kept < SHORT_ROWS || places.has(place))) keep = true;
                    if (!keep) left.more += 1;
                    // A row of your list is kept whatever comes: it does not use up the room of the others.
                    if (!onList) units += q;
                }
                if (!away && o.price < p.lineS && !onList) unitsAll += q;
                if (keep) { rows.push(away ? { ...o, out: true } : o); if (!away) kept += 1; }
            }
            rows.sort((a, b) => slRank(a) - slRank(b) || a.price - b.price);
            out.set(id, { rows, all: pile.length, under, good, left, lowAll: lowAll || lowOld, lowBazaar });
        }
        return out;
    }

    /* ===== src/core/verdict.js ===== */
    // "Open your shop?": one verdict, four checks.
    // The shop is what you pay sellers who trade with you. It is worth being open when a set bought at your rate still
    // leaves your least profit, nothing you need is cheaper in a bazaar than from your sellers, you still need pieces,
    // and your share of money for sets has room. Once open, a new cheap listing never closes it: it goes on your list.
    // Pure working-out; the words are put together by the page.

    const vdNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const vdWhole = (v) => Math.max(0, Math.floor(vdNum(v)));

    /** A cheap listing left unbought this long turns an open shop amber. A wait, not a price. */
    const HOT_SIT_MS = 10 * 60000;

    /**
     * Listings of pieces you need that are cheaper than what you pay sellers: anyone can buy there and sell to you.
     * @param pieces   [{ id, name, need, pay }] - pay = your price for one, at your rate
     * @param offersOf id -> [{ price, qty, src, who, whoId }]
     * @returns [{ id, name, key, q, price, pay, who, whoId, im }] cheapest first within a piece, never more than you need
     */
    function hotListings(pieces, offersOf) {
        const out = [];
        for (const p of pieces || []) {
            let left = vdWhole(p.need);
            if (!left || !(p.pay > 0)) continue;
            const offers = [...((offersOf && offersOf(p.id)) || [])].filter((o) => o.price > 0 && o.qty > 0 && o.price < p.pay).sort((a, b) => a.price - b.price);
            for (const o of offers) {
                if (!left) break;
                const q = Math.min(left, vdWhole(o.qty));
                const im = o.src === 'market';
                out.push({ id: p.id, name: p.name, key: p.id + '|' + (im ? 'im' : 'b:' + (o.whoId ?? o.who ?? '')), q, price: o.price, pay: p.pay, who: o.who || null, whoId: o.whoId ?? null, im });
                left -= q;
            }
        }
        return out;
    }

    /** When each hot listing was first seen: { key: t }. A listing that is gone is forgotten. */
    function hotSince(prev, hot, now) {
        const out = {};
        for (const h of hot || []) out[h.key] = (prev && prev[h.key]) || now;
        return out;
    }

    /**
     * @param i {
     *   open        the shop is open now
     *   sets        [{ name, market, value, profit, ok, cap }] - sets.js's rateSet() for each set you trade, at your rate
     *   hot         hotListings()
     *   since       hotSince()
     *   onList      key -> true when that listing is on your shopping list
     *   needUnits   pieces you still need
     *   coverSets   how many more sets your share of money covers (null = no limit set)
     *   now
     * }
     * @returns {
     *   state   'no-price' | 'low' | 'full' | 'share' | 'buy-first' | 'open-now' | 'stay' | 'stay-buy'
     *   lamp    'ok' | 'warn' | 'bad'
     *   checks  { leaves: { ok, profit, name, cap }, cheaper: { ok, units, listings, sat }, need: { ok, units }, share: { ok, sets } }
     *   worth   every check holds
     * }
     */
    function shopVerdict(i) {
        const sets = (i.sets || []).filter(Boolean);
        const priced = sets.length > 0 && sets.every((s) => s.market > 0 && s.value > 0);
        const worst = sets.reduce((a, s) => (!a || s.profit < a.profit ? s : a), null);
        const leaves = { ok: priced && sets.every((s) => s.ok), profit: worst ? worst.profit : 0, name: worst ? worst.name : '', cap: sets.length ? Math.min(...sets.map((s) => vdNum(s.cap))) : 0 };
        const hot = i.hot || [];
        const units = hot.reduce((s, h) => s + h.q, 0);
        const sat = hot.filter((h) => i.since && i.since[h.key] && i.now - i.since[h.key] >= HOT_SIT_MS).length;
        const listed = hot.filter((h) => i.onList && i.onList(h.key)).length;
        const cheaper = { ok: i.open ? sat === 0 : units === 0, units, listings: hot.length, sat, listed };
        const need = { ok: vdWhole(i.needUnits) > 0, units: vdWhole(i.needUnits) };
        const share = { ok: i.coverSets == null || i.coverSets > 0, sets: i.coverSets == null ? null : vdWhole(i.coverSets) };
        const checks = { leaves, cheaper, need, share };
        let state;
        if (!priced) state = 'no-price';
        else if (!leaves.ok) state = 'low';
        else if (!need.ok) state = 'full';
        else if (!share.ok) state = 'share';
        else if (!i.open) state = units ? 'buy-first' : 'open-now';
        else state = sat ? 'stay-buy' : 'stay';
        const lamp = state === 'open-now' || state === 'stay' ? 'ok' : state === 'low' ? 'bad' : 'warn';
        return { state, lamp, checks, worth: leaves.ok && cheaper.ok && need.ok && share.ok };
    }

    /** The verdict's headline. */
    const VERDICT_WORDS = {
        'no-price': 'Waiting for prices',
        low: 'Not worth it at this rate',
        full: 'Nothing needed: stay closed',
        share: 'Your share for sets is full',
        'buy-first': 'Not yet: buy first',
        'open-now': 'Worth opening now',
        stay: 'Open, and worth staying open',
        'stay-buy': 'Open: buy the cheap ones first',
    };

    /**
     * How many more sets your share of money covers.
     * @param worth    everything you have (cash, vault, and what sits in pieces and points)
     * @param inSets   what sits in pieces and points now, at cost
     * @param sharePct the most of your money you want in sets and points (0 = no limit)
     * @param setCost  what a set costs at your rate
     * @returns null with no limit, else whole sets
     */
    function shareCovers(worth, inSets, sharePct, setCost) {
        if (!(sharePct > 0)) return null;
        if (!(setCost > 0)) return 0;
        return vdWhole((vdNum(worth) * sharePct / 100 - vdNum(inSets)) / setCost);
    }

    /* ===== src/core/view.js ===== */
    // The view: everything the hub's pages and the box on Torn's pages show, worked out once from what the engine holds.
    // Pure: the engine hands in settings, the stock count, prices, the points market, the books and the open trades;
    // out comes one plain object. No page, no storage, no clock of its own. The pages only format it.















    const vwNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const vwWhole = (v) => Math.max(0, Math.floor(vwNum(v)));
    const vwSum = (xs, f) => (xs || []).reduce((a, x) => a + f(x), 0);
    const VW_DAY_MS = 86400000;
    const vwDay = (t) => new Date(t).toISOString().slice(0, 10);

    /** The two sets' colours and short names, as the pages name them. */
    const SET_LOOK = { plushie: { label: 'Plushie', color: 'var(--s-plush)' }, flower: { label: 'Flower', color: 'var(--s-flower)' } };

    /** The sets you trade. */
    const setsTraded = (settings) => SETS.filter((s) => settings.which[s.key] !== false);

    /** Every piece id the Archive keeps count of and may put on your TornW3B list: all 24, whatever is switched on. */
    const ALL_PIECE_IDS = SETS.flatMap((s) => s.pieces.map((p) => String(p.id)));

    /** The k-th set bought fresh costs the k-th cheapest unit of every piece. @returns [cost of set 1, set 2, ...] */
    function setLadder(set, offersOf, most = 500) {
        const ladders = set.pieces.map((p) => {
            const units = [];
            const all = [...((offersOf && offersOf(p.id)) || [])].filter((o) => o.price > 0 && o.qty > 0).sort((a, b) => a.price - b.price);
            for (const o of all) { for (let k = 0; k < vwWhole(o.qty) && units.length < most; k++) units.push(o.price); if (units.length >= most) break; }
            return units;
        });
        const depth = Math.min(...ladders.map((l) => l.length));
        const out = [];
        for (let k = 0; k < depth; k++) out.push(ladders.reduce((s, l) => s + l[k], 0));
        return out;
    }

    const VW_DEPTH_AT = [1, 10, 50, 100, 250, 500];
    /** The stops of the list the dashboard names under "Do now": as many as its card ever has room for. */
    const VW_FIRST_STOPS = 12;

    /**
     * @param i {
     *   now, settings (archiveSettings)
     *   held(id), stockAt            the stock count and when Torn's inventory was last read (0 = never)
     *   mv(id)                       Torn's market value
     *   offers(id), pricesAt         bazaar and Item Market listings of a piece, cheapest first or not
     *   priced(id)                   (optional) whether the piece's listings were read at all
     *   topBid(id)                   { pct, name, price, at } the best any other buyer pays, as a percent of market value, in
     *                                dollars, and when it was read - or null
     *   rate                         the price table fixed for the hour (core/sellrate.js fixTable), or null: then what
     *                                you pay is worked out now
     *   listings, pointsAt           the points market (points.js parsePointsMarket)
     *   days, wallDays               the lowest listing and the first wall by day (points.js recordPrice)
     *   lots, mineLots               lots.js's record, and your own lots [{ points, wait }]
     *   pool, book, mugs, outs       books.js: the cost pool, the points book's entries, mugs, money that left your hand
     *   money                        { points, onHand, vault }, each null when not read
     *   trades, finished             open trades (trades.js parseTrade) and finished ones [{ id, who, whoId, t, units, paid, mv }]
     *   rows                         the Ledger's rows of pieces (core/ledger.js)
     *   cart, run                    the shopping list and the run (shopping.js)
     *   hotSince                     verdict.js hotSince()
     *   thread                       { id, title, at } your buying thread as Torn has it, or null
     *   w3b                          { list (Map | null), listAt, receipts (Map), lastReceiptAt, error }
     *   hist                         { low: { id: [{ day, low }] }, pays: [{ day, plushie, flower }], share: [{ day, share }] }
     *   names(id)                    a player's name by id, when known
     * }
     */
    function archiveView(i) {
        const now = i.now || Date.now();
        const settings = i.settings;
        const ctx = setsCtx(settings);
        const on = setsTraded(settings);
        const money = i.money || {};
        const mv = (id) => vwWhole(i.mv(id));
        // A row that was not looked at lately (`ok: false`, engine/state.js COUNT_MS) is shown, after the checked ones,
        // and counts for nothing: no list, no "Do now", no "cheapest". It is asked of Torn first (buy.check).
        // A row in a place you do not buy from (settings.from: `out: true`) is shown too, after the ones you do, and
        // counts for no list either. It still counts as a price: a set's cost, the day's lowest, "Open your shop?".
        //
        // The in-between layer (1.3.0). `i.offers(id)` is the whole pile of a piece, cheapest first, sorted by the
        // engine only when an answer moved it (engine/state.js pileOf); its rows are shared and never written on here.
        // From it a shortlist per piece is kept (core/shortlist.js): the list, the deals and "Sold by" read that.
        const pileMemo = new Map();
        const inPlace = buysFrom(settings);
        const isOut = (o) => !!o.out || !inPlace(o);
        const pile = (id) => {
            const k = String(id);
            if (!pileMemo.has(k)) {
                const rows = (i.offers && i.offers(id)) || [];
                // The engine hands them in sorted; a caller that does not gets them sorted here, once.
                let sorted = true;
                for (let n = 1; n < rows.length && sorted; n++) if (rows[n].price < rows[n - 1].price) sorted = false;
                pileMemo.set(k, sorted ? rows : [...rows].sort((a, b) => a.price - b.price));
            }
            return pileMemo.get(k);
        };
        const pileLive = (id) => pile(id).filter((o) => o.price > 0 && o.qty > 0);
        let short = new Map();
        const offersOf = (id) => (short.get(String(id)) || { rows: [] }).rows;
        const checkedAll = (id) => offersOf(id).filter((o) => o.ok !== false);
        const checkedOf = (id) => offersOf(id).filter((o) => o.ok !== false && !o.out);

        // ---- the points price --------------------------------------------------------------------------------------------
        const price = listPrice(i.listings || [], settings.pointsRule);
        const pointsPrice = price ? price.price : 0;
        const level = usualLevel(i.days || [], now);
        const cheap = pointsCheap(price ? price.lowest : 0, level);

        // ---- the books ---------------------------------------------------------------------------------------------------
        const pointsHeld = money.points == null ? null : vwWhole(money.points);
        // A swap booked before 1.3.0 does not say how much of its cost was an estimate: it is "about" for as long as
        // the pool of its set still holds units never seen bought (F1).
        const estNow = {};
        for (const s of SETS) {
            let n = 0;
            let est = 0;
            for (const p of s.pieces) { const c = (i.pool || {})[String(p.id)]; if (c) { n += c.n; est += c.est; } }
            estNow[s.key] = n ? est / n : 0;
        }
        const bookIn = (i.book || []).map((e) => (e.kind === 'made' && e.est == null ? { ...e, est: estNow[e.set] || 0 } : e));
        const plain = avgBook(bookIn, pointsPrice);
        const before = pointsHeld == null ? null : Math.max(0, pointsHeld - plain.left);
        // With a cost typed for them, the points you had before open the book - as many as they were when the book
        // began: what you hold now, less every point made since, plus every point sold or used since. (Until 1.2.3 the
        // book was opened with what is left of them NOW, and the sales that had already taken some took them again.)
        const flow = vwSum(i.book || [], (e) => (e.kind === 'made' ? -1 : 1) * vwWhole(e.points));
        const opened = pointsHeld == null ? 0 : Math.max(0, pointsHeld + flow);
        const book = settings.beforeEach > 0 && opened ? avgBook(bookIn, pointsPrice, { points: opened, each: settings.beforeEach }) : plain;
        const pool = poolSum(i.pool);
        const cash = money.onHand == null && money.vault == null ? null : vwWhole(money.onHand) + vwWhole(money.vault);
        const share = moneyShare({ pieces: pool.cost, points: book.cost, cash: money.onHand, vault: money.vault });

        // ---- the sets and their pieces -----------------------------------------------------------------------------------
        const cartList = i.cart || [];
        // While a run is on a line keeps the units you took on it (it says "took 5 of 5" until Next), and those units
        // are in your stock: what is still to buy is the list less what was taken.
        const leftList = i.run && i.run.on ? listAfterRun(cartList, i.run) : cartList;
        const sets = [];
        const pieces = [];
        const heldOf = (set) => { const m = {}; for (const p of set.pieces) m[p.id] = vwWhole(i.held(p.id)); return m; };
        // "From my cash": one purse for all the sets - your cash, no more than keeps sets and points under their share
        // of your money - spent on the pieces you do not hold yet.
        const room = settings.shareMax > 0 ? Math.max(0, share.total * settings.shareMax / 100 - share.inSets) : Infinity;
        const budget = cash == null ? null : Math.min(cash, room);
        // One idea of what a point is worth (core/sellrate.js): the lower of today's price and the price you usually
        // sell points for. Every limit rests on it - what you pay your sellers, a piece's worth, the cart's Buy line.
        // What a set BRINGS on the screen stays at today's price.
        const usual = usualSell(i.book || [], level, now);
        const caut = cautiousPrice(pointsPrice, usual.price);
        // What you pay your sellers: each set at the lower of your rate and its own ceiling. While your shop is open
        // the engine fixes that table for an hour (`i.rate`); inside the hour it only comes down, when the points
        // price falls under your least profit - worked out here as well, so no page ever shows a price over it.
        const live = liveTable(on, mv, settings.pct, settings.least, caut);
        const fixedIn = settings.open && i.rate && i.rate.key === rateKey(settings) && on.every((s) => i.rate.sets && i.rate.sets[s.key]) ? i.rate : null;
        const fixed = fixedIn ? safeTable(fixedIn, on, caut.price, now) : null;
        const payTable = fixed || live;
        const payOf = (id) => { const p = payTable.pay[id]; return p == null ? ratePrice(mv(id), settings.pct) : p; };
        const auto = settings.targetMode === 'number' ? null : autoTargets(on, heldOf, budget, payOf);
        // While a list is on hand, the sets it was made for stay: your money moves with every buy and sale (and Torn
        // says so a minute before your stock does), and a list whose numbers move under you cannot be bought.
        const kept = auto && i.kept ? i.kept : null;
        const leastUp = 1 + Math.max(0, vwNum(settings.least)) / 100;
        // Every set judged first: what of each piece's listings is Buy, Stretch or No thanks, on the SET they finish.
        const judged = [];
        const shortIn = [];
        for (const set of on) {
            const heldMap = heldOf(set);
            const target = kept && Number.isInteger(kept[set.key]) ? kept[set.key] : auto ? auto[set.key] : settings.target;
            const stock = setStock(set, heldMap, target);
            const guide = new Map(set.pieces.map((p) => [String(p.id), safeWorth(p.id, mv, caut.price, settings.least)]));
            // Buy: the set pays at the lower of the two points prices. Stretch: it pays only at the higher one.
            const o = {
                target: stock.target, held: (id) => heldMap[id], avg: (id) => poolEach(i.pool, id), guide: (id) => guide.get(String(id)) || 0,
                more: caut.high > caut.price ? set.points * (caut.high - caut.price) / leastUp : 0,
                perMore: set.points / leastUp, priceNow: caut.price,
            };
            const live = new Map(set.pieces.map((p) => [String(p.id), pileLive(p.id)]));
            // On the rows that count (a list is made of these), and on every row where you buy, checked or not (what
            // a list would hold if every row shown were true: its bazaars are the ones to ask Torn about next).
            const judge = judgeSet(set, { ...o, rows: (id) => live.get(String(id)).filter((r) => r.ok !== false && !isOut(r)) });
            const wishJ = judgeSet(set, { ...o, rows: (id) => live.get(String(id)).filter((r) => !isOut(r)) });
            judged.push({ set, heldMap, stock, guide, judge, wishJ });
            for (const p of stock.pieces) {
                const j = judge.pieces.get(String(p.id));
                const w = wishJ.pieces.get(String(p.id));
                shortIn.push({ id: p.id, need: p.need, take: Math.min(p.need, j.buy + j.fin), takeLine: j.takeLine, line: j.line, lineS: Math.max(j.lineS, w.lineS), worth: guide.get(String(p.id)) || 0 });
            }
        }
        const cartAt = new Map();
        for (const l of cartList) { const k = String(l.id); if (!cartAt.has(k)) cartAt.set(k, new Set()); cartAt.get(k).add(l.place); }
        short = shortlists(shortIn, pileLive, (id) => cartAt.get(String(id)) || null, isOut);
        for (const { set, heldMap, stock, guide, judge, wishJ } of judged) {
            // What a set costs at what you pay and what it leaves at today's points price; `cap` is the ceiling the
            // table was made with, `pct` what you pay, `typed` the most you pay, `down` when it came down this hour.
            const tr = payTable.sets[set.key];
            const atToday = rateSet(set, mv, tr.pct, pointsPrice, settings.least);
            const paidSet = vwSum(set.pieces, (p) => payOf(p.id));
            const rate = {
                ...atToday, cost: paidSet, profit: atToday.value - paidSet, kept: paidSet > 0 ? (atToday.value - paidSet) / paidSet * 100 : 0,
                cap: tr.cap, pct: tr.pct, typed: settings.pct, down: tr.down || null,
                ok: atToday.value > 0 && atToday.market > 0 && tr.cap > 0 && tr.pct <= tr.cap,
            };
            const value = setValue(set, pointsPrice);
            const ladder = setLadder(set, pileLive);
            const mine = stock.pieces.map((p) => {
                const sl = short.get(String(p.id));
                const offers = sl.rows;
                const worth = guide.get(String(p.id)) || 0;
                const j = judge.pieces.get(String(p.id));
                const w = wishJ.pieces.get(String(p.id));
                const take = Math.min(p.need, j.buy + j.fin);
                const pay = payOf(p.id);
                const bid = (i.topBid && i.topBid(p.id)) || null;
                const listed = onList(leftList, p.id);
                const good = offers.filter((o) => o.ok !== false && !o.out && o.price < j.takeLine);
                return {
                    ...p, set: set.key, short: shortName(p.name), target: stock.target, mv: mv(p.id), pay, worth,
                    // The three groups, on the set (setjudge.js): a row under `line` is Buy, under `lineS` Stretch, else
                    // No thanks. `take` units under `takeLine` are what a list takes; `needs`: the points price the
                    // dearest Stretch unit needs. `wish`: the same, were every row shown true.
                    line: j.line, lineS: j.lineS, take, takeLine: j.takeLine, buyUnits: Math.min(p.need, j.buy), stretchUnits: j.stretch, fin: j.fin, needs: j.needs,
                    wish: { take: Math.min(p.need, w.buy + w.fin), takeLine: w.takeLine },
                    brings: Math.floor(pieceBrings(p.id, mv, pointsPrice)),
                    // low: the cheapest where you buy. lowAll: the cheapest anywhere (the day's record, the tape).
                    offers, low: offers.find((o) => !o.out) || null, lowAll: sl.lowAll,
                    lowBazaar: sl.lowBazaar,
                    // What one press of "Add all" on this piece would put on the list.
                    more: onList(addAll(leftList, { ...p, worth: j.takeLine, need: take }, good), p.id) - listed,
                    under: sl.under, good: sl.good,
                    // Rows the shortlist leaves out, said once under the table: over the line, more under it, not
                    // checked lately, in a place you do not buy from. `all`: every row there is.
                    left: sl.left, all: sl.all,
                    // A price read over a day ago counts for nothing (the owner, 2026-10-11: lists over 24 h old do not).
                    other: bid && bid.pct > 0 && !(bid.at > 0 && now - bid.at > BID_KEEPS_MS) ? { pct: bid.pct, name: bid.name || '', price: vwNum(bid.price), at: vwNum(bid.at) } : null,
                    hist: (((i.hist && i.hist.low) || {})[p.id] || []).slice(-7).map((d) => d.low),
                    listed,
                };
            });
            // Shortest first: the piece holding the next set back leads.
            mine.sort((a, b) => a.held - b.held || a.rank - b.rank);
            const own = poolSetCost(i.pool, set);
            sets.push({
                key: set.key, name: set.name, museum: set.museum, hash: set.hash, points: set.points, ...SET_LOOK[set.key],
                full: stock.full, target: stock.target, value, rate, pieces: mine,
                // What a set costs you: from what you paid, or at your rate while there is no buy on record.
                cost: own || rate.cost, costKnown: own > 0,
                // Bought fresh at the cheapest listings now: what one set leaves.
                fresh: ladder.length ? ladder[0] : 0, pays: ladder.length && value ? value - ladder[0] : null,
                // False until every piece's listings were read once: "no price" then means not read yet.
                priced: !i.priced || set.pieces.every((p) => i.priced(p.id)),
                ladder,
                needUnits: vwSum(mine, (p) => p.need),
                // The next set you would finish: what it still has to spare over its listings, in all and a point.
                next: judge.next,
            });
            pieces.push(...mine);
        }
        // The pieces as a list takes them (Buy, and the Stretch that finishes a set), and as "Do now" does.
        const listOf = listPieces(pieces);
        const wishOf = pieces.map((p) => ({ ...p, worth: p.wish.takeLine, need: p.wish.take }));
        const pieceOf = (id) => pieces.find((p) => String(p.id) === String(id)) || null;
        const worthOf = (id) => (pieceOf(id) || {}).worth || 0;
        const fullAll = vwSum(sets, (s) => s.full);
        const needUnits = vwSum(pieces, (p) => p.need);
        const fullAfter = (extra) => Object.fromEntries(sets.map((s) => [s.key, Math.min(...s.pieces.map((p) => p.held + vwWhole(extra(p))))]));

        // ---- buying ------------------------------------------------------------------------------------------------------
        const marginCtx = { mv, pointsPrice, leastPct: settings.least };
        const plan = fillList(listOf, checkedOf);
        const planStops = stopsOf(plan, worthOf);
        // What the list would hold if every row shown were true: the bazaars of it that are not checked are the ones
        // to ask Torn about next. Checked, they count - or are gone, and the next ones are asked.
        const wish = fillPlan(wishOf, (id) => offersOf(id).filter((o) => !o.out));
        const unsure = wish.filter((l) => !l.im && (offersOf(l.id).find((o) => placeOf(o) === l.place) || {}).ok === false);
        const check = [...new Set(unsure.map((l) => String(l.whoId)))];
        const nameOfPiece = (id) => (pieceOf(id) || {}).name || (i.itemName && i.itemName(id)) || 'Item ' + id;
        // The lines of the list that are over the piece's own share: carried by the set's room, or a Stretch.
        const lineGroup = (l) => { const p = pieceOf(l.id); return !p || l.price < p.worth ? '' : l.price < p.line ? 'room' : l.price < p.lineS ? 'stretch' : 'no'; };
        // `g` on a line: '' under the piece's own share, 'room', 'stretch' or 'no' (dear now: it leaves at the next read).
        const stops = runOrder(stopsOf(cartList, worthOf), i.run).map((s) => ({ ...s, lines: s.lines.map((l) => ({ ...l, g: lineGroup(l) })), margin: placeMargin(s.lines.map((l) => ({ id: l.id, take: l.q, price: l.price })), marginCtx) }));
        // `took` (line key -> units you took) rides along: the box on a bazaar says it per line.
        const run = { ...runView(i.run, stops), took: (i.run && i.run.took) || {} };
        // Cheaper than you pay your sellers, wherever it is: anyone can buy there and sell to you ("Open your shop?").
        const hot = hotListings(pieces, checkedAll);
        // What "Do now" says to buy, as the list its button makes: under what you pay sellers and under the worth.
        const hotPlan = fillList(cheapPieces(listOf), checkedOf);
        const hotPlanStops = stopsOf(hotPlan, (id) => (pieceOf(id) || {}).pay || 0);
        const leftStops = leftList === cartList ? stops : stopsOf(leftList, worthOf);
        const cartCost = vwSum(leftStops, (s) => s.cost);
        // "it should know how much i paid to complete the set" (the owner, 2026-10-11): what a set costs you a point
        // now (each piece at its average in the pool), and with everything on the list bought.
        let poolAfter = i.pool || {};
        for (const l of leftList) poolAfter = poolAdd(poolAfter, l.id, l.q, l.q * l.price);
        const even = sets.map((s) => {
            const set = setByKey(s.key);
            const from = poolSetCost(i.pool, set);
            const to = leftList.some((l) => l.set === s.key || s.pieces.some((p) => String(p.id) === String(l.id))) ? poolSetCost(poolAfter, set) : 0;
            return { key: s.key, label: s.label, from: from ? Math.ceil(from / s.points) : 0, to: to ? Math.ceil(to / s.points) : 0 };
        });
        const depthN = Math.min(...sets.map((s) => s.ladder.length), Infinity);
        const depthX = VW_DEPTH_AT.filter((k) => k <= depthN);
        const buy = {
            plan: {
                units: vwSum(plan, (l) => l.q), need: needUnits, stops: planStops.length, cost: vwSum(planStops, (s) => s.cost),
                full: fullAfter((p) => onList(plan, p.id)),
            },
            stops, run, from: { ...settings.from },
            // Bazaars shown but not checked lately that a list would use (asked of Torn next), and their units.
            check, unsure: vwSum(unsure, (l) => l.q),
            units: vwSum(leftStops, (s) => s.units), cost: cartCost, gain: vwSum(leftStops, (s) => s.gain),
            // The list's capital beside what you have on hand, and what it does to a set's cost a point.
            cash: { onHand: money.onHand == null ? null : vwWhole(money.onHand), vault: money.vault == null ? null : vwWhole(money.vault) },
            even,
            // Units on the list bought over the piece's own share: carried by the set's room, or a Stretch.
            stretch: { units: vwSum(leftList.filter((l) => lineGroup(l) === 'stretch'), (l) => l.q), needs: Math.max(0, ...pieces.filter((p) => leftList.some((l) => String(l.id) === String(p.id) && lineGroup(l) === 'stretch')).map((p) => p.needs)) },
            // `low` / `high`: the two points prices the groups are judged at (Buy pays at the lower, a Stretch only at
            // the higher); `by`: which of them is the lower - 'today' or 'usual'.
            usual: { price: usual.price, from: usual.from, low: caut.price, high: caut.high, by: caut.from },
            // Buys a page told of that Torn's log does not have: taken back, said once.
            back: (i.back || []).map((b) => ({ ...b, name: nameOfPiece(b.id), who: (i.names && i.names(b.whoId)) || '' })),
            full: fullAfter((p) => p.listed),
            left: listAfterRun(cartList, i.run),
            vault: money.onHand == null ? null : Math.max(0, cartCost - vwWhole(money.onHand)),
            hot, hotUnits: vwSum(hot, (h) => h.q), hotStops: new Set(hot.map((h) => (h.im ? 'im' : h.whoId ?? h.who))).size,
            depth: depthX.length >= 2 ? {
                x: depthX, series: sets.map((s) => ({ key: s.key, name: s.label, color: s.color, data: depthX.map((k) => s.ladder[k - 1]) })),
                value: sets[0] ? sets[0].value : 0, safe: sets[0] ? Math.floor(sets[0].points * caut.price / (1 + settings.least / 100)) : 0,
            } : null,
        };

        // ---- the trades open with you ------------------------------------------------------------------------------------
        const stockOf = (set) => { const s = sets.find((x) => x.key === set.key); return { pieces: s ? s.pieces : [] }; };
        const nameOf = (id) => { const p = pieceOf(id); if (p) return p.name; const set = SETS.find((s) => s.pieces.some((x) => String(x.id) === String(id))); return set ? set.pieces.find((x) => String(x.id) === String(id)).name : (i.itemName && i.itemName(id)) || 'Item ' + id; };
        const receipts = (i.w3b && i.w3b.receipts) || new Map();
        const open = (i.trades || []).map((t) => {
            const offer = tradeOffer(t.theirs.map((x) => ({ id: x.id, name: nameOf(x.id), qty: x.qty })), { settings: ctx, stockOf, mv, pct: settings.pct, pay: payOf });
            const margin = tradeMargin(offer, marginCtx);
            const total = offer.all.total;
            const state = tradeTurn(t, total);
            // The sets with a priced piece in this trade: the message names the rate really paid, each set its own
            // when they differ, and the box says when one came down inside the hour.
            const inIt = sets.filter((s) => offer.rows.some((r) => r.each > 0 && s.pieces.some((p) => String(p.id) === String(r.id))));
            return {
                id: t.id, who: t.who, whoId: t.whoId, modified: t.modified, ago: agoWords(t.modified, now), state, readAt: t.readAt || 0,
                rows: offer.rows, items: offer.rows.length, units: offer.all.items, total, needTotal: offer.need.total, needUnits: offer.need.items,
                margin, myMoney: t.myMoney, other: t.other,
                message: total ? `Hi! At ${rateWords(inIt.map((s) => ({ label: s.label, pct: s.rate.pct })))} that is $${total.toLocaleString('en-US')} for all ${offer.all.items.toLocaleString('en-US')}. I will add the money now, thank you.` : '',
                paid: rateShort(inIt.map((s) => ({ label: s.label, pct: s.rate.pct }))),
                rateDown: inIt.filter((s) => s.rate.down).map((s) => ({ key: s.key, label: s.label, from: s.rate.down.from, to: s.rate.pct, at: s.rate.down.at, price: s.rate.down.price })),
                messageNeed: tradeMessage(offer, { open: settings.open }),
                // Money to take out of the vault just before you pay: what the trade still wants, over what is on hand.
                vault: money.onHand == null ? null : Math.max(0, total - t.myMoney - vwWhole(money.onHand)),
                receipt: receipts.get(String(t.id)) || null,
                after: offer.rows.filter((r) => r.state !== 'other').map((r) => ({ id: r.id, name: r.name, held: r.held, q: r.qty, take: r.take, target: r.target })),
                full: fullAfter((p) => vwSum(offer.rows.filter((r) => String(r.id) === String(p.id)), (r) => r.qty)),
            };
        });
        const mineTurn = open.filter((t) => t.state === 'you');
        const trades = {
            // What they still wait for: money already in a trade is not asked for again.
            open, wait: mineTurn.length, waitMoney: vwSum(mineTurn, (t) => Math.max(0, t.total - vwWhole(t.myMoney))),
            // listed: your list on TornW3B has a price for each of its pieces - a receipt is made from that list.
            finished: (i.finished || []).slice(0, 60).map((f) => ({ ...f, ago: agoWords(f.t, now), rate: f.mv > 0 ? f.paid / f.mv * 100 : 0, receipt: receipts.get(String(f.id)) || null, listed: !!(i.w3b && i.w3b.list) && (f.rows || []).length > 0 && (f.rows || []).every((r) => i.w3b.list.has(String(r.id))) })),
            receiptsError: (i.w3b && i.w3b.receiptsError) || '',
        };

        // ---- points ------------------------------------------------------------------------------------------------------
        const levels = priceLevels(i.listings || []);
        let ahead = 0;
        const ladder = levels.slice(0, 14).map((lv) => { const row = { price: lv.price, qty: lv.qty, lots: lv.lots, ahead, wall: !!price && lv.price === price.wall }; ahead += lv.qty; return row; });
        const table = lotTable((i.lots && i.lots.gone) || [], i.mineLots || [], now);
        const sell = sellPlan(book.left, table);
        const mugs = mugCheck(book.rows.filter((r) => r.kind === 'sold').map((r) => ({ id: r.id, t: r.t, got: Math.round(r.mine * r.each) })), i.mugs || [], i.outs || [], i.outsFrom || 0);
        const hold = cheap && settings.cheapRule === 'hold';
        const points = {
            price: pointsPrice, lowest: price ? price.lowest : 0, wall: price ? price.wall : null, rule: price ? price.rule : settings.pointsRule,
            ahead: price ? price.ahead : 0, at: i.pointsAt || 0, level, cheap, hold, held: pointsHeld, before,
            ladder, table,
            sell: {
                points: book.left, least: book.least, loss: !!pointsPrice && book.left > 0 && pointsPrice < book.least,
                one: sell.one, quick: sell.quick, lands: book.left * pointsPrice,
                profit: book.left && pointsPrice ? book.left * pointsPrice - book.cost : 0,
            },
            // The break-even (C2): what a point you hold cost you against the price now - under it, selling loses
            // `loss` in all - and what a set costs you a point, now and with the list bought. `usual`: what you
            // usually sell a point for.
            even: {
                each: book.left ? Math.ceil(book.each) : 0, now: pointsPrice, usual: usual.price, usualFrom: usual.from,
                loss: pointsPrice > 0 && book.left > 0 && pointsPrice < book.least ? Math.round(book.cost - book.left * pointsPrice) : 0,
                sets: even,
            },
            book: { ...book, rows: book.rows.slice(0, 200) },
            heldDays: heldByDay(i.book || [], now, 14),
            chart: vwPriceChart(i.days || [], i.wallDays || [], now, level, book.least),
        };

        // ---- my prices ---------------------------------------------------------------------------------------------------
        const forum = forumText({ open: settings.open, pct: settings.pct, stocks: sets.map((s) => ({ pieces: s.pieces })), sets: on });
        // The thread names your rate - the most you pay. What you pay today is beside it when it is less.
        const paidRows = sets.map((s) => ({ label: s.label, pct: s.rate.pct }));
        const thread = i.thread && i.thread.title ? { ...i.thread, check: threadCheck(i.thread.title, { open: settings.open, pct: settings.pct, paid: paidRows }) } : null;
        const setCost = sets.length ? Math.max(...sets.map((s) => s.rate.cost)) : 0;
        const cover = cash == null ? null : shareCovers(share.total, share.inSets, settings.shareMax, setCost);
        const verdict = shopVerdict({
            open: settings.open, sets: sets.map((s) => ({ ...s.rate, name: s.label })), hot, since: i.hotSince, onList: (key) => cartList.some((l) => l.key === key),
            needUnits, coverSets: cover, now,
        });
        const w3bList = (i.w3b && i.w3b.list) || null;
        const w3bDiff = w3bList ? listDiff(w3bList, desiredList(pieces, settings.open), ALL_PIECE_IDS) : null;
        const rates = [];
        for (let r = 99; r <= 104.001; r += 0.5) rates.push(Math.round(r * 10) / 10);
        const bidOf = (id) => (pieceOf(id) || {}).other || null;
        const prices = {
            // `pct`: the most you pay (what you typed). `paid`: what you pay today, short ("101%", "100.6% to 101%").
            pct: settings.pct, open: settings.open, least: settings.least, paid: rateShort(paidRows), paidRows,
            cap: sets.length ? Math.min(...sets.map((s) => s.rate.cap)) : 0,
            // The table fixed for the hour (null: the shop is closed, or nothing is fixed yet - `sets` then say what
            // you would pay now). `held`: its hour is over and it stands still while a trade is open.
            fixed: fixed ? { at: fixed.at, until: fixed.until, held: !!fixed.held } : null,
            // The points price the table was made at, and where it is from ('today' | 'usual'); today's beside it.
            points: { price: payTable.price, from: payTable.from, today: pointsPrice, usual: usual.price, usualFrom: usual.from },
            // What a fix would take now: the engine fixes the hour's table from this.
            live,
            sets: sets.map((s) => {
                // The piece holding the set back (you hold fewest of it), when its best other buyer pays over your
                // ceiling: only said - you do not pay over the ceiling for it.
                const first = s.pieces.find((p) => p.need > 0) || null;
                const others = othersPay(setByKey(s.key), mv, bidOf, now);
                const firstBid = first && first.other && first.other.at > 0 ? first.other : null;
                return {
                    key: s.key, label: s.label, color: s.color, cost: s.rate.cost, profit: s.rate.profit, kept: s.rate.kept, ok: s.rate.ok, cap: s.rate.cap, points: s.points,
                    pct: s.rate.pct, typed: settings.pct, capped: s.rate.pct < settings.pct, down: s.rate.down,
                    others, short: firstBid && s.rate.cap > 0 && firstBid.pct > s.rate.cap ? { name: first.short, pct: firstBid.pct } : null,
                };
            }),
            verdict, cover, forum, thread,
            w3b: {
                known: !!w3bList, at: (i.w3b && i.w3b.listAt) || 0, error: (i.w3b && i.w3b.error) || '', sync: settings.w3bSync,
                diff: w3bDiff, matches: w3bDiff ? listMatches(w3bDiff) : null,
                // Kept by itself, and this hour's prices were already brought to TornW3B: a list that differs now is
                // written when they are next fixed (engine stepOwn). Your own press sends at any time.
                waits: !!settings.w3bSync && !!fixedIn && fixed === fixedIn && i.rateSent === fixedIn.rev,
                lastReceiptAt: (i.w3b && i.w3b.lastReceiptAt) || 0, listedUntil: listedUntil((i.w3b && i.w3b.lastReceiptAt) || 0),
            },
            chart: {
                x: rates, least: sets[0] && sets[0].value ? Math.round(sets[0].value - sets[0].value / (1 + settings.least / 100)) : 0,
                series: sets.map((s) => ({ key: s.key, name: s.name, color: s.color, data: rates.map((r) => Math.round(s.value - s.rate.market * r / 100)) })),
            },
        };

        // ---- the ledger --------------------------------------------------------------------------------------------------
        // Pieces that left as themselves (F3): sold in your bazaar, on the Item Market or in a trade - each its own
        // profit or loss against what it had cost you - or given away (shown, and counted for nothing).
        const directRows = [...(i.direct || [])].sort((a, b) => b.t - a.t).map((d) => ({ ...d, name: nameOf(d.itemId), gain: d.give ? 0 : d.got - d.cost }));
        const directSold = directRows.filter((d) => !d.give);
        const days = profitBuckets(book.rows, mugs.rows, now, 'day', 14, directSold);
        const sum14 = profitSum(days);
        const sum7 = profitSum(days.slice(-7));
        const buys = (i.rows || []).filter((r) => r.side === 'buy');
        const soldRows = book.rows.filter((r) => r.kind === 'sold');
        // What the pieces and points you hold would bring today: each piece at its share of a set, each point at the price now.
        const worthNow = Object.entries(i.pool || {}).reduce((s, [id, c]) => s + c.n * pieceBrings(id, mv, pointsPrice), 0) + book.left * pointsPrice;
        const ledger = {
            days, weeks: profitBuckets(book.rows, mugs.rows, now, 'week', 12, directSold), months: profitBuckets(book.rows, mugs.rows, now, 'month', 12, directSold),
            sum: sum14, cum: runningTotal(days),
            notSold: pool.cost + book.cost, notSoldPoints: book.left, poolEst: pool.est, poolUnits: pool.units,
            // F2: the same at what it is worth today (0 while there is no points price), and the difference.
            notSoldWorth: pointsPrice ? Math.round(worthNow) : 0, notSoldDiff: pointsPrice ? Math.round(worthNow) - (pool.cost + book.cost) : 0,
            // F1: a part of what is left rests on an estimated cost (pieces never seen bought), as a share.
            estLeft: pool.cost + book.cost > 0 ? ((i.pool ? Object.entries(i.pool).reduce((s, [, c]) => s + (c.n ? c.cost * c.est / c.n : 0), 0) : 0) + book.cost * book.est) / (pool.cost + book.cost) : 0,
            sold: soldRows.map((r) => {
                const mug = mugs.rows.find((m) => m.saleId === r.id) || null;
                // F4: points of the lot that were yours before the book began: sold, and counted for nothing.
                const before = Math.max(0, vwWhole(r.points) - r.mine);
                return { id: r.id, t: r.t, points: r.mine, each: r.each, got: Math.round(r.mine * r.each), cost: r.cost, gain: r.gain, about: vwNum(r.est) >= BOOK_ABOUT && r.mine > 0, before, beforeGot: Math.round(before * r.each), mug: mug ? { counted: mug.counted, after: mug.after } : null };
            }),
            before: { points: vwSum(soldRows, (r) => Math.max(0, vwWhole(r.points) - r.mine)), got: Math.round(vwSum(soldRows, (r) => Math.max(0, vwWhole(r.points) - r.mine) * r.each)) },
            direct: {
                rows: directRows.slice(0, 200),
                units: vwSum(directSold, (d) => d.qty), got: vwSum(directSold, (d) => d.got), cost: vwSum(directSold, (d) => d.cost), gain: vwSum(directSold, (d) => d.gain),
                given: vwSum(directRows.filter((d) => d.give), (d) => d.qty), givenCost: vwSum(directRows.filter((d) => d.give), (d) => d.cost),
            },
            buys: [...buys].sort((a, b) => b.t - a.t).slice(0, 300).map((r) => ({ id: r.id, t: r.t, itemId: r.itemId, name: nameOf(r.itemId), qty: r.qty, each: Math.round(r.each), paid: Math.round(r.qty * r.each), venue: r.venue, who: r.whoName || (i.names && i.names(r.who)) || '', rate: mv(r.itemId) ? r.each / mv(r.itemId) * 100 : 0 })),
            where: vwWhere(buys, now, 14),
            swapped: vwSwapped(i.book || [], now, 14),
            sellers: vwSellers(buys, open, nameOf, i.names, now),
            mugs,
        };

        // ---- the dashboard -----------------------------------------------------------------------------------------------
        const todo = [];
        // The stops a thing to do names, the one that saves most first: `gain` is against what the line above them says
        // (what you pay your sellers for the cheap listings, the pieces' worth for the rest).
        const firstStops = (stops) => stops.slice(0, VW_FIRST_STOPS).map((s) => ({ im: s.im, who: s.who, whoId: s.whoId, units: s.units, cost: s.cost, gain: s.gain }));
        if (open.length) todo.push({ kind: 'trades', tone: 'warn', n: open.length, wait: trades.wait, money: trades.waitMoney });
        if (hotPlan.length) todo.push({ kind: 'hot', tone: '', n: vwSum(hotPlan, (l) => l.q), stops: hotPlanStops.length, pic: hotPlan[0].id, first: firstStops(hotPlanStops), cost: vwSum(hotPlanStops, (s) => s.cost), full: fullAfter((p) => onList(hotPlan, p.id)) });
        else if (buy.plan.units) todo.push({ kind: 'buy', tone: '', n: buy.plan.units, stops: buy.plan.stops, pic: plan[0].id, first: firstStops(planStops), cost: buy.plan.cost, full: buy.plan.full });
        if (fullAll) todo.push({ kind: 'swap', tone: 'brand', n: fullAll, points: vwSum(sets, (s) => s.full * s.points) });
        if (book.left) todo.push(hold ? { kind: 'hold', tone: 'warn', usual: level.lo || 0 } : { kind: 'sell', tone: 'good', n: book.left, price: pointsPrice, each: Math.ceil(book.cost / book.left), loss: pointsPrice > 0 && book.left * pointsPrice < book.cost });

        return {
            at: now,
            ready: i.stockAt > 0 && pieces.some((p) => p.mv > 0),
            settings,
            top: { points: pointsPrice, cheap, usual: level, onHand: money.onHand == null ? null : vwWhole(money.onHand), vault: money.vault == null ? null : vwWhole(money.vault), pricesAt: i.pricesAt || 0, pointsAt: i.pointsAt || 0, stockAt: i.stockAt || 0, stock: i.stock || null },
            nav: { full: fullAll, need: pieces.filter((p) => p.need > 0).length, trades: open.length, hot: trades.wait > 0 },
            shop: { open: settings.open, pct: settings.pct, paid: prices.paid, state: verdict.state, lamp: verdict.lamp },
            sets, pieces, buy, trades, points, prices, ledger,
            dash: {
                full: fullAll, pointsHeld, made: book.left, profit7: sum7.profit, today: days[days.length - 1].profit, todo,
                pays: sets.map((s) => ({ key: s.key, label: s.label, pays: s.pays, priced: s.priced })),
                paysDays: ((i.hist && i.hist.pays) || []).slice(-40),
            },
            stock: { units: pool.units, cost: pool.cost, est: pool.est, made: book.left, sold14: sum14.points },
            share: { ...share, max: settings.shareMax, days: ((i.hist && i.hist.share) || []).slice(-14) },
            tape: pieces.filter((p) => p.lowAll).map((p) => ({ id: p.id, name: p.name, set: p.set, price: p.lowAll.price })),
        };
    }

    /** The cheap listings (hotListings) by seller: how many pieces, what they cost, how far under what you pay sellers. */
    function vwHotStops(hot) {
        const by = new Map();
        for (const h of hot || []) {
            const place = h.im ? 'im' : 'b:' + (h.whoId ?? h.who ?? '');
            if (!by.has(place)) by.set(place, { im: !!h.im, who: h.who, whoId: h.whoId, units: 0, cost: 0, gain: 0 });
            const s = by.get(place);
            s.units += h.q;
            s.cost += h.q * h.price;
            s.gain += h.q * (h.pay - h.price);
        }
        return [...by.values()].sort((a, b) => (a.im - b.im) || b.gain - a.gain);
    }

    /** The points price by day: the first wall and the lowest listing, the usual range, your least price. */
    function vwPriceChart(days, wallDays, now, level, least) {
        const from = vwDay(now - 39 * VW_DAY_MS);
        const low = new Map((days || []).filter((d) => d.day >= from && d.n > 0).map((d) => [d.day, Math.round(d.sum / d.n)]));
        const wall = new Map((wallDays || []).filter((d) => d.day >= from && d.n > 0).map((d) => [d.day, Math.round(d.sum / d.n)]));
        const x = [...new Set([...low.keys(), ...wall.keys()])].sort();
        return {
            x, low: x.map((d) => low.get(d) ?? wall.get(d)), wall: x.map((d) => wall.get(d) ?? low.get(d)),
            usual: level && level.lo ? { lo: level.lo, hi: level.hi } : null, least: least || 0,
        };
    }

    /** Pieces bought by day and by where: { x: [day], bazaar, market, trade }. */
    function vwWhere(buys, now, days) {
        const x = [];
        for (let k = days - 1; k >= 0; k--) x.push(vwDay(now - k * VW_DAY_MS));
        const at = new Map(x.map((d, k) => [d, k]));
        const out = { x, bazaar: x.map(() => 0), market: x.map(() => 0), trade: x.map(() => 0) };
        for (const r of buys) {
            const k = at.get(vwDay(r.t));
            if (k != null && out[r.venue]) out[r.venue][k] += vwWhole(r.qty);
        }
        return out;
    }

    /** Sets swapped at the museum by day, from the points book: { x, plushie, flower }. */
    function vwSwapped(entries, now, days) {
        const x = [];
        for (let k = days - 1; k >= 0; k--) x.push(vwDay(now - k * VW_DAY_MS));
        const at = new Map(x.map((d, k) => [d, k]));
        const out = { x, plushie: x.map(() => 0), flower: x.map(() => 0) };
        for (const e of entries) {
            const set = e.kind === 'made' && e.set ? setByKey(e.set) : null;
            const k = at.get(vwDay(e.t));
            if (set && k != null) out[set.key][k] += Math.round(vwWhole(e.points) / set.points);
        }
        return out;
    }

    /** Who sells to you: trades, units, what you paid, what they mostly bring, when they last came. */
    function vwSellers(buys, open, nameOf, names, now) {
        const by = new Map();
        for (const r of buys) {
            if (r.venue !== 'trade' || !r.who) continue;
            const s = by.get(r.who) || { whoId: r.who, who: r.whoName || (names && names(r.who)) || '', trades: new Set(), units: 0, paid: 0, items: new Map(), last: 0 };
            s.trades.add(String(r.id).split(':')[1]);
            s.units += vwWhole(r.qty);
            s.paid += Math.round(r.qty * r.each);
            s.items.set(r.itemId, (s.items.get(r.itemId) || 0) + vwWhole(r.qty));
            s.last = Math.max(s.last, r.t);
            if (!s.who && r.whoName) s.who = r.whoName;
            by.set(r.who, s);
        }
        const openWith = new Set((open || []).map((t) => String(t.whoId)));
        return [...by.values()].sort((a, b) => b.paid - a.paid).map((s) => ({
            whoId: s.whoId, who: s.who, trades: s.trades.size, units: s.units, paid: s.paid, last: s.last,
            brings: [...s.items].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([id]) => shortName(nameOf(id))).join(', '),
            came: openWith.has(String(s.whoId)) ? 'now: a trade is open' : agoWords(s.last, now),
        }));
    }

    /** The pieces as a list takes them: `take` units, each under `takeLine` - Buy, and the Stretch that finishes a set. */
    const listPieces = (pieces) => (pieces || []).map((p) => ({ ...p, worth: p.takeLine ?? p.worth, need: p.take ?? p.need }));
    /** ... and as a list keeps them: a line stays for as long as its listing is under the Stretch line. */
    const keepPieces = (pieces) => (pieces || []).map((p) => ({ ...p, worth: p.lineS ?? p.worth }));

    /** A piece's line in the view, by item id. What a mark on a Torn page reads. */
    const viewPiece = (view, itemId) => ((view && view.pieces) || []).find((p) => String(p.id) === String(itemId)) || null;

    /** The view as the Torn tabs get it: the long tables left out. */
    function viewForTabs(view) {
        return {
            ...view,
            pieces: view.pieces.map((p) => ({ ...p, offers: p.offers.slice(0, 3), hist: [] })),
            sets: view.sets.map((s) => ({ ...s, pieces: s.pieces.map((p) => ({ id: p.id, name: p.name, short: p.short, held: p.held, need: p.need, ahead: p.ahead, state: p.state, top: p.top })), ladder: [] })),
            points: { ...view.points, book: { ...view.points.book, rows: [] }, heldDays: [], chart: null },
            ledger: null, dash: null,
            buy: { ...view.buy, depth: null },
        };
    }

    /* ===== src/api/torn.js ===== */
    /*
     * Thin wrappers over the Torn endpoints this tool uses. Every one of these
     * works with a Public access key, except fetchInventory: reading your own
     * inventory needs Limited access, and only the selling page calls it, with
     * the separate key that page keeps.
     */

    /** Torn's access levels, lowest first. Public is all the overlay needs. */
    const ACCESS_PUBLIC = 1;
    const ACCESS_LIMITED = 3;

    /** "Access level of this key is not high enough". */
    const TORN_ERROR_ACCESS_LEVEL = 16;

    const ACCESS_LEVEL_NAMES = {
        1: 'Public',
        2: 'Minimal',
        3: 'Limited',
        4: 'Full',
    };

    /**
     * A key too weak for Torn Archive (3.14.3 review): a Public or Minimal key cannot
     * read your inventory. The reason in words, or null. Limited, Full and custom
     * keys (whose level Torn gives as 0) pass - custom keys may include it.
     */
    function keyTooLowForInventory(info) {
        const level = Number(info && info.access_level);
        if (level === 1 || level === 2) return 'That is a ' + ACCESS_LEVEL_NAMES[level] + ' key: Torn Archive needs a Limited key to read your inventory.';
        return null;
    }

    /**
     * The full item database. Public key.
     *
     * Read from v2 (`/v2/torn/items`), where an item no NPC will buy has
     * `value.sell_price: null` - the game's "Sell: N/A". That null is the whole
     * point: an item without an NPC sell price must never be priced as if an NPC
     * would pay for it. v1 (`torn?selections=items`) is the fallback if v2 fails.
     *
     * Returned in the v1 shape ({ "<id>": { name, sell_price, market_value } })
     * so buildItemIndex has one input format.
     */
    async function fetchItems(client) {
        try {
            return await fetchItemsV2(client);
        } catch (error) {
            // A dead key, a rate limit or an IP block fails v1 the same way; do
            // not ask twice. Anything else (a v2 shape change, an unknown
            // selection) falls back.
            const code = error && Number(error.code);
            if (KEY_DEAD_CODES.has(code) || code === TORN_ERROR_RATE_LIMIT || code === TORN_ERROR_IP_BLOCK) {
                throw error;
            }
        }

        const data = await client.get('torn', { selections: 'items' });

        if (!data || !data.items) {
            throw new Error('Torn API returned no item database.');
        }

        /*
         * v1 has no shop list, so its `sell_price` cannot be checked against a
         * shop in Torn - and it is exactly the field that says a Companion
         * Script sells for $12m. No NPC price from v1 at all: an item with no
         * NPC price is never shown as an NPC deal, which is the safe way to be
         * wrong. `npc_unknown` makes the cache short-lived (items.js), so the
         * real prices return with v2.
         */
        const out = {};
        for (const [id, item] of Object.entries(data.items)) {
            out[id] = { ...item, sell_price: null, npc_shop: null, npc_unknown: true };
        }
        return out;
    }

    /**
     * What an NPC shop in Torn pays for an item, and which shop.
     *
     * Neither API field is trustworthy alone; each lies differently. Captured
     * live, 2026-09-24, against the game's own "Sell:" line:
     *
     *   item                sell_price  shops                                game
     *   Beretta M9          1300        [Torn  Big Al's       sell 1300]     $1,300
     *   Companion Script    12000000    []                                   N/A
     *   Stick of Dynamite   null        [China General Store  sell 37500]    N/A
     *   Pillow              150         [UAE sell 75, Torn Big Al's sell 150] $150
     *
     * Foreign shops' "sell" is a filler of 75% of their buy price (Dynamite
     * 50,000 -> 37,500; Printing Paper 75,000 -> 56,250) - and nobody can sell
     * abroad anyway: items are bought abroad and sold in Torn. So an item has
     * an NPC buyer only when BOTH hold:
     *
     *   - `sell_price` is a positive number (rules out Dynamite & co.), and
     *   - a shop in Torn lists a positive sell price (rules out the Companion
     *     Scripts and anything sold only abroad).
     *
     * The price is that Torn shop's (preferring the one matching `sell_price`).
     * A payload from before `shops` existed falls back to a vendor in Torn.
     *
     * @returns {{price: number|null, shop: string|null}}
     */
    function npcSaleFromValue(value) {
        const v = value || {};
        const none = { price: null, shop: null };

        /*
         * Torn removes `sell_price`, `buy_price` and `vendor` from value on
         * 2027-01-01, leaving `shops`. Without the field, a shop in Torn that
         * pays a positive price is the NPC price on its own - which gives the
         * same answer as both rules together for every item captured above.
         */
        if (!Object.prototype.hasOwnProperty.call(v, 'sell_price') && Array.isArray(v.shops)) {
            const torn = tornShops(v.shops, 'sell_price');
            return torn.length ? torn.reduce((a, b) => (b.price > a.price ? b : a)) : none;
        }

        const listed = Number(v.sell_price);

        if (!Number.isFinite(listed) || listed <= 0) return none;

        if (Array.isArray(v.shops)) {
            const torn = tornShops(v.shops, 'sell_price');
            if (!torn.length) return none;
            return torn.find((t) => t.price === listed) || torn.reduce((a, b) => (b.price > a.price ? b : a));
        }

        if (v.vendor && v.vendor.country === 'Torn') {
            return { price: listed, shop: v.vendor.name || null };
        }

        return none;
    }

    /** Shops in Torn (not abroad) with a positive `field` price: [{price, shop}]. */
    function tornShops(shops, field) {
        const out = [];
        for (const s of shops || []) {
            const price = Number(s && s[field]);
            if (s && s.country === 'Torn' && Number.isFinite(price) && price > 0) out.push({ price, shop: s.shop || null });
        }
        return out;
    }

    /** What a shop in Torn sells an item for, from `buy_price` or (after 2027-01-01) `shops`. */
    function shopBuyPriceFromValue(value) {
        const v = value || {};
        if (Object.prototype.hasOwnProperty.call(v, 'buy_price')) return v.buy_price ?? null;
        const torn = tornShops(v.shops, 'buy_price');
        return torn.length ? Math.min(...torn.map((t) => t.price)) : null;
    }

    /** v2 item list -> v1-shaped map. Follows `_metadata.links.next` if paged. */
    async function fetchItemsV2(client) {
        const out = {};
        let params = { sort: 'ASC' };

        for (let page = 0; page < 20; page += 1) {
            const data = await client.get('v2/torn/items', params);

            if (!data || !Array.isArray(data.items)) {
                throw new Error('Torn API v2 returned no item list.');
            }

            for (const item of data.items) {
                if (!item || !Number.isFinite(Number(item.id))) continue;
                const value = item.value || {};
                const npc = npcSaleFromValue(value);

                out[String(item.id)] = {
                    name: item.name,
                    type: item.type || null,
                    sub_type: item.sub_type || null,
                    // null = "Sell: N/A": no NPC shop buys it.
                    sell_price: npc.price,
                    npc_shop: npc.shop,
                    buy_price: shopBuyPriceFromValue(value),
                    market_value: value.market_price ?? 0,
                    circulation: item.circulation ?? 0,
                };
            }

            const next = data._metadata && data._metadata.links && data._metadata.links.next;
            if (!next) break;

            // Absolute or relative, it is a page of the same list on api.torn.com.
            const nextUrl = new URL(next, 'https://api.torn.com/v2/torn/items');
            params = Object.fromEntries(nextUrl.searchParams);
            delete params.key;
        }

        if (Object.keys(out).length === 0) {
            throw new Error('Torn API v2 returned an empty item list.');
        }

        return out;
    }

    /**
     * What the current key can actually do.
     *
     * Used only to warn the user when they have pasted in a key with more access
     * than this tool needs. Written so that an unexpected payload shape means
     * "cannot tell" rather than a false alarm or a crash.
     *
     * @returns {{level: number|null, name: string|null}}
     */
    async function fetchKeyAccess(client) {
        try {
            const data = await client.get('key', { selections: 'info' });

            const level = Number(data && data.access_level);
            const name =
                (data && data.access_type) ||
                ACCESS_LEVEL_NAMES[level] ||
                null;

            return {
                level: Number.isFinite(level) ? level : null,
                name,
            };
        } catch {
            // The check is advisory. If it fails, say nothing rather than
            // blocking a key that is probably fine.
            return { level: null, name: null };
        }
    }

    /**
     * Item Market listings for one item: GET /v2/market/{id}/itemmarket.
     *
     * Public key. "Globally cached selection" - Torn serves everyone the same
     * snapshot and refreshes it no faster than `cache_delay` seconds (30 in every
     * observed response), so asking again before cache_timestamp + cache_delay
     * returns the same rows and only spends quota. The caller uses `nextAt` to
     * avoid that.
     *
     * The response names no seller and no listing id: a row is a price and an
     * amount. So an Item Market hit links to the item, never to a seller.
     *
     * @returns {Promise<{listings: Array<{price: number, amount: number}>,
     *   averagePrice: number|null, cacheTimestamp: number|null, nextAt: number,
     *   total: number}>} cacheTimestamp and nextAt in ms
     */
    /** An item's Item Market listings are asked again no sooner than this (Torn caches 30 s). */
    const ITEM_MARKET_MIN_RECHECK_MS = 10000;

    async function fetchItemMarket(
        client,
        itemId,
        { limit = 20, offset = 0, now = Date.now(), tag = null, priority = 'high' } = {},
    ) {
        const data = await client.get(
            'v2/market/' + encodeURIComponent(String(itemId)) + '/itemmarket',
            { limit, offset },
            { tag, priority },
        );

        const market = (data && data.itemmarket) || {};
        const raw = Array.isArray(market.listings) ? market.listings : [];

        const cacheTs = Number(market.cache_timestamp);
        const cacheDelay = Number(market.cache_delay);
        const cacheTimestamp = Number.isFinite(cacheTs) && cacheTs > 0
            ? cacheTs * 1000
            : null;
        const delayMs = (Number.isFinite(cacheDelay) && cacheDelay > 0
            ? cacheDelay
            : 30) * 1000;

        const average = Number(market.item && market.item.average_price);

        return {
            listings: raw
                .map((l) => ({
                    price: Number(l && l.price) || 0,
                    amount: Number(l && (l.amount ?? l.quantity)) || 0,
                }))
                .filter((l) => l.price > 0 && l.amount > 0),
            averagePrice: Number.isFinite(average) && average > 0 ? average : null,
            cacheTimestamp,
            // Torn's snapshot renews delayMs after its timestamp. A timestamp that
            // is already old made the item due again on every 3 s tick (the whole
            // feed budget on a few items): never sooner than ITEM_MARKET_MIN_RECHECK_MS.
            nextAt: Math.max((cacheTimestamp || now) + delayMs, now + ITEM_MARKET_MIN_RECHECK_MS),
            total: Number(data && data._metadata && data._metadata.total) || raw.length,
        };
    }

    /** "Wrong fields" and "Incorrect category": a parameter Torn did not accept. */
    const TORN_ERROR_WRONG_FIELDS = 4;
    const TORN_ERROR_INCORRECT_CATEGORY = 21;

    /**
     * The `cat` values /v2/user/inventory accepts: TornInventoryItemType in
     * Torn's published OpenAPI spec (@types/torn-api, components/schemas).
     */
    const TORN_INVENTORY_CATEGORIES = [
        'Collectible', 'Clothing', 'Other', 'Tool', 'Melee', 'Defensive',
        'Material', 'Car', 'Primary', 'Secondary', 'Book', 'Special',
        'Supply Pack', 'Temporary', 'Enhancer', 'Artifact', 'Flower', 'Booster',
        'Medical', 'Candy', 'Jewelry', 'Alcohol', 'Plushie', 'Drug', 'Energy Drink',
    ];

    /** Torn refused the request for want of a (valid) `cat`. */
    function isCategoryError(error) {
        const code = Number(error && error.code);
        if (code === TORN_ERROR_INCORRECT_CATEGORY || code === TORN_ERROR_WRONG_FIELDS) return true;
        return /categor/i.test(String((error && error.message) || ''));
    }

    /** Every page of one inventory request (with or without a category). */
    async function fetchInventoryPages(client, params, limit, { priority = 'normal', onStamp = null } = {}) {
        const out = [];
        let offset = 0;

        for (let page = 0; page < 40; page += 1) {
            let data;
            try {
                data = await client.get('v2/user/inventory', { ...params, limit, offset }, { tag: 't.inventory', priority });
            } catch (error) {
                if (error && Number(error.code) === TORN_ERROR_ACCESS_LEVEL) {
                    throw new TornApiError('This key cannot read your inventory: it needs Limited access.', {
                        code: TORN_ERROR_ACCESS_LEVEL,
                    });
                }
                throw error;
            }

            out.push(...parseInventoryPage(data));
            // The time Torn's answer carries (seconds), handed on as it came: how old Torn's count is, if it says.
            const stamp = Number(data && data.inventory && data.inventory.timestamp);
            if (onStamp && Number.isFinite(stamp) && stamp > 0) onStamp(stamp);

            const next = nextInventoryOffset(data);
            if (next === null || next <= offset) break;
            offset = next;
        }

        return out;
    }

    /**
     * Your own inventory: GET /v2/user/inventory, paged with limit/offset.
     * Needs a LIMITED key; Torn caches it for about an hour per category.
     * Only the selling page calls this, with that page's own key. Error 16
     * (access level too low) is reported as such, never retried.
     *
     * The spec says `cat` is optional, but Torn has been seen to answer
     * "Incorrect category" without it. So: ask once without a category; if that
     * is refused as a category or field error, ask once per category instead
     * (25 calls, each paged, all through the shared limiter) and merge. A
     * category Torn no longer knows is skipped, never fatal.
     *
     * `byCategoryFirst` (Torn Archive: two categories hold every set piece) asks
     * for the named categories straight away, so the refused first try is not
     * spent every hour; only when Torn knows none of them is the whole inventory
     * asked for, and a refusal of that is an error - never an empty inventory.
     *
     * `priority` ('normal' unless said): Torn Archive asks 'high' - its whole count
     * stands on this read. `onStamp(seconds)`: told the time each page of Torn's
     * answer carries, when it carries one.
     *
     * @returns {Promise<Array>} rows from parseInventoryPage, every page
     */
    async function fetchInventory(client, { limit = 250, categories = TORN_INVENTORY_CATEGORIES, byCategoryFirst = false, priority = 'normal', onStamp = null } = {}) {
        const how = { priority, onStamp };
        if (byCategoryFirst) {
            const rows = [];
            let known = 0;
            for (const cat of categories) {
                try {
                    rows.push(...(await fetchInventoryPages(client, { cat }, limit, how)));
                    known += 1;
                } catch (error) {
                    if (!isCategoryError(error)) throw error;
                }
            }
            if (known === categories.length) return rows;
            return fetchInventoryPages(client, {}, limit, how);
        }
        try {
            return await fetchInventoryPages(client, {}, limit, how);
        } catch (error) {
            if (!isCategoryError(error)) throw error;
        }

        const out = [];
        for (const cat of categories) {
            try {
                out.push(...(await fetchInventoryPages(client, { cat }, limit, how)));
            } catch (error) {
                if (!isCategoryError(error)) throw error;
            }
        }
        return out;
    }

    /**
     * The points market (3.24.0): GET /v2/market/pointsmarket. Public data, one call for every listing.
     * The answer is handed back as Torn gives it; core/points.js (parsePointsMarket) reads it, so a shape Torn
     * changes is one place to follow.
     */
    async function fetchPointsMarket(client, { tag = 't.sets', priority = 'low' } = {}) {
        return client.get('v2/market/pointsmarket', {}, { tag, priority });
    }

    /**
     * Your points, cash on hand and vault (3.24.0): GET /v2/user/money, Limited key.
     * @returns {{points: number|null, onHand: number|null, vault: number|null}} null = Torn did not say
     */
    function parseUserMoney(data) {
        const m = (data && (data.money || data)) || {};
        const pick = (...keys) => {
            for (const k of keys) {
                const v = m[k];
                if (v !== undefined && v !== null && Number.isFinite(Number(v))) return Number(v);
            }
            return null;
        };
        // The names Torn sent ride along (names only), so an answer Torn Archive cannot read can be said in the problem log.
        return { points: pick('points'), onHand: pick('wallet', 'money_onhand', 'cash'), vault: pick('vault', 'vault_amount'), keys: Object.keys(m).slice(0, 20) };
    }

    async function fetchMoney(client, { tag = 't.sets', priority = 'low' } = {}) {
        return parseUserMoney(await client.get('v2/user/money', {}, { tag, priority }));
    }

    /** Torn's list of log types (3.24.0): v1 torn/?selections=logtypes -> { logtypes: { id: title } }. Asked once a week. */
    async function fetchLogTypes(client, { tag = 't.sets', priority = 'low' } = {}) {
        return client.get('torn', { selections: 'logtypes' }, { tag, priority });
    }

    /* ===== src/engine/engine.js ===== */
    // The engine: asks Torn and TornW3B for what is due, folds each answer into the state (state.js), keeps the shopping
    // list and the run, and answers the hub's buttons. One engine runs, in the Archive's own tab; Torn's pages only
    // show what it worked out. Everything outside (keys, storage, the clock, the clients) is handed in, so the whole
    // loop runs in a test on stand-ins. Nothing here presses, buys, posts or sends anything on Torn.

















    const EG_MIN = 60000;
    const EG_HOUR = 3600000;
    const EG_DAY = 86400000;

    /** How often each thing is read. The pieces' prices follow the setting (1, 2, 5 or 10 minutes). */
    const READ_EVERY = Object.freeze({
        self: 6 * EG_HOUR, items: EG_HOUR, types: 7 * EG_DAY, log: 2 * EG_MIN, finished: 5 * EG_MIN, inventory: 5 * EG_MIN,
        money: EG_MIN, points: EG_MIN, trades: EG_MIN, thread: 10 * EG_MIN, ownList: 10 * EG_MIN, receipts: 30 * EG_MIN, bids: 6 * EG_HOUR,
    });
    // The inventory: everything else is worked out from it, so it is asked before anything that can wait ('high').
    // Torn counts it once an hour for each category and its answer says when it counted: it is asked again the moment
    // that hour is over (EG_INV_AFTER_MS past it), when you make a list or start a run, a little after a buy, and
    // every five minutes besides - two requests each time.
    const EG_INV_AFTER_MS = 5000;
    const EG_INV_AFTER_BUY_MS = 30000;
    /** After a buy seen on a page your log is asked this long after it, each time: Torn's log is the judge of the buy (state.js judgeSeen). */
    const EG_LOG_AFTER_BUY_MS = [5000, 20000, 65000];
    /**
     * The calm pace (1.3.0; the owner: "calm automatic is fine"). What decides which reads are due is worked out from
     * a view no older than this, not afresh after every answer: on 2026-10-11 the hub stood frozen 38 minutes of a day
     * working the view out after each of thousands of reads. A buy, a press, a note from a Torn tab or a read that
     * concerns your list still works it out at once.
     */
    const EG_CALM_MS = 3000;
    /** An old trade that priced a piece oddly is read again, this many a go (state.js tradesOdd). */
    const EG_REPRICE_AT_ONCE = 3;
    /** "Read" on your stock asks Torn at most this often. */
    const EG_STOCK_PRESS_MS = 10000;
    /** A read that failed is tried again after this long. */
    const RETRY_MS = EG_MIN;
    /** A piece you do not need is priced this many times less often than one you do. */
    const IDLE_TIMES = 10;
    /** TornW3B's full listing of an item is scarce (1,000 a day): never more than this many an hour, across all pieces. */
    const LISTINGS_PER_HOUR = 38;
    /** A piece's listing is read again after this long even when its cheapest price has not moved. */
    const LISTING_STALE_MS = 20 * EG_MIN;
    /** How many reads of one kind may be on their way at once. */
    const EG_FLIGHT = { market: 3, shops: 2, listings: 1, bids: 1 };
    /** TornW3B refuses a burst: its reads of one kind are started this far apart, however many are due. */
    const EG_GAP_MS = { listings: 7000, bids: 5000 };
    /** With no history to wait for after this long, the count starts from Torn's inventory anyway. */
    const EG_HISTORY_WAIT_MS = 3 * EG_MIN;
    /** Log pages read in one go, and finished trades read in full in one go. */
    const EG_LOG_PAGES = 5;
    const EG_TRADES_FULL = 8;
    /** A finished trade gets its receipt by itself this long after it ended (TornW3B lets a receipt be put right for 6 hours). */
    const EG_RECEIPT_WITHIN_MS = 6 * EG_HOUR;
    /** ... tried this many times at most, this far apart. */
    const EG_RECEIPT_TRIES = 3;
    const EG_RECEIPT_GAP_MS = 5 * EG_MIN;
    /** A read TornW3B refuses outright (401, 403) is not asked again every minute. */
    const EG_REFUSED_RETRY_MS = 30 * EG_MIN;
    /** Bazaars confirmed with Torn itself each round: the stops of your list and the cheapest places first. */
    const EG_SHOPS = 12;
    /** ... or this share of what Torn allows you a minute, when that is more (alone on the key: about 34 of 85). */
    const EG_SHOPS_SHARE = 0.4;
    /** A read of Torn's made this lately is the newest there is: "Read now" does not ask for it again. */
    const EG_JUST_READ_MS = 45000;
    /** The piece open on the hub: this many rows of its "Sold by" table are confirmed with Torn, while it was looked at this lately. */
    const EG_LOOK_ROWS = 14;
    /** How often one finished trade is asked for before it is left out and said. */
    const EG_TRADE_TRIES = 3;
    /** How far before the last finished trade read the list is asked from, in seconds (readFinished). */
    const EG_TRADES_BACK_S = 24 * 3600;
    const EG_LOOK_MS = 10 * EG_MIN;
    const EG_SYNC_GAP_MS = 2 * EG_MIN;

    const egMsg = (error) => String((error && error.message) || error || '');
    const egLocal = (error) => !!(error && (error.local || error.takingTurns));
    /** The shape of something sent - names and kinds, no value - for the problem log. */
    const egShape = (v) => (Array.isArray(v) ? '[' + (v.length ? egShape(v[0]) : '') + '] x ' + v.length : v && typeof v === 'object' ? '{ ' + Object.entries(v).map(([k, x]) => k + ': ' + egShape(x)).join(', ') + ' }' : typeof v);
    /** Words joined into as few log lines as hold them: a line of the problem log keeps 300 characters. */
    function egLines(words, room = 250) {
        const out = [];
        let line = '';
        for (const w of words) {
            if (line && line.length + 2 + w.length > room) { out.push(line); line = ''; }
            line += (line ? ', ' : '') + w;
        }
        if (line) out.push(line);
        return out;
    }

    /**
     * @param env {
     *   now()                          the clock
     *   load(part), save(part, value)  storage, one value per part of the state (and 'w3bHour', 'keyState')
     *   settings()                     core/settings.js archiveSettings()
     *   torn, full, w3b, own           the clients (api/client.js, api/ledger.js, api/w3b.js, api/tw3b-own.js)
     *   hasKey(kind)                   'limited' | 'full' | 'w3b'
     *   paused()                       true: nothing is asked (main.js never pauses; Torn Trading only changes the limits)
     *   say(kind, what, detail)        one line for the problem log
     *   changed()                      something the screen shows has changed
     *   notify(notice)                 a new trade: { title, body, tradeId }
     *   kick()                         (optional) a read came back: step again now, not at the next tick
     * }
     */
    function makeEngine(env) {
        const stored = {};
        for (const part of ENGINE_PARTS) stored[part] = env.load(part);
        const S = engineLoad(stored);
        const dirty = new Set();
        const due = {};
        const busy = {};
        const said = new Set();
        const off = new Set();
        const per = { market: {}, listings: {}, shops: {}, bids: {} };
        const flying = { market: 0, shops: 0, listings: 0, bids: 0 };
        const gapUntil = {};
        const started = env.now();
        let hour = (env.load('w3bHour') || []).filter((t) => Number.isFinite(t));
        let keyState = { limited: {}, full: {}, w3b: {}, ...(env.load('keyState') || {}) };
        let cache = null;
        /** The view last worked out, whatever has changed since: what the calm pace reads (calm). */
        let last = null;
        /** The list is to be checked against the listings at the next calm pass (tidySoon). */
        let tidyDue = false;
        let tidyAt = 0;
        /** When your log is asked for after a buy seen on a page (EG_LOG_AFTER_BUY_MS). */
        let logSoon = [];
        /** Finished trades Torn would not hand over, and how often (readFinished). */
        const tradeFails = {};
        /** The piece open on the hub's "Sold by" table (shopsWanted). Not kept: the next look says it again. */
        let looked = { id: '', at: 0 };
        let syncAt = 0;
        // Why the list was last not written by itself (said when it changes, not every step), and the request TornW3B
        // called wrong: the same one is not sent by itself again.
        let syncWhy = '';
        let listRefused = '';
        const flags = { w3b: false, receipt: null };

        const touch = (...parts) => { for (const p of parts) dirty.add(p); cache = null; };
        const settings = () => env.settings();
        const sayOnce = (kind, what, detail = null) => { if (said.has(kind)) return; said.add(kind); env.say('note', what, detail); };
        // A tab out of view ticks as rarely as once a minute: what waited for room is asked for as soon as a read comes back.
        const again = () => { if (env.kick) env.kick(); };

        function flush() {
            for (const part of dirty) env.save(part, S[part]);
            dirty.clear();
        }

        /** The view, worked out at most once per change. Timed for the speed log: the next zip shows what it took. */
        function view() {
            const now = env.now();
            if (cache && now - cache.at < 5000) return cache.view;
            const work = () => archiveView(engineInput(S, settings(), now, { logRead: logRead() }));
            const v = env.timed ? env.timed('engine', work) : work();
            const hot = hotSince(S.hot, v.buy.hot, now);
            if (JSON.stringify(hot) !== JSON.stringify(S.hot)) { S.hot = hot; dirty.add('hot'); }
            if (settleMugs(S, v.ledger.mugs.rows, now)) dirty.add('ledger');
            cache = { at: now, view: v };
            last = cache;
            return v;
        }

        /** The view as the calm pace takes it: the one last worked out while it is no older than EG_CALM_MS. */
        function calm() {
            const now = env.now();
            if (cache && now - cache.at < 5000) return cache.view;
            if (last && now >= last.at && now - last.at < EG_CALM_MS) return last.view;
            return view();
        }

        function setKeyState(kind, patch) {
            keyState = { ...keyState, [kind]: { ...keyState[kind], ...patch } };
            env.save('keyState', keyState);
            cache = null;
        }

        /** A key Torn refuses for good: said on its box, and not used again until it is changed. */
        function keyFailed(kind, error) {
            const code = error && Number(error.code);
            if (!KEY_DEAD_CODES.has(code)) return false;
            setKeyState(kind, { ok: false, error: egMsg(error) || 'Torn refused this key' });
            return true;
        }
        const keyOk = (kind) => env.hasKey(kind) && !keyState[kind].error;

        // ---- one read, with its bookkeeping -------------------------------------------------------------------------------

        function run(name, every, fn, { key = 'limited' } = {}) {
            if (busy[name] || off.has(name)) return;
            const now = env.now();
            if (now < (due[name] || 0)) return;
            busy[name] = true;
            due[name] = now + every;
            Promise.resolve()
                .then(fn)
                .catch((error) => {
                    // Refused here (paused, or our own limit): not a problem, asked again when there is room.
                    const refused = error && (error.http === 401 || error.http === 403);
                    due[name] = env.now() + (egLocal(error) && error.retryAt ? Math.max(5000, error.retryAt - env.now()) : refused ? Math.max(RETRY_MS, Math.min(every, EG_REFUSED_RETRY_MS)) : RETRY_MS);
                    if (egLocal(error)) return;
                    if (key) keyFailed(key, error);
                    sayOnce(name + '-failed', 'Could not read: ' + name, egMsg(error));
                })
                .finally(() => { busy[name] = false; flush(); env.changed(); again(); });
        }

        // ---- who you are, items, your money ---------------------------------------------------------------------------------

        async function readSelf() {
            const info = await fetchLedgerKeyInfo(env.torn);
            if (info.level != null && info.level < 3) { setKeyState('limited', { ok: false, error: 'not a Limited key' }); return; }
            if (info.userId && info.userId !== S.self.id) { S.self = { ...S.self, id: info.userId }; enBump(S, null); touch('self'); }
            setKeyState('limited', { ok: true, error: '' });
        }

        async function readFullKey() {
            const info = await fetchLedgerKeyInfo(env.full);
            if (!isFullKey(info)) { setKeyState('full', { ok: false, error: 'not a Full key' }); return; }
            if (S.self.id && info.userId && info.userId !== S.self.id) { setKeyState('full', { ok: false, error: "another player's key" }); return; }
            setKeyState('full', { ok: true, error: '' });
        }

        async function readItems() {
            const raw = await fetchItems(env.torn);
            if (!foldItems(S, raw, env.now())) throw new Error("Torn's item list came back without the set pieces.");
            touch('items');
        }

        async function readMoney() {
            const m = await fetchMoney(env.torn);
            if (!foldMoney(S, m, env.now())) { off.add('money'); sayOnce('money-shape', "Torn's answer for your money has none of the names known", 'it has: ' + ((m && m.keys) || []).join(', ')); return; }
            touch('money');
        }

        async function readPoints() {
            const json = await fetchPointsMarket(env.torn);
            if (!foldPoints(S, json, env.now())) { sayOnce('points-empty', 'The points market came back with no listing that could be read', 'the answer has: ' + Object.keys(json || {}).slice(0, 8).join(', ')); return; }
            touch('points');
        }

        async function readInventory() {
            // Where Torn wants a category named, only the two that hold set pieces are asked for.
            let tornAt = 0;
            const rows = await fetchInventory(env.torn, { categories: ['Plushie', 'Flower'], byCategoryFirst: true, priority: 'high', onStamp: (sec) => { tornAt = tornAt ? Math.min(tornAt, sec * 1000) : sec * 1000; } });
            const had = S.stock.tornAt || 0;
            foldInventory(S, rows, env.now(), tornAt);
            touch('stock', 'book');
            tidySoon(true);
            // Torn's next count, asked for as it is made.
            const age = stockAge(S.stock);
            if (age.nextAt > env.now()) due.inventory = Math.min(due.inventory || Infinity, age.nextAt + EG_INV_AFTER_MS);
            if (tornAt && tornAt !== had && env.say) env.say('note', 'Torn counted your items at ' + new Date(tornAt).toISOString().slice(11, 19) + ' UTC', age.tornAt ? null : 'that time is not trusted until a second read carries the same one');
        }

        // ---- your log and your trades ---------------------------------------------------------------------------------------

        async function readTypes() {
            const json = await fetchLogTypes(env.torn);
            const types = pointsLogTypes(json);
            foldLogTypes(S, types, outLogTypes(json), env.now());
            touch('types');
            const missing = ['made', 'sold', 'used'].filter((k) => !types[k].length);
            if (missing.length) sayOnce('types', "Torn's list of log types names none for: " + missing.join(', '), JSON.stringify(types.titles).slice(0, 300));
        }

        async function readLog() {
            const now = env.now();
            // A few kinds in a request, each sort by itself (state.js logTypeGroups says why).
            const groups = logTypeGroups(S.types);
            const use = { tag: 't.setslog', priority: 'low' };
            const gap = S.log.gap || null;
            const from = gap ? gap.from : S.log.from || Math.floor((now - BACKFILL_MS) / 1000);
            const priceNow = S.points.listings.length ? S.points.listings[0].cost : 0;
            const got = { ...(S.log.got || {}) };
            let newest = S.log.newest || 0;
            let pages = 0;
            // Where this go stopped short: the request it was on, and how far back it had come.
            let left = null;
            for (let g = gap && gap.g < groups.length ? gap.g : 0; g < groups.length && !left; g++) {
                let to = gap && gap.g === g ? gap.to : null;
                for (;;) {
                    if (pages >= EG_LOG_PAGES) { left = { g, to }; break; }
                    pages += 1;
                    // Torn's `from` is "after this time": the second already read is asked for again, so a row written in it
                    // after the last read is not lost (a row is taken once, by its id).
                    const rows = await fetchLogPage(env.full, { from: Math.max(0, from - 1), to, types: groups[g].ids, use });
                    const res = foldLog(S, rows, { now, priceNow });
                    for (const u of res.unread) sayOnce('log-row-' + u.type, 'A log row of type ' + u.type + ' ("' + u.title + '") could not be read', 'its data has: ' + u.keys.join(', '));
                    newest = Math.max(newest, res.newest);
                    got[groups[g].name] = (got[groups[g].name] || 0) + rows.length;
                    // A full page: older rows of the same stretch wait behind it.
                    if (rows.length < 100 || !res.oldest) break;
                    // `to` is "up to and including": the page's oldest second is asked for again, the rows of it that did
                    // not fit come with the next page. A page that is one second from end to end cannot be split so.
                    to = res.oldest === res.newest || res.oldest === to ? res.oldest - 1 : res.oldest;
                }
            }
            if (left) {
                // More rows in this stretch than one go reads: the next go carries on from here, at once.
                S.log = { ...S.log, gap: { from, to: left.to, g: left.g }, newest, got, at: now };
                due.log = 0;
            } else {
                S.log = { ...S.log, gap: null, newest, got, from: newest || from, until: now, at: now, backfilled: true };
                // Once per page load, for the zip: what Torn's log has brought, by sort.
                sayOnce('log-read', 'Your log, read through', groups.map((x) => x.name).filter((n, i, a) => a.indexOf(n) === i).map((n) => n + ': ' + (got[n] || 0) + ' rows').join(' · '));
                judgeBuys();
            }
            // Bought at a stop of the run: counted there.
            countRun();
            // 'seen': a buy tied to its log row is stored so. (Until 1.3.0 it was not, and after a reload the same buy
            // came off its seller's listing twice.)
            touch('log', 'book', 'ledger', 'outs', 'stock', 'run', 'seen');
            tidySoon(true);
        }

        /**
         * Torn's log is the judge of what a page saw: a buy it does not have, read a minute past it, is taken back
         * everywhere - and said, once, in the log and on the screen.
         */
        function judgeBuys() {
            const back = judgeSeen(S, env.now());
            if (!back.length) return;
            const nameOf = (id) => (S.items.list[String(id)] || [])[0] || 'item ' + id;
            for (const b of back) env.say('note', 'Not a buy after all: taken back', b.qty + ' x ' + nameOf(b.id) + (b.im ? ' on the Item Market' : ' at bazaar ' + b.whoId) + ', seen ' + new Date(b.t).toISOString().slice(11, 19) + " UTC. Torn's log, read past it, has no such buy.");
            touch('seen');
        }

        async function readTrades() {
            const now = env.now();
            const use = { tag: 't.setslog', priority: 'normal' };
            const list = await fetchTradesOpen(env.torn, { use });
            // The first look ever tells of nothing: those trades were open before Torn Archive was there.
            const first = !(S.trades.seen && S.trades.seen.began) || !Array.isArray(S.trades.told);
            const res = foldTradeList(S, list, now);
            touch('trades', 'names');
            if (res.closed.length) due.finished = 0;
            if (!Array.isArray(S.trades.told)) S.trades = { ...S.trades, told: [] };
            for (const id of res.read.slice(0, EG_TRADES_FULL)) {
                const t = foldTradeOpen(S, await fetchTrade(env.torn, id, use), env.now());
                touch('trades');
                // Told of once, when its pieces are in - which is after it was opened, often minutes after.
                if (!t || !tradeHasPieces(t) || S.trades.told.includes(id)) continue;
                S.trades = { ...S.trades, told: [...S.trades.told, id].slice(-400) };
                if (first) continue;
                cache = null;
                const shown = view().trades.open.find((x) => x.id === id);
                env.notify({ ...tradeNotice(t, shown ? shown.items : t.theirs.length, shown ? shown.total : 0), tradeId: id });
            }
        }

        async function readFinished() {
            const now = env.now();
            const use = { tag: 't.setslog', priority: 'low' };
            const from = S.ledger.tradesFrom || Math.floor((now - BACKFILL_MS) / 1000);
            // Whether Torn's `from` goes by when a trade was finished or when it was opened is not known: a day back is
            // asked for, and a trade is taken once by its id. A full page means a backlog: then from where it stood.
            let list = await fetchTradesPage(env.torn, { from: Math.max(0, from - EG_TRADES_BACK_S), use });
            if (list.length >= 100) list = await fetchTradesPage(env.torn, { from: Math.max(0, from - 1), use });
            let newest = from;
            let read = 0;
            let left = false;
            // The oldest trade that could not be read: the next go starts from it again, so it is not lost.
            let stuck = 0;
            for (const x of list) {
                if (!x || x.id == null) continue;
                const done = Number(x.completed_at ?? x.timestamp ?? x.modified_at) || 0;
                if (S.ledger.tradeIds.includes(String(x.id))) { newest = Math.max(newest, done); continue; }
                if (tradeFails[x.id] >= EG_TRADE_TRIES) { newest = Math.max(newest, done); continue; }
                if (read >= EG_TRADES_FULL) { left = true; break; }
                read += 1;
                let full = null;
                // One trade Torn refuses does not stop the ones after it: until 1.2.2 it did, and every later trade
                // (its pieces, its money) stayed out of the count for as long as that one failed.
                try { full = await fetchTrade(env.torn, x.id, use); } catch (error) {
                    tradeFails[x.id] = (tradeFails[x.id] || 0) + 1;
                    if (tradeFails[x.id] >= EG_TRADE_TRIES) env.say('note', 'A finished trade could not be read from Torn, and is left out', `trade ${x.id}: ${egMsg(error)}`);
                    else stuck = stuck ? Math.min(stuck, done || from) : done || from;
                    continue;
                }
                foldTradeFinished(S, full, now);
                newest = Math.max(newest, done);
            }
            if (stuck) newest = Math.min(newest, Math.max(from, stuck - 1));
            // Once: old trades that priced a piece with a whole trade's money (until 1.3.0 anything in a trade that was
            // not a set piece took none of the money) are read again and priced as they are now.
            if (!S.ledger.repriced && !left) {
                const odd = tradesOdd(S);
                for (const id of odd.slice(0, EG_REPRICE_AT_ONCE)) {
                    let full = null;
                    try { full = await fetchTrade(env.torn, id, use); } catch { full = null; }
                    const n = foldTradeReprice(S, id, full);
                    if (n) env.say('note', 'An old trade priced again', 'trade ' + id + ': ' + n + ' row(s) - its money is shared over everything that was in it');
                }
                if (odd.length <= EG_REPRICE_AT_ONCE) S.ledger = { ...S.ledger, repriced: true };
                else due.finished = 0;
            }
            countRun();
            S.ledger = { ...S.ledger, tradesFrom: newest, tradesAt: now, tradesBackfilled: S.ledger.tradesBackfilled || (!left && list.length < 100) };
            touch('ledger', 'trades', 'outs', 'stock', 'names');
            // More of them wait: the next go follows at once.
            if (left || list.length >= 100) due.finished = 0;
        }

        // ---- prices of the pieces -------------------------------------------------------------------------------------------

        async function readSummary() {
            foldSummary(S, await fetchW3bSummary(env.w3b, { tag: 'w.summary' }), env.now());
            touch('summary');
        }

        const pieceIds = () => setsTraded(settings()).flatMap((s) => s.pieces.map((p) => String(p.id)));

        function each(kind, ids, everyOf, fn, key = 'limited') {
            const now = env.now();
            const list = ids.filter((id) => !(per[kind][id] && per[kind][id].busy) && now >= ((per[kind][id] && per[kind][id].due) || 0));
            for (const id of list) {
                if (flying[kind] >= EG_FLIGHT[kind] || now < (gapUntil[kind] || 0)) return;
                if (EG_GAP_MS[kind]) gapUntil[kind] = now + EG_GAP_MS[kind];
                flying[kind] += 1;
                per[kind][id] = { busy: true, due: now + everyOf(id) };
                Promise.resolve()
                    .then(() => fn(id))
                    .catch((error) => {
                        per[kind][id].due = env.now() + (egLocal(error) && error.retryAt ? Math.max(5000, error.retryAt - env.now()) : RETRY_MS);
                        if (egLocal(error)) return;
                        if (key) keyFailed(key, error);
                        sayOnce(kind + '-failed', 'Could not read: ' + kind, egMsg(error));
                    })
                    .finally(() => { flying[kind] -= 1; per[kind][id].busy = false; flush(); env.changed(); again(); });
            }
        }

        function readMarkets(v) {
            const every = settings().readMin * EG_MIN;
            const need = new Map(v.pieces.map((p) => [String(p.id), p.need]));
            const ids = pieceIds().sort((a, b) => (need.get(b) || 0) - (need.get(a) || 0));
            each('market', ids, (id) => (need.get(id) > 0 ? every : every * IDLE_TIMES), async (id) => {
                const r = await fetchItemMarket(env.torn, id, { limit: 20, tag: 't.sets', priority: 'low' });
                foldMarket(S, id, r.listings, env.now());
                touch('offers');
            });
        }

        /** The piece whose bazaars are most worth a look: never read, then one whose cheapest price moved, then the oldest. */
        function listingDue(v) {
            const now = env.now();
            hour = hour.filter((t) => now - t < EG_HOUR);
            if (hour.length >= LISTINGS_PER_HOUR) return [];
            const rank = (p) => {
                const o = S.offers[String(p.id)] || {};
                const low = S.summary.low[String(p.id)] || 0;
                if (!o.bazAt) return 4;
                const moved = low > 0 && low !== o.bazLow && S.summary.at > o.bazAt;
                if (moved && p.need > 0 && low < p.worth) return 3;
                if (moved && p.need > 0) return 2;
                // Read by another PC of ours lately: the server has those bazaars, and reads them from Torn itself.
                const read = serverListReadAt(o.bazAt, p.id, serverOn(now) ? S.server.dir : null);
                if (now - read.at > LISTING_STALE_MS * (p.need > 0 ? 1 : IDLE_TIMES) + read.wait) return 1;
                return 0;
            };
            return v.pieces.map((p) => ({ id: String(p.id), r: rank(p), need: p.need })).filter((x) => x.r > 0).sort((a, b) => b.r - a.r || b.need - a.need).map((x) => x.id);
        }

        function readListings(v) {
            each('listings', listingDue(v), () => 30000, async (id) => {
                // Counted whether it was answered or not; a refusal of our own making (never sent) is not.
                const count = () => { hour.push(env.now()); env.save('w3bHour', hour); };
                const r = await fetchW3bListings(env.w3b, id, { tag: 'w.sets' }).catch((error) => { if (!egLocal(error)) count(); throw error; });
                count();
                foldListings(S, id, r.listings, env.now());
                touch('offers', 'names');
                tidySoon(false);
            }, null);
        }

        /** The bazaars to confirm with Torn itself: the run's stop, the stops of your list, the listings under your rate, the cheapest of what you need. */
        function shopsWanted(v) {
            const ids = [];
            const add = (id) => { if (id != null && id !== '' && !ids.includes(String(id))) ids.push(String(id)); };
            const cur = v.buy.run.stops.find((s) => s.state === 'cur');
            if (cur && !cur.im) add(cur.whoId);
            // The piece open on the hub's "Sold by" table: every bazaar the table shows is asked of Torn itself, so no
            // row there is TornW3B's older copy for longer than one round (the owner, 2026-10-11: "i press read now as
            // well, its still stale items, and non existent items").
            const seen = looked.id && env.now() - looked.at < EG_LOOK_MS ? viewPiece(v, looked.id) : null;
            const extra = seen ? seen.offers.slice(0, EG_LOOK_ROWS).filter((o) => o.src !== 'market').length : 0;
            if (seen) for (const o of seen.offers.slice(0, EG_LOOK_ROWS)) if (o.src !== 'market') add(o.whoId);
            if (extra) {
                const rest = [];
                const more = (id) => { if (id != null && id !== '' && !ids.includes(String(id)) && !rest.includes(String(id))) rest.push(String(id)); };
                for (const s of v.buy.stops) if (!s.im) more(s.whoId);
                for (const id of v.buy.check || []) more(id);
                for (const h of v.buy.hot) if (!h.im) more(h.whoId);
                for (const p of v.pieces) if (p.need > 0) for (const o of p.offers.slice(0, 2)) if (o.src !== 'market' && !o.out && o.price < p.worth) more(o.whoId);
                return [...ids, ...rest.slice(0, shopsCap())];
            }
            for (const s of v.buy.stops) if (!s.im) add(s.whoId);
            // The bazaars a list would use that are shown but not checked: checked, they count.
            for (const id of v.buy.check || []) add(id);
            for (const h of v.buy.hot) if (!h.im) add(h.whoId);
            for (const p of v.pieces) if (p.need > 0) for (const o of p.offers.slice(0, 2)) if (o.src !== 'market' && !o.out && o.price < p.worth) add(o.whoId);
            return ids.slice(0, shopsCap());
        }

        /** How many bazaars are kept checked with Torn at once. */
        const shopsCap = () => Math.max(EG_SHOPS, Math.floor((Number(env.torn && env.torn.maxPerMinute) || 0) * EG_SHOPS_SHARE));

        /** The server answered lately: what it holds is in step with Torn. */
        const serverOn = (now) => S.server.at > 0 && now - S.server.at < SERVER_QUIET_MS;

        /** Of those, the ones to ask Torn for here: a bazaar the server read from Torn within the time is not asked again. */
        function shopsDue(v) {
            const now = env.now();
            const every = settings().readMin * EG_MIN;
            const cur = v.buy.run.stops.find((s) => s.state === 'cur');
            return shopsWanted(v).filter((id) => {
                const theirs = serverShop(S.server.shops, id);
                return !(theirs && now - theirs.at < (cur && String(cur.whoId) === id ? Math.min(every, 30000) : every));
            });
        }

        function readShops(v) {
            const every = settings().readMin * EG_MIN;
            const stops = v.buy.run.stops;
            const cur = stops.find((s) => s.state === 'cur');
            // While a run is on, the stop you stand on and the one after it go ahead of every other read (A5).
            const next = cur ? stops[stops.indexOf(cur) + 1] : null;
            const first = new Set([cur, next].filter((s) => s && !s.im).map((s) => String(s.whoId)));
            each('shops', shopsDue(v), (id) => (cur && String(cur.whoId) === id ? Math.min(every, 30000) : every), async (id) => {
                const json = await env.torn.get('v2/user', { selections: 'bazaar', id }, { tag: 't.sets', priority: first.has(id) ? 'high' : 'normal' });
                if (!foldShop(S, id, json, env.now())) { sayOnce('shop-shape', "Torn's answer for a bazaar had no bazaar in it", 'it has: ' + Object.keys(json || {}).slice(0, 8).join(', ')); return; }
                touch('shops');
                // A bazaar of your list: the list follows at once. Any other: at the next calm pass.
                tidySoon(S.cart.some((l) => String(l.whoId) === String(id)));
            });
        }

        function readBids() {
            each('bids', pieceIds().filter((id) => !(S.bids[id] && env.now() - S.bids[id].at < READ_EVERY.bids)), () => READ_EVERY.bids, async (id) => {
                const r = await fetchW3bItemTraders(env.w3b, id, { tag: 'w.buyers' });
                foldBids(S, id, r.traders, env.now());
                touch('bids');
            }, null);
        }

        /**
         * The list against the newest listings and your stock: what is gone, no longer worth it or already bought
         * comes off; nothing is ever added. While a run is on, a line keeps what you took on it until Next.
         */
        function tidyList() {
            tidyDue = false;
            tidyAt = env.now();
            if (!S.cart.length) return;
            cache = null;
            const v = view();
            const took = S.run.on ? (key) => (S.run.took || {})[key] : null;
            // A line stays while its listing is under the Stretch line of its piece (view.js keepPieces). The whole
            // pile is asked, as the layer keeps it: a line's bazaar may be off the shortlist.
            const res = refreshList(S.cart, keepPieces(v.pieces), (id) => pileOf(S, id, env.now()), took);
            if (res.dropped.length || JSON.stringify(res.cart) !== JSON.stringify(S.cart)) { S.cart = res.cart; touch('cart'); }
            // Every line gone under a run (sold to someone else, or dear now): there is nowhere left to go.
            if (!S.cart.length && S.run.on) { S.run = { ...RUN_IDLE }; touch('run'); }
        }

        /**
         * The list checked after a read. `concerns`: the read was of something the list rests on (a bazaar on it,
         * your stock, your log, what a page showed) - checked at once. Else at the next calm pass (step): the list
         * shows nothing wrong meanwhile, only something a few seconds old.
         */
        function tidySoon(concerns) {
            if (!S.cart.length) return;
            if (concerns) tidyList(); else tidyDue = true;
        }

        /**
         * "Sets to build from my cash" is worked out from your money, and your money moves with every buy and sale. So
         * the number is kept as it was when the list was made, for as long as there is a list - and worked out afresh
         * when the list is made again, is empty, or a setting it rests on changes.
         */
        function planKeep() {
            const s = settings();
            const key = JSON.stringify([s.targetMode, s.which, s.pct, s.shareMax]);
            const none = () => { if (S.plan.targets) { S.plan = { targets: null, at: 0, key: '' }; touch('plan'); } };
            if (!S.cart.length || s.targetMode === 'number') { none(); return; }
            if (S.plan.targets && S.plan.key === key) return;
            none();
            const v = view();
            if (!v.ready) return;
            const targets = {};
            for (const p of v.pieces) targets[p.set] = p.target;
            S.plan = { targets, at: env.now(), key };
            touch('plan');
        }

        /** Your log is read (a Full key Torn takes): a buy seen on a page waits for its log row. Else the page is all there is. */
        const logRead = () => keyOk('full') && keyState.full.ok === true;

        /** What you bought since the run began, counted on its lines: from the pages you bought on and from Torn's log. */
        function countRun() {
            if (!S.run.on) return;
            const began = S.run.began || 0;
            const got = new Map();
            const add = (key, qty) => got.set(key, (got.get(key) || 0) + qty);
            for (const r of S.ledger.rows) {
                if (r.side !== 'buy' || !(r.t >= began)) continue;
                if (r.venue === 'bazaar' && r.who) add(lineKey(r.itemId, 'b:' + r.who), r.qty);
                else if (r.venue === 'market') add(lineKey(r.itemId, IM_PLACE), r.qty);
            }
            const seen = new Map();
            for (const b of S.seen) {
                // A buy the log does not have was not one (state.js judgeSeen): it is on no line.
                if (b.no) continue;
                // A buy seen on the Item Market's page is on its one line; a bazaar's on that bazaar's.
                const key = b.t >= began ? (b.im ? lineKey(b.id, IM_PLACE) : b.whoId ? lineKey(b.id, 'b:' + b.whoId) : null) : null;
                if (key) seen.set(key, (seen.get(key) || 0) + b.qty);
            }
            // Counted afresh each time from what is on record since the run began: a buy taken back comes off its line
            // again. (Until 1.3.0 the larger count ever seen stood - and a false "bought" with it.)
            const took = {};
            for (const l of S.cart) { const n = Math.max(got.get(l.key) || 0, seen.get(l.key) || 0); if (n > 0) took[l.key] = n; }
            if (JSON.stringify(took) !== JSON.stringify(S.run.took || {})) { S.run = { ...S.run, took }; touch('run'); }
        }

        // ---- your thread, your TornW3B list ----------------------------------------------------------------------------------

        async function readThread() {
            const json = await env.torn.get('v2/user/forumthreads', { limit: 50 }, { tag: 't.sets', priority: 'low' });
            foldThreads(S, json, env.now());
            touch('thread');
        }

        async function readOwnList() {
            try {
                foldOwnList(S, await env.own.readList(), env.now());
            } catch (error) {
                if (!egLocal(error)) S.w3b = { ...S.w3b, error: egMsg(error) };
                touch('w3b');
                throw error;
            }
            touch('w3b');
        }

        async function readReceipts() {
            const rows = await env.own.receipts();
            if (keyState.w3b.ok !== true || keyState.w3b.error) setKeyState('w3b', { ok: true, error: '' });
            if (S.w3b.receiptsError) S.w3b = { ...S.w3b, receiptsError: '' };
            const known = new Set(S.w3b.receipts.map(([, r]) => String(r.id)));
            let read = 0;
            for (const r of rows) {
                if (!r || r.id == null || known.has(String(r.id)) || read >= 5) continue;
                read += 1;
                const one = await env.own.receipt(r.id);
                for (const [tid, rec] of receiptsByTrade([one])) {
                    const at = Date.parse(rec.at) || Number(rec.at) * 1000 || env.now();
                    S.w3b = { ...S.w3b, receipts: [...S.w3b.receipts.filter(([id]) => id !== tid), [tid, { id: rec.id, total: rec.total, url: '', at }]].slice(-300), lastReceiptAt: Math.max(S.w3b.lastReceiptAt, at) };
                }
            }
            S.w3b = { ...S.w3b, receiptsAt: env.now() };
            touch('w3b');
        }

        // ---- what you pay your sellers, fixed for the hour --------------------------------------------------------------------

        const egMoney = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('en-US');
        /** Torn's clock, as the pages say it. */
        const egClock = (t) => new Date(t).toISOString().slice(11, 16) + ' TCT';
        /** A trade with a piece of your sets in it is open (and read in full): its total is at the prices of this hour. */
        const tradeOpen = () => S.trades.open.some((t) => (S.trades.full || {})[t.id] != null && tradeHasPieces(t));

        /**
         * What you pay your sellers (core/sellrate.js), kept for an hour while the shop is open - the owner, 2026-10-12:
         * "maybe it checks the points every hour, so we can update every hour if i decide to trade?". Fixed from what
         * the view says a fix would take now (`prices.live`: each set at the lower of your rate and its ceiling, at
         * the cautious points price) - no read of its own. Until the hour ends nothing of it is worked out again;
         * the one thing that moves it is the safety: a points price fallen under your least profit brings it down at
         * once. A trade with set pieces open holds it past the hour (its receipt on TornW3B is made from your list
         * when it ends); the safety still applies. Your own change of rate, least profit or sets fixes at once.
         * Closed: nothing is fixed - the view says what you would pay now.
         */
        function rateKeep(now, v) {
            // The view the calm pace holds was worked out on the table as it stood: after a change the list is compared
            // (stepOwn) on a view worked out anew, or a list matching the old prices would count as written.
            const put = (next) => { S.rate = next; touch('rate'); last = null; };
            const s = settings();
            // A stored table that is not one (no sets, no hour) counts as none: it is fixed anew.
            const t = S.rate.table && S.rate.table.sets && S.rate.table.until > 0 ? S.rate.table : null;
            if (!s.open) {
                if (t || S.rate.sent) put({ table: null, sent: 0 });
                return;
            }
            const live = v.prices && v.prices.live;
            // No ceiling can be said yet (no points price, a market value missing), or the view is from before your
            // press: the next pass decides.
            if (!v.ready || !live || !live.ok || live.pct !== s.pct || live.least !== s.least) return;
            const key = rateKey(s);
            const own = !t || t.key !== key;
            const held = !own && now >= t.until && tradeOpen();
            if (own || (now >= t.until && !held)) {
                const next = fixTable(live, key, now);
                put({ ...S.rate, table: next });
                const sets = Object.entries(next.sets).map(([k, r]) => k + ' ' + r.pct + '% (' + (r.pct < next.pct ? 'its ceiling, under your ' + next.pct + '%' : 'the most that keeps your ' + next.least + '%: ' + r.cap + '%') + ')');
                env.say('note', 'Your prices fixed for an hour', sets.join(' · ') + ' · points ' + egMoney(next.price) + (next.from === 'usual' ? ' (what you usually sell for; ' + egMoney(next.today) + ' today)' : " (today's)") + ' · until ' + egClock(next.until) + (own && t ? ' · your settings changed' : ''));
                return;
            }
            let cur = t;
            if (held && !t.held) {
                cur = { ...t, held: true };
                env.say('note', 'Your prices stand still while a trade is open', 'their hour ended at ' + egClock(t.until) + ': they are fixed anew when no trade with set pieces is open');
            }
            const safe = safeTable(cur, setsTraded(s), live.price, now);
            if (safe !== cur) {
                const sets = Object.entries(safe.sets).filter(([k, r]) => r.down && (!cur.sets[k] || cur.sets[k].pct !== r.pct)).map(([k, r]) => k + ' ' + cur.sets[k].pct + '% to ' + r.pct + '%');
                env.say('note', 'Your prices came down inside the hour', sets.join(' · ') + ' · points fell to ' + egMoney(live.price) + ': over that your least ' + safe.least + '% would be gone' + (safe.held ? '' : ' · fixed anew at ' + egClock(safe.until)));
            }
            if (safe !== t) put({ ...S.rate, table: safe });
        }

        /** The request a write of your list would send now, or why there is none. */
        function listWrite() {
            const v = view();
            if (!v.ready || !S.w3b.list) return { why: 'your list on TornW3B has not been read yet', unread: true };
            const diff = listDiff(new Map(S.w3b.list), desiredList(v.pieces, v.settings.open), ALL_PIECE_IDS);
            if (listMatches(diff)) return { why: v.settings.open ? 'it already matches your rate' : 'your shop is closed: no set piece of yours is on your TornW3B list' };
            return { diff, body: putBody(diff), closed: !v.settings.open };
        }

        /**
         * Your list on TornW3B brought to your rate: only the set pieces are set or taken off, nothing else is touched.
         * Every write is in the problem log (the owner, 2026-10-12: if TornW3B refuses it, the zip alone must say why):
         * what was sent and what TornW3B answered; on a refusal its words, the request's shape and the whole of what
         * was sent - item ids and prices, which are your public list. Never the key (it rides in a header).
         * @param by 'your press' | 'by itself'
         */
        async function sendList(by = 'your press') {
            const w = listWrite();
            if (w.why) {
                env.say('note', 'Your list was not written to TornW3B', by + ' · ' + w.why);
                if (w.unread) throw new Error('Your list on TornW3B has not been read yet.');
                return;
            }
            syncAt = env.now();
            const sent = w.diff.set.length + ' set, ' + w.diff.remove.length + ' taken off' + (w.closed ? ' · your shop is closed: the set pieces come off your list' : '');
            // The prices this write carries: the hour's table as it stands now (rateKeep).
            const rev = S.rate.table ? S.rate.table.rev : 0;
            let answer;
            try {
                answer = await env.own.putList(w.body);
            } catch (error) {
                if (egLocal(error)) env.say('note', 'Your list was not written to TornW3B', by + ' · ' + egMsg(error));
                else {
                    // A request TornW3B calls wrong (400) is the same request the next time: by itself it is not sent
                    // again until what would be sent changes. Your own press always sends.
                    if (error && error.http === 400) listRefused = JSON.stringify(w.body);
                    env.say('note', 'TornW3B refused the write of your list', by + ' · ' + egMsg(error) + (error && error.said ? ' · it said: ' + error.said : '') + ' · sent: ' + sent);
                    env.say('note', 'TornW3B refused the write of your list: its shape', egShape(w.body) + (w.diff.remove.length ? ' · the last ' + w.diff.remove.length + ' with itemID only' : ''));
                    const parts = [...egLines(w.diff.set.map((s) => s.itemID + ' $' + s.price + (s.was == null ? ' (new)' : ' (was $' + s.was + ')'))).map((l) => 'set: ' + l), ...egLines(w.diff.remove.map((r) => String(r.itemID))).map((l) => 'taken off: ' + l)];
                    parts.forEach((l, k) => env.say('note', 'TornW3B refused the write of your list: what was sent, ' + (k + 1) + ' of ' + parts.length, l));
                }
                throw error;
            }
            listRefused = '';
            syncWhy = '';
            if (rev && S.rate.table && S.rate.table.rev === rev && S.rate.sent !== rev) { S.rate = { ...S.rate, sent: rev }; touch('rate'); }
            env.say('note', 'Your list written to TornW3B', by + ' · ' + sent + ' · it answered: ' + (answer == null ? 'nothing that could be read' : JSON.stringify(answer).slice(0, 180)));
            setKeyState('w3b', { ok: true, error: '' });
            foldOwnList(S, await env.own.readList(), env.now());
            touch('w3b');
        }

        /** "Keep it at my rate by itself" is on and nothing is sent: the reason, said once each time it changes. */
        function syncQuiet(why) {
            if (why === syncWhy) return;
            syncWhy = why;
            env.say('note', 'Keeping your TornW3B list at your rate: nothing sent', why);
        }

        /**
         * @param what 'list' (your price list: shown on its panel) or 'receipts' (shown with the receipts)
         * TornW3B refusing the key (401, or 403 "The API key must match the API key linked to this user ID in our
         * database") is said on the key's own box, and nothing of yours is asked of TornW3B again until the key is
         * changed: on 2026-10-11 the badge said "working" all evening while every read of your trades was refused.
         */
        function w3bFailed(error, what = 'list') {
            if (egLocal(error)) return;
            // A 403 that does not name the key (a block, a page that moved) is no verdict on it: asked again later.
            const key403 = !!error && error.http === 403 && /api key|invalid key/i.test(String(error.said || ''));
            if (error && (error.http === 401 || key403)) setKeyState('w3b', { ok: false, error: key403 ? 'TornW3B refuses this key for your Torn id: it is not the one registered there' : 'TornW3B does not know this key' });
            S.w3b = { ...S.w3b, [what === 'receipts' ? 'receiptsError' : 'error']: egMsg(error) };
            touch('w3b');
            // Once for each thing it said: the request itself is in the log every time it fails.
            sayOnce('w3b-' + what + '-' + egMsg(error), what === 'receipts' ? 'TornW3B: your receipts' : 'TornW3B: your own list', egMsg(error) + (error && error.said ? ' · it said: ' + error.said : ''));
        }

        /** A receipt for one finished trade, made on TornW3B from your list there. */
        function makeReceipt(id) {
            const f = S.trades.finished.find((x) => x.id === id);
            if (!f || flags.receipt) return;
            flags.receipt = id;
            const body = receiptBody(id, f.rows || [], f.whoId);
            env.own.makeReceipt(body)
                .then((json) => {
                    const r = readReceipt(json, f.paid);
                    foldReceipt(S, id, r, env.now());
                    touch('w3b');
                    if (!r.ok) env.say('note', "TornW3B's receipt differs from what you paid", 'trade ' + id + ': theirs ' + r.total + ', yours ' + f.paid + (r.missing.length ? ', not on your list: ' + r.missing.join(', ') : ''));
                })
                .catch((e) => {
                    w3bFailed(e, 'receipts');
                    // A request TornW3B calls wrong (400) is the same request the next time: not sent for this trade
                    // again, and its shape - names and kinds, no value - goes into the log so the cause can be found.
                    if (e && e.http === 400) {
                        S.w3b = { ...S.w3b, tried: { ...(S.w3b.tried || {}), [id]: { n: EG_RECEIPT_TRIES, at: env.now() } } };
                        touch('w3b');
                        env.say('note', 'TornW3B called a receipt request wrong', 'trade ' + id + ' · sent: ' + egShape(body) + ' · it is not sent for this trade again');
                    }
                })
                .finally(() => { flags.receipt = null; flush(); env.changed(); });
        }

        /**
         * A trade that just finished gets its receipt by itself - once your list on TornW3B holds a price for each of
         * its pieces, since TornW3B makes the receipt from that list. Older trades keep their button.
         */
        function autoReceipt(now) {
            if (flags.receipt || !S.w3b.list) return;
            const have = new Set(S.w3b.receipts.map(([id]) => id));
            const listed = new Map(S.w3b.list);
            const tried = S.w3b.tried || {};
            for (const f of S.trades.finished) {
                if (have.has(f.id) || !(now - f.t < EG_RECEIPT_WITHIN_MS)) continue;
                const t = tried[f.id] || { n: 0, at: 0 };
                if (t.n >= EG_RECEIPT_TRIES || now - t.at < EG_RECEIPT_GAP_MS) continue;
                if (!(f.rows || []).length || !(f.rows || []).every((r) => listed.has(String(r.id)))) continue;
                const kept = Object.fromEntries(Object.entries(tried).filter(([, x]) => now - x.at < 2 * EG_RECEIPT_WITHIN_MS));
                S.w3b = { ...S.w3b, tried: { ...kept, [f.id]: { n: t.n + 1, at: now } } };
                touch('w3b');
                makeReceipt(f.id);
                return;
            }
        }

        // ---- the loop ---------------------------------------------------------------------------------------------------------

        /** Every few seconds, and when a read comes back: whatever is due is asked for. Nothing without a key. */
        function step() {
            if (env.paused()) return;
            const now = env.now();
            if (!env.hasKey('limited') || keyState.limited.error) { stepOwn(now); return; }
            run('self', READ_EVERY.self, readSelf);
            if (!S.self.id) return;
            run('items', READ_EVERY.items, readItems);
            if (!S.items.at) return;
            const s = settings();
            planKeep();
            const full = keyOk('full');
            // Your inventory first: once the count has begun nothing is asked ahead of it.
            // (It begins after the history is in: your newest buys say what the pieces cost.)
            const fullPending = full && keyState.full.ok == null;
            const history = S.ledger.tradesBackfilled && !fullPending && (!(full && keyState.full.ok) || S.log.backfilled);
            if (history || S.stock.invAt || now - started > EG_HISTORY_WAIT_MS) run('inventory', READ_EVERY.inventory, readInventory);
            if (full && keyState.full.ok == null) run('fullKey', READ_EVERY.self, readFullKey, { key: 'full' });
            if (full && keyState.full.ok) {
                if (now - S.types.at > READ_EVERY.types) run('types', RETRY_MS, readTypes);
                // After a buy seen on a page the log is asked a few seconds, twenty seconds and a minute on.
                if (logSoon.length && now >= logSoon[0] && !busy.log) { logSoon = logSoon.filter((t) => t > now); due.log = 0; }
                if (S.types.at) run('log', READ_EVERY.log, readLog, { key: 'full' });
            }
            run('finished', READ_EVERY.finished, readFinished);
            run('money', READ_EVERY.money, readMoney);
            run('points', READ_EVERY.points, readPoints);
            run('trades', READ_EVERY.trades, readTrades);
            run('summary', s.readMin * EG_MIN, readSummary, { key: null });
            run('thread', READ_EVERY.thread, readThread);
            // The list against what was read since the last pass - not after every answer, but never later than this.
            if (tidyDue && now - tidyAt >= EG_CALM_MS) tidyList();
            const v = calm();
            readMarkets(v);
            if (S.summary.at) readListings(v);
            readShops(v);
            readBids();
            rateKeep(now, v);
            stepOwn(now);
            if (v.ready && now - (due.day || 0) > 0) { due.day = now + EG_MIN; recordDay(S, v, now); touch('hist'); }
            flush();
        }

        function stepOwn(now) {
            const keep = !!settings().w3bSync;
            if (!keep) syncWhy = '';
            if (!keyOk('w3b') || !S.self.id) {
                if (keep) syncQuiet(!S.self.id ? 'your Torn id is not known yet' : 'the key you registered on TornW3B is not set, or TornW3B refuses it (its box in Settings says which)');
                return;
            }
            run('ownList', READ_EVERY.ownList, () => readOwnList().catch((e) => { w3bFailed(e); throw e; }), { key: null });
            run('receipts', READ_EVERY.receipts, () => readReceipts().catch((e) => { w3bFailed(e, 'receipts'); throw e; }), { key: null });
            autoReceipt(now);
            if (!keep) return;
            if (!S.w3b.list) { syncQuiet('your list on TornW3B has not been read yet'); return; }
            if (flags.w3b || now - syncAt < EG_SYNC_GAP_MS) return;
            const v = calm();
            if (!v.ready) { syncQuiet('not everything is read yet'); return; }
            const matches = !v.prices.w3b.diff || v.prices.w3b.matches;
            if (!v.settings.open) {
                // Closed: the set pieces come off your list, once. Nothing else is written while you are closed.
                if (matches) { syncQuiet('your shop is closed: no set piece of yours is on your TornW3B list'); return; }
            } else {
                // Open: written once for each fixing of your prices (rateKeep) - at most once an hour, and at once
                // when the safety brought them down. Your own press sends at any time.
                const t = S.rate.table;
                if (!t) { syncQuiet('your prices are not fixed yet: the points price or a market value is not read'); return; }
                if (S.rate.sent === t.rev) { syncQuiet(matches ? 'it already matches your rate' : 'it differs from your prices of this hour: written when they are next fixed, at ' + egClock(t.until) + (t.held ? ' or when the open trade has ended' : '') + ' - your own press sends it now'); return; }
                if (matches) { S.rate = { ...S.rate, sent: t.rev }; touch('rate'); syncQuiet('it already matches your rate'); return; }
            }
            if (listRefused) {
                const w = listWrite();
                if (w.body && JSON.stringify(w.body) === listRefused) { syncQuiet('TornW3B called this same request wrong: it is not sent again by itself until your prices change - your own press still sends it'); return; }
            }
            flags.w3b = true;
            sendList('by itself').catch(w3bFailed).finally(() => { flags.w3b = false; flush(); env.changed(); });
        }

        // ---- the shared server ------------------------------------------------------------------------------------------------

        /**
         * What Torn Archive tells the shared server (core/server.js serverBody takes it): the bazaars it knows sell a
         * piece, the ones on your list and under your rate, what each piece is worth to you, what you just bought at a
         * bazaar, and which of TornW3B's lists it read.
         */
        function serverWant() {
            const now = env.now();
            const v = calm();
            const me = String(S.self.id);
            const sellers = new Set();
            const dir = [];
            for (const id of ENGINE_PIECES) {
                const o = S.offers[id];
                if (!o) continue;
                if (o.bazAt) dir.push([Number(id), o.bazAt]);
                for (const r of o.baz || []) if (String(r.whoId) !== me) sellers.add(Number(r.whoId));
            }
            const mv = mvOf(S);
            const worth = {};
            for (const id of ENGINE_PIECES) {
                const p = viewPiece(v, id);
                // A piece of a set you do not trade is still watched, at its market value: the server sends only what is named.
                const w = (p && p.worth) || mv(id);
                if (w > 0) worth[id] = w;
            }
            const bought = [];
            for (const r of S.ledger.rows) if (r.side === 'buy' && r.venue === 'bazaar' && r.who && now - r.t < SERVER_BOUGHT_MS) bought.push({ whoId: r.who, id: r.itemId, qty: r.qty, price: r.each, t: r.t });
            // Seen on the page and not in the log yet.
            for (const b of S.seen) if (b.whoId && !b.no && b.t > S.log.until && now - b.t < SERVER_BOUGHT_MS) bought.push({ whoId: b.whoId, id: b.id, qty: b.qty, price: b.price, t: b.t });
            return { sellers: [...sellers], looking: shopsWanted(v).map(Number), worth, bought, dir, need: v.pieces.filter((p) => p.need > 0).map((p) => Number(p.id)) };
        }

        /** One answer of the shared server. */
        function serverTook(answer, got) {
            foldServer(S, answer, got);
            touch('server');
            // The two markets as the server read them: taken when newer than what is held, and then not asked of Torn
            // here until the server's read has had its time (one more exchange is allowed for it to come).
            const theirs = serverMarketIn(answer, ENGINE_PIECES, got);
            const slack = SERVER_SYNC_MS + 5000;
            if (theirs.points && theirs.points.at > (S.points.at || 0) && foldPoints(S, theirs.points.json, theirs.points.at)) {
                touch('points');
                due.points = Math.max(due.points || 0, theirs.points.at + READ_EVERY.points + slack);
            }
            if (theirs.market.length) {
                const v = calm();
                const every = settings().readMin * EG_MIN;
                for (const m of theirs.market) {
                    const o = S.offers[m.id];
                    if (o && o.imAt >= m.at) continue;
                    foldMarket(S, m.id, m.listings, m.at);
                    touch('offers');
                    const p = viewPiece(v, m.id);
                    const next = m.at + (p && p.need > 0 ? Math.max(every, 60000) : every * IDLE_TIMES) + slack;
                    const had = per.market[m.id];
                    if (!(had && had.busy)) per.market[m.id] = { busy: false, due: Math.max((had && had.due) || 0, next) };
                }
            }
            // A bazaar of your list among what it read: the list follows at once. Else at the next calm pass.
            const mine = new Set(S.cart.map((l) => String(l.whoId)));
            const named = [...((answer && Array.isArray(answer.reads) ? answer.reads : []).map((r) => r && r.id)), ...((answer && Array.isArray(answer.seen) ? answer.seen : []).map((p) => (Array.isArray(p) ? p[0] : null)))];
            tidySoon(named.some((id) => id != null && mine.has(String(id))));
            flush();
            env.changed();
            again();
        }

        /** The server is off, or another one: what it said goes. */
        function serverForget() {
            S.server = serverEmpty();
            touch('server');
            flush();
            env.changed();
        }

        /** Your items can be asked for: there is a key that works, and Torn has said who you are and what its items are. */
        const canCount = () => !env.paused() && env.hasKey('limited') && !keyState.limited.error && !!S.self.id && !!S.items.at && !!S.stock.invAt;
        let stockAsked = 0;

        /**
         * "Read" on your stock, pressed on a Torn page: your items, and your log where a Full key reads it, ahead of
         * anything else. The prices are left as they are. Not more often than every ten seconds, however it is pressed.
         */
        function readStock() {
            const now = env.now();
            if (now - stockAsked < EG_STOCK_PRESS_MS) return;
            stockAsked = now;
            due.inventory = 0;
            if (logRead()) due.log = 0;
            if (canCount()) run('inventory', READ_EVERY.inventory, readInventory);
            step();
        }

        /** "Read now": everything is due. */
        function readNow() {
            // Nothing looked at before this press counts until it is looked at again (a read of the last moments is
            // the newest Torn has: it stands). The bazaars of your list and the ones a list would use are asked first.
            S.fresh = { since: env.now() - EG_JUST_READ_MS };
            enBump(S, null);
            cache = null;
            last = null;
            for (const k of Object.keys(due)) due[k] = 0;
            for (const kind of Object.keys(per)) if (kind !== 'listings' && kind !== 'bids') for (const id of Object.keys(per[kind])) per[kind][id].due = 0;
            if (looked.id) looked = { ...looked, at: env.now() };
            said.clear();
            off.clear();
            // Your items first: asked ahead of every other read of this press (the owner, 2026-10-11: "if i also press
            // read now, can it prioritize reading my inventory?").
            if (canCount()) run('inventory', READ_EVERY.inventory, readInventory);
            step();
        }

        /** A key was pasted, changed or forgotten. */
        function keyChanged(kind) {
            setKeyState(kind, { ok: null, error: '' });
            said.clear();
            off.clear();
            if (kind === 'limited') { due.self = 0; due.items = 0; }
            if (kind === 'full') { due.fullKey = 0; due.types = 0; due.log = 0; }
            if (kind === 'w3b') { due.ownList = 0; due.receipts = 0; }
            step();
        }

        // ---- the hub's buttons ------------------------------------------------------------------------------------------------

        const stops = () => { const v = view(); return runOrder(stopsOf(S.cart, (id) => (viewPiece(v, id) || {}).worth || 0), S.run); };
        const idle = () => { S.run = { ...RUN_IDLE }; };
        /** A piece as a list takes it: `take` units, each under `takeLine` (view.js listPieces), and its rows that count. */
        const asListed = (p) => listPieces([p])[0];
        const counting = (p, line) => p.offers.filter((o) => o.ok !== false && !o.out && o.price < line);

        const actions = {
            cart(itemId, place) {
                const p = viewPiece(view(), itemId);
                const offer = p && p.offers.find((o) => placeOf(o) === place);
                if (!offer) return;
                // Your own press: any listing may go on. The Item Market's line is its rows under the Stretch line.
                S.cart = toggleLine(S.cart, { ...p, worth: p.lineS }, offer);
                idle();
                touch('cart', 'run');
            },
            drop(key) { S.cart = dropLine(S.cart, key); idle(); touch('cart', 'run'); },
            // One piece, every listing of it that counts (checked, where you buy, a Buy on its set), in one press. With
            // nothing more to add, the press takes the piece off the list.
            cartAll(itemId) {
                const p = viewPiece(view(), itemId);
                if (!p) return;
                const next = addAll(S.cart, asListed(p), counting(p, p.takeLine));
                S.cart = next.length > S.cart.length ? next : dropPiece(S.cart, itemId);
                idle();
                touch('cart', 'run');
            },
            // A list of one piece alone, in place of the list on hand: every listing of it that counts, cheapest first.
            listOnly(itemId) {
                const p = viewPiece(view(), itemId);
                if (!p) return;
                S.cart = addAll([], asListed(p), counting(p, p.takeLine));
                idle();
                touch('cart', 'run');
                due.inventory = 0;
                if (logRead()) due.log = 0;
            },
            // A list is made from the count as it stands, and Torn is asked for its own at once: the list follows it.
            // `kind` 'hot': only what "Do now" counted - under what you pay your sellers. Else every Buy, and the
            // Stretch that finishes a set. Made from the shortlists the view keeps (core/shortlist.js): the same list
            // the whole pile makes, without sorting it.
            makeList(kind) {
                S.plan = { targets: null, at: 0, key: '' };
                touch('plan');
                const v = view();
                const pieces = listPieces(v.pieces);
                S.cart = fillList(kind === 'hot' ? cheapPieces(pieces) : pieces, (id) => { const p = viewPiece(v, id); return p ? p.offers.filter((o) => o.ok !== false && !o.out) : []; });
                idle();
                touch('cart', 'run');
                due.inventory = 0;
                if (logRead()) due.log = 0;
            },
            clearList() { S.cart = []; idle(); touch('cart', 'run'); },
            // `place` (Next pressed on a Torn page): where you stand. A bazaar of the list that is not the stop the run
            // is on becomes that stop first - you did not follow the order - and Next goes on from there; the stops
            // passed over stay on the list. (Until 1.3.0 Next was only offered on the current stop.)
            run(op, place = null) {
                const list = stops();
                if (op === 'start') { S.run = { ...runStart(list), began: env.now() }; due.inventory = 0; if (logRead()) due.log = 0; }
                else if (op === 'stop') idle();
                else {
                    countRun();
                    if (S.run.on && place && place !== S.run.place && list.some((s) => s.place === place)) S.run = { ...S.run, place, at: list.findIndex((s) => s.place === place) };
                    S.run = runNext(S.run, list);
                    // Over: what you took leaves the list, what you skipped stays on it. The run is summed here, once:
                    // its counts are of the lines as they were, and those lines are shorter from now on.
                    if (S.run.done) {
                        const end = runView(S.run, list);
                        S.cart = listAfterRun(S.cart, S.run);
                        S.run = { ...S.run, took: {}, sum: { got: end.got, units: end.units, skipped: end.skipped } };
                    }
                }
                touch('cart', 'run');
                // The stop you are sent to is confirmed with Torn at once.
                const at = runAt(S.run, stops());
                const cur = at >= 0 ? stops()[at] : null;
                if (cur && !cur.im && per.shops[String(cur.whoId)]) per.shops[String(cur.whoId)].due = 0;
            },
            read: readNow,
            readStock,
            // `false`: nothing the screen shows changed - the hub is not drawn again for it (a draw that asked for a
            // look that asked for a draw went round every 60 ms on the Buy page until 1.3.0).
            look(itemId) { const id = String(itemId || ''); if (id === looked.id && env.now() - looked.at < EG_MIN) return false; looked = { id, at: env.now() }; step(); return false; },
            w3b(op) {
                if (flags.w3b) return;
                flags.w3b = true;
                (op === 'send' ? sendList() : readOwnList()).catch(w3bFailed).finally(() => { flags.w3b = false; flush(); env.changed(); });
            },
            receipt(tradeId) { makeReceipt(String(tradeId)); },
        };

        function act(name, ...args) {
            if (!actions[name]) return false;
            // Every press is in the problem log, with when: a press that seemed to do nothing can be found in the zip.
            if (name !== 'look') env.say('note', 'Pressed: ' + name, args.filter((a) => a != null).map(String).join(' ') || null);
            if (actions[name](...args) === false) return true;
            // Your own press is never calm: the next pass decides from a view worked out after it.
            last = null;
            planKeep();
            flush();
            env.changed();
            return true;
        }

        /** What a Torn page saw: a buy on a bazaar, a press of EXCHANGE, your thread's title. */
        /** Your log, asked a few seconds, twenty seconds and a minute from now (only read with a Full key). */
        function askLogSoon(now) {
            if (logRead()) logSoon = [...logSoon.filter((t) => t > now), ...EG_LOG_AFTER_BUY_MS.map((d) => now + d)].sort((a, b) => a - b).slice(-6);
        }

        function note(kind, what) {
            const now = env.now();
            if (kind === 'buy') {
                // What you took is in your stock at once, and off the list (or ticked on it, while a run is on).
                if (noteSeenBuy(S, what, now, { noLog: !logRead() })) {
                    touch('seen', 'stock');
                    countRun();
                    tidyList();
                    // Torn's log is the judge of the buy: asked a few seconds, twenty seconds and a minute after it.
                    askLogSoon(now);
                    due.inventory = Math.min(due.inventory || 0, now + EG_INV_AFTER_BUY_MS);
                }
            // Torn's own Buy pressed on a listing in a Torn tab. Nothing is counted for it - Torn may still ask "are
            // you sure", or refuse - but its log is asked soon after: what was bought is in it. Nothing on the screen
            // changes by the press itself.
            } else if (kind === 'press') { askLogSoon(now); return; }
            else if (kind === 'swap') { noteSwap(S, what, now, { noLog: !logRead() }); touch('swaps', 'book', 'stock'); }
            else if (kind === 'thread') { noteThread(S, what, now); touch('thread'); }
            // A Torn tab sees a trade that is not as it was read: read again now, not at the minute.
            else if (kind === 'trade') { due.trades = 0; again(); }
            // A bazaar's own page, in front of you: the newest look at it there is.
            // (Also a listing the page proved gone, a bazaar with nothing in it, and "Gone" pressed on a line.)
            else if (kind === 'shop') { if (notePage(S, what, now)) { cache = null; tidyList(); } }
            // What a Torn tab saw is never calm either.
            last = null;
            flush();
            env.changed();
        }

        return {
            state: S, step, view, calm, act, note, readNow, keyChanged, flush, serverWant, serverTook, serverForget,
            serverMark: () => ({ seq: S.server.seq, seenAt: S.server.seenAt }),
            keys: () => keyState,
            busy: () => ({ ...flags }),
            mv: mvOf(S),
            /** Whether the settings changed something the reads depend on. */
            settingsChanged() {
                cache = null;
                // Your own press is never calm: what you pay is fixed from a view worked out after it (rateKeep).
                last = null;
                syncAt = 0;
                // A place switched off ("Buy from") leaves the list at once - but never a line you already took from.
                const left = dropPlaces(S.cart, buysFrom(settings()), (l) => S.run.on && S.run.took && S.run.took[l.key] > 0);
                if (left.length !== S.cart.length) { S.cart = left; idle(); touch('cart', 'run'); }
            },
        };
    }

    /** Every piece id, for callers that only have the engine. */
    const ENGINE_ALL_PIECES = ENGINE_PIECES;

    /* ===== src/core/leader.js ===== */
    /*
     * Which Torn tab runs the live feed. Pure: the caller reads and writes the
     * shared record.
     *
     * Every Torn tab boots this script. Without one leader, five tabs make five
     * times the requests - Torn's 100/min is per USER across every key and tool,
     * and TornW3B's 100/min is per IP. So exactly one tab polls and the others
     * render what it stores.
     *
     * Only a VISIBLE tab may lead. Torn's rules forbid software that works from
     * unfocused pages to "generate alerts, or draw attention to itself"; a hidden
     * tab polling in the background is the shape of that, so a tab that is
     * hidden gives up the role instead of keeping it.
     */

    /** A leader that has not renewed in this long is presumed gone. */
    const LEADER_STALE_MS = 10000;

    /** How often the leader renews its claim. */
    const LEADER_HEARTBEAT_MS = 3000;

    /**
     * @param {object|null} record - { id, ts } as last stored
     * @param {string} me - this tab's id
     * @param {object} opts
     * @param {number} opts.now
     * @param {boolean} opts.visible
     * @returns {{lead: boolean, confirmed: boolean, write: object|null}}
     *   `write` is the record to store (null = leave it alone). `confirmed` is
     *   true only when the stored record ALREADY named this tab: two tabs can
     *   both claim a stale record in the same instant, and only the one whose
     *   write survived sees itself there on the next tick. Poll only when
     *   confirmed, and the race costs one heartbeat instead of double requests.
     */
    function decideLeader(record, me, { now, visible, staleMs = LEADER_STALE_MS }) {
        const held = record && record.id && Number.isFinite(record.ts);
        const mine = held && record.id === me;
        const fresh = held && now - record.ts < staleMs;

        if (mine) {
            if (visible) {
                return { lead: true, confirmed: true, write: { id: me, ts: now } };
            }
            // Hidden: step down so a visible tab can take over at once.
            return { lead: false, confirmed: false, write: { id: null, ts: 0 } };
        }

        if (!fresh && visible) {
            return { lead: true, confirmed: false, write: { id: me, ts: now } };
        }

        return { lead: false, confirmed: false, write: null };
    }

    function makeTabId() {
        return (
            Date.now().toString(36) +
            '-' +
            Math.random().toString(36).slice(2, 10)
        );
    }

    /* ===== src/core/hub-leader.js ===== */
    // Which of Torn Archive's own tabs does the reading, when more than one is open. One at a time: the first to
    // open, until it closes (its mark goes stale) or you press "Use this tab" in another. The tab that reads does so
    // in view or not: a new trade has to be noticed while you are on Torn.

    const HUB_LEAD_KEY = 'hubLead';
    /** The reading tab writes its mark this often... */
    const HUB_LEAD_BEAT_MS = 5 * 1000;
    /** ...and a mark this old is a tab that closed. Longer than a hidden tab's slowed timers (once a minute). */
    const HUB_LEAD_STALE_MS = 150 * 1000;

    /**
     * @param record { id, ts } as stored, or null
     * @param me     this tab's id
     * @param o      { now, claim } - claim: you asked for this tab
     * @returns { lead, write } - write: the mark to store, or null to leave it
     */
    function hubLeader(record, me, { now, claim = false, staleMs = HUB_LEAD_STALE_MS } = {}) {
        const ts = record ? Number(record.ts) : NaN;
        // A mark from the future (the clock moved back) is no one's.
        const held = !!(record && record.id && Number.isFinite(ts) && now - ts < staleMs && ts <= now + 1000);
        if (claim || !held || record.id === me) return { lead: true, write: { id: me, ts: now } };
        return { lead: false, write: null };
    }

    /* ===== src/core/turns.js ===== */
    /*
     * Sharing the limits with Torn Bids (the Torn Trading script: its overlay on
     * Torn's pages, and its Torn Bids page). Pure.
     *
     * The owner's rule (2026-10-10, replacing "off while Torn Bids is on"): both
     * run together, and the requests go to the one being looked at. Looking at
     * Torn Archive's page gives Torn Archive the larger share, looking at Torn
     * Bids' page gives it to Torn Bids; on any other page the last one looked at
     * keeps it. Torn counts requests per player and TornW3B per address, so the
     * two shares must fit under one limit.
     *
     * How each learns of the other: two userscripts cannot read each other's
     * stored values, but both pages live on the same site, so both can read that
     * site's own page storage. Two marks are kept there:
     *
     *   tornapps.front    { app: 'archive' | 'trading', at }
     *                     which page was looked at last. Torn Archive writes it
     *                     for both (its script also runs on Torn Bids' page).
     *   tornapps.behind   { app: 'trading', at, torn, w3b }
     *                     written by Torn Bids while it keeps to the smaller
     *                     share because Torn Archive is in front; renewed at
     *                     least once a minute.
     *   tornapps.archive  { app: 'archive', at }
     *                     written by Torn Archive's own page while it is open,
     *                     in view or not, so Torn Bids knows the app it makes
     *                     room for is still there. Left to run out when the
     *                     page is closed: Torn Bids believes it for 150 s.
     *   tornapps.w3b.archive / tornapps.w3b.trading   { at, m, d }
     *                     each app's own requests for an item's full listing on
     *                     TornW3B: `m` the times (ms) of the last minute's, `d`
     *                     a count for each hour (hour = floor(ms / 3,600,000),
     *                     the last 25). TornW3B counts those per address, so
     *                     each app adds the other's to its own before it asks.
     *
     * Going down is done at once; going up waits a minute, so what the other
     * asked in the minute before has left Torn's count. A Torn Bids that does not
     * write `tornapps.behind` (every release before it learns this) keeps its
     * whole limit, so beside it Torn Archive stays on the smaller share even when
     * it is the one in view: 85 + 12 is under Torn's 100.
     *
     * The page side - looking for the host, writing the marks, telling the
     * clients - is not here: this file touches no document and no storage.
     */

    /**
     * Torn Bids' own hosts: the overlay on Torn's pages, Torn Bids on its page.
     * The OTHER app's ids, on purpose - Torn Archive's own begin tarc-.
     */
    const TRADING_HOST_IDS = ['ttv2-host', 'ttv2-sell-host'];

    /** GM key every tab and the page read: when Torn Bids was last seen. */
    const TRADING_SEEN_KEY = 'tradingSeenAt';

    /** GM keys: when Torn Bids' own page, and Torn Archive's own page, were last looked at (in view, with the keyboard). */
    const TRADING_VIEW_KEY = 'tradingViewAt';
    const ARCHIVE_VIEW_KEY = 'archiveViewAt';

    /** A page that is being looked at says so at most this often. */
    const VIEW_MARK_EVERY_MS = 5 * 1000;

    /** The two marks in the site's own page storage (see the top of this file). */
    const FRONT_MARK = 'tornapps.front';
    const BEHIND_MARK = 'tornapps.behind';
    const ALIVE_MARK = 'tornapps.archive';

    /**
     * Torn Archive's page says it is open this often. A tab out of view runs its timers about once a minute, which is
     * still twice inside the 150 s Torn Bids believes the mark.
     */
    const ALIVE_EVERY_MS = 30 * 1000;

    /** Torn Bids' "I keep to the smaller share" is believed this long. Over two of a hidden tab's once-a-minute ticks. */
    const BEHIND_FRESH_MS = 150 * 1000;

    /** The larger share is taken this long after coming to the front. */
    const RAMP_MS = 60 * 1000;

    /**
     * Torn Bids counts as running this long after it was last seen. Two minutes, not one (Pumping Iron, round 7
     * review): Chrome's intensive throttling runs a hidden tab's timers about once a minute, so a tab that still runs
     * Torn Bids can mark it seen only every ~60 s; a 60 s grace let the mark flicker off between two of them.
     */
    const TRADING_GRACE_MS = 120 * 1000;

    /** A tab looks for Torn Bids' host this often (one getElementById), hidden tabs too. */
    const TRADING_LOOK_EVERY_MS = 5 * 1000;

    /** A tab that sees Torn Bids notes it at most this often (one small GM write). */
    const TRADING_MARK_EVERY_MS = 15 * 1000;

    /** Torn Bids' own limits, which Torn Archive may use while it runs alone. */
    const TORN_PER_MINUTE_ALONE = 85;
    const W3B_PER_MINUTE_ALONE = 80;

    /**
     * Requests a minute. `behind` is also what is left beside a Torn Bids that keeps its whole limit: Torn allows
     * 100 and Torn Bids takes up to 85.
     */
    const SHARES = Object.freeze({
        alone: Object.freeze({ torn: TORN_PER_MINUTE_ALONE, w3b: W3B_PER_MINUTE_ALONE }),
        front: Object.freeze({ torn: 70, w3b: 65 }),
        behind: Object.freeze({ torn: 12, w3b: 8 }),
    });

    /**
     * Is Torn Bids on this page right now? Read only: its host is looked for and never touched.
     * @param {{getElementById: function(string): *}|null} doc - the document, or anything that answers getElementById
     */
    function tradingOnPage(doc) {
        if (!doc || typeof doc.getElementById !== 'function') return false;
        return TRADING_HOST_IDS.some((id) => !!doc.getElementById(id));
    }

    /** Is Torn Bids running now (seen within the grace period)? */
    function tradingRunning(seenAt, now) {
        const t = Number(seenAt) || 0;
        return t > 0 && now - t < TRADING_GRACE_MS;
    }

    /** Should this tab write a fresh "seen" mark? */
    function shouldMarkSeen(seenAt, now) {
        const t = Number(seenAt) || 0;
        // A mark from the future (the clock moved back) is replaced, or it would never be renewed.
        return !(t > 0) || now - t >= TRADING_MARK_EVERY_MS || t > now;
    }

    /** Should a page that is being looked at say so again? */
    function shouldMarkView(viewAt, now) {
        const t = Number(viewAt) || 0;
        return !(t > 0) || now - t >= VIEW_MARK_EVERY_MS || t > now;
    }

    /** Is it time for Torn Archive's page to say again that it is open? Also after the clock was set back. */
    function shouldMarkAlive(lastAt, now) {
        const t = Number(lastAt) || 0;
        return !(t > 0) || now - t >= ALIVE_EVERY_MS || t > now;
    }

    const W3B_MARK = 'tornapps.w3b.archive';
    const W3B_OTHER_MARK = 'tornapps.w3b.trading';
    const W3B_MARK_HOURS = 24;
    const W3B_MARK_MOST = 200;

    /** Our own item-listing requests on TornW3B as a mark: the last minute's times, and a count for each hour. */
    function w3bMarkText(times, day, now) {
        const got = readW3bMark(JSON.stringify({ at: now, m: times, d: day }), now);
        return JSON.stringify({ at: now, m: got ? got.m : [], d: got ? got.d : {} });
    }

    /**
     * The other app's item-listing requests, read back from the page storage: only what still counts at `now`.
     * @returns {{m: number[], d: Object<string, number>}|null} null when it is missing or not such a mark
     */
    function readW3bMark(text, now) {
        if (typeof text !== 'string' || !text) return null;
        let mark = null;
        try { mark = JSON.parse(text); } catch { return null; }
        if (!mark || typeof mark !== 'object' || Array.isArray(mark)) return null;
        const m = (Array.isArray(mark.m) ? mark.m : []).filter((x) => typeof x === 'number' && Number.isFinite(x) && x <= now && now - x < 60000).sort((a, b) => a - b).slice(-W3B_MARK_MOST);
        const hour = Math.floor(now / 3600000);
        const d = {};
        for (const [h, n] of Object.entries(mark.d && typeof mark.d === 'object' && !Array.isArray(mark.d) ? mark.d : {})) {
            const at = Number(h);
            const count = Math.floor(Number(n));
            if (Number.isInteger(at) && at <= hour && at >= hour - W3B_MARK_HOURS && count > 0) d[at] = Math.min(count, 100000);
        }
        return { m, d };
    }

    /** One of the marks as text, for the site's page storage. */
    function markText(mark) {
        return JSON.stringify(mark);
    }

    /** A mark read back from the page storage: null when it is missing or not one of ours. */
    function readMark(text) {
        if (typeof text !== 'string' || !text) return null;
        let m = null;
        try { m = JSON.parse(text); } catch { return null; }
        if (!m || typeof m !== 'object' || (m.app !== 'archive' && m.app !== 'trading')) return null;
        const at = Number(m.at);
        if (!(at > 0)) return null;
        const count = (v) => (Number.isFinite(Number(v)) && Number(v) >= 0 && v !== null && v !== '' ? Math.floor(Number(v)) : null);
        return { app: m.app, at, torn: count(m.torn), w3b: count(m.w3b) };
    }

    /** Is Torn Archive the one in front: its page looked at later than Torn Bids' page? Never looked at either: Torn Bids. */
    function archiveInFront(archiveViewAt, tradingViewAt) {
        return (Number(archiveViewAt) || 0) > (Number(tradingViewAt) || 0);
    }

    /**
     * What Torn Archive may ask a minute, now.
     *
     * @param {object} i
     * @param {number} i.now
     * @param {number} i.tradingSeenAt   when Torn Bids was last seen running (0 = never)
     * @param {number} i.tradingViewAt   when Torn Bids' page was last looked at
     * @param {number} i.archiveViewAt   when Torn Archive's page was last looked at
     * @param {object|null} i.behind     readMark() of the page's `tornapps.behind`
     * @param {number} i.frontSince      when Torn Archive came to the front (0 = it is not)
     * @returns {{mode: 'alone'|'front'|'behind', why: ''|'trading-in-view'|'no-answer'|'ramp', torn: number, w3b: number}}
     */
    function shareNow({ now, tradingSeenAt = 0, tradingViewAt = 0, archiveViewAt = 0, behind = null, frontSince = 0 }) {
        if (!tradingRunning(tradingSeenAt, now)) return { mode: 'alone', why: '', ...SHARES.alone };
        const back = (why) => ({ mode: 'behind', why, ...SHARES.behind });
        if (!archiveInFront(archiveViewAt, tradingViewAt)) return back('trading-in-view');
        // Only a Torn Bids that says it keeps to the smaller share has made room.
        const said = behind && behind.app === 'trading' && behind.at <= now + 1000 && now - behind.at < BEHIND_FRESH_MS;
        if (!said) return back('no-answer');
        if (!(frontSince > 0) || now - frontSince < RAMP_MS) return back('ramp');
        // What Torn Bids says it keeps comes off what the two may ask together; never over the front share.
        const room = (kind) => {
            const theirs = behind[kind] == null ? SHARES.alone[kind] - SHARES.front[kind] : behind[kind];
            return Math.max(SHARES.behind[kind], Math.min(SHARES.front[kind], SHARES.alone[kind] - theirs));
        };
        return { mode: 'front', why: '', torn: room('torn'), w3b: room('w3b') };
    }

    /* ===== src/core/errlog.js ===== */
    /*
     * The problem log (3.15, the owner: "an error log he can export in settings,
     * so if he encounters a bug he can write the report there, send the
     * screenshot, and zip that along with the error log - so it helps you
     * instead of grepping the code from scratch").
     *
     * Every tab adds what went wrong (a request that failed and why, a script
     * error) and what you did just before (picked an item, planned, accepted,
     * pressed Next...). Kept 7 days, at most LOG_MAX entries. No key (redacted
     * before it is stored), no player id or name.
     */

    const LOG_MAX = 400;
    const LOG_KEEP_MS = 7 * 24 * 60 * 60 * 1000;

    /*
     * The listings a bazaar no longer has (3.23.0; the friend's log, 2026-10-04,
     * was line after line of them, one a listing): one line a bazaar. An entry
     * carries `fold` (a name for this visit to this bazaar - never the seller's
     * id) and `gone` ([[item id, count when last seen]]); entries with the same
     * `fold` become one, at the time of the first.
     */
    const GONE_KEPT = 100;
    const GONE_LISTED = 20;
    const GONE_TEXT = 190;

    /** @param {Array<[string|number, number]>} gone  @param {number} [more] - others, not kept one by one */
    function goneLine(gone, more = 0) {
        const tail = ' - left out of the plans in Torn Archive';
        const n = gone.length + more;
        if (n === 1 && gone.length) return 'A listing is no longer in this bazaar (item ' + gone[0][0] + ', ' + gone[0][1] + ' when last seen)' + tail;
        let shown = '';
        let listed = 0;
        for (const [id, qty] of gone) {
            const next = (listed ? ', ' : 'item ') + id + ' ×' + qty;
            if (listed >= GONE_LISTED || shown.length + next.length > GONE_TEXT) break;
            shown += next;
            listed += 1;
        }
        return n + ' listings are no longer in this bazaar (when last seen: ' + shown + (n > listed ? ' and ' + (n - listed) + ' more' : '') + ')' + tail;
    }

    function foldGone(into, e) {
        const byId = new Map((into.gone || []).map(([id, qty]) => [String(id), qty]));
        let more = Number(into.goneMore) || 0;
        for (const [id, qty] of e.gone || []) {
            if (byId.has(String(id)) || byId.size < GONE_KEPT) byId.set(String(id), qty);
            else more += 1;
        }
        more += Number(e.goneMore) || 0;
        into.gone = [...byId];
        if (more) into.goneMore = more;
        into.what = goneLine(into.gone, more);
        into.lastAt = Math.max(Number(into.lastAt) || 0, Number(e.lastAt) || 0, Number(e.at) || 0);
    }

    /** The stored log plus new entries: oldest first, a week at most, LOG_MAX at most. */
    function addLogEntries(stored, entries, now = Date.now()) {
        const all = [...(Array.isArray(stored) ? stored : []), ...(entries || [])]
            .filter((e) => e && Number.isFinite(Number(e.at)) && now - Number(e.at) < LOG_KEEP_MS)
            .sort((a, b) => a.at - b.at);
        // The same line twice in a row within a minute is counted, not repeated. The same line: message AND detail
        // (Torn Archive 1.0.0 - two different failures with one message were folded into one, and the second's detail lost).
        const out = [];
        const folds = new Map();
        for (const e of all) {
            if (e.fold && Array.isArray(e.gone)) {
                const first = folds.get(e.fold);
                if (first) foldGone(first, e);
                else {
                    const copy = { ...e, gone: e.gone.map((g) => [String(g[0]), g[1]]) };
                    folds.set(e.fold, copy);
                    out.push(copy);
                }
                continue;
            }
            const last = out[out.length - 1];
            if (last && !last.fold && last.kind === e.kind && last.where === e.where && last.what === e.what && (last.detail || '') === (e.detail || '') && e.at - last.at < 60000) {
                last.times = (last.times || 1) + (e.times || 1);
                last.lastAt = e.at;
            } else {
                out.push({ ...e });
            }
        }
        return out.slice(-LOG_MAX);
    }

    /**
     * A request that got no answer in time, for something still held from an
     * earlier read (3.22.2): TornExchange's list of active traders is waited 90 s
     * for, asked again later, and the list last read is used meanwhile. The
     * friend's report, 2026-10-04, was "2 errors today" - both this, with nothing
     * lost. A note in the log, not an error. Without a list held it is an error.
     */
    function lateButHeld(path, error, held) {
        return Boolean(held) && /^active_traders$/.test(String(path || '')) && /^no answer/.test(String((error && error.reason) || ''));
    }

    /** A line of text, never a key: anything key-like is masked (16 letters and digits). */
    function logText(text, max = 300) {
        return String(text === null || text === undefined ? '' : text)
            .replace(/key=[^&\s"']+/gi, 'key=****')
            .replace(/\b[A-Za-z0-9]{16}\b/g, '****')
            .slice(0, max);
    }

    /** The log as plain text, one line each, for the report. */
    function logAsText(list) {
        const pad = (n) => String(n).padStart(2, '0');
        const t = (ms) => {
            const d = new Date(ms);
            return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
        };
        return (list || []).map((e) => t(e.at) + '  ' + (e.kind === 'error' ? 'ERROR ' : e.kind === 'action' ? 'did   ' : 'note  ') + '[' + (e.where || '?') + '] ' + e.what + (e.detail ? ' - ' + e.detail : '') + (e.times > 1 ? ' (x' + e.times + ', last ' + t(e.lastAt) + ')' : e.fold && e.lastAt > e.at ? ' (last ' + t(e.lastAt) + ')' : '')).join('\n') + '\n';
    }

    /* ===== src/core/zip.js ===== */
    /*
     * A .zip of a few text files, made in the browser (3.15: Settings › API use ›
     * Export, "downloads as a zip file so he can send it to us"). Stored, not
     * compressed - a few hundred KB of numbers at most - so nothing but a CRC-32
     * and the zip headers: no library.
     */

    const CRC_TABLE = (() => {
        const t = new Uint32Array(256);
        for (let n = 0; n < 256; n++) {
            let c = n;
            for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
            t[n] = c >>> 0;
        }
        return t;
    })();

    function crc32(bytes) {
        let c = 0xffffffff;
        for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
        return (c ^ 0xffffffff) >>> 0;
    }

    /** MS-DOS time and date, as zip headers keep them. */
    function dosTime(d) {
        return {
            time: (d.getHours() << 11) | (d.getMinutes() << 5) | Math.floor(d.getSeconds() / 2),
            date: ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate(),
        };
    }

    /**
     * @param {Array<{name: string, text?: string, data?: Uint8Array}>} files
     * @param {Date} [when]
     * @returns {Uint8Array} the .zip
     */
    function makeZip(files, when = new Date()) {
        const enc = new TextEncoder();
        const { time, date } = dosTime(when);
        const parts = [];
        const central = [];
        let offset = 0;
        for (const f of files) {
            const name = enc.encode(f.name);
            // Text, or bytes as they are (a screenshot).
            const data = f.data instanceof Uint8Array ? f.data : enc.encode(f.text || '');
            const crc = crc32(data);
            const local = new DataView(new ArrayBuffer(30));
            local.setUint32(0, 0x04034b50, true);
            local.setUint16(4, 20, true); // version needed
            local.setUint16(6, 0x0800, true); // UTF-8 names
            local.setUint16(8, 0, true); // stored
            local.setUint16(10, time, true);
            local.setUint16(12, date, true);
            local.setUint32(14, crc, true);
            local.setUint32(18, data.length, true);
            local.setUint32(22, data.length, true);
            local.setUint16(26, name.length, true);
            local.setUint16(28, 0, true);
            parts.push(new Uint8Array(local.buffer), name, data);

            const cen = new DataView(new ArrayBuffer(46));
            cen.setUint32(0, 0x02014b50, true);
            cen.setUint16(4, 20, true);
            cen.setUint16(6, 20, true);
            cen.setUint16(8, 0x0800, true);
            cen.setUint16(10, 0, true);
            cen.setUint16(12, time, true);
            cen.setUint16(14, date, true);
            cen.setUint32(16, crc, true);
            cen.setUint32(20, data.length, true);
            cen.setUint32(24, data.length, true);
            cen.setUint16(28, name.length, true);
            cen.setUint32(42, offset, true);
            central.push(new Uint8Array(cen.buffer), name);
            offset += 30 + name.length + data.length;
        }
        const centralSize = central.reduce((a, p) => a + p.length, 0);
        const end = new DataView(new ArrayBuffer(22));
        end.setUint32(0, 0x06054b50, true);
        end.setUint16(8, files.length, true);
        end.setUint16(10, files.length, true);
        end.setUint32(12, centralSize, true);
        end.setUint32(16, offset, true);
        const all = [...parts, ...central, new Uint8Array(end.buffer)];
        const out = new Uint8Array(all.reduce((a, p) => a + p.length, 0));
        let at = 0;
        for (const p of all) {
            out.set(p, at);
            at += p.length;
        }
        return out;
    }

    /* ===== src/sources/route.js ===== */
    /*
     * Which Torn page are we on? Pure string work, so it is testable.
     *
     * V1 ran both scanners on every page under `@match .../*`, which is why it
     * lit up on the Items page and in city shops. Here exactly one scanner runs,
     * and on an unrecognised page nothing runs at all.
     *
     * Cut for Torn Archive from Torn Bids 3.24.0 (sources/route.js): the pages
     * Torn Archive reads or marks, and its own page's address in place of Torn
     * Bids'. Profiles and the Item Market's own-listing pages are left behind.
     */

    const PAGE_BAZAAR = 'bazaar';
    const PAGE_ITEM_MARKET = 'itemmarket';
    const PAGE_NONE = null;

    /**
     * @param {string} href - normally location.href
     * @returns {'bazaar'|'itemmarket'|null}
     */
    function detectPage(href) {
        if (typeof href !== 'string' || !href) return PAGE_NONE;

        const url = href.toLowerCase();

        // Item Market 2.0 lives behind page.php?sid=ItemMarket; imarket.php is
        // the older path and still redirects for some users.
        if (url.includes('sid=itemmarket') || url.includes('/imarket.php')) {
            return PAGE_ITEM_MARKET;
        }

        // Own bazaar and other players' bazaars, new path and legacy query form.
        if (url.includes('/bazaar.php') || url.includes('page=bazaar')) {
            return PAGE_BAZAAR;
        }

        return PAGE_NONE;
    }

    /**
     * Torn's trade page (trade.php, any step). `page=trade` is the test
     * harness's stand-in, as `page=bazaar` is for bazaars.
     */
    function isTradePage(href) {
        const url = String(href || '').toLowerCase();
        return url.includes('/trade.php') || /[?&]page=trade(?:[&#]|$)/.test(url);
    }

    /**
     * Deep link to an item's Item Market page.
     *
     * Used by the panel's navigate button. One click, one navigation - the script
     * never buys anything and never chains a second request off the same click.
     */
    function itemMarketUrl(itemId, itemName) {
        const params = new URLSearchParams({
            itemID: String(itemId),
            itemName: String(itemName || ''),
        });

        return (
            'https://www.torn.com/page.php?sid=ItemMarket#/market/view=search&' +
            params.toString()
        );
    }

    function queryOf(href) {
        try {
            return new URL(href).searchParams;
        } catch {
            return new URLSearchParams();
        }
    }

    /**
     * Whose bazaar is this? `bazaar.php?userId=123`. Null for your own bazaar
     * (no userId) or anything unparseable - a sighting with no seller is simply
     * remembered without one.
     */
    function bazaarOwnerId(href) {
        if (detectPage(href) !== PAGE_BAZAAR) return null;

        // Any spelling (userId, userid, userID, USERID): Torn's own links vary, and
        // a missed one made another player's bazaar look like your own.
        let id = null;
        for (const [name, value] of queryOf(href)) {
            if (name.toLowerCase() === 'userid') {
                id = value;
                break;
            }
        }
        return id && /^\d+$/.test(id) ? id : null;
    }

    /**
     * The listing a feed link asked us to point at: `ttItem` / `ttPrice`, which
     * bazaarUrl() in core/feed.js writes. Highlighting it is reading and marking
     * the page the user opened, which is allowed; nothing is clicked or filled.
     */
    function bazaarTarget(href) {
        if (detectPage(href) !== PAGE_BAZAAR) return null;

        const q = queryOf(href);
        const itemId = q.get('ttItem');
        const price = Number(q.get('ttPrice'));

        if (!itemId || !/^\d+$/.test(itemId)) return null;

        return {
            itemId,
            price: Number.isFinite(price) && price > 0 ? price : null,
        };
    }

    /**
     * Your OWN bazaar's add-listings (#/add) and manage-listings (#/manage)
     * pages: bazaar.php with no userId, and that hash. Anything else - another
     * player's bazaar, your own storefront - is null. The hash changes without a
     * page load, so callers re-check on hashchange.
     *
     * @returns {'add'|'manage'|null}
     */
    function ownBazaarPage(href) {
        if (typeof href !== 'string' || !href) return null;
        if (detectPage(href) !== PAGE_BAZAAR) return null;
        if (bazaarOwnerId(href)) return null;

        const hash = (href.split('#')[1] || '').toLowerCase().replace(/^\/+/, '').split(/[?&]/)[0];
        if (hash === 'add' || hash.startsWith('add/')) return 'add';
        if (hash === 'manage' || hash.startsWith('manage/')) return 'manage';
        return null;
    }

    /*
     * Torn Archive's own page, in its own tab, on a page of our own (GitHub
     * Pages), not on Torn: the script draws the page over a blank one there.
     * Nothing on torn.com is loaded for it, and it can be opened and checked like
     * any site.
     */
    const ARCHIVE_PAGE_URL = 'https://abrahamdelosreyes17-oss.github.io/torn-archive/';
    /* The test harness boots the page on its own address with this marker (?tarc=archive). */
    const ARCHIVE_PAGE_PARAM = 'tarc';
    const ARCHIVE_PAGE_VALUE = 'archive';

    function isTornHost(href) {
        try {
            return /(^|\.)torn\.com$/.test(new URL(href).hostname);
        } catch {
            return false;
        }
    }

    /** Is this Torn Archive's own page? Its address with or without the last slash or index.html; or the harness's stand-in, never on Torn. */
    function isArchivePageUrl(url) {
        const bare = String(url || '').split(/[?#]/)[0];
        const base = ARCHIVE_PAGE_URL.replace(/\/$/, '');
        if (bare === base || bare === base + '/' || bare === base + '/index.html') return true;
        return queryOf(url).get(ARCHIVE_PAGE_PARAM) === ARCHIVE_PAGE_VALUE && !isTornHost(url);
    }

    /* ------------------------------------------------------------- Sets (3.24.0) */

    /** Torn's museum, the points market, and a trade as you view it. Links only: one press, one page. */
    const MUSEUM_URL = 'https://www.torn.com/museum.php';
    const POINTS_MARKET_URL = 'https://www.torn.com/pmarket.php';
    function tradeViewUrl(tradeId) {
        return 'https://www.torn.com/trade.php#step=view&ID=' + encodeURIComponent(String(tradeId).replace(/\D/g, ''));
    }

    /** The museum (museum.php). `page=museum` is the test harness's stand-in. */
    function isMuseumPage(href) {
        const url = String(href || '').toLowerCase();
        return url.includes('/museum.php') || /[?&]page=museum(?:[&#]|$)/.test(url);
    }

    /** The points market (pmarket.php). `page=pmarket` is the harness's stand-in. */
    function isPointsMarketPage(href) {
        const url = String(href || '').toLowerCase();
        return url.includes('/pmarket.php') || /[?&]page=pmarket(?:[&#]|$)/.test(url);
    }

    /** Torn's forums (forums.php). `page=forum` is the harness's stand-in. */
    function isForumPage(href) {
        const url = String(href || '').toLowerCase();
        return url.includes('/forums.php') || /[?&]page=forum(?:[&#]|$)/.test(url);
    }

    /* ===== src/ui/hub-css.js ===== */
    // The hub's look: mockup AB's own stylesheet, taken whole (mockups/AB-torn-archive.html in the Torn Trading folder).
    // The hub owns its page, so nothing here is scoped. What is drawn on Torn's pages has its own, prefixed, in marks-css.js.

    const HUB_CSS = `
    :root {
      --rail: 60px; --side: 236px;
      --bg: #090b10; --rail-bg: #0c0f15; --panel: #10131a; --raised: #171b24; --hover: #1c212c; --input: #0a0c11;
      --line: rgba(255,255,255,.07); --line2: rgba(255,255,255,.13);
      --text: #f3f5f9; --text2: #c9cfda; --muted: #8e96a6; --faint: #626a7a;
      --brand: #8f7bff; --brand-bg: rgba(143,123,255,.14); --brand-line: rgba(143,123,255,.45);
      --good: #3fcf6b; --good-bg: rgba(63,207,107,.12); --bad: #f0605d; --bad-bg: rgba(240,96,93,.12);
      --warn: #f5a524; --warn-bg: rgba(245,165,36,.12); --need: #4c9dff; --need-bg: rgba(76,157,255,.12);
      /* what you hold of a piece against what you build (the owner, 2026-10-11): orange still needed, green exactly enough, red too many */
      --st-need: var(--warn); --st-even: var(--good); --st-over: var(--bad);
      --s-plush: #3987e5; --s-flower: #d55181; --s-gold: #c98500; --s-violet: #9085e9; --s-aqua: #199e70;
      --grid: #1a1f29; --axis: #2a303c;
      --sans: "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
      --disp: "Segoe UI Variable Display", "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
      --ease: cubic-bezier(.2,.8,.2,1);
    }
    * { box-sizing: border-box; }
    html, body { height: 100%; margin: 0; overflow: hidden; background: var(--bg); color: var(--text); }
    body { font: 400 13px/1.45 var(--sans); -webkit-font-smoothing: antialiased; }
    b, strong { font-weight: 600; }
    button { font: inherit; color: inherit; cursor: pointer; }
    .num, td, th, .k-v { font-variant-numeric: tabular-nums; }
    svg.ic { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }

    /* ---------- shell ---------- */
    .app { height: 100vh; display: grid; grid-template-columns: var(--rail) minmax(0, 1fr); transition: grid-template-columns .26s var(--ease); background: radial-gradient(1100px 520px at 12% -10%, rgba(143,123,255,.07), transparent 60%), var(--bg); }
    .app.pinned { grid-template-columns: var(--side) minmax(0, 1fr); }
    .side { position: relative; z-index: 40; }
    .side-in { position: absolute; inset: 0 auto 0 0; width: var(--rail); display: flex; flex-direction: column; background: var(--rail-bg); border-right: 1px solid var(--line); overflow: hidden; transition: width .26s var(--ease), box-shadow .26s var(--ease); }
    .side.open .side-in, .app.pinned .side-in { width: var(--side); }
    .app:not(.pinned) .side.open .side-in { box-shadow: 18px 0 48px rgba(0,0,0,.55); border-right-color: var(--line2); }
    .lab { opacity: 0; transform: translateX(-6px); transition: opacity .18s var(--ease), transform .26s var(--ease); white-space: nowrap; pointer-events: none; }
    .side.open .lab, .app.pinned .lab { opacity: 1; transform: none; pointer-events: auto; }
    .brand { height: 52px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 0 0 14px; border-bottom: 1px solid var(--line); }
    .mark { width: 32px; height: 32px; flex: none; border-radius: 10px; display: grid; place-items: center; color: #fff; background: linear-gradient(145deg, #a694ff, #6a55e8); box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset, 0 6px 18px rgba(143,123,255,.35); }
    .brand .lab b { display: block; font: 650 15px/1.1 var(--disp); letter-spacing: .01em; }
    .brand .lab span { color: var(--muted); font-size: 12px; } .brand .pin { margin-left: auto; margin-right: 10px; }
    .nav { position: relative; flex: 1; padding: 8px; display: flex; flex-direction: column; gap: 2px; min-height: 0; }
    .nav-ind { position: absolute; left: 8px; right: 8px; top: 0; height: 38px; border-radius: 10px; background: var(--brand-bg); box-shadow: inset 0 0 0 1px var(--brand-line); transition: transform .32s var(--ease); pointer-events: none; }
    .nav-ind::before { content: ""; position: absolute; left: -8px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--brand); }
    .nav-g { height: 26px; flex: none; display: flex; align-items: center; padding: 0 12px; color: var(--faint); font: 650 12px var(--sans); letter-spacing: .08em; text-transform: uppercase; position: relative; }
    .nav-g::after { content: ""; position: absolute; left: 12px; right: 12px; top: 50%; border-top: 1px solid var(--line); transition: opacity .18s; }
    .side.open .nav-g::after, .app.pinned .nav-g::after { opacity: 0; }
    .nav-b { position: relative; height: 38px; flex: none; display: flex; align-items: center; gap: 14px; padding: 0 12px; border: 0; border-radius: 10px; background: none; color: var(--muted); text-align: left; transition: color .16s, background .16s; }
    .nav-b:hover { color: var(--text); background: rgba(255,255,255,.04); }
    .nav-b.on { color: var(--text); }
    .nav-b.on svg { color: var(--brand); }
    .nav-b .lab { flex: 1; font-weight: 550; }
    .nav-b .cnt { font: 650 12px var(--sans); padding: 1px 7px; border-radius: 999px; color: var(--need); background: var(--need-bg); }
    .nav-b .cnt.hot { color: var(--warn); background: var(--warn-bg); }
    .nav-b .pip { position: absolute; left: 28px; top: 8px; width: 7px; height: 7px; border-radius: 50%; background: var(--warn); box-shadow: 0 0 0 2px var(--rail-bg); transition: opacity .18s; }
    .side.open .pip, .app.pinned .pip { opacity: 0; }
    .side-f { flex: none; padding: 8px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 6px; }
    .shop { height: 40px; display: flex; align-items: center; gap: 14px; padding: 0 12px; border-radius: 10px; }
    .shop .dot { margin: 0 6px 0 7px; }
    .shop .lab { flex: 1; color: var(--text2); } .shop .lab b { color: var(--good); }
    .pin { width: 30px; height: 30px; flex: none; border-radius: 8px; border: 1px solid var(--line2); background: var(--raised); display: grid; place-items: center; color: var(--muted); transition: color .16s, background .16s, opacity .18s var(--ease); }
    .pin svg { width: 16px; height: 16px; transform: rotate(45deg); transition: transform .26s var(--ease); }
    .app.pinned .pin svg { transform: none; }
    .pin:hover { color: var(--text); }
    .app.pinned .pin { color: #fff; background: var(--brand); border-color: transparent; }
    .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--good); flex: none; display: inline-block; }
    .dot.warn { background: var(--warn); } .dot.off { background: var(--faint); } .dot.need { background: var(--need); }
    .live { width: 8px; height: 8px; border-radius: 50%; background: var(--good); flex: none; display: inline-block; position: relative; }
    .live::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; border: 1px solid var(--good); animation: ping 2.4s var(--ease) infinite; }

    .main { display: grid; grid-template-rows: 52px minmax(0, 1fr) 30px; height: 100vh; min-width: 0; container-type: inline-size; }
    .top { display: flex; align-items: center; gap: 10px; padding: 0 16px; border-bottom: 1px solid var(--line); white-space: nowrap; min-width: 0; }
    .top h1 { margin: 0 8px 0 0; font: 650 19px/1 var(--disp); letter-spacing: -.01em; }
    .tabs { display: flex; gap: 2px; align-self: stretch; }
    .tab { position: relative; padding: 0 12px; border: 0; background: none; color: var(--muted); font-weight: 550; transition: color .16s; }
    .tab:hover { color: var(--text); }
    .tab.on { color: var(--text); }
    .tab::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: 0; height: 2px; border-radius: 2px 2px 0 0; background: var(--brand); transform: scaleX(0); transition: transform .26s var(--ease); }
    .tab.on::after { transform: none; }
    .sp { flex: 1; }
    .pill { height: 30px; display: inline-flex; align-items: center; gap: 7px; padding: 0 10px; border-radius: 9px; background: var(--panel); border: 1px solid var(--line); color: var(--muted); font-size: 12px; }
    .pill b { color: var(--text); font-size: 13px; }
    .pill .dn { color: var(--warn); } .pill.flash { animation: flash 1s var(--ease); }
    @container (max-width: 1130px) { .pill.opt { display: none; } }
    @container (max-width: 1240px) { .page.stackable { grid-template-columns: minmax(0, 1fr); } .page.stackable .minc { min-height: 260px !important; } }
    /* Five panels across only with room for them: three and two below that (at 1707 px five cut their badges and buttons). */
    .tiles.five { grid-template-columns: repeat(5, minmax(0, 1fr)); }
    @container (max-width: 1900px) { .tiles.five { grid-template-columns: repeat(6, minmax(0, 1fr)); } .tiles.five > * { grid-column: span 2; } .tiles.five > :nth-child(n+4) { grid-column: span 3; } }
    @container (max-width: 1000px) { .tiles.five { grid-template-columns: repeat(2, minmax(0, 1fr)); } .tiles.five > *, .tiles.five > :nth-child(n+4) { grid-column: auto; } }
    @container (max-width: 1420px) { .page.stackable.wide { grid-template-columns: minmax(0, 1fr); } .page.stackable.wide .minc { min-height: 260px !important; } }
    .btn { height: 30px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--line2); background: var(--raised); color: var(--text); font-weight: 550; font-size: 13px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap; transition: background .16s, transform .16s var(--ease), border-color .16s; }
    .btn:hover { background: var(--hover); border-color: rgba(255,255,255,.22); }
    .btn:active { transform: scale(.97); }
    .btn.sm { height: 26px; padding: 0 10px; border-radius: 8px; font-size: 12px; }
    .btn.go { background: var(--brand); border-color: transparent; color: #fff; }
    .btn.go:hover { background: #a08fff; }
    .btn.link { background: var(--need-bg); border-color: transparent; color: #9cc6ff; }

    .tape { display: flex; align-items: center; border-top: 1px solid var(--line); background: var(--rail-bg); font-size: 12px; color: var(--muted); white-space: nowrap; min-width: 0; }
    .tape-l, .tape-r { flex: none; padding: 0 12px; height: 100%; display: flex; align-items: center; gap: 8px; }
    .tape-l { border-right: 1px solid var(--line); color: var(--text2); font-weight: 600; }
    .tape-r { border-left: 1px solid var(--line); gap: 14px; }
    .tape-m { flex: 1; min-width: 0; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 40px, #000 calc(100% - 40px), transparent); }
    .tape-t { display: inline-flex; gap: 26px; padding-left: 26px; animation: tape 150s linear infinite; }
    .tape-m:hover .tape-t { animation-play-state: paused; }
    .tk b { color: var(--text2); font-weight: 550; margin-right: 6px; } .tk .num { color: var(--text); margin-right: 6px; }
    .up { color: var(--bad); } .down { color: var(--good); }

    /* ---------- pages and panels ---------- */
    .view { overflow: auto; padding: 12px 16px; min-width: 0; scrollbar-width: thin; scrollbar-color: #2a303c transparent; }
    .page { display: none; gap: 12px; min-height: 100%; }
    .page.on { display: grid; }
    .pane { display: none; gap: 12px; min-height: 0; min-width: 0; }
    .pane.on { display: grid; }
    .col { display: flex; flex-direction: column; gap: 12px; min-width: 0; min-height: 0; }
    .panel { display: flex; flex-direction: column; min-width: 0; min-height: 0; background: linear-gradient(180deg, rgba(255,255,255,.018), transparent 120px), var(--panel); border: 1px solid var(--line); border-radius: 12px; transition: border-color .2s; animation: rise .46s var(--ease) both; animation-delay: calc(var(--i, 0) * 36ms); }
    .panel:hover { border-color: var(--line2); }
    .panel.grow { flex: 1; }
    .panel.tint { border-color: var(--brand-line); background: linear-gradient(180deg, var(--brand-bg), transparent 140px), var(--panel); }
    .panel.hold { border-color: rgba(245,165,36,.4); }
    .ph { flex: none; display: flex; align-items: center; gap: 12px; padding: 11px 14px 0; white-space: nowrap; min-height: 37px; }
    .ph h2 { margin: 0; font: 650 13px/1.2 var(--sans); color: var(--text); }
    .ph .sub { color: var(--muted); font-size: 12px; }
    .pb { flex: 1; min-height: 0; padding: 10px 14px 13px; position: relative; }
    .pb.flush { padding: 6px 0 4px; }
    .chart { position: absolute; inset: 4px 8px 6px 6px; }
    .chart svg { width: 100%; height: 100%; display: block; overflow: visible; }
    .legend { display: flex; gap: 14px; color: var(--text2); font-size: 12px; }
    .legend span { display: inline-flex; align-items: center; gap: 6px; }
    .key { width: 14px; height: 2px; border-radius: 2px; background: var(--c); flex: none; }
    .key.box { height: 10px; width: 10px; border-radius: 3px; }
    .key.band { height: 10px; background: rgba(255,255,255,.1); }
    .key.dash { background: repeating-linear-gradient(90deg, var(--muted) 0 4px, transparent 4px 7px); }
    .seg { display: inline-flex; background: var(--input); border: 1px solid var(--line); border-radius: 9px; padding: 2px; }
    .seg button { height: 24px; padding: 0 10px; border: 0; border-radius: 7px; background: none; color: var(--muted); font-size: 12px; font-weight: 600; transition: background .16s, color .16s; }
    .seg button.on { background: var(--raised); color: var(--text); }
    .tip { position: absolute; left: 0; top: 0; z-index: 20; pointer-events: none; padding: 8px 10px; border-radius: 9px; background: #1d222d; border: 1px solid var(--line2); box-shadow: 0 10px 30px rgba(0,0,0,.5); font-size: 12px; white-space: nowrap; opacity: 0; transition: opacity .12s; }
    .tip.on { opacity: 1; }
    .tip h4 { margin: 0 0 4px; font: 600 12px var(--sans); color: var(--muted); }
    .tip div { display: flex; align-items: center; gap: 7px; color: var(--text2); } .tip div b { margin-left: auto; padding-left: 14px; color: var(--text); }
    svg .g { stroke: var(--grid); stroke-width: 1; } svg .ax { fill: var(--muted); font: 12px var(--sans); }
    svg .lb { fill: var(--text2); font: 600 12px var(--sans); } svg .rl { fill: var(--muted); font: 12px var(--sans); }
    svg .ln { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
    svg .ln.draw { stroke-dasharray: 1; stroke-dashoffset: 1; animation: draw 1.1s var(--ease) .1s forwards; }
    svg .fade { animation: fade .9s ease .35s both; }
    svg .bar.growy { transform-box: fill-box; transform-origin: bottom; animation: growy .55s var(--ease) both; }
    svg .bar.neg.growy { transform-origin: top; }
    svg .cross { stroke: var(--line2); stroke-width: 1; }

    /* ---------- dashboard ---------- */
    .p-dash { grid-template-columns: repeat(12, minmax(0, 1fr)); grid-template-rows: auto minmax(170px, 1.25fr) minmax(160px, 1fr); height: 100%; min-height: 470px; }
    .kpi { grid-column: span 2; padding: 11px 14px 12px; position: relative; overflow: hidden; }
    .k-l { color: var(--muted); font-size: 12px; white-space: nowrap; }
    .k-v { font: 650 clamp(18px, 1.72cqw, 23px)/1.25 var(--disp); letter-spacing: -.015em; white-space: nowrap; }
    .k-v.good { color: var(--good); }
    .k-s { color: var(--muted); font-size: 12px; line-height: 1.4; } .k-s b { color: var(--text2); }
    .k-x { position: absolute; right: 12px; top: 9px; opacity: .95; }
    .meter { position: relative; height: 6px; border-radius: 4px; background: rgba(255,255,255,.07); margin: 7px 0 6px; }
    .meter i { position: absolute; inset: 0 auto 0 0; border-radius: 4px; background: var(--brand); width: var(--w); animation: growx .8s var(--ease) .2s both; transform-origin: left; }
    .meter u { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--text2); left: var(--at); border-radius: 2px; }
    .s8 { grid-column: span 8; } .s7 { grid-column: span 7; } .s6 { grid-column: span 6; } .s5 { grid-column: span 5; } .s4 { grid-column: span 4; } .s3 { grid-column: span 3; } .s12 { grid-column: span 12; }
    .next { display: grid; grid-auto-rows: minmax(0, 1fr); height: 100%; }
    .nx { display: flex; align-items: center; gap: 11px; padding: 6px 0; border-top: 1px solid var(--line); min-height: 0; }
    .nx:first-child { border-top: 0; }
    .next.few { display: flex; flex-direction: column; gap: 10px; }
    .nx-g { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; } .nx-g.bare { flex: none; } .nx-g + .nx-g { border-top: 1px solid var(--line); padding-top: 6px; }
    .nx-g > .nx { flex: none; padding: 4px 0 10px; border-top: 0; }
    /* The lines that fit are shown whole; one that would be cut goes to a column out of sight. */
    .nx-m { flex: 1; min-height: 0; display: flex; flex-flow: column wrap; overflow: hidden; align-content: flex-start; }
    .nm { flex: 1 0 28px; max-height: 38px; width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 64px 124px; align-items: center; gap: 10px; padding: 0 2px; border-top: 1px solid var(--line); white-space: nowrap; color: var(--text2); }
    .nm b { color: var(--text); font-weight: 600; } .nm-a { white-space: normal; line-height: 1.25; overflow-wrap: anywhere; } .nm-b, .nm-c { text-align: right; }
    .nm.h { flex: 0 0 24px; border-top: 0; color: var(--muted); font-size: 11px; align-items: end; padding-bottom: 5px; }
    .nx-f { flex: none; display: flex; justify-content: space-between; gap: 6px 16px; flex-wrap: wrap; padding-top: 9px; border-top: 1px solid var(--line); color: var(--text2); white-space: nowrap; } .nx-f b { color: var(--text); font-weight: 600; }
    /* A short card with two things to do has no room for their lines: one line each, as with many. */
    .pb.todo { container: todo / size; }
    @container todo (max-height: 250px) { .next.n2 .nx-m, .next.n2 .nx-f { display: none; } .next.n2 .nx-g { justify-content: center; } .next.n2 .nx-g > .nx { padding: 0; } }
    @container todo (max-height: 110px) { .next.n1 .nx-m, .next.n1 .nx-f { display: none; } .next.n1 .nx-g { flex: 1 1 0; justify-content: center; } }
    .nx-i { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; flex: none; background: var(--c-bg); color: var(--c); }
    .nx-i svg { width: 17px; height: 17px; }
    .nx-t { flex: 1; min-width: 0; color: var(--text2); line-height: 1.35; } .nx-t b { color: var(--text); }
    .sky2 { display: grid; grid-template-columns: 13fr 11fr; gap: 18px; height: 100%; }
    .sky { display: flex; flex-direction: column; min-height: 0; }
    .sky-h { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; color: var(--muted); font-size: 12px; margin-bottom: 6px; } .sky-h b { color: var(--text); font-size: 13px; }
    .sky-b { flex: 1; min-height: 0; position: relative; display: flex; align-items: flex-end; gap: 3px; border-bottom: 1px solid var(--axis); }
    .sky-c { flex: 1; max-width: 22px; height: var(--h); border-radius: 4px 4px 0 0; background: #4a5263; position: relative; animation: growy .6s var(--ease) both; animation-delay: calc(var(--n) * 22ms + 120ms); transform-origin: bottom; }
    .sky-c.need { background: var(--st-need); } .sky-c.even { background: var(--st-even); } .sky-c.over { background: var(--st-over); }
    .sky-c:hover { filter: brightness(1.25); }
    /* Over the bars (z-index): a bar taller than the line stood on the line's number (measured, 1.3.0). */
    .sky-l { position: absolute; left: 0; right: 0; bottom: var(--at); border-top: 1px dashed var(--muted); pointer-events: none; z-index: 1; }
    .sky-l span { position: absolute; right: 0; bottom: 2px; color: var(--muted); font-size: 12px; background: var(--panel); padding-left: 4px; }
    .sky-f { color: var(--text2); font-size: 12px; margin-top: 6px; white-space: nowrap; } .sky-f b { color: var(--text); }
    [data-tip] { position: relative; }
    [data-tip]:hover::after { content: attr(data-tip); position: absolute; left: 50%; bottom: calc(100% + 7px); transform: translateX(-50%); padding: 5px 8px; border-radius: 8px; background: #1d222d; border: 1px solid var(--line2); color: var(--text); font: 12px var(--sans); white-space: nowrap; z-index: 30; box-shadow: 0 8px 22px rgba(0,0,0,.5); }
    .ladder { display: grid; grid-auto-rows: minmax(16px, 1fr); height: 100%; font-size: 12px; line-height: 16px; }
    .lad { display: grid; grid-template-columns: 62px minmax(0, 1fr) 58px 92px; align-items: center; gap: 10px; padding: 0 14px; white-space: nowrap; }
    .lad.h { color: var(--faint); font-weight: 600; }
    .lad .r { text-align: right; } .lad .p { color: var(--text); font-weight: 600; }
    .lad .bar { height: 10px; border-radius: 0 4px 4px 0; background: var(--s-gold); width: var(--w); min-width: 3px; opacity: .85; animation: growx .7s var(--ease) both; animation-delay: calc(var(--n) * 50ms + 150ms); transform-origin: left; }
    .lad.wall .bar { opacity: 1; } .lad .tag { color: var(--muted); }
    /* Rows from the top, each its own height: one row is one row, not the whole panel (13 still fit without a scroll). */
    .after { display: grid; grid-auto-rows: minmax(18px, 34px); align-content: start; height: 100%; padding: 6px 0; box-sizing: border-box; font-size: 12px; min-height: 150px; }
    .af { display: grid; grid-template-columns: 178px minmax(0, 1fr) 110px; align-items: center; gap: 12px; padding: 0 14px; white-space: nowrap; }
    .af b { color: var(--text); font-weight: 600; } .af .it { margin-right: 8px; } .af .r { text-align: right; color: var(--muted); }
    .af-b { position: relative; height: 10px; display: flex; gap: 2px; }
    .af-b i { height: 100%; background: #4a5263; width: var(--w); animation: growx .7s var(--ease) both; animation-delay: calc(var(--n) * 40ms + 150ms); transform-origin: left; } .af-b i:first-child { border-radius: 3px 0 0 3px; } .af-b i:last-of-type { border-radius: 0 3px 3px 0; }
    .af-b i.nd { background: var(--need); } .af-b i.ah { background: var(--warn); }
    .af-b u { position: absolute; left: var(--at); top: -4px; bottom: -4px; width: 2px; background: var(--text2); border-radius: 2px; }
    .lad.you { background: var(--brand-bg); box-shadow: inset 2px 0 0 var(--brand); grid-template-columns: 62px minmax(0, 1fr); color: var(--text2); } .lad.you b { color: var(--text); }

    /* ---------- tables, tiles, bits ---------- */
    table.t { width: 100%; border-collapse: collapse; }
    .t th { text-align: left; padding: 7px 8px; color: var(--faint); font: 650 12px var(--sans); border-bottom: 1px solid var(--line); white-space: nowrap; position: sticky; top: 0; background: var(--panel); }
    .t td { padding: 7px 8px; border-bottom: 1px solid var(--line); color: var(--text2); white-space: nowrap; vertical-align: middle; }
    .t tr:last-child td { border-bottom: 0; }
    .t tbody tr { transition: background .14s; } .t tbody tr:hover { background: rgba(255,255,255,.028); }
    .t th:first-child, .t td:first-child { padding-left: 14px; } .t th:last-child, .t td:last-child { padding-right: 14px; }
    .t.kv th { position: static; width: 34%; white-space: normal; border-bottom: 1px solid var(--line); padding-left: 0; vertical-align: top; } .t.kv td { white-space: normal; padding-right: 0; } .t.kv tr:last-child th { border-bottom: 0; }
    .t.tight td { padding-top: 5px; padding-bottom: 5px; } .t.wrapth th { white-space: normal; vertical-align: bottom; } .t .n { text-align: right; } .t td b { color: var(--text); }
    .t tr.sum td { border-top: 1px solid var(--line2); border-bottom: 0; color: var(--text); font-weight: 600; }
    .sw { width: 8px; height: 8px; border-radius: 3px; display: inline-block; margin-right: 8px; background: var(--c); }
    .badge { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 999px; font: 600 12px/1 var(--sans); white-space: nowrap; color: var(--muted); background: rgba(255,255,255,.06); }
    .badge.need { color: #8fc1ff; background: var(--need-bg); } .badge.ahead { color: var(--warn); background: var(--warn-bg); } .badge.ok { color: var(--good); background: var(--good-bg); } .badge.bad { color: #ff8a87; background: var(--bad-bg); } .badge.best { color: #c9bfff; background: var(--brand-bg); }
    .badge.st-need { color: var(--warn); background: var(--warn-bg); } .badge.st-even { color: var(--good); background: var(--good-bg); } .badge.st-over { color: #ff8a87; background: var(--bad-bg); }
    .t-good { color: var(--good); } .t-bad { color: #ff8a87; } .t-warn { color: var(--warn); } .t-need { color: #8fc1ff; } .t-muted { color: var(--muted); }
    .t-stn { color: var(--warn); } .t-ste { color: var(--good); } .t-sto { color: #ff8a87; }
    .tiles { display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 12px; }
    .tile { padding: 11px 14px 12px; }
    /* Stock tiles (1.3.0, "maybe fix the size?"): a tile is never smaller than what it shows - 140 x 166 px holds the
       three lines - so as many go across as fit, at most --cols (two rows on a wide window), and a window too short
       scrolls the page. Nothing in a tile is hidden by its size any more. */
    .pgrid { display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(max(140px, calc((100% - (var(--cols, 7) - 1) * 8px) / var(--cols, 7) - .1px)), 1fr)); grid-auto-rows: minmax(166px, 1fr); }
    .p-stock > .col { min-height: auto; } .p-stock .panel.setp { flex: 1 0 auto; min-height: auto; } .p-stock .panel.setp > .pb { display: grid; flex: 1 0 auto; min-height: auto; }
    .pc { border-radius: 10px; background: var(--raised); border: 1px solid var(--line); min-width: 0; transition: transform .2s var(--ease), border-color .2s; }
    .pc:hover { transform: translateY(-2px); border-color: var(--line2); }
    .pc-n { font-weight: 600; line-height: 1.25; } .pc-q { color: var(--muted); font-size: 12px; } .pc-q b { color: var(--text); font: 650 15px var(--disp); margin-right: 3px; }
    .pc-bar { height: 4px; border-radius: 3px; background: rgba(255,255,255,.08); margin-top: auto; position: relative; overflow: hidden; }
    .pc-bar i { position: absolute; inset: 0 auto 0 0; width: var(--w); border-radius: 3px; background: #5a6274; animation: growx .7s var(--ease) both; animation-delay: calc(var(--n) * 25ms + 150ms); transform-origin: left; }
    .pc.need .pc-bar i { background: var(--st-need); } .pc.even .pc-bar i { background: var(--st-even); } .pc.over .pc-bar i { background: var(--st-over); }
    .pc-s { font-size: 12px; color: var(--muted); } .pc.need .pc-s { color: var(--warn); } .pc.even .pc-s { color: var(--good); } .pc.over .pc-s { color: #ff8a87; }
    .pc.first { border-color: rgba(245,165,36,.5); box-shadow: 0 0 0 3px rgba(245,165,36,.08); }
    .pc.act { background: var(--brand-bg); border-color: var(--brand-line); color: var(--text2); font-size: 12px; }
    .flow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; }
    .fl .k-l { white-space: normal; } .fl { padding: 2px 10px 2px 14px; border-left: 1px solid var(--line); position: relative; } .fl:first-child { border-left: 0; padding-left: 0; }
    .fl:not(:first-child)::before { content: "›"; position: absolute; left: -6px; top: 16px; color: var(--faint); background: var(--panel); font-size: 16px; line-height: 1; }
    .rows { display: flex; flex-direction: column; }
    .row { display: flex; align-items: center; gap: 10px; padding: 7px 0; border-top: 1px solid var(--line); white-space: nowrap; } .row:first-child { border-top: 0; }
    .row .grow1 { flex: 1; min-width: 0; white-space: normal; color: var(--text2); } .row .grow1 b { color: var(--text); }
    .li { display: flex; align-items: center; gap: 10px; padding: 8px 14px; border-top: 1px solid var(--line); transition: background .14s; } .li:hover { background: rgba(255,255,255,.028); }
    .li.sel { background: var(--brand-bg); box-shadow: inset 2px 0 0 var(--brand); }
    .li-m { flex: 1; min-width: 0; } .li-m b { display: block; } .li-m span { color: var(--muted); font-size: 12px; }
    .av { width: 30px; height: 30px; border-radius: 50%; background: var(--raised); border: 1px solid var(--line2); display: grid; place-items: center; font: 650 12px var(--sans); color: var(--text2); flex: none; }
    .msg { padding: 7px 12px; border-radius: 10px; background: var(--input); border: 1px solid var(--line); color: var(--text2); line-height: 1.5; }
    .hero { font: 650 36px/1 var(--disp); letter-spacing: -.02em; } .hero small { font-size: 16px; color: var(--muted); font-weight: 500; letter-spacing: 0; margin-left: 6px; }
    .track { position: relative; height: 8px; border-radius: 5px; background: rgba(255,255,255,.07); margin: 27px 0 26px; }
    .track i { position: absolute; inset: 0 auto 0 0; width: var(--w); border-radius: 5px; background: linear-gradient(90deg, #6a55e8, #a694ff); }
    .track .knob { position: absolute; left: var(--w); top: 50%; width: 16px; height: 16px; margin: -8px 0 0 -8px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 4px rgba(143,123,255,.3); }
    .track .mk { position: absolute; left: var(--at); top: -5px; bottom: -5px; width: 2px; background: var(--warn); }
    .track .mk span { position: absolute; top: 16px; left: 50%; transform: translateX(-50%); font-size: 12px; color: var(--muted); white-space: nowrap; }
    .track .mk.r span { left: auto; right: 0; transform: none; } .track .mk.l span { left: 0; transform: none; }
    .track .lo, .track .hi { position: absolute; top: -20px; font-size: 12px; color: var(--faint); } .track .lo { left: 0; } .track .hi { right: 0; }
    .toggle { display: inline-flex; align-items: center; gap: 8px; }
    .sw-t { width: 38px; height: 22px; border-radius: 999px; background: var(--good); position: relative; flex: none; } .sw-t::after { content: ""; position: absolute; right: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
    .field { display: flex; align-items: center; gap: 10px; padding: 9px 0; border-top: 1px solid var(--line); white-space: nowrap; } .field:first-child { border-top: 0; }
    .field .f-l { flex: 1; min-width: 0; white-space: normal; } .field .f-l span { display: block; color: var(--muted); font-size: 12px; }
    .inp { display: inline-flex; align-items: center; height: 30px; padding: 0 10px; border-radius: 8px; background: var(--input); border: 1px solid var(--line2); color: var(--text); font-variant-numeric: tabular-nums; }
    .inp.key { flex: 1; min-width: 0; letter-spacing: .2em; color: var(--muted); }
    .stack { display: flex; height: 14px; gap: 2px; border-radius: 5px; overflow: hidden; margin: 10px 0; } .stack i { background: var(--c); width: var(--w); animation: growx .8s var(--ease) both; transform-origin: left; }
    .notes { max-width: none; columns: 2; column-gap: 28px; color: var(--text2); line-height: 1.55; } .notes h3 { margin: 0 0 6px; font: 650 14px var(--sans); color: var(--text); break-after: avoid; } .notes ul { margin: 0 0 16px; padding-left: 18px; } .notes li { margin-bottom: 5px; break-inside: avoid; } .notes li b { color: var(--text); }
    .paused { position: absolute; inset: 52px 0 30px 0; z-index: 35; display: none; place-items: center; background: rgba(9,11,16,.82); backdrop-filter: blur(6px); }
    .paused.on { display: grid; animation: fade .3s ease both; }
    .paused .card { width: min(560px, 90%); padding: 22px 24px; border-radius: 16px; background: var(--panel); border: 1px solid rgba(245,165,36,.45); box-shadow: 0 24px 80px rgba(0,0,0,.6); }
    .paused h2 { margin: 0 0 8px; font: 650 19px var(--disp); display: flex; align-items: center; gap: 10px; } .paused p { margin: 0 0 10px; color: var(--text2); }

    /* ---------- item pictures: Torn's own, as Torn Bids shows them ---------- */
    .it { width: 38px; height: 19px; box-sizing: content-box; flex: none; display: inline-grid; place-items: center; vertical-align: middle; margin-right: 8px; border-radius: 4px; background: rgba(255,255,255,.05); border-bottom: 2px solid var(--c, transparent); font: 650 12px/1 var(--sans); color: var(--text2); overflow: hidden; }
    .it img { width: 38px; height: 19px; object-fit: contain; display: block; }
    .it.lg { width: 60px; height: 30px; } .it.lg img { width: 60px; height: 30px; }
    .tk .it { margin-right: 6px; }
    .t-brand { color: #c9bfff; }
    .top.tight .pill.opt { display: none; } .top.tighter .pill .dn { display: none; }
    .nx-p { width: 38px; flex: none; display: grid; place-items: center; } .nx-p .it { margin: 0; }
    .pc-h { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 2px 6px; } .pc-h .it { margin: 0; } .pc .it, .pc .it img { width: 30px; height: 15px; }
    /* stock tiles: what is in a tile grows with the tile, so a tall screen leaves no empty box */
    .pc { container: pc / size; display: block; padding: 0; cursor: pointer; }
    .pc-in { height: 100%; display: flex; flex-direction: column; gap: 2px; padding: 7px 8px; }
    .pc.act { cursor: default; } .pc.act .pc-in { justify-content: center; align-items: flex-start; gap: 7px; }
    .pc-big { font: 650 15px var(--disp); color: var(--text); margin-right: 5px; }
    .pc-x { display: grid; gap: 2px; flex: none; margin-top: 4px; padding-top: 5px; border-top: 1px solid var(--line); } .pc-k .w { display: none; } .pc-bar, .pc-h, .pc-n, .pc-q { flex: none; }
    .pc-k { display: flex; align-items: baseline; justify-content: space-between; gap: 0 6px; font-size: 12px; color: var(--muted); white-space: nowrap; } .pc-k b { color: var(--text2); font-weight: 600; }
    /* A bigger tile is roomier - picture, type, the longer words - and never shows less. */
    @container pc (min-width: 176px) { .pc-k .w { display: inline; } .pc-k .n { display: none; } }
    @container pc (min-height: 200px) { .pc-in { padding: 10px 12px 11px; gap: 3px; } .pc .it, .pc .it img { width: 60px; height: 30px; } .pc-n { font-size: 14px; margin-top: 2px; } .pc-q b, .pc-big { font-size: 21px; } .pc-bar { height: 6px; } .pc.act { font-size: 13px; } .pc-x { gap: 3px; margin-top: 5px; padding-top: 6px; } }
    @container pc (min-height: 270px) and (min-width: 170px) { .pc-in { padding: 12px 14px 13px; gap: 4px; } .pc .it, .pc .it img { width: 100px; height: 50px; } .pc-n { font-size: 15px; } .pc-q b, .pc-big { font-size: 26px; } .pc-x { gap: 5px; } }
    /* the buying run */
    .stop.cur { background: var(--brand-bg); box-shadow: inset 3px 0 0 var(--brand); }
    .stop.done .stop-n { background: var(--good-bg); border-color: transparent; color: var(--good); } .stop.skip .stop-n { color: var(--faint); }
    .stop.done .chips, .stop.skip .chips { opacity: .55; }
    .stop-st { font-size: 12px; color: var(--muted); } .stop.done .stop-st { color: var(--good); } .stop.cur .stop-st { color: #c9bfff; }
    .kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; margin-left: 8px; padding: 0 4px; border-radius: 5px; background: rgba(255,255,255,.22); font: 650 12px/1 var(--sans); }
    .runbar { display: flex; align-items: center; gap: 8px 10px; flex-wrap: wrap; padding-bottom: 9px; color: var(--text2); } .runbar > span { flex: 1 1 220px; min-width: 0; } .runbar b { color: var(--text); }
    /* a name or a button that opens the real page on Torn */
    .lk { color: inherit; cursor: pointer; text-decoration: none; } .lk::after { content: "\\2197"; margin-left: 4px; font-size: 12px; font-weight: 400; color: var(--faint); transition: color .14s; } .lk:hover, .lk:hover::after { color: #c9bfff; }
    .btn.out::after { content: "\\2197"; margin-left: 6px; opacity: .75; }
    @container pc (max-width: 120px) { .pc .btn.out::after { display: none; } }
    .main { position: relative; }
    .kpis { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; } .kpis .kpi { grid-column: auto; }
    /* is it worth opening */
    .verdict { display: flex; align-items: center; gap: 10px; padding-bottom: 9px; white-space: nowrap; } .verdict b { font: 650 16px var(--disp); } .verdict .sp { flex: 1; } .verdict .lamp { margin: 0 4px; }
    .chk { display: flex; align-items: baseline; gap: 10px; padding: 6px 0; border-top: 1px solid var(--line); color: var(--text2); line-height: 1.45; } .chk b { color: var(--text); }
    .chk::before { content: "\\2713"; flex: none; width: 16px; color: var(--good); font-weight: 700; } .chk.no::before { content: "\\2715"; color: var(--warn); }
    /* open trades */
    .li[data-tr] { cursor: pointer; } .li .amt { text-align: right; white-space: nowrap; } .li .amt span { display: block; }
    .st { font-size: 12px; white-space: nowrap; color: var(--muted); } .st.you { color: var(--warn); } .st.new { color: #c9bfff; }
    .av.new { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-bg); }
    /* the notice of a new trade */
    .toast { position: absolute; top: 62px; right: 16px; z-index: 60; display: flex; align-items: center; gap: 12px; padding: 10px 10px 10px 12px; border-radius: 12px; background: var(--panel); border: 1px solid var(--brand-line); box-shadow: 0 16px 40px rgba(0,0,0,.55); white-space: nowrap; opacity: 0; transform: translateY(-8px); pointer-events: none; transition: opacity .26s var(--ease), transform .26s var(--ease); }
    .toast.on { opacity: 1; transform: none; pointer-events: auto; } .toast b { display: block; } .toast .s { color: var(--muted); font-size: 12px; }
    .toast .x { width: 22px; height: 22px; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--faint); font-size: 16px; line-height: 1; } .toast .x:hover { color: var(--text); background: rgba(255,255,255,.08); }
    .shows { display: grid; gap: 18px; align-content: start; } .shows h4 { margin: 0 0 7px; font: 600 12px var(--sans); color: var(--muted); } .shows p { margin: 0; color: var(--text2); }
    .field { flex-wrap: wrap; row-gap: 6px; } .field .f-l { flex: 1 1 150px; } .field > .seg, .field > .inp { margin-left: auto; }
    .osn { width: 100%; display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 10px; background: #2b2d33; border: 1px solid rgba(255,255,255,.1); color: #f1f1f1; font: 13px/1.4 "Segoe UI", system-ui, sans-serif; box-shadow: 0 10px 30px rgba(0,0,0,.5); } .osn b { display: block; } .osn span.s { color: #b9bcc4; font-size: 12px; }
    .tabt { display: inline-flex; align-items: center; gap: 8px; padding: 7px 14px; border-radius: 9px 9px 0 0; background: var(--raised); border: 1px solid var(--line2); border-bottom: 0; color: var(--text2); } .tabt .mark, .osn .mark { width: 20px; height: 20px; border-radius: 6px; } .osn .mark { width: 30px; height: 30px; border-radius: 9px; } .tabt .mark svg { width: 12px; height: 12px; }
    .ta-ok { color: var(--good); font-size: 12px; } .ta-warn { color: var(--warn); font-size: 12px; } .mk.fill[data-take] { cursor: pointer; }

    /* ---------- buy: every place that sells a piece, and the shopping list ---------- */
    .p-buy { grid-template-columns: minmax(0, 1fr); } .p-buy > .pane { height: 100%; } .gbuy { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); }
    /* Side by side only while "Sold by" keeps room for a seller's name beside its six columns. */
    @container (max-width: 1560px) { .pane.stk { grid-template-columns: minmax(0, 1fr); } .pane.stk .minc { min-height: 260px !important; } }
    .t tr.pick { cursor: pointer; } .t tbody tr.sel, .t tbody tr.sel:hover { background: var(--brand-bg); box-shadow: inset 2px 0 0 var(--brand); }
    .rec { display: flex; align-items: center; gap: 10px 18px; flex-wrap: wrap; } .rec .hero { white-space: nowrap; } .rec-t { flex: 1; min-width: 240px; color: var(--text2); line-height: 1.5; } .rec-t b { color: var(--text); } .rec-b { display: flex; align-items: center; gap: 8px 14px; flex-wrap: wrap; } .from { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; white-space: nowrap; } .ph .from { margin-right: 6px; }
    /* "Against its worth" holds "No thanks · $1,234 a point over" whole (1.3.0: at 150px it ran under "Checked"). */
    .wl { display: grid; grid-template-columns: minmax(96px, 1fr) 44px 72px 196px 104px 104px; align-items: center; gap: 8px; padding: 6px 14px; border-top: 1px solid var(--line); white-space: nowrap; color: var(--text2); transition: background .14s; }
    .wl:hover { background: rgba(255,255,255,.028); } .wl b { color: var(--text); } .wl .n { text-align: right; }
    .wl.h { color: var(--faint); font: 650 12px var(--sans); } .wl.h:hover { background: none; }
    .wl.cheap b.num { color: #c9bfff; } .wl.old > span:not(.wl-a), .wl.old > b { opacity: .5; } .wl-s.old-h { border-top: 1px solid var(--line); } .wl.on { background: var(--brand-bg); box-shadow: inset 2px 0 0 var(--brand); }
    .wl-a { display: flex; gap: 6px; justify-content: flex-end; }
    .wl-s { padding: 4px 14px 9px; color: var(--text2); font-size: 12px; line-height: 1.5; } .wl-s b { color: var(--text); } .wl-s.foot { padding-top: 9px; border-top: 1px solid var(--line); color: var(--muted); }
    .stop { display: flex; gap: 10px; padding: 9px 14px; border-top: 1px solid var(--line); } .stop:first-child { border-top: 0; }
    .stop-n { width: 22px; height: 22px; flex: none; border-radius: 50%; display: grid; place-items: center; background: var(--raised); border: 1px solid var(--line2); font: 650 12px var(--sans); color: var(--text2); }
    .stop-m { flex: 1; min-width: 0; } .stop-h { display: flex; align-items: center; gap: 10px; white-space: nowrap; flex-wrap: wrap; }
    .chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 7px; }
    .chip { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 4px 0 6px; border-radius: 8px; background: var(--raised); border: 1px solid var(--line); white-space: nowrap; font-size: 12px; color: var(--text2); }
    .chip .it { margin: 0; } .chip b { color: var(--text); }
    .tg { display: inline-flex; align-items: center; height: 18px; padding: 0 7px; border-radius: 999px; font: 600 12px/1 var(--sans); color: var(--warn); background: var(--warn-bg); }
    /* the three groups, said once */
    .grp { display: grid; gap: 4px; } .grp > span { color: var(--muted); } .grp b { display: inline-block; min-width: 104px; color: var(--text); }
    /* the break-even: your cost a point against the price now */
    .even-b { position: relative; height: 10px; margin: 6px 0 12px; border-radius: 5px; background: rgba(255,255,255,.07); }
    .even-b i { position: absolute; top: 0; bottom: 0; left: var(--a); width: var(--w); background: var(--good); opacity: .5; } .even-b.bad i { background: var(--bad); }
    .even-b u { position: absolute; top: -4px; bottom: -4px; left: var(--at); width: 3px; margin-left: -1px; border-radius: 2px; background: var(--c); }
    .even-k { display: flex; flex-wrap: wrap; gap: 4px 18px; padding-bottom: 6px; font-size: 12px; color: var(--text2); } .even-k span { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; } .even-k b { color: var(--text); }
    .k-v small { font: 500 13px var(--sans); color: var(--muted); letter-spacing: 0; }
    .chip .x { width: 18px; height: 18px; padding: 0; border: 0; border-radius: 5px; background: none; color: var(--faint); font-size: 15px; line-height: 1; } .chip .x:hover { color: var(--text); background: rgba(255,255,255,.08); }

    /* ---------- is it safe to be open, lot sizes ---------- */
    .safe { display: flex; gap: 14px; align-items: flex-start; color: var(--text2); line-height: 1.5; } .safe b { color: var(--text); } .safe p { margin: 0 0 6px; } .safe p:last-child { margin: 0; }
    .lamp { width: 12px; height: 12px; margin-top: 4px; border-radius: 50%; flex: none; background: var(--good); box-shadow: 0 0 0 4px var(--good-bg); } .lamp.warn { background: var(--warn); box-shadow: 0 0 0 4px var(--warn-bg); }
    .hb-t { display: inline-block; width: 96px; margin-right: 8px; vertical-align: middle; text-align: left; }
    .hb { display: block; height: 8px; min-width: 3px; width: var(--w); border-radius: 0 4px 4px 0; background: var(--s-gold); animation: growx .7s var(--ease) both; transform-origin: left; }

    /* ---------- Torn's own pages: a grey stand-in, our marks on top ---------- */
    .tn { display: grid; grid-template-columns: minmax(0, 1fr) 304px; gap: 14px; align-items: start; min-height: 100%; padding: 14px; border-radius: 12px; background: #191919; border: 1px solid #2b2b2b; color: #ddd; font: 12px/1.4 Arial, Helvetica, sans-serif; animation: rise .46s var(--ease) both; }
    .tn-cap { margin: 0 0 10px; color: #8d8d8d; }
    .tn-t { display: flex; align-items: center; gap: 6px 10px; flex-wrap: wrap; padding: 7px 10px; border-radius: 5px 5px 0 0; background: linear-gradient(180deg, #444, #333); color: #fff; font-weight: bold; white-space: nowrap; }
    .tn-t i { font-style: normal; font-weight: normal; color: #bbb; }
    .tn-b { position: relative; margin-bottom: 12px; padding: 10px; border-radius: 0 0 5px 5px; background: #333; }
    .tn-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(178px, 1fr)); gap: 18px 8px; padding-top: 8px; }
    .tn-c { position: relative; display: flex; flex-direction: column; gap: 3px; padding: 8px; border-radius: 4px; background: #2a2a2a; border: 1px solid #3a3a3a; }
    .tn-c .im { height: 50px; display: grid; place-items: center; } .tn-c .im img { width: 100px; height: 50px; object-fit: contain; }
    .tn-c .nm { font-weight: bold; } .tn-c .pr { color: #9c0; font-weight: bold; } .tn-c .qt { color: #999; }
    .tn-btn { height: 24px; padding: 0 12px; display: inline-grid; place-items: center; border-radius: 3px; background: #555; color: #eee; font-weight: bold; white-space: nowrap; } .tn-c .tn-btn { margin-top: 4px; background: #444; color: #ccc; font-weight: normal; }
    .tn-in { display: inline-flex; align-items: center; height: 24px; min-width: 76px; padding: 0 8px; border-radius: 3px; background: #1b1b1b; border: 1px solid #444; color: #ccc; }
    .tn-ex { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; color: #bbb; white-space: nowrap; }
    .tn-row { display: flex; align-items: center; gap: 10px; min-height: 36px; padding: 5px 10px; border-top: 1px solid #3a3a3a; background: #2a2a2a; white-space: nowrap; } .tn-row:first-child { border-top: 0; } .tn-row { flex-wrap: wrap; row-gap: 4px; }
    .tn-row .it, .tn-th .it { margin: 0; border-bottom: 0; background: none; } .tn-row .q { color: #999; } .tn-row .mk { margin-left: auto; }
    .tn-2 { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; } .tn-2 h5 { margin: 0; padding: 7px 10px; background: #222; color: #ccc; font-size: 12px; border-radius: 4px 4px 0 0; }
    .tn-ths { display: flex; flex-wrap: wrap; gap: 6px; margin: 8px 0 10px; }
    .tn-th { position: relative; display: flex; flex-direction: column; align-items: center; gap: 2px; width: 58px; padding: 6px 0 4px; border-radius: 4px; background: #2a2a2a; border: 1px solid #3a3a3a; color: #bbb; }
    .tn-lr { display: grid; grid-template-columns: 90px 90px 130px 60px minmax(0, 1fr); align-items: center; gap: 10px; min-height: 32px; padding: 4px 10px; border-top: 1px solid #3a3a3a; background: #2a2a2a; white-space: nowrap; } .tn-lr.h { background: #222; color: #999; min-height: 26px; } .tn-lr .mk { justify-self: start; }
    .tn-post { display: grid; grid-template-columns: 110px minmax(0, 1fr); gap: 12px; } .tn-av { padding: 10px; border-radius: 4px; background: #2a2a2a; color: #bbb; text-align: center; } .tn-av span { display: block; width: 60px; height: 60px; margin: 0 auto 6px; border-radius: 4px; background: #222; }
    .mk-ring { box-shadow: inset 0 0 0 2px var(--need); } .mk-ring.top { box-shadow: inset 0 0 0 2px var(--need), 0 0 14px rgba(76,157,255,.45); } .mk-ring.ahead { box-shadow: inset 0 0 0 1px var(--warn); }
    .mk { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 999px; font: 600 12px/1 var(--sans); white-space: nowrap; background: #10233b; color: #cfe5ff; border: 1px solid rgba(76,157,255,.5); box-shadow: 0 2px 8px rgba(0,0,0,.5); }
    .mk b { color: #fff; } .mk.c { position: absolute; top: -11px; right: 6px; z-index: 2; } .mk.b { position: absolute; bottom: -11px; right: 6px; z-index: 2; }
    .mk.ahead { background: #2a2110; color: var(--warn); border-color: rgba(245,165,36,.45); } .mk.grey { background: #23262c; color: #cfd4dc; border-color: rgba(255,255,255,.14); } .mk.good { background: #10261a; color: var(--good); border-color: rgba(63,207,107,.45); }
    .mk.fill { background: var(--brand); color: #fff; border-color: transparent; }
    .ta { position: sticky; top: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--panel); border: 1px solid var(--line2); box-shadow: 0 16px 40px rgba(0,0,0,.5); color: var(--text); font: 13px/1.45 var(--sans); overflow: hidden; }
    .ta-h { display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 8px 0 10px; border-bottom: 1px solid var(--line); background: var(--rail-bg); white-space: nowrap; }
    .ta-h .mark { width: 24px; height: 24px; border-radius: 7px; } .ta-h .mark svg { width: 15px; height: 15px; } .ta-h b { font: 650 13px var(--disp); margin-right: auto; } .ta-h span.w { color: var(--muted); font-size: 12px; }
    .ta-b { display: grid; gap: 8px; padding: 10px 12px 12px; }
    .ta-b h4 { margin: 0; display: flex; align-items: baseline; gap: 8px; font: 650 13px var(--sans); white-space: nowrap; } .ta-b h4 span { margin-left: auto; color: var(--muted); font-weight: 400; font-size: 12px; }
    .ta-l { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 2px 8px; padding: 6px 8px; border-radius: 9px; background: var(--raised); border: 1px solid var(--line); }
    .ta-l .it { margin: 0; } .ta-l b { font-weight: 600; } .ta-l .s { grid-column: 1 / -1; color: var(--muted); font-size: 12px; } .ta-l.dim b { color: var(--muted); font-weight: 500; }
    .ta-kv { display: flex; align-items: baseline; gap: 10px; font-size: 12px; color: var(--muted); } .ta-kv > :last-child { margin-left: auto; color: var(--text); text-align: right; } .ta-kv.sep { padding-top: 8px; border-top: 1px solid var(--line); }
    .ta-n { color: var(--muted); font-size: 12px; line-height: 1.5; } .ta-n b { color: var(--text2); }
    .ta-hold { padding: 8px 10px; border-radius: 9px; background: var(--warn-bg); border: 1px solid rgba(245,165,36,.4); color: var(--text2); font-size: 12px; line-height: 1.5; } .ta-hold b { color: var(--warn); }
    .ta .msg { font-size: 12px; padding: 7px 10px; } .ta-btns { display: flex; gap: 6px; flex-wrap: wrap; }

    /* page grids */
    .g2 { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); } .g2r { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } .g57 { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); } .g11 { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } .g1 { grid-template-columns: minmax(0, 1fr); }
    .p-tabs { grid-template-columns: minmax(0, 1fr); } .p-tabs > .pane { height: 100%; }
    .minc { min-height: 180px; }

    @keyframes rise { from { opacity: 0; transform: translateY(8px); } }
    @keyframes draw { to { stroke-dashoffset: 0; } }
    @keyframes fade { from { opacity: 0; } }
    @keyframes growy { from { transform: scaleY(0); } }
    @keyframes growx { from { transform: scaleX(0); } }
    @keyframes ping { 0% { transform: scale(.6); opacity: .9; } 70%, 100% { transform: scale(1.5); opacity: 0; } }
    @keyframes flash { 0% { background: rgba(245,165,36,.28); border-color: rgba(245,165,36,.6); } }
    @keyframes tape { to { transform: translateX(-50%); } }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } svg .ln.draw { stroke-dashoffset: 0; } }
    `;

    /* ===== src/ui/fmt.js ===== */
    // Words and numbers as the hub and the marks on Torn's pages write them. Pure strings: no page is touched here.

    const H_ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

    /** Anything that came from Torn, TornW3B or a typed box goes through this before it is put in a page. */
    const hEsc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => H_ESC[c]);

    const hNum = (n) => Math.abs(Math.round(Number(n) || 0)).toLocaleString('en-US');
    const hMoney = (n) => (n < 0 ? '-' : '') + '$' + hNum(n);
    const hSigned = (n) => (n < 0 ? '-' : '+') + '$' + hNum(n);
    /** A short money figure for a graph's axis: $1.2M, $340k. */
    const hShort = (v) => (v < 0 ? '-' : '') + '$' + (Math.abs(v) >= 1e6 ? (Math.abs(v) / 1e6).toFixed(1).replace('.0', '') + 'M' : Math.abs(v) >= 1e3 ? Math.round(Math.abs(v) / 1e3) + 'k' : Math.abs(v));
    const hPct = (n) => (Math.round((Number(n) || 0) * 10) / 10).toFixed(1) + '%';
    /** A rate as it is typed: 101, 101.4. */
    const hRate = (n) => String(Math.round((Number(n) || 0) * 10) / 10);
    const hPlural = (n, one, many) => hNum(n) + ' ' + (n === 1 ? one : many || one + 's');

    const H_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const hTwo = (n) => String(n).padStart(2, '0');
    /** Torn's time (UTC): "9 Oct, 21:40". */
    function hWhen(t) {
        if (!(t > 0)) return '';
        const d = new Date(t);
        return d.getUTCDate() + ' ' + H_MONTHS[d.getUTCMonth()] + ', ' + hTwo(d.getUTCHours()) + ':' + hTwo(d.getUTCMinutes());
    }
    /** Torn's time of day (UTC): "21:40". */
    const hClock = (t) => (t > 0 ? hTwo(new Date(t).getUTCHours()) + ':' + hTwo(new Date(t).getUTCMinutes()) : '');
    /** A day as the books keep it ("2026-10-09"), or a time: "9 Oct". */
    function hDay(day) {
        const d = typeof day === 'number' ? new Date(day) : new Date(String(day) + 'T00:00:00Z');
        return Number.isNaN(d.getTime()) ? '' : d.getUTCDate() + ' ' + H_MONTHS[d.getUTCMonth()];
    }
    /** How long ago a read landed: "12 s ago", "3 min ago". */
    function hAge(t, now) {
        if (!(t > 0)) return 'not yet';
        const s = Math.max(0, Math.round((now - t) / 1000));
        if (s < 2) return 'just now';
        if (s < 100) return s + ' s ago';
        if (s < 5400) return Math.round(s / 60) + ' min ago';
        return Math.round(s / 3600) + ' h ago';
    }

    const HUB_ICONS = {
        brand: '<path d="M3 8 10 3.5 17 8H3Z"/><path d="M5 10.5v4.5M8.3 10.5v4.5M11.7 10.5v4.5M15 10.5v4.5M3.5 17h13"/>',
        dash: '<rect x="3" y="3" width="6" height="8" rx="1.5"/><rect x="11" y="3" width="6" height="5" rx="1.5"/><rect x="3" y="13" width="6" height="4" rx="1.5"/><rect x="11" y="10" width="6" height="7" rx="1.5"/>',
        stock: '<path d="M10 3 3 6.5 10 10l7-3.5L10 3Z"/><path d="m3 10 7 3.5 7-3.5"/><path d="m3 13.5 7 3.5 7-3.5"/>',
        buy: '<path d="M2.5 4h2l1.7 8.2h8.3l1.8-5.7H5.4"/><circle cx="7.8" cy="15.6" r="1.2"/><circle cx="13.8" cy="15.6" r="1.2"/>',
        trades: '<path d="M4 7h12l-3-3M16 13H4l3 3"/>',
        points: '<circle cx="10" cy="10" r="6.8"/><path d="M8.4 13.6V6.6h2.3a2 2 0 0 1 0 4H8.4"/>',
        tag: '<path d="M3.5 10.4V4.5a1 1 0 0 1 1-1h5.9l6 6a1 1 0 0 1 0 1.4l-5.1 5.1a1 1 0 0 1-1.4 0l-6.4-5.6Z"/><circle cx="7.2" cy="7.2" r="1.1"/>',
        book: '<path d="M6 3.5h9.5v13H6A1.5 1.5 0 0 1 4.5 15V5A1.5 1.5 0 0 1 6 3.5Z"/><path d="M4.5 14.8A1.5 1.5 0 0 1 6 13.5h9.5M8 7h4.5M8 9.8h3"/>',
        set: '<path d="M4 6h6.5M15.5 6h.5M4 14h.5M9.5 14H16"/><circle cx="13" cy="6" r="2.2"/><circle cx="7" cy="14" r="2.2"/>',
        pin: '<path d="M7 3h6l-.8 5 2.3 2.5v1.5h-9v-1.5L7.8 8 7 3ZM10 12v5"/>',
    };
    const hIcon = (name) => `<svg class="ic" viewBox="0 0 20 20">${HUB_ICONS[name] || ''}</svg>`;

    const H_PIC_SIZE = { lg: 'medium', xl: 'large' };
    /**
     * A piece's picture: Torn's own, loaded from torn.com. Two letters show when it does not load (the page swaps a
     * broken picture for its `data-ab`).
     */
    function hPic(id, name, cls = '', color = '') {
        const ab = String(name || '').replace(/\s+Plushie$/i, '').split(' ').map((w) => w[0] || '').join('').slice(0, 2);
        return `<span class="it ${cls}"${color ? ` style="--c:${color}"` : ''}><img src="https://www.torn.com/images/items/${Number(id) || 0}/${H_PIC_SIZE[cls] || 'small'}.png" alt="" loading="lazy" data-ab="${hEsc(ab)}"></span>`;
    }

    /** A link that opens a Torn page in a new tab. One press, one page. */
    const hOut = (url, html, cls = '', attrs = '') => `<a class="${cls || 'lk'}" href="${hEsc(url)}" target="_blank" rel="noopener"${attrs ? ' ' + attrs : ''}>${html}</a>`;
    const hProfileUrl = (id) => 'https://www.torn.com/profiles.php?XID=' + encodeURIComponent(String(id == null ? '' : id).replace(/\D/g, ''));

    /* ===== src/ui/charts.js ===== */
    // The hub's graphs: a line graph, a column graph and a small line for a table cell. Each draws one SVG into the
    // element it is given, at the element's own size; nothing is loaded. Taken from drawing AB.



    const chCss = (el, v) => getComputedStyle(el.ownerDocument.documentElement).getPropertyValue(v).trim();
    const chClamp = (v, a, b) => Math.max(a, Math.min(b, v));
    // 'var(--s-gold)' -> the colour itself, for a gradient stop (a gradient cannot read a variable everywhere).
    const chColor = (el, c) => (/^var\(/.test(c) ? chCss(el, c.slice(4, -1)) : c);
    let chUid = 0;

    /** Round steps for an axis: [lo, ..., hi] covering the range. */
    function chTicks(lo, hi, n) {
        if (!(hi > lo)) hi = lo + 1;
        const raw = (hi - lo) / n;
        const mag = Math.pow(10, Math.floor(Math.log10(raw)));
        const f = raw / mag;
        const step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * mag;
        const out = [];
        for (let v = Math.floor(lo / step) * step; v < hi + step * 0.999; v += step) out.push(Math.round(v * 1e6) / 1e6);
        return out;
    }

    const chPick = (n, k) => { k = Math.min(n, Math.max(2, k)); return [...new Set(Array.from({ length: k }, (_, i) => Math.round(i * (n - 1) / (k - 1))))]; };

    function chTip(el) {
        let t = el.querySelector('.tip');
        if (!t) { t = el.ownerDocument.createElement('div'); t.className = 'tip'; el.appendChild(t); }
        return t;
    }
    function chPlaceTip(t, x, y, W) {
        t.classList.add('on');
        const w = t.offsetWidth;
        t.style.left = (x + 14 + w > W ? x - w - 14 : x + 14) + 'px';
        t.style.top = Math.max(0, y - 20) + 'px';
    }
    const chEmpty = (el, words) => { el.innerHTML = `<div class="ch-none">${words}</div>`; };

    /**
     * @param c { x: [label | number], series: [{ name, color, data, area }], refs: [{ y, name }], band: { lo, hi, name, last },
     *            zero, left, right, yfmt, xfmt, tipx, xticks, none }
     * @param anim draw the lines in (on a page's first showing only)
     */
    function lineChart(el, c, anim) {
        const W = el.clientWidth;
        const H = el.clientHeight;
        if (W < 80 || H < 60) return;
        const xs = c.x || [];
        const n = xs.length;
        if (n < 2 || !c.series.length) { chEmpty(el, c.none || 'Fills as the days pass.'); return; }
        const m = { l: c.left || 62, r: c.right == null ? 70 : c.right, t: 12, b: 24 };
        const isNum = typeof xs[0] === 'number';
        const xv = (i) => (isNum ? xs[i] : i);
        const xa = xv(0);
        const xb = xv(n - 1);
        const px = (i) => m.l + (xv(i) - xa) / (xb - xa) * (W - m.l - m.r);
        let lo = Infinity;
        let hi = -Infinity;
        const see = (v) => { if (v < lo) lo = v; if (v > hi) hi = v; };
        c.series.forEach((s) => s.data.forEach(see));
        (c.refs || []).forEach((r) => see(r.y));
        if (c.band) { see(c.band.lo); see(c.band.hi); }
        if (c.zero) see(0);
        const tk = chTicks(lo, hi, Math.max(2, Math.round((H - m.t - m.b) / 48)));
        lo = tk[0];
        hi = tk[tk.length - 1];
        const py = (v) => m.t + (hi - v) / (hi - lo) * (H - m.t - m.b);
        const yf = c.yfmt || hMoney;
        const xf = c.xfmt || ((v) => v);
        const id = 'g' + (++chUid);
        const panel = chCss(el, '--panel');
        let g = '<defs>' + c.series.map((s, k) => (s.area ? `<linearGradient id="${id}-${k}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${chColor(el, s.color)}" stop-opacity=".13"/><stop offset="1" stop-color="${chColor(el, s.color)}" stop-opacity="0"/></linearGradient>` : '')).join('') + '</defs>';
        tk.forEach((t) => { g += `<line class="g" x1="${m.l}" x2="${W - m.r}" y1="${py(t)}" y2="${py(t)}"/><text class="ax" x="${m.l - 8}" y="${py(t) + 4}" text-anchor="end">${yf(t)}</text>`; });
        const ix = c.xticks ? c.xticks.map((v) => xs.indexOf(v)).filter((i) => i >= 0) : chPick(n, Math.floor((W - m.l - m.r) / 88));
        ix.forEach((i) => { g += `<text class="ax" x="${px(i)}" y="${H - 5}" text-anchor="${i === 0 ? 'start' : 'middle'}">${xf(xs[i])}</text>`; });
        if (c.band) {
            const b0 = px(Math.max(0, n - (c.band.last || n)));
            g += `<rect class="${anim ? 'fade' : ''}" x="${b0}" y="${py(c.band.hi)}" width="${px(n - 1) - b0}" height="${py(c.band.lo) - py(c.band.hi)}" fill="rgba(255,255,255,.055)" rx="3"/><text class="rl" x="${b0 + 8}" y="${py(c.band.hi) - 7}">${c.band.name}</text>`;
        }
        (c.refs || []).forEach((r) => { g += `<line x1="${m.l}" x2="${W - m.r}" y1="${py(r.y)}" y2="${py(r.y)}" stroke="${chCss(el, '--muted')}" stroke-dasharray="4 4"/><text class="rl" x="${m.l + 8}" y="${py(r.y) - 6}">${r.name}</text>`; });
        const ends = [];
        c.series.forEach((s, k) => {
            const d = s.data.map((v, i) => (i ? 'L' : 'M') + px(i).toFixed(1) + ' ' + py(v).toFixed(1)).join('');
            if (s.area) g += `<path class="${anim ? 'fade' : ''}" d="${d}L${px(n - 1)} ${py(lo)}L${px(0)} ${py(lo)}Z" fill="url(#${id}-${k})"/>`;
            g += `<path class="ln ${anim ? 'draw' : ''}" pathLength="1" d="${d}" stroke="${s.color}"/>`;
            g += `<circle class="${anim ? 'fade' : ''}" cx="${px(n - 1)}" cy="${py(s.data[n - 1])}" r="4" fill="${s.color}" stroke="${panel}" stroke-width="2"/>`;
            ends.push({ y: py(s.data[n - 1]), t: yf(s.data[n - 1]) });
        });
        if (m.r >= 60) {
            ends.sort((a, b) => a.y - b.y);
            for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 15) ends[i].y = ends[i - 1].y + 15;
            ends.forEach((e) => { g += `<text class="lb ${anim ? 'fade' : ''}" x="${px(n - 1) + 9}" y="${e.y + 4}">${e.t}</text>`; });
        }
        g += `<line class="cross" y1="${m.t}" y2="${H - m.b}" visibility="hidden"/>` + c.series.map((s) => `<circle class="hd" r="4.5" fill="${s.color}" stroke="${panel}" stroke-width="2" visibility="hidden"/>`).join('');
        el.innerHTML = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${g}<rect x="${m.l}" y="${m.t}" width="${W - m.l - m.r}" height="${H - m.t - m.b}" fill="transparent"/></svg>`;
        const svg = el.querySelector('svg');
        const cross = svg.querySelector('.cross');
        const hd = [...svg.querySelectorAll('.hd')];
        const tip = chTip(el);
        svg.onmousemove = (e) => {
            const bx = svg.getBoundingClientRect();
            const mx = (e.clientX - bx.left) * W / bx.width;
            let i = 0;
            let best = 1e9;
            for (let j = 0; j < n; j++) { const dd = Math.abs(px(j) - mx); if (dd < best) { best = dd; i = j; } }
            cross.setAttribute('x1', px(i));
            cross.setAttribute('x2', px(i));
            cross.setAttribute('visibility', 'visible');
            hd.forEach((h, k) => { h.setAttribute('cx', px(i)); h.setAttribute('cy', py(c.series[k].data[i])); h.setAttribute('visibility', 'visible'); });
            tip.innerHTML = `<h4>${(c.tipx || xf)(xs[i])}</h4>` + c.series.map((s) => `<div><i class="key" style="--c:${s.color}"></i>${s.name}<b>${yf(s.data[i])}</b></div>`).join('');
            chPlaceTip(tip, px(i) * bx.width / W, e.clientY - bx.top, bx.width);
        };
        svg.onmouseleave = () => { cross.setAttribute('visibility', 'hidden'); hd.forEach((h) => h.setAttribute('visibility', 'hidden')); tip.classList.remove('on'); };
    }

    /** Stacked columns. A negative value hangs under the line in red. @param c { x, series, left, yfmt, posneg, none } */
    function colChart(el, c, anim) {
        const W = el.clientWidth;
        const H = el.clientHeight;
        if (W < 80 || H < 60) return;
        const n = (c.x || []).length;
        if (!n || !c.series.some((s) => s.data.some((v) => v))) { chEmpty(el, c.none || 'Nothing yet.'); return; }
        const m = { l: c.left || 62, r: 10, t: 12, b: 24 };
        const yf = c.yfmt || hMoney;
        const tot = c.x.map((_, i) => c.series.reduce((a, s) => a + s.data[i], 0));
        const up = c.x.map((_, i) => c.series.reduce((a, s) => a + Math.max(0, s.data[i]), 0));
        const dn = c.x.map((_, i) => c.series.reduce((a, s) => a + Math.min(0, s.data[i]), 0));
        const tk = chTicks(Math.min(0, ...dn), Math.max(...up), Math.max(2, Math.round((H - m.t - m.b) / 48)));
        const lo = tk[0];
        const hi = tk[tk.length - 1];
        const py = (v) => m.t + (hi - v) / (hi - lo) * (H - m.t - m.b);
        const band = (W - m.l - m.r) / n;
        const bw = Math.min(24, band * 0.62);
        const cx = (i) => m.l + band * (i + 0.5);
        const bad = chCss(el, '--bad');
        const good = chCss(el, '--good');
        let g = '';
        tk.forEach((t) => { g += `<line class="g" x1="${m.l}" x2="${W - m.r}" y1="${py(t)}" y2="${py(t)}" ${t === 0 ? `style="stroke:${chCss(el, '--axis')}"` : ''}/><text class="ax" x="${m.l - 8}" y="${py(t) + 4}" text-anchor="end">${yf(t)}</text>`; });
        chPick(n, Math.floor((W - m.l - m.r) / 80)).forEach((i) => { g += `<text class="ax" x="${cx(i)}" y="${H - 5}" text-anchor="middle">${c.x[i]}</text>`; });
        const cap = (x, y, w, h, top) => {
            const r = Math.min(4, w / 2, h);
            return top ? `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z` : `M${x},${y}V${y + h - r}Q${x},${y + h} ${x + r},${y + h}H${x + w - r}Q${x + w},${y + h} ${x + w},${y + h - r}V${y}Z`;
        };
        for (let i = 0; i < n; i++) {
            let acc = 0;
            const live = c.series.filter((s) => s.data[i] > 0);
            const dl = `style="animation-delay:${i * 28 + 80}ms"`;
            c.series.forEach((s) => {
                const v = s.data[i];
                if (!v) return;
                const last = s === live[live.length - 1];
                if (v < 0) { g += `<path class="bar neg ${anim ? 'growy' : ''}" ${dl} d="${cap(cx(i) - bw / 2, py(0), bw, py(v) - py(0), false)}" fill="${bad}"/>`; return; }
                const y1 = py(acc + v);
                const h = py(acc) - y1 - (acc ? 2 : 0);
                acc += v;
                g += last ? `<path class="bar ${anim ? 'growy' : ''}" ${dl} d="${cap(cx(i) - bw / 2, y1, bw, Math.max(1, h), true)}" fill="${c.posneg ? good : s.color}"/>` : `<rect class="bar ${anim ? 'growy' : ''}" ${dl} x="${cx(i) - bw / 2}" y="${y1}" width="${bw}" height="${Math.max(1, h)}" fill="${s.color}"/>`;
            });
        }
        g += `<rect class="hb" y="${m.t}" width="${band}" height="${H - m.t - m.b}" fill="rgba(255,255,255,.04)" rx="4" visibility="hidden"/>`;
        el.innerHTML = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${g}<rect x="${m.l}" y="${m.t}" width="${W - m.l - m.r}" height="${H - m.t - m.b}" fill="transparent"/></svg>`;
        const svg = el.querySelector('svg');
        const hb = svg.querySelector('.hb');
        const tip = chTip(el);
        svg.onmousemove = (e) => {
            const bx = svg.getBoundingClientRect();
            const mx = (e.clientX - bx.left) * W / bx.width;
            const i = chClamp(Math.floor((mx - m.l) / band), 0, n - 1);
            hb.setAttribute('x', m.l + band * i);
            hb.setAttribute('visibility', 'visible');
            tip.innerHTML = `<h4>${c.x[i]}</h4>` + c.series.map((s) => `<div>${c.series.length > 1 ? `<i class="key box" style="--c:${s.color}"></i>` : ''}${s.name}<b>${yf(s.data[i])}</b></div>`).join('') + (c.series.length > 1 ? `<div>Together<b>${yf(tot[i])}</b></div>` : '');
            chPlaceTip(tip, cx(i) * bx.width / W, e.clientY - bx.top, bx.width);
        };
        svg.onmouseleave = () => { hb.setAttribute('visibility', 'hidden'); tip.classList.remove('on'); };
    }

    /** A small line for a table cell or a panel's head, as a string. Nothing when there are fewer than two points. */
    function sparkSvg(data, color, w = 70, h = 26) {
        if (!data || data.length < 2) return '';
        const hi = Math.max(...data);
        const a = Math.min(...data);
        const y = (v) => h - 2 - (v - a) / (hi - a || 1) * (h - 4);
        return `<svg width="${w}" height="${h}"><polyline fill="none" stroke="${color}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round" points="${data.map((v, i) => (i * (w - 4) / (data.length - 1) + 2).toFixed(1) + ',' + y(v).toFixed(1)).join(' ')}"/></svg>`;
    }

    /* ===== src/ui/hub-pages.js ===== */
    // The hub's pages, as strings, from the view. Nothing here reads the page or stores anything: a page is a function
    // of (what the engine holds, what you have pressed on the hub). The shell puts the string in and patches what changed.
    // Every part that can change carries data-k: the shell swaps only the parts whose string differs.
    // A press is a data-act (with data-v, data-id); a page to go to is data-go (with data-pane).
















    const HUB_PAGES = [
        { key: 'dashboard', title: 'Dashboard', icon: 'dash', group: 'Desk' },
        { key: 'stock', title: 'Stock', icon: 'stock' },
        { key: 'buy', title: 'Buy', icon: 'buy' },
        { key: 'trades', title: 'Trades', icon: 'trades' },
        { key: 'points', title: 'Points', icon: 'points' },
        { key: 'prices', title: 'My prices', icon: 'tag', group: 'Shop' },
        { key: 'ledger', title: 'Ledger', icon: 'book', group: 'Books' },
        { key: 'settings', title: 'Settings', icon: 'set', last: true },
    ];

    /** A page's tabs, as the top bar names them. */
    function hubTabs(page, d) {
        const v = d.view;
        if (page === 'buy') return ['Pieces I need', `All ${v.pieces.length} pieces`, v.buy.units ? `Shopping list · ${hNum(v.buy.units)}` : 'Shopping list'];
        if (page === 'points') return ['Market', 'Points book'];
        if (page === 'ledger') return ['Profit', 'Points sold', 'Buys', 'Receipts', 'Sellers', 'Mugged', 'Pieces sold'];
        if (page === 'settings') return ['Keys and API use', 'Sets, points and notifications'];
        return [];
    }

    const pgIco = (p, cls) => hPic(p.id, p.name, cls, (SET_LOOK[p.set] || {}).color || '');
    const pgItem = (v, id, name, cls) => { const p = viewPiece(v, id); return p ? pgIco(p, cls) : hPic(id, name, cls); };
    const pgLow = (s) => String(s || '').toLowerCase();
    const pgKey = (label, color, box) => `<span><i class="key${box ? ' box' : ''}" style="--c:${color}"></i>${label}</span>`;
    const pgSetKeys = (v, box) => v.sets.map((s) => pgKey(s.label, s.color, box)).join('');
    const pgNone = (words) => `<div class="wl-s" style="padding-top:9px">${words}</div>`;
    const pgPlace = (s) => (s.im ? 'the Item Market' : hEsc(s.who || 'a bazaar') + "'s bazaar");
    const pgStopUrl = (s) => (s.im ? itemMarketUrl(s.lines[0].id, s.lines[0].name) : bazaarUrl(s.whoId, s.lines[0].id, s.lines[0].price));
    const pgSeg = (key, value, choices) => `<span class="seg">${choices.map(([v, label]) => `<button data-act="set" data-id="${key}" data-v="${hEsc(v)}"${String(v) === String(value) ? ' class="on"' : ''}>${label}</button>`).join('')}</span>`;
    const pgInput = (key, value, width = 64, after = '') => `<input class="inp" data-set="${key}" value="${hEsc(value)}" inputmode="decimal" autocomplete="off" style="width:${width}px">${after ? `<span class="t-muted">${after}</span>` : ''}`;
    // The two points prices a listing is judged at (view.buy.usual): Buy pays at the lower of today's price and the one
    // you usually sell for, a Stretch only at the higher.
    const pgUsualFor = (u) => (u.from === 'sales' ? 'you usually sell points for' : 'points usually sell for');
    const pgLowPrice = (u) => (u.by === 'usual' ? `the ${hMoney(u.low)} ${pgUsualFor(u)}` : `today's ${hMoney(u.low)} a point`);
    const pgHighPrice = (u) => (u.by === 'usual' ? `today's ${hMoney(u.high)} a point` : `the ${hMoney(u.high)} ${pgUsualFor(u)}`);
    /**
     * What you hold of a piece against what you build, in the owner's three colours (2026-10-11: "red for we have too
     * much, orange we still need more, and green we have enough exactly"): 'need', 'even' or 'over'.
     */
    const pgStockCls = (p) => (p.state === 'need' ? 'need' : p.state === 'ahead' ? 'over' : 'even');

    // ---- Dashboard ---------------------------------------------------------------------------------------------------

    function pgLadder(v, n) {
        const rows = v.points.ladder.slice(0, n);
        if (!rows.length) return pgNone('The points market has not been read yet.');
        const max = Math.max(...rows.map((r) => r.qty));
        let you = v.points.price > 0;
        let out = '<div class="lad h"><span>Price</span><span></span><span class="r">Points</span><span class="r">Sell before it</span></div>';
        rows.forEach((r, i) => {
            if (you && r.price > v.points.price) {
                out += `<div class="lad you"><span class="p num">${hMoney(v.points.price)}</span><span><b>Your price</b> · ${hNum(v.points.ahead)} points sell first</span></div>`;
                you = false;
            }
            out += `<div class="lad ${r.wall ? 'wall' : ''}" style="--n:${i}"><span class="p num">${hMoney(r.price)}</span><span><i class="bar" style="--w:${Math.max(2, r.qty / max * 100)}%;display:block"></i></span><span class="r num">${hNum(r.qty)}</span><span class="r num tag">${r.wall ? 'first wall' : hNum(r.ahead)}</span></div>`;
        });
        return out;
    }

    const PG_SHOP_LINE = {
        'no-price': () => 'waiting for prices',
        low: (c) => `a set leaves ${hSigned(c.leaves.profit)}: under your least profit`,
        full: () => 'nothing needed',
        share: () => 'your share for sets is full',
        'buy-first': (c) => `buy ${hPlural(c.cheaper.units, 'piece')} first`,
        'open-now': (c) => `worth opening: a set leaves <b>${hSigned(c.leaves.profit)}</b>`,
        stay: (c) => `worth it: a set leaves <b>${hSigned(c.leaves.profit)}</b>`,
        'stay-buy': (c) => `buy the ${hPlural(c.cheaper.units, 'cheap piece')} first`,
    };

    function pgTodo(v, t) {
        const row = (style, icon, text, btn) => `<div class="nx"${style ? ` style="${style}"` : ''}>${icon}<span class="nx-t">${text}</span>${btn}</div>`;
        const tone = { warn: '--c:var(--warn);--c-bg:var(--warn-bg)', brand: '--c:var(--brand);--c-bg:var(--brand-bg)', good: '--c:var(--good);--c-bg:var(--good-bg)' };
        const ic = (name) => `<span class="nx-i">${hIcon(name)}</span>`;
        const pic = (id) => `<span class="nx-p">${pgItem(v, id, '')}</span>`;
        if (t.kind === 'trades') return row(tone.warn, ic('trades'), `<b>${hPlural(t.n, 'trade')} open with you.</b> ${t.wait ? `${t.wait} ${t.wait === 1 ? 'waits' : 'wait'} for your money: ${hMoney(t.money)}.` : 'None waits for you.'}`, '<button class="btn sm go" data-go="trades">See them</button>');
        if (t.kind === 'hot') return row('', pic(t.pic), `<b>Buy ${hPlural(t.n, 'piece')}.</b> Cheaper than from your sellers, ${hPlural(t.stops, 'stop')}.`, '<button class="btn sm" data-act="make-list" data-v="hot">The list</button>');
        if (t.kind === 'buy') return row('', pic(t.pic), `<b>Buy ${hPlural(t.n, 'piece')}.</b> Under their worth, ${hPlural(t.stops, 'stop')}.`, '<button class="btn sm" data-act="make-list">The list</button>');
        if (t.kind === 'swap') return row(tone.brand, ic('brand'), `<b>Swap ${hPlural(t.n, 'set')}.</b> ${hNum(t.points)} points.`, hOut(MUSEUM_URL, 'Museum', 'btn sm out'));
        if (t.kind === 'hold') return row(tone.warn, ic('points'), `<b>Hold your points.</b> Under the usual ${hMoney(t.usual)}.`, '<button class="btn sm" data-go="points">Points</button>');
        if (t.loss) return row(tone.warn, ic('points'), `<b>Your ${hNum(t.n)} points would sell at a loss.</b> They cost you ${hMoney(t.each)} each, the market pays ${hMoney(t.price)}.`, '<button class="btn sm" data-go="points">Points</button>');
        return row(tone.good, ic('points'), `<b>Sell ${hNum(t.n)} points.</b> At ${hMoney(t.price)}.`, '<button class="btn sm" data-go="points">Points</button>');
    }

    /** Up to this many things to do get their own lines under them; more than that and each is one line. */
    const PG_TODO_ROOMY = 2;
    const PG_TODO_LINES = 12;

    /** The lines under a thing to do, drawn when the card has room for them: where it starts, or what it comes to. */
    function pgTodoMore(v, t) {
        const line = (a, b, c) => `<div class="nm"><span class="nm-a">${a}</span><span class="nm-b num">${b}</span><span class="nm-c num">${c}</span></div>`;
        const head = (a, b, c) => `<div class="nm h"><span class="nm-a">${a}</span><span class="nm-b">${b}</span><span class="nm-c">${c}</span></div>`;
        if (t.kind === 'trades') return head('Open with you', 'Pieces', 'You pay') + v.trades.open.slice(0, PG_TODO_LINES).map((o) => line(`<b>${hEsc(o.who)}</b> · ${TURN_WORDS[o.state]}`, hNum(o.units), o.total ? hMoney(o.total) : '')).join('');
        // A list's stop may hold pieces bought over their own share, on the room of their set (1.3.0, setjudge.js): in
        // sum it is then not under its pieces' worth, and says so - never a minus in green. (Short: the column is 124px.)
        const under = (s) => (s.gain < 0 ? `<span class="t-muted" title="These pieces are over their own share of the set by this much: the set carries it - it still pays at today's points price, with your least profit">${hMoney(-s.gain)} over</span>` : `<span class="t-good">${hSigned(s.gain)}</span>`);
        if (t.kind === 'hot' || t.kind === 'buy') return head(t.kind === 'hot' ? 'Where' : 'The first stops', 'Pieces', t.kind === 'hot' ? 'Under your sellers' : 'Under their worth') + (t.first || []).map((s) => line(`<b>${s.im ? 'Item Market' : hEsc(s.who || 'Bazaar ' + (s.whoId ?? ''))}</b>`, hNum(s.units), under(s))).join('');
        if (t.kind === 'swap') return head('Full sets', 'Sets', 'Points') + v.sets.filter((s) => s.full).map((s) => line(`<b>${hEsc(s.label)} Set</b>`, hNum(s.full), hNum(s.full * s.points))).join('');
        if (t.kind === 'hold') return '';
        const sell = v.points.sell;
        return head('At this price', '', '') + line('You get', '', hMoney(sell.lands)) + line('Over what they cost you', '', `<span class="${sell.profit >= 0 ? 't-good' : 't-warn'}">${hSigned(sell.profit)}</span>`);
    }

    function pgTodoList(v) {
        const todo = v.dash.todo;
        // Under the lines of a buy: what it costs and what it makes of your sets.
        const foot = (t) => (t.full ? `<div class="nx-f"><span>Costs <b class="num">${hMoney(t.cost)}</b></span><span>Full sets after: ${pgFullWords(v, t.full)}</span></div>` : '');
        if (!todo.length) return `<div class="next"><div class="nx"><span class="nx-t">${v.ready ? 'Nothing to do now.' : 'Waiting for the first read.'}</span></div></div>`;
        // Many things to do: one line each, spread over the card. A few: each from the top, with its own lines under it.
        if (todo.length > PG_TODO_ROOMY) return `<div class="next">${todo.map((t) => pgTodo(v, t)).join('')}</div>`;
        return `<div class="next few n${todo.length}">${todo.map((t) => { const more = pgTodoMore(v, t); return `<div class="nx-g${more ? '' : ' bare'}">${pgTodo(v, t)}${more ? `<div class="nx-m">${more}</div>${foot(t)}` : ''}</div>`; }).join('')}</div>`;
    }

    function pgSky(v) {
        return v.sets.map((s) => {
            const max = Math.max(...s.pieces.map((p) => p.held), s.target, 1) * 1.08;
            const first = s.pieces[0];
            return `<div class="sky"><div class="sky-h"><b>${s.label} Set</b>${s.full} full</div><div class="sky-b">${s.pieces.map((p, i) => `<i class="sky-c ${pgStockCls(p)}" style="--h:${p.held / max * 100}%;--n:${i}" title="${hEsc(p.name)}: ${p.held}${p.need ? ', need ' + p.need : p.ahead ? ', ' + p.ahead + ' ahead' : ', enough'}"></i>`).join('')}<div class="sky-l" style="--at:${s.target / max * 100}%"><span>${s.target}</span></div></div><div class="sky-f">Shortest: <b>${hEsc(first.short)} ${first.held}</b></div></div>`;
        }).join('');
    }

    /** Beside Torn Trading: which of the two asks more now, in one line. Alone: nothing. */
    const PG_TURNS = {
        front: 'you look at Torn Archive: Torn Trading asks less',
        'trading-in-view': 'you look at Torn Trading: Torn Archive asks less',
        'no-answer': 'Torn Trading is on and has not made room: Torn Archive asks less',
        ramp: 'you look at Torn Archive: it asks more in a minute',
    };
    const pgTurns = (t) => { const line = t && t.mode !== 'alone' ? PG_TURNS[t.mode === 'front' ? 'front' : t.why] : ''; return line ? ` · <span class="t-warn">${line}</span>` : ''; };

    function pgDashboard(d, ui) {
        const v = d.view;
        const pays = v.dash.pays;
        const paysLine = (p) => (p.pays == null ? (p.priced === false ? 'reading' : 'no price') : hSigned(p.pays));
        const seg = (name) => `<div class="seg">${[7, 30, 40].map((n) => `<button data-act="range" data-id="${name}" data-v="${n}"${ui.range[name] === n ? ' class="on"' : ''}>${n} days</button>`).join('')}</div>`;
        return `<section class="page p-dash on">
        <div class="kpis" data-k="kpis">
          <div class="panel kpi"><div class="k-l">Full sets ready</div><div class="k-v">${hNum(v.dash.full)}</div><div class="k-s">${v.sets.map((s) => `<b>${s.full}</b> ${pgLow(s.label)}`).join(' · ')}</div></div>
          <div class="panel kpi"><div class="k-l">A set pays now</div><div class="k-v ${pays[0] && pays[0].pays > 0 ? 'good' : ''}">${pays[0] ? paysLine(pays[0]) : 'no set'}</div><div class="k-s">${pays[0] ? pgLow(pays[0].label) : ''}${pays[1] ? ` · ${pgLow(pays[1].label)} <b>${paysLine(pays[1])}</b>` : ''}</div></div>
          <div class="panel kpi"><div class="k-l">Points held</div><div class="k-v">${v.dash.pointsHeld == null ? 'not read' : hNum(v.dash.pointsHeld)}</div><div class="k-s"><b>${hNum(v.dash.made)}</b> made from sets</div></div>
          <div class="panel kpi"><div class="k-l">Profit, 7 days</div><div class="k-v ${v.dash.profit7 >= 0 ? 'good' : ''}"${v.dash.profit7 < 0 ? ' style="color:#ff8a87"' : ''}>${hSigned(v.dash.profit7)}</div><div class="k-s">today <b>${hSigned(v.dash.today)}</b></div></div>
          <div class="panel kpi"><div class="k-l">Your shop</div><div class="k-v ${v.shop.open ? 'good' : ''}">${v.shop.open ? 'Open' : 'Closed'}</div><div class="k-s">${PG_SHOP_LINE[v.shop.state](v.prices.verdict.checks)}</div></div>
        </div>
        <div class="panel s8" data-k="pts">
          <div class="ph"><h2>Points price</h2><div class="legend">${pgKey('First wall', 'var(--s-gold)')}${pgKey('Lowest listing', 'var(--s-violet)')}</div><span class="sp"></span>${seg('pts')}</div>
          <div class="pb"><div class="chart" data-chart="pts"></div></div>
        </div>
        <div class="panel s4 tint" data-k="todo">
          <div class="ph"><h2>Do now</h2></div>
          <div class="pb todo">${pgTodoList(v)}</div>
        </div>
        <div class="panel s4" data-k="margin">
          <div class="ph"><h2>What a set pays</h2><div class="legend">${pgSetKeys(v)}</div></div>
          <div class="pb"><div class="chart" data-chart="margin"></div></div>
        </div>
        <div class="panel s4" data-k="sky">
          <div class="ph"><h2>Stock</h2><div class="legend">${pgKey('Need', 'var(--st-need)', 1)}${pgKey('Enough', 'var(--st-even)', 1)}${pgKey('Ahead', 'var(--st-over)', 1)}</div><span class="sp"></span><button class="btn sm" data-go="stock">Stock</button></div>
          <div class="pb"><div class="sky2"${v.sets.length === 1 ? ' style="grid-template-columns:1fr"' : ''}>${pgSky(v)}</div></div>
        </div>
        <div class="panel s4" data-k="ladder">
          <div class="ph"><h2>Points market now</h2><span class="sub">lowest first</span><span class="sp"></span><button class="btn sm" data-go="points">Points</button></div>
          <div class="pb flush"><div class="ladder">${pgLadder(v, 6)}</div></div>
        </div>
      </section>`;
    }

    // ---- Stock -------------------------------------------------------------------------------------------------------

    function pgStockSet(v, s) {
        const tiles = s.pieces.map((p, i) => {
            const low = p.low;
            const gap = low ? p.worth - low.price : 0;
            // Every tile always shows the three lines (1.3.0): what a tile shows no longer depends on its size. Until
            // then they were hidden on a tile under 136 x 158 px, so they came and went with the window.
            return `<div class="pc ${pgStockCls(p)} ${i === 0 && p.need ? 'first' : ''}" style="--n:${i}" data-act="pick" data-id="${p.id}" title="Where to buy ${hEsc(p.name)}"><div class="pc-in"><div class="pc-h">${pgIco(p, 'xl')}<span class="pc-s">${p.need ? 'need ' + p.need : p.ahead ? p.ahead + ' ahead' : 'enough'}</span></div><div class="pc-n">${hEsc(p.short)}</div><div class="pc-q"><b class="num">${p.held}</b>of ${p.target}</div>
          <div class="pc-x"><div class="pc-k"><span><span class="w">Cheapest now</span><span class="n">Cheapest</span></span><b class="num ${low && low.price < p.pay ? 't-brand' : ''}">${low ? hMoney(low.price) : 'none'}</b></div><div class="pc-k"><span><span class="w">Worth to you</span><span class="n">Worth</span></span><b class="num">${hMoney(p.worth)}</b></div><div class="pc-k"><span><span class="w">${!low || gap > 0 ? 'Under its worth' : 'Over its worth'}</span><span class="n">${!low || gap > 0 ? 'Under worth' : 'Over worth'}</span></span><b class="num ${low && gap > 0 ? 't-good' : 't-muted'}">${!low ? 'no listing' : gap > 0 ? hSigned(gap) : hMoney(-gap)}</b></div></div>
          <div class="pc-bar"><i style="--w:${Math.min(100, p.target ? p.held / p.target * 100 : 0)}%"></i></div></div></div>`;
        }).join('');
        const act = `<div class="pc act"><div class="pc-in"><span><b class="pc-big num">${s.full}</b><b style="color:var(--text)">full ${s.full === 1 ? 'set' : 'sets'}</b> · ${hNum(s.full * s.points)} points</span>${hOut(MUSEUM_URL, 'Museum', 'btn sm go out')}</div></div>`;
        // As many across as fit, never more than half the tiles (two rows on a wide window); a tile is never smaller
        // than what it shows, and a window too short scrolls the page (hub-css.js .pgrid).
        return `<div class="panel grow setp" data-k="set-${s.key}"><div class="ph"><h2>${hEsc(s.name)}</h2><span class="sub"><b>${s.full}</b> full · building <b>${s.target}</b> · <b>${hMoney(s.cost)}</b> a set${s.costKnown ? '' : ' at your rate'}</span></div>
            <div class="pb"><div class="pgrid" style="--cols:${Math.ceil((s.pieces.length + 1) / 2)}">${tiles}${act}</div></div></div>`;
    }

    function pgStock(d) {
        const v = d.view;
        return `<section class="page g2 p-stock on">
        <div class="col">${v.sets.map((s) => pgStockSet(v, s)).join('')}</div>
        <div class="col">
          <div class="panel" data-k="flow"><div class="ph"><h2>From pieces to money</h2><span class="sp"></span><button class="btn sm" data-act="read-stock" title="Your items and your log are asked of Torn now, ahead of everything else. Nothing else is read.">Read my stock</button></div><div class="pb"><div class="flow">
            <div class="fl"><div class="k-l">Pieces held</div><div class="k-v">${hNum(v.stock.units)}</div><div class="k-s">${v.stock.est ? 'about ' : ''}${hShort(v.stock.cost)} paid</div></div>
            <div class="fl"><div class="k-l">Full sets</div><div class="k-v">${hNum(v.nav.full)}</div></div>
            <div class="fl"><div class="k-l">Points held, made from sets</div><div class="k-v">${hNum(v.stock.made)}</div></div>
            <div class="fl"><div class="k-l">Points sold, 14 days</div><div class="k-v">${hNum(v.stock.sold14)}</div></div>
          </div><div class="wl-s foot" style="margin-top:10px;padding:9px 0 0">${pgStockAge(v)}</div></div></div>
          <div class="panel grow minc" style="min-height:160px" data-k="swapped"><div class="ph"><h2>Sets swapped</h2><div class="legend">${pgSetKeys(v, 1)}</div></div><div class="pb"><div class="chart" data-chart="swapped"></div></div></div>
        </div>
      </section>`;
    }

    // ---- Buy ---------------------------------------------------------------------------------------------------------

    const pgNeedBadge = (p) => (p.need ? `<span class="badge st-need">need ${p.need}</span>` : p.ahead ? `<span class="badge st-over">${p.ahead} ahead</span>` : '<span class="badge st-even">enough</span>');
    /**
     * A listing against its piece, as the SET judges it (core/setjudge.js), in dollars a point of the set: under the
     * piece's own share, or over it and Buy (the set still pays at today's points price with your least profit),
     * Stretch (only at the price you usually sell points for) or No thanks.
     */
    function pgJudged(v, p, price) {
        if (price < p.worth) return `<span class="t-good">${hSigned(p.worth - price)}</span>`;
        const pts = (v.sets.find((s) => s.key === p.set) || {}).points || 0;
        const a = pts ? `${hMoney(Math.ceil((price - p.worth) / pts))} a point` : hMoney(price - p.worth);
        if (price < p.line) return `<span title="Over this piece's own share by ${hMoney(price - p.worth)}. Its set still pays at ${pgLowPrice(v.buy.usual)}, with your least profit">Buy · ${a} over</span>`;
        if (price < p.lineS) return `<span class="t-warn" title="Over this piece's own share by ${hMoney(price - p.worth)}. Its set pays only at ${pgHighPrice(v.buy.usual)}">Stretch · ${a} over</span>`;
        return `<span class="t-muted" title="Over this piece's own share by ${hMoney(price - p.worth)}: its set would not pay even at ${pgHighPrice(v.buy.usual)}">No thanks · ${a} over</span>`;
    }
    const pgFullWords = (v, full) => v.sets.map((s) => `${pgLow(s.label)} <b>${s.full}</b> to <b>${full[s.key]}</b>`).join(' · ');

    /** "Buy from": the places a list may send you to. Both lit until you press one off. */
    const pgFrom = (v) => `<span class="from"><span class="t-muted">Buy from</span><span class="seg"><button data-act="from" data-v="bazaar"${v.buy.from.bazaar ? ' class="on"' : ''}>Bazaars</button><button data-act="from" data-v="market"${v.buy.from.market ? ' class="on"' : ''}>Item Market</button></span></span>`;
    const pgSeller = (p, o) => (o.src === 'market' ? hOut(itemMarketUrl(p.id, p.name), 'Item Market') : hOut(bazaarUrl(o.whoId, p.id, o.price), `<b>${hEsc(o.who || 'Bazaar ' + (o.whoId ?? ''))}</b>`));

    function pgWhere(v, p, lines) {
        if (!p) return '';
        const hist = sparkSvg(p.hist, 'var(--muted)', 54, 20);
        const under = p.offers.filter((o) => o.ok !== false && !o.out && o.price < p.worth);
        const shown = p.offers.slice(0, 14);
        // Rows of a place you do not buy from ("Buy from") come after the ones you do, with no Add.
        const firstOut = shown.findIndex((o) => o.out && o.ok !== false);
        // Rows not looked at lately come after the checked ones (core/view.js), under a line that says what they are.
        const firstOld = shown.findIndex((o) => o.ok === false);
        // The Item Market is one line for all its rows: each row says its own part of it, cheapest first.
        const imLine = lines.get(lineKey(p.id, IM_PLACE));
        const want = Math.max(0, p.need - p.listed);
        const imPart = imShares(shown.map((o) => (o.src === 'market' ? o : { price: 0, qty: 0 })), p.lineS, imLine ? imLine.q : want);
        const rows = shown.map((o, k) => {
            const im = o.src === 'market';
            const key = lineKey(p.id, placeOf(o));
            const on = im ? (imLine && imPart[k] ? { q: imPart[k] } : null) : lines.get(key);
            const q = im ? (imLine ? 0 : imPart[k]) : Math.min(o.qty, want);
            // Add: any listing the set can carry, a Stretch too (it says so on its row). Never a "No thanks".
            const btn = on ? `<button class="btn sm" data-act="cart" data-id="${p.id}" data-v="${hEsc(placeOf(o))}" title="Take it off the list">${on.q} on list ✓</button>` : o.out ? '' : o.price < p.lineS && q ? `<button class="btn sm go" data-act="cart" data-id="${p.id}" data-v="${hEsc(placeOf(o))}">Add ${q}</button>` : '';
            // Torn's own answer, or TornW3B's older copy of that bazaar: said on the row, with its age.
            const how = o.from === 'w3b' ? "TornW3B's copy of this bazaar: Torn itself has not been asked yet" : o.from === 'page' ? 'Seen on its own page, in your Torn tab' : 'Read from Torn itself';
            const age = o.at ? `<span class="n num ${o.ok === false || o.from === 'w3b' ? 't-warn' : 't-muted'}" title="${how}">${o.from === 'w3b' ? 'TornW3B · ' : ''}${hAge(o.at, v.at).replace(' ago', '')}</span>` : '<span></span>';
            const split = k === firstOld ? `<div class="wl-s old-h">Not checked in the last 5 minutes${firstOld ? '' : ': nothing here is'}. These are not counted until Torn has been asked${v.buy.check && v.buy.check.length ? ': it is being asked now' : ''}.</div>` : '';
            const left = k === firstOut ? `<div class="wl-s old-h">${im ? 'The Item Market' : 'Bazaars'}: not where you buy now, so not counted. "Buy from" switches ${im ? 'it' : 'them'} back on.</div>` : '';
            return `${left}${split}<div class="wl ${o.ok === false || o.out ? 'old' : ''} ${o.price < p.pay ? 'cheap' : ''} ${on ? 'on' : ''}"><span>${pgSeller(p, o)}</span><span class="n num">×${hNum(o.qty)}</span><b class="n num">${hMoney(o.price)}</b><span class="n num">${pgJudged(v, p, o.price)}</span>${age}<span class="wl-a">${btn}</span></div>`;
        }).join('');
        const u = p.under.units;
        // What the set carries over the piece's own share: counted with it, as a list counts it.
        const g = Math.max(u, p.good.units);
        // What the shortlist leaves out of the table (core/shortlist.js), said once.
        const L = p.left;
        const cut = p.offers.length - shown.length;
        const out = [L.over ? `${hPlural(L.over, 'listing')} over the line: No thanks` : '', L.more + cut > 0 ? `${hPlural(L.more + cut, 'more listing')} than you can use` : '', L.old ? `${hNum(L.old)} not checked lately` : '', L.out ? `${hNum(L.out)} where you do not buy` : ''].filter(Boolean);
        const foot = (under.length ? `<b>${hNum(u)}</b> under its worth in ${hPlural(p.under.places, 'place')}` : 'Nowhere under its worth now')
            + (g > u ? `, ${hNum(g - u)} more its set carries` : '')
            + (!p.need ? '. You have enough of it.' : !g ? '.' : g >= p.need ? `: covers the ${p.need} you need.` : `. The other ${p.need - g} come from your sellers.`)
            + (p.offers.some((o) => o.price < p.pay) ? ' Violet: cheaper than you pay sellers.' : '')
            + (out.length ? ` Not shown: ${out.join(' · ')}.` : '');
        // One press for the whole piece: everything counted above, cheapest first. With all of it on, the press takes it off.
        const all = p.more ? `<button class="btn sm go" data-act="cart-all" data-id="${p.id}" title="Every listing of it under its worth, cheapest first">Add all ${hNum(p.more)}</button>` : p.listed ? `<button class="btn sm" data-act="cart-all" data-id="${p.id}" title="Take ${hEsc(p.name)} off the list">Take all ${hNum(p.listed)} off</button>` : '';
        // A list of this piece alone (the owner, 2026-10-11: "where is the button that says make list here? so its only
        // kitten plushies for example?"): what "Add all" would put on an empty list, in place of the list on hand.
        const only = p.take;
        const make = only > 0 ? `<button class="btn sm go" data-act="list-only" data-id="${p.id}" title="${hNum(only)} of them, cheapest first, and nothing else: it takes the place of the list you have">Make the list: only ${hEsc(p.name)}</button>` : '';
        return `<div class="ph">${pgIco(p, 'lg')}<h2>${hEsc(p.name)}</h2>${pgNeedBadge(p)}<span class="sp"></span>${make}${hist ? `<span class="sub">7 days</span>${hist}` : ''}</div><div class="pb flush">
        <div class="wl-s">Worth <b>${hMoney(p.worth)}</b> to you · you pay sellers <b>${hMoney(p.pay)}</b>${p.line > p.worth ? ` · its set carries it up to <b>${hMoney(p.line - 1)}</b>` : ''}${p.lineS > p.line ? ` · a Stretch up to <b>${hMoney(p.lineS - 1)}</b>${p.needs ? `: that needs points at ${hMoney(p.needs)}` : ''}` : ''}</div>
        ${p.offers.length ? `<div class="wl h"><span>Sold by</span><span class="n">Stock</span><span class="n">Price</span><span class="n">Against its worth</span><span class="n">Checked</span><span class="wl-a">${all}</span></div>${rows}` : pgNone('Nobody lists it now.')}
        <div class="wl-s foot">${foot}</div></div>`;
    }

    function pgRunBar(v, ui) {
        const run = v.buy.run;
        const S = run.stops;
        if (!S.length) return '';
        const at = S.findIndex((s) => s.state === 'cur');
        if (at >= 0) {
            const next = S[at + 1];
            // The Item Market is one stop with a page for each piece: Next opens the next piece's page (ui.imKey: the
            // line whose page was opened last; none yet = the first, which the press that came here opened).
            if (S[at].im) {
                const lines = S[at].lines;
                const k = Math.max(0, lines.findIndex((l) => l.key === ui.imKey));
                const piece = lines.find((l, j) => j > k && l.q - Math.min(l.q, (run.took && run.took[l.key]) || 0) > 0);
                if (piece) return `<div class="runbar"><span><b>Stop ${at + 1} of ${S.length}:</b> the Item Market, a page for each piece. ${hNum(run.got)} of ${hNum(run.units)} bought so far.</span>${hOut(itemMarketUrl(piece.id, piece.name), `Next: ${hEsc(piece.name)}, its Item Market page<span class="kbd">N</span>`, 'btn go', `data-act="im-walk" data-v="${hEsc(piece.key)}"`)}<button class="btn sm link" data-act="run" data-v="stop">Stop the run</button></div>`;
            }
            const btn = next ? hOut(pgStopUrl(next), `Next: ${pgPlace(next)}<span class="kbd">N</span>`, 'btn go', 'data-act="run" data-v="next"') : '<button class="btn go" data-act="run" data-v="next">Done: back to the list<span class="kbd">N</span></button>';
            return `<div class="runbar"><span><b>Stop ${at + 1} of ${S.length}:</b> ${pgPlace(S[at])}. ${hNum(run.got)} of ${hNum(run.units)} bought so far.</span>${btn}<button class="btn sm link" data-act="run" data-v="stop">Stop the run</button></div>`;
        }
        if (run.began) return `<div class="runbar"><span><b>Run done.</b> ${hNum(run.got)} of ${hNum(run.units)} bought${run.skipped ? `. ${hPlural(run.skipped, 'stop')} skipped: still on the list` : ''}.</span>${hOut(pgStopUrl(S[0]), 'Start again', 'btn sm', 'data-act="run" data-v="start"')}</div>`;
        return `<div class="runbar"><span>One press opens one bazaar, with your pieces marked. <b>Next</b> opens the one after it.</span>${hOut(pgStopUrl(S[0]), `Start: open ${pgPlace(S[0])}`, 'btn go', 'data-act="run" data-v="start"')}</div>`;
    }

    const PG_STOP_WORDS = {
        cur: (s) => 'you are here' + (s.took ? ` · took ${s.took} of ${s.units}` : ''),
        done: (s) => `took ${s.took} of ${s.units} ✓`,
        part: (s) => `took ${s.took} of ${s.units}`,
        skip: () => 'skipped · still on the list',
    };

    /**
     * How fresh your stock count is, said where you are about to buy on it. Torn counts your items once an hour;
     * between its counts yours is carried by what you buy and swap.
     */
    function pgStockAge(v) {
        const st = v.top.stock;
        if (!st || !st.readAt) return 'Your items have not been read from Torn yet.';
        const now = Date.now();
        const from = st.log ? 'your log and the pages you buy on' : 'the pages you buy on';
        const since = st.since ? ` ${hPlural(st.since, 'piece')} changed since: counted from ${from}.` : '';
        const key = st.log ? '' : ` <span class="t-warn">No Full key: a buy made where Torn Archive is not on the page shows only at Torn's next count.</span>`;
        if (st.tornAt) return `<b>Torn counts your items once an hour:</b> last at ${hClock(st.tornAt)} (${hAge(st.tornAt, now)}), again at ${hClock(st.nextAt)}, and it is asked then.${since}${key}`;
        return `Your items were read from Torn ${hAge(st.readAt, now)}. Torn counts them once an hour; what you buy in between is counted from ${from}.${key}`;
    }

    function pgAfterRow(v, p, add, take, extra, i) {
        const max = Math.max(p.target, p.held + add, 1) * 1.04;
        const w = (n) => (n / max * 100).toFixed(1) + '%';
        return `<div class="af" style="--n:${i}"><b>${pgIco(p)}${hEsc(p.name)}</b><span class="af-b"><i style="--w:${w(p.held)}"></i>${take ? `<i class="nd" style="--w:${w(take)}"></i>` : ''}${extra ? `<i class="ah" style="--w:${w(extra)}"></i>` : ''}<u style="--at:${w(p.target)}"></u></span><span class="r num">${p.held} to ${p.held + add} of ${p.target}</span></div>`;
    }

    function pgBuy(d, ui) {
        const v = d.view;
        const lines = new Map(v.buy.stops.flatMap((s) => s.lines).map((l) => [l.key, l]));
        if (ui.pane === 2) {
            const S = v.buy.run.stops;
            const paid = S.reduce((a, s) => a + s.margin.paid, 0);
            const leaves = S.reduce((a, s) => a + s.margin.leaves, 0);
            // A line over its piece's own share says what it is: a Stretch, or dear now (it leaves at the next read).
            const tag = (l) => (l.g === 'stretch' ? '<span class="tg">Stretch</span>' : l.g === 'no' ? '<span class="tg">dear now</span>' : '');
            const list = !S.length ? pgNone('Nothing on the list. Press Add on a listing, or Fill my stock.') : S.map((s, i) => {
                const cls = s.state === 'part' ? 'done' : s.state;
                // A stop judged by itself may be under your least profit while its set carries it (setjudge.js).
                const carried = !s.margin.ok && s.lines.some((l) => l.g === 'room' || l.g === 'stretch');
                return `<div class="stop ${cls}"><span class="stop-n">${s.state === 'done' ? '✓' : i + 1}</span><div class="stop-m"><div class="stop-h">${hOut(pgStopUrl(s), `<b>${s.im ? 'Item Market' : hEsc(s.who || 'A bazaar') + "'s bazaar"}</b>`)}<span class="stop-st">${s.state ? PG_STOP_WORDS[s.state](s) : ''}</span><span class="sp"></span><b class="num">${hMoney(s.cost)}</b><span class="${s.margin.ok ? 't-good' : carried ? 't-muted' : 't-warn'} num">${marginWords(s.margin)}${carried ? ' by itself: its set carries it' : ''}</span></div><div class="chips">${s.lines.map((l) => `<span class="chip">${pgItem(v, l.id, l.name)}<span><b>${hEsc((viewPiece(v, l.id) || {}).short || l.name)}</b> ×${l.q}</span><span class="num t-muted">${hMoney(l.price)}</span>${tag(l)}<button class="x" data-act="drop" data-v="${hEsc(l.key)}" title="Take it off the list">×</button></span>`).join('')}</div></div></div>`;
            }).join('');
            // The list's capital, once, beside what you have on hand (the owner, 2026-10-11: "can it say how much
            // capital i need to buy that list").
            const cash = v.buy.cash;
            const have = cash.onHand == null ? '' : ` <span class="t-muted">· on hand ${hMoney(cash.onHand)}${cash.vault ? ` · vault ${hMoney(cash.vault)}` : ''}</span>`;
            const vault = v.buy.vault == null || !v.buy.units ? '' : v.buy.vault > 0 ? `<span class="grow1 t-warn">Take ${hMoney(v.buy.vault)} out of the vault first. <span class="t-muted">You press Buy yourself.</span></span>` : '<span class="grow1 t-muted">What you have on hand covers it. You press Buy yourself.</span>';
            // What the list does to what a set costs you a point: under that price, selling the points is a loss.
            const even = v.buy.even.filter((e) => e.to > 0).map((e) => `<div class="row"><span class="grow1">Your break-even on a ${pgLow(e.label)} set, a point</span><b class="num" style="font-weight:500">${e.from ? `<b>${hMoney(e.from)}</b> to ` : ''}<b>${hMoney(e.to)}</b></b></div>`).join('');
            const st = v.buy.stretch;
            const stretch = st.units ? `<div class="row"><span class="grow1 t-warn">${hPlural(st.units, 'piece')} on it ${st.units === 1 ? 'is' : 'are'} a Stretch: ${st.units === 1 ? 'it finishes' : 'they finish'} a set that pays only with points at ${hMoney(st.needs)} or more.${v.buy.usual.by === 'usual' ? ` <span class="t-muted">Points are at ${hMoney(v.buy.usual.high)} today; you usually sell at ${hMoney(v.buy.usual.low)}.</span>` : v.buy.usual.price ? ` <span class="t-muted">You usually sell at ${hMoney(v.buy.usual.price)}.</span>` : ''}</span></div>` : '';
            // A buy a Torn page told of that Torn's log does not have: taken back, and said here for a few minutes.
            const back = v.buy.back.map((b) => `<div class="row"><span class="grow1 t-warn"><b>Not a buy after all:</b> ${hNum(b.qty)} × ${hEsc(b.name)} ${b.im ? 'on the Item Market' : 'at ' + hEsc(b.who || 'bazaar ' + b.whoId) + "'s bazaar"}, seen at ${hClock(b.t)}. Torn's log has no such buy, so it is taken back: off your stock, the run and the list.</span></div>`).join('');
            const onList = v.pieces.filter((p) => p.listed);
            return `<section class="page p-buy on"><div class="pane gbuy stk on">
          <div class="panel grow" data-k="list"><div class="ph"><h2>Shopping list</h2><span class="sub">${v.buy.units ? `${hPlural(v.buy.units, 'piece')} · ${hPlural(S.length, 'stop')}` : 'empty'}</span><span class="sp"></span>${pgFrom(v)}<button class="btn sm" data-act="make-list">Fill my stock</button><button class="btn sm" data-act="clear-list">Clear</button></div><div class="pb flush">${list}</div></div>
          <div class="col">
            <div class="panel tint" data-k="run"><div class="ph"><h2>The run</h2><span class="sub">Next counts only what you took</span></div><div class="pb"><div class="rows">${pgRunBar(v, ui)}
              ${back}
              <div class="row"><span class="grow1"><b>This list costs</b>${have}</span><b class="num">${hMoney(v.buy.cost)}</b></div>
              ${vault ? `<div class="row">${vault}</div>` : ''}
              ${paid ? `<div class="row"><span class="grow1">What it leaves</span><span class="num ${leaves < 0 ? 't-warn' : 't-good'}">${hSigned(leaves)} · ${hPct(leaves / paid * 100)}</span></div>` : ''}
              <div class="row"><span class="grow1">Full sets after</span><b class="num" style="font-weight:500">${pgFullWords(v, v.buy.full)}</b></div>
              ${even}${stretch}
              <div class="row"><span class="grow1 t-muted">${pgStockAge(v)}</span></div></div></div></div>
            <div class="panel grow" data-k="list-after"><div class="ph"><h2>Your stock after the list</h2><div class="legend">${pgKey('You hold', '#4a5263', 1)}${pgKey('On the list', 'var(--need)', 1)}</div></div><div class="pb flush"><div class="after">${onList.length ? onList.map((p, i) => pgAfterRow(v, p, p.listed, p.listed, 0, i)).join('') : '<div class="af" style="grid-template-columns:minmax(0,1fr);color:var(--muted)"><span>Nothing on the list.</span></div>'}</div></div></div>
          </div></div></section>`;
        }
        const all = ui.pane === 1;
        const rows = v.pieces.filter((p) => all || p.need).sort((a, b) => (b.target ? b.need / b.target : 0) - (a.target ? a.need / a.target : 0));
        const sel = viewPiece(v, ui.sel) || rows[0] || v.pieces[0] || null;
        // Read by the hub after the draw: the piece whose sellers are shown.
        ui.shown = sel ? String(sel.id) : '';
        const plan = v.buy.plan;
        const table = rows.length ? '<thead><tr><th>Piece</th><th class="n">Need</th><th class="n">Cheapest</th><th>Where</th><th class="n">Against its worth</th><th class="n">On your list</th></tr></thead><tbody>' + rows.map((p) => {
            const low = p.low;
            return `<tr class="pick ${sel && p.id === sel.id ? 'sel' : ''}" data-act="sel" data-id="${p.id}"><td>${pgIco(p)}<b>${hEsc(p.name)}</b></td><td class="n">${p.need ? `<span class="t-stn">${p.need}</span>` : p.ahead ? `<span class="t-sto">${p.ahead} ahead</span>` : '<span class="t-ste">enough</span>'}</td><td class="n">${low ? `<b class="${low.price < p.pay ? 't-brand' : ''}">${hMoney(low.price)}</b> <span class="t-muted">×${hNum(low.qty)}</span>` : `<span class="t-muted">${p.lowAll ? 'none where you buy' : 'none listed'}</span>`}</td><td>${low ? (low.src === 'market' ? 'Item Market' : hEsc(low.who || 'Bazaar ' + (low.whoId ?? ''))) : ''}</td><td class="n">${low ? pgJudged(v, p, low.price) : ''}</td><td class="n">${p.listed ? `<b>${p.listed}</b> <span class="t-muted">of ${p.need}</span>` : '<span class="t-muted">none</span>'}</td></tr>`;
        }).join('') + '</tbody>' : '';
        // The three groups (the owner, 2026-10-11: "yes whole set is how i think about it"): every listing judged on
        // the set it would finish, in dollars a point. Said once here; each row of "Sold by" says its own.
        const grp = v.pieces.reduce((a, p) => ({ buy: a.buy + p.buyUnits, stretch: a.stretch + p.stretchUnits, fin: a.fin + p.fin, no: a.no + p.left.over, needs: Math.max(a.needs, p.needs) }), { buy: 0, stretch: 0, fin: 0, no: 0, needs: 0 });
        const usual = v.buy.usual;
        const spare = v.sets.filter((s) => s.next && s.next.room > 0).map((s) => `the next ${pgLow(s.label)} set has <b>${hMoney(s.next.room)}</b> to spare over its listings, ${hMoney(s.next.perPoint)} a point`).join(' · ');
        const groups = !v.top.points ? '' : `<div class="row"><span class="grow1"><span class="grp"><span><b>Buy ${hNum(grp.buy)}</b>the set still pays at ${pgLowPrice(usual)}, with your least profit</span><span><b class="${grp.stretch ? 't-warn' : ''}">Stretch ${hNum(grp.stretch)}</b>${usual.high > usual.low ? `pays only at ${pgHighPrice(usual)}${grp.fin ? `; ${hNum(grp.fin)} finish a set and go on a list` : ''}` : usual.price ? 'none: points are at what you usually sell for' : 'none: what points usually sell for is not known yet'}</span><span><b>No thanks ${hNum(grp.no)}</b>${grp.no === 1 ? 'listing' : 'listings'} over even that, left out</span></span></span></div>${spare ? `<div class="row"><span class="grow1 t-muted">${spare[0].toUpperCase() + spare.slice(1)}.</span></div>` : ''}`;
        return `<section class="page p-buy on"><div class="pane gbuy stk on">
          <div class="col">
            <div class="panel tint" data-k="rec"><div class="ph"><h2>Fill my stock</h2></div><div class="pb">
              <div class="rec"><div class="hero">${hNum(plan.units)}<small>of the ${hPlural(plan.need, 'piece')} you need ${plan.units === 1 ? 'is' : 'are'} worth buying now</small></div><div class="rec-t"><b>${hPlural(plan.stops, 'stop')}</b> · ${hMoney(plan.cost)}<br>${pgFullWords(v, plan.full)}</div><div class="rec-b">${pgFrom(v)}<button class="btn go" data-act="make-list"${plan.units ? '' : ' disabled'}>Make the list</button></div></div>
              <div class="rows">${groups}<div class="row"><span class="grow1 t-muted">${pgStockAge(v)}</span></div>${v.buy.unsure ? `<div class="row"><span class="grow1 t-muted">${hPlural(v.buy.unsure, 'more piece')} in ${hPlural(v.buy.check.length, 'bazaar')} not checked in the last 5 minutes: not counted until Torn has been asked, which it is being now.</span></div>` : ''}</div>
            </div></div>
            <div class="panel grow" data-k="buy-t"><div class="ph"><h2>Where each piece is cheapest</h2><span class="sub">press a piece to see every place that sells it</span></div>
              <div class="pb flush">${rows.length ? `<table class="t wrapth">${table}</table>` : pgNone('You need nothing: every set is at its target. "All pieces" lists them anyway.')}</div></div>
          </div>
          <div class="col">
            <div class="panel" data-k="where">${pgWhere(v, sel, lines)}</div>
            <div class="panel grow minc" style="min-height:168px" data-k="depth"><div class="ph"><h2>How deep the cheap pieces go</h2><div class="legend">${pgSetKeys(v)}</div></div>
              <div class="pb"><div class="chart" data-chart="depth"></div></div></div>
          </div></div></section>`;
    }

    // ---- Trades ------------------------------------------------------------------------------------------------------

    function pgMargin(t) {
        const m = t.margin;
        const out = [];
        if (m.state === 'ok') out.push(`Everything in it <b class="t-good">${marginWords(m.all)}</b>.`);
        else if (m.state === 'under') out.push(`<b class="t-warn">Everything in it ${marginWords(m.all)}: under your least profit since the points price fell.</b>${m.mend ? ` Paying ${hRate(m.mend)}% would keep it.` : ''}`);
        else if (m.state === 'loss') out.push(`<b class="t-bad">Everything in it ${marginWords(m.all)}: a loss at the points price now.</b>${m.mend ? ` Paying ${hRate(m.mend)}% would keep your least profit.` : ''}`);
        if (m.held > 0 && m.state !== 'none') out.push(`${hMoney(m.held)} of it buys pieces you do not need yet: they pay when the rest of their set arrives.`);
        if (m.others.length) out.push(`<span class="t-warn">${m.others.map(hEsc).join(', ')}: not a set piece, not priced.</span> The total does not cover ${m.others.length === 1 ? 'it' : 'them'}.`);
        // What you pay came down inside its hour (core/sellrate.js safeTable): the seller may have counted on more.
        for (const r of t.rateDown || []) out.push(`<span class="t-warn">Your ${pgLow(r.label)} price came down from ${hRate(r.from)}% to ${hRate(r.to)}% at ${hClock(r.at)} TCT as points fell to ${hMoney(r.price)}.</span>`);
        return out.length ? `<div class="wl-s" style="padding-top:9px;border-top:1px solid var(--line)">${out.join(' ')}</div>` : '';
    }

    function pgTrade(v, t) {
        if (!t) return `<div class="panel grow"><div class="ph"><h2>No trade is open with you</h2></div><div class="pb" style="color:var(--text2)">A new trade shows here within a minute, with your prices on every piece.</div></div>`;
        const forSets = (r) => (r.state === 'other' ? '<span class="t-warn">not a set piece</span>' : r.take === r.qty ? `<span class="t-need">need all ${r.qty}</span>` : r.take ? `<span class="t-need">need ${r.take}</span> <span class="t-muted">· ${r.qty - r.take} ahead</span>` : '<span class="t-muted">not needed</span>');
        const rows = t.rows.map((r) => `<tr><td>${pgItem(v, r.id, r.name)}<b>${hEsc(r.name)}</b></td><td class="n">${hNum(r.qty)}</td><td>${forSets(r)}</td><td class="n">${r.each ? hMoney(r.each) : '<span class="t-muted">not priced</span>'}</td><td class="n">${r.each ? `<b>${hMoney(r.total)}</b>` : ''}</td></tr>`).join('');
        const sum = `<tr class="sum"><td colspan="4">Everything in the trade</td><td class="n">${hMoney(t.total)}</td></tr>${t.needTotal && t.needTotal < t.total ? `<tr><td colspan="4" class="t-muted">Only what you need</td><td class="n t-muted">${hMoney(t.needTotal)}</td></tr>` : ''}`;
        let foot;
        if (t.state === 'you') {
            const owed = t.total - t.myMoney;
            foot = `<div style="padding:8px 14px 6px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center"><div class="msg">${hEsc(t.message)}</div><button class="btn" data-act="copy" data-v="${hEsc(t.message)}">Copy the message</button></div>`
                + (t.vault == null ? '' : t.vault > 0 ? `<div class="wl-s">On hand ${hMoney(v.top.onHand)}: <b class="t-warn">take ${hMoney(t.vault)} out of the vault</b> just before you pay${t.myMoney ? ` the other ${hMoney(owed)}` : ''}. You press Accept.</div>` : `<div class="wl-s">On hand ${hMoney(v.top.onHand)} covers it. You press Accept.</div>`);
        } else {
            foot = `<div class="wl-s" style="padding-top:9px">${t.state === 'them' ? `You paid <b>${hMoney(t.myMoney)}</b>. Nothing to do until ${hEsc(t.who)} accepts.` : `${hEsc(t.who)} is still adding items. Your prices are ready when they stop.`}</div>`;
        }
        const sets = v.sets.filter((s) => t.after.some((r) => (viewPiece(v, r.id) || {}).set === s.key)).map((s) => `${s.label} sets <b>${s.full}</b> to <b>${t.full[s.key]}</b>`).join(' · ');
        const after = t.after.map((r, i) => { const p = viewPiece(v, r.id); return p ? pgAfterRow(v, p, r.q, r.take, r.q - r.take, i) : ''; }).join('');
        return `<div class="panel" data-k="trade"><div class="ph"><h2>${hOut(hProfileUrl(t.whoId), hEsc(t.who))}</h2><span class="sub">${hPlural(t.items, 'item')} · ${hPlural(t.units, 'piece')}</span><span class="sp"></span><span class="st ${t.state}">${TURN_WORDS[t.state]}</span>${hOut(tradeViewUrl(t.id), 'Open the trade', 'btn sm go out')}</div>
            <div class="pb flush"><table class="t tight"><thead><tr><th>Their items</th><th class="n">In the trade</th><th>For your sets</th><th class="n">Your price</th><th class="n">Total</th></tr></thead><tbody>${rows}${sum}</tbody></table>${pgMargin(t)}${foot}</div></div>
          <div class="panel grow" data-k="after"><div class="ph"><h2>Your sets after this trade</h2><div class="legend">${pgKey('You hold', '#4a5263', 1)}${pgKey('Needed', 'var(--need)', 1)}${pgKey('Ahead', 'var(--warn)', 1)}</div></div>
            <div class="pb flush"><div class="after">${after}<div class="af" style="grid-template-columns:minmax(0,1fr);color:var(--text2)"><span>${sets}</span></div></div></div></div>`;
    }

    function pgTrades(d, ui) {
        const v = d.view;
        const open = v.trades.open;
        const sel = open.find((t) => t.id === ui.trade) || open[0] || null;
        const wait = v.trades.wait;
        return `<section class="page g2r on">
        <div class="col">
          <div class="panel" data-k="open"><div class="ph"><h2>Open with you</h2><span class="sp"></span>${open.length ? `<span class="badge ${wait ? 'ahead' : ''}">${wait} ${wait === 1 ? 'waits' : 'wait'} for you</span>` : ''}</div><div class="pb flush">${open.length ? open.map((t) => `<div class="li ${sel && t.id === sel.id ? 'sel' : ''}" data-act="trade" data-id="${hEsc(t.id)}" style="cursor:pointer"><span class="av ${t.state === 'new' ? 'new' : ''}">${hEsc(String(t.who || '?')[0])}</span><span class="li-m"><b>${hEsc(t.who)}</b><span>${hPlural(t.items, 'item')} · ${t.ago}</span></span><span class="amt"><b class="num">${hMoney(t.total)}</b><span class="st ${t.state}">${TURN_WORDS[t.state]}</span></span></div>`).join('') : pgNone('No trade is open with you.')}</div></div>
          <div class="panel grow" data-k="fin"><div class="ph"><h2>Finished</h2><span class="sp"></span><button class="btn sm" data-go="ledger" data-pane="3">Receipts</button></div><div class="pb flush">${v.trades.finished.length ? v.trades.finished.slice(0, 12).map((f) => `<div class="li"><span class="av">${hEsc(String(f.who || '?')[0])}</span><span class="li-m"><b>${hOut(hProfileUrl(f.whoId), hEsc(f.who))}</b><span>${hPlural(f.units, 'piece')} · ${hWhen(f.t)}</span></span><b class="num">${hMoney(f.paid)}</b></div>`).join('') : pgNone('None yet.')}</div></div>
        </div>
        <div class="col">${pgTrade(v, sel)}</div>
      </section>`;
    }

    // ---- Points ------------------------------------------------------------------------------------------------------

    const PG_BOOK_BADGE = { made: ['best', 'Made'], sold: ['ok', 'Sold'], used: ['need', 'Used'] };

    function pgBookRow(v, r) {
        const [cls, word] = PG_BOOK_BADGE[r.kind] || ['', r.kind];
        const set = r.set ? v.sets.find((s) => s.key === r.set) : null;
        const what = r.kind === 'made' ? (set ? `${hPlural(Math.round(r.points / set.points), set.label + ' Set')} at the museum` : 'Sets at the museum') : r.kind === 'sold' ? 'One lot on the points market' : 'Used by you';
        const out = r.kind !== 'made';
        return `<tr><td>${hWhen(r.t)}</td><td><span class="badge ${cls}">${word}</span> ${what}${out && r.mine < r.points ? ` <span class="t-muted">· ${hNum(r.points - r.mine)} were yours before</span>` : ''}</td><td class="n"><b>${out ? '-' : '+'}${hNum(out ? r.mine : r.points)}</b></td><td class="n">${hMoney(r.cost)}</td><td class="n">${r.kind === 'sold' ? hMoney(r.each) : `<span class="t-muted">${r.kind === 'used' ? 'used' : 'held'}</span>`}</td><td class="n">${r.kind === 'sold' ? `<span class="${r.gain < 0 ? 't-bad' : 't-good'}">${hSigned(r.gain)}</span>` : r.kind === 'used' ? '<span class="t-muted">not counted</span>' : ''}</td></tr>`;
    }

    function pgPoints(d, ui) {
        const v = d.view;
        const pt = v.points;
        const book = pt.book;
        if (ui.pane === 1) {
            const swapped = v.ledger.swapped;
            const sets14 = v.sets.reduce((a, s) => a + (swapped[s.key] || []).reduce((x, y) => x + y, 0), 0);
            return `<section class="page p-tabs on"><div class="pane g2 on">
          <div class="col">
            <div class="tiles" style="--n:4" data-k="tiles">
              <div class="panel tile"><div class="k-l">Made from sets</div><div class="k-v">${hNum(book.made)}</div><div class="k-s">${hPlural(sets14, 'set')} in 14 days</div></div>
              <div class="panel tile"><div class="k-l">Sold</div><div class="k-v">${hNum(book.sold)}</div><div class="k-s">profit <b class="${book.profitSold < 0 ? 't-bad' : 't-good'}">${hSigned(book.profitSold)}</b></div></div>
              <div class="panel tile"><div class="k-l">Used by you</div><div class="k-v">${hNum(book.used)}</div><div class="k-s">cost you <b>${hMoney(book.usedCost)}</b> · not profit</div></div>
              <div class="panel tile"><div class="k-l">Held, made from sets</div><div class="k-v">${hNum(book.left)}</div><div class="k-s">${book.left ? `cost ${hMoney(book.each)} · worth ${hMoney(pt.price)} today` : 'none held'}</div></div>
            </div>
            <div class="panel grow" data-k="book"><div class="ph"><h2>Points book</h2><span class="sub">sets put points in at what they cost · a sale takes them out at the average</span></div><div class="pb flush">${book.rows.length ? `<table class="t"><thead><tr><th>When</th><th>What</th><th class="n">Points</th><th class="n">Cost each</th><th class="n">Price each</th><th class="n">Profit</th></tr></thead><tbody>${book.rows.map((r) => pgBookRow(v, r)).join('')}</tbody></table>` : pgNone('Empty. A set swapped at the museum puts its points here, at what the pieces cost you.')}</div></div>
          </div>
          <div class="col">
            <div class="panel grow minc" data-k="held"><div class="ph"><h2>Points held, made from sets</h2><span class="sp"></span><span class="sub">14 days</span></div><div class="pb"><div class="chart" data-chart="held"></div></div></div>
            <div class="panel" data-k="before"><div class="ph"><h2>The points you had before</h2></div><div class="pb" style="color:var(--text2)">${pt.before == null ? 'Your points have not been read yet.' : pt.before ? `${hNum(pt.before)} points were yours before Torn Archive. They are left alone: never filled, never counted as profit. Type what a point cost you if you want them in the book.` : 'Every point you hold was made from sets.'}${pt.before ? `<span style="margin-left:8px;white-space:nowrap">$ ${pgInput('beforeEach', v.settings.beforeEach || '', 84)}</span>` : ''}</div></div>
          </div></div></section>`;
        }
        const max = Math.max(1, ...pt.table.map((r) => r.lots));
        const lots = pt.table.map((r) => `<tr><td><b>${r.label}</b></td><td><span class="hb-t"><i class="hb" style="--w:${r.lots / max * 100}%"></i></span><span class="num">${hNum(r.lots)}</span></td><td class="n">${hNum(r.points)}</td><td class="n">${r.wait == null ? '<span class="t-muted">not seen yet</span>' : waitWords(r.wait)}</td><td>${r.mine ? `${r.mine.n} of yours${r.mine.lo == null ? '' : r.mine.lo === r.mine.hi ? ': ' + waitWords(r.mine.lo) : `: ${waitWords(r.mine.lo)} to ${waitWords(r.mine.hi)}`}` : '<span class="t-muted">none of yours yet</span>'}</td></tr>`).join('');
        const sell = pt.sell;
        const about = (ms) => (ms == null ? '<span class="t-muted">no wait seen yet</span>' : 'about ' + waitWords(ms));
        const sellRows = !sell.points ? '<div class="row"><span class="grow1 t-muted">No points made from sets to sell. Swap full sets at the museum first.</span></div>' : `
              <div class="row"><span class="grow1">Price to type, $1 under the ${pt.rule === 'wall' ? 'first wall' : 'lowest listing'}</span><b class="num">${hMoney(pt.price)}</b></div>
              ${sell.loss ? `<div class="row"><span class="grow1 t-bad">Under your least price ${hMoney(sell.least)}: selling now is a loss.</span></div>` : ''}
              ${sell.quick ? `<div class="row"><span class="grow1"><b>Quickest:</b> ${lotsWords(sell.quick.lots)}</span><b class="num">${about(sell.quick.wait)}</b></div>` : ''}
              <div class="row"><span class="grow1">${sell.quick ? '' : '<b>Quickest:</b> '}One lot of ${hNum(sell.points)}</span><b class="num">${about(sell.one.wait)}</b></div>
              <div class="row"><span class="grow1">Profit over what they cost</span><b class="num ${sell.profit < 0 ? 't-bad' : 't-good'}">${hSigned(sell.profit)}</b></div>
              <div class="row"><span class="grow1 t-muted">Bank each lot as it sells.</span></div>`;
        const seg = `<div class="seg">${[7, 30, 40].map((n) => `<button data-act="range" data-id="pts2" data-v="${n}"${ui.range.pts2 === n ? ' class="on"' : ''}>${n} days</button>`).join('')}</div>`;
        // The break-even (the owner, 2026-10-11: "give me something visual to warn ... if i sell lower than this i
        // would lose money"): what a point you hold cost you against the price now, on one bar.
        const ev = pt.even;
        const marks = [['Your cost a point', ev.each, 'var(--text2)'], ['Price now', ev.now, ev.each && ev.now < ev.each ? 'var(--bad)' : 'var(--good)'], [ev.usualFrom === 'sales' ? 'You usually sell at' : 'Points usually sell at', ev.usual, 'var(--s-gold)']].filter((m) => m[1] > 0);
        const lo = Math.min(...marks.map((m) => m[1]));
        const hi = Math.max(...marks.map((m) => m[1]));
        const pad = Math.max(1, (hi - lo) * 0.2, hi * 0.002);
        const at = (x) => ((x - lo + pad) / (hi - lo + 2 * pad) * 100).toFixed(1) + '%';
        const under = ev.each > 0 && ev.now > 0 && ev.now < ev.each;
        const evSets = ev.sets.filter((e) => e.from > 0).map((e) => `a ${pgLow(e.label)} set costs you <b>${hMoney(e.from)}</b> a point${e.to && e.to !== e.from ? `, <b>${hMoney(e.to)}</b> with your list bought` : ''}`).join(' · ');
        const evWords = !ev.each ? 'You hold no points made from sets: the bar shows your cost a point once a set is swapped.'
            : !ev.now ? 'The points market has not been read yet.'
            : under ? `<b class="t-bad">Selling now loses ${hMoney(ev.loss || sell.points * (ev.each - ev.now))}.</b> Every point you hold cost you ${hMoney(ev.each)}; the price to type is ${hMoney(ev.now)}.`
            : `A point sold now leaves <b class="t-good">${hSigned(ev.now - ev.each)}</b> over what it cost you. Under ${hMoney(ev.each)} a point, selling is a loss.`;
        const evPanel = `<div class="panel ${under ? 'hold' : ''}" data-k="even"><div class="ph"><h2>Your break-even</h2><span class="sp"></span>${under ? '<span class="badge bad">under your cost</span>' : ''}</div><div class="pb">
              ${marks.length > 1 && ev.each ? `<div class="even-b ${under ? 'bad' : ''}">${ev.now ? `<i style="--a:${at(Math.min(ev.each, ev.now))};--w:calc(${at(Math.max(ev.each, ev.now))} - ${at(Math.min(ev.each, ev.now))})"></i>` : ''}${marks.map((m) => `<u style="--at:${at(m[1])};--c:${m[2]}"></u>`).join('')}</div><div class="even-k">${marks.map((m) => `<span><i class="key box" style="--c:${m[2]}"></i>${m[0]}<b class="num">${hMoney(m[1])}</b></span>`).join('')}</div>` : ''}
              <div class="rows"><div class="row"><span class="grow1">${evWords}</span></div>${evSets ? `<div class="row"><span class="grow1 t-muted">${evSets[0].toUpperCase() + evSets.slice(1)}.</span></div>` : ''}</div></div></div>`;
        return `<section class="page p-tabs on"><div class="pane g2 on">
          <div class="col">
            <div class="panel grow minc" data-k="pts2"><div class="ph"><h2>Points price</h2><div class="legend">${pgKey('First wall', 'var(--s-gold)')}${pgKey('Lowest listing', 'var(--s-violet)')}</div><span class="sp"></span>${seg}</div>
              <div class="pb"><div class="chart" data-chart="pts2"></div></div></div>
            <div class="panel" data-k="lots"><div class="ph"><h2>Which lot size sells</h2><span class="sub">lots that left the market, 7 days</span></div><div class="pb flush"><table class="t tight wrapth"><thead><tr><th>Lot size</th><th>Lots gone</th><th class="n">Points in them</th><th class="n">Usual wait at the wall price</th><th>Your own lots</th></tr></thead><tbody>${lots}</tbody></table></div></div>
          </div>
          <div class="col">
            <div class="panel grow" data-k="ladder"><div class="ph"><h2>The market now</h2><span class="sub">lowest first</span><span class="sp"></span>${hOut(POINTS_MARKET_URL, 'Points market', 'btn sm out')}</div><div class="pb flush"><div class="ladder">${pgLadder(v, 9)}</div></div></div>
            ${evPanel}
            <div class="panel ${pt.hold && sell.points ? 'hold' : ''}" data-k="sell"><div class="ph"><h2>Selling your ${hNum(sell.points)} points</h2><span class="sp"></span>${pt.hold && sell.points ? '<span class="badge ahead">cheap today: hold</span>' : pt.cheap && sell.points ? '<span class="badge ahead">cheap today</span>' : ''}</div><div class="pb"><div class="rows">${sellRows}</div></div></div>
          </div></div></section>`;
    }

    // ---- My prices ---------------------------------------------------------------------------------------------------

    function pgVerdict(v) {
        const vd = v.prices.verdict;
        const c = vd.checks;
        const ck = (ok, html) => `<div class="chk ${ok ? '' : 'no'}"><span>${html}</span></div>`;
        const btn = { 'buy-first': '<button class="btn sm" data-act="make-list">The list</button>', 'stay-buy': '<button class="btn sm" data-act="make-list">The list</button>', 'open-now': '<button class="btn sm go" data-act="set" data-id="open" data-v="1">Open the shop</button>' }[vd.state] || '';
        // The set that leaves least, at the rate it is paid today (its own ceiling when that is under your rate).
        const worst = v.prices.sets.find((s) => s.label === c.leaves.name);
        const cheaper = c.cheaper.ok
            ? (c.cheaper.listings ? `${hPlural(c.cheaper.listings, 'listing')} under your price ${c.cheaper.listed >= c.cheaper.listings ? `${c.cheaper.listings === 1 ? 'is' : 'are'} <b>on your list</b>` : 'can go on your list'}. A new listing never closes the shop` : 'Nothing you need is cheaper in a bazaar')
            : `<b>${hPlural(c.cheaper.units, 'piece')}</b> you need ${c.cheaper.units === 1 ? 'is' : 'are'} cheaper in a bazaar than from your sellers${v.prices.open ? ', and have sat unbought for 10 minutes' : ''}`;
        return `<div class="verdict"><span class="lamp ${vd.lamp === 'ok' ? '' : 'warn'}"${vd.lamp === 'bad' ? ' style="background:var(--bad);box-shadow:0 0 0 4px rgba(240,96,93,.16)"' : ''}></span><b>${VERDICT_WORDS[vd.state]}</b><span class="sp"></span>${btn}</div>`
            + (vd.state === 'no-price' ? '' : ck(c.leaves.ok, `A ${pgLow(c.leaves.name)} set bought at ${hRate(worst ? worst.pct : v.prices.pct)}% leaves <b>${hSigned(c.leaves.profit)}</b>${c.leaves.ok ? '' : `: under your least ${hRate(v.prices.least)}%`}`)
                + ck(c.cheaper.ok, cheaper)
                + ck(c.need.ok, c.need.ok ? `You still need <b>${hPlural(c.need.units, 'piece')}</b>` : 'You need nothing: every set is at its target')
                + ck(c.share.ok, c.share.sets == null ? 'No limit set on your share of money in sets' : c.share.ok ? `Your ${v.share.max}% share covers <b>${hPlural(c.share.sets, 'more set')}</b>` : `Your ${v.share.max}% share of money in sets and points is full`));
    }

    const PG_THREAD = {
        match: ['ok', 'the title on Torn matches'],
        open: ['ahead', 'the title on Torn still says closed'],
        closed: ['ahead', 'the title on Torn still says open'],
    };

    function pgW3b(d) {
        const w = d.view.prices.w3b;
        const key = (d.keys && d.keys.w3b) || {};
        let badge = '<span class="badge">no key yet</span>';
        let body;
        if (!key.set) body = '<div class="row"><span class="grow1">Paste the key you registered on TornW3B to keep your price list there at your rate, and to make a receipt for a trade.</span><button class="btn sm" data-go="settings">Settings</button></div>';
        else if (w.error) { badge = '<span class="badge bad">not read</span>'; body = `<div class="row"><span class="grow1 t-bad">${hEsc(w.error)}</span><button class="btn sm" data-act="w3b" data-v="read">Read again</button></div>`; }
        else if (!w.known) { badge = '<span class="badge">reading</span>'; body = '<div class="row"><span class="grow1 t-muted">Your list on TornW3B has not been read yet.</span></div>'; }
        else if (w.matches) { badge = '<span class="badge ok">matches your prices</span>'; body = `<div class="row"><span class="grow1">${d.view.prices.open ? `Every piece is on it at ${d.view.prices.paid || hRate(d.view.prices.pct) + '%'}.` : 'No set piece is on it: your shop is closed.'}</span></div>`; }
        else {
            badge = `<span class="badge ahead">${hPlural(w.diff.set.length + w.diff.remove.length, 'price')} differ</span>`;
            body = `<div class="row"><span class="grow1">${[w.diff.set.length ? `${hPlural(w.diff.set.length, 'price')} to set` : '', w.diff.remove.length ? `${hPlural(w.diff.remove.length, 'piece')} to take off` : ''].filter(Boolean).join(' · ')}. Only set pieces are touched: anything else on your list stays as it is.${w.waits ? ' <span class="t-muted">Written by itself when your prices are next fixed.</span>' : ''}</span>${w.sync && !w.waits ? '<span class="t-muted">sending</span>' : `<button class="btn sm go" data-act="w3b" data-v="send"${d.busy && d.busy.w3b ? ' disabled' : ''}>Send to TornW3B</button>`}</div>`;
        }
        const listed = !key.set ? '' : w.listedUntil > d.view.at ? `Buyers see your list until ${hDay(w.listedUntil)}: TornW3B shows it for 7 days after a receipt.` : 'Buyers do not see your list: TornW3B shows it for 7 days after a receipt.';
        return `<div class="panel" data-k="w3b"><div class="ph"><h2>Your price list on TornW3B</h2><span class="sp"></span>${badge}</div><div class="pb"><div class="rows">${body}
            ${key.set ? `<div class="field"><span class="f-l">Keep it at my rate by itself<span>${listed}</span></span>${pgSeg('w3bSync', d.view.settings.w3bSync ? 1 : 0, [[1, 'On'], [0, 'Off']])}</div>` : ''}
            <div class="row"><span class="grow1 t-muted">Open and Closed on TornW3B's own page is yours to press there.</span></div></div></div></div>`;
    }

    /**
     * One set on "What you pay sellers": the rate it is paid today and why it is not your own (its ceiling, or a fall
     * inside the hour), what a set costs and leaves, and - quieter - how far the ceiling is and what the other buyers
     * pay for the whole set. The piece holding the set back is named only when its best other buyer pays over your
     * ceiling: said, never chased.
     */
    function pgRateRow(v, s) {
        const pr = v.prices;
        const why = s.down ? `, down from ${hRate(s.down.from)}% at ${hClock(s.down.at)} TCT as points fell to ${hMoney(s.down.price)},` : s.capped ? `, its ceiling under your ${hRate(s.typed)}%,` : '';
        const o = s.others;
        const more = [
            s.cap > 0 && s.pct < s.cap ? `the most that keeps your ${hRate(pr.least)}% is ${hRate(s.cap)}%` : '',
            o ? `others pay ${hRate(o.pct)}% for the set${o.pieces < o.of ? `, on the ${o.pieces} of ${o.of} pieces with a buyer seen` : ''}${v.at - o.at >= BID_OLD_MS ? `, read ${hAge(o.at, v.at)}` : ''}` : '',
            s.short ? `${hEsc(s.short.name)}: others pay ${hPct(s.short.pct)}, over your ceiling` : '',
        ].filter(Boolean).join(' · ');
        return `<div class="row"><span class="grow1">A ${pgLow(s.label)} set at <b>${hRate(s.pct)}%</b>${why} costs you <b>${hMoney(s.cost)}</b> and makes ${s.points} points${more ? ` <span class="t-muted">· ${more}</span>` : ''}</span><b class="num ${s.ok ? 't-good' : s.profit < 0 ? 't-bad' : 't-warn'}">${hSigned(s.profit)} a set</b></div>`;
    }

    /** The hour your prices are fixed for, or why they are not, and the points price they are counted at - one row. */
    function pgRateHour(pr) {
        const pt = pr.points;
        const state = !pr.open ? 'Your shop is closed: this is <b>what you would pay if you opened now</b>.'
            : !pr.fixed ? (pr.live.ok ? 'Your prices are being fixed for the hour.' : 'Not fixed yet.')
            : pr.fixed.held ? `Your prices <b>stand still while a trade with set pieces is open</b>: their hour ended at ${hClock(pr.fixed.until)} TCT.`
            : `<b>Fixed until ${hClock(pr.fixed.until)} TCT</b>: points moving changes nothing before then, unless your least profit would be gone.`;
        const from = pt.from === 'usual' ? (pt.usualFrom === 'sales' ? 'what you usually sell for' : 'what points usually sell for') : pr.fixed ? 'the price when they were fixed' : "today's price";
        const counted = !pt.price ? 'The points price has not been read yet: you pay your rate until it is.'
            : `Counted at ${hMoney(pt.price)} a point, ${from}${pt.today && pt.today !== pt.price ? ` · ${hMoney(pt.today)} now` : ''}.`;
        return `<div class="row"><span class="grow1">${state} <span class="t-muted">${counted}</span></span></div>`;
    }

    function pgPrices(d) {
        const v = d.view;
        const pr = v.prices;
        const at = (r) => Math.max(0, Math.min(100, (r - 99) / 5 * 100));
        const paid = pr.paid || hRate(pr.pct) + '%';
        const th = pr.thread;
        const [tcls, twords] = !th ? ['', 'no buying thread of yours found']
            : th.check.state === 'rate' ? ['ahead', `the title on Torn says ${hRate(th.check.says.pct)}%`]
            : th.check.state === 'under' ? ['ahead', `the title says ${hRate(th.check.says.pct)}%, you pay ${paid} today`]
            : PG_THREAD[th.check.state];
        const capOf = (p) => (pr.sets.find((s) => s.key === p.set) || {}).cap || 0;
        const mkAt = at(pr.cap);
        const table = '<thead><tr><th>Piece</th><th class="n">Market value</th><th class="n">You pay, ' + paid + '</th><th class="n">Best other buyer</th><th class="n">Cheapest bazaar</th></tr></thead><tbody>' + v.pieces.map((p) => `<tr><td>${pgIco(p)}<b>${hEsc(p.name)}</b></td><td class="n">${hMoney(p.mv)}</td><td class="n"><b>${hMoney(p.pay)}</b></td><td class="n">${p.other ? `<span class="${p.pay > 0 && p.other.price > p.pay ? 't-warn' : 't-muted'}" title="${hEsc(p.other.name)}${capOf(p) > 0 && p.other.pct > capOf(p) ? ' · over your ceiling' : ''}">${hPct(p.other.pct)}</span>` : '<span class="t-muted">none seen</span>'}</td><td class="n">${!p.lowBazaar ? '<span class="t-muted">none</span>' : p.lowBazaar < p.pay ? `<span class="t-warn">cheaper than you</span> <b class="t-warn">${hMoney(p.lowBazaar)}</b>` : hMoney(p.lowBazaar)}</td></tr>`).join('') + '</tbody>';
        return `<section class="page g57 stackable wide on">
        <div class="col">
          <div class="panel tint" data-k="rate"><div class="ph"><h2>What you pay sellers</h2><span class="sp"></span><span class="toggle" data-act="set" data-id="open" data-v="${pr.open ? 0 : 1}" style="cursor:pointer" title="${pr.open ? 'Close the shop' : 'Open the shop'}"><span class="sw-t"${pr.open ? '' : ' style="background:var(--faint)"'}></span><b class="${pr.open ? 't-good' : 't-muted'}">${pr.open ? 'Shop open' : 'Shop closed'}</b></span></div><div class="pb">
            <div class="hero">${paid}<small>of market value, ${pr.sets.some((s) => s.pct !== pr.sets[0].pct) ? 'each set its own' : 'every piece'}</small></div>
            <div class="track" style="--w:${at(pr.pct)}%;--at:${mkAt}%"><i></i><span class="knob"></span>${pr.cap ? `<span class="mk${mkAt > 80 ? ' r' : mkAt < 20 ? ' l' : ''}"><span>${pr.sets.length > 1 ? 'the lower ceiling' : 'the ceiling'}</span></span>` : ''}<span class="lo">99%</span><span class="hi">104%</span></div>
            <div class="rows">
              ${pr.sets.map((s) => pgRateRow(v, s)).join('')}
              ${pgRateHour(pr)}
              <div class="row"><span class="grow1">Your rate, the most you pay <span class="t-muted">· a set is paid the lower of it and its own ceiling</span></span>${pgInput('pct', hRate(pr.pct), 64, '%')}</div>
            </div>
          </div></div>
          <div class="panel" data-k="verdict"><div class="ph"><h2>Open your shop?</h2></div><div class="pb">${pgVerdict(v)}</div></div>
          ${pgW3b(d)}
          <div class="panel" data-k="thread"><div class="ph"><h2>Your forum thread</h2><span class="sp"></span><span class="badge ${tcls}">${twords}</span></div><div class="pb">
            <div class="msg"><b>${hEsc(pr.forum.title)}</b><br>${hEsc(pr.forum.post).replace(/\n/g, '<br>')}</div>
            <div style="display:flex;gap:8px;margin-top:10px;align-items:center"><button class="btn" data-act="copy" data-v="${hEsc(pr.forum.title)}">Copy the title</button><button class="btn" data-act="copy" data-v="${hEsc(pr.forum.post)}">Copy the post</button>${th && th.url ? hOut(th.url, 'Your thread', 'btn out') : ''}<span class="sp"></span><span class="t-muted" style="font-size:12px">You paste and post it.</span></div>
          </div></div>
          <div class="panel grow minc" data-k="ratechart"><div class="ph"><h2>What a set leaves you, by rate</h2><div class="legend">${pgSetKeys(v)}</div></div><div class="pb"><div class="chart" data-chart="rate"></div></div></div>
        </div>
        <div class="panel grow" data-k="price-t"><div class="ph"><h2>Your price for every piece</h2><span class="sub">beside what others pay and what a bazaar asks</span></div><div class="pb flush"><table class="t">${table}</table></div></div>
      </section>`;
    }

    // ---- Ledger ------------------------------------------------------------------------------------------------------

    const PG_VENUE = { bazaar: 'Bazaar', market: 'Item Market' };
    const PG_UNITS = [['day', 'Day'], ['week', 'Week'], ['month', 'Month']];

    function pgLedger(d, ui) {
        const v = d.view;
        const lg = v.ledger;
        const sum = lg.sum;
        const wrap = (cls, body, style = '') => `<section class="page p-tabs on"><div class="pane ${cls} on"${style ? ` style="${style}"` : ''}>${body}</div></section>`;
        const one = (k, head, sub, table, none) => wrap('g1', `<div class="panel grow" data-k="${k}"><div class="ph"><h2>${head}</h2>${sub ? `<span class="sub">${sub}</span>` : ''}</div><div class="pb flush">${table || pgNone(none)}</div></div>`);
        if (ui.pane === 1) {
            // `about`: a part of the lot's cost was an estimate (pieces never seen bought). `before`: points of the lot
            // that were yours before the book began - sold, and counted for nothing: shown, so the page adds up to
            // what you received.
            const then = (s) => [s.before ? `<span class="t-muted">+ ${hNum(s.before)} held before: ${hMoney(s.beforeGot)}, not counted</span>` : '', s.mug ? `<span class="t-bad">mugged ${waitWords(s.mug.after)} later: -${hMoney(s.mug.counted)}</span>` : ''].filter(Boolean).join(' · ');
            const rows = lg.sold.map((s) => `<tr><td>${hWhen(s.t)}</td><td class="n"><b>${hNum(s.points)}</b></td><td class="n">${hMoney(s.each)}</td><td class="n">${hMoney(s.got)}</td><td class="n">${s.points ? (s.about ? '<span class="t-muted">about</span> ' : '') + hMoney(s.cost) : ''}</td><td class="n">${s.points ? `<span class="${s.gain < 0 ? 't-bad' : 't-good'}">${s.about ? 'about ' : ''}${hSigned(s.gain)}</span>` : ''}</td><td>${then(s)}</td></tr>`).join('');
            const all = lg.sold.reduce((a, s) => ({ points: a.points + s.points, got: a.got + s.got, gain: a.gain + s.gain, about: a.about || s.about }), { points: 0, got: 0, gain: 0, about: false });
            const bf = lg.before;
            const foot = (all.points ? `<tr class="sum"><td>Every lot</td><td class="n">${hNum(all.points)}</td><td class="n">${hMoney(all.got / all.points)}</td><td class="n">${hMoney(all.got)}</td><td class="n">${hMoney((all.got - all.gain) / all.points)}</td><td class="n">${all.about ? 'about ' : ''}${hSigned(all.gain)}</td><td>${lg.mugs.counted ? `less buy-mugs: ${hSigned(all.gain - lg.mugs.counted)}` : ''}</td></tr>` : '')
                + (bf.points ? `<tr><td class="t-muted">Held before, not counted</td><td class="n t-muted">${hNum(bf.points)}</td><td></td><td class="n t-muted">${hMoney(bf.got)}</td><td></td><td></td><td></td></tr><tr class="sum"><td>You received in all</td><td class="n">${hNum(all.points + bf.points)}</td><td></td><td class="n">${hMoney(all.got + bf.got)}</td><td></td><td></td><td></td></tr>` : '');
            return one('sold', 'Every lot of points you sold', `profit is counted on the points made from sets${all.about ? ' · "about": a part of their cost was an estimate' : ''}`, rows && `<table class="t"><thead><tr><th>When</th><th class="n">Lot</th><th class="n">Price each</th><th class="n">You got</th><th class="n">Cost a point then</th><th class="n">Profit</th><th>Then</th></tr></thead><tbody>${rows}${foot}</tbody></table>`, 'No points sold yet.');
        }
        if (ui.pane === 6) {
            // Pieces that left as themselves: each its own profit or loss against what it had cost you (1.3.0; until
            // then such a piece left your stock at its average cost and the money was nowhere).
            const where = { bazaar: 'Your bazaar', market: 'Item Market', trade: 'A trade' };
            const dr = lg.direct;
            const rows = dr.rows.map((r) => `<tr><td>${hWhen(r.t)}</td><td>${pgItem(v, r.itemId, r.name)}<b>${hEsc(r.name)}</b></td><td>${r.give ? 'Given away' : where[r.venue] || hEsc(r.venue || '')}</td><td class="n">${hNum(r.qty)}</td><td class="n">${r.give ? '' : hMoney(r.got)}</td><td class="n">${r.est >= BOOK_ABOUT ? '<span class="t-muted">about</span> ' : ''}${hMoney(r.cost)}</td><td class="n">${r.give ? '<span class="t-muted">not counted</span>' : `<span class="${r.gain < 0 ? 't-bad' : 't-good'}">${r.est >= BOOK_ABOUT ? 'about ' : ''}${hSigned(r.gain)}</span>`}</td></tr>`).join('');
            const foot = dr.units ? `<tr class="sum"><td colspan="3">Every piece sold</td><td class="n">${hNum(dr.units)}</td><td class="n">${hMoney(dr.got)}</td><td class="n">${hMoney(dr.cost)}</td><td class="n">${hSigned(dr.gain)}</td></tr>` : '';
            return one('direct', 'Pieces sold as themselves', `each against what it had cost you${dr.given ? ` · ${hPlural(dr.given, 'piece')} given away, ${hMoney(dr.givenCost)} of cost: shown, not counted` : ''}`, rows && `<table class="t"><thead><tr><th>When</th><th>Piece</th><th>Where</th><th class="n">Units</th><th class="n">You got</th><th class="n">It had cost</th><th class="n">Profit</th></tr></thead><tbody>${rows}${foot}</tbody></table>`, 'No set piece sold or given away as itself yet. One sold in your bazaar, on the Item Market or in a trade shows here, with its own profit or loss.');
        }
        if (ui.pane === 2) {
            const rows = lg.buys.slice(0, 120).map((b) => `<tr><td>${hWhen(b.t)}</td><td>${pgItem(v, b.itemId, b.name)}<b>${hEsc(b.name)}</b></td><td>${b.venue === 'trade' ? 'Trade with ' + hEsc(b.who || 'a seller') : (PG_VENUE[b.venue] || hEsc(b.venue)) + (b.venue === 'bazaar' && b.who ? ' · ' + hEsc(b.who) : '')}</td><td class="n">${hNum(b.qty)}</td><td class="n">${hMoney(b.each)}</td><td class="n"><b>${hMoney(b.paid)}</b></td><td><span class="t-muted">${b.rate ? hPct(b.rate) : ''}</span></td></tr>`).join('');
            return wrap('g2', `<div class="panel grow" data-k="buys"><div class="ph"><h2>Every piece you bought</h2><span class="sub">from Torn's log</span></div><div class="pb flush">${rows ? `<table class="t"><thead><tr><th>When</th><th>Piece</th><th>Where</th><th class="n">Units</th><th class="n">Each</th><th class="n">Paid</th><th>Rate</th></tr></thead><tbody>${rows}</tbody></table>` : pgNone('No buy read from your log yet.')}</div></div>
          <div class="panel grow minc" data-k="bought"><div class="ph"><h2>Pieces bought, by where</h2><span class="sp"></span><span class="sub">14 days</span></div>
            <div class="pb" style="display:flex;flex-direction:column"><div class="legend" style="margin-bottom:4px">${pgKey('Bazaars', 'var(--s-gold)', 1)}${pgKey('Item Market', 'var(--s-violet)', 1)}${pgKey('Trades with you', 'var(--s-aqua)', 1)}</div><div style="flex:1;position:relative;min-height:0"><div class="chart" data-chart="bought" style="inset:0"></div></div></div></div>`);
        }
        if (ui.pane === 3) {
            const hasKey = d.keys && d.keys.w3b && d.keys.w3b.set;
            const rows = v.trades.finished.map((f) => `<tr><td>${hWhen(f.t)}</td><td><b>${hOut(hProfileUrl(f.whoId), hEsc(f.who))}</b></td><td class="n">${hNum(f.units)}</td><td class="n"><b>${hMoney(f.paid)}</b></td><td class="n"><span class="t-muted">${f.rate ? hPct(f.rate) : ''}</span></td><td class="n">${f.receipt && f.receipt.url ? hOut(f.receipt.url, 'Receipt', 'btn sm out') : f.receipt ? '<span class="t-muted">made</span>' : hasKey ? `${f.listed ? '' : '<span class="t-muted" style="margin-right:8px">not priced on your TornW3B list</span>'}<button class="btn sm" data-act="receipt" data-id="${hEsc(f.id)}"${d.busy && d.busy.receipt === f.id ? ' disabled' : ''}>Make the receipt</button>` : ''}</td></tr>`).join('');
            return one('rec', 'Receipts', v.trades.receiptsError ? 'TornW3B does not give your receipts: ' + hEsc(v.trades.receiptsError) : 'one per trade · made on TornW3B by itself, from your list there, when a trade ends', rows && `<table class="t"><thead><tr><th>When</th><th>Seller</th><th class="n">Pieces</th><th class="n">You paid</th><th class="n">Rate</th><th></th></tr></thead><tbody>${rows}</tbody></table>`, 'No finished trade yet.');
        }
        if (ui.pane === 4) {
            const rows = lg.sellers.map((s) => `<tr><td><b>${hOut(hProfileUrl(s.whoId), hEsc(s.who || 'Seller ' + s.whoId))}</b></td><td class="n">${hNum(s.trades)}</td><td class="n">${hNum(s.units)}</td><td class="n"><b>${hMoney(s.paid)}</b></td><td>${hEsc(s.brings)}</td><td>${s.came}</td></tr>`).join('');
            return one('sel', 'Sellers', '', rows && `<table class="t"><thead><tr><th>Seller</th><th class="n">Trades</th><th class="n">Units</th><th class="n">You paid</th><th>Mostly brings</th><th>Last came</th></tr></thead><tbody>${rows}</tbody></table>`, 'Nobody has sold to you in a trade yet.');
        }
        if (ui.pane === 5) {
            const sale = (m) => lg.sold.find((s) => s.id === m.saleId);
            const what = (m) => { const s = m.counted ? sale(m) : null; return m.counted ? `${s ? `${hNum(s.points)} points sold at ${hMoney(s.each)} ${waitWords(m.after)} before: ` : ''}${hMoney(m.onHand)} of points money was on hand, not yet banked` : 'No points money on hand'; };
            const rows = lg.mugs.rows.map((m) => `<tr><td>${hWhen(m.t)}</td><td>${hEsc(m.by || 'Someone')}</td><td class="n ${m.counted ? 't-bad' : 't-muted'}">-${hMoney(m.taken)}</td><td>${what(m)}</td><td>${m.counted ? `<span class="badge bad">buy-mug: ${m.counted < m.taken ? hMoney(m.counted) + ' ' : ''}counted</span>` : '<span class="badge">left out</span>'}</td></tr>`).join('');
            return one('mug', 'Mugged', 'counted only when it took points money you had not banked', rows && `<table class="t"><thead><tr><th>When</th><th>By</th><th class="n">Taken</th><th>What was on hand</th><th>In the profit</th></tr></thead><tbody>${rows}</tbody></table>`, 'No mug in your log.');
        }
        return wrap('g1', `<div class="tiles" style="--n:5" data-k="tiles">
            <div class="panel tile"><div class="k-l">Points sold</div><div class="k-v">${hMoney(sum.got)}</div><div class="k-s">${sum.points ? `${hNum(sum.points)} points · average ${hMoney(sum.got / sum.points)}` : 'none in 14 days'}</div></div>
            <div class="panel tile"><div class="k-l">less what they cost you</div><div class="k-v">${hMoney(sum.cost)}</div><div class="k-s">${sum.points ? `average ${hMoney(sum.cost / sum.points)} a point` : ''}</div></div>
            <div class="panel tile"><div class="k-l">less buy-mugs</div><div class="k-v"${sum.mug ? ' style="color:#ff8a87"' : ''}>${hMoney(-sum.mug)}</div><div class="k-s"><b>${lg.mugs.rows.length - lg.mugs.left}</b> counted · ${lg.mugs.left} left out</div></div>
            <div class="panel tile tint"><div class="k-l">Profit, 14 days</div><div class="k-v ${sum.profit >= 0 ? 'good' : ''}"${sum.profit < 0 ? ' style="color:#ff8a87"' : ''}>${sum.about ? '<small>about</small> ' : ''}${hSigned(sum.profit)}</div><div class="k-s">${sum.direct ? `of it <b>${hSigned(sum.direct)}</b> from pieces sold as themselves` : 'counted when points sell'}${sum.about ? ' · about: a part of the cost behind it is an estimate' : ''}</div></div>
            <div class="panel tile"><div class="k-l">Not sold yet, at ${lg.poolEst || lg.estLeft >= BOOK_ABOUT ? 'about its ' : ''}cost</div><div class="k-v">${hMoney(lg.notSold)}</div><div class="k-s">${hNum(lg.poolUnits)} pieces and ${hNum(lg.notSoldPoints)} points${lg.notSoldWorth ? ` · worth <b>${hMoney(lg.notSoldWorth)}</b> today: <b class="${lg.notSoldDiff < 0 ? 't-bad' : 't-good'}">${hSigned(lg.notSoldDiff)}</b>` : ''}</div></div>
          </div>
          <div class="g2" style="display:grid;gap:12px;min-height:0">
            <div class="panel grow minc" data-k="profit"><div class="ph"><h2>Profit by ${ui.unit}</h2><div class="legend">${pgKey('Points sold', 'var(--good)', 1)}${lg.direct.rows.length ? pgKey('Pieces sold', 'var(--s-violet)', 1) : ''}${pgKey('Buy-mug', 'var(--bad)', 1)}</div><span class="sp"></span><div class="seg">${PG_UNITS.map(([u, label]) => `<button data-act="unit" data-v="${u}"${ui.unit === u ? ' class="on"' : ''}>${label}</button>`).join('')}</div></div><div class="pb"><div class="chart" data-chart="profit"></div></div></div>
            <div class="col">
              <div class="panel grow minc" data-k="cum"><div class="ph"><h2>Running total</h2><span class="sp"></span><span class="sub">14 days</span></div><div class="pb"><div class="chart" data-chart="cum"></div></div></div>
            </div>
          </div>`, 'grid-template-rows:auto minmax(0,1fr)');
    }

    // ---- Settings ----------------------------------------------------------------------------------------------------

    const PG_KEYS = [
        ['limited', 'Limited key', [
            ['Data storage', 'Only in this browser'],
            ['Data sharing', 'Nobody'],
            ['Purpose of use', 'Personal gain: your museum sets and points'],
            ['Key storage and sharing', 'Stored in this browser, not shared'],
            ['Key access level', 'Limited: your inventory, money and open trades; items, the Item Market, the points market'],
        ]],
        ['full', 'Full key', [
            ['Data storage', 'Only time, item, quantity and price. Never the text of the log'],
            ['Data sharing', 'Nobody'],
            ['Purpose of use', 'What you paid, the points you made, sold and used, mugs'],
            ['Key storage and sharing', 'Stored in this browser, not shared'],
            ['Key access level', 'Full: used only for your log'],
        ]],
        ['w3b', 'The key you registered on TornW3B', [
            ['Data storage', 'Only in this browser'],
            ['Data sharing', 'TornW3B only, which already has it: you registered it there'],
            ['Purpose of use', 'Your own price list there, and a receipt for a trade'],
            ['Key storage and sharing', 'Stored in this browser. Sent to TornW3B with those two requests, never in an address'],
            ['Key access level', 'Whatever you registered there. Torn Archive asks Torn nothing with it'],
        ]],
    ];

    function pgKeyBox([kind, title, rows], d) {
        const k = (d.keys && d.keys[kind]) || {};
        // What a key's owner said against it stands on a line of its own: in the badge it was cut off under the next
        // panel. The badge never says "working" while the key is refused (1.3.0, TornW3B's 403).
        const badge = !k.set ? '<span class="badge">not set</span>' : k.error ? '<span class="badge bad">not working</span>' : k.ok ? '<span class="badge ok">working</span>' : '<span class="badge">checking</span>';
        const box = k.set
            ? `<span class="inp key"${k.shown ? ' style="letter-spacing:0;color:var(--text)"' : ''}>${k.shown ? hEsc(k.shown) : '••••••••••••••••'}</span><button class="btn" data-act="key-show" data-v="${kind}">${k.shown ? 'Hide' : 'Show'}</button><button class="btn" data-act="key-forget" data-v="${kind}">Forget</button>`
            : `<input class="inp key" type="password" data-key="${kind}" placeholder="Paste it here" autocomplete="off" spellcheck="false" style="letter-spacing:0"><button class="btn go" data-act="key-save" data-v="${kind}">Save</button>`;
        return `<div class="panel" data-k="key-${kind}"><div class="ph"><h2>${title}</h2><span class="sp"></span>${badge}</div><div class="pb">
              <div style="display:flex;gap:8px">${box}</div>
              ${k.set && k.error ? `<div class="wl-s t-bad" style="padding:8px 0 0">${hEsc(k.error[0].toUpperCase() + k.error.slice(1))}.${kind === 'w3b' ? ' TornW3B is not asked with it again until you change it.' : ''}</div>` : ''}
              <table class="t kv" style="margin-top:10px">${rows.map(([th, td]) => `<tr><th>${th}</th><td>${td}</td></tr>`).join('')}</table>
            </div></div>`;
    }

    const PG_SERVER_BADGE = { off: ['', 'not set'], alone: ['', 'working alone'], ok: ['ok', 'connected'], idle: ['', 'connecting'], warn: ['ahead', 'no answer'], bad: ['bad', 'refused'] };

    /** The shared server: its address and your password for it, and what it last said. The password is never shown again. */
    function pgServer(d) {
        const s = d.server || { on: false, level: 'off', now: 'Off. Torn Archive works alone.' };
        const [cls, word] = PG_SERVER_BADGE[s.level] || PG_SERVER_BADGE.off;
        // Built into this copy: nothing to type, and its address is not shown. One typed in an older copy stays, with Forget.
        const box = s.builtIn && !(s.on && !s.own) ? ''
            : s.on
            ? `<div style="display:flex;gap:8px"><span class="inp key" style="letter-spacing:0;color:var(--text)">${hEsc(s.address)}</span><button class="btn" data-act="server-forget">Forget</button></div>`
            // The address on a line of its own: it is long, and is never cut short.
            : `<div style="display:flex"><input class="inp key" type="text" data-server="address" value="${hEsc(s.typed || '')}" placeholder="Its address: https://….workers.dev" autocomplete="off" spellcheck="false" style="letter-spacing:0"></div>
              <div style="display:flex;gap:8px;margin-top:8px"><input class="inp key" type="password" data-server="pass" placeholder="${s.hasPass ? 'Password saved' : 'Your password for it'}" autocomplete="off" spellcheck="false" style="letter-spacing:0"><button class="btn go" data-act="server-save">Save</button></div>`;
        const rows = [['Now', hEsc(s.now)]];
        if (s.msg) rows.push(['', hEsc(s.msg)]);
        if (s.key) rows.push(['Your key there', hEsc(s.key.text)]);
        if (s.split) rows.push(['Your 100 Torn calls a minute', `your apps <b>${s.split.pc}</b> · the server <b>${s.split.server}</b> · never used <b>${s.split.free}</b>`]);
        if (s.on && s.bazaars) rows.push(['Bazaars from it', `<b>${hNum(s.bazaars)}</b> that sell a piece`]);
        rows.push(['What it is told', (s.builtIn ? 'Your Torn id, to know whose copy this is. Then bazaar' : 'Bazaar') + ' and item numbers, prices and counts. Never a key, your stock or your money']);
        rows.push(['What it gives', 'Bazaars, the points market and the Item Market, read from Torn itself with a key of each of you']);
        return `<div class="panel" data-k="server"><div class="ph"><h2>Torn Shared Server</h2><span class="sp"></span><span class="badge ${cls}">${word}</span></div><div class="pb">
              ${box}
              <table class="t kv"${box ? ' style="margin-top:10px"' : ''}>${rows.map(([th, td]) => `<tr><th>${th}</th><td>${td}</td></tr>`).join('')}</table>
            </div></div>`;
    }

    function pgSettings(d, ui) {
        const v = d.view;
        const s = v.settings;
        const u = d.usage || {};
        if (ui.pane === 1) {
            const n = d.notice;
            return `<section class="page p-tabs on"><div class="pane g1 on" style="grid-template-rows:auto minmax(0,1fr)">
          <div class="tiles" style="--n:3">
            <div class="panel" data-k="sets"><div class="ph"><h2>Sets</h2></div><div class="pb">
              <div class="field"><span class="f-l">Sets to trade</span><span class="seg"><button data-act="which" data-v="plushie"${s.which.plushie ? ' class="on"' : ''}>Plushie</button><button data-act="which" data-v="flower"${s.which.flower ? ' class="on"' : ''}>Flower</button></span></div>
              <div class="field"><span class="f-l">Sets to build at once<span>from cash: kept as it is while a list is on hand</span></span>${pgSeg('targetMode', s.targetMode, [['cash', 'From my cash and stock'], ['number', 'A number']])}${s.targetMode === 'number' ? pgInput('target', s.target, 56) : ''}</div>
              <div class="field"><span class="f-l">Most of my money in sets and points<span>0 = no limit</span></span>${pgInput('shareMax', s.shareMax, 56, '%')}</div>
              <div class="field"><span class="f-l">Least profit on a set</span>${pgInput('least', hRate(s.least), 56, '%')}</div>
              <div class="field"><span class="f-l">Read prices every</span>${pgSeg('readMin', s.readMin, READ_CHOICES.map((m) => [m, m + ' min']))}</div>
            </div></div>
            <div class="panel" data-k="rules"><div class="ph"><h2>Points and Torn's pages</h2></div><div class="pb">
              <div class="field"><span class="f-l">Points price to type</span>${pgSeg('pointsRule', s.pointsRule, [['wall', 'Under the first wall'], ['lowest', 'Under the lowest']])}</div>
              <div class="field"><span class="f-l">When points are under their usual level</span>${pgSeg('cheapRule', s.cheapRule, [['hold', 'Hold'], ['tell', 'Tell me only']])}</div>
              <div class="field"><span class="f-l">Fill at the museum<span>You press EXCHANGE</span></span>${pgSeg('fillMuseum', s.fillMuseum ? 1 : 0, [[1, 'On'], [0, 'Off']])}</div>
              <div class="field"><span class="f-l">Fill at the points market<span>You press ADD LISTING</span></span>${pgSeg('fillPoints', s.fillPoints ? 1 : 0, [[1, 'On'], [0, 'Off']])}</div>
            </div></div>
            <div class="panel" data-k="tell"><div class="ph"><h2>Tell me when</h2><span class="sp"></span><button class="btn sm" data-act="notify-test">Try it</button></div><div class="pb">
              <div class="field"><span class="f-l">Someone opens a trade with you<span>Seen within a minute, with a Torn tab or this page open</span></span>${pgSeg('notify', s.notify, [['browser', 'Browser'], ['app', 'In the app'], ['off', 'Off']])}</div>
              <div class="field"><span class="f-l">Sound</span>${pgSeg('sound', s.sound ? 1 : 0, [[1, 'On'], [0, 'Off']])}</div>
              ${n ? `<div class="field" style="display:block"><div class="osn"><span class="mark">${hIcon('brand')}</span><div><b>${hEsc(n.title)}</b><span class="s">${hEsc(n.body)}</span></div></div></div>` : ''}
              <div class="field"><span class="f-l t-muted" style="font-size:12px">Also a count on the browser tab and on Trades in the sidebar. Nothing is accepted or sent for you.</span></div>
            </div></div>
          </div>
          <div class="panel grow minc" data-k="share"><div class="ph"><h2>Share of your money in sets and points</h2><span class="sp"></span><span class="sub">now ${hPct(v.share.share)} · 14 days</span></div><div class="pb"><div class="chart" data-chart="share"></div></div></div>
        </div></section>`;
        }
        return `<section class="page p-tabs on"><div class="pane g1 on" style="grid-template-rows:auto minmax(0,1fr)">
          <div class="tiles five">
            ${PG_KEYS.map((k) => pgKeyBox(k, d)).join('')}
            ${pgServer(d)}
            <div class="panel" data-k="help"><div class="ph"><h2>Help</h2><span class="sp"></span><span class="sub">${d.version ? 'Torn Archive ' + hEsc(d.version) : ''}</span></div><div class="pb"><div class="rows">
              <div class="row"><span class="grow1"><b>Report a problem.</b> One zip on your computer. No key in it, nothing is sent.</span><button class="btn sm go" data-act="zip">Make the zip</button></div>
              <div class="row"><span class="grow1"><b>Beside Torn Trading.</b> Both run. The one whose page you look at asks more, the other less.</span></div>
              <div class="row"><span class="grow1 t-muted">TornW3B is sent item numbers only. The key you registered there goes with your own price list and receipts, nothing else.</span></div>
            </div></div></div>
          </div>
          <div class="panel grow minc" data-k="usage"><div class="ph"><h2>Requests a minute</h2><div class="legend">${pgKey('Torn', 'var(--s-plush)')}${pgKey('TornW3B', 'var(--s-flower)')}</div><span class="sub">now Torn <b>${hNum(u.nowTorn)}</b> of ${(d.turns && d.turns.torn) || TORN_PER_MINUTE_ALONE} · TornW3B <b>${hNum(u.nowW3b)}</b> of ${(d.turns && d.turns.w3b) || W3B_PER_MINUTE_ALONE} · refused, last hour <b>${hNum(u.refused)}</b>${pgTurns(d.turns)}</span><span class="sp"></span><button class="btn sm" data-act="usage-export">Export</button></div><div class="pb"><div class="chart" data-chart="usage"></div></div></div>
        </div></section>`;
    }

    const PG_RENDER = { dashboard: pgDashboard, stock: pgStock, buy: pgBuy, trades: pgTrades, points: pgPoints, prices: pgPrices, ledger: pgLedger, settings: pgSettings };

    /** One page as a string. @param d { view, keys, usage, busy, notice, version } @param ui { page, pane, sel, trade, range, unit } */
    const hubPage = (d, ui) => (PG_RENDER[ui.page] || pgDashboard)(d, ui);

    // ---- The graphs --------------------------------------------------------------------------------------------------

    const pgWeek = (b) => hDay(b.start);
    const PG_MONTH = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const pgSt = (v) => (v === 1 ? 'st' : v === 2 ? 'nd' : v === 3 ? 'rd' : 'th');

    /** What one graph draws. @returns { kind: 'line' | 'col', cfg } or null when the page has no such graph */
    function hubChart(name, d, ui) {
        const v = d.view;
        const line = (cfg) => ({ kind: 'line', cfg });
        const col = (cfg) => ({ kind: 'col', cfg });
        const count = (n) => hNum(n);
        if (name === 'pts' || name === 'pts2') {
            const c = v.points.chart;
            const n = ui.range[name] || 40;
            return line({
                x: c.x.slice(-n).map(hDay), none: 'The points price is kept by day from the first read: this fills as the days pass.',
                series: [{ name: 'First wall', color: 'var(--s-gold)', data: c.wall.slice(-n), area: true }, { name: 'Lowest listing', color: 'var(--s-violet)', data: c.low.slice(-n) }],
                band: c.usual ? { lo: c.usual.lo, hi: c.usual.hi, name: 'Usual range, 30 days', last: 30 } : null,
                refs: c.least ? [{ y: c.least, name: `Your least price ${hMoney(c.least)}: under this the points are a loss` }] : [],
            });
        }
        if (name === 'margin') {
            const days = v.dash.paysDays;
            return line({
                x: days.map((p) => hDay(p.day)), zero: true, none: 'What a set pays is kept by day from the first read: this fills as the days pass.',
                series: v.sets.map((s) => ({ name: s.name, color: s.color, data: days.map((p) => p[s.key] || 0) })),
                refs: v.prices.chart.least ? [{ y: v.prices.chart.least, name: `Your least profit, ${hRate(v.prices.least)}%` }] : [],
            });
        }
        if (name === 'depth') {
            const c = v.buy.depth;
            if (!c) return line({ x: [], series: [], none: 'Too few listings to say how deep the cheap pieces go.' });
            return line({
                x: c.x, xticks: c.x.filter((k) => k === 1 || k >= 100), xfmt: (k) => 'set ' + k, tipx: (k) => `The ${k}${pgSt(k)} set you buy costs`, left: 70,
                series: c.series.map((s) => ({ name: s.name, color: s.color, data: s.data })),
                refs: c.value ? [{ y: c.value, name: `A set at today's points price, ${hMoney(c.value)}` }, { y: c.safe, name: `With your least profit, ${hMoney(c.safe)}: buy while under this` }] : [],
            });
        }
        if (name === 'swapped') {
            const c = v.ledger.swapped;
            return col({ x: c.x.map(hDay), left: 34, yfmt: count, none: 'No set swapped at the museum in 14 days.', series: v.sets.map((s) => ({ name: s.label + ' sets', color: s.color, data: c[s.key] })) });
        }
        if (name === 'bought') {
            const c = v.ledger.where;
            return col({ x: c.x.map(hDay), left: 44, yfmt: count, none: 'No piece bought in 14 days.', series: [{ name: 'Bazaars', color: 'var(--s-gold)', data: c.bazaar }, { name: 'Item Market', color: 'var(--s-violet)', data: c.market }, { name: 'Trades with you', color: 'var(--s-aqua)', data: c.trade }] });
        }
        if (name === 'profit') {
            const b = ui.unit === 'week' ? v.ledger.weeks : ui.unit === 'month' ? v.ledger.months : v.ledger.days;
            const x = b.map((k) => (ui.unit === 'month' ? PG_MONTH[new Date(k.start).getUTCMonth()] : ui.unit === 'week' ? pgWeek(k) : hDay(k.day)));
            const direct = v.ledger.direct.rows.length ? [{ name: 'Pieces sold', color: 'var(--s-violet)', data: b.map((k) => k.direct) }] : [];
            return col({ x, yfmt: hShort, none: 'Profit is counted when points sell: none sold yet.', series: [{ name: 'Points sold', color: 'var(--good)', data: b.map((k) => k.sold) }, ...direct, { name: 'Buy-mug', color: 'var(--bad)', data: b.map((k) => k.mug) }] });
        }
        if (name === 'cum') return line({ x: v.ledger.days.map((k) => hDay(k.day)), zero: true, yfmt: hShort, right: 62, series: [{ name: 'Running total', color: 'var(--s-aqua)', data: v.ledger.cum, area: true }] });
        if (name === 'held') return line({ x: v.points.heldDays.map((k) => hDay(k.day)), zero: true, yfmt: count, left: 44, right: 44, series: [{ name: 'Points held', color: 'var(--s-gold)', data: v.points.heldDays.map((k) => k.left), area: true }] });
        if (name === 'rate') {
            const c = v.prices.chart;
            return line({
                x: c.x, xticks: c.x.filter((r) => r === Math.round(r)), xfmt: (r) => r + '%', tipx: (r) => `Paying ${r}% of market value`, zero: true,
                none: 'Waiting for prices.', series: c.least ? c.series.map((s) => ({ name: s.name, color: s.color, data: s.data })) : [],
                refs: c.least ? [{ y: c.least, name: `Your least profit, ${hRate(v.prices.least)}%` }] : [],
            });
        }
        if (name === 'share') {
            const days = v.share.days;
            return line({ x: days.map((k) => hDay(k.day)), zero: true, yfmt: (n) => n + '%', left: 44, right: 44, none: 'Kept by day from the first read: this fills as the days pass.', series: [{ name: 'In sets and points', color: 'var(--s-violet)', data: days.map((k) => k.share), area: true }], refs: v.share.max ? [{ y: v.share.max, name: `Your limit, ${v.share.max}%` }] : [] });
        }
        if (name === 'usage') {
            const u = d.usage || {};
            const x = (u.torn || []).map((_, i) => i);
            const last = x.length - 1;
            return line({ x, xfmt: (i) => (last - i ? (last - i) + ' min ago' : 'now'), zero: true, yfmt: count, left: 40, right: 40, none: 'No request yet.', series: [{ name: 'Torn', color: 'var(--s-plush)', data: u.torn || [] }, { name: 'TornW3B', color: 'var(--s-flower)', data: u.w3b || [] }], refs: [{ y: TORN_PER_MINUTE_ALONE, name: `Limit when alone: Torn ${TORN_PER_MINUTE_ALONE}, TornW3B ${W3B_PER_MINUTE_ALONE}` }] });
        }
        return null;
    }

    /* ===== src/ui/hub.js ===== */
    // The hub: Torn Archive's own page. It owns the whole document it is mounted on (never a Torn page).
    // It draws what the engine holds and hands every press back to the engine as an action; it reads nothing and
    // stores nothing itself, save which page you were on and whether the sidebar is pinned.







    // What the drawing's stylesheet has no word for: real boxes to type in, links that look like buttons, an empty graph.
    const HUB_CSS_MORE = `
    input.inp { font: inherit; font-variant-numeric: tabular-nums; outline: 0; min-width: 0; }
    input.inp:focus { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-bg); }
    input.inp::placeholder { color: var(--faint); }
    a.btn { text-decoration: none; }
    .btn[disabled] { opacity: .45; pointer-events: none; }
    .ch-none { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; padding: 0 24px; color: var(--muted); font-size: 12px; }
    .view.still [data-k] *, .view.still [data-k] { animation: none !important; }
    .pill.warn { border-color: rgba(245,165,36,.4); cursor: pointer; }
    .shop.shut .dot { background: var(--faint); } .shop.shut .lab b { color: var(--text2); }
    `;

    const HUB_BOOL = new Set(['open', 'fillMuseum', 'fillPoints', 'sound', 'w3bSync']);
    const HUB_NUM = new Set(['pct', 'least', 'target', 'shareMax', 'readMin', 'beforeEach']);
    const HUB_PIN_KEY = 'tarc-pin';
    /** The piece open on "Sold by" is named to the engine when it changes, and again this often while it stays open. */
    const HUB_LOOK_EVERY_MS = 60 * 1000;
    const HUB_TITLE = 'Torn Archive';

    function hubShell() {
        let nav = '<div class="nav-ind" id="ind"></div>';
        for (const p of HUB_PAGES) {
            if (p.group) nav += `<div class="nav-g"><span class="lab">${p.group}</span></div>`;
            if (p.last) nav += '<span class="sp"></span>';
            nav += `<button class="nav-b" data-go="${p.key}">${hIcon(p.icon)}${p.key === 'trades' ? '<i class="pip" id="nav-pip" hidden></i>' : ''}<span class="lab">${p.title}</span><span class="lab cnt" id="cnt-${p.key}" hidden></span></button>`;
        }
        return `<div class="app" id="app">
    <aside class="side" id="side"><div class="side-in">
      <div class="brand"><div class="mark">${hIcon('brand')}</div><div class="lab"><b>Torn Archive</b><span>Sets and points</span></div><button class="pin lab" id="pin" title="Keep the sidebar open">${hIcon('pin')}</button></div>
      <nav class="nav" id="nav">${nav}</nav>
      <div class="side-f"><div class="shop" id="shop"><span class="dot"></span><span class="lab" id="shop-l"></span></div></div>
    </div></aside>
    <div class="main">
      <header class="top" id="top">
        <h1 id="title"></h1>
        <nav class="tabs" id="tabs"></nav>
        <span class="sp"></span>
        <span class="pill" id="pill-pts"></span>
        <span class="pill opt" id="pill-hand"></span>
        <span class="pill opt" id="pill-vault"></span>
        <span class="pill" id="pill-age"></span>
        <button class="btn" data-act="read">Read now</button>
      </header>
      <div class="view" id="view"></div>
      <footer class="tape"><div class="tape-l">Cheapest now</div><div class="tape-m"><div class="tape-t" id="tape"></div></div></footer>
      <div class="toast" id="toast"><span class="nx-i" style="--c:#c9bfff;--c-bg:var(--brand-bg)">${hIcon('trades')}</span><div><b id="toast-t"></b><span class="s" id="toast-s"></span></div><button class="btn sm go" id="toast-go">See it</button><button class="x" id="toast-x" title="Close">×</button></div>
      <div class="paused" id="paused"><div class="card" id="paused-card"></div></div>
    </div>
    </div>`;
    }

    /**
     * Put the hub on a document and return its handle.
     * @param doc     the document to take over
     * @param actions what a press asks of the engine: set(patch), cart(itemId, place), drop(lineKey), makeList(),
     *                clearList(), run('start' | 'next' | 'stop'), read(), readStock(), copy(text), keySave(kind, value), keyForget(kind),
     *                keyShow(kind), zip(), w3b('send' | 'read'), receipt(tradeId), usageExport(), notifyTest(), here()
     * @returns { show(desk), toast({ title, body, tradeId }), go(page, pane) }
     */
    function mountHub(doc, actions) {
        const win = doc.defaultView;
        const $ = (s, r = doc) => r.querySelector(s);
        const $$ = (s, r = doc) => [...r.querySelectorAll(s)];
        const style = doc.createElement('style');
        style.textContent = HUB_CSS + HUB_CSS_MORE;
        doc.head.appendChild(style);
        doc.body.innerHTML = hubShell();

        const ui = { page: 'dashboard', pane: 0, sel: null, trade: null, range: { pts: 40, pts2: 40 }, unit: 'day', imKey: '' };
        let desk = null;
        let shown = '';
        let tabsShown = '';
        let toastTrade = null;
        let toastT = 0;
        let looked = { id: '', at: 0 };
        const view = $('#view');
        const app = $('#app');
        const side = $('#side');
        const act = (name, ...args) => { try { if (actions && actions[name]) return actions[name](...args); } catch (e) { win.console.error('[Torn Archive]', name, e); } return undefined; };

        // ---- drawing -------------------------------------------------------------------------------------------------

        function drawCharts(anim) {
            for (const el of $$('.chart[data-chart]', view)) {
                if (el.offsetParent === null) continue;
                const c = hubChart(el.dataset.chart, desk, ui);
                if (!c) continue;
                const sig = el.clientWidth + 'x' + el.clientHeight + JSON.stringify(c.cfg);
                if (el._sig === sig && el.firstChild) continue;
                el._sig = sig;
                (c.kind === 'col' ? colChart : lineChart)(el, c.cfg, anim);
            }
        }

        function countUp() {
            if (win.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
            for (const el of $$('.k-v, .hero', view)) {
                const node = el.firstChild;
                if (!node || node.nodeType !== 3) continue;
                const txt = node.textContent;
                const m = txt.match(/[\d,]+/);
                if (!m) continue;
                const to = Number(m[0].replace(/,/g, ''));
                const t0 = win.performance.now();
                const step = (t) => {
                    if (!node.isConnected) return;
                    const k = Math.min(1, (t - t0) / 650);
                    node.textContent = txt.replace(m[0], Math.round(to * (1 - Math.pow(1 - k, 3))).toLocaleString('en-US'));
                    if (k < 1) win.requestAnimationFrame(step);
                };
                win.requestAnimationFrame(step);
            }
        }

        /** The page's string into the view: the whole page when it is another one, else only the parts that differ. */
        function patch(html, fresh) {
            const tpl = doc.createElement('template');
            tpl.innerHTML = html;
            const next = tpl.content.firstElementChild;
            const cur = view.firstElementChild;
            const keyed = (root) => [...root.querySelectorAll('[data-k]')];
            if (!fresh && cur) {
                const a = keyed(cur);
                const b = keyed(next);
                if (a.length === b.length && a.every((el, i) => el.dataset.k === b[i].dataset.k)) {
                    view.classList.add('still');
                    b.forEach((el, i) => {
                        const src = el.innerHTML;
                        if (a[i]._src === src) return;
                        // A box being typed in is left alone until you leave it.
                        const at = doc.activeElement;
                        if (at && at.tagName === 'INPUT' && a[i].contains(at)) return;
                        a[i].innerHTML = src;
                        a[i].className = el.className;
                        a[i]._src = src;
                    });
                    return false;
                }
            }
            view.classList.remove('still');
            view.replaceChildren(next);
            keyed(next).forEach((el) => { el._src = el.innerHTML; });
            $$('.panel', view).forEach((p, k) => p.style.setProperty('--i', k));
            return true;
        }

        function drawShell() {
            const v = desk.view;
            const page = HUB_PAGES.find((p) => p.key === ui.page) || HUB_PAGES[0];
            $('#title').textContent = page.title;
            const tabs = hubTabs(ui.page, desk);
            const tabsHtml = tabs.map((t, i) => `<button class="tab${i === ui.pane ? ' on' : ''}" data-tab="${i}">${hEsc(t)}</button>`).join('');
            if (tabsHtml !== tabsShown) { $('#tabs').innerHTML = tabsHtml; tabsShown = tabsHtml; }
            for (const b of $$('.nav-b')) b.classList.toggle('on', b.dataset.go === ui.page);
            const cur = $('.nav-b.on');
            if (cur) $('#ind').style.transform = `translateY(${cur.offsetTop}px)`;
            const cnt = (key, text, hot) => { const el = $('#cnt-' + key); el.hidden = !text; el.textContent = text || ''; el.classList.toggle('hot', !!hot); };
            cnt('stock', v.nav.full ? v.nav.full + (v.nav.full === 1 ? ' set' : ' sets') : '');
            cnt('buy', v.nav.need ? v.nav.need + ' need' : '');
            cnt('trades', v.nav.trades ? v.nav.trades + ' open' : '', true);
            $('#nav-pip').hidden = !v.nav.hot;
            $('#shop').classList.toggle('shut', !v.shop.open);
            $('#shop-l').innerHTML = `Shop <b>${v.shop.open ? 'Open' : 'Closed'}</b> · ${v.shop.paid || hRate(v.shop.pct) + '%'}`;
            const pts = $('#pill-pts');
            const ptsHtml = v.top.points ? `Points <b class="num">${hMoney(v.top.points)}</b>${v.top.cheap ? '<span class="dn">▼ under its usual level</span>' : ''}` : 'Points <b>not read</b>';
            if (pts._src !== ptsHtml) {
                const flash = pts._src && v.top.points;
                pts.innerHTML = ptsHtml;
                pts._src = ptsHtml;
                if (flash) { pts.classList.remove('flash'); void pts.offsetWidth; pts.classList.add('flash'); }
            }
            const pill = (id, label, n) => { const el = $(id); el.hidden = n == null; if (n != null) el.innerHTML = `${label} <b class="num">${n >= 1e7 ? hShort(n) : hMoney(n)}</b>`; };
            pill('#pill-hand', 'On hand', v.top.onHand);
            pill('#pill-vault', 'Vault', v.top.vault);
            drawAge();
            const tape = v.tape.map((t) => `<span class="tk">${hPic(t.id, t.name, '', (SET_LOOK[t.set] || {}).color || '')}<b>${hEsc(t.name)}</b><span class="num">${hMoney(t.price)}</span></span>`).join('');
            const tapeEl = $('#tape');
            if (tapeEl._src !== tape) { tapeEl.innerHTML = tape + tape; tapeEl._src = tape; }
            doc.title = (v.nav.trades ? `(${v.nav.trades}) ` : '') + HUB_TITLE;
            drawPaused();
            fitTop();
        }

        function drawAge() {
            if (!desk) return;
            const el = $('#pill-age');
            const keys = desk.keys || {};
            const noKey = !(keys.limited && keys.limited.set);
            el.classList.toggle('warn', noKey);
            const html = noKey ? '<b class="dn">No key yet: paste one in Settings</b>' : `<i class="live"></i>Prices <b>${hAge(desk.view.top.pricesAt, Date.now())}</b>`;
            if (el._src !== html) { el.innerHTML = html; el._src = html; }
        }

        function drawPaused() {
            // Another of your tabs has Torn Archive open and does the reading: nothing is asked twice.
            const away = !!desk.elsewhere;
            $('#paused').classList.toggle('on', away);
            if (!away) return;
            const card = $('#paused-card');
            const html = `<h2><span class="dot"></span>Torn Archive is open in another tab.</h2>
        <p>That tab does the reading, so nothing is asked of Torn twice. Go back to it, or go on here.</p>
        <p><button class="btn go" data-act="here">Use this tab</button></p>`;
            if (card._src !== html) { card.innerHTML = html; card._src = html; }
        }

        function fitTop() {
            const t = $('#top');
            t.classList.remove('tight', 'tighter');
            if (t.scrollWidth > t.clientWidth) t.classList.add('tight');
            if (t.scrollWidth > t.clientWidth) t.classList.add('tighter');
        }

        function draw(fresh) {
            if (!desk) return;
            drawShell();
            const html = hubPage(desk, ui);
            // The piece whose sellers are on the screen: its bazaars are checked with Torn itself. Told when the piece
            // changes and once a minute while it stays - never on every draw: until 1.3.0 the telling asked for a draw,
            // and the Buy page drew itself without end.
            if (ui.page === 'buy' && ui.shown) {
                const t = Date.now();
                if (looked.id !== ui.shown || t - looked.at >= HUB_LOOK_EVERY_MS) { looked = { id: ui.shown, at: t }; act('look', ui.shown); }
            } else looked = { id: '', at: 0 };
            if (!fresh && html === shown) { drawCharts(false); return; }
            shown = html;
            const whole = patch(html, fresh);
            if (whole) { view.scrollTop = 0; countUp(); }
            drawCharts(whole);
        }

        /** The address keeps the page. A new page is a new step for the browser's Back; a tab only updates the step it is on. */
        function remember(step) {
            try { win.history[step ? 'pushState' : 'replaceState']({ page: ui.page, pane: ui.pane }, '', '#' + ui.page); } catch { /* a page that cannot keep its address still works */ }
        }

        /** What the address says: '#buy' a page, '#buy/186' the Buy page on one piece. */
        function hashPage() {
            const [page, id] = (win.location.hash || '#dashboard').slice(1).split('/');
            return { page, id: /^\d+$/.test(id || '') ? id : '' };
        }

        function go(page, pane = 0) {
            const was = ui.page;
            ui.page = HUB_PAGES.some((p) => p.key === page) ? page : 'dashboard';
            ui.pane = Math.max(0, Number(pane) || 0);
            remember(ui.page !== was);
            draw(true);
        }

        // Back and Forward: the browser says which step it is on, and that page is shown. Nothing is added to the steps here.
        win.addEventListener('popstate', (e) => {
            const at = e.state || {};
            const page = at.page || hashPage().page;
            ui.page = HUB_PAGES.some((p) => p.key === page) ? page : 'dashboard';
            ui.pane = Math.max(0, Number(at.pane) || 0);
            draw(true);
        });

        // ---- presses ---------------------------------------------------------------------------------------------------

        function setValue(key, raw) {
            if (HUB_BOOL.has(key)) return raw === true || raw === '1' || raw === 1;
            if (HUB_NUM.has(key)) { const n = Number(String(raw).replace(/[^0-9.]/g, '')); return Number.isFinite(n) ? n : 0; }
            return raw;
        }

        function press(el, e) {
            const a = el.dataset.act;
            const v = el.dataset.v;
            const id = el.dataset.id;
            if (a === 'set') act('set', { [id]: setValue(id, v) });
            else if (a === 'which') { const which = { ...desk.view.settings.which }; which[v] = !which[v]; act('set', { which }); }
            else if (a === 'pick') { ui.sel = id; const p = desk.view.pieces.find((x) => String(x.id) === id); go('buy', p && p.need ? 0 : 1); }
            else if (a === 'sel') { ui.sel = id; draw(false); }
            else if (a === 'trade') { ui.trade = id; draw(false); }
            else if (a === 'range') { ui.range[id] = Number(v); draw(false); }
            else if (a === 'unit') { ui.unit = v; draw(false); }
            // Where a list may send you: pressing the only place still lit swaps to the other one, so one is always on.
            else if (a === 'from') { const from = { ...desk.view.settings.from }; from[v] = !from[v]; if (!from.bazaar && !from.market) from[v === 'bazaar' ? 'market' : 'bazaar'] = true; act('set', { from }); }
            else if (a === 'cart') act('cart', id, v);
            else if (a === 'cart-all') act('cartAll', id);
            // A list of this piece alone, and the list is shown: as "Make the list", for one piece.
            else if (a === 'list-only') { act('listOnly', id); go('buy', 2); }
            else if (a === 'drop') act('drop', v);
            else if (a === 'make-list') { act('makeList', v || ''); go('buy', 2); }
            else if (a === 'clear-list') act('clearList');
            // Start and Next are links: the press opens the bazaar itself, here the run only moves on.
            else if (a === 'run') { ui.imKey = ''; act('run', v); }
            // The Item Market stop: the link opened the next piece's page; the run stays on the stop.
            else if (a === 'im-walk') { ui.imKey = v; draw(false); }
            else if (a === 'copy') { act('copy', v); const was = el.textContent; el.textContent = 'Copied ✓'; win.setTimeout(() => { if (el.isConnected) el.textContent = was; }, 1400); }
            else if (a === 'key-save') { const box = $(`input[data-key="${v}"]`); const key = box ? box.value.trim() : ''; if (key) { box.value = ''; act('keySave', v, key); } }
            else if (a === 'key-forget') act('keyForget', v);
            else if (a === 'key-show') act('keyShow', v);
            else if (a === 'server-save') { const at = $('input[data-server="address"]'); const pw = $('input[data-server="pass"]'); act('serverSave', at ? at.value.trim() : '', pw ? pw.value.trim() : ''); if (pw) pw.value = ''; }
            else if (a === 'server-forget') act('serverForget');
            else if (a === 'receipt') act('receipt', id);
            else if (a === 'w3b') act('w3b', v);
            else if (a === 'zip') act('zip');
            else if (a === 'usage-export') act('usageExport');
            else if (a === 'notify-test') act('notifyTest');
            else if (a === 'read') act('read');
            else if (a === 'read-stock') { act('readStock'); const was = el.textContent; el.textContent = 'Asked ✓'; win.setTimeout(() => { if (el.isConnected) el.textContent = was; }, 1400); }
            else if (a === 'here') act('here');
            if (el.tagName !== 'A') e.preventDefault();
        }

        doc.addEventListener('click', (e) => {
            const t = e.target;
            const tab = t.closest('[data-tab]');
            if (tab) { ui.pane = Number(tab.dataset.tab); remember(false); draw(true); return; }
            const a = t.closest('[data-act]');
            if (a) { press(a, e); return; }
            const g = t.closest('[data-go]');
            if (g) go(g.dataset.go, g.dataset.pane);
        });
        doc.addEventListener('change', (e) => {
            const el = e.target;
            if (el.dataset && el.dataset.set) act('set', { [el.dataset.set]: setValue(el.dataset.set, el.value) });
        });
        doc.addEventListener('keydown', (e) => {
            const typing = /INPUT|TEXTAREA|SELECT/.test(e.target.tagName);
            if (typing && e.key === 'Enter') { e.target.blur(); const k = e.target.dataset.key; if (k) { const b = $(`[data-act="key-save"][data-v="${k}"]`); if (b) b.click(); } if (e.target.dataset.server) { const b = $('[data-act="server-save"]'); if (b) b.click(); } return; }
            if (typing || e.ctrlKey || e.metaKey || e.altKey || e.key.toLowerCase() !== 'n' || ui.page !== 'buy') return;
            const next = $('[data-act="im-walk"], [data-act="run"][data-v="next"]', view);
            if (next) next.click();
        });
        // A picture Torn does not serve gives way to the piece's letters.
        doc.addEventListener('error', (e) => { const t = e.target; if (t && t.tagName === 'IMG' && t.dataset.ab != null && t.parentNode) t.parentNode.textContent = t.dataset.ab; }, true);

        // ---- the sidebar, the toast, the clock ---------------------------------------------------------------------------

        let sideT = 0;
        const openSide = (on) => { win.clearTimeout(sideT); sideT = win.setTimeout(() => side.classList.toggle('open', on), on ? 80 : 240); };
        side.addEventListener('mouseenter', () => openSide(true));
        side.addEventListener('mouseleave', () => openSide(false));
        side.addEventListener('focusin', () => openSide(true));
        side.addEventListener('focusout', () => openSide(false));
        const pinned = () => { try { return win.localStorage.getItem(HUB_PIN_KEY) === '1'; } catch { return false; } };
        if (pinned()) app.classList.add('pinned');
        $('#pin').onclick = () => {
            const on = app.classList.toggle('pinned');
            $('#pin').title = on ? 'Let the sidebar close' : 'Keep the sidebar open';
            try { win.localStorage.setItem(HUB_PIN_KEY, on ? '1' : '0'); } catch { /* the pin then lasts until the page closes */ }
        };

        const toastOn = (on) => $('#toast').classList.toggle('on', on);
        $('#toast-x').onclick = () => toastOn(false);
        $('#toast-go').onclick = () => { if (toastTrade) ui.trade = toastTrade; toastOn(false); go('trades'); };
        function toast({ title, body, tradeId }) {
            $('#toast-t').textContent = title || '';
            $('#toast-s').textContent = body || '';
            toastTrade = tradeId || null;
            toastOn(true);
            win.clearTimeout(toastT);
            toastT = win.setTimeout(() => toastOn(false), 9000);
        }

        win.setInterval(drawAge, 1000);
        let rz = 0;
        if (win.ResizeObserver) new win.ResizeObserver(() => { win.clearTimeout(rz); rz = win.setTimeout(() => { if (desk) { drawCharts(false); const cur = $('.nav-b.on'); if (cur) $('#ind').style.transform = `translateY(${cur.offsetTop}px)`; fitTop(); } }, 150); }).observe(view);

        // Opened from a piece of "Your stock" on a Torn page (#buy/<item id>): the Buy page, on that piece.
        const from = hashPage();
        ui.page = from.page;
        if (!HUB_PAGES.some((p) => p.key === ui.page)) ui.page = 'dashboard';
        if (ui.page === 'buy' && from.id) { ui.sel = from.id; ui.arrive = true; }

        return {
            /** @param d { view, keys, usage, turns, busy, notice, version, elsewhere } */
            show(d) {
                const first = !desk;
                desk = d;
                // The piece the address named: its table is the one it is in, as a press on a piece chooses it.
                if (ui.arrive && d.view && d.view.pieces) { ui.arrive = false; const p = d.view.pieces.find((x) => String(x.id) === String(ui.sel)); if (p) ui.pane = p.need ? 0 : 1; else ui.sel = null; }
                draw(first);
            },
            toast,
            go,
        };
    }

    /* ===== src/ui/mask.js ===== */
    /*
     * Masked API key boxes, the same way on every page.
     *
     * A key box must hide what is typed WITHOUT being a password field: Chrome,
     * Edge and password managers offer to save (and sync) whatever is typed in a
     * type="password" box, and a Full key in a synced password store is a key
     * outside our control. So the box is type="text" and CSS hides the letters
     * (-webkit-text-security, which Chrome, Edge and Safari support).
     *
     * Where CSS cannot mask (some Firefox builds), a plain text box would show
     * the key in the clear; there, and only there, it falls back to a password
     * box with saving discouraged (autocomplete off, password-manager opt-outs).
     */

    /** Can this browser hide a text box's letters with CSS? */
    function cssMaskSupported() {
        try {
            return Boolean(
                typeof CSS !== 'undefined' &&
                    CSS.supports &&
                    (CSS.supports('-webkit-text-security', 'disc') || CSS.supports('text-security', 'disc')),
            );
        } catch {
            return false;
        }
    }

    /** The attributes every key box gets: no autofill, no spellcheck, no password-manager capture. */
    function keyInputAttrs() {
        return {
            type: cssMaskSupported() ? 'text' : 'password',
            autocomplete: 'off',
            autocapitalize: 'off',
            autocorrect: 'off',
            spellcheck: 'false',
            'data-lpignore': 'true',
            'data-1p-ignore': 'true',
            'data-bwignore': 'true',
            'data-form-type': 'other',
        };
    }

    /** A revealed saved key is taken out of the box again after this long. */
    const REVEAL_MS = 60000;

    /**
     * Show / hide for one key box.
     *
     * @param {HTMLInputElement} input
     * @param {string} maskedClass - the page's CSS class that hides the letters
     * @param {object} [opts]
     * @param {function} [opts.onReveal] - () => the saved key, put in the box only while shown
     * @param {function} [opts.onChange] - (hidden) => void, e.g. to relabel a Show button
     * @returns {{hidden: function, toggle: function, hide: function}}
     */
    function keyMask(input, maskedClass, { onReveal = null, onChange = () => {} } = {}) {
        const byCss = input.type !== 'password';
        let hidden = true;
        let revealed = false;
        let timer = null;

        const apply = () => {
            if (byCss) input.classList.toggle(maskedClass, hidden);
            else input.type = hidden ? 'password' : 'text';
            onChange(hidden);
        };

        const hide = () => {
            if (timer) clearTimeout(timer);
            timer = null;
            hidden = true;
            // A saved key shown on request never stays in the box: any script
            // that can reach the box could read it.
            if (revealed) {
                input.value = '';
                revealed = false;
            }
            apply();
        };

        const show = () => {
            hidden = false;
            if (!input.value && onReveal) {
                input.value = onReveal() || '';
                revealed = true;
                timer = setTimeout(hide, REVEAL_MS);
            }
            apply();
        };

        if (byCss) input.classList.add(maskedClass);
        return {
            hidden: () => hidden,
            toggle: () => (hidden ? show() : hide()),
            hide,
        };
    }

    /* ===== src/ui/marks-css.js ===== */
    /*
     * The marks Torn Archive puts on Torn's own pages: their CSS, and nothing of
     * the panel or the page.
     *
     * Taken for Torn Archive from Torn Bids 3.24.0 (ui/styles.js, PAGE_CSS), cut
     * to what sources/dom/float.js, the marks on a listing (the deal outline and
     * its label, a trader's tag, the listing a link was opened for) and the Sets
     * marks of sources/dom/sets-pages.js need. Class and attribute names begin
     * tarc- (they were ttv2- there). No token variable is used: every colour is
     * written out, as it was; --tarc-fr is set by float.js and has its fallback.
     *
     * Left behind in PAGE_CSS (Torn Bids' own): the buying-run strip on a card
     * (buybar; its ring came over as tarc-buyhere in 1.2.0), the trade page's send rows and their Fill, the bazaar owner's
     * status, the asking-price chips (bztag, bzchips, bzsell), the price boxes'
     * tones, the Fill button of your bazaar and the Item Market (fillbox, fillbtn,
     * fillmark, filltag, fillset) and the chat mark.
     *
     * The attributes the labels are read from (set by whoever marks the card):
     *   data-tarc-profit       on .tarc-hit: the label's text
     *   data-tarc-trader       on .tarc-trader: the tag's text
     *   data-tarc-trader-old   on .tarc-trader: present = an old list, "aging" = it glows
     */
    const MARKS_CSS = `
    /*
     * Every mark on Torn's own pages takes no room (3.20, the owner: "it
     * shouldn't resize a row, add columns etc. it should just sit at the side or
     * on top like a bring to front"). Outlines are inset box-shadows, labels are
     * pseudo-elements or absolutely placed, and nothing sets a Torn element's
     * size, padding, margin or wrapping. Colours: green money, blue buying and
     * your trade, amber check this, red the listing you opened (Graphite,
     * mockups/T-graphite-everything.html).
     */
    .tarc-hit {
        position: relative !important;

        box-shadow:
            inset 0 0 0 2px #6fdc7f,
            inset 0 0 0 9999px rgba(111, 220, 127, 0.12) !important;

        transition: box-shadow 0.15s ease;
    }

    /*
     * The profit label, drawn as a pseudo-element from a data attribute.
     *
     * pointer-events: none is the important line: it means this can never
     * intercept a click, so it cannot block Torn's Buy button no matter where it
     * lands. That was the original complaint about V1, and it is fixed by making
     * the label unclickable rather than by removing it.
     */
    .tarc-hit.tarc-hit::after {
        /*
         * Every declaration here is load-bearing, and all of it was worked out
         * against a live Torn page rather than guessed.
         *
         * - The doubled class and !important on 'content': Torn defines ::after
         *   on its own item tiles at equal specificity and wins on document
         *   order, so the plain rule computed to content: "" and the label
         *   silently never appeared.
         * - The width/height/inset resets: overriding 'content' alone leaves
         *   Torn's geometry in place, which clipped the label to an 8px sliver.
         * - The chip background: white text alone was invisible against the
         *   tile's artwork.
         * - On the card's top edge, half in the gap above it, one line (3.20.4,
         *   the owner: inside the card it covered the item's name and price).
         */
        content: attr(data-tarc-profit) !important;

        display: block !important;
        position: absolute !important;
        top: -13px !important;
        right: 4px !important;
        left: auto !important;
        bottom: auto !important;

        width: auto !important;
        height: auto !important;
        min-width: 0 !important;
        max-width: none !important;
        margin: 0 !important;
        padding: 1px 7px !important;
        transform: none !important;

        overflow: visible !important;
        white-space: nowrap !important;
        opacity: 1 !important;
        visibility: visible !important;
        z-index: 2147483000 !important;

        background: rgba(15, 36, 20, 0.94) !important;
        border: 1px solid rgba(111, 220, 127, 0.55) !important;
        border-radius: 9px !important;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5) !important;

        color: #6fdc7f !important;
        font: 700 11px/15px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif !important;
        text-align: right !important;

        /* Cannot intercept a click, so it can never block Torn's Buy button. */
        pointer-events: none !important;
    }


    /*
     * A trusted trader pays more than this listing asks: "FAFFO pays $73,500 /
     * +$3,500 each", drawn the same way as the profit label and just as unable
     * to catch a click. In blue (a trader, not an NPC deal); one line on the
     * card's top edge (3.20.4). On a card that is also a deal, profit and
     * trader share that one line.
     */
    .tarc-trader {
        position: relative !important;
    }

    .tarc-trader.tarc-trader::after {
        content: attr(data-tarc-trader) !important;

        display: block !important;
        position: absolute !important;
        top: -13px !important;
        right: 4px !important;
        left: auto !important;
        bottom: auto !important;

        width: auto !important;
        height: auto !important;
        min-width: 0 !important;
        max-width: none !important;
        margin: 0 !important;
        padding: 2px 7px !important;
        transform: none !important;

        overflow: visible !important;
        white-space: nowrap !important;
        text-align: right !important;
        opacity: 1 !important;
        visibility: visible !important;
        z-index: 2147483000 !important;

        background: rgba(15, 26, 42, 0.94) !important;
        border: 1px solid rgba(90, 167, 255, 0.5) !important;
        border-radius: 9px !important;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5) !important;

        color: #8cc0ff !important;
        font: 700 11px/15px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif !important;

        pointer-events: none !important;
    }

    .tarc-hit.tarc-trader.tarc-trader::after {
        content: attr(data-tarc-profit) "  ·  " attr(data-tarc-trader) !important;
        white-space: nowrap !important;
        text-align: right !important;
        background: rgba(15, 36, 20, 0.94) !important;
        border-color: rgba(111, 220, 127, 0.55) !important;
        color: #6fdc7f !important;
    }

    /*
     * That trader's price is from a TornW3B list not changed in over 24 hours
     * (3.23.0): an amber dot inside the tag, at its start - drawn as the tag's
     * own background, so nothing is added to Torn's card and the tag stays one
     * line. Until two days the tag also glows amber, slowly (a filter: nothing
     * of the page is laid out again); past two days the dot alone.
     */
    .tarc-trader.tarc-trader.tarc-trader[data-tarc-trader-old]::after {
        padding-left: 20px !important;
        background-image: radial-gradient(circle closest-side, #f6b74a 0, #f6b74a 86%, rgba(246, 183, 74, 0) 100%) !important;
        background-repeat: no-repeat !important;
        background-size: 7px 7px !important;
        background-position: 7px 50% !important;
    }

    .tarc-trader.tarc-trader.tarc-trader[data-tarc-trader-old="aging"]::after {
        animation: tarc-oldlist 1.6s ease-in-out infinite;
    }

    @keyframes tarc-oldlist {
        0%, 100% { filter: drop-shadow(0 0 0 rgba(246, 183, 74, 0)); }
        50% { filter: drop-shadow(0 0 4px rgba(246, 183, 74, 0.95)); }
    }

    /*
     * Fill on the trade page: floats beside the item's name (3.20). Taken out of
     * the line, so Torn's name cell keeps its size and its wrapping; placed by
     * main.js placeFloat where the cell lays its items out as a row.
     */
    .tarc-float {
        position: absolute !important;
        z-index: 3;
        box-sizing: border-box;
        white-space: nowrap !important;
    }

    /*
     * Sets (3.24.0, mockups Z6-Z10): a mark on a museum piece, a bazaar card, an item in a trade or your forum
     * thread's title. Absolutely placed in Torn's element, so it takes no room; it catches no click.
     */
    .tarc-setmark {
        top: -9px;
        left: 4px;
        height: 18px;
        padding: 0 7px;
        border: 1px solid rgba(90, 167, 255, 0.55);
        border-radius: 9px;
        background: #10233b;
        color: #cfe5ff;
        font: 600 11px/16px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
        font-variant-numeric: tabular-nums;
        letter-spacing: 0;
        text-transform: none;
        pointer-events: none;
        box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
    }
    .tarc-setmark[data-where="right"] { top: 50%; left: auto; right: 8px; transform: translateY(-50%); }
    .tarc-setmark[data-where="under"] { top: calc(100% - 4px); left: 4px; }
    .tarc-setmark[data-where="tile"] { top: auto; bottom: 2px; left: 2px; }
    /* Beside one of Torn's controls (the points market's ADD LISTING): its left and top are set by measure. */
    .tarc-setmark[data-where="note"] { height: 22px; padding: 0 10px; border-radius: 11px; font-size: 12px; line-height: 20px; transform: translateY(-50%); }
    .tarc-setmark[data-state="top"] { border-color: #5aa7ff; background: #173a63; color: #fff; box-shadow: 0 0 0 1px #5aa7ff, 0 0 10px rgba(90, 167, 255, 0.5); }
    .tarc-setmark[data-state="ok"] { border-color: rgba(160, 168, 184, 0.45); background: #1c2029; color: #c3c9d4; }
    .tarc-setmark[data-state="ahead"] { border-color: rgba(246, 183, 74, 0.6); background: #33260c; color: #ffd98a; }
    /* More typed than you need: red (the owner, 2026-10-11: "a warning that turns red if im buying more than i need"). */
    .tarc-setmark[data-state="over"] { border-color: rgba(255, 120, 120, 0.7); background: #3a1414; color: #ffc9c9; }
    .tarc-setmark[data-state="bad"] { border-color: rgba(255, 120, 120, 0.6); background: #3a1414; color: #ffc9c9; }
    .tarc-setmark[data-state="good"] { border-color: rgba(111, 220, 127, 0.55); background: #12301a; color: #b9f3c2; }

    /*
     * A listing to buy for your sets, ringed as Torn Trading rings the listing to buy for a trade (the same blue,
     * the same glow). Paint only: nothing of Torn's card is sized or moved.
     *   data-tarc-ring="top"   on your list: the full ring and its glow
     *   data-tarc-ring="need"  a piece you need, under its worth, not on the list: thinner, no glow
     *   data-tarc-ring="over"  you are typing more than you need: amber
     */
    .tarc-buyhere {
        position: relative !important;
        box-shadow:
            inset 0 0 0 2px #5aa7ff,
            inset 0 0 0 9999px rgba(90, 167, 255, 0.12),
            0 0 14px rgba(90, 167, 255, 0.35) !important;
        transition: box-shadow 0.15s ease;
    }
    .tarc-buyhere[data-tarc-ring="need"] {
        box-shadow:
            inset 0 0 0 1px #5aa7ff,
            inset 0 0 0 9999px rgba(90, 167, 255, 0.06) !important;
    }
    .tarc-buyhere[data-tarc-ring="over"] {
        box-shadow:
            inset 0 0 0 2px #ff7878,
            inset 0 0 0 9999px rgba(255, 120, 120, 0.12) !important;
    }

    /*
     * A listing that pulses: an outline, so it takes no room, catches no click and leaves the ring's own paint alone.
     *   data-tarc-pulse="link"  the listing a link of ours named (the hub's "Sold by", a stop of your run), until you
     *                           press anything
     *   data-tarc-pulse="buy"   a listing still to buy here, once you pressed Fill or Fill all (1.3.0: "can it
     *                           pulsate a bit? on the items i need to buy"), until it is bought
     *   data-tarc-pulse="aim"   the listing the Down key, or a buy, brought you to: for a few seconds
     */
    [data-tarc-pulse] { outline: 2px solid rgba(90, 167, 255, 0.95); outline-offset: 1px; animation: tarc-pulse 1.1s ease-in-out infinite; }
    @keyframes tarc-pulse { 0%, 100% { outline-color: rgba(90, 167, 255, 0.95); outline-offset: 1px; } 50% { outline-color: rgba(90, 167, 255, 0.25); outline-offset: 5px; } }
    @media (prefers-reduced-motion: reduce) { [data-tarc-pulse] { animation: none; } }

    /*
     * The points market (mockup Z7): a hairline in Torn's list, on the edge between two rows - where your listing
     * would sit (blue), above which a price is under the usual (amber) or a loss (red). Two pixels on the rows' own
     * border and no words: it stands on nothing of Torn's (the owner: a thicker line "blocks the torn page").
     * Everything a row of Torn's could hand down to it is set here, so it is two pixels on any page.
     */
    .tarc-setrule {
        display: block !important;
        top: -1px !important;
        left: 0 !important;
        right: 0 !important;
        bottom: auto !important;
        width: auto !important;
        min-width: 0 !important;
        height: 2px !important;
        min-height: 0 !important;
        max-height: 2px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        float: none !important;
        font-size: 0 !important;
        line-height: 0 !important;
        background: #5aa7ff !important;
        box-shadow: none !important;
        pointer-events: none !important;
    }
    .tarc-setrule[data-state="ahead"] { background: #f6b74a !important; }
    .tarc-setrule[data-state="bad"] { background: #ff7878 !important; }

    /* Fill beside Torn's own box on the museum and the points market: it types, you press Torn's button. */
    .tarc-setfill {
        top: 50%;
        left: calc(100% + 8px);
        transform: translateY(-50%);
        height: 24px;
        padding: 0 10px;
        border: 1px solid rgba(90, 167, 255, 0.55);
        border-radius: 7px;
        background: #10233b;
        color: #cfe5ff;
        font: 600 11px/22px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
        font-variant-numeric: tabular-nums;
        cursor: pointer;
    }
    .tarc-setfill:hover { background: #173a63; color: #fff; }
    .tarc-setfill[data-done="1"] { border-color: rgba(111, 220, 127, 0.55); background: #12301a; color: #b9f3c2; }

    /* Why a price box on your bazaar's add page is red or amber, and a piece kept for sets (no Fill). */
    .tarc-tonetag, .tarc-keptnote {
        height: 16px;
        padding: 0 6px;
        border-radius: 8px;
        font: 600 10px/16px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
        pointer-events: none;
        box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
    }
    .tarc-tonetag { top: calc(100% - 6px); right: 2px; background: #33260c; color: #ffd98a; border: 1px solid rgba(246, 183, 74, 0.6); }
    .tarc-tonetag[data-tone="under"] { background: #3a1414; color: #ffc9c9; border-color: rgba(255, 120, 120, 0.6); }
    .tarc-keptnote.tarc-fillcell { margin-left: 0; white-space: nowrap; }
    .tarc-keptnote { margin-left: 8px; background: #1c2029; color: #c3c9d4; border: 1px solid rgba(160, 168, 184, 0.45); }

    /* The listing a feed link was opened for: light red (3.14.2, the owner; it was yellow). Paint-only, like .tarc-hit. */
    .tarc-target {
        box-shadow:
            inset 0 0 0 2px #ff7b6e,
            inset 0 0 0 9999px rgba(255, 123, 110, 0.12) !important;
    }

    .tarc-hit-top {
        box-shadow:
            inset 0 0 0 2px #a6f5b0,
            inset 0 0 0 9999px rgba(111, 220, 127, 0.2),
            0 0 12px rgba(111, 220, 127, 0.35) !important;
    }

    .tarc-hit-top.tarc-hit-top::after {
        background: #6fdc7f !important;
        border-color: transparent !important;
        color: #0d1a10 !important;
    }

    /*
     * Profitable, but below your Min: amber, thinner and fainter than green, so
     * the deals that meet your Min still stand out first. (Light red marks the
     * listing a panel link was opened for.)
     */
    .tarc-hit.tarc-hit-low {
        box-shadow:
            inset 0 0 0 1px #f6b74a,
            inset 0 0 0 9999px rgba(246, 183, 74, 0.08) !important;
    }

    .tarc-hit.tarc-hit-low.tarc-hit-low::after {
        background: rgba(42, 33, 16, 0.94) !important;
        border-color: rgba(246, 183, 74, 0.5) !important;
        color: #f6b74a !important;
        font-weight: 700 !important;
    }

    /*
     * Your own bazaar's manage rows and the Item Market's: the asking prices
     * and Fill, together in one group that floats in the row (3.20): at its
     * right, just left of Torn's boxes, centred on the row - over the row, never
     * a line or a column of its own. Text only; nothing is clicked on Torn's.
     */
    .tarc-rowfloat {
        position: absolute !important;
        top: 50%;
        right: var(--tarc-fr, 8px);
        z-index: 3;
        display: inline-flex !important;
        align-items: center;
        gap: 6px;
        margin: 0 !important;
        transform: translateY(-50%);
        white-space: nowrap;
    }

    /* Fill's result, beside Torn's page for a few seconds (3.20): in place of the line it used to add to the row. */
    .tarc-toast {
        position: fixed;
        z-index: 2147483001;
        max-width: 400px;
        padding: 8px 12px;
        border: 1px solid rgba(111, 220, 127, 0.42);
        border-radius: 10px;
        background: #1c1e23;
        color: #cdd2db;
        font: 12px/1.5 "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
        box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 12px 32px rgba(0, 0, 0, 0.35);
        pointer-events: none;
        animation: tarc-toast-in 0.2s cubic-bezier(0.2, 0.7, 0.2, 1);
    }

    .tarc-toast[data-level="warn"] { border-color: rgba(246, 183, 74, 0.42); color: #f6b74a; }
    .tarc-toast[data-level="bad"] { border-color: rgba(255, 123, 110, 0.42); color: #ff7b6e; }

    @keyframes tarc-toast-in {
        from { opacity: 0; transform: translateY(4px); }
        to { opacity: 1; transform: none; }
    }

    @media (prefers-reduced-motion: reduce) {
        .tarc-toast { animation: none !important; }
        .tarc-trader.tarc-trader.tarc-trader[data-tarc-trader-old]::after { animation: none !important; }
        .tarc-hit, .tarc-buyhere { transition: none !important; }
    }
    `;

    /* ===== src/ui/box-css.js ===== */
    // The overlay on Torn's pages, in the hub's look. It lives in a shadow root of its own host (#tarc-host), so
    // none of this reaches Torn's page and none of Torn's styles reach it.

    /** With no room beside Torn's content it is a pill; opened from there it stands this far from the window's edge. */
    const BOX_GAP = 12;

    const BOX_CSS = `
    :host {
      --panel: #10131a; --raised: #171b24; --input: #0a0c11; --rail-bg: #0c0f15;
      --line: rgba(255,255,255,.07); --line2: rgba(255,255,255,.13);
      --text: #f3f5f9; --text2: #c9cfda; --muted: #8e96a6; --faint: #626a7a;
      --brand: #8f7bff; --good: #3fcf6b; --warn: #f5a524; --warn-bg: rgba(245,165,36,.12);
      --need: #4c9dff; --need-bg: rgba(76,157,255,.12); --good-bg: rgba(63,207,107,.12);
      --sans: "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
      --disp: "Segoe UI Variable Display", "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
      all: initial;
    }
    * { box-sizing: border-box; }
    .ta { position: fixed; z-index: 99990; top: var(--top, 84px); left: var(--left, 12px); width: var(--width, 430px);
      max-height: var(--max-h, 640px); display: flex; flex-direction: column; border-radius: 12px; background: var(--panel);
      border: 1px solid var(--line2); box-shadow: 0 16px 40px rgba(0,0,0,.5); color: var(--text); font: 400 13px/1.45 var(--sans);
      -webkit-font-smoothing: antialiased; overflow: hidden; text-align: left; container: ta / inline-size; }
    .ta[hidden], .pill[hidden] { display: none; }
    .ta-h { display: flex; align-items: center; gap: 8px; min-height: 38px; flex: none; padding: 4px 6px 4px 8px; border-bottom: 1px solid var(--line); background: var(--rail-bg); white-space: nowrap; cursor: grab; user-select: none; -webkit-user-select: none; touch-action: none; }
    /* A narrow strip (the free window beside Torn's content on a smaller screen): the mark alone names it, so the words
       have the room; what does not fit on one line takes two, never cut. */
    @container ta (max-width: 300px) { .ta-h { gap: 6px; } .ta-h > b { display: none; } .ta-h button.open { padding: 0 8px; } }
    .ta.drag .ta-h { cursor: grabbing; } .ta.drag { transition: none; }
    /* Folded, or with room for the bar only: the bar. */
    .ta.folded .ta-b, .ta.bar .ta-b { display: none; } .ta.folded .ta-h, .ta.bar .ta-h { border-bottom: 0; }
    .mark { width: 24px; height: 24px; flex: none; border-radius: 7px; display: grid; place-items: center; color: #fff; background: linear-gradient(145deg, #a694ff, #6a55e8); box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset; }
    .mark svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    .ta-h b { font: 650 13px var(--disp); }
    .ta-h .w { flex: 1; min-width: 0; color: var(--muted); font-size: 12px; line-height: 1.25; white-space: normal; overflow-wrap: anywhere; }
    .ta-h button { width: 28px; height: 28px; flex: none; display: grid; place-items: center; border: 0; border-radius: 8px; background: none; color: var(--muted); cursor: pointer; font: 600 14px/1 var(--sans); }
    .ta-h button:hover { background: var(--raised); color: var(--text); }
    .ta-h button.open { width: auto; height: 26px; padding: 0 11px; border: 1px solid var(--line2); background: var(--raised); color: var(--text); font: 550 12px/1 var(--sans); }
    .ta-h button.open:hover { background: #1c212c; }
    /* Purple only when opening the hub is the thing to do next. */
    .ta-h button.open.go { background: var(--brand); border-color: transparent; color: #fff; } .ta-h button.open.go:hover { background: #a08fff; }
    .ta-b { display: grid; gap: 8px; padding: 10px 12px 12px; overflow-y: auto; overscroll-behavior: contain; }
    /* The scrollbar: a thin line with no arrows, and only while your pointer is on the box (the owner, 2026-10-11:
       "that scroll bar always visible is annoying"). The list still scrolls by the wheel when it is not shown. */
    .ta-b::-webkit-scrollbar { width: 6px; } .ta-b::-webkit-scrollbar-track { background: transparent; }
    .ta-b::-webkit-scrollbar-thumb { background: transparent; border-radius: 3px; }
    .ta:hover .ta-b::-webkit-scrollbar-thumb { background: rgba(255,255,255,.2); } .ta:hover .ta-b::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.34); }
    @supports not selector(::-webkit-scrollbar) { .ta-b { scrollbar-width: thin; scrollbar-color: transparent transparent; } .ta:hover .ta-b { scrollbar-color: rgba(255,255,255,.2) transparent; } }
    .ta-b h4 { margin: 0; display: flex; align-items: baseline; gap: 8px; font: 650 13px var(--sans); white-space: nowrap; }
    .ta-b h4 span { margin-left: auto; color: var(--muted); font-weight: 400; font-size: 12px; }
    .ta-l { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 2px 8px; padding: 6px 8px; border-radius: 9px; background: var(--raised); border: 1px solid var(--line); }
    .ta-l b { font-weight: 600; } .ta-l .s { grid-column: 1 / -1; color: var(--muted); font-size: 12px; } .ta-l.dim b { color: var(--muted); font-weight: 500; }
    /* A checklist line: the tick, then the piece; under it what you hold of it against your target. */
    .ta-l .lead { display: inline-flex; align-items: center; gap: 7px; }
    .tk { width: 16px; height: 16px; flex: none; display: grid; place-items: center; border-radius: 5px; border: 1.5px solid var(--line2); color: transparent; font: 700 11px/1 var(--sans); }
    .ta-l.done { background: none; } .ta-l.done b { color: var(--text2); font-weight: 500; } .ta-l.done .num { color: var(--good); }
    .ta-l.done .tk { background: var(--good); border-color: transparent; color: #0b130d; }
    .ta-l.away { background: none; border-style: dashed; } .ta-l.away b { color: var(--text2); }
    .ta-l .hold { display: flex; align-items: center; gap: 8px; white-space: nowrap; } .ta-l .hold b { color: var(--text2); }
    .bar { flex: 1; height: 4px; border-radius: 2px; background: rgba(255,255,255,.08); overflow: hidden; }
    /* What you hold of a piece against what you build (the owner, 2026-10-11: "red for we have too much, orange we
       still need more, and green we have enough exactly"): the same three colours as the hub's Stock page. */
    .bar i { display: block; height: 100%; width: var(--w); border-radius: 2px; background: var(--warn); transition: width .3s ease; } .bar.full i { background: var(--good); }
    .it { width: 38px; height: 19px; flex: none; display: inline-grid; place-items: center; }
    .it img { width: 38px; height: 19px; object-fit: contain; display: block; }
    .ta-kv { display: flex; align-items: baseline; gap: 10px; font-size: 12px; color: var(--muted); }
    .ta-kv > :last-child { margin-left: auto; color: var(--text); text-align: right; }
    .ta-kv.sep { padding-top: 8px; border-top: 1px solid var(--line); }
    .ta-n { color: var(--muted); font-size: 12px; line-height: 1.5; } .ta-n b { color: var(--text2); font-weight: 600; }
    .ta-hold, .ta-warn { padding: 8px 10px; border-radius: 9px; background: var(--warn-bg); border: 1px solid rgba(245,165,36,.4); color: var(--text2); font-size: 12px; line-height: 1.5; }
    .ta-hold b { color: var(--warn); font-weight: 600; }
    .ta-ok { padding: 8px 10px; border-radius: 9px; background: var(--good-bg); border: 1px solid rgba(63,207,107,.35); color: var(--text2); font-size: 12px; line-height: 1.5; }
    .msg { padding: 7px 10px; border-radius: 10px; background: var(--input); border: 1px solid var(--line); color: var(--text2); font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }
    .ta-btns { display: flex; gap: 6px; flex-wrap: wrap; } .ta-btns:empty { display: none; } .ta-btns.late { margin-top: 6px; }
    /* The keys, in one line: each key's cap, then what it does. */
    .ta-n.keys { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 0; } .ta-n.keys .kbd { margin: 0 5px 0 12px; background: rgba(255,255,255,.12); color: var(--text2); } .ta-n.keys .kbd:first-child { margin-left: 0; }
    .btn { height: 26px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--line2); background: var(--raised); color: var(--text); font: 550 12px/1 var(--sans); display: inline-flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap; cursor: pointer; }
    .btn:hover { background: #1c212c; }
    .btn.go { background: var(--brand); border-color: transparent; color: #fff; } .btn.go:hover { background: #a08fff; }
    .btn.link { background: var(--need-bg); border-color: transparent; color: #9cc6ff; }
    .btn[data-done] { background: var(--good-bg); border-color: rgba(63,207,107,.35); color: var(--good); }
    .kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; margin-left: 2px; padding: 0 4px; border-radius: 5px; background: rgba(255,255,255,.22); font: 650 12px/1 var(--sans); }
    .lk { color: #9cc6ff; cursor: pointer; text-decoration: none; } .lk:hover { color: #c9bfff; }
    .num { font-variant-numeric: tabular-nums; }
    .t-good { color: var(--good); } .t-bad { color: #ff8a87; }
    /* Your stock, on its own beside the page: a row a piece, its count moving as you buy. Red = more than you need. */
    .st-r { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 1px 8px; padding: 3px 8px; border-radius: 8px; border: 1px solid transparent; }
    .st-r .n { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text2); } .st-r.here .n { color: var(--text); font-weight: 600; }
    .st-r .x { grid-column: 2; color: var(--muted); font-size: 11.5px; white-space: nowrap; } .st-r .bar { grid-column: 3; width: 54px; flex: none; }
    .st-r.need .x { color: var(--warn); } .st-r.ahead .x { color: #ff8a87; } .st-r.ok .x { color: var(--good); }
    .st-r.ahead .bar i, .st-r.ahead .bar.full i { background: #ff7878; }
    .st-r.over { background: rgba(255, 90, 90, .13); border-color: rgba(255, 120, 120, .55); } .st-r.over .x, .st-r.over b { color: #ff8a87; font-weight: 600; } .st-r.over .bar i { background: #ff7878; }
    .ta-hold.st-over { background: rgba(255, 90, 90, .13); border-color: rgba(255, 120, 120, .55); } .ta-hold.st-over b { color: #ff8a87; }
    .ta.ts .ta-b { gap: 3px; } .ta.ts .ta-b h4 { margin-top: 5px; }
    /* A piece is a press: Torn Archive opens on it, where its sellers are and the list is made. */
    .st-r[data-act] { cursor: pointer; } .st-r[data-act]:hover { background: var(--raised); } .st-r.over[data-act]:hover { background: rgba(255, 90, 90, .2); }
    .pill { position: fixed; z-index: 99990; right: 12px; bottom: 56px; height: 34px; padding: 0 12px 0 6px; display: inline-flex; align-items: center; gap: 8px; border-radius: 999px;
      border: 1px solid var(--line2); background: var(--panel); color: var(--text); font: 600 12px/1 var(--sans); box-shadow: 0 8px 24px rgba(0,0,0,.5); cursor: pointer; white-space: nowrap; }
    .pill:hover { background: var(--raised); }
    @media (prefers-reduced-motion: no-preference) { .ta { animation: ta-in .18s cubic-bezier(.2,.8,.2,1); } @keyframes ta-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } } }
    `;

    /** Our marks on Torn's own elements: the pill of the drawing, a little larger than the copy we started from. */
    const BOX_MARKS_CSS = `
    .tarc-setmark { height: 20px; padding: 0 8px; border-radius: 999px; font: 600 12px/18px "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, Arial, sans-serif; top: -11px; }
    `;

    /* ===== src/ui/box-pages.js ===== */
    // What the small box on Torn's pages says, and what each mark says: worked out from the view the hub shares and
    // from what the page in front of you holds. Strings and plain data only; ui/torn-page.js puts them on the page.
    // Nothing here presses anything of Torn's: a button either types into a box of Torn's on your press (Fill),
    // copies text, or opens one page.








    const bxKv = (l, r, cls = '') => `<div class="ta-kv ${cls}"><span>${l}</span><b class="num">${r}</b></div>`;
    const bxNote = (t) => `<div class="ta-n">${t}</div>`;

    /** The hub shares its numbers at least once a minute. Silent for longer than this, a Torn tab says how old they are. */
    const VIEW_LATE_MS = 3 * 60 * 1000;
    /**
     * '' while the hub answers. Else one line, first in the box: since when it has not - by the whole minute, so the box
     * is not drawn again every second. (Past VIEW_OLD_MS no number is shown at all: boxClosed.)
     */
    function boxLate(at, now) {
        if (!(at > 0) || !(now - at > VIEW_LATE_MS)) return '';
        return `<div class="ta-hold"><b>The hub last answered ${Math.floor((now - at) / 60000)} min ago.</b> These numbers are from then. Open its tab and they are current again.</div>`;
    }
    const bxBtn = (act, label, cls = '', v = '', more = '') => `<button class="btn sm ${cls}" data-act="${act}"${v !== '' ? ` data-v="${hEsc(v)}"` : ''}${more}>${label}</button>`;
    const bxHead = (title, right = '') => `<h4>${title}<span>${right}</span></h4>`;

    /** While the hub has not shared anything yet, or what it shared is old. */
    function boxWaiting(old) {
        return { where: '', html: bxNote(old ? 'Torn Archive is not open: these numbers would be old. <b>Open the hub</b> and they come back.' : 'Open the hub once: your sets are worked out there, and shown here.'), marks: [] };
    }

    /**
     * The hub is not open, or was never set up: no number is shown, it would be old. `go`: Open is the thing to do.
     * @param setUp a key has been pasted
     * @param old   the hub shared something once
     */
    function boxClosed(setUp, old) {
        if (!setUp) return { head: 'not set up yet', go: true, where: '', html: bxNote('Torn Archive has no key yet. <b>Open</b> it and paste one in Settings: nothing is read before that.'), marks: [] };
        return { ...boxWaiting(old), head: 'hub is closed', go: true };
    }

    /**
     * A buy a Torn page told of that Torn's log does not have: the hub took it back, and it is said here for as long as
     * the hub says it (a few minutes), in one line.
     */
    function bxBack(v) {
        const rows = (v.buy && v.buy.back) || [];
        if (!rows.length) return '';
        const one = rows.length === 1;
        return `<div class="ta-hold"><b>Not ${one ? 'a buy' : 'buys'} after all: ${rows.map((b) => `${hNum(b.qty)} × ${hEsc(b.name || 'item ' + b.id)}`).join(', ')}.</b> Torn's log has no such buy, so ${one ? 'it is' : 'they are'} taken back: off your stock, the run and the list.</div>`;
    }

    /**
     * A listing's price against its piece, in the list's three groups (core/setjudge.js): under the piece's own worth,
     * over it and carried by its set (Buy), a Stretch, or over all of them.
     */
    const bxWorth = (p, price) => (price < p.worth ? `worth ${hMoney(p.worth)} to you`
        : price < p.line ? `over its own worth ${hMoney(p.worth)}: its set carries it`
        : price < p.lineS ? `a Stretch: it pays with points at ${hMoney(p.needs)} or more`
        : 'over what its set can carry');

    /** A page of Torn's that is none of ours, while the hub is open: your sets, and what waits for you. */
    function boxAny(v) {
        const full = v.sets.reduce((n, s) => n + s.full, 0);
        let html = bxBack(v) + bxHead('Your sets', hPlural(full, 'full set'));
        for (const s of v.sets) {
            const short = s.pieces[0];
            const need = s.pieces.reduce((n, p) => n + p.need, 0);
            html += `<div class="ta-l"><b>${hEsc(s.label)} Set</b><span></span><b class="num">${hNum(s.full)} full</b>`
                + `<span class="s">${short ? `Shortest: ${hEsc(short.short)} ${hNum(short.held)} · ` : ''}${need ? hPlural(need, 'piece') + ' short' : 'nothing short'}</span></div>`;
        }
        if (v.buy.units) html += bxKv('Your shopping list', `${hPlural(v.buy.units, 'piece')} · ${hPlural(v.buy.run.stops.length, 'stop')}`);
        if (v.trades.open.length) html += bxKv('Trades open with you', hNum(v.trades.open.length));
        return { head: full ? `${hPlural(full, 'set')} ready` : 'no full set yet', where: '', html, marks: [] };
    }

    /** One line of the checklist: the tick, the piece, how many, and under it what you hold of it against your target. */
    function bxCheck(p, { n, right = '', cls = '', sub = '', held, act = '' }) {
        const target = p.target || 0;
        const w = target ? Math.min(100, Math.round(held / target * 100)) : 0;
        return `<div class="ta-l ck ${cls}"><span class="lead"><span class="tk">✓</span>${hPic(p.id, p.name)}</span><b>${hEsc(p.name)}${n ? ' ×' + hNum(n) : ''}</b><b class="num">${right}</b>`
            + (sub ? `<span class="s">${sub}</span>` : '')
            + `<span class="s hold">You hold <b class="num">${hNum(held)}</b>${target ? ` of ${hNum(target)}` : ''}<span class="bar ${target && held >= target ? 'full' : ''}"><i style="--w:${w}%"></i></span></span>`
            + (act ? `<span class="s">${act}</span>` : '') + '</div>';
    }

    /**
     * Your stock on its own, beside Torn's page while you buy (the owner, 2026-10-11: "my separate overlay with live
     * tracking ... a warning that turns red if im buying more than i need"). Every piece of the sets you build: what
     * you hold now - a buy seen here a moment ago counted in - against what the set needs. A piece turns red when the
     * number in its open Buy box is more than you need.
     * @param live { pend: { itemId: units }, typed: { itemId: units in an open Buy box here }, here: [itemId on this page] }
     * @returns { head, html, over: [{ id, name, typed, need }] }
     */
    function boxStock(v, live = {}) {
        const pend = live.pend || {};
        const typed = live.typed || {};
        const here = new Set((live.here || []).map(String));
        const whole = (n) => Math.max(0, Math.floor(Number(n) || 0));
        const over = [];
        let togo = 0;
        let body = '';
        for (const s of v.sets) {
            let full = Infinity;
            let rows = '';
            for (const p of s.pieces) {
                const id = String(p.id);
                const held = p.held + whole(pend[id]);
                const target = Math.max(0, p.held + p.need - p.ahead);
                const need = Math.max(0, target - held);
                const t = whole(typed[id]);
                const more = t > need ? t - need : 0;
                if (more) over.push({ id, name: p.name, typed: t, need });
                togo += need;
                full = Math.min(full, held);
                const cls = more ? 'over' : need > 0 ? 'need' : held > target ? 'ahead' : 'ok';
                const say = more ? `typing ${hNum(t)} · ${hNum(more)} too many` : t ? `typing ${hNum(t)} of ${hNum(need)}` : need > 0 ? `need ${hNum(need)}` : held > target ? `${hNum(held - target)} ahead` : 'enough';
                const w = target ? Math.min(100, Math.round((held / target) * 100)) : 100;
                rows += `<div class="st-r ${cls}${here.has(id) ? ' here' : ''}" data-act="plan" data-v="${hEsc(id)}" title="Open Torn Archive on ${hEsc(p.name)}: who sells it, and your shopping list">${hPic(p.id, p.name)}<span class="n">${hEsc(p.short || p.name)}</span><b class="num">${hNum(held)}</b><span class="x">${say}</span><span class="bar ${target && held >= target ? 'full' : ''}"><i style="--w:${w}%"></i></span></div>`;
            }
            body += bxHead(`${hEsc(s.label)} sets`, `${hNum(Number.isFinite(full) ? full : 0)} full of ${hNum(s.target)}`) + rows;
        }
        const warn = over.length ? `<div class="ta-hold st-over"><b>More than you need.</b> ${over.map((o) => `${hEsc(o.name)}: ${hNum(o.typed)} typed, ${o.need ? `you need ${hNum(o.need)}` : 'you need no more'}`).join(' · ')}</div>` : '';
        // When Torn counted, so "Read" says what it brought: Torn counts your items once an hour, and a read in
        // between brings that same count. What you buy in between is counted here, from the pages you buy on.
        const age = (v.top && v.top.stock) || null;
        const foot = age && age.tornAt ? `<div class="ta-n">Torn counted your items at ${hClock(age.tornAt)} and counts again at ${hClock(age.nextAt)}. Your buys since are counted in.</div>`
            : age && age.readAt ? `<div class="ta-n">Your items were read at ${hClock(age.readAt)}. Torn counts them once an hour; your buys since are counted in.</div>` : '';
        return { head: over.length ? 'more than you need' : togo ? `${hNum(togo)} to go` : 'every piece is in', html: warn + body + foot, over };
    }

    /**
     * Someone's bazaar, or the Item Market: the checklist of what to buy here, each piece with what you hold of it.
     * @param cards [{ itemId, price, qty, typed, hasBox }] the listings on the page, in page order
     * @param place 'b:' + the owner's id, or 'im'
     * @param live  what this tab saw that the shared view does not hold yet, so the box moves the moment you buy:
     *              pend { itemId: units } bought here and not in the view yet, took { itemId: units } bought here on
     *              this visit, fillAll (Fill all is on), itemId (the Item Market: the piece its address names),
     *              gone (a Set of piece ids proven or marked gone from this bazaar), late (a press of Start, Next or
     *              Stop made in a box still waits for the hub)
     * @returns null when nothing here is yours to buy and no run is on; else { where, head, html,
     *          marks: [{ i, text, state, ring }], fill: [{ i, n }] the number Fill all types into each card's box,
     *          waits: lines of your list here that are not on the page as it stands,
     *          imNext: { id, name } | null - the Item Market, a run on: the piece whose page Next opens }
     */
    function boxBazaar(v, cards, place, live = {}) {
        const pend = live.pend || {};
        const tookHere = live.took || {};
        const goneSet = live.gone || new Set();
        const im = place === IM_PLACE;
        const stops = v.buy.run.stops;
        const run = v.buy.run;
        const at = stops.findIndex((s) => s.place === place);
        const here = at >= 0 ? stops[at] : null;
        const cur = stops.find((s) => s.state === 'cur') || null;
        const on = !!cur;
        const next = here ? stops[at + 1] || null : cur || stops[0] || null;
        const lineOf = (id) => (here ? here.lines.find((l) => String(l.id) === String(id)) : null);
        const gotOf = (id) => Math.max(0, Math.floor(Number(pend[String(id)]) || 0));
        // Taken on a line: what the run has counted, and what you bought here a moment ago.
        const takenOn = (line) => Math.min(line.q, (on ? Math.min(line.q, (run.took && run.took[line.key]) || 0) : 0) + gotOf(line.id));
        const heldOf = (p) => p.held + gotOf(p.id);
        const marks = [];
        const rows = [];
        const fill = [];
        const onPage = new Set();
        // Units already given to cards of the same piece further up the page (the Item Market has a row for every price).
        const usedOn = new Map();
        let any = false;
        cards.forEach((c, i) => {
            const p = viewPiece(v, c.itemId);
            if (!p) return;
            any = true;
            const id = String(p.id);
            const line = lineOf(id);
            // The Item Market lists one piece many times: only the listings worth taking are marked - under the piece's
            // own worth, or at your list's price for it or under (a piece its set carries, or a Stretch).
            if (im && !(c.price > 0 && (c.price < p.worth || (line && c.price <= line.price)) && (line || p.need > 0))) return;
            const first = !onPage.has(id);
            onPage.add(id);
            const need = Math.max(0, p.need - gotOf(id));
            const taken = line ? takenOn(line) : 0;
            // On your list, and dearer on the page now than the list has it - past everything its set can carry: not
            // bought at that price. The hub is told what the page shows, and makes the list again.
            const dear = !!line && c.price > line.price && !(c.price < Math.max(p.worth, p.lineS || 0));
            const left = dear ? 0 : line ? line.q - taken : need > 0 && c.price > 0 && c.price < p.worth ? need : 0;
            // Never more than the listing holds, as the page says it now.
            // On the Item Market the piece's rows share what is left, in the order the page has them. A card that does
            // not say its stock (a category tile there) gets no number: "buy 150 here" where three exist is a guess.
            const used = usedOn.get(id) || 0;
            const open = Math.max(0, left - used);
            const blind = im && !(c.qty > 0);
            const take = first || im ? (c.qty > 0 ? Math.min(open, c.qty) : blind ? 0 : open) : 0;
            usedOn.set(id, used + take);
            const cap = line ? take : need;
            let text;
            let state;
            let ring = '';
            if (c.typed > cap && c.typed > 0) { text = cap ? `typing ${hNum(c.typed)} · you ${line ? 'listed' : 'need'} ${hNum(cap)}` : `typing ${hNum(c.typed)} · you need no more`; state = 'over'; ring = 'over'; }
            else if (take > 0 && c.typed === take) { text = `${hNum(take)} typed · press Buy`; state = line ? 'top' : ''; ring = line ? 'top' : 'need'; }
            // The owner, 2026-10-11: "it says need 150 ... but it only has a few things there. Can it just tell me how
            // much I need from that bazaar". So the mark says what to take HERE, never the whole of what you need.
            else if (line && take > 0) { text = `buy ${hNum(take)} here · on your list${take < open ? ' · all it has' : ''}`; state = 'top'; ring = 'top'; }
            else if (blind && open > 0) { text = 'under its worth · open it for the stock'; state = ''; ring = 'need'; }
            else if (dear) { text = 'dearer now than your list has it'; state = 'ahead'; }
            else if (line && taken > 0 && first) { text = `took ${hNum(taken)} ✓`; state = 'good'; }
            else if (take > 0) { text = `buy ${hNum(take)} here${take < open ? ' · all it has' : ''}`; state = ''; ring = 'need'; }
            else if (im && need > 0) { text = 'no more needed from this row'; state = 'ok'; }
            else if (need > 0) { text = 'none here · over its worth'; state = 'ok'; }
            else if (p.ahead > 0) { text = `none here · ${hNum(p.ahead)} ahead already`; state = 'ahead'; }
            else { text = 'none here · enough for now'; state = 'ok'; }
            marks.push({ i, text, state, ring });
            if (take > 0) fill.push({ i, n: take });
            // The Item Market: each price row you are to buy from is a row of the box, with its own number and price.
            if (first ? take > 0 || taken > 0 : take > 0) rows.push({ p, c, i, take, line, taken: first ? taken : 0, short: take < open });
        });
        // On your list here, and not on the page as it stands: further down the bazaar (Torn draws only the listings
        // near the screen), or sold since the list was made.
        const away = (here ? here.lines : []).filter((l) => !onPage.has(String(l.id))).map((l) => ({ l, p: viewPiece(v, l.id), taken: takenOn(l) })).filter((x) => x.p);
        // Bought here on this visit and on no line any more (the list let go of it once it was yours).
        const shown = new Set([...rows.map((r) => String(r.p.id)), ...away.map((x) => String(x.p.id))]);
        const bought = Object.keys(tookHere).filter((id) => tookHere[id] > 0 && !shown.has(String(id))).map((id) => ({ p: viewPiece(v, id), n: tookHere[id] })).filter((x) => x.p);
        // With a run on, every bazaar and every page of the Item Market shows the way on: back to its stop, or past it.
        if (!any && !here && !bought.length && !on) return null;

        const todo = rows.filter((r) => r.take > 0);
        const waits = away.filter((x) => x.l.q - x.taken > 0 && !goneSet.has(String(x.p.id)));
        // A press in a box that the hub has not taken after a few seconds: said, with the way to its tab. The press
        // itself shows here already.
        const late = live.late ? `<div class="ta-hold"><b>The hub's tab has not taken your last press yet.</b> It shows here already. With its tab open it is taken at once.<div class="ta-btns late">${bxBtn('hub', 'Open its tab')}</div></div>` : '';
        let html = late + bxBack(v) + bxHead(here ? (on ? 'Buying your list' : 'On your list here') : 'Under their worth here', here ? `stop ${at + 1} of ${stops.length}` : todo.length || bought.length ? '' : 'nothing');
        for (const r of rows) {
            const done = !r.take;
            const typed = !done && r.c.typed === r.take;
            const act = done ? '' : typed ? `<b class="t-good">${hNum(r.take)} typed.</b> Press Buy on Torn.`
                : r.c.hasBox ? bxBtn('fill-card', `Fill ${hNum(r.take)}`, '', String(r.i), ` data-n="${r.take}"`)
                : live.fillAll ? `Open its Buy box on Torn: ${hNum(r.take)} is typed for you.` : 'Open its Buy box on Torn, then Fill types the number.';
            html += bxCheck(r.p, {
                n: done ? r.taken : r.take, cls: done ? 'done' : '', held: heldOf(r.p), act,
                right: done ? 'took ✓' : hMoney(r.take * r.c.price),
                sub: done ? '' : `${hMoney(r.c.price)} each · ${bxWorth(r.p, r.c.price)}${r.short ? ' · all this listing has' : ''}${r.taken ? ` · took ${hNum(r.taken)} so far` : ''}`,
            });
        }
        for (const x of away) {
            const left = x.l.q - x.taken;
            const gone = goneSet.has(String(x.p.id));
            html += bxCheck(x.p, left > 0 ? {
                n: left, cls: 'away', held: heldOf(x.p), right: gone ? 'gone' : hMoney(left * x.l.price),
                sub: gone ? 'gone from this bazaar: your list is made again without it' : im ? 'on its own page of the Item Market' : 'not on the page as it stands',
                // "item no longer there": Torn draws only the listings near the screen, so the page cannot tell a
                // listing further down from one that sold. You can, with one press.
                act: gone || im ? '' : bxBtn('gone', 'Gone', '', String(x.p.id), ' title="It is not in this bazaar any more: taken off your list here, and the list is made again"'),
            } : { n: x.taken, cls: 'done', held: heldOf(x.p), right: 'took ✓' });
        }
        for (const x of bought) html += bxCheck(x.p, { n: x.n, cls: 'done', held: heldOf(x.p), right: 'took ✓' });
        if (waits.length && !im) html += bxNote(`<b>${hPlural(waits.length, 'piece')} on your list ${waits.length === 1 ? 'is' : 'are'} not on the page as it stands.</b> Scroll down the bazaar: Torn draws only the listings near the screen${live.fillAll ? ', and Fill all types into each as it comes' : ''}. One that is not there has sold: press Gone on it.`);
        if (todo.length) {
            const cost = todo.reduce((s, r) => s + r.take * r.c.price, 0);
            const gain = todo.reduce((s, r) => s + r.take * (r.p.worth - r.c.price), 0);
            html += bxKv(`${hPlural(todo.reduce((s, r) => s + r.take, 0), 'piece')} cost`, hMoney(cost), 'sep')
                + (gain >= 0 ? bxKv('Worth more than you pay', `<span class="t-good">${hSigned(gain)}</span>`) : bxKv('Over their own worth', `${hMoney(-gain)} · their sets carry it`));
            // Fill all: one press of yours, and each number is typed into its own box. Nothing of Torn's is pressed.
            const typed = todo.filter((r) => r.c.typed === r.take).length;
            html += '<div class="ta-btns">' + (live.fillAll ? bxBtn('fill-all', 'Fill all is on · put back', '', 'off') : bxBtn('fill-all', `Fill all ${hNum(todo.length)}`, 'go', 'on')) + '</div>';
            if (live.fillAll) html += bxNote(typed >= todo.length ? `<b>All ${hNum(todo.length)} typed.</b> Press Buy on each.` : `<b>${hNum(typed)} of ${hNum(todo.length)} typed.</b> Open the Buy box of the others: each gets its number as it opens.`);
        } else if (!rows.length && !away.length && !bought.length) {
            html += bxNote('Nothing here is under its worth for the pieces you need.');
        }
        if (here && on) {
            const took = Math.min(here.units, here.lines.reduce((s, l) => s + takenOn(l), 0));
            html += took >= here.units ? `<div class="ta-ok">You took ${hNum(took)} of ${hNum(here.units)} ✓</div>`
                : took ? `<div class="ta-warn">You took ${hNum(took)} of ${hNum(here.units)}. Next counts only what you took.</div>`
                : bxNote('Not bought yet. Or skip it: <b>Next counts only what you took.</b>');
        }
        // While a run stands here the Next button names the next stop: said once.
        if (next && next !== here && !on) html += `<div class="ta-kv"><span>${here ? 'Next stop' : 'Your list starts at'}</span><span>${next.im ? 'Item Market' : hEsc(next.who || 'a bazaar')}: ${next.lines.map((l) => hEsc(l.name.replace(/ (Plushie|Flower)$/i, '')) + ' ×' + hNum(l.q)).join(', ')}</span></div>`;
        const after = here ? stops[at + 1] || null : null;
        // The Item Market is ONE stop with a page for each piece. Next walks its pieces in the list's order, and only
        // after the last one moves on (the owner, 2026-10-11: "so the next next in shopping list just takes me there").
        // Until 1.2.4 Next left the Item Market after its first piece: the others were "skipped".
        const pageAt = im && here ? here.lines.reduce((k0, l, k) => (onPage.has(String(l.id)) || String(l.id) === String(live.itemId || '') ? k : k0), -1) : -1;
        const imNext = im && here && on ? here.lines.find((l, k) => k > pageAt && l.q - takenOn(l) > 0) || null : null;
        const stopName = (s) => (s.im ? 'the Item Market' : hEsc(s.who || 'a bazaar'));
        const linesOf = (s) => ` title="${hEsc(s.lines.map((l) => l.name + ' ×' + l.q).join(', '))}"`;
        // The keys, said where they do something: while something of yours is to buy on this page. The right arrow is
        // the press of Next (or of "Your stop"), and is said as where that takes you.
        const right = !here ? 'your stop' : imNext ? 'the next piece' : !after ? 'back to the list' : after.im ? 'the Item Market' : 'the next bazaar';
        if (todo.length || waits.length) html += `<div class="ta-n keys"><span class="kbd">↑</span>Fill all<span class="kbd">↓</span>the next listing to buy${on ? `<span class="kbd">→</span>${right}` : ''}</div>`;
        // One purple button on the page: Fill all while there is something to type, Next once there is not.
        const main = todo.length ? '' : 'go';
        const stop = bxBtn('run-stop', 'Stop the run', 'link');
        const past = cur ? stops[stops.indexOf(cur) + 1] || null : null;
        // A run that a press in this box just ended, before the hub has answered: nothing to press until it does.
        html += '<div class="ta-btns">' + (run.over ? ''
            // A run is on and this place is on your list - the stop the run is on or another ("i didnt follow the
            // list"): Next goes on from here, and the stops passed over stay on the list.
            : on && here ? bxBtn('run-next', (imNext ? `Next: ${hEsc(imNext.name)} ×${hNum(imNext.q - takenOn(imNext))}, its Item Market page` : after ? (after.im ? 'Next: the Item Market' : 'Next bazaar: ' + hEsc(after.who || '')) : 'Done: back to the list') + '<span class="kbd">N</span>', main, '', !imNext && after ? linesOf(after) : '') + stop
            // A run is on and this place is not on your list: back to the run's stop, or on past it.
            : on ? bxBtn('run-go', `Your stop: ${stopName(cur)}<span class="kbd">N</span>`, main, '', linesOf(cur)) + bxBtn('run-next', past ? `Skip it: on to ${stopName(past)}` : 'Skip it: the list ends there', '', '', past ? linesOf(past) : '') + stop
            : stops.length ? bxBtn('run-start', 'Start the run', main) : '') + '</div>';
        if (run.over) html += bxNote('<b>The run is over.</b> What you took leaves your list, what you skipped stays on it.');
        html += bxNote(`Fill types the number into Torn's box. <b>You press Buy.</b> A buy is counted when the page shows the sale${v.top.stock && v.top.stock.log ? "; Torn's log, read just after, is the judge" : ''}.`);
        // Folded, the bar says what is here, so you know to unfold it.
        const left = todo.length + waits.length;
        const head = here ? (left ? `${hNum(left)} to buy here` : 'all taken here ✓') : todo.length ? `${hNum(todo.length)} under ${todo.length === 1 ? 'its' : 'their'} worth here` : '';
        return { where: im ? 'the Item Market' : 'a bazaar', head, html, marks, fill, waits: waits.length, imNext: imNext ? { id: imNext.id, name: imNext.name } : null };
    }

    /**
     * A trade.
     * @param t      the trade as the view has it (view.trades.open), or null when the hub has not read it
     * @param rows   [{ name, qty }] the other side's rows on the page, in page order
     * @param step   'view' | 'addmoney'
     */
    /**
     * Whether the set pieces on Torn's page are the ones the hub read: the same pieces, the same counts. The total,
     * the message and Fill are of the trade as it was read; a pile put in or taken out since makes them wrong.
     * Only set pieces are compared (their names are Torn's own on both sides). No rows from the page: nothing to compare.
     * @param rows [{ name, qty }] the other side's rows on the page
     * @returns { same, diff: Set of lower-case names whose count differs }
     */
    function tradeSame(v, t, rows) {
        const diff = new Set();
        if (!t || !rows || !rows.length) return { same: true, diff };
        const pieces = new Set(v.pieces.map((p) => String(p.name).toLowerCase()));
        const sum = (list, ok) => { const m = new Map(); for (const r of list) { const k = String(r.name).toLowerCase(); if (ok(r, k)) m.set(k, (m.get(k) || 0) + Math.max(1, Math.floor(Number(r.qty) || 0))); } return m; };
        const here = sum(rows, (r, k) => pieces.has(k));
        const read = sum(t.rows, (r) => r.state !== 'other');
        for (const k of new Set([...here.keys(), ...read.keys()])) if (here.get(k) !== read.get(k)) diff.add(k);
        return { same: !diff.size, diff };
    }

    /**
     * A trade.
     * @param known the other side's rows as this tab last saw them on the trade's own view (the add-money step shows none)
     */
    function boxTrade(v, t, rows, step, hasMoneyBox, known = null) {
        const marks = [];
        if (!t) {
            return rows.length ? { where: 'a trade', html: bxNote('This trade has not been read yet. The hub reads your open trades once a minute.'), marks } : null;
        }
        const same = tradeSame(v, t, rows.length ? rows : known || []);
        const pieceNames = new Set(v.pieces.map((p) => String(p.name).toLowerCase()));
        rows.forEach((row, i) => {
            const key = String(row.name).toLowerCase();
            const r = t.rows.find((x) => String(x.name).toLowerCase() === key);
            if (!r) { if (pieceNames.has(key)) marks.push({ i, text: 'not read yet', state: 'over', where: 'right' }); return; }
            if (r.state === 'other' || !r.each) { marks.push({ i, text: 'not a set piece, not priced', state: 'over', where: 'right' }); return; }
            if (same.diff.has(key)) { marks.push({ i, text: `${hMoney(r.each)} each · its count changed`, state: 'over', where: 'right' }); return; }
            const word = r.take >= r.qty ? `need all ${hNum(r.qty)}` : r.take ? `need ${hNum(r.take)} of ${hNum(r.qty)}` : r.ahead ? 'ahead already' : 'enough for now';
            marks.push({ i, text: `${hMoney(r.each)} · ${word}`, state: r.take ? (r.top ? 'top' : '') : 'ahead', where: 'right' });
        });
        const m = t.margin;
        // The rate this trade is really paid at ("101%", or "100.6% to 101%" when its sets differ): each set at the
        // lower of your rate and its own ceiling (core/sellrate.js).
        const paid = t.paid || v.prices.paid || hRate(v.settings.pct) + '%';
        if (!same.same) {
            // The numbers of the trade as it was would be paid for the trade as it is: none is shown, nothing is filled.
            const others = v.trades.open.filter((x) => x.id !== t.id);
            return {
                where: 'a trade', marks, changed: true,
                html: bxHead('Your prices', `${paid} of market value`)
                    + `<div class="ta-hold"><b>This trade changed since it was read${t.readAt ? ' ' + hAge(t.readAt, v.at) : ''}.</b> Its total is being worked out again: it is here within a minute. Nothing is filled until then.</div>`
                    + (others.length ? `<div class="ta-kv sep"><span>Also open with you</span><span>${others.map((x) => `<a class="lk" data-act="open-trade" data-v="${hEsc(x.id)}">${hEsc(x.who || 'a trade')}</a>`).join(' · ')}</span></div>` : ''),
            };
        }
        let html = bxHead('Your prices', `${paid} of market value`)
            + bxKv('Only what you need', hMoney(t.needTotal)) + bxKv(`Everything, ${hPlural(t.units, 'piece')}`, hMoney(t.total));
        if (m && m.state === 'ok') html += `<div class="ta-ok">Everything in it ${marginWords(m.all)}.</div>`;
        else if (m && m.state === 'under') html += `<div class="ta-hold"><b>Everything in it ${marginWords(m.all)}:</b> under your least profit since the points price fell.${m.mend ? ` Paying ${hRate(m.mend)}% would keep it.` : ''}</div>`;
        else if (m && m.state === 'loss') html += `<div class="ta-hold"><b>Everything in it ${marginWords(m.all)}:</b> a loss at the points price now.${m.mend ? ` Paying ${hRate(m.mend)}% would keep your least profit.` : ''}</div>`;
        // What you pay came down inside its hour: the seller may have counted on more.
        for (const r of t.rateDown || []) html += `<div class="ta-hold"><b>${hEsc(r.label)} pieces:</b> your price came down from ${hRate(r.from)}% to ${hRate(r.to)}% at ${hClock(r.at)} TCT as points fell to ${hMoney(r.price)}.</div>`;
        if (m && m.others && m.others.length) html += bxNote(`<b>${m.others.map(hEsc).join(', ')}</b>: not a set piece, not priced. The total does not cover ${m.others.length === 1 ? 'it' : 'them'}.`);
        if (t.message) html += `<div class="msg">${hEsc(t.message)}</div><div class="ta-btns">${bxBtn('copy', 'Copy the message', 'go', t.message)}${t.messageNeed && t.needTotal !== t.total ? bxBtn('copy', 'Only what I need', '', t.messageNeed) : ''}</div>`;
        const owed = Math.max(0, t.total - t.myMoney);
        if (owed && step === 'addmoney') html += '<div class="ta-btns">' + (hasMoneyBox ? bxBtn('fill-money', `Fill ${hMoney(t.total)}`, 'go', String(t.total)) : '') + '</div>';
        if (t.vault > 0 && v.top.onHand != null) html += `<div class="ta-hold"><b>On hand ${hMoney(v.top.onHand)}.</b> Take ${hMoney(t.vault)} out of the vault just before you pay.</div>`;
        else if (!owed && t.total) html += '<div class="ta-ok">Your money covers it: nothing to do until they accept.</div>';
        const others = v.trades.open.filter((x) => x.id !== t.id);
        if (others.length) html += `<div class="ta-kv sep"><span>Also open with you</span><span>${others.map((x) => `<a class="lk" data-act="open-trade" data-v="${hEsc(x.id)}">${hEsc(x.who || 'a trade')}</a>`).join(' · ')}</span></div>`;
        html += bxNote(`Fill types the money into Torn's box. <b>You press Change and Accept.</b> Nothing is sent or accepted for you.`);
        return { where: 'a trade', html, marks };
    }

    /**
     * The museum.
     * @param found [{ set, hasBox }] the EXCHANGE controls on the page
     * @param off   { setKey: sets } swapped since the view was worked out
     */
    function boxMuseum(v, found, off = {}) {
        const shown = found.map((f) => f.set);
        const sets = v.sets.filter((s) => !shown.length || shown.includes(s.key)).map((s) => ({ ...s, full: Math.max(0, s.full - (off[s.key] || 0)) }));
        const full = sets.reduce((a, s) => a + s.full, 0);
        const price = v.points.price;
        let html = bxHead('Sets ready', `${hNum(full)} full`);
        const tiles = [];
        for (const s of sets) {
            const gain = price ? s.full * (s.value - s.cost) : null;
            if (s.full) {
                html += `<div class="ta-l"><b style="grid-column:1/3">${hNum(s.full)} ${hEsc(s.label)} ${s.full === 1 ? 'Set' : 'Sets'} · ${hNum(s.full * s.points)} points</b><b class="num ${gain == null ? '' : gain >= 0 ? 't-good' : 't-bad'}">${gain == null ? '' : hSigned(gain)}</b>`
                    + `<span class="s">cost you ${hMoney(s.cost)} a set${s.costKnown ? '' : ' (at your rate: no buy on record)'}${price ? ` · worth ${hMoney(s.value)} at ${hMoney(price)} a point` : ''}</span></div>`;
            }
            const short = s.pieces[0];
            if (short) {
                html += bxKv(`${hEsc(short.short || short.name)} holds ${hEsc(s.label.toLowerCase())} sets at`, hNum(s.full), s === sets[0] ? 'sep' : '');
                tiles.push({ set: s.key, id: short.id, text: `holds you at ${hNum(s.full)}`, state: 'top' });
            }
            const ex = found.find((f) => f.set === s.key);
            if (s.full && v.settings.fillMuseum) {
                html += ex && ex.hasBox ? `<div class="ta-btns">${bxBtn('fill-museum', `Fill ${hNum(s.full)}${sets.length > 1 ? ' ' + hEsc(s.label.toLowerCase()) : ''}`, 'go', s.key, ` data-n="${s.full}"`)}</div>`
                    : ex ? bxNote('No number box was found beside EXCHANGE: one press there swaps what Torn says.') : '';
            }
        }
        if (v.points.cheap && full) html += `<div class="ta-hold"><b>Points are cheap today.</b> Swap if you like: the points wait in your book until the price is back.</div>`;
        html += bxNote(`Fill types the number of full sets into Torn's box. <b>You press EXCHANGE.</b> The points go into your book at what the sets cost. Profit is counted later, when the points sell.`);
        return { where: 'the museum', html, marks: [], tiles };
    }

    const PM_RANK = { '': 1, ahead: 2, bad: 3 };

    /**
     * The points market as you type (mockup Z7): where the price in Torn's box would sit in the list, and whether it is
     * a loss, cheap, or more under the lowest than it takes.
     * @param page { typed: { amount, price } | null, rows: [{ points, each }] } - the page's own list, cheapest first
     * @returns { html, marks: [{ i, state }] (a line on the top edge of row i of the page's list), note: { text, state } | null }
     */
    function pointsTyped(v, page) {
        const p = v.points;
        const onPage = !!(page && page.rows && page.rows.length);
        // The page's own list is of now; without it, the hub's read of the market (a minute old at most).
        const rows = onPage ? page.rows : (p.ladder || []).map((l) => ({ points: l.qty, each: l.price }));
        const least = p.sell.least || 0;
        const usual = p.level && p.level.lo ? `${hMoney(p.level.lo)} to ${hMoney(p.level.hi)}` : '';
        const t = page && page.typed ? typedListing(rows, { ...page.typed, least, level: p.level }) : null;
        // A line in Torn's list is a hairline on the edge between two rows, with no words on it: the box says what it is.
        const marks = new Map();
        const said = [];
        const add = (i, state, words) => {
            const m = marks.get(i);
            marks.set(i, { i, state: m && PM_RANK[m.state] > PM_RANK[state] ? m.state : state });
            said.push({ i, words });
        };
        if (onPage) {
            const lines = listLines(rows, { least, level: p.level });
            if (t && t.at != null) add(t.at, '', 'is where yours would sit');
            if (lines.cheapAt != null) add(lines.cheapAt, 'ahead', `has the prices under the usual ${usual} above it`);
            if (lines.lossAt != null) add(lines.lossAt, 'bad', `has the prices that are a loss (under your ${hMoney(least)}) above it`);
        }
        const hue = { '': ['blue', '#5aa7ff'], ahead: ['amber', '#f6b74a'], bad: ['red', '#ff7878'] };
        const by = new Map();
        for (const s of said) by.set(s.i, [...(by.get(s.i) || []), s.words]);
        const legend = by.size ? bxNote(`In Torn's list: ${[...by].map(([i, words]) => `the <b style="color:${hue[marks.get(i).state][1]}">${hue[marks.get(i).state][0]} line</b> ${words.join(', and ')}`).join('; ')}.`) : '';
        if (!t) return { html: legend, marks: [...marks.values()], note: least ? { text: `Your least price: ${hMoney(least)}`, state: '' } : null };
        const pos = t.past ? `over ${hNum(t.ahead)} points sell first` : t.ahead ? `${hNum(t.ahead)} points sell first` : rows.length ? 'first in the list' : '';
        const verdict = t.state === 'loss' ? (t.by < 0 ? `a loss of ${hMoney(-t.by)} a point` : 'no profit: what they cost you')
            : t.under ? `${hMoney(t.under)} under the lowest: $1 under is enough`
            : t.state === 'cheap' ? `${p.hold ? 'hold: ' : ''}under the usual ${usual}`
            : t.state === 'good' ? `${hSigned(t.by)} a point over cost` : '';
        const text = [pos, verdict].filter(Boolean).join(' · ');
        const note = text ? { text: text.charAt(0).toUpperCase() + text.slice(1), state: t.state === 'loss' ? 'bad' : t.under || t.state === 'cheap' ? 'ahead' : t.state === 'good' ? 'good' : '' } : null;
        let html = bxHead('What you typed', `${t.amount ? hNum(t.amount) + ' at ' : ''}${hMoney(t.price)}`)
            + bxKv('Sell before yours', t.past ? `over ${hNum(t.ahead)} points` : t.ahead ? `${hNum(t.ahead)} points` : rows.length ? 'none: first in the list' : 'not read')
            + (t.by == null ? '' : bxKv(`${t.by < 0 ? 'Under' : 'Over'} your cost, ${hMoney(least - 1)}`, `${hMoney(Math.abs(t.by))} a point`, t.by > 0 ? 't-good' : 't-bad'))
            + (t.amount ? bxKv('Puts on hand', hMoney(t.amount * t.price)) : '');
        if (t.state === 'loss') html += `<div class="ta-hold"><b>A loss.</b> ${hMoney(t.price)} is under your least price ${hMoney(least)}${t.amount && t.by < 0 ? `: ${hMoney(-t.by * t.amount)} on these ${hNum(t.amount)}` : ''}.</div>`;
        else if (t.under) html += `<div class="ta-hold"><b>${hMoney(t.under)} under the lowest listing.</b> ${hMoney(t.lowest - 1)} is first already${t.given ? `: ${hMoney(t.given)} given away on these ${hNum(t.amount)}` : ''}.</div>`;
        else if (t.state === 'cheap' && !(p.hold || p.cheap)) html += `<div class="ta-hold"><b>Cheap.</b> ${hMoney(t.price)} is under the usual ${usual}.</div>`;
        return { html: html + legend, marks: [...marks.values()], note };
    }

    /**
     * The points market. `hasBoxes` = Torn's Amount and Price boxes were found.
     * `page` = what the page itself shows: { typed: { amount, price } | null, rows: [{ points, each }] } (see pointsTyped).
     */
    function boxPoints(v, hasBoxes, page = null) {
        const p = v.points;
        if (!p.price) return { where: 'the points market', html: bxNote('The points price has not been read yet. The hub reads it once a minute.'), marks: [], note: null };
        const typed = pointsTyped(v, page);
        const sell = p.sell;
        const lot = sell.quick && sell.quick.size ? sell.quick.size : sell.points;
        let html = '';
        // Cheap is judged on the lowest listing, not on the price Fill would type.
        const low = p.lowest || p.price;
        if (p.hold && p.level && p.level.lo) html += `<div class="ta-hold"><b>Hold.</b> The lowest listing is ${hMoney(low)}, under the usual ${hMoney(p.level.lo)} to ${hMoney(p.level.hi)}. Your rule: cheap points are not sold.</div>`;
        else if (p.cheap && p.level && p.level.lo) html += `<div class="ta-hold"><b>Cheap today.</b> The lowest listing is ${hMoney(low)}, under the usual ${hMoney(p.level.lo)} to ${hMoney(p.level.hi)}.</div>`;
        if (!sell.points) {
            html += typed.html + bxNote(`No points made from your sets are waiting to be sold.${p.before ? ` The ${hNum(p.before)} you had before have no cost on record, so no price is called a loss for them: type what a point cost you on the hub's Points page and it is.` : ''}`);
            return { where: 'the points market', html, marks: typed.marks, note: typed.note };
        }
        // Mockup Z7: the full sets not swapped yet would make the lot bigger.
        const readySets = (v.sets || []).reduce((a, s) => a + s.full, 0);
        const ready = (v.sets || []).reduce((a, s) => a + s.full * s.points, 0);
        html += bxHead(p.hold ? 'If you list anyway' : 'Your points', `${hNum(sell.points)} made from sets`)
            + bxKv(`Price to type · $1 under the ${p.rule === 'wall' ? 'first wall' : 'lowest'}`, hMoney(p.price))
            + bxKv('Listed at that or cheaper', `${hNum(p.ahead)} points`)
            + bxKv('Lot', sell.quick ? `${lotsWords(sell.quick.lots)} · the size that leaves quickest` : `all ${hNum(sell.points)} in one`)
            + (ready ? bxKv('Or wait for a bigger lot', `${hNum(sell.points + ready)} with your ${hPlural(readySets, 'full set')}`) : '')
            + bxKv('One lot puts on hand', hMoney(lot * p.price));
        if (sell.loss) html += `<div class="ta-hold"><b>A loss.</b> ${hMoney(p.price)} is under the ${hMoney(sell.least)} these points cost you. Wait.</div>`;
        else if (v.settings.fillPoints) html += '<div class="ta-btns">' + (hasBoxes ? bxBtn('fill-points', `${p.hold ? 'Fill anyway' : 'Fill'}: ${hNum(lot)} at ${hMoney(p.price)}`, p.hold ? '' : 'go', String(lot), ` data-n="${p.price}"`) : '') + '</div>'
            + (hasBoxes ? '' : bxNote("Torn's Amount and Price boxes were not found on this page: type them yourself."));
        html += typed.html + bxNote(`${p.before ? `The ${hNum(p.before)} points you had before are left alone. ` : ''}Bank each lot when it sells: a buy-mug takes cash on hand. Fill types lot and price. <b>You press ADD LISTING.</b>`);
        return { where: 'the points market', html, marks: typed.marks, note: typed.note };
    }

    /** Your buying thread. `title` = its title as the page shows it. */
    function boxForum(v, title, check) {
        const pr = v.prices;
        // 'under': the title names your rate - the most you pay - while a set is paid less today (its ceiling). The
        // title is not wrong, so nothing asks for an edit: it is said, and the trade message names the rate paid.
        const under = check.state === 'under';
        const ok = check.state === 'match' || under;
        const paid = pr.paid || hRate(pr.pct) + '%';
        const shop = pr.open ? `Open · ${paid}` : 'Closed';
        const why = check.state === 'open' ? `It says CLOSED; your shop is Open at ${paid}.` : check.state === 'closed' ? 'It says OPEN; your shop is Closed.' : check.state === 'rate' ? `It says ${hRate(check.says.pct)}%; your rate is ${hRate(pr.pct)}%.` : '';
        let html = bxHead('Your thread', under ? 'the title names your rate' : ok ? 'the title matches' : 'the title is out of date') + bxKv('Shop', `<span class="${pr.open ? 't-good' : ''}">${shop}</span>`);
        if (under) html += `<div class="ta-hold"><b>It says ${hRate(check.says.pct)}%; today you pay ${paid}.</b> The points price holds a set under your rate. The message for a trade names what you pay.</div>`;
        else if (!ok) html += `<div class="ta-hold"><b>${hEsc(why)}</b> Edit the thread on Torn and paste the new title.</div><div class="msg">${hEsc(pr.forum.title)}</div>`;
        html += `<div class="ta-btns">${bxBtn('copy', 'Copy the title', ok ? '' : 'go', pr.forum.title)}${bxBtn('copy', 'Copy the post', '', pr.forum.post)}</div>`
            + bxNote('<b>Nothing is posted or edited for you.</b>');
        return { where: 'your thread', html, marks: [], titleMark: { text: under ? `says ${hRate(check.says.pct)}%, you pay ${paid} today` : ok ? `matches your shop: ${shop}` : 'does not match your shop', state: under ? 'ahead' : ok ? 'good' : 'over' }, title };
    }

    /* ===== src/core/overlay.js ===== */
    // Where Torn Archive's overlay may stand on one of Torn's pages: only in the empty window beside Torn's content,
    // on its right or on its left, never over it. Numbers in, numbers out: ui/torn-page.js measures and applies them.
    //
    // The width, the least width and the gap are Torn Trading's own (its panel), so the two are one column when they
    // meet. Torn Trading keeps its place then: the Archive goes over it or under it, never beside it, never on top.

    const OV_WIDTH = 430;
    /** With less free window than this on a side, the overlay does not stand there. */
    const OV_MIN_WIDTH = 200;
    /** Kept clear of Torn's content, and of Torn Trading's panel. */
    const OV_GAP = 8;
    /** Kept clear of the window's edge. */
    const OV_EDGE = 16;
    /** The bar: the overlay folded. */
    const OV_BAR = 40;
    /** Where it stands until you move it: on the right, under Torn's own header. */
    const OV_TOP = 84;
    /** With less height than this it is its bar only: a body that short says nothing. */
    const OV_BODY_MIN = 110;

    const ovClamp = (n, lo, hi) => Math.min(Math.max(n, lo), Math.max(lo, hi));

    /**
     * The two strips of empty window beside Torn's content.
     * @param winW  the window's width
     * @param left  where Torn's content begins, null when the page has none we know
     * @param right where it ends
     * @returns { left, right } each { from, to, width } or null when the overlay does not fit there
     */
    function overlayStrips({ winW, left = null, right = null }) {
        const strip = (from, to) => {
            const free = Math.floor(to - from);
            return free >= OV_MIN_WIDTH ? { from: Math.ceil(from), to: Math.floor(to), width: Math.min(OV_WIDTH, free) } : null;
        };
        if (left == null || right == null) return { left: null, right: strip(OV_EDGE, winW - OV_EDGE) };
        return { left: strip(OV_EDGE, left - OV_GAP), right: strip(right + OV_GAP, winW - OV_EDGE) };
    }

    /** The side a spot belongs to while you drag: the half of the window it is in, when the overlay fits there. */
    function overlaySide(centre, strips, middle) {
        const want = centre < middle ? 'left' : 'right';
        if (strips[want]) return want;
        return strips.right ? 'right' : strips.left ? 'left' : null;
    }

    /**
     * A box you put down yourself (your stock, dragged by its bar): where you left it, kept whole inside the window.
     * It is yours to put anywhere, also over Torn's page. Unfolded it keeps room for `least` of its body: left near
     * the window's foot it stands that much higher.
     * @param pos   { left, top } where you left it
     * @param least the least height it keeps (its bar when folded)
     * @returns { left, top, width, maxHeight }
     */
    function overlayFree({ pos, width, winW, winH, least = OV_BAR }) {
        const w = Math.max(0, Math.min(width, winW - 2 * OV_GAP));
        const left = ovClamp(Number(pos && pos.left) || 0, OV_GAP, winW - w - OV_GAP);
        const top = ovClamp(Number(pos && pos.top) || 0, 0, winH - Math.max(OV_BAR, least) - OV_GAP);
        return { left: Math.round(left), top: Math.round(top), width: Math.round(w), maxHeight: Math.floor(winH - top - OV_GAP) };
    }

    /**
     * Where the overlay stands.
     * @param pos    { side, left, top } where you left it, or null
     * @param strips overlayStrips()
     * @param winH   the window's height
     * @param want   the height it would take with nothing in its way (its bar when folded)
     * @param cap    the most height it ever takes
     * @param other  Torn Trading's panel on this page { left, top, right, bottom, width }, or null
     * @returns null when no side has the room, else { side, left, top, width, maxHeight, bar, by }
     *          bar: there is room for the bar only. by: 'over' | 'under' Torn Trading's panel, '' when alone.
     */
    function overlayPlace({ pos = null, strips, winH, want = OV_BAR, cap = Infinity, other = null }) {
        const side = pos && strips[pos.side] ? pos.side : strips.right ? 'right' : strips.left ? 'left' : null;
        if (!side) return null;
        const strip = strips[side];
        const tall = ovClamp(want, OV_BAR, cap);
        let width = strip.width;
        // Until you move it, it rests against the window's edge.
        const rest = side === 'right' ? strip.to - width : strip.from;
        let left = ovClamp(pos && pos.side === side && Number.isFinite(pos.left) ? pos.left : rest, strip.from, strip.to - width);
        let top = ovClamp(pos && Number.isFinite(pos.top) ? pos.top : OV_TOP, 0, winH - OV_BAR - OV_GAP);
        let by = '';
        let room;
        if (other && other.right > strip.from && other.left < strip.to) {
            // The same side as Torn Trading's panel: its column, its width, and only the height it leaves.
            left = other.left;
            width = other.width;
            const over = other.top - OV_GAP;
            const under = winH - other.bottom - 2 * OV_GAP;
            if (top >= other.bottom + OV_GAP && under >= OV_BAR) {
                by = 'under';
                room = winH - top - OV_GAP;
            } else if (over >= OV_BAR || under < OV_BAR) {
                by = 'over';
                // It keeps under Torn's header while that leaves room for a body (the body scrolls); only when the
                // panel leaves less than that does it go up to the window's top.
                const floor = Math.min(top, OV_TOP);
                top = over - floor >= OV_BODY_MIN ? Math.max(floor, Math.min(top, over - tall)) : Math.max(0, Math.min(top, over - Math.min(tall, over)));
                room = Math.max(OV_BAR, over - top);
            } else {
                by = 'under';
                top = other.bottom + OV_GAP;
                room = winH - top - OV_GAP;
            }
        } else {
            // Unfolded near the window's foot it grows upward: the bar goes back to its place when folded.
            top = Math.max(0, Math.min(top, winH - OV_GAP - tall));
            room = winH - top - OV_GAP;
        }
        const maxHeight = Math.floor(Math.min(room, cap));
        return { side, left: Math.round(left), top: Math.round(top), width: Math.round(width), maxHeight, bar: maxHeight < OV_BODY_MIN, by };
    }

    /* ===== src/core/parse.js ===== */
    /*
     * Pure parsing + formatting helpers. No DOM, no network.
     */

    function applyMagnitude(value, suffix) {
        if (!Number.isFinite(value)) return null;

        switch ((suffix || '').toLowerCase()) {
            case 'k':
                return value * 1e3;
            case 'm':
                return value * 1e6;
            case 'b':
                return value * 1e9;
            default:
                return value;
        }
    }

    /**
     * Parse a money string into a number.
     *
     * Handles "$1,234", "1,234", "$1.2m", "806000". Returns null when the input
     * contains no number, rather than guessing.
     *
     * Note: unlike V1 this is never handed whole-row text. Callers pass the
     * contents of one specific cell, so there is no "first $ in the row" problem
     * to solve here.
     */
    function parseMoney(text) {
        if (typeof text !== 'string' && typeof text !== 'number') return null;

        const cleaned = String(text).replace(/[$,\s]/g, '');

        const exact = cleaned.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/i);
        if (exact) return applyMagnitude(Number(exact[1]), exact[2]);

        /*
         * Embedded in a longer string. The number must END there: a following
         * letter or digit means we are looking at something else.
         *
         * This guard is load-bearing. Without it "$2,896 Buy" collapsed to
         * "2896Buy", the "B" was read as the billions suffix, and the price came
         * out as 2,896,000,000,000. Same for "$3,000 min" and "$500 market".
         */
        const loose = cleaned.match(/(-?\d+(?:\.\d+)?)([kmb])?(?![A-Za-z0-9])/);
        if (!loose) return null;

        return applyMagnitude(Number(loose[1]), loose[2]);
    }

    /**
     * Parse a quantity from strings like "x12", "12", "12 available", "Qty: 12".
     * Returns null when no quantity is present, so the caller decides whether to
     * assume 1 or to skip the row.
     */
    function parseQuantity(text) {
        if (text === null || text === undefined) return null;

        /*
         * Strip money figures before looking for a count.
         *
         * Without this, parseQuantity('$2,896') returned 2896 — so a price cell
         * whose class happened to contain "amount" became the quantity, and total
         * profit was inflated by three orders of magnitude.
         */
        const s = String(text)
            .toLowerCase()
            .replace(/,/g, '')
            .replace(/\$\s*\d+(?:\.\d+)?/g, ' ');

        // "x12" or "12x"
        const xForm = s.match(/(?:^|[^a-z0-9])x\s*(\d+)|(\d+)\s*x(?:[^a-z0-9]|$)/);
        if (xForm) {
            const n = Number(xForm[1] !== undefined ? xForm[1] : xForm[2]);
            if (Number.isFinite(n) && n > 0) return Math.floor(n);
        }

        const plain = s.match(/(\d+)/);
        if (plain) {
            const n = Number(plain[1]);
            if (Number.isFinite(n) && n > 0) return Math.floor(n);
        }

        return null;
    }

    /**
     * A money amount typed by a person: "1000000", "1,000,000", "$1m", "1.5m",
     * "500k", "2b", "1kk", "1 million". Returns null for anything else.
     *
     * The chips used to drop every non-digit, so "1m" became $1 - and a $1 cash
     * cap hides every deal without saying why.
     */
    function parseMoneyInput(text) {
        const raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[$,\s_]/g, '');
        if (!raw) return null;

        const m = raw.match(/^(-?\d+(?:\.\d+)?)(k|kk|m|mil|mill|million|b|bil|bill|billion|thousand)?$/);
        if (!m) return null;

        const mult = {
            k: 1e3, thousand: 1e3,
            kk: 1e6, m: 1e6, mil: 1e6, mill: 1e6, million: 1e6,
            b: 1e9, bil: 1e9, bill: 1e9, billion: 1e9,
        }[m[2] || ''] || 1;

        const n = Number(m[1]) * mult;
        return Number.isFinite(n) ? Math.round(n) : null;
    }

    /** "$1,234" */
    function formatMoney(value) {
        if (!Number.isFinite(value)) return '-';

        const rounded = Math.round(value);
        const sign = rounded < 0 ? '-' : '';

        return sign + '$' + Math.abs(rounded).toLocaleString('en-US');
    }

    /** "$1.2m" - compact form for tight panel rows. */
    function formatMoneyShort(value) {
        if (!Number.isFinite(value)) return '-';

        const abs = Math.abs(value);
        const sign = value < 0 ? '-' : '';

        if (abs >= 1e9) return sign + '$' + (abs / 1e9).toFixed(2) + 'b';
        if (abs >= 1e6) return sign + '$' + (abs / 1e6).toFixed(2) + 'm';
        if (abs >= 1e4) return sign + '$' + (abs / 1e3).toFixed(1) + 'k';

        return formatMoney(value);
    }

    /**
     * formatMoneyShort without zeros that say nothing: "$1.5m", "$25m", "$12k".
     * The same amount, in fewer characters - for the panel's one-row chips.
     */
    function formatMoneyCompact(value) {
        return formatMoneyShort(value).replace(/\.0+([kmb])$/, '$1').replace(/(\.\d)0([kmb])$/, '$1$2');
    }

    /** "4.2%" */
    function formatPct(ratio) {
        if (!Number.isFinite(ratio)) return '-';
        return (ratio * 100).toFixed(1) + '%';
    }

    /** "12s ago" / "4m ago" - for the staleness readout. */
    function formatAge(ms) {
        if (!Number.isFinite(ms) || ms < 0) return 'never';

        const seconds = Math.floor(ms / 1000);
        if (seconds < 60) return seconds + 's ago';

        const minutes = Math.floor(seconds / 60);
        if (minutes < 60) return minutes + 'm ago';

        const hours = Math.floor(minutes / 60);
        if (hours < 24) return hours + 'h ago';

        return Math.floor(hours / 24) + 'd ago';
    }

    /**
     * A whole number typed in a quantity box (3.14.3): "25", "1,000" and "1 000"
     * read as numbers; anything else ("abc", "-3", "5m", "2.5", empty) is null -
     * never a guess. A stray "s" is not dropped any more (the old /[,s]/ typo).
     */
    function readWholeNumber(text) {
        const t = String(text === null || text === undefined ? '' : text).trim().replace(/[,\s]/g, '');
        if (!/^\d+$/.test(t)) return null;
        const n = Number(t);
        return Number.isSafeInteger(n) ? n : null;
    }

    /* ===== src/core/items.js ===== */
    /*
     * The item database: indexing and cache policy. Pure - no GM_*, no DOM, no
     * network. main.js supplies the storage adapter and the fetcher.
     *
     * The index is built ONCE at load. V1's fatal performance bug was rebuilding
     * and re-sorting a ~1,500-entry name array inside a per-element loop; here
     * name lookup is a Map hit.
     */

    /** Bump to invalidate every cached item database in the wild. */
    const ITEMS_CACHE_VERSION = 'items-v5';

    /**
     * One hour. sell_price barely moves, but market_value moves every day, and
     * every "below market value" judgement is only as good as it. A week-old
     * market value made listings look cheap, or not, against a price that no
     * longer existed. One Public API call an hour is nothing.
     */
    const ITEMS_TTL_MS = 60 * 60 * 1000;

    /**
     * Canonical form for name matching: lowercase, collapsed whitespace.
     * Kept in one place so the index and the lookups can never disagree.
     */
    function normalizeItemName(name) {
        if (typeof name !== 'string') return '';
        return name.trim().toLowerCase().replace(/\s+/g, ' ');
    }

    /**
     * Build the lookup index from the raw `torn/items` payload.
     *
     * @param {object} rawItems - { "1": { name, sell_price, ... }, ... }
     */
    function buildItemIndex(rawItems) {
        const byId = new Map();
        const byName = new Map();

        for (const [id, item] of Object.entries(rawItems || {})) {
            if (!item || typeof item.name !== 'string') continue;

            const record = {
                id: String(id),
                name: item.name,
                type: item.type || null,
                // v2's sub_type (Melee / Primary / Secondary / Temporary for weapons).
                subType: item.sub_type || null,
                buyPrice: Number(item.buy_price) || 0,
                // 0 when no NPC shop buys it ("Sell: N/A" in game).
                sellPrice: Number(item.sell_price) || 0,
                // Which NPC shop buys it, when the item data names one.
                npcShopName: item.npc_shop || null,
                marketValue: Number(item.market_value) || 0,
                circulation: Number(item.circulation) || 0,
            };

            byId.set(record.id, record);

            const key = normalizeItemName(record.name);
            // Torn item names are unique; if that ever changes, first wins and the
            // duplicate is simply not reachable by name.
            if (key && !byName.has(key)) byName.set(key, record);
        }

        return { byId, byName, size: byId.size };
    }

    /**
     * An item list without NPC prices (Torn's v1 fallback, see api/torn.js) is
     * asked for again after this, so real NPC prices return within minutes.
     */
    const ITEMS_PARTIAL_TTL_MS = 5 * 60 * 1000;

    /** Wrap a raw payload with the metadata the cache policy needs. */
    function makeItemsCacheEntry(rawItems, now = Date.now()) {
        const partial = Object.values(rawItems || {}).some((i) => i && i.npc_unknown);
        return {
            version: ITEMS_CACHE_VERSION,
            fetchedAt: now,
            items: rawItems,
            ...(partial ? { partial: true } : {}),
        };
    }

    /** True when a stored entry is the right shape, right version, and not stale. */
    function isItemsCacheFresh(entry, now = Date.now(), ttl = ITEMS_TTL_MS) {
        if (!entry || typeof entry !== 'object') return false;
        if (entry.version !== ITEMS_CACHE_VERSION) return false;
        if (!entry.items || typeof entry.items !== 'object') return false;
        if (!Number.isFinite(entry.fetchedAt)) return false;

        return now - entry.fetchedAt < (entry.partial ? Math.min(ttl, ITEMS_PARTIAL_TTL_MS) : ttl);
    }

    /**
     * Look an item up by display name. Returns null on a miss - never a guess.
     *
     * @param {object} index - from buildItemIndex
     */
    function findItemByName(index, name) {
        if (!index || !index.byName) return null;

        const key = normalizeItemName(name);
        if (!key) return null;

        return index.byName.get(key) || null;
    }

    /** Look an item up by id. */
    function findItemById(index, id) {
        if (!index || !index.byId) return null;
        return index.byId.get(String(id)) || null;
    }

    /** An item's category in Torn Bids' filter: Torn's own item type. */
    function itemCategory(item) {
        return (item && typeof item.type === 'string' && item.type.trim()) || 'Other';
    }

    /**
     * How many items each category has, most first (then by name), for the
     * Category dropdown. A category you picked stays listed, with 0, while the
     * items that fill it are still loading: the pick is never dropped under you.
     *
     * @param {string[]} categories - one per item
     * @param {string} [picked]
     * @returns {{category: string, count: number}[]}
     */
    function categoryCounts(categories, picked = '') {
        const n = new Map();
        for (const c of categories) n.set(c, (n.get(c) || 0) + 1);
        if (picked && !n.has(picked)) n.set(picked, 0);
        return [...n]
            .map(([category, count]) => ({ category, count }))
            .sort((a, b) => b.count - a.count || a.category.localeCompare(b.category));
    }

    /*
     * Never flip "Other" (3.14.2, the friend: "nakakahiya itrade" - embarrassing
     * to trade): Torn's Other category joins Clothing on the Never flip list,
     * once - a list saved before keeps its choices and gains "Other"; taking it
     * off again afterwards is yours to keep.
     */
    const NEVER_FLIP_ONCE = 'otherOn3142';

    /** Stored Torn Bids preferences with "Other" added to Never flip once, or null when already done. */
    function neverFlipOtherOnce(stored) {
        const p = stored && typeof stored === 'object' ? stored : {};
        if (p[NEVER_FLIP_ONCE]) return null;
        const never = new Set(Array.isArray(p.neverFlip) ? p.neverFlip : ['Clothing']);
        never.add('Other');
        return { ...p, neverFlip: [...never], [NEVER_FLIP_ONCE]: true };
    }

    /* ===== src/sources/dom/detect.js ===== */
    /*
     * Finding the listing cards on the page.
     *
     * This is the part that has to work, so it uses two strategies and prefers
     * whichever actually finds cards:
     *
     *   1. Image-anchored. Every listing carries an item image whose path holds
     *      the item id (/images/items/206/large.png). Starting there and climbing
     *      to the card is cheap and precise.
     *
     *   2. Content-shaped. Walk the document for elements whose text contains a
     *      price AND "in stock", that are visible and card-sized, then climb to
     *      the smallest ancestor that looks like a whole card (price + stock +
     *      image + plausible dimensions).
     *
     * Strategy 2 is deliberately the same approach as the script that is known to
     * work on live Torn pages. It is slower, so it runs only when strategy 1
     * finds nothing - which keeps the fast path fast without betting the whole
     * feature on it.
     */

    const ITEM_IMAGE_SELECTOR =
        'img[src*="/images/items/"], img[srcset*="/images/items/"]';

    const ITEM_IMAGE_ID_RE = /\/images\/items\/(\d+)\//;

    /** Known card containers, tightest first. */
    const CARD_SELECTOR = [
        '[class*="itemTile"]',
        '[data-testid="item-description"]',
        '[class*="itemDescription"]',
        '[class*="sellerRow"]',
        '[class*="listItem"]',
    ].join(', ');

    const PRICE_RE = /\$\s*[\d,]+/;
    const STOCK_RE = /in\s+stock|in\s+total/i;

    const MAX_CLIMB = 8;

    /** The item id from an image path, or null if it is not an item image. */
    function itemIdFromImage(img) {
        if (!img || typeof img.getAttribute !== 'function') return null;

        const src = img.getAttribute('src') || img.getAttribute('srcset') || '';
        const match = src.match(ITEM_IMAGE_ID_RE);

        return match ? match[1] : null;
    }

    function isVisible(el) {
        if (!el || typeof window === 'undefined') return true;

        const style = window.getComputedStyle(el);
        if (style.display === 'none' || style.visibility === 'hidden') return false;

        const rect = el.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
    }

    function boxOf(el) {
        if (!el || typeof el.getBoundingClientRect !== 'function') {
            return { width: 0, height: 0 };
        }
        return el.getBoundingClientRect();
    }

    function countItemImages(el) {
        try {
            return el.querySelectorAll(ITEM_IMAGE_SELECTOR).length;
        } catch {
            return 0;
        }
    }

    /**
     * Climb from an item image to the element representing ONE listing.
     *
     * The guard that matters: the moment an ancestor contains more than one item
     * image we have climbed into a container holding several listings and must
     * stop. Without it, one card's name gets paired with another card's price -
     * which is the oldest bug in this project.
     */
    function cardFromImage(img) {
        const preferred = img.closest ? img.closest(CARD_SELECTOR) : null;
        if (preferred && countItemImages(preferred) === 1) return preferred;

        let node = img.parentElement;
        let best = null;

        for (let depth = 0; depth < MAX_CLIMB && node; depth += 1) {
            if (countItemImages(node) > 1) break;

            best = node;

            const text = node.textContent || '';
            if (node.querySelector('[aria-label^="Buy"]') || PRICE_RE.test(text)) {
                return node;
            }

            node = node.parentElement;
        }

        return best;
    }

    /** Climb from a price-bearing element to something card-shaped. */
    function cardFromContent(el) {
        let node = el;

        for (let depth = 0; depth < MAX_CLIMB && node; depth += 1) {
            const text = node.textContent || '';
            const box = boxOf(node);

            if (
                PRICE_RE.test(text) &&
                STOCK_RE.test(text) &&
                node.querySelector('img') &&
                box.width >= 150 &&
                box.width <= 600 &&
                box.height >= 60 &&
                box.height <= 400
            ) {
                return node;
            }

            node = node.parentElement;
        }

        return null;
    }

    function dedupe(cards) {
        const seen = new Set();
        const out = [];

        for (const card of cards) {
            if (!card || seen.has(card)) continue;
            seen.add(card);
            out.push(card);
        }

        return out;
    }

    /** Strategy 1: anchored on item images. */
    function findByImage(root) {
        let images;
        try {
            images = Array.from(root.querySelectorAll(ITEM_IMAGE_SELECTOR));
        } catch {
            return { cards: [], images: 0 };
        }

        const cards = dedupe(images.map(cardFromImage).filter(Boolean));

        return { cards, images: images.length };
    }

    /** Is this element card-sized text with a price and a stock count? */
    function looksLikeListing(el) {
        const text = el.textContent || '';
        if (!text || text.length > 500) return false;
        if (!PRICE_RE.test(text) || !STOCK_RE.test(text)) return false;
        if (!isVisible(el)) return false;
        const box = boxOf(el);
        return box.width >= 120 && box.height >= 60;
    }

    /**
     * Strategy 2: shaped like a listing card.
     *
     * Starts from the text that holds a "$" and climbs a few parents, instead of
     * reading the text of EVERY element on the page (each one re-reading all of
     * its children): that ran on every 2.5 s scan of a page with no item images
     * (your own storefront, a page still loading) and cost far more than the page
     * it looked at. A listing's price is always in its own text, so the same
     * cards are found; the climb stops where the text grows past a card's.
     */
    function findByContent(root) {
        const doc = root && (root.nodeType === 9 ? root : root.ownerDocument);
        const start = root && root.nodeType === 9 ? root.body : root;
        if (!doc || !start || typeof doc.createTreeWalker !== 'function') return [];

        const candidates = [];
        const tried = new Set();
        let walker;
        try {
            walker = doc.createTreeWalker(start, 4 /* NodeFilter.SHOW_TEXT */);
        } catch {
            return [];
        }

        for (let node = walker.nextNode(); node; node = walker.nextNode()) {
            if (!node.nodeValue || node.nodeValue.indexOf('$') < 0) continue;
            let el = node.parentElement;
            for (let depth = 0; depth < MAX_CLIMB && el; depth += 1, el = el.parentElement) {
                if (tried.has(el)) break;
                tried.add(el);
                if ((el.textContent || '').length > 500) break;
                if (looksLikeListing(el)) candidates.push(el);
            }
        }

        // In page order, as the old walk over every element returned them.
        const cards = dedupe(candidates.map(cardFromContent).filter(Boolean));
        return cards.sort((a, b) => (a === b ? 0 : a.compareDocumentPosition(b) & 4 ? -1 : 1));
    }

    /**
     * Find every listing card on the page.
     *
     * @returns {{cards: Element[], strategy: string, images: number}}
     */
    function findCards(root) {
        if (!root) return { cards: [], strategy: 'none', images: 0 };

        const byImage = findByImage(root);
        if (byImage.cards.length > 0) {
            return {
                cards: byImage.cards,
                strategy: 'image',
                images: byImage.images,
            };
        }

        const byContent = findByContent(root);

        return {
            cards: byContent,
            strategy: byContent.length > 0 ? 'content' : 'none',
            images: byImage.images,
        };
    }

    /* ===== src/sources/dom/scan.js ===== */
    /*
     * Reading one listing card into numbers.
     *
     * Extraction order, most reliable first:
     *
     *   1. Torn's own buy-control ARIA label, which states everything outright:
     *        "Buy item Hammer, $100, 1 in total."
     *   2. The item image path, which carries the item id: /images/items/1/
     *   3. Text parsing, as a fallback: the first price, and "( N in stock)".
     *
     * Steps 1 and 2 were read off live Torn markup, so where they apply there is
     * no guessing at all. Step 3 exists because a layout that lacks both still
     * needs to work, and it is the approach already proven on live pages.
     */





    /** "Buy item Hammer, $100, 1 in total." */
    const BUY_LABEL_FULL_RE =
        /^buy item\s+(.+?),\s*\$([\d,]+(?:\.\d+)?),\s*([\d,]+)\s*in total/i;

    /** "Buy: Xanax" */
    const BUY_LABEL_NAME_RE = /^buy(?:\s+item)?:?\s+(.+?)\.?$/i;

    const BUY_CONTROL_SELECTOR =
        '[aria-label^="Buy item"], [aria-label^="Buy:"]';

    /** "( 5,931 in stock)" - a market-wide total, NOT stock at this price. */
    const IN_STOCK_RE = /\(?\s*([\d,]+)\s*in\s+stock/i;

    /** "1,805 available" - one seller's stock, which IS at this price. */
    const AVAILABLE_RE = /([\d,]+)\s*available/i;

    /** Every money figure in a block of text, in order. */
    const ALL_PRICES_RE = /\$\s*[\d,]+(?:\.\d+)?/g;

    /** Name cells, when the image alt is missing. */
    const NAME_SELECTOR = '[class*="name___"], [class*="itemName"], .name';

    /**
     * Parse Torn's buy-control ARIA label.
     * @returns {{name: string, price: number|null, qty: number|null}|null}
     */
    function parseBuyLabel(label) {
        if (typeof label !== 'string' || !label.trim()) return null;

        const text = label.trim();

        const full = text.match(BUY_LABEL_FULL_RE);
        if (full) {
            const price = parseMoney(full[2]);
            const qty = parseQuantity(full[3]);

            return {
                name: full[1].trim(),
                price: Number.isFinite(price) && price > 0 ? price : null,
                qty: Number.isFinite(qty) && qty > 0 ? qty : null,
            };
        }

        const bare = text.match(BUY_LABEL_NAME_RE);
        if (bare) return { name: bare[1].trim(), price: null, qty: null };

        return null;
    }

    /**
     * An element's OWN text: its direct text nodes, joined - never its
     * children's. This is a stricter form of "read leaves".
     *
     * A leaf-element rule misses a price that shares its element with a badge:
     * <p>$838,745<span>1%</span></p> has a child, so it is not a leaf, and its
     * full text "$838,7451%" reads as $8,387,451. Own text is "$838,745". It
     * also rejoins what React splits: {'$'}{price} renders two text nodes.
     */
    function ownText(node) {
        let out = '';
        for (const child of node.childNodes || []) {
            if (child.nodeType === 3) out += child.nodeValue;
        }
        return out.replace(/\s+/g, ' ').trim();
    }

    function textOf(node) {
        if (!node) return '';
        return (node.textContent || '').trim();
    }

    /** The item name Torn shows on this card. */
    function nameFromCard(card) {
        const img = card.querySelector('img[alt]');
        const alt = img ? (img.getAttribute('alt') || '').trim() : '';
        if (alt) return alt;

        const named = card.querySelector(NAME_SELECTOR);
        const text = textOf(named);

        return text && text.length < 80 ? text : '';
    }

    /** Catalogue lookup: by id where possible, by name only as a fallback. */
    function resolveItem(card, index, buy) {
        const img = card.querySelector(ITEM_IMAGE_SELECTOR);
        const id = itemIdFromImage(img);

        if (id) {
            const byId = findItemById(index, id);
            if (byId) return byId;
        }

        const name = (buy && buy.name) || nameFromCard(card);
        return findItemByName(index, name);
    }

    /*
     * A bazaar item the viewer cannot buy: Torn's $1 "Dollar Sale" lock. A $1
     * listing is open only to a random few percent of players (by ID); for
     * everyone else the card shows a red padlock, rendered as an element whose
     * class starts with isBlockedForBuying___. There is no seller-set lock, and
     * neither the Torn API nor TornW3B carries a lock flag - the page is the only
     * source, so the page is what is checked. Same selector TornTools uses for
     * its identical "cheaper than the NPC" highlight.
     *
     * Never inferred from a missing price: a card can lack a readable price for
     * other reasons, and that is reported as noPrice, not as locked.
     */
    const LOCKED_SELECTOR = '[class*="isBlockedForBuying"]';

    /** Is this card (or the bazaar item tile around it) locked for the viewer? */
    function isLockedCard(card) {
        if (!card || typeof card.querySelector !== 'function') return false;
        if (card.matches && card.matches(LOCKED_SELECTOR)) return true;
        if (card.querySelector(LOCKED_SELECTOR)) return true;

        // The card found may be the description inside a bazaar tile, with the
        // padlock drawn elsewhere in the tile.
        const tile = card.closest && card.closest('[class*="item___"]');
        return Boolean(tile && tile !== card && tile.querySelector(LOCKED_SELECTOR));
    }

    /*
     * One specific item. On the Item Market a weapon or armour listing is one
     * item with its own stats: every Fiveseven card showed "53.47 damage points"
     * / "49.31 accuracy points" and a Buy label of "1 in total" (read off the
     * owner's page, 2026-09-26). Torn's API calls these non-stackable listings;
     * their only stats are damage, accuracy and armor. A stackable item (Xanax)
     * is one tile for the whole market ("13,531 in total"), with no stats.
     */
    const OWN_STAT_RE = /^[\d.,]+\s+(?:damage|accuracy|armou?r)\s+points$/i;

    /**
     * Is this listing exactly one item at its price? Yes when the card shows
     * the item's own stats and its Buy label (when readable) says 1 in total.
     * @param {Array<string>} statLabels - aria-labels of the card's value cells
     * @param {{qty: number|null}|null} buy - from parseBuyLabel
     */
    function isOneItemListing(statLabels, buy) {
        if (!(statLabels || []).some((l) => OWN_STAT_RE.test(String(l).trim()))) return false;
        return !(buy && buy.qty && buy.qty !== 1);
    }

    /**
     * Read one card.
     * @returns {object|null}
     */
    function readCard(card, index, pageType) {
        // Locked first: never priced, never highlighted, whatever price it shows.
        if (isLockedCard(card)) return { skipped: 'locked' };

        const buyNode = card.querySelector(BUY_CONTROL_SELECTOR);
        const buy = buyNode
            ? parseBuyLabel(buyNode.getAttribute('aria-label'))
            : null;

        const item = resolveItem(card, index, buy);
        if (!item) return { skipped: 'noItem' };

        let marketTotal = null;

        const text = card.textContent || '';

        /*
         * Read LEAF elements, never the row's concatenated text.
         *
         * React emits no whitespace between sibling nodes, so a seller row's
         * textContent is "BCS605$6,9727 availableBUY". The price then parses as
         * $69,727 instead of $6,972 - wildly above any exit price, so the row is
         * judged unprofitable and never highlights, from a number that was never
         * on screen. Each leaf holds exactly one value, so reading leaves removes
         * the ambiguity instead of guessing at it.
         */
        const leaves = [];
        for (const node of card.querySelectorAll('*')) {
            const t = ownText(node);
            if (t) leaves.push(t);
        }

        const priceLeaf = leaves.find((t) => /^\$\s*[\d,]+(?:\.\d+)?$/.test(t));
        const qtyLeaf = leaves.find((t) => /^[\d,]+\s*available$/i.test(t));

        let price = buy && buy.price;
        let priceAssumed = false;

        if (!Number.isFinite(price) || price <= 0) {
            if (priceLeaf) {
                // A leaf that is nothing but a price is unambiguous.
                price = parseMoney(priceLeaf);
                priceAssumed = false;
            } else {
                /*
                 * No dedicated price cell. Reading from text is only a guess when
                 * there is more than one money figure to choose between; with
                 * exactly one, it is the price.
                 */
                const found = text.match(ALL_PRICES_RE) || [];

                price = found.length > 0 ? parseMoney(found[0]) : null;
                priceAssumed = found.length > 1;
            }
        }

        if (!Number.isFinite(price) || price <= 0) return { skipped: 'noPrice' };

        /*
         * Quantity, and crucially WHETHER IT IS AVAILABLE AT THIS PRICE.
         *
         * A category tile reports the market-wide total across every seller
         * ("694,057 in total", "5,931 in stock") while showing only the CHEAPEST
         * price. Multiplying the two is nonsense: of 694,057 Gasoline, only 1,805
         * are at $424 - the next seller wants $520. Doing that produced a
         * confident "+$3.58m" for a trade that does not exist.
         *
         * A seller row ("1,805 available") is the one case where the quantity
         * really is available at the stated price.
         */
        let qty = null;
        let qtyAtPrice = false;
        let qtyAssumed = false;

        if (qtyLeaf) {
            qty = parseQuantity(qtyLeaf);
            qtyAtPrice = Number.isFinite(qty) && qty > 0;
        } else {
            const available = text.match(AVAILABLE_RE);
            if (available) {
                qty = parseQuantity(available[1]);
                qtyAtPrice = Number.isFinite(qty) && qty > 0;
            }
        }

        /*
         * On a BAZAAR, "(390 in stock)" is this one seller's stock, all at the
         * one price shown - a bazaar has a single price per item. Only on the
         * Item Market's category tiles is "in stock" a market-wide total. Reading
         * it as a total everywhere left every bazaar row "qty unknown".
         */
        if (!qtyAtPrice && pageType === 'bazaar' && !(buy && buy.qty)) {
            const inStock = leaves
                .map((t) => t.match(IN_STOCK_RE))
                .find(Boolean) || text.match(IN_STOCK_RE);

            if (inStock) {
                qty = parseQuantity(inStock[1]);
                qtyAtPrice = Number.isFinite(qty) && qty > 0;
            }
        }

        // A weapon or armour card on the Item Market: one item, known - so Min
        // applies to it (amber below Min, green at or above).
        if (!qtyAtPrice && pageType === 'itemmarket') {
            const statLabels = [...card.querySelectorAll('[aria-label]')].map((n) => n.getAttribute('aria-label'));
            if (isOneItemListing(statLabels, buy)) {
                qty = 1;
                qtyAtPrice = true;
            }
        }

        if (!qtyAtPrice) {
            // Market-wide totals are context, never a multiplier.
            const total = buy && buy.qty ? buy.qty : null;
            const inStock = text.match(IN_STOCK_RE);

            marketTotal =
                total || (inStock ? parseQuantity(inStock[1]) : null) || null;

            qty = 1;
            qtyAssumed = true;
        }

        return {
            el: card,
            buyEl: buyNode || null,
            itemId: item.id,
            name: item.name,
            item,
            listingPrice: price,
            priceAssumed,
            qty,
            qtyAtPrice,
            qtyAssumed,
            marketTotal,
            source: pageType,
        };
    }

    /**
     * Read every listing on the current page.
     *
     * @param {string} pageType - from detectPage()
     * @param {Document|Element} root
     * @param {object} ctx
     * @param {object} ctx.index - item index from buildItemIndex()
     * @returns {{listings: Array, diagnostics: object}}
     */
    function scanDom(pageType, root, { index } = {}) {
        const diagnostics = {
            pageType,
            strategy: 'none',
            images: 0,
            cards: 0,
            fromAria: 0,
            noItem: 0,
            noPrice: 0,
            locked: 0,
            priceAssumed: 0,
            qtyAssumed: 0,
            listings: 0,
        };

        if (!root || !index) return { listings: [], diagnostics };

        const found = findCards(root);

        diagnostics.strategy = found.strategy;
        diagnostics.images = found.images;
        diagnostics.cards = found.cards.length;

        const listings = [];

        for (const card of found.cards) {
            const result = readCard(card, index, pageType);

            if (!result || result.skipped) {
                if (result && result.skipped === 'noItem') diagnostics.noItem += 1;
                if (result && result.skipped === 'noPrice') diagnostics.noPrice += 1;
                if (result && result.skipped === 'locked') diagnostics.locked += 1;
                continue;
            }

            if (!result.priceAssumed && !result.qtyAssumed) {
                diagnostics.fromAria += 1;
            }
            if (result.priceAssumed) diagnostics.priceAssumed += 1;
            if (result.qtyAssumed) diagnostics.qtyAssumed += 1;

            listings.push(result);
        }

        diagnostics.listings = listings.length;

        return { listings, diagnostics };
    }

    /* ===== src/sources/dom/fill.js ===== */
    /*
     * The Fill button's side of Torn's pages: in one row, find the price box and
     * the quantity box, and type into them the way Torn's own forms accept.
     *
     * Only on the page you are viewing, only in the row whose Fill you pressed,
     * only after you pressed it. Nothing of Torn's is ever clicked: not the
     * confirm / list / update buttons, and not the tick box of a weapon or
     * armour row (you tick it; Fill types the price).
     *
     * The markup comes from two working 2026 scripts for these pages - Greasy
     * Fork's "Customizable Bazaar Filler" 1.82 (bazaar add / manage) and "Torn
     * Market Filler" 1.1.2 (Item Market add / your listings):
     *
     *   bazaar #/add     li.clearfix; price ".price input"; quantity ".amount input";
     *                    how many you have ".item-amount.qty"; a weapon or armour
     *                    row has "div.amount.choice-container input" (a tick box)
     *   bazaar #/manage  the price in [class*="price___"] as input.input-money
     *   market add       [class*=itemRow___]; price [class*=priceInputWrapper___]
     *                    input.input-money (a visible and a hidden one, both set);
     *                    quantity [class*=amountInputWrapper___] input.input-money;
     *                    single-copy rows have a [class*=checkboxWrapper___] tick box
     *   market view      (your listings) the price only
     */




    /** Our own marks inside Torn's rows. */
    const FILL_BUTTON_CLASS = 'tarc-fillbtn';
    const FILL_TAG_CLASS = 'tarc-filltag';

    const MARKET_ROW_SELECTOR = '[class*="itemRow___"]:not([class*="grayedOut___"])';

    function text(node) {
        return ((node && node.textContent) || '').replace(/\s+/g, ' ').trim();
    }

    function visible(input) {
        if (!input) return false;
        if (input.type === 'hidden') return false;
        return !(input.offsetParent === null && input.getClientRects && input.getClientRects().length === 0);
    }

    /** The first number in a text: "x12", "12", "1,234 in stock". */
    function countIn(value) {
        const m = String(value || '').match(/(\d[\d,]*)/);
        if (!m) return null;
        const n = Number(m[1].replace(/,/g, ''));
        return Number.isFinite(n) && n > 0 ? n : null;
    }

    /**
     * The price and quantity boxes of one row, and how many you have of it.
     *
     * @param {'bazaar-add'|'bazaar-manage'|'market-add'|'market-view'} page
     * @param {Element} row
     * @returns {{price: HTMLInputElement[], qty: HTMLInputElement[], single: boolean, have: number|null}}
     */
    function rowInputs(page, row) {
        const out = { price: [], qty: [], single: false, have: null };
        if (!row || !row.querySelector) return out;

        if (page === 'bazaar-add') {
            // Checked on the owner's real page (2026-09-26): a visible text box and a
            // hidden twin (name="price"), both input.input-money; both are set.
            out.price.push(...row.querySelectorAll('.price input.input-money, .price input[name="price"]'));
            if (!out.price.length) {
                const price = row.querySelector('.price input');
                if (price) out.price.push(price);
            }
            out.single = Boolean(row.querySelector('div.amount.choice-container input, .choice-container input[type="checkbox"]'));
            if (!out.single) {
                const qty = row.querySelector('.amount input');
                if (qty) out.qty.push(qty);
            }
            out.have = countIn(text(row.querySelector('.item-amount.qty'))) || countIn((text(row.querySelector('.name-wrap')).match(/x\s*(\d[\d,]*)\s*$/i) || [])[1]);
            return out;
        }

        if (page === 'bazaar-manage') {
            const group = row.querySelector('[class*="price___"]');
            const inputs = group ? [...group.querySelectorAll('input.input-money')] : [];
            out.price.push(...(inputs.length ? inputs : [...row.querySelectorAll('[class*="price___"] input')]));
            return out;
        }

        if (page === 'market-add' || page === 'market-view') {
            const priceWrap = row.querySelector('[class*="priceInputWrapper___"]');
            if (priceWrap) out.price.push(...priceWrap.querySelectorAll('input.input-money'));
            if (page === 'market-add') {
                out.single = Boolean(row.querySelector('[class*="checkboxWrapper___"] input[type="checkbox"]'));
                if (!out.single) {
                    const qtyWrap = row.querySelector('[class*="amountInputWrapper___"]');
                    if (qtyWrap) out.qty.push(...qtyWrap.querySelectorAll('input.input-money'));
                }
                // "Xanax x12" in the row's name.
                const m = text(row).match(/\bx\s?(\d[\d,]*)/i);
                out.have = m ? countIn(m[1]) : null;
            }
            return out;
        }
        return out;
    }

    /** An Item Market row's item id: its info button's aria-controls, else its picture. */
    function marketRowItemId(row) {
        const info = row.querySelector('[class*="viewInfoButton___"]');
        const m = info && String(info.getAttribute('aria-controls') || '').match(/-(\d+)-/);
        if (m) return m[1];
        const img = row.querySelector(ITEM_IMAGE_SELECTOR) || row.querySelector('img[src*="/items/"]');
        return img ? itemIdFromImage(img) : null;
    }

    /**
     * Every Item Market row on the page you are viewing, with its item.
     *
     * @param {'market-add'|'market-view'} page
     * @returns {{rows: Array<{el, nameEl, itemId, name, item}>, diagnostics: object}}
     */
    function scanMarketRows(page, root, index) {
        const diagnostics = { page, rows: 0, identified: 0, noItem: 0 };
        const rows = [];
        if (!root || !index) return { rows, diagnostics };
        for (const el of root.querySelectorAll(MARKET_ROW_SELECTOR)) {
            if (el.closest && el.closest('#tarc-host')) continue;
            // A row inside a row (Torn nests wrappers): only the outermost counts.
            if (el.parentElement && el.parentElement.closest && el.parentElement.closest(MARKET_ROW_SELECTOR)) continue;
            if (!el.querySelector('[class*="priceInputWrapper___"]')) continue;
            diagnostics.rows += 1;
            const id = marketRowItemId(el);
            const nameEl = el.querySelector('[class*="name___"], [class*="title___"]');
            const name = text(nameEl).replace(/\s*x\s?\d[\d,]*\s*$/i, '');
            const item = (id && findItemById(index, id)) || findItemByName(index, name) || null;
            if (!item) {
                diagnostics.noItem += 1;
                continue;
            }
            diagnostics.identified += 1;
            rows.push({ el, nameEl: nameEl || null, itemId: item.id, name: item.name, item });
        }
        return { rows, diagnostics };
    }

    /** The item a row shows right now, from its picture: /images/items/{id}/. */
    function rowItemIdNow(page, row) {
        if (!row) return null;
        if (page === 'market-add' || page === 'market-view') return marketRowItemId(row);
        const img = row.querySelector(ITEM_IMAGE_SELECTOR) || row.querySelector('img[src*="/items/"]');
        return img ? itemIdFromImage(img) : null;
    }

    /** The price Torn has on file for a row (its box's value attribute), not what is typed now. */
    function savedPrice(inputs) {
        for (const i of inputs || []) {
            const v = Number(String(i.getAttribute('value') || '').replace(/[^\d]/g, ''));
            if (v > 0) return v;
        }
        return null;
    }

    /**
     * Where Fill's settings link goes: Torn's links bar at the top of the page
     * ("Manage items · Personalize · Back" on your bazaar), as the reference
     * script does.
     */
    function linksBar(doc = document) {
        return doc.querySelector('[class*="linksContainer___"]');
    }

    /** What a box holds now, to put back on Undo. */
    function readInputs(inputs) {
        return (inputs || []).map((i) => i.value);
    }

    /**
     * Type a value into Torn's boxes. Torn's forms listen for input events and
     * (the bazaar add page) key-ups; React keeps its own copy of a box's value,
     * so the value goes in through the native setter, which React sees.
     *
     * @param {HTMLInputElement[]} inputs
     * @param {string|string[]} value - one value for all, or one per box (Undo)
     */
    function writeInputs(inputs, value) {
        const list = inputs || [];
        list.forEach((input, i) => {
            let v = Array.isArray(value) ? value[i] : value;
            if (v === undefined || v === null) return;
            // A hidden twin holds the plain number (value="119999"), the visible box the formatted one.
            if (input.type === 'hidden' && !Array.isArray(value)) v = String(v).replace(/[^\d]/g, '');
            const proto = Object.getPrototypeOf(input);
            const desc = Object.getOwnPropertyDescriptor(proto, 'value') || Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
            if (desc && desc.set) desc.set.call(input, String(v));
            else input.value = String(v);
        });
        // One set of events, from the box you can see (Torn mirrors it into the hidden one).
        // The one box that is not a hidden twin is the one you see (asking the page costs a layout of all of it, 3.22.0).
        const shown = list.filter((i) => i && i.type !== 'hidden');
        const target = (shown.length === 1 ? shown[0] : shown.find(visible)) || list[0];
        if (!target) return;
        for (const type of ['input', 'change']) target.dispatchEvent(new Event(type, { bubbles: true }));
        target.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true }));
    }

    /** How a price goes into the box: the bazaar pages show 1,234,567; the Item Market takes digits. */
    function priceText(page, price) {
        const n = Math.round(Number(price));
        return page === 'bazaar-add' || page === 'bazaar-manage' ? n.toLocaleString('en-US') : String(n);
    }

    /** Your own player id, from the page's own data (#torn-user) or the sidebar's profile link. */
    function ownIdFromPage(doc = document) {
        try {
            const raw = doc.getElementById('torn-user');
            const data = raw && raw.value ? JSON.parse(raw.value) : null;
            const id = data && Number(data.id);
            if (id > 0) return String(id);
        } catch {
            /* not there */
        }
        const a = doc.querySelector('#sidebarroot a[href*="profiles.php?XID="], a[class*="menu-value"][href*="profiles.php?XID="]');
        const m = a && String(a.getAttribute('href')).match(/XID=(\d+)/);
        return m ? m[1] : null;
    }

    /* ===== src/sources/dom/trade.js ===== */
    /*
     * Torn's trade page (trade.php), read only. Markup read on the owner's real
     * page on 2026-09-27 (a trade with another player, nothing touched):
     *
     *   View step (#/step=view): .trade-cont
     *     .t-title                         "Trade between A and B"
     *     .user.left  / .user.right        you / them
     *       .title-black                   the name of the other player
     *       ul.cont > li.color1            money: .name "No money in trade" or "$1,234"
     *                 li.color2            items: ul.desc > li > .name "Bag of Candy Kisses x1"
     *                 li.color3            properties
     *
     *   Add step (#step=add): the same item list as your bazaar's add page -
     *     ul.items-cont > li.clearfix, the item id in the picture's path
     *     (/images/items/1321/large.png), .item-amount.qty how many you have,
     *     .amount input[name=amount] (Qty), a tick box instead for one-of-a-kind
     *     items (weapons), rows "disabled" when they cannot be traded, and one
     *     ADD TO TRADE button for the page. One ul.items-cont per category tab
     *     (.all-items first); only the tab you are on is shown. The price and
     *     .info-wrap cells are in each row but hidden (display: none) - read
     *     again on 2026-09-27: marks go in .name-wrap, the visible cell.
     *
     * Nothing here clicks, types or presses anything; Fill (in main.js) types
     * into one row's Qty box when you press it, like Fill on your bazaar.
     */




    /** "Bag of Candy Kisses x12" -> {name, qty}; a line with no "xN" is one. */
    function parseTradeItemLine(text) {
        const s = String(text || '').replace(/\s+/g, ' ').trim();
        if (!s) return null;
        const m = s.match(/^(.*?)\s+x\s?(\d[\d,]*)$/i);
        if (m) return { name: m[1].trim(), qty: Number(m[2].replace(/,/g, '')) };
        return { name: s, qty: 1 };
    }

    /** "$1,234,567" -> 1234567; "No money in trade" (or nothing) -> 0. */
    function parseTradeMoney(text) {
        const m = String(text || '').replace(/\s+/g, '').match(/\$([\d,]+)/);
        return m ? Number(m[1].replace(/,/g, '')) : 0;
    }

    function tradeText(el) {
        return el ? String(el.textContent || '').replace(/\s+/g, ' ').trim() : '';
    }

    /**
     * The trade view, if it is on the page: who it is with, what each side has
     * put in. Null on other steps.
     *
     * @returns {null|{partner: string, you: {money: number, items: Array<{name, qty}>}, them: {money: number, items: Array<{name, qty}>}}}
     */
    function readTradeView(doc = document) {
        const box = doc.querySelector('.trade-cont');
        if (!box) return null;
        const side = (el) => {
            if (!el) return { money: 0, items: [] };
            const money = el.querySelector('ul.cont > li.color1 .name');
            const items = [...el.querySelectorAll('ul.cont > li.color2 ul.desc > li .name')]
                .map((n) => parseTradeItemLine(tradeText(n)))
                .filter((x) => x && !/^no items in trade$/i.test(x.name));
            return { money: parseTradeMoney(tradeText(money)), items };
        };
        const right = box.querySelector('.user.right');
        const partner = right ? tradeText(right.querySelector('.title-black')) : '';
        return { partner, you: side(box.querySelector('.user.left')), them: side(right) };
    }

    /*
     * Which item a row shows, kept per row (3.22.0; the owner: "in the fill all
     * everywhere, is it no longer laggy as well?"). Torn's list can hold over a
     * thousand rows, and each read of the page looked up every row's picture,
     * boxes and name again - for a trade that sends three of them. The picture is
     * looked up once per row (again when Torn redraws it), and only the rows the
     * trade wants are read further.
     */
    const tradeRowItems = new WeakMap();

    function tradeRowItemId(li) {
        const known = tradeRowItems.get(li);
        if (known && known.img.isConnected && known.img.getAttribute('src') === known.src && li.contains(known.img)) return known.itemId;
        const img = li.querySelector(ITEM_IMAGE_SELECTOR) || li.querySelector('img[src*="/items/"]');
        const itemId = img ? itemIdFromImage(img) : null;
        if (itemId) tradeRowItems.set(li, { img, src: img.getAttribute('src'), itemId: String(itemId) });
        else tradeRowItems.delete(li);
        return itemId ? String(itemId) : null;
    }

    /** One row of the add step, or null when it cannot be added (disabled, or no item read). */
    function readTradeAddRow(li) {
        if (!li || !li.classList || li.classList.contains('disabled')) return null;
        const itemId = tradeRowItemId(li);
        if (!itemId) return null;
        const inputs = rowInputs('bazaar-add', li);
        const known = tradeRowItems.get(li);
        const name = tradeText(li.querySelector('.name-wrap .t-overflow')) || (known && known.img.getAttribute('alt')) || '';
        return { el: li, itemId, name, have: inputs.have, qty: inputs.qty[0] || null, single: inputs.single };
    }

    /**
     * The add step's rows you can add: item id, name, how many you have, and
     * the Qty box (or null for a tick-box row - one-of-a-kind items).
     *
     * @param {function|null} [wanted] - (itemId) => boolean: only these items' rows are read (all of them without it)
     * @returns {Array<{el: Element, itemId: string, name: string, have: number|null, qty: HTMLInputElement|null, single: boolean}>}
     */
    function readTradeAddRows(doc = document, wanted = null) {
        const out = [];
        // Every category tab's list: the one you switch to is marked too.
        for (const li of doc.querySelectorAll('ul.items-cont li.clearfix')) {
            if (li.classList.contains('disabled')) continue;
            const itemId = tradeRowItemId(li);
            if (!itemId || (wanted && !wanted(itemId))) continue;
            const row = readTradeAddRow(li);
            if (row) out.push(row);
        }
        return out;
    }

    /* ===== src/sources/dom/float.js ===== */
    /*
     * Marks on Torn's pages take no room (3.20, the owner: "it shouldn't resize
     * a row, add columns etc. it should just sit at the side or on top like a
     * bring to front").
     *
     * A mark is taken out of the line (absolutely placed, .tarc-float in
     * styles.js), so the Torn element it sits in keeps its size, its padding and
     * its wrapping. Where that element is a block of text, the mark stays just
     * after what comes before it - its static position - with no measuring at
     * all. Where it lays its children out as a row or a grid, that position
     * would be the element's start, over Torn's own content: there the mark is
     * placed after the element before it, by measure.
     *
     * Only our own marks and Torn's element's `position` are ever written (and
     * that only from static to relative, which moves nothing).
     */

    const FLOAT_CLASS = 'tarc-float';
    /* The group of prices and Fill floating in a row of your bazaar's manage page or the Item Market's. */
    const ROW_FLOAT_CLASS = 'tarc-rowfloat';
    /* Torn's element we made a containing block (static -> relative). */
    const POSITIONED_FLAG = 'tarcPos';

    function viewOf(el) {
        return (el && el.ownerDocument && el.ownerDocument.defaultView) || null;
    }

    /** Make Torn's element the containing block of our marks: relative only when it was static. */
    function holdMarks(el) {
        const view = viewOf(el);
        if (!el || !view || el.dataset[POSITIONED_FLAG]) return;
        if (view.getComputedStyle(el).position === 'static') {
            el.style.position = 'relative';
            el.dataset[POSITIONED_FLAG] = '1';
        }
    }

    /** Torn's element as it was, once our marks in it are gone. */
    function releaseMarks(el) {
        if (!el || !el.dataset || !el.dataset[POSITIONED_FLAG]) return;
        el.style.removeProperty('position');
        delete el.dataset[POSITIONED_FLAG];
    }

    /** The element before `mark` that is Torn's, not one of ours. */
    function tornBefore(mark) {
        let prev = mark.previousElementSibling;
        while (prev && /(^|\s)tarc-/.test(String(prev.className || ''))) prev = prev.previousElementSibling;
        return prev;
    }

    /**
     * Float `mark` where it sits in its parent: after what comes before it, out
     * of the line. Cheap when the parent is a block (one style read); measured
     * when it is a row or a grid. Writes only what changed.
     */
    function placeFloat(mark) {
        if (!mark) return;
        if (!mark.classList.contains(FLOAT_CLASS)) mark.classList.add(FLOAT_CLASS);
        const parent = mark.parentElement;
        const view = viewOf(mark);
        if (!parent || !view) return;
        const display = view.getComputedStyle(parent).display;
        if (!/flex|grid/.test(display)) {
            if (mark.style.left) mark.style.removeProperty('left');
            if (mark.style.top) mark.style.removeProperty('top');
            return;
        }
        holdMarks(parent);
        const box = parent.getBoundingClientRect();
        const prev = tornBefore(mark);
        const r = prev ? prev.getBoundingClientRect() : { right: box.left + parent.clientLeft, top: box.top, height: box.height };
        const left = Math.round(r.right - box.left - parent.clientLeft) + 'px';
        const top = Math.round(r.top - box.top - parent.clientTop + (r.height - mark.offsetHeight) / 2) + 'px';
        if (mark.style.left !== left) mark.style.left = left;
        if (mark.style.top !== top) mark.style.top = top;
    }

    /**
     * The group that floats in a row (your bazaar's manage page, the Item
     * Market's rows): created at the row's end, the row made its containing
     * block. Placed by fitRowFloats.
     */
    function rowFloat(rowEl, doc = document) {
        let group = rowEl.querySelector(':scope > .' + ROW_FLOAT_CLASS);
        if (!group) {
            group = doc.createElement('span');
            group.className = ROW_FLOAT_CLASS;
            rowEl.appendChild(group);
        }
        holdMarks(rowEl);
        return group;
    }

    /**
     * Where each row's group goes: just left of Torn's first box in the row
     * (the quantity or the price), centred on the row; with no box, at the row's
     * right. Where it would cover the item's name, its prices give way and only
     * Fill stays (data-tight) - the prices are in the panel's My bazaar too.
     * All reads first, then all writes.
     *
     * @param {Array<{el: Element, nameEl?: Element}>} rows
     */
    function fitRowFloats(rows) {
        const todo = [];
        for (const row of rows || []) {
            const group = row.el && row.el.querySelector(':scope > .' + ROW_FLOAT_CLASS);
            if (!group || !group.firstChild) continue;
            const rect = row.el.getBoundingClientRect();
            if (!rect.width) continue;
            const input = [...row.el.querySelectorAll('input')].find((i) => i.type !== 'hidden' && i.type !== 'checkbox' && i.getBoundingClientRect().width > 0);
            const anchor = input ? input.closest('[class*="InputWrapper"], [class*="inputWrapper"], .input-money-group') || input : null;
            const a = anchor ? anchor.getBoundingClientRect() : null;
            const right = a && a.left > rect.left ? Math.round(rect.right - a.left + 8) : 8;
            const nameEl = row.nameEl && row.nameEl !== row.el ? row.nameEl : null;
            let nameRight = rect.left;
            if (nameEl) {
                const range = nameEl.ownerDocument.createRange();
                range.selectNodeContents(nameEl);
                const nr = range.getBoundingClientRect();
                if (nr.width) nameRight = nr.right;
            }
            todo.push({ group, rect, right, nameRight });
        }
        for (const t of todo) {
            const v = t.right + 'px';
            if (t.group.style.getPropertyValue('--tarc-fr') !== v) t.group.style.setProperty('--tarc-fr', v);
            if (t.group.dataset.tight) delete t.group.dataset.tight;
        }
        for (const t of todo) t.width = t.group.offsetWidth;
        for (const t of todo) {
            const left = t.rect.right - t.right - t.width;
            if (left < t.nameRight + 8) t.group.dataset.tight = '1';
        }
    }

    /** Every row group gone, and the rows given back as they were. */
    function removeRowFloats(root = document) {
        for (const g of root.querySelectorAll('.' + ROW_FLOAT_CLASS)) {
            const row = g.parentElement;
            g.remove();
            if (row && !row.querySelector('.' + ROW_FLOAT_CLASS + ', .tarc-float')) releaseMarks(row);
        }
    }

    /*
     * Fill's result beside Torn's page for a few seconds (3.20): it used to be a
     * line added under the row. Fixed in the window, in the free space right of
     * the row when there is some, else just above the row; it catches no click.
     */
    const TOAST_CLASS = 'tarc-toast';
    const TOAST_MS = 4500;

    /* The toast's widest (styles.js): with this much free beside the row it goes there. */
    const TOAST_MAX_W = 400;

    /**
     * @param {Element} rowEl
     * @param {string} text
     * @param {string} [level]
     * @param {Document} [doc]
     * @param {{right: number, top: number}} [at] - the row's place, when the caller has just read it
     *
     * Placed from the row's place alone, by the edge it hangs from (3.22.0): its
     * own size is never asked for - on a long page each such question made the
     * browser lay the whole page out again.
     */
    function showToast(rowEl, text, level = '', doc = document, at = null) {
        const view = viewOf(rowEl) || (doc && doc.defaultView);
        if (!view || !text) return null;
        for (const old of doc.querySelectorAll('.' + TOAST_CLASS)) old.remove();
        const r = at || (rowEl && rowEl.getBoundingClientRect ? rowEl.getBoundingClientRect() : { left: 16, right: 16, top: 16, bottom: 16 });
        const toast = doc.createElement('div');
        toast.className = TOAST_CLASS;
        toast.setAttribute('role', 'status');
        if (level) toast.dataset.level = level;
        toast.textContent = text;
        const room = view.innerWidth - r.right - 16;
        if (room >= TOAST_MAX_W) {
            // Free space right of the row: beside it, from the row's top down.
            toast.style.left = Math.round(r.right + 12) + 'px';
            toast.style.top = Math.round(Math.max(8, Math.min(view.innerHeight - 96, r.top))) + 'px';
        } else {
            // Else just above the row, its right edge on the row's.
            toast.style.right = Math.round(Math.max(8, view.innerWidth - r.right)) + 'px';
            toast.style.bottom = Math.round(Math.max(8, Math.min(view.innerHeight - 40, view.innerHeight - r.top + 6))) + 'px';
        }
        doc.body.appendChild(toast);
        view.setTimeout(() => toast.remove(), TOAST_MS);
        return toast;
    }

    /* ===== src/sources/dom/sets-pages.js ===== */
    /*
     * Sets on Torn's own pages (3.24.0, mockups Z6-Z10): where things are on the
     * museum, the points market, a trade and a forum thread, and the small marks
     * Torn Archive floats there.
     *
     * The museum, the points market and the forum were never read as markup when
     * this was written - only as text. So nothing here leans on a class name of
     * theirs: a control is found by the words on it (EXCHANGE, ADD LISTING), a
     * piece by its picture (/images/items/{id}/), a box by standing next to its
     * button. Where the page is not what this expects, nothing is found and
     * nothing is marked; the panel's box still says the numbers.
     *
     * It reads the page and adds marks of its own (absolutely placed, they take
     * no room and catch no click). It never presses anything of Torn's.
     */





    const SET_MARK_CLASS = 'tarc-setmark';
    const SET_FILL_CLASS = 'tarc-setfill';
    /* A hairline on the top edge of a row of Torn's (the points market). */
    const SET_RULE_CLASS = 'tarc-setrule';

    const OURS = '#tarc-host, .' + SET_MARK_CLASS + ', .' + SET_FILL_CLASS + ', .' + SET_RULE_CLASS;
    const OUR_WORDS = '.' + SET_MARK_CLASS;

    function setsShown(el) {
        return Boolean(el && el.getClientRects && el.getClientRects().length);
    }

    function setsOurs(el) {
        return Boolean(el && el.closest && el.closest(OURS));
    }

    function setsWords(el) {
        if (!el) return '';
        let raw = String((el.tagName === 'INPUT' ? el.value : el.textContent) || '');
        // A mark of ours inside the element is not its words (a thread's title was read back with its mark in it).
        if (el.tagName !== 'INPUT' && el.querySelectorAll) for (const m of el.querySelectorAll(OUR_WORDS)) raw = raw.replace(m.textContent, '');
        return raw.replace(/\s+/g, ' ').trim();
    }

    /**
     * A float mark inside one of Torn's elements: made once, its words and state kept up, gone with no words.
     * @param {string} where - '' (the element's top edge, left), 'right' (its right side, centred) or 'under'
     */
    function setMark(host, text, state = '', where = '') {
        if (!host || !host.children) return null;
        let mark = null;
        for (const c of host.children) {
            if (c.classList && c.classList.contains(SET_MARK_CLASS)) {
                mark = c;
                break;
            }
        }
        if (!text) {
            if (mark) {
                mark.remove();
                releaseMarks(host);
            }
            return null;
        }
        if (!mark) {
            mark = host.ownerDocument.createElement('span');
            mark.className = 'tarc-float ' + SET_MARK_CLASS;
            host.appendChild(mark);
            holdMarks(host);
        }
        if (mark.textContent !== text) mark.textContent = text;
        if (mark.dataset.state !== state) mark.dataset.state = state;
        if ((mark.dataset.where || '') !== where) mark.dataset.where = where;
        return mark;
    }

    /** Every Sets mark and Fill button off the page, and Torn's elements given back as they were. */
    function clearSetMarks(doc = document) {
        for (const m of doc.querySelectorAll('.' + SET_MARK_CLASS + ', .' + SET_FILL_CLASS + ', .' + SET_RULE_CLASS)) {
            const host = m.parentElement;
            m.remove();
            if (host && !host.querySelector(':scope > .tarc-float')) releaseMarks(host);
        }
    }

    /** Torn's controls with these words on them (the innermost one of each). */
    function findByWords(doc, re) {
        const found = [];
        for (const el of doc.querySelectorAll('button, input[type="submit"], input[type="button"], a, [role="button"], span.btn, div.btn')) {
            if (setsOurs(el) || !setsShown(el)) continue;
            if (re.test(setsWords(el))) found.push(el);
        }
        return found.filter((el) => !found.some((o) => o !== el && el.contains(o)));
    }

    /** The text boxes you can see nearest a control: in its form, else in what holds it, a few steps up at most. */
    function boxesNear(el, min = 1) {
        let node = el.form || el.parentElement;
        for (let up = 0; node && up < 6; up += 1, node = node.parentElement) {
            const boxes = [...node.querySelectorAll('input')].filter((i) => /^(text|number|tel|)$/.test(i.getAttribute('type') || '') && setsShown(i) && !setsOurs(i));
            if (boxes.length >= min) return { root: node, boxes };
        }
        return { root: null, boxes: [] };
    }

    /** A box and its hidden twin (Torn's money boxes keep the plain number in one), for writeInputs. */
    function boxTwins(box) {
        const group = box && box.closest && box.closest('.input-money-group');
        return group ? [...group.querySelectorAll('input')] : box ? [box] : [];
    }

    /**
     * The museum's EXCHANGE controls you can see, each with the set it swaps and its "number of sets" box (if any).
     * The set is told by the words around the control ("To exchange a Plushie set for 10 points...").
     * @param sets [{ key, museum }]
     * @returns [{ set, button, box, root }]
     */
    function museumExchanges(doc, sets, hash = '') {
        const out = [];
        for (const button of findByWords(doc, /^exchange$/i)) {
            let key = null;
            let root = null;
            let node = button.parentElement;
            for (let up = 0; node && up < 8 && !key; up += 1, node = node.parentElement) {
                const text = String(node.textContent || '');
                // The whole page names every set: no telling from there.
                if (text.length > 6000) break;
                const hits = sets.filter((s) => new RegExp(s.museum.replace(/\s+set$/i, ''), 'i').test(text));
                if (hits.length === 1) {
                    key = hits[0].key;
                    root = node;
                } else if (hits.length > 1) break;
            }
            // Not told by the words: by the tab in the address (museum.php#plushie).
            if (!key) {
                const byHash = sets.find((s) => new RegExp('#/?' + s.hash + '\\b', 'i').test(hash || ''));
                if (byHash) key = byHash.key;
            }
            if (!key) continue;
            const near = boxesNear(button, 1);
            out.push({ set: key, button, box: near.boxes[near.boxes.length - 1] || null, root: root || near.root || button.parentElement });
        }
        return out;
    }

    /**
     * A set's pieces as the page shows them: the element around each piece's picture.
     * @param pieces [{ id }]; @param root where to look (the set's own part of the page, else the page)
     * @returns [{ id, el }]
     */
    function pieceTiles(root, pieces) {
        const out = [];
        for (const p of pieces) {
            const img = [...root.querySelectorAll('img[src*="/images/items/' + p.id + '/"]')].find((i) => setsShown(i) && !setsOurs(i));
            if (!img) continue;
            out.push({ id: p.id, el: img.closest('li') || img.parentElement });
        }
        return out;
    }

    /** The points market's "Add listing": its button, the Points box and the Price each box. Null when not on the page. */
    function pointsListing(doc) {
        const button = findByWords(doc, /^add listing$/i)[0];
        if (!button) return null;
        const { root, boxes } = boxesNear(button, 2);
        if (boxes.length < 2) return null;
        const label = (i) => [i.name, i.id, i.placeholder, i.getAttribute('aria-label')].join(' ').toLowerCase();
        let price = boxes.find((i) => /price|cost/.test(label(i))) || null;
        let amount = boxes.find((i) => i !== price && /amount|point|quant/.test(label(i))) || null;
        // No name to go by: Torn's order on the page, Points and then Price each.
        if (!price || !amount) {
            amount = boxes[0];
            price = boxes[1];
        }
        return { button, amount, price, root };
    }

    /** A row's words, cell by cell with a space between (Torn's cells stand side by side with none), ours left out. */
    function rowWords(el) {
        const parts = [];
        const walk = (node) => {
            for (const c of node.childNodes) {
                if (c.nodeType === 3) parts.push(c.nodeValue);
                else if (c.nodeType === 1 && !c.matches(OUR_WORDS)) walk(c);
            }
        };
        walk(el);
        return parts.join(' ').replace(/\s+/g, ' ').trim();
    }

    /**
     * The points market's list as the page shows it: [{ el, points, each, total }], cheapest first. A row is told by its
     * own numbers (count x price = total), never by a class name of Torn's. Empty when no rows are found, or when they
     * are not in the order of their prices (then nothing can say where a listing would sit).
     */
    function pointsRows(doc) {
        const found = [];
        for (const el of doc.querySelectorAll('li, tr')) {
            if (setsOurs(el) || !setsShown(el)) continue;
            const text = rowWords(el);
            if (text.length > 400 || !text.includes('$')) continue;
            const row = parsePointsRow(text);
            if (row) found.push({ el, ...row });
        }
        // A row holding another row is the list around it: the innermost ones are the listings.
        const inner = found.filter((r) => !found.some((o) => o !== r && r.el.contains(o.el)));
        const by = new Map();
        for (const r of inner) by.set(r.el.parentElement, [...(by.get(r.el.parentElement) || []), r]);
        const rows = [...by.values()].sort((a, b) => b.length - a.length)[0] || [];
        return rows.every((r, i) => !i || r.each >= rows[i - 1].each) ? rows : [];
    }

    /**
     * A hairline on the top edge of one of Torn's rows: on the edge between two rows, with no words on it, so it
     * stands on nothing of Torn's. Absolutely placed: it takes no room and catches no click. `on` false takes it away.
     */
    function setRule(host, on, state = '') {
        if (!host || !host.children) return null;
        let rule = null;
        for (const c of host.children) {
            if (c.classList && c.classList.contains(SET_RULE_CLASS)) {
                rule = c;
                break;
            }
        }
        if (!on) {
            if (rule) {
                rule.remove();
                if (!host.querySelector(':scope > .tarc-float')) releaseMarks(host);
            }
            return null;
        }
        if (!rule) {
            // An <i>, not a <span> or a cell: Torn styles the spans of its rows, and the line must take none of that.
            rule = host.ownerDocument.createElement('i');
            rule.className = 'tarc-float ' + SET_RULE_CLASS;
            host.appendChild(rule);
            holdMarks(host);
        }
        if (rule.dataset.state !== state) rule.dataset.state = state;
        return rule;
    }

    /** Torn's own buttons, links and boxes you can see inside `root`: what a mark of ours never stands on. */
    const TORN_CONTROLS = 'a, button, input, select, textarea, label, [role="button"], .btn, .torn-btn';
    function tornControls(root) {
        return [...root.querySelectorAll(TORN_CONTROLS)].filter((el) => el.type !== 'hidden' && !setsOurs(el) && setsShown(el));
    }

    /** Two boxes on the page share some room (`gap`: how near counts as touching). */
    const boxesMeet = (a, b, gap = 3) => a.left < b.right + gap && a.right > b.left - gap && a.top < b.bottom + gap && a.bottom > b.top - gap;

    /**
     * Put a mark of ours beside one of Torn's controls, in the empty room to its right; where that room is too small,
     * under it. By measure only: nothing of Torn's is sized or moved.
     *
     * It never stands on a button, a link or a box of Torn's (the owner, 2026-10-11, on the points market's "Are you
     * sure ...? Yes / No": "this also blocks my buttons"). Where neither place is free of them, and when the control
     * it belongs to is no longer shown, the mark is not shown at all: the box says the same words.
     * @returns whether the mark is shown
     */
    function markBeside(mark, anchor) {
        const host = mark && mark.parentElement;
        if (!host || !anchor || !anchor.getBoundingClientRect) return false;
        const hide = () => { if (mark.style.visibility !== 'hidden') mark.style.visibility = 'hidden'; return false; };
        if (!setsShown(anchor)) return hide();
        const h = host.getBoundingClientRect();
        const a = anchor.getBoundingClientRect();
        // The room is the widest thing around the control that starts where its own row starts: Torn's panel.
        let room = h;
        let roomEl = host;
        for (let node = host.parentElement, up = 0; node && up < 6 && node !== host.ownerDocument.body; node = node.parentElement, up += 1) {
            const r = node.getBoundingClientRect();
            if (Math.abs(r.left - h.left) > 24) break;
            if (r.width > room.width) { room = r; roomEl = node; }
        }
        const m = mark.getBoundingClientRect();
        const width = m.width;
        const half = (m.height || 22) / 2;
        const fits = a.right + 12 + width <= room.right - 6;
        // Beside the control (when it fits there), else under it; `top` is the mark's middle line.
        const spots = [];
        if (fits) spots.push({ left: a.right - h.left + 12, top: a.top - h.top + a.height / 2 });
        spots.push({ left: Math.max(0, Math.min(a.left - h.left, room.right - 6 - width - h.left)), top: a.bottom - h.top + 14 });
        const theirs = tornControls(roomEl).map((el) => el.getBoundingClientRect());
        const free = spots.find((s) => {
            const box = { left: h.left + s.left, right: h.left + s.left + width, top: h.top + s.top - half, bottom: h.top + s.top + half };
            return !theirs.some((r) => boxesMeet(box, r));
        });
        if (!free) return hide();
        const left = Math.round(free.left);
        const top = Math.round(free.top);
        if (mark.style.left !== left + 'px') mark.style.left = left + 'px';
        if (mark.style.top !== top + 'px') mark.style.top = top + 'px';
        if (mark.style.visibility) mark.style.removeProperty('visibility');
        return true;
    }

    /** The other side's item rows on the trade view: [{ el, name, qty }]. */
    function tradeTheirRows(doc) {
        const box = doc.querySelector('.trade-cont');
        if (!box) return [];
        const out = [];
        for (const li of box.querySelectorAll('.user.right ul.cont > li.color2 ul.desc > li')) {
            const n = li.querySelector('.name');
            const it = n ? parseTradeItemLine(setsWords(n)) : null;
            if (it && !/^no items in trade$/i.test(it.name)) out.push({ el: li, name: it.name, qty: it.qty });
        }
        return out;
    }

    /** A forum thread, as far as the page says: its id (from the address) and the headings that may be its title. */
    function forumThread(doc, href) {
        const m = String(href || '').match(/[#&?/]t=(\d+)/);
        const titles = [];
        for (const el of doc.querySelectorAll('h1, h2, h3, h4, .title-black, [class*="thread-name"], [class*="threadName"], [class*="thread-title"], [class*="threadTitle"], [class*="subject"]')) {
            if (setsOurs(el) || !setsShown(el)) continue;
            const text = setsWords(el);
            if (text.length >= 5 && text.length <= 200) titles.push({ el, text });
        }
        return { id: m ? m[1] : null, titles, docTitle: String(doc.title || '') };
    }

    /* ===== src/sources/dom/buy-box.js ===== */
    // A listing on a bazaar or the Item Market, past the card that names it: the whole tile Torn draws for it, and
    // the box you type how many into.
    //
    // The card the scan finds (detect.js) is the part with the picture, the name, the price and the stock. Torn puts
    // the buy controls beside it in the same tile, not inside it: the quantity box and Buy come with the tile's buy
    // menu, once you open it. So what you press, and where a number is typed, is looked for in the tile.
    //
    //
    // SEEN on the owner's own page, 2026-10-11 (a bazaar): the tile is div.item___; closed, it holds the card
    // (div.itemDescription___: picture, a "Buy: <name>" button, name, price, stock). OPEN, the card is NOT on the
    // page: the tile holds only div.buyMenu___ - the name, the price, "(890 in stock)", input.buyAmountInput___ and
    // the Buy button. So an open listing has no picture, and a scan by pictures does not find it. 1.2.0 and 1.2.1
    // took that for "the listing is gone after your press: you bought it", and Fill all never found the box.
    //
    // Nothing here presses or types anything: it only finds.



    /** Torn's own name for one listing's tile on a bazaar (as its lock mark is found, scan.js isLockedCard). */
    const TILE_SELECTOR = '[class*="item___"]';
    /** A quantity box by its look, as Torn Trading finds a bazaar card's (main.js buyQtyInput). */
    const QTY_SELECTOR = 'input[type="number"], input[name*="quant" i], input[placeholder*="quant" i], input[placeholder*="qty" i], input[class*="amount" i], input[class*="quant" i]';
    const TYPING_SELECTOR = 'input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="search"]):not([type="button"]):not([type="submit"])';
    const BB_CLIMB = 4;
    /** A tile is never this many times its card: past that it is the list, not one listing. */
    const BB_AREA = 4;

    const bbImages = (el) => { try { return el.querySelectorAll(ITEM_IMAGE_SELECTOR).length; } catch { return 0; } };
    const bbArea = (el) => { const r = el.getBoundingClientRect ? el.getBoundingClientRect() : null; return r ? r.width * r.height : 0; };

    /**
     * The tile around a listing's card: the largest element that still holds this one listing and nothing else.
     * The card itself when nothing larger is found.
     */
    function listingTile(card) {
        if (!card || !card.closest) return card || null;
        const named = card.closest(TILE_SELECTOR);
        if (named && bbImages(named) === 1) return named;
        const own = bbArea(card);
        let best = card;
        let node = card.parentElement;
        for (let depth = 0; depth < BB_CLIMB && node && node !== card.ownerDocument.body; depth += 1) {
            if (bbImages(node) !== 1) break;
            if (own > 0 && bbArea(node) > own * BB_AREA) break;
            best = node;
            node = node.parentElement;
        }
        return best;
    }

    const bbShown = (input) => !input.disabled && !input.readOnly && input.getClientRects().length > 0 && !input.closest('#tarc-host');

    /** The tile's quantity box, when it is on the page and can be typed in (Torn shows it once the buy menu is open). */
    function buyBox(tile) {
        if (!tile || !tile.querySelectorAll) return null;
        return [...tile.querySelectorAll(QTY_SELECTOR)].find(bbShown) || [...tile.querySelectorAll(TYPING_SELECTOR)].find(bbShown) || null;
    }

    /** Torn's buy form for one listing, while it is open. */
    const MENU_SELECTOR = '[class*="buyMenu"]';
    const bbDigits = (s) => Number(String(s == null ? '' : s).replace(/[^\d]/g, '')) || 0;

    /**
     * The buy forms open on the page: [{ el, tile, name, price, qty, input }]. The form stands where the listing's card
     * was and says the same three things - the name, the price and how many are in stock (0 when it does not say).
     */
    function openBuyMenus(root) {
        const out = [];
        if (!root || !root.querySelectorAll) return out;
        for (const el of root.querySelectorAll(MENU_SELECTOR)) {
            if (el.closest('#tarc-host') || !el.getClientRects().length || out.some((m) => m.el.contains(el))) continue;
            const text = String(el.textContent || '').replace(/\s+/g, ' ');
            const named = el.querySelector('[class*="name"]');
            const name = String(named ? named.textContent : text.split('$')[0]).replace(/\s+/g, ' ').trim();
            const price = bbDigits((text.match(/\$\s?[\d,]+/) || [])[0]);
            const qty = bbDigits((text.match(/([\d,]+)\s+in stock/i) || [])[1]);
            if (!name || !price) continue;
            out.push({ el, tile: el.closest(TILE_SELECTOR) || el, name, price, qty, input: buyBox(el) });
        }
        return out;
    }

    /** Is this tile still a listing on the page - its card, or its buy form in the card's place? */
    function tileHolds(tile) {
        return Boolean(tile && tile.isConnected && (bbImages(tile) > 0 || tile.querySelector(MENU_SELECTOR)));
    }

    /* ===== src/core/accepted.js ===== */
    /*
     * A trade's count, and buys seen on a bazaar page. Pure: no DOM, no network.
     *
     * Cut for Torn Archive from Torn Bids 3.24.0 (core/accepted.js), which was
     * everything about a trade the trader said yes to. What stayed:
     *
     *   - the most items one trade takes (TRADE_MAX_UNITS), the count against it
     *     (tradeCount, through boughtSince) and the one line to say (countView);
     *   - buys seen on the page you are viewing, from a card's stock dropping in
     *     front of you (stockBuys).
     *
     * boughtSince still reads a trade in Torn Bids' shape - {trader: {name}, at,
     * items: [{kind: 'flip'|'yours', itemId, name, units, bid, left, steps:
     * [{qty, price, bought, boughtQty, boughtAt, skipped, sellerName}]}],
     * extra: [{itemId, name, qty, price, bid, seller, at}]} - because the count is
     * worked out there. Accepting, ticking, the buying run, leftovers, Checkout
     * and the log-over-page rules are left behind.
     */

    /*
     * The most items one trade takes (3.23.0; the owner, 2026-10-05: "the 10k
     * limit is per trade"): a count of units - what the plan buys, what you buy
     * outside it and your own To sell lines together. The plan, Add all and Fill
     * all stop at it; what goes over waits in To sell under that trader, for a
     * second trade with them ("yes can go to sell").
     */
    const TRADE_MAX_UNITS = 10000;
    /* From this share of it, the count says how much room is left. */
    const TRADE_NEAR = 0.9;

    /** A step you have been through: bought (all or some), or skipped. */
    function stepDone(step) {
        return Boolean(step && (step.bought || step.skipped || step.boughtQty > 0));
    }

    /** How many of a line to send: yours as planned; a flip what you actually bought, once you started buying it. */
    function sendUnits(line) {
        if (!line) return 0;
        if (line.kind === 'yours') return line.units;
        const started = (line.steps || []).some(stepDone);
        if (!started) return line.units;
        return line.steps.reduce((a, st) => a + (st.bought ? (st.boughtQty > 0 ? st.boughtQty : st.qty) : st.boughtQty || 0), 0);
    }

    /** Units of a line that went to the trader: what you send, minus what they did not take. */
    function takenUnits(line) {
        return Math.max(0, sendUnits(line) - Math.max(0, Math.floor(Number(line && line.left) || 0)));
    }

    /* ------------------------------------ Bought since you accepted (3.14.3) */

    /*
     * The owner, 2026-09-28: a separate window, only while a trade is accepted,
     * listing everything bought for it since "X accepted" - and on Torn's trade
     * page, a checklist: each item ticks itself once it is in the trade, and a
     * warning names what was bought but not added. Picked from mockups/Q: its own
     * window, moved anywhere. Items bought that the trader does not buy are left
     * off; ones they buy that were not planned are orange (red when at a loss).
     * `trade.extra` holds those unplanned buys ({itemId, name, qty, price, seller,
     * at, bid}); nothing fills it until the bazaar page's own purchase message has
     * been read live (the planned steps are counted as before).
     */

    /**
     * Unplanned buys on a bazaar page (3.14.3; the owner: "don't we have enough
     * ... the way the script is written?"): the same way the planned buys are
     * counted - a card's stock on the page you are viewing - for every card.
     * Stock that drops while you are on the page: bought. A card that vanishes:
     * bought only if you pressed a button on it (else someone else bought it out,
     * and it is not counted). A card whose stock the page does not say is never
     * counted. `seen` carries each card's last stock between reads.
     *
     * Torn Archive 1.2.2 (the owner's page, 2026-10-11: buys shown that he never made): a count is never a guess.
     * A listing that is gone counts for no more than the number that stood in its Buy box when you pressed Torn's Buy
     * (`gone` as a Map), and a stock that fell counts only on a listing you pressed in (`pressedIn`): other buyers
     * take from the same bazaar while you look at it.
     *
     * @param {object} seen - key ('itemId|price') -> {qty, itemId, price, name}
     * @param {Array<{itemId, name, listingPrice, qty, qtyAssumed}>} cards - this read
     * @param {Set<string>|Map<string, number>} [gone] - listings gone after your press: their keys, or key -> the most you can have taken
     * Torn Archive 1.3.0: a stock that fell counts for no more than the number in the box when you pressed Torn's Buy
     * there (`pressedIn` as a Map): someone else buying from the listing you have open is not your buy.
     *
     * @param {Set<string>|Map<string, number>|null} [pressedIn] - keys of the listings you pressed in (a Map: key -> the most you can have taken); null = a fallen stock always counts
     * @returns {{bought: Array<{itemId, name, price, qty}>, seen: object}}
     */
    function stockBuys(seen, cards, gone = new Set(), pressedIn = null) {
        const now = {};
        for (const c of cards || []) {
            if (!c || c.qtyAssumed || !(Number(c.qty) > 0) || !(Number(c.listingPrice) > 0)) continue;
            const key = String(c.itemId) + '|' + Number(c.listingPrice);
            const prev = now[key];
            now[key] = { qty: (prev ? prev.qty : 0) + Number(c.qty), itemId: String(c.itemId), price: Number(c.listingPrice), name: c.name || null };
        }
        const bought = [];
        for (const [key, was] of Object.entries(seen || {})) {
            const is = now[key];
            if (is && is.qty < was.qty) {
                if (!pressedIn || pressedIn.has(key)) {
                    const most = pressedIn instanceof Map ? Math.floor(Number(pressedIn.get(key)) || 0) : Infinity;
                    const qty = Math.min(was.qty - is.qty, most);
                    if (qty > 0) bought.push({ itemId: was.itemId, name: was.name, price: was.price, qty });
                }
            } else if (!is && gone.has(key)) {
                const most = gone instanceof Map ? Math.floor(Number(gone.get(key)) || 0) : was.qty;
                const qty = Math.min(was.qty, most);
                if (qty > 0) bought.push({ itemId: was.itemId, name: was.name, price: was.price, qty });
            }
        }
        return { bought, seen: now };
    }

    /**
     * @param {object} trade - an accepted trade (acceptTrade + recordBuy)
     * @param {object} [o]
     * @param {Map<string, number>|null} [o.inside] - lowercase item name -> how many are in Torn's trade now (the trade page), or null elsewhere
     * @returns {{trader, at, rows: Array, extra: Array, toBuy: number, totals: {cost, pays, profit}, missing: Array<{name, qty}>, done: boolean}}
     */
    function boughtSince(trade, { inside = null, max = TRADE_MAX_UNITS } = {}) {
        const rows = [];
        let cost = 0;
        let pays = 0;
        let toBuy = 0;
        for (const i of (trade && trade.items) || []) {
            if (i.kind !== 'flip') continue;
            let qty = 0;
            let spent = 0;
            let at = 0;
            const sellers = [];
            for (const st of i.steps || []) {
                if (!stepDone(st)) {
                    toBuy += 1;
                    continue;
                }
                const n = st.boughtQty > 0 ? st.boughtQty : st.bought ? st.qty : 0;
                if (!n) continue;
                qty += n;
                spent += n * st.price;
                at = Math.max(at, Number(st.boughtAt) || 0);
                if (st.sellerName && !sellers.includes(st.sellerName)) sellers.push(st.sellerName);
            }
            if (!qty) continue;
            const send = takenUnits(i);
            cost += spent;
            pays += send * i.bid;
            rows.push({ itemId: i.itemId, name: i.name, qty, each: spent / qty, bid: i.bid, sellers, at, planned: true, tone: 'planned', send, inTrade: null, profit: send * i.bid - (spent / qty) * send });
        }
        // Bought but not planned: only what this trader buys (the owner: "if the trader doesn't buy it, leave it off").
        const extra = [];
        for (const x of (trade && trade.extra) || []) {
            if (!x || !(x.bid > 0) || !(x.qty > 0)) continue;
            cost += x.qty * x.price;
            pays += x.qty * x.bid;
            extra.push({ ...x, each: x.price, sellers: x.seller ? [x.seller] : [], planned: false, tone: x.bid > x.price ? 'extra' : 'loss', send: x.qty, inTrade: null, profit: x.qty * (x.bid - x.price) });
        }
        const all = [...rows, ...extra].sort((a, b) => (a.at || 0) - (b.at || 0));
        // 10,000 items a trade (3.23.0): in the order you bought, then your own lines. What is over is not
        // sent, not expected money and not asked for by the checklist - it goes to To sell when the trade ends.
        const most = Number(max) > 0 ? Math.floor(Number(max)) : 0;
        let room = most;
        const overBy = new Map();
        for (const r of all) {
            const fit = Math.min(r.send, room);
            room -= fit;
            if (fit < r.send) {
                const cut = r.send - fit;
                const o = overBy.get(r.itemId) || { itemId: r.itemId, name: r.name, qty: 0, cost: 0 };
                o.qty += cut;
                o.cost += cut * r.each;
                overBy.set(r.itemId, o);
                cost -= cut * r.each;
                pays -= cut * r.bid;
                r.over = cut;
                r.send = fit;
                r.profit = fit * (r.bid - r.each);
            }
        }
        const yoursOver = {};
        let yoursSent = 0;
        for (const i of (trade && trade.items) || []) {
            if (i.kind === 'flip') continue;
            const want = takenUnits(i);
            const fit = Math.min(want, room);
            room -= fit;
            yoursSent += fit;
            if (fit < want) yoursOver[String(i.itemId)] = (yoursOver[String(i.itemId)] || 0) + (want - fit);
        }
        const overRows = [...overBy.values()].map((o) => ({ itemId: o.itemId, name: o.name, qty: o.qty, each: o.qty ? o.cost / o.qty : 0 }));
        const units = most - room;
        const count = {
            max: most,
            units,
            room,
            full: units >= most,
            // Nearly full: from nine tenths of it, Checkout says how much room is left.
            near: units < most && units >= most * TRADE_NEAR,
            over: overRows.reduce((a, o) => a + o.qty, 0) + Object.values(yoursOver).reduce((a, n) => a + n, 0),
            // Planned and not bought yet: not in the trade, and said apart.
            toBuy: ((trade && trade.items) || []).reduce((a, i) => a + (i.kind === 'flip' ? (i.steps || []).reduce((b, st) => b + (stepDone(st) ? 0 : Number(st.qty) || 0), 0) : 0), 0),
            overRows,
            yoursOver,
            yoursSent,
        };
        // What is in the trade, shared out in the order you bought: one item bought
        // twice (planned, and again unplanned) is not ticked twice from one count.
        if (inside) {
            const left = new Map([...inside].map(([k, n]) => [String(k).toLowerCase(), n]));
            for (const r of all) {
                const k = String(r.name).toLowerCase();
                r.inTrade = Math.min(r.send, left.get(k) || 0);
                left.set(k, (left.get(k) || 0) - r.inTrade);
            }
        }
        const missing = inside ? all.filter((r) => r.inTrade < r.send).map((r) => ({ name: r.name, qty: r.send - r.inTrade })) : [];
        return {
            trader: trade && trade.trader ? trade.trader.name : null,
            at: trade ? Number(trade.at) || 0 : 0,
            rows: all,
            toBuy,
            totals: { cost, pays, profit: pays - cost },
            missing,
            done: Boolean(inside) && all.length > 0 && !missing.length,
            count,
        };
    }

    /**
     * The trade's items against the most one trade takes (TRADE_MAX_UNITS).
     *
     * @returns {{max, units, room, full, over, toBuy, overRows: Array<{itemId, name, qty, each}>, yoursOver: object, yoursSent: number}}
     *   units: in the trade as it stands - bought (planned and not), and your own
     *   lines; toBuy: planned, not bought yet; over: bought or yours, past the
     *   limit (overRows: what you bought; yoursOver: item id -> units of yours)
     */
    function tradeCount(trade, max = TRADE_MAX_UNITS) {
        return boughtSince(trade, { max }).count;
    }

    /**
     * The count as Checkout and Torn Bids show it (3.23.0): how full, and the one
     * line to say - nothing while there is room, the room left from nine tenths,
     * and where the rest goes once it is full.
     *
     * @param {object|null} count - tradeCount / boughtSince's count
     * @param {string|null} name - the trader
     * @returns {{state: 'ok'|'near'|'full', units, max, pct, text, say}|null}
     */
    function countView(count, name) {
        if (!count || !(count.max > 0)) return null;
        const n = (x) => Number(x).toLocaleString('en-US');
        const who = name || 'them';
        const state = count.full ? 'full' : count.near ? 'near' : 'ok';
        const say = count.over > 0
            ? 'This trade is full. ' + n(count.over) + (count.over === 1 ? ' more goes' : ' more go') + ' to To sell under ' + who + ' when it is done, for a second trade.'
            : count.full
                ? 'This trade is full. Anything more you buy goes to To sell under ' + who + ', for a second trade.'
                : count.near ? 'Room for ' + n(count.room) + ' more in this trade.' : '';
        return {
            state,
            units: count.units,
            max: count.max,
            pct: Math.min(100, Math.round((count.units / count.max) * 1000) / 10),
            text: n(count.units) + ' of ' + n(count.max),
            say,
        };
    }

    /* ===== src/ui/torn-page.js ===== */
    // Torn Archive on Torn's own pages: an overlay beside the page, and marks on the things it is about.
    //
    // The overlay is on every page of Torn's: folded it is one bar (what there is to know, Open, + / –), and it
    // unfolds by itself where it has something to say. It stands only in the empty window beside Torn's content, on
    // the right or on the left: you drag it by its bar, and it stays where you left it. The backtick key folds and
    // unfolds it. Torn Trading's panel on the same page comes first: it keeps its place and that key, and the Archive
    // goes over it or under it in its column, never beside it and never on top of it.
    //
    // A Torn tab never asks Torn's API or TornW3B anything. It shows what the Archive's own tab worked out (shared
    // through storage), reads the page in front of you, and tells the Archive's tab what it saw: a buy on a bazaar,
    // a press of EXCHANGE, your thread's title.
    //
    // It never presses anything of Torn's. A Fill button of the box types a number into Torn's own box, only on
    // your press and only on the page you are looking at; you press Buy, EXCHANGE, ADD LISTING, Change and Accept.
    // The marks take no room and catch no click. Beside Torn Trading's own panel it is shown all the same.
    //
    // On a bazaar the box is a checklist: what to buy here, what you hold of each piece, and a tick the moment you
    // buy. The listings to buy are ringed as Torn Trading rings one. "Fill all" is one press of yours: from then on,
    // on that page, each listing's number is typed into its own quantity box - the ones that are open now, and each
    // other one as you open it or scroll to it (Torn draws only the listings near the screen). You press Buy on each.
    // Typing sends nothing to Torn.
    //
    // 1.3.0. The page is moved for you in two cases only, and only within what Torn has drawn: after a buy of yours
    // the next listing to buy here is brought into view ("automatically puts me to the next item"), and the Down key
    // does the same on your press. The listings still to buy pulse once you have pressed Fill or Fill all. The keys,
    // on a bazaar or the Item Market while something of yours is to buy there, and never while you type: Up = Fill
    // all, Down = the next listing to buy, Right or N = the next bazaar.
    //
    // A buy is never counted at the press of Torn's Buy. It is counted when the page shows the sale: the listing's
    // stock fell (by no more than the number in the box at the press), or the listing left the page and another
    // listing - or the list itself - has stood in its place for a moment. While anything else stands there (a step of
    // Torn's own between Buy and the sale: never read on a real page) nothing is counted, and what stands there is
    // written to the log once, so a zip shows it. With a Full key Torn's own log is the judge either way: it is asked
    // a few seconds after the press (engine.js note 'press'), and a page buy it does not have is taken back
    // (engine/state.js judgeSeen).



















    /** What the Archive's own tab shares with Torn's tabs: { at, v } (core/view.js viewForTabs). */
    const SHARED_VIEW_KEY = 'view';
    /** What Torn's tabs tell the Archive's tab: [{ id, t, kind, what }]. */
    const SHARED_NOTES_KEY = 'notes';
    const NOTES_KEEP_MS = 10 * 60 * 1000;
    /** A view older than this says so instead of showing its numbers. */
    const VIEW_OLD_MS = 15 * 60 * 1000;
    /** The hub shares its view at least once a minute: with none for this long, its tab is closed or asleep. */
    const VIEW_QUIET_MS = 3 * 60 * 1000;
    /**
     * A press in a listing's tile counts for a listing that then vanishes, for this long (as Torn Trading's
     * STOCK_PRESS_MS: typing a number, Buy, then Torn's own "are you sure" take longer than a few seconds).
     */
    const TP_PRESS_MS = 90 * 1000;
    /** A buy seen here is shown on this page at once, until the hub's view holds it - or this long, if it never does. */
    const TP_PEND_MS = 3 * 60 * 1000;
    /**
     * The buys seen in a tab that still wait for the hub: [{ nid, id, qty, t }]. One leaves when the hub's view names
     * its note (`taken`), or when a view worked out more than TP_PEND_MS after it still does not.
     * @param viewAt when the hub worked out the view this tab holds
     */
    /** A bazaar's page is told to the hub again after this long, though nothing on it changed: its rows stay checked. */
    const TP_SHOP_EVERY_MS = 60 * 1000;
    const TP_PIECES = new Set(SETS.flatMap((s) => s.pieces.map((p) => String(p.id))));

    /**
     * The set pieces a bazaar's page shows with a price and a stock: [{ id, price, qty }], a piece listed twice at its
     * cheaper price. A card whose stock is not stated (its Buy box is open and says none) is left out: it says nothing.
     */
    function shopSeen(listings) {
        const by = new Map();
        for (const c of listings || []) {
            const id = String(c && c.itemId);
            const price = Math.floor(Number(c && c.listingPrice)) || 0;
            const qty = c && !c.qtyAssumed ? Math.floor(Number(c.qty)) || 0 : 0;
            if (!TP_PIECES.has(id) || !(price > 1) || !(qty > 0)) continue;
            if (!by.has(id) || price < by.get(id).price) by.set(id, { id, price, qty });
        }
        return [...by.values()].sort((a, b) => (a.id < b.id ? -1 : 1));
    }

    function pendLeft(pend, taken, viewAt) {
        return (pend || []).filter((p) => !taken.has(p.nid) && !(viewAt - p.t > TP_PEND_MS));
    }

    /** The presses of Start, Next and Stop in the box that the hub has not taken yet: [{ nid, op, place, t }]. Every Torn tab reads them. */
    const BOX_PRESSES_KEY = 'boxPresses';
    /** Such a press not taken after this long is said in the box, with Open. */
    const TP_LATE_MS = 4000;
    /** A view the hub worked out this long after a press that still does not name it never will: the press is let go. */
    const TP_PRESS_VIEW_MS = 30 * 1000;

    /**
     * The box's presses of the run still waiting for the hub: not named by its view (`taken`), not older than a note is
     * kept, and not passed over by a view worked out well after them.
     */
    function pressesLeft(list, taken, now, viewAt = 0) {
        return (Array.isArray(list) ? list : []).filter((p) => p && p.nid && !taken.has(p.nid) && now - p.t < NOTES_KEEP_MS && !(viewAt - p.t > TP_PRESS_VIEW_MS));
    }

    /** The view with those presses applied to its run, so the box answers a press at once (core/shopping.js runLocal). */
    function viewWithPresses(v, presses) {
        if (!v || !presses || !presses.length) return v;
        let run = v.buy.run;
        for (const p of presses) run = runLocal(run, p.op, p.place || null);
        return { ...v, buy: { ...v.buy, run } };
    }

    /**
     * Did exactly one listing leave a page that did not move? `prev` and `cur` are the items on the page in page order
     * (one id a picture). Yes when `cur` is `prev` without one of them - with, where Torn draws only the listings near
     * the screen, the next ones drawn at its end. A sort or a filter (the order changes, or many go) proves nothing.
     * @returns { at, id } the one that left, or null
     */
    function oneRemoved(prev, cur) {
        if (!Array.isArray(prev) || !Array.isArray(cur) || !prev.length || cur.length < prev.length - 1) return null;
        let i = 0;
        while (i < prev.length && i < cur.length && prev[i] === cur[i]) i += 1;
        if (i >= prev.length) return null;
        for (let k = i + 1; k < prev.length; k += 1) if (prev[k] !== cur[k - 1]) return null;
        return { at: i, id: prev[i] };
    }
    /** After a press on Torn's page it is looked at again this soon, and once more: Torn redraws in steps. */
    const TP_AFTER_PRESS_MS = [150, 700];
    const TP_SCAN_MS = 250;
    /**
     * A listing that left the page is called gone when another listing, or the list itself, has stood in its place for
     * this long: a list Torn draws again in one go is back well within it.
     */
    const TP_GONE_MS = 800;
    /** A bazaar's page with no item on it at all for this long, fully loaded: told to the hub as empty. */
    const TP_EMPTY_MS = 5000;
    /** The listing the Down key brought you to pulses for this long. */
    const TP_AIM_MS = 4000;
    const TP_DONE_MS = 4000;
    /** Torn Trading's panel is looked at this often while it is on the page: it can be moved, folded, or come later. */
    const TP_OTHER_MS = 1000;
    /** The most of the window's height the overlay takes, as Torn Trading's panel. */
    const TP_TALL = 0.75;
    const TP_TALL_MAX = 640;
    /* Your stock, on its own: its width, and the least height worth showing it in. */
    const TS_WIDTH = 300;
    const TS_MIN_H = 160;
    /** Where you left the overlay: { side, left, top }. Folded or not: 'boxOpen' where it has something to say, 'boxOpenAny' elsewhere. */
    const TP_POS_KEY = 'boxPos';
    /** Where you left your stock: { left, top }. None until you drag it: then it stands beside Torn's page by itself. */
    const TS_POS_KEY = 'stockPos';

    const tpDigits = (v) => Number(String(v == null ? '' : v).replace(/[^\d]/g, '')) || 0;

    /** The page a Torn address is, for the box: '' when it is none of ours. */
    function tornPageKind(href) {
        if (isMuseumPage(href)) return 'museum';
        if (isPointsMarketPage(href)) return 'points';
        if (isTradePage(href)) return 'trade';
        if (isForumPage(href)) return 'forum';
        const page = detectPage(href);
        if (page === PAGE_BAZAAR) return bazaarOwnerId(href) ? 'bazaar' : '';
        if (page === PAGE_ITEM_MARKET) return 'itemmarket';
        return '';
    }

    /** A note for the Archive's tab, added to the shared queue. @returns its id: the shared view names the notes it holds. */
    function pushNote(tabId, kind, what, now = Date.now()) {
        const q = gmGet(SHARED_NOTES_KEY, []);
        const list = (Array.isArray(q) ? q : []).filter((n) => n && now - n.t < NOTES_KEEP_MS);
        const id = tabId + ':' + now.toString(36) + ':' + Math.random().toString(36).slice(2, 6);
        list.push({ id, t: now, kind, what });
        gmSet(SHARED_NOTES_KEY, list.slice(-80));
        return id;
    }

    /**
     * Put the Archive on one of Torn's pages.
     * @param doc    the document
     * @param tabId  this tab's id
     * @param scripted the test page only: presses made by a script count as yours. Never set by the script itself.
     * @returns { scan(), stop() }
     */
    function mountTornPage(doc, { tabId, version = '', scripted = false } = {}) {
        const win = doc.defaultView;
        // Only a press of your own counts: a click made by a script on the page is not one.
        const yours = (event) => scripted || event.isTrusted === true;
        const now = () => Date.now();
        const st = {
            shared: null, index: null, indexAt: 0, kind: '', href: '',
            cards: [], tiles: [], seen: {}, seenPlace: '', pressed: new Map(), images: 0,
            // What this tab saw you buy here: `pend` until the hub's view holds it, `took` for as long as you stay.
            pend: [], took: {}, fillAll: null, fill: [], said: new Set(),
            exchanges: [], presses: [], pressAt: 0, listing: null, imNext: null, moneyBox: null, tradeRows: null, tradeAsked: 0, shopSig: '', shopAt: 0,
            marked: false, html: '', done: '', doneAt: 0, threadSaid: '',
            // Torn's elements holding a note of ours beside a control: the ones of the last look, and of this one.
            notes: new Set(), notesNow: new Set(),
            // Your stock on its own: what this tab adds to the view (buys seen, numbers typed), and its fold.
            live: null, stockOut: null, stockHtml: '', stockOpen: gmGet('stockOpen', true) !== false, stockPos: gmGet(TS_POS_KEY, null),
            // The listing a link of ours named: brought into view once, pulsing until you press anything.
            arrived: '', pulseOff: '',
            // The view with the box's own presses of the run applied, and whether one of them still waits for the hub.
            v: null, late: false,
            // The items on the page in page order at the last look, and where the page stood then: a listing that
            // leaves a page that did not move was sold. `goneHere`: the pieces proven gone from this bazaar (or marked
            // so by you), `goneCand` one that is being confirmed.
            pics: [], lookAt: 0, lookY: 0, lookW: 0, lookH: 0, goneHere: new Map(), goneCand: null, goneT: 0, backSeen: new Set(),
            emptyAt: 0, emptySaid: false, searchEl: null, pressSaid: 0,
            // The listings to buy pulse (Fill or Fill all was pressed here); the one a key or a buy brought you to.
            pulsing: false, aimKey: '', aimAt: 0, wantNext: false, waits: 0,
            open: gmGet('boxOpen', true) !== false, openAny: gmGet('boxOpenAny', false) === true, pinned: false, room: true, timer: 0,
            content: null, has: false, pos: gmGet(TP_POS_KEY, null), strips: { left: null, right: null }, mid: 0, at: null, other: '', drawn: '',
        };

        // ---- our own elements ----------------------------------------------------------------------------------------

        const style = doc.createElement('style');
        style.id = 'tarc-marks';
        style.textContent = MARKS_CSS + BOX_MARKS_CSS;
        (doc.head || doc.documentElement).appendChild(style);

        const host = doc.createElement('div');
        host.id = 'tarc-host';
        const root = host.attachShadow({ mode: 'open' });
        root.innerHTML = `<style>${BOX_CSS}</style>`
            + `<div class="ta" hidden><div class="ta-h" title="Torn Archive: drag to move"><span class="mark">${hIcon('brand')}</span><b>Torn Archive</b><span class="w"></span>`
            + `<button class="open" data-act="hub" title="Open Torn Archive in a new tab">Open</button><button data-act="fold">–</button></div><div class="ta-b"></div></div>`
            + `<div class="ta ts" hidden><div class="ta-h" title="Your stock, as you buy: drag to move"><span class="mark">${hIcon('brand')}</span><b>Your stock</b><span class="w"></span><button class="open" data-act="stock-read" title="Ask Torn for your items now, ahead of everything else">Read</button><button data-act="stock-fold">–</button></div><div class="ta-b"></div></div>`
            + `<button class="pill" hidden data-act="unfold" title="Show Torn Archive"><span class="mark">${hIcon('brand')}</span><span class="pw"></span></button>`;
        doc.body.appendChild(host);
        const box = root.querySelector('.ta');
        const body = root.querySelector('.ta-b');
        const head = root.querySelector('.ta-h');
        const whereEl = root.querySelector('.w');
        const openBtn = root.querySelector('.open');
        const foldBtn = root.querySelector('[data-act="fold"]');
        const pill = root.querySelector('.pill');
        const pillWords = root.querySelector('.pw');
        const stockBox = root.querySelector('.ts');
        const stockHead = stockBox.querySelector('.ta-h');
        const stockBody = stockBox.querySelector('.ta-b');
        const stockWords = stockBox.querySelector('.w');
        const stockFold = stockBox.querySelector('[data-act="stock-fold"]');
        const stockRead = stockBox.querySelector('[data-act="stock-read"]');

        // ---- where it stands ------------------------------------------------------------------------------------------

        /** Torn's content on this page, left edge to right edge: the selectors Torn Trading's panel fits itself by. */
        function tornSides() {
            let parts = [doc.querySelector('.content-wrapper'), doc.getElementById('sidebarroot'), doc.getElementById('sidebar')].filter(Boolean);
            if (!parts.length) parts = [doc.querySelector('#mainContainer') || doc.querySelector('[role="main"]')].filter(Boolean);
            const rects = parts.map((el) => el.getBoundingClientRect()).filter((r) => r.width > 0 && r.height > 0);
            return rects.length ? { left: Math.min(...rects.map((r) => r.left)), right: Math.max(...rects.map((r) => r.right)) } : { left: null, right: null };
        }

        /** Torn Trading's panel on this page, where it shows one. Looked at, never touched: it keeps its place. */
        function tradingRect() {
            const other = doc.getElementById(TRADING_HOST_IDS[0]);
            const panel = other && other.shadowRoot ? other.shadowRoot.querySelector('.ttv2-panel') : null;
            const r = panel ? panel.getBoundingClientRect() : null;
            return r && r.width > 0 && r.height > 0 ? { left: r.left, top: r.top, right: r.right, bottom: r.bottom, width: r.width } : null;
        }

        const isOpen = () => (st.has ? st.open : st.openAny);

        /** Beside Torn's content, on the side you left it; with no room on either side it is a pill you open yourself. */
        function place() {
            const sides = tornSides();
            const other = tradingRect();
            st.strips = overlayStrips({ winW: win.innerWidth, left: sides.left, right: sides.right });
            st.mid = sides.left == null ? win.innerWidth / 2 : (sides.left + sides.right) / 2;
            st.other = other ? [other.left, other.top, other.right, other.bottom].map(Math.round).join() : '';
            const cap = Math.max(OV_BAR, Math.min(win.innerHeight * TP_TALL, TP_TALL_MAX));
            // Measured whole: a `bar` left from the last place hides the body and would measure it as nothing, and
            // the bar itself can be two lines on a narrow strip.
            const open = isOpen() && !box.hidden;
            box.classList.remove('bar', 'folded');
            const barH = Math.max(OV_BAR, head.offsetHeight + 2);
            const want = open ? head.offsetHeight + body.scrollHeight + 2 : barH;
            box.classList.toggle('folded', !isOpen());
            st.at = overlayPlace({ pos: st.pos, strips: st.strips, winH: win.innerHeight, want, cap, other });
            st.room = !!st.at;
            // No room: opened from its pill it stands at the window's edge, over Torn's page, until you fold it.
            const width = Math.min(OV_WIDTH, win.innerWidth - 2 * BOX_GAP);
            const at = st.at || { left: win.innerWidth - width - BOX_GAP, top: OV_TOP, width, maxHeight: Math.max(OV_BAR, win.innerHeight - OV_TOP - BOX_GAP), bar: false };
            box.style.setProperty('--left', at.left + 'px');
            box.style.setProperty('--top', at.top + 'px');
            box.style.setProperty('--width', at.width + 'px');
            box.style.setProperty('--max-h', Math.max(at.maxHeight, barH) + 'px');
            box.classList.toggle('bar', !!at.bar);
        }

        /**
         * Draw the overlay. What this page has to say (a bazaar, a trade, the museum...) is its content; null on a page
         * that is none of ours: there it is the bar, with your sets under it when you unfold it.
         */
        function show(content) {
            st.content = content && content.html ? content : null;
            st.has = !!st.content;
            const fresh = st.shared && now() - st.shared.at < VIEW_OLD_MS;
            const said = st.content || (fresh ? boxAny(st.shared.v) : boxClosed(String(gmGet('key.limited', '') || '').trim() !== '', !!st.shared));
            const open = isOpen();
            const other = tradingOnPage(doc);
            // With no room beside Torn's page it stays a pill until you press it: it would cover the page.
            const away = !st.room && !st.pinned;
            // Unfolded, the bar names the place only: the count is in the body under it, and is not said twice.
            const words = (open ? said.where : said.head || said.where) || '';
            box.hidden = away;
            pill.hidden = !away;
            box.classList.toggle('folded', !open);
            openBtn.classList.toggle('go', !!said.go);
            if (whereEl.textContent !== words) whereEl.textContent = words;
            // The pill is the overlay at its smallest: it says what the folded bar would.
            const small = said.head || said.where || 'Torn Archive';
            if (pillWords.textContent !== small) pillWords.textContent = small;
            // Numbers from the hub are on show (this page's, or your sets): if it has gone quiet, that is said first.
            const html = (st.content || fresh ? boxLate(st.shared.at, now()) : '') + said.html;
            if (st.html !== html) {
                st.html = html;
                const top = body.scrollTop;
                body.innerHTML = html;
                body.scrollTop = top;
            }
            const done = st.done && now() - st.doneAt < TP_DONE_MS ? st.done : '';
            for (const b of body.querySelectorAll('button[data-act]')) {
                const key = b.dataset.act + ':' + (b.dataset.v || '');
                if (key === done) b.dataset.done = '1'; else delete b.dataset.done;
            }
            // Measured again only when what is drawn changed: its place depends on its height.
            const drawn = [away, open, st.has, words].join('|') + html;
            if (st.drawn !== drawn) {
                st.drawn = drawn;
                const was = st.room;
                place();
                if (was !== st.room) { st.drawn = ''; show(content); return; }
            }
            // The + / – after the place is known: unfolded with room for the bar only, it says why.
            const stuck = open && !!st.at && st.at.bar;
            foldBtn.textContent = open && !stuck ? '–' : '+';
            foldBtn.title = stuck ? (st.at.by === 'over' ? 'No room to unfold here: fold the panel under it first' : st.at.by === 'under' ? 'No room to unfold here: fold the panel over it first' : 'No room to unfold here: drag it up') : (open ? 'Fold' : 'Unfold') + (other ? '' : ' (backtick key)');
        }

        /**
         * Your stock on its own, while you buy. Until you move it: on the side of Torn's page the box is not on, and
         * only where that side has room - by itself it never stands over Torn's page; with no room the box's own
         * checklist says what you hold. Dragged by its bar it stands where you left it, anywhere in the window (the
         * owner, 2026-10-11: "can i make my stocklist moveable? its stuck").
         */
        function showStock(out) {
            st.stockOut = out;
            const pos = st.stockPos && Number.isFinite(st.stockPos.left) && Number.isFinite(st.stockPos.top) ? st.stockPos : null;
            const free = out && pos ? overlayFree({ pos, width: TS_WIDTH, winW: win.innerWidth, winH: win.innerHeight, least: st.stockOpen ? TS_MIN_H : OV_BAR }) : null;
            const side = st.at && st.at.side === 'left' ? 'right' : 'left';
            const strip = !free && out && st.at && !box.hidden ? st.strips[side] : null;
            const width = free ? free.width : strip ? Math.min(TS_WIDTH, strip.width) : 0;
            const left = free ? free.left : strip ? (side === 'left' ? strip.to - width : strip.from) : 0;
            let room = free ? free.maxHeight : win.innerHeight - OV_TOP - BOX_GAP;
            const other = strip ? tradingRect() : null;
            if (other && other.left < left + width && other.right > left) room = other.top - OV_TOP - OV_GAP;
            if (!free && (!strip || room < TS_MIN_H)) { stockBox.hidden = true; return; }
            stockBox.hidden = false;
            stockBox.classList.toggle('folded', !st.stockOpen);
            stockBox.classList.toggle('alarm', out.over.length > 0);
            if (stockWords.textContent !== out.head) stockWords.textContent = out.head;
            if (st.stockHtml !== out.html) {
                st.stockHtml = out.html;
                const top = stockBody.scrollTop;
                stockBody.innerHTML = out.html;
                stockBody.scrollTop = top;
            }
            stockFold.textContent = st.stockOpen ? '–' : '+';
            stockBox.style.setProperty('--left', left + 'px');
            stockBox.style.setProperty('--top', (free ? free.top : OV_TOP) + 'px');
            stockBox.style.setProperty('--width', width + 'px');
            stockBox.style.setProperty('--max-h', room + 'px');
        }

        /** Fold or unfold, remembered: apart for the pages where it has something to say and for the rest. */
        function setOpen(on) {
            if (st.has) { st.open = on; gmSet('boxOpen', on); } else { st.openAny = on; gmSet('boxOpenAny', on); }
            if (!on) st.pinned = false;
            show(st.content);
        }

        /** Drag by the bar, to the right or to the left of Torn's content. A press that does not move unfolds a folded bar. */
        function enableDrag() {
            let start = null;
            head.addEventListener('pointerdown', (event) => {
                if (event.button !== 0 || !st.at) return;
                if (event.target.closest && event.target.closest('button, a, input')) return;
                const r = box.getBoundingClientRect();
                start = { x: event.clientX, y: event.clientY, left: r.left, top: r.top, moved: false };
                try { if (head.setPointerCapture) head.setPointerCapture(event.pointerId); } catch { /* a pointer the browser does not track: the drag still follows its moves */ }
            });
            head.addEventListener('pointermove', (event) => {
                if (!start) return;
                const dx = event.clientX - start.x;
                const dy = event.clientY - start.y;
                if (!start.moved && Math.abs(dx) + Math.abs(dy) < 4) return;
                start.moved = true;
                box.classList.add('drag');
                const left = start.left + dx;
                const side = overlaySide(left + box.offsetWidth / 2, st.strips, st.mid);
                if (!side) return;
                st.pos = { side, left: Math.round(left), top: Math.round(start.top + dy) };
                place();
            });
            const end = (event) => {
                if (!start) return;
                const { moved } = start;
                start = null;
                box.classList.remove('drag');
                if (head.hasPointerCapture && head.hasPointerCapture(event.pointerId)) head.releasePointerCapture(event.pointerId);
                if (moved && st.at && st.pos) {
                    // Where you let go, kept inside the window: the bar's own place, also when it stands unfolded upward.
                    st.pos = { side: st.at.side, left: st.at.left, top: Math.min(Math.max(0, st.pos.top), Math.max(0, win.innerHeight - OV_BAR - OV_GAP)) };
                    gmSet(TP_POS_KEY, st.pos);
                    place();
                } else if (!moved && !isOpen()) {
                    setOpen(true);
                }
            };
            head.addEventListener('pointerup', end);
            head.addEventListener('pointercancel', end);
        }
        enableDrag();

        /** Your stock, dragged by its bar: anywhere in the window, and it stays there. A press that does not move unfolds it. */
        function enableStockDrag() {
            let start = null;
            stockHead.addEventListener('pointerdown', (event) => {
                if (event.button !== 0) return;
                if (event.target.closest && event.target.closest('button, a, input')) return;
                const r = stockBox.getBoundingClientRect();
                start = { x: event.clientX, y: event.clientY, left: r.left, top: r.top, moved: false };
                try { if (stockHead.setPointerCapture) stockHead.setPointerCapture(event.pointerId); } catch { /* a pointer the browser does not track: the drag still follows its moves */ }
            });
            stockHead.addEventListener('pointermove', (event) => {
                if (!start) return;
                const dx = event.clientX - start.x;
                const dy = event.clientY - start.y;
                if (!start.moved && Math.abs(dx) + Math.abs(dy) < 4) return;
                start.moved = true;
                stockBox.classList.add('drag');
                st.stockPos = { left: Math.round(start.left + dx), top: Math.round(start.top + dy) };
                showStock(st.stockOut);
            });
            const end = (event) => {
                if (!start) return;
                const { moved } = start;
                start = null;
                stockBox.classList.remove('drag');
                if (stockHead.hasPointerCapture && stockHead.hasPointerCapture(event.pointerId)) stockHead.releasePointerCapture(event.pointerId);
                if (moved && st.stockPos) {
                    // Kept as it stands now, inside the window.
                    const r = stockBox.getBoundingClientRect();
                    st.stockPos = { left: Math.round(r.left), top: Math.round(r.top) };
                    gmSet(TS_POS_KEY, st.stockPos);
                } else if (!moved && !st.stockOpen) {
                    st.stockOpen = true;
                    gmSet('stockOpen', true);
                }
                showStock(st.stockOut);
            };
            stockHead.addEventListener('pointerup', end);
            stockHead.addEventListener('pointercancel', end);
        }
        enableStockDrag();

        // ---- the shared view -----------------------------------------------------------------------------------------

        function loadShared() {
            const s = gmGet(SHARED_VIEW_KEY, null);
            st.shared = s && s.v && s.v.pieces && s.v.sets ? s : null;
            if (st.shared && st.indexAt !== st.shared.at) {
                st.index = buildItemIndex(Object.fromEntries(st.shared.v.pieces.map((p) => [String(p.id), { name: p.name }])));
                st.indexAt = st.shared.at;
            }
        }

        const note = (kind, what) => pushNote(tabId, kind, what, now());
        /** One line for the hub's log (it is in the zip), said once per page of this tab: what the page was seen to hold. */
        const say = (once, what, detail = '') => {
            if (once) { if (st.said.has(once)) return; st.said.add(once); }
            note('say', { what, detail });
        };

        // ---- each page -----------------------------------------------------------------------------------------------

        const cardKey = (c) => String(c.itemId) + '|' + Number(c.listingPrice);

        /** The ring Torn Trading puts on a listing to buy, on ours: '' takes it off. */
        function setRing(el, ring) {
            if (!el || !el.classList) return;
            if (!ring) {
                if (el.classList.contains('tarc-buyhere')) { el.classList.remove('tarc-buyhere'); el.removeAttribute('data-tarc-ring'); }
                return;
            }
            if (!el.classList.contains('tarc-buyhere')) el.classList.add('tarc-buyhere');
            if (el.getAttribute('data-tarc-ring') !== ring) el.setAttribute('data-tarc-ring', ring);
        }

        /** What stands in an element, for the log: its class names two deep, its buttons' words, its first words. */
        function shapeOf(el) {
            if (!el || !el.tagName) return 'nothing';
            const cls = (x) => String((x.className && x.className.baseVal != null ? x.className.baseVal : x.className) || '').replace(/\s*tarc-\S+/g, '').trim() || String(x.tagName).toLowerCase();
            const kids = [...el.children].slice(0, 4).map((k) => cls(k) + (k.children.length ? ' > ' + [...k.children].slice(0, 4).map(cls).join(', ') : '')).join(' | ');
            const buttons = [...el.querySelectorAll('button, [role="button"], a')].slice(0, 5).map((b) => String(b.getAttribute('aria-label') || b.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 24)).filter(Boolean).join(', ');
            const words = String(el.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 120);
            return `${cls(el)}: ${kids || 'no element in it'}${buttons ? ' · buttons: ' + buttons : ''}${words ? ' · words: ' + words : ''}`;
        }

        /**
         * What stands where a listing you pressed Buy on stood:
         *   'held'  its own tile, with its card or its buy form: opened, not bought out;
         *   'gone'  another listing of this page, or the list itself: the listing left;
         *   'away'  that place is out of the window (you scrolled: Torn takes such listings out of the page itself);
         *   'step'  anything else - its tile with neither card nor form, a box over the page, a list drawn anew. Torn's
         *           own step between Buy and the sale was never read on a real page, so nothing is concluded from it.
         */
        function standsThere(p) {
            if (tileHolds(p.tile)) return { state: 'held', el: p.tile };
            if (p.tile && p.tile.isConnected) {
                const r = p.tile.getBoundingClientRect();
                if (r.width > 0 && r.height > 0) return { state: 'step', el: p.tile };
            }
            const x = p.left + p.w / 2 - (win.scrollX - p.x);
            const y = p.top + p.h / 2 - (win.scrollY - p.y);
            if (!(x >= 0 && x < win.innerWidth && y >= 0 && y < win.innerHeight)) return { state: 'away', el: null };
            const stack = doc.elementsFromPoint ? doc.elementsFromPoint(x, y) : [doc.elementFromPoint(x, y)];
            const at = stack.find((el) => el && el.id !== 'tarc-host' && !(el.classList && el.classList.contains('tarc-setmark'))) || null;
            // The list it stood in is no longer on the page, or something lies over it: not known.
            if (!at || !p.list || !p.list.isConnected || !(at === p.list || p.list.contains(at))) return { state: 'step', el: at };
            const tiles = st.tiles.filter((x2) => x2.tile && x2.tile.isConnected);
            // Another listing of this page stands there, or the list's own ground while it still holds listings (a list
            // with none may be one Torn is drawing again: that proves nothing).
            const other = tiles.some((x2) => x2.tile === at || x2.tile.contains(at));
            return other || (at === p.list && tiles.length > 0) ? { state: 'gone', el: at } : { state: 'step', el: at };
        }

        /**
         * The listings you pressed Torn's Buy on that are gone: key -> the number in the box at the press, the most you
         * can have taken. Never at the press itself, and never while Torn's own step may still stand there (until 1.3.0
         * "its tile holds neither card nor form" was read as bought: all 56 buys the page reported on 2026-10-11 came
         * from that rule, ten of them were in no log of Torn's, one of them four times over). A filter or a sort takes
         * many listings out at once: nothing is concluded from that either.
         */
        function pressedGone(t, images) {
            const keys = new Map();
            const many = st.images - images > 1;
            let again = false;
            for (const [k, p] of st.pressed) {
                if (t - p.at > TP_PRESS_MS) { st.pressed.delete(k); continue; }
                // Only Torn's own Buy, pressed in the open form, buys: the number in its box then is the most you took.
                if (!p.buy || !(p.typed > 0)) continue;
                const s = standsThere(p);
                if (s.state !== 'gone' || many) {
                    p.goneAt = 0;
                    if (s.state === 'step') say('step:' + k, 'After your press of Buy something that is no listing stands in its place: nothing is counted from it', 'what stands there: ' + shapeOf(s.el));
                    else if (s.state === 'held' && !buyBox(p.tile) && !p.tile.querySelector('img[src*="/images/items/"]')) say('held:' + k, 'After your press of Buy its buy form stands without a number box', 'what stands there: ' + shapeOf(p.tile));
                    continue;
                }
                if (!p.goneAt) { p.goneAt = t; again = true; continue; }
                if (t - p.goneAt >= TP_GONE_MS) keys.set(k, p.typed); else again = true;
            }
            if (again) lookIn(TP_GONE_MS + 60);
            return keys;
        }

        /** One more look at the page after `ms`, though nothing on it changes meanwhile. One timer for all who ask. */
        function lookIn(ms) {
            if (st.goneT) return;
            st.goneT = win.setTimeout(() => { st.goneT = 0; later(0); }, ms);
        }

        /** Fill all, while it is on: each listing's number into its own open box, once (again only when the number changed and you left ours). */
        function fillAllNow() {
            const fa = st.fillAll;
            if (!fa) return 0;
            let typed = 0;
            for (const f of st.fill) {
                const input = st.tiles[f.i] ? st.tiles[f.i].input : null;
                if (!input || !input.isConnected) continue;
                const had = fa.done.get(input);
                if (had && (had.n === f.n || tpDigits(input.value) !== had.n)) continue;
                fa.done.set(input, { was: had ? had.was : input.value, n: f.n });
                writeInputs(boxTwins(input), String(f.n));
                typed += 1;
            }
            return typed;
        }

        function fillAllOff() {
            const fa = st.fillAll;
            st.fillAll = null;
            if (!fa) return;
            // Put back what was there, where the number is still ours.
            for (const [input, rec] of fa.done) if (input.isConnected && tpDigits(input.value) === rec.n) writeInputs(boxTwins(input), rec.was);
        }

        function onBazaar(v, kind) {
            const place = kind === 'itemmarket' ? IM_PLACE : 'b:' + bazaarOwnerId(st.href);
            const whoId = kind === 'itemmarket' ? '' : bazaarOwnerId(st.href);
            const { listings } = scanDom(kind === 'itemmarket' ? PAGE_ITEM_MARKET : PAGE_BAZAAR, doc, { index: st.index });
            // A listing whose Buy box is open: Torn puts its buy form where the card was, so the scan by pictures does
            // not find it. It is the same listing still, at the same price, and its box is the one Fill types into.
            const menus = openBuyMenus(doc);
            for (const m of menus) {
                const item = findItemByName(st.index, m.name);
                if (!item || listings.some((c) => c.el && m.tile.contains(c.el) && String(c.itemId) === String(item.id))) continue;
                listings.push({ el: m.el, itemId: item.id, name: item.name, listingPrice: m.price, qty: m.qty, qtyAssumed: !m.qty, menu: true });
            }
            if (menus.length) say('menu', 'A Buy box open on a listing', `read as the same listing: ${menus[0].name} at $${menus[0].price}, ${menus[0].qty || 'stock not said'} in stock, its number box ${menus[0].input ? 'found' : 'NOT found'}`);
            st.cards = listings;
            st.tiles = listings.map((c) => { const tile = c.menu ? c.el : listingTile(c.el); return { tile, input: buyBox(tile) }; });
            const t = now();
            // Another place: nothing seen at the last one is carried over, and Fill all is off.
            if (st.seenPlace !== place) {
                st.seen = {}; st.seenPlace = place; st.pressed.clear(); st.took = {}; st.said.clear(); st.images = 0; fillAllOff();
                st.pics = []; st.lookAt = 0; st.goneHere.clear(); st.goneCand = null; st.emptyAt = 0; st.emptySaid = false; st.searchEl = null;
                st.pulsing = false; st.aimKey = ''; st.wantNext = false;
            }
            const pics = [...doc.querySelectorAll('img[src*="/images/items/"]')].map((img) => (String(img.getAttribute('src') || '').match(/\/images\/items\/(\d+)\//) || [])[1] || '');
            const images = pics.length;
            // What you took: a listing's stock that dropped after your press of Buy on it, or a listing you pressed Buy
            // on that left the page.
            const before = st.seen;
            const goneNow = pressedGone(t, images);
            // A stock that fell is yours only on a listing you pressed Torn's Buy on, and for no more than the number in
            // its box then: other buyers take from the same listing while you have it open. (The Item Market's buy step
            // has no form this script knows by name: a press in the listing counts there, as it did.)
            const pressedIn = new Map();
            for (const [k, p] of st.pressed) {
                if (p.buy && p.typed > 0) pressedIn.set(k, p.typed);
                else if (kind === 'itemmarket') pressedIn.set(k, Infinity);
            }
            const r = stockBuys(before, listings, goneNow, pressedIn);
            // A listing you pressed in that says nothing just now (Torn's own words stand in it, or its step): its last
            // stock is kept, so the buy shows as that stock falling when the card is back - and a card back with the
            // stock it had is no buy.
            for (const k of st.pressed.keys()) if (!r.seen[k] && before[k] && !goneNow.has(k)) r.seen[k] = before[k];
            st.seen = r.seen;
            st.images = images;
            const onNow = new Set(listings.map((c) => String(c.itemId)));
            for (const b of r.bought) {
                const key = String(b.itemId) + '|' + Number(b.price);
                const gone = !r.seen[key];
                const typed = (st.pressed.get(key) || {}).typed || 0;
                st.pressed.delete(key);
                const id = String(b.itemId);
                const nid = note('buy', { t, id, qty: b.qty, price: b.price, whoId, im: kind === 'itemmarket' });
                st.pend.push({ nid, id, qty: b.qty, t });
                st.took[id] = (st.took[id] || 0) + b.qty;
                st.wantNext = true;
                // Bought out: this bazaar has none of it left, which the list is told with the page (below).
                if (gone && kind === 'bazaar' && !onNow.has(id)) st.goneHere.set(id, t);
                say('', `A buy seen on the page: ${b.qty} × ${b.name || 'item ' + id} at $${b.price}`, gone ? `the listing left the page after your Buy with ${goneNow.get(key)} in its box, and another listing or the list itself stood in its place for ${TP_GONE_MS} ms` : `the stock on its listing fell after your Buy${typed ? ` with ${typed} in its box` : ''}`);
            }
            // A listing that leaves a page that did not move was sold (or taken down): "item no longer there". Only
            // where the page proves it - the same pictures in the same order but one, no scroll and no resize since the
            // last look, nothing typed in the bazaar's search, not a listing you pressed in (its Buy form takes its
            // card's place), no other listing of that piece here - and only once that has stood for a moment.
            const still = st.lookAt > 0 && win.scrollY === st.lookY && win.innerWidth === st.lookW && win.innerHeight === st.lookH;
            const searching = !!(st.searchEl && st.searchEl.isConnected && String(st.searchEl.value || '').trim());
            if (kind === 'bazaar') {
                for (const id of [...st.goneHere.keys()]) if (onNow.has(id)) st.goneHere.delete(id);
                const cand = st.goneCand;
                if (cand && (onNow.has(cand.id) || !still || searching)) st.goneCand = null;
                else if (cand && t - cand.at >= TP_GONE_MS) {
                    st.goneCand = null;
                    st.goneHere.set(cand.id, t);
                    say('gone:' + cand.id, `A listing left the page while you looked at it: ${(v.pieces.find((p) => String(p.id) === cand.id) || {}).name || 'item ' + cand.id}`, 'the page did not move and the other listings stayed in their order: told to the hub as gone from this bazaar');
                } else if (cand) lookIn(TP_GONE_MS + 60);
                if (!st.goneCand && still && !searching) {
                    const one = oneRemoved(st.pics, pics);
                    if (one && TP_PIECES.has(one.id) && !onNow.has(one.id) && !st.goneHere.has(one.id) && ![...st.pressed.keys()].some((k) => k.startsWith(one.id + '|'))) {
                        st.goneCand = { id: one.id, at: t };
                        lookIn(TP_GONE_MS + 60);
                    }
                }
            }
            st.pics = pics; st.lookAt = t; st.lookY = win.scrollY; st.lookW = win.innerWidth; st.lookH = win.innerHeight;
            // What this bazaar's page shows of your pieces, told to the hub: the page in front of you is the newest look
            // at a bazaar there is (as Torn Trading lets the page correct its list). Told when it changes, and once a
            // minute while you stand here. After the buys above: what it shows is the bazaar after them.
            if (kind === 'bazaar' && whoId) {
                const shop = shopSeen(listings);
                const shown = new Set(shop.map((x) => x.id));
                const items = [...shop, ...[...st.goneHere.keys()].filter((id) => !shown.has(id)).sort().map((id) => ({ id, gone: true }))];
                const sig = whoId + '|' + items.map((x) => (x.gone ? x.id + ':gone' : x.id + ':' + x.price + ':' + x.qty)).join(',');
                if (items.length && (sig !== st.shopSig || t - st.shopAt > TP_SHOP_EVERY_MS)) {
                    st.shopSig = sig;
                    st.shopAt = t;
                    note('shop', { t, whoId, items });
                }
                // "that bazaar is empty already, it still shows it": a bazaar's page, fully loaded, with no item on it
                // at all for a while, and nothing typed in its search. Told once a visit. What such a page holds was
                // never read on a real one: it is written to the log, so a zip shows it.
                const content = doc.querySelector('.content-wrapper, #mainContainer, [role="main"]');
                const none = !images && !menus.length && !searching && doc.readyState === 'complete' && !!content;
                if (!none) st.emptyAt = 0;
                else if (!st.emptyAt) { st.emptyAt = t; lookIn(TP_EMPTY_MS + 100); }
                else if (t - st.emptyAt < TP_EMPTY_MS) lookIn(TP_EMPTY_MS - (t - st.emptyAt) + 100);
                else if (!st.emptySaid) {
                    st.emptySaid = true;
                    note('shop', { t, whoId, items: [], empty: true });
                    say('empty', 'A bazaar with no item on its page: told to the hub as empty', 'what the page holds: ' + shapeOf(content));
                }
            }
            // A buy the page told of that Torn's log does not have (the hub took it back): off what this tab counted
            // as taken here, once.
            for (const b of (v.buy && v.buy.back) || []) {
                const k = String(b.id) + '|' + b.t;
                if (st.backSeen.has(k) || (b.im ? IM_PLACE : 'b:' + b.whoId) !== place) continue;
                st.backSeen.add(k);
                if (st.took[b.id]) st.took[b.id] = Math.max(0, st.took[b.id] - b.qty);
            }
            // Held by the hub's view now (it names the notes it has taken), or never taken: no longer added here.
            const taken = new Set((st.shared && st.shared.notes) || []);
            // A view worked out well after the buy that still does not name it never will. A hub that is closed makes
            // no new view: the buy then stays in this tab's numbers (until 1.2.3 it left after three minutes, and the
            // count fell back to what it was before you bought).
            st.pend = pendLeft(st.pend, taken, st.shared ? st.shared.at : 0);
            const pend = {};
            for (const p of st.pend) pend[p.id] = (pend[p.id] || 0) + p.qty;

            const cards = listings.map((c, i) => {
                const input = st.tiles[i].input;
                return { itemId: c.itemId, price: c.listingPrice, qty: c.qtyAssumed ? 0 : c.qty, typed: input ? tpDigits(input.value) : 0, hasBox: !!input };
            });
            // The Item Market's page is of one piece: its address names it, also while no listing is drawn yet.
            const itemId = kind === 'itemmarket' ? (st.href.match(/[#&?/]itemID=(\d+)/i) || [])[1] || '' : '';
            const live = { pend, took: st.took, fillAll: !!st.fillAll, itemId, gone: new Set(st.goneHere.keys()), late: st.late };
            let out = boxBazaar(v, cards, place, live);
            st.fill = out ? out.fill : [];
            st.waits = out ? out.waits || 0 : 0;
            const typedOf = () => { const by = {}; for (const c of cards) if (c.hasBox && c.typed > 0) by[c.itemId] = (by[c.itemId] || 0) + c.typed; return by; };
            st.live = { pend, typed: typedOf(), here: cards.map((c) => c.itemId) };
            // Fill all is on: the boxes that are open now get their numbers, and the box says so in the same look.
            if (st.fillAll && fillAllNow()) {
                cards.forEach((c, i) => { const input = st.tiles[i].input; c.typed = input ? tpDigits(input.value) : 0; });
                out = boxBazaar(v, cards, place, { ...live, fillAll: true });
                st.fill = out ? out.fill : [];
                st.live.typed = typedOf();
            }
            st.imNext = out ? out.imNext || null : null;
            const marks = new Map((out ? out.marks : []).map((m) => [m.i, m]));
            listings.forEach((c, i) => {
                // Nothing of ours on Torn's open buy form: it is where you type and press.
                const m = c.menu ? null : marks.get(i);
                setMark(c.el, m ? m.text : '', m ? m.state : '');
                setRing(c.el, m ? m.ring : '');
            });
            // Opened from a link of ours that names a listing (the hub's "Sold by", a stop of your run): that listing
            // pulses, and the page is brought to it once when it is on the page. A press of yours ends it.
            // The listings still to buy pulse too, once you pressed Fill or Fill all here ("can it pulsate a bit? on the
            // items i need to buy"), and so does the one the Down key or a buy brought you to. An outline on Torn's own
            // card: it takes no room and catches no click; nothing is put on an open buy form.
            const named = (() => { try { const u = new URL(st.href); return { id: u.searchParams.get('ttItem') || '', price: Number(u.searchParams.get('ttPrice')) || 0 }; } catch { return { id: '', price: 0 }; } })();
            const toBuy = new Set(st.pulsing ? st.fill.map((f) => f.i) : []);
            const aimed = st.aimKey && t - st.aimAt < TP_AIM_MS ? st.aimKey : '';
            let aim = null;
            listings.forEach((c, i) => {
                if (c.menu || !c.el) return;
                const is = !!named.id && st.pulseOff !== st.href && String(c.itemId) === named.id && (!named.price || Number(c.listingPrice) === named.price) && !aim;
                if (is) aim = c.el;
                const want = is ? 'link' : aimed === cardKey(c) ? 'aim' : toBuy.has(i) ? 'buy' : '';
                if ((c.el.getAttribute('data-tarc-pulse') || '') !== want) { if (want) c.el.setAttribute('data-tarc-pulse', want); else c.el.removeAttribute('data-tarc-pulse'); }
            });
            // After a buy of yours: the next listing to buy here, brought into view when it is not.
            if (st.wantNext) { st.wantNext = false; nextListing(true); }
            if (aim && st.arrived !== st.href) {
                st.arrived = st.href;
                const r = aim.getBoundingClientRect();
                if ((r.top < 0 || r.bottom > win.innerHeight) && aim.scrollIntoView) aim.scrollIntoView({ block: 'center', behavior: 'smooth' });
                say('aim', 'Opened from a link that names a listing', 'the listing is on the page: it pulses');
            }
            if (listings.length) {
                const first = st.tiles[0];
                say('cards', `A ${kind === 'itemmarket' ? 'page of the Item Market' : 'bazaar'}: ${listings.length} set piece${listings.length === 1 ? '' : 's'} on the page`, 'the tile around a listing: ' + (first.tile === listings[0].el ? 'the card itself' : (first.tile.className || first.tile.tagName)) + '; the card: ' + (String(listings[0].el.className || '').replace(/\s*tarc-\S+/g, '') || listings[0].el.tagName));
                const open = st.tiles.find((x) => x.input);
                if (open) say('box', 'A quantity box was found in a listing', 'its class: ' + (open.input.className || '(none)') + '; its type: ' + open.input.type);
            }
            return out;
        }

        function onTrade(v) {
            const id = (st.href.match(/[#&?]ID=(\d+)/i) || [])[1] || '';
            const step = /step=addmoney/i.test(st.href) ? 'addmoney' : 'view';
            const rows = tradeTheirRows(doc);
            const t = id ? v.trades.open.find((x) => String(x.id) === id) || null : null;
            const money = step === 'addmoney' ? [...doc.querySelectorAll('.input-money-group input.input-money, input.input-money')].find((i) => i.type !== 'hidden' && i.getClientRects().length && !i.closest('#tarc-host')) || null : null;
            st.moneyBox = money;
            if (!id) return null;
            // The rows as this tab saw them on the trade's own view: the add-money step shows none to compare.
            if (rows.length) st.tradeRows = { id, t: now(), rows: rows.map((r) => ({ name: r.name, qty: r.qty })) };
            const known = st.tradeRows && st.tradeRows.id === id && now() - st.tradeRows.t < VIEW_OLD_MS ? st.tradeRows.rows : null;
            const out = boxTrade(v, t, rows, step, !!money, known);
            // Not the trade the hub read (or not read at all): the hub is asked to read it now, at most every 20 s.
            if (((out && out.changed) || (!t && rows.length)) && now() - (st.tradeAsked || 0) > 20000) { st.tradeAsked = now(); note('trade', { id }); }
            if (out && out.changed) st.moneyBox = null;
            const marks = new Map((out ? out.marks : []).map((m) => [m.i, m]));
            rows.forEach((row, i) => {
                const m = marks.get(i);
                setMark(row.el, m ? m.text : '', m ? m.state : '', 'right');
            });
            return out;
        }

        const pieceWords = (p) => (p.need > 0 ? `${p.held.toLocaleString('en-US')} · need ${p.need.toLocaleString('en-US')}` : p.ahead > 0 ? `${p.held.toLocaleString('en-US')} · ${p.ahead.toLocaleString('en-US')} ahead` : `${p.held.toLocaleString('en-US')} ✓`);

        function swapsSince(at) {
            const off = {};
            for (const p of st.presses) if (p.t > at) off[p.set] = (off[p.set] || 0) + p.sets;
            return off;
        }

        /**
         * A note of ours beside one of Torn's controls (ADD LISTING, EXCHANGE). It lives only as long as that control is
         * on the page: when Torn swaps its form for "Are you sure ...? Yes / No", the next look finds no control, names
         * no note here, and scan() takes the old one away - it used to stay where it was, on top of Yes and No.
         */
        function noteBeside(host, text, state, anchor) {
            const mark = setMark(host, text, state, 'note');
            if (!mark) return;
            st.notesNow.add(host);
            markBeside(mark, anchor);
        }

        function onMuseum(v) {
            const found = museumExchanges(doc, SETS, win.location.hash);
            st.exchanges = found;
            const off = swapsSince(st.shared.at);
            for (const s of v.sets) {
                const ex = found.find((f) => f.set === s.key) || null;
                if (found.length && !ex) continue;
                const less = off[s.key] || 0;
                for (const tile of pieceTiles(ex && ex.root ? ex.root : doc, s.pieces)) {
                    const p = s.pieces.find((x) => String(x.id) === String(tile.id));
                    if (!p) continue;
                    // Sets swapped since the view was worked out come off what you hold; the target stays.
                    const target = p.held + p.need - p.ahead;
                    const held = Math.max(0, p.held - less);
                    const live = { held, need: Math.max(0, target - held), ahead: Math.max(0, held - target) };
                    setMark(tile.el, pieceWords(live), p.top ? 'top' : live.need > 0 ? '' : live.ahead > 0 ? 'ahead' : 'ok');
                }
            }
            // Mockup Z6: more sets typed than you hold is said beside Torn's button. Torn's box is never changed for you.
            for (const ex of found) {
                const s = v.sets.find((x) => x.key === ex.set);
                const host = ex.root || ex.button.parentElement;
                if (!s || !ex.box || !host) continue;
                const full = Math.max(0, s.full - (off[s.key] || 0));
                const over = tpDigits(ex.box.value) > full;
                noteBeside(host, over ? (full ? `You hold ${hNum(full)} full ${full === 1 ? 'set' : 'sets'}` : 'No full set yet') : '', 'bad', ex.button);
            }
            return boxMuseum(v, found.map((f) => ({ set: f.set, hasBox: !!f.box })), off);
        }

        /**
         * The points market (mockup Z7): what the price in Torn's box is, said beside ADD LISTING, and a hairline in
         * Torn's list where that listing would sit - and above which a price is cheap, or a loss. The hairline is on
         * the edge between two rows and carries no words (the owner, 2026-10-11: a line with words on it "blocks the
         * torn page"). Read only: the boxes are looked at as you type, never written here.
         */
        function onPoints(v) {
            const l = pointsListing(doc);
            st.listing = l;
            const rows = pointsRows(doc);
            say('pm', 'The points market, as this tab sees it', `${l ? 'the Points and Price boxes found' : 'the Points and Price boxes NOT found'} · ${rows.length ? `${rows.length} rows of the list read, from ${hMoney(rows[0].each)}` : 'no row of the list could be read: no line is drawn'}`);
            const typed = l ? { amount: tpDigits(l.amount.value), price: tpDigits(l.price.value) } : null;
            const out = boxPoints(v, !!l, { typed, rows: rows.map((r) => ({ points: r.points, each: r.each })) });
            const lines = new Map(out.marks.map((m) => [m.i, m]));
            rows.forEach((r, i) => {
                const m = lines.get(i);
                setRule(r.el, !!m, m ? m.state : '');
            });
            if (l && l.root) noteBeside(l.root, out.note ? out.note.text : '', out.note ? out.note.state : '', l.button);
            return out;
        }

        function onForum(v) {
            const th = forumThread(doc, st.href);
            const pr = v.prices;
            const mine = pr.thread && pr.thread.id != null ? String(pr.thread.id) : '';
            const exact = th.titles.find((t) => t.text === pr.forum.title) || null;
            if (!exact && !(th.id && mine === th.id)) return null;
            const title = exact || th.titles.find((t) => isBuyingTitle(t.text)) || null;
            if (!title) return null;
            // The thread's title as the page shows it: told once per title, so the hub's check is of now.
            const said = (th.id || '') + '|' + title.text;
            if (st.threadSaid !== said) {
                st.threadSaid = said;
                note('thread', { id: th.id, title: title.text });
            }
            const out = boxForum(v, title.text, threadCheck(title.text, { open: pr.open, pct: pr.pct, paid: pr.paidRows }));
            setMark(title.el, out.titleMark.text, out.titleMark.state, 'right');
            return out;
        }

        // ---- one look at the page ------------------------------------------------------------------------------------

        function clear() {
            if (st.marked) {
                clearSetMarks(doc);
                for (const el of doc.querySelectorAll('.tarc-buyhere')) setRing(el, '');
                st.marked = false;
            }
            fillAllOff();
            for (const el of doc.querySelectorAll('[data-tarc-pulse]')) el.removeAttribute('data-tarc-pulse');
            st.pulsing = false;
            st.waits = 0;
            st.goneCand = null;
            st.live = null;
            st.cards = [];
            st.tiles = [];
            st.fill = [];
            st.exchanges = [];
            st.listing = null;
            st.imNext = null;
            st.moneyBox = null;
            st.notes = new Set();
        }

        function scan() {
            st.timer = 0;
            const t = now();
            st.href = win.location.href;
            const kind = tornPageKind(st.href);

            if (kind !== st.kind) {
                clear();
                st.kind = kind;
                st.seen = {};
                st.seenPlace = '';
            }
            if (!st.shared) loadShared();
            const fresh = st.shared && t - st.shared.at < VIEW_OLD_MS;
            // A page that is none of ours, or numbers that would be old: the bar alone says which.
            if (!kind || !fresh) {
                if (kind) clear();
                st.v = null;
                show(null);
                showStock(null);
                return;
            }
            // The hub's view, with the presses of Start, Next and Stop made in a box that it has not taken yet.
            const waiting = pressesLeft(gmGet(BOX_PRESSES_KEY, []), new Set(st.shared.notes || []), t, st.shared.at);
            st.late = waiting.some((p) => t - p.t > TP_LATE_MS);
            const v = viewWithPresses(st.shared.v, waiting);
            st.v = v;
            let out = null;
            st.notesNow = new Set();
            try {
                if (kind === 'bazaar' || kind === 'itemmarket') out = onBazaar(v, kind);
                else if (kind === 'trade') out = onTrade(v);
                else if (kind === 'museum') out = onMuseum(v);
                else if (kind === 'points') out = onPoints(v);
                else if (kind === 'forum') out = onForum(v);
                st.marked = true;
            } catch (error) {
                win.console.error('[Torn Archive] page', kind, error);
                out = null;
            }
            // A note whose control this look did not find is taken off the page.
            for (const host of st.notes) if (!st.notesNow.has(host)) setMark(host, '', '', 'note');
            st.notes = st.notesNow;
            show(out);
            showStock((kind === 'bazaar' || kind === 'itemmarket') && st.live ? boxStock(v, st.live) : null);
        }

        function later(ms = TP_SCAN_MS) {
            if (st.timer) return;
            st.timer = win.setTimeout(scan, ms);
        }

        // ---- presses in the box --------------------------------------------------------------------------------------

        function done(key) {
            st.done = key;
            st.doneAt = now();
            show(st.content);
            win.setTimeout(() => show(st.content), TP_DONE_MS + 50);
        }

        const placeNow = () => (st.kind === 'itemmarket' ? IM_PLACE : 'b:' + bazaarOwnerId(st.href));
        const openStop = (stop) => {
            const first = stop.lines[0];
            win.location.assign(stop.im ? itemMarketUrl(first.id, first.name) : bazaarUrl(stop.whoId, first.id, first.price));
        };

        /**
         * A press of Start, Next or Stop: told to the hub, and applied in this box at once (until 1.3.0 the box showed
         * nothing until the hub answered: "i press stop the run but nothing happens"). Kept until the hub's view names
         * the note; every Torn tab shows it meanwhile.
         */
        function pressRun(op, place = null) {
            const t = now();
            const nid = note('act', { name: 'run', args: place ? [op, place] : [op] });
            gmSet(BOX_PRESSES_KEY, [...pressesLeft(gmGet(BOX_PRESSES_KEY, []), new Set(), t), { nid, op, place, t }].slice(-12));
            later(0);
            win.setTimeout(() => later(0), TP_LATE_MS + 100);
        }

        /**
         * Next, from wherever you stand ("i didnt follow the list, it still wouldnt let me go to next bazaar"): on a
         * bazaar of your list the run goes on from that bazaar, anywhere else from the stop it is on. The stops passed
         * over stay on the list.
         */
        function goNext(v) {
            // The Item Market, with a piece of your list still unvisited: its page, and the run stays on this stop.
            if (st.kind === 'itemmarket' && st.imNext) { win.location.assign(itemMarketUrl(st.imNext.id, st.imNext.name)); return; }
            const stops = v.buy.run.stops;
            const cur = stops.findIndex((s) => s.state === 'cur');
            if (cur < 0) return;
            const here = stops.findIndex((s) => s.place === placeNow());
            const next = stops[(here >= 0 ? here : cur) + 1] || null;
            pressRun('next', here >= 0 ? placeNow() : null);
            if (next) openStop(next);
        }

        /** Fill all, on: by its button, or the Up key. */
        function fillAllOn() {
            if (st.fillAll || (st.kind !== 'bazaar' && st.kind !== 'itemmarket')) return;
            st.fillAll = { done: new Map() };
            st.pulsing = true;
            say('', 'Fill all pressed', `${st.fill.length} listing${st.fill.length === 1 ? '' : 's'} to type into, ${st.tiles.filter((x) => x.input).length} quantity box${st.tiles.filter((x) => x.input).length === 1 ? '' : 'es'} open`);
            later(0);
        }

        /**
         * The next listing to buy on this page, brought into view: on the Down key (each press the one after), and by
         * itself after a buy of yours. Only among the listings Torn has drawn. With none of them drawn and lines of
         * your list still waiting, a press of Down goes one step down the page - Torn draws the listings near the
         * screen only - and from its foot back to its top. Nothing of Torn's is pressed.
         */
        function nextListing(auto = false) {
            const rows = st.fill.map((f) => st.cards[f.i]).filter((c) => c && c.el && c.el.isConnected);
            if (!rows.length) {
                if (auto || !st.waits) return;
                const foot = win.scrollY + win.innerHeight >= doc.documentElement.scrollHeight - 2;
                win.scrollTo({ top: foot ? 0 : win.scrollY + Math.round(win.innerHeight * 0.8), behavior: 'smooth' });
                return;
            }
            const was = auto ? -1 : rows.findIndex((c) => cardKey(c) === st.aimKey);
            const c = rows[(was + 1) % rows.length];
            st.aimKey = cardKey(c);
            st.aimAt = now();
            const r = c.el.getBoundingClientRect();
            if ((r.top < 0 || r.bottom > win.innerHeight) && c.el.scrollIntoView) c.el.scrollIntoView({ block: 'center', behavior: 'smooth' });
            win.setTimeout(() => later(0), TP_AIM_MS + 60);
            later(0);
        }

        /** The run's stop, from a page that is not it: opened on your press, and the run stays where it is. */
        function goStop(v) {
            const cur = v.buy.run.stops.find((s) => s.state === 'cur');
            if (cur && cur.place !== placeNow()) openStop(cur);
        }

        function press(btn) {
            const act = btn.dataset.act;
            const val = btn.dataset.v || '';
            const n = tpDigits(btn.dataset.n);
            const v = st.v || (st.shared ? st.shared.v : null);
            if (act === 'fold') { if (!(isOpen() && st.at && st.at.bar)) setOpen(!isOpen()); return; }
            if (act === 'unfold') { st.pinned = true; setOpen(true); return; }
            if (act === 'stock-fold') { st.stockOpen = !st.stockOpen; gmSet('stockOpen', st.stockOpen); showStock(st.stockOut); return; }
            if (act === 'stock-read') {
                // A Torn tab asks Torn nothing itself: the Archive's own tab does, your items first. With that tab
                // closed or gone quiet nothing would answer, so it is opened: it reads your items as it starts.
                const quiet = !st.shared || now() - st.shared.at > VIEW_QUIET_MS;
                if (quiet) gmOpenTab(ARCHIVE_PAGE_URL);
                else note('read', { what: 'stock' });
                stockRead.textContent = quiet ? 'Opened' : 'Asked ✓';
                win.setTimeout(() => { stockRead.textContent = 'Read'; }, TP_DONE_MS);
                return;
            }
            if (act === 'hub') { gmOpenTab(ARCHIVE_PAGE_URL); return; }
            // A piece of your stock: Torn Archive opens on its Buy page, on that piece (ui/hub.js reads the address).
            if (act === 'plan') { gmOpenTab(ARCHIVE_PAGE_URL + (tpDigits(val) ? '#buy/' + tpDigits(val) : '#buy')); return; }
            if (act === 'copy') { if (gmCopy(val)) done('copy:' + val); return; }
            if (act === 'open-trade') { win.location.assign(tradeViewUrl(val)); return; }
            if (!v) return;
            if (act === 'run-start') { pressRun('start'); return; }
            if (act === 'run-stop') { pressRun('stop'); return; }
            if (act === 'run-next') { goNext(v); return; }
            if (act === 'run-go') { goStop(v); return; }
            // "item no longer there": a line of your list that is not on this bazaar's page, marked gone by you. The
            // hub is told as it is told what the page shows, and makes the list again without it.
            if (act === 'gone') {
                if (st.kind !== 'bazaar' || !tpDigits(val)) return;
                st.goneHere.set(String(tpDigits(val)), now());
                st.shopSig = '';
                say('', 'Gone pressed on a line of your list', 'item ' + tpDigits(val) + ': not on the page of this bazaar');
                later(0);
                return;
            }
            // Fill: a number typed into Torn's own box, on this press. Nothing of Torn's is pressed.
            if (act === 'fill-all') {
                // On from this press, on this page only; a second press puts back what was there.
                if (st.fillAll) { fillAllOff(); st.pulsing = false; later(0); } else fillAllOn();
            } else if (act === 'fill-card') {
                const tile = st.tiles[Number(val)];
                const input = tile && tile.input && tile.input.isConnected ? tile.input : null;
                if (input && n > 0) { writeInputs(boxTwins(input), String(n)); st.pulsing = true; done('fill-card:' + val); later(0); }
            } else if (act === 'fill-money') {
                if (st.moneyBox && st.moneyBox.isConnected && tpDigits(val) > 0) { writeInputs(boxTwins(st.moneyBox), String(tpDigits(val))); done('fill-money:' + val); }
            } else if (act === 'fill-museum') {
                const ex = st.exchanges.find((x) => x.set === val && x.box && x.box.isConnected);
                if (ex && n > 0) { writeInputs([ex.box], String(n)); done('fill-museum:' + val); }
            } else if (act === 'fill-points') {
                const l = st.listing;
                if (l && l.amount.isConnected && l.price.isConnected && tpDigits(val) > 0 && n > 0) {
                    writeInputs(boxTwins(l.amount), String(tpDigits(val)));
                    writeInputs(boxTwins(l.price), String(n));
                    done('fill-points:' + val);
                }
            }
        }

        root.addEventListener('click', (event) => {
            const btn = event.target.closest && event.target.closest('[data-act]');
            if (btn && yours(event)) press(btn);
        });

        // ---- what you do on Torn's page, watched and never done for you ----------------------------------------------

        function onClick(event) {
            if (!yours(event) || !st.shared) return;
            const target = event.target;
            if (!target || !target.closest || target.closest('#tarc-host')) return;
            // A press anywhere in a listing's tile (its Buy box is beside the card, not in it): the listing may vanish
            // because you bought it out.
            if (st.kind === 'bazaar' || st.kind === 'itemmarket') {
                // Any press of yours on the page: the listing a link named stops pulsing.
                if (st.pulseOff !== st.href) { st.pulseOff = st.href; for (const el of doc.querySelectorAll('[data-tarc-pulse="link"]')) el.removeAttribute('data-tarc-pulse'); }
                pressIn(target);
                for (const ms of TP_AFTER_PRESS_MS) win.setTimeout(() => later(0), ms);
                return;
            }
            // The points market and the museum: a press of yours may swap Torn's form for its "Are you sure ...?" by
            // showing and hiding what is already there, which no change of the page's nodes tells us. Looked at once.
            if (st.kind === 'points' || st.kind === 'museum') for (const ms of TP_AFTER_PRESS_MS) win.setTimeout(() => later(0), ms);
            // A press of Torn's EXCHANGE, by you: told to the hub, which writes the points into your book at cost.
            if (st.kind === 'museum') {
                const ex = st.exchanges.find((x) => x.button && x.button.isConnected && (x.button === target || x.button.contains(target)));
                if (!ex) return;
                const t = now();
                const set = st.shared.v.sets.find((s) => s.key === ex.set);
                if (!set) return;
                const full = Math.max(0, set.full - (swapsSince(st.shared.at)[set.key] || 0));
                const typed = ex.box ? tpDigits(ex.box.value) : 1;
                // Nothing typed, or more than you hold: Torn refuses it, and nothing is written. One press, written once.
                if (!(typed >= 1) || typed > full || t - st.pressAt < 3000) return;
                st.pressAt = t;
                st.presses = [...st.presses.filter((p) => t - p.t < 6 * 3600 * 1000), { t, set: set.key, sets: typed }];
                note('swap', { t, set: set.key, sets: typed });
                later(0);
            }
        }

        /** A press of yours in a listing's tile, remembered with where the tile stood. */
        function pressIn(target, enter = false) {
            const i = st.cards.findIndex((c, k) => (st.tiles[k] && st.tiles[k].tile && st.tiles[k].tile.contains(target)) || (c.el && c.el.contains(target)));
            if (i < 0) return false;
            const r = (st.tiles[i].tile || st.cards[i].el).getBoundingClientRect();
            const el = st.tiles[i].tile || st.cards[i].el;
            const tile = (el.closest && el.closest('[class*="item___"]')) || el;
            // The list this listing stands in: the nearest element around it that holds another listing too.
            let list = tile.parentElement;
            while (list && list !== doc.body && !st.tiles.some((x) => x.tile && x.tile !== el && x.tile !== tile && list.contains(x.tile))) list = list.parentElement;
            // Torn's own Buy in the open form (or Enter in its box): the only press that buys, with the number in the box.
            const menu = target.closest ? target.closest('[class*="buyMenu"]') : null;
            const button = target.closest ? target.closest('button') : null;
            const label = button ? String(button.getAttribute('aria-label') || button.textContent || '').trim() : '';
            const box = menu ? buyBox(menu) : null;
            const key = cardKey(st.cards[i]);
            const had = st.pressed.get(key);
            let buy = !!(menu && ((button && /^buy\b/i.test(label)) || (enter && box && box.contains(target))));
            let typed = buy && box ? tpDigits(box.value) : 0;
            // Torn's own Buy, pressed: nothing is counted for it, and the hub is told so that Torn's log is asked a few
            // seconds from now - what was bought is in it.
            if (buy && typed > 0 && now() - st.pressSaid > 1500) {
                st.pressSaid = now();
                note('press', { t: st.pressSaid, id: String(st.cards[i].itemId), whoId: st.kind === 'itemmarket' ? '' : bazaarOwnerId(st.href), im: st.kind === 'itemmarket' });
            }
            // A press on Torn's Close takes the buy back; any other press in the tile (a "Yes" Torn may ask for) keeps it.
            if (!buy && had && had.buy && !(button && /^(close|no|cancel)\b/i.test(label))) { buy = true; typed = had.typed; }
            // The tile itself is kept: a listing is gone only when its tile is (a buy form in it is the listing, open).
            st.pressed.set(key, { at: now(), x: win.scrollX, y: win.scrollY, left: r.left, top: r.top, w: r.width, h: r.height, tile, list, buy, typed, goneAt: 0 });
            return true;
        }

        function onKey(event) {
            if (!yours(event)) return;
            // Enter in a listing's box is a press there, as a click on its Buy is.
            if (event.key === 'Enter' && (st.kind === 'bazaar' || st.kind === 'itemmarket') && event.target && event.target.closest && !event.target.closest('#tarc-host')) {
                if (pressIn(event.target, true)) for (const ms of TP_AFTER_PRESS_MS) win.setTimeout(() => later(0), ms);
                return;
            }
            const arrow = event.key === 'ArrowUp' || event.key === 'ArrowDown' || event.key === 'ArrowRight';
            if (event.key !== 'n' && event.key !== 'N' && event.key !== '`' && !arrow) return;
            if (event.ctrlKey || event.metaKey || event.altKey || (arrow && event.shiftKey)) return;
            const el = event.target;
            if (el && (el.isContentEditable || /^(input|textarea|select)$/i.test(el.tagName || ''))) return;
            if (event.key === '`') {
                // Torn Trading's panel on this page keeps the key: ours is folded with its own + and –.
                if (!tradingOnPage(doc) && (st.room || st.pinned)) setOpen(!isOpen());
                return;
            }
            if (!st.v || (st.kind !== 'bazaar' && st.kind !== 'itemmarket')) return;
            const v = st.v;
            // Up = Fill all, Down = the next listing to buy here. Only while something of yours is to buy on this page:
            // then they no longer scroll Torn's page; with nothing to buy here they are Torn's keys as ever.
            if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
                if (!st.fill.length && !st.waits) return;
                event.preventDefault();
                if (event.key === 'ArrowUp') fillAllOn();
                else nextListing();
                return;
            }
            // Right or N = the next bazaar, while a run is on: from a bazaar of your list, on from it; from anywhere
            // else, to the stop the run is on.
            if (!v.buy.run.stops.some((s) => s.state === 'cur')) return;
            if (arrow) event.preventDefault();
            if (v.buy.run.stops.some((s) => s.place === placeNow())) goNext(v);
            else goStop(v);
        }

        doc.addEventListener('click', onClick, true);
        doc.addEventListener('keydown', onKey, true);
        // A number typed into a card's box: its mark says at once when it is more than you need.
        const onInput = (event) => {
            // The points market and the museum: a number typed into Torn's box is judged as you type.
            if (st.kind === 'points' || st.kind === 'museum') { later(120); return; }
            if (st.kind !== 'bazaar' && st.kind !== 'itemmarket') return;
            // Typed by you outside every listing (the bazaar's own search): listings that go now were filtered, not bought.
            const el = event.target;
            if (yours(event) && el && el.closest && !el.closest('#tarc-host') && !st.tiles.some((x) => x.tile && x.tile.contains(el))) { st.pressed.clear(); st.searchEl = el; st.goneCand = null; }
            later(120);
        };
        doc.addEventListener('input', onInput, true);

        // ---- when to look again ---------------------------------------------------------------------------------------

        const mo = new win.MutationObserver((list) => {
            // Our own marks changing is not the page changing.
            for (const m of list) {
                const el = m.target.nodeType === 1 ? m.target : m.target.parentElement;
                if (el && el.closest && el.closest('#tarc-host, .tarc-setmark, .tarc-setrule')) continue;
                const nodes = m.type === 'childList' ? [...m.addedNodes, ...m.removedNodes] : [];
                if (nodes.length && nodes.every((x) => x.nodeType === 1 && x.classList && (x.classList.contains('tarc-setmark') || x.classList.contains('tarc-setrule')))) continue;
                later();
                return;
            }
        });
        mo.observe(doc.body, { childList: true, characterData: true, subtree: true });
        const onHash = () => later(0);
        const onResize = () => { st.drawn = ''; later(0); };
        win.addEventListener('hashchange', onHash);
        win.addEventListener('popstate', onHash);
        win.addEventListener('resize', onResize);
        const reload = () => { loadShared(); later(0); };
        gmOnChange(SHARED_VIEW_KEY, reload);
        gmOnChange(BOX_PRESSES_KEY, () => later(0));

        // Torn Trading on this page: said to every tab, so the Archive's own tab shares the limits with it.
        function look() {
            const t = now();
            const had = st.shared ? st.shared.at : 0;
            if (tradingOnPage(doc) && shouldMarkSeen(gmGet(TRADING_SEEN_KEY, 0), t)) gmSet(TRADING_SEEN_KEY, t);
            // The view is re-read here too where the host cannot tell us it changed.
            loadShared();
            // Torn's own page may have moved under us (its sidebar, a page of another width).
            if (!box.hidden) place();
            // Looked at again only when something of ours changed: the page's own changes are seen as they happen.
            if (had !== (st.shared ? st.shared.at : 0) || win.location.href !== st.href) later(0);
        }
        const lookTimer = win.setInterval(look, TRADING_LOOK_EVERY_MS);
        // Torn Trading's panel moved, folded, came or went: the Archive makes room at once.
        const otherTimer = win.setInterval(() => {
            if (doc.hidden || (!doc.getElementById(TRADING_HOST_IDS[0]) && !st.other)) return;
            const r = tradingRect();
            const sig = r ? [r.left, r.top, r.right, r.bottom].map(Math.round).join() : '';
            if (sig !== st.other) { st.drawn = ''; show(st.content); }
        }, TP_OTHER_MS);

        place();
        loadShared();
        look();
        later(0);

        return {
            scan,
            stop() {
                win.clearInterval(lookTimer);
                win.clearInterval(otherTimer);
                if (st.timer) win.clearTimeout(st.timer);
                if (st.goneT) win.clearTimeout(st.goneT);
                mo.disconnect();
                doc.removeEventListener('click', onClick, true);
                doc.removeEventListener('keydown', onKey, true);
                doc.removeEventListener('input', onInput, true);
                win.removeEventListener('hashchange', onHash);
                win.removeEventListener('popstate', onHash);
                win.removeEventListener('resize', onResize);
                clearSetMarks(doc);
                for (const el of doc.querySelectorAll('.tarc-buyhere')) setRing(el, '');
                host.remove();
                style.remove();
            },
            version,
        };
    }

    /* ===== src/main.js ===== */
    // Torn Archive: where it starts.
    //
    // On its own page (one tab of yours) it is the hub: the one place that asks Torn's API and TornW3B anything, in
    // view or not, and works your sets out. On Torn's pages it asks nothing: it shows a small box and marks from what
    // the hub worked out, and tells the hub what the page showed. Beside Torn Trading it keeps running, and the two
    // share the limits: the one whose page you look at asks more, the other less (core/turns.js).
    //
    // Your keys are pasted by you into Settings and kept in Tampermonkey's storage. A Torn key goes to api.torn.com
    // only. The key you registered on TornW3B goes to weav3r.dev only, in a header, for your own price list and your
    // receipts. The shared server, once you save its address and your password for it, is told bazaar and item numbers,
    // prices and counts - never a key, never your stock or your money. Nothing presses a button of Torn's.



























    const VERSION = typeof TARC_BUILD_VERSION === 'string' ? TARC_BUILD_VERSION : 'dev';
    /** The shared server's address, built in (build.mjs). '' in a copy built without one. */
    const SERVER_HOME = typeof TARC_SERVER_HOME === 'string' ? TARC_SERVER_HOME : '';

    /** Torn Trading's own page: Torn Archive only notes that Torn Trading runs there, and when you look at it. */
    const TRADING_PAGE_URL = 'https://abrahamdelosreyes17-oss.github.io/torn-moneymaker-releases/';

    const STEP_MS = 5 * 1000;
    /** The hub in view draws at most this often by itself; your own press is drawn at once (1.3.0, the calm pace). */
    const DRAW_CALM_MS = 1000;
    const DRAW_PRESS_MS = 30;
    /** Presses that change nothing on the screen: no draw follows them. */
    const HUB_QUIET = new Set(['look', 'copy', 'zip', 'usageExport']);
    const USAGE_FLUSH_MS = 15 * 1000;
    const KEY_KINDS = ['limited', 'full', 'w3b'];
    const keyOf = (kind) => String(gmGet('key.' + kind, '') || '').trim();
    const store = { get: gmGet, set: gmSet, del: gmDel };

    // ---- the logs: what was asked of whom, and what went wrong. Never a key. -------------------------------------------------

    let usagePending = {};
    let usageTimer = 0;
    /** Is the shared server on? Set by the hub: only there are requests made. */
    let serverOn = () => false;
    const refusedAt = [];

    function flushUsage() {
        if (usageTimer) clearTimeout(usageTimer);
        usageTimer = 0;
        if (!Object.keys(usagePending).length) return;
        const pending = usagePending;
        usagePending = {};
        gmSet('usage', usageMerge(gmGet('usage', null), pending));
        // With the shared server on, the same counts wait in one sum for the next exchange (how many requests of each
        // kind, and how TornW3B answered; nothing else).
        if (serverOn()) gmSet(SERVER_CALLS_KEY, usageCallsAdd(gmGet(SERVER_CALLS_KEY, null), pending));
    }

    function recordUse(service, tag) {
        usageAdd(usagePending, usageLabel(tag && (String(tag).charAt(0) === service || String(tag).startsWith('r.' + service + '.')) ? tag : service + '.other'));
        if (!usageTimer) usageTimer = setTimeout(flushUsage, USAGE_FLUSH_MS);
    }

    function logLine(kind, where, what, detail = null) {
        const entry = { at: Date.now(), kind, where, what: logText(what), ...(detail ? { detail: logText(detail) } : {}) };
        gmSet('log', addLogEntries(gmGet('log', []), [entry]));
    }

    function logFailed(service, x) {
        const e = x && x.error;
        if (e && (e.local || e.takingTurns)) return;
        logLine('error', service === 't' ? 'Torn API' : 'TornW3B', String(x.path || '').split('?')[0] + ': ' + String((e && e.message) || e || 'failed'), e && (e.code || e.http) ? 'code ' + (e.code ?? '') + ' http ' + (e.http ?? '') + (e.said ? ' · it said: ' + e.said : '') : null);
    }

    // ---- Torn Trading seen on this page: said to every tab ---------------------------------------------------------------

    /**
     * This page is being looked at (in view, with the keyboard): said to every tab of ours, and to the other app through
     * the site's own page storage (both apps' pages live on one site; two userscripts cannot read each other's values).
     */
    function markViewed(app, key) {
        if (document.visibilityState !== 'visible' || !document.hasFocus()) return false;
        const now = Date.now();
        if (!shouldMarkView(gmGet(key, 0), now)) return false;
        gmSet(key, now);
        try { window.localStorage.setItem(FRONT_MARK, markText({ app, at: now })); } catch { /* no page storage: Torn Trading is never told, and we stay behind it */ }
        return true;
    }

    function watchTrading(itsOwnPage) {
        const look = () => {
            const now = Date.now();
            if (tradingOnPage(document) && shouldMarkSeen(gmGet(TRADING_SEEN_KEY, 0), now)) gmSet(TRADING_SEEN_KEY, now);
            if (itsOwnPage) markViewed('trading', TRADING_VIEW_KEY);
        };
        look();
        if (itsOwnPage) {
            window.addEventListener('focus', look);
            document.addEventListener('visibilitychange', look);
        }
        return setInterval(look, TRADING_LOOK_EVERY_MS);
    }

    // ---- the hub ---------------------------------------------------------------------------------------------------------

    function bootHub(tabId) {
        const now = () => Date.now();
        let frontSince = 0;
        let share = { mode: 'alone', why: '', ...SHARES.alone };
        let leading = false;
        let engine = null;
        let hub = null;
        let drawT = 0;
        let drawDue = 0;
        let drawnAt = 0;
        let notice = null;
        let shareAt = 0;
        let shareTried = 0;
        let shared = '';
        let notesTaken = null;
        let stepping = false;
        let link = null;
        let serverMsg = '';
        let serverSaid = '';
        const shown = { limited: 0, full: 0, w3b: 0 };

        const settings = () => archiveSettings(gmGet('settings', null));

        const tornWin = tabWindow('win.torn', tabId, store);
        const w3bWin = tabWindow('win.w3b', tabId, store);
        const listWin = tabWindow('win.w3blist', tabId, store);
        const tornShared = {
            maxPerMinute: SHARES.alone.torn,
            loadWindow: () => tornWin.load(),
            addToWindow: (at) => tornWin.add(at),
            loadPause: () => gmGet('tornPause', null),
            savePause: (p) => gmSet('tornPause', p),
            onSent: (x) => recordUse('t', x.tag),
            onFailed: (x) => logFailed('t', x),
            // Beside the shared server: its part of your Torn limit is left to it (core/server.js). Off, or silent: no check.
            mayCall: (t, recent) => serverMayCall(link ? link.grant() : null, recent, t),
            // What Torn's "too many" taught, for every tab; and the careful pace while the server does not let this copy in.
            loadCeil: () => gmGet('tornCeil', null),
            saveCeil: (c) => gmSet('tornCeil', c),
            turnedAway: () => !!link && link.turnedAway(),
            carefulMost: SERVER_CAREFUL_MOST,
        };
        const torn = new TornApiClient({ getKey: () => keyOf('limited'), ...tornShared });
        const full = new LedgerClient({ getKey: () => keyOf('full'), ...tornShared });
        // Calls held back for the server's part: it is asked for room sooner than its next exchange.
        torn.onHeld = () => { if (link) link.askSoon(); };
        full.onHeld = torn.onHeld;
        const w3b = new W3bClient({
            maxPerMinute: SHARES.alone.w3b,
            onSent: (x) => recordUse('w', x.tag),
            onAnswered: (x) => recordUse('w', 'r.w.' + x.how),
            onFailed: (x) => logFailed('w', x),
            onLocal: () => { refusedAt.push(now()); },
            loadShared: () => ({ recent: w3bWin.load(), cooldownUntil: Number(gmGet('w3bCool', 0)) || 0 }),
            saveShared: (s) => gmSet('w3bCool', s.cooldownUntil),
            addShared: (at) => w3bWin.add(at),
            loadListing: () => listWin.load(),
            addListing: (at) => listWin.add(at),
            loadListingDay: () => gmGet('w3bListDay', {}),
            saveListingDay: (counts) => {
                gmSet('w3bListDay', counts);
                // Told to Torn Bids through the page's storage: TornW3B counts the two apps as one address.
                try { window.localStorage.setItem(W3B_MARK, w3bMarkText(listWin.load(), counts, now())); } catch { /* no page storage: Torn Bids counts only its own */ }
            },
            loadListingOther: () => {
                try { return readW3bMark(window.localStorage.getItem(W3B_OTHER_MARK), now()); } catch { return null; }
            },
        });
        const own = new Tw3bOwnClient({
            getKey: () => keyOf('w3b'),
            getUser: () => (engine ? engine.state.self.id : ''),
            onSent: (x) => recordUse('w', x.tag),
            onFailed: (x) => logFailed('w', x),
        });

        /**
         * The hub is drawn again. By itself (a read came in) at most once a second; `soon`: your own press, at once.
         * Out of view nothing is drawn - one draw when you come back - and Torn's tabs still get what changed.
         * (Until 1.3.0 every read drew the whole page 60 ms later, in view or not.)
         */
        function schedule(soon = false) {
            if (document.visibilityState !== 'visible') { shareView(); return; }
            const t = now();
            const at = soon === true ? t + DRAW_PRESS_MS : Math.max(t + 60, drawnAt + DRAW_CALM_MS);
            if (drawT && drawDue <= at) return;
            if (drawT) clearTimeout(drawT);
            drawDue = at;
            drawT = setTimeout(() => { drawT = 0; draw(); }, Math.max(0, at - t));
        }

        // ---- the limits shared with Torn Trading: more for the one you look at ---------------------------------------------

        /** What Torn Archive may ask a minute now, told to the clients. Going down takes effect at once. */
        function applyShare() {
            const t = now();
            const seenAt = gmGet(TRADING_SEEN_KEY, 0);
            const viewAt = gmGet(ARCHIVE_VIEW_KEY, 0);
            const theirsAt = gmGet(TRADING_VIEW_KEY, 0);
            const front = tradingRunning(seenAt, t) && archiveInFront(viewAt, theirsAt);
            if (!front) frontSince = 0;
            else if (!frontSince) frontSince = t;
            let behind = null;
            try { behind = readMark(window.localStorage.getItem(BEHIND_MARK)); } catch { behind = null; }
            const s = shareNow({ now: t, tradingSeenAt: seenAt, tradingViewAt: theirsAt, archiveViewAt: viewAt, behind, frontSince });
            torn.maxPerMinute = s.torn;
            full.maxPerMinute = s.torn;
            w3b.maxPerMinute = s.w3b;
            w3b.sharedPerMinute = s.w3b;
            const changed = s.mode !== share.mode || s.why !== share.why || s.torn !== share.torn || s.w3b !== share.w3b;
            share = s;
            if (changed) schedule();
            return s;
        }

        /** Torn Archive's page is open: said to Torn Trading in the site's page storage, in view or not. Any tab of it may. */
        function alive() {
            const t = Date.now();
            try {
                const had = readMark(window.localStorage.getItem(ALIVE_MARK));
                if (shouldMarkAlive(had && had.app === 'archive' ? had.at : 0, t)) window.localStorage.setItem(ALIVE_MARK, markText({ app: 'archive', at: t }));
            } catch { /* no page storage: Torn Trading goes by when this page was last looked at */ }
        }

        /** This page looked at: said, and the share worked out again. */
        function looked() {
            if (markViewed('archive', ARCHIVE_VIEW_KEY)) applyShare();
        }

        function notify(n) {
            const s = settings();
            notice = { ...n, at: now() };
            if (s.notify === 'off') return;
            const hidden = document.visibilityState !== 'visible';
            if (s.notify === 'browser' && hidden && typeof Notification === 'function' && Notification.permission === 'granted') {
                try {
                    const note = new Notification(n.title, { body: n.body, tag: 'tarc-trade-' + (n.tradeId || '') });
                    note.onclick = () => { window.focus(); if (hub && n.tradeId) hub.go('trades', 0); note.close(); };
                } catch { /* the toast below still says it */ }
            }
            if (hub) hub.toast(n);
            if (s.sound) beep();
        }

        function beep() {
            try {
                const Ctx = window.AudioContext || window.webkitAudioContext;
                if (!Ctx) return;
                const ctx = new Ctx();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.frequency.value = 880;
                gain.gain.setValueAtTime(0.0001, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.08, ctx.currentTime + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.35);
                osc.connect(gain).connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + 0.4);
                osc.onended = () => ctx.close();
            } catch { /* no sound then */ }
        }

        function newEngine() {
            return makeEngine({
                now,
                load: (part) => gmGet('s.' + part, null),
                // Only the tab that reads writes: a tab that gave the reading away must not write its old copy back.
                save: (part, value) => { if (leading) gmSet('s.' + part, value); },
                settings,
                torn, full, w3b, own,
                hasKey: (kind) => !!keyOf(kind),
                paused: () => false,
                say: (kind, what, detail) => logLine(kind, 'Torn Archive', what, detail),
                changed: () => schedule(),
                notify,
                kick: () => { step(); },
                // The engine's own working-out, in the speed log: it was most of what froze the page and was not timed.
                timed: perfTimed,
            });
        }

        // ---- the shared server: every 30 s, by the tab that reads -----------------------------------------------------

        let greeted = false;
        let besideWas = false;

        link = new ServerLink({
            load: (key) => gmGet(key, null),
            save: gmSet,
            del: gmDel,
            send: gmSend,
            now,
            version: VERSION,
            home: SERVER_HOME,
            getId: () => (engine ? engine.state.self.id : ''),
            random: () => Array.from(crypto.getRandomValues(new Uint8Array(24)), (b) => b.toString(16).padStart(2, '0')).join(''),
            lowered: () => torn.ceilNow(now()) !== null,
            pieces: ENGINE_ALL_PIECES,
            getUse: () => ({ used: torn.stats(now()).usedLastMinute, waiting: torn.queue.length + full.queue.length }),
            tradingOn: () => tradingRunning(gmGet(TRADING_SEEN_KEY, 0), now()),
            getWant: () => engine.serverWant(),
            getMark: () => engine.serverMark(),
            take: (answer, got) => { if (leading) engine.serverTook(answer, got); },
            forget: () => { if (engine) engine.serverForget(); },
            onChange() {
                // Said once in the problem log when it changes. Never the password.
                const said = link.status().error || '';
                if (said !== serverSaid) { serverSaid = said; if (said) logLine('note', 'Torn Shared Server', said); }
                schedule();
            },
        });

        serverOn = () => link.on();

        function serverDesk() {
            const st = link.status();
            return { ...serverLines(st, now()), bazaars: engine ? Object.keys(engine.state.server.shops).length : 0, address: st.address || '', typed: st.typed, hasPass: st.hasPass, own: st.own, builtIn: st.builtIn, msg: serverMsg };
        }

        // ---- what Torn's tabs told us ------------------------------------------------------------------------------

        function readNotes() {
            if (!leading || !engine) return;
            const t = now();
            const q = gmGet(SHARED_NOTES_KEY, []);
            if (!Array.isArray(q) || !q.length) return;
            const done = new Set(gmGet('notesDone', []));
            let any = false;
            let moved = false;
            for (const n of q) {
                if (!n || !n.id || done.has(n.id) || t - n.t > NOTES_KEEP_MS) continue;
                done.add(n.id);
                any = true;
                try {
                    // A press in the box on a Torn page. Start, Next and Stop of the run; Next may name the bazaar you
                    // stand in. Written down with how long it waited: a press that seemed dead shows in the zip.
                    if (n.kind === 'act') {
                        const args = Array.isArray(n.what && n.what.args) ? n.what.args.slice(0, 2) : [];
                        logLine('note', 'A Torn page', 'A press in the box taken: ' + String((n.what && n.what.name) || '') + ' ' + args.map(String).join(' '), 'it waited ' + Math.max(0, t - n.t) + ' ms');
                        if (n.what && n.what.name === 'run') engine.act('run', ...args);
                        moved = true;
                    }
                    // 'press': Torn's own Buy pressed on a listing - counted for nothing, your log is asked soon after.
                    else if (n.kind === 'buy' || n.kind === 'swap' || n.kind === 'thread' || n.kind === 'trade' || n.kind === 'shop' || n.kind === 'press') { engine.note(n.kind, n.what); moved = moved || n.kind === 'buy' || n.kind === 'swap' || n.kind === 'shop'; }
                    // "Read" on your stock, pressed on a Torn page: your items are asked for now, ahead of the rest.
                    else if (n.kind === 'read') { engine.act('readStock'); logLine('note', 'A Torn page', 'Read pressed on your stock', 'it waited ' + Math.max(0, t - n.t) + ' ms'); moved = true; }
                    // What a Torn tab saw of its page, for the log: it is in the zip.
                    else if (n.kind === 'say' && n.what) logLine('note', 'A Torn page', String(n.what.what || ''), n.what.detail ? String(n.what.detail) : null);
                } catch (error) {
                    logLine('error', 'Torn Archive', 'A note from a Torn page was not taken: ' + n.kind, String((error && error.message) || error));
                }
            }
            if (!any) return;
            notesTaken = [...done].slice(-300);
            gmSet('notesDone', notesTaken);
            // A buy, a swap or a press of the run: Torn's tabs get the new view now, not at the next redraw (a tab out
            // of view redraws once a minute), and it names the notes it holds.
            if (moved) { shareView(true); schedule(true); }
        }

        /** What Torn's tabs show: shared when it changed, and at least once a minute so they know it is alive. */
        function shareView(now_ = false, view = null) {
            if (!leading || !engine) return;
            const t = now();
            if (!now_ && (t - shareAt <= 5000 || t - shareTried <= 5000)) return;
            shareTried = t;
            const v = viewForTabs(view || (now_ ? engine.view() : engine.calm()));
            const json = JSON.stringify(v);
            if (!now_ && json === shared && t - shareAt <= 60000) return;
            shared = json;
            shareAt = t;
            if (!notesTaken) notesTaken = gmGet('notesDone', []);
            gmSet(SHARED_VIEW_KEY, { at: t, v, notes: (Array.isArray(notesTaken) ? notesTaken : []).slice(-60) });
        }

        // ---- the desk the hub draws ----------------------------------------------------------------------------------

        function keysDesk() {
            const st = engine.keys() || {};
            const out = {};
            const t = now();
            for (const kind of KEY_KINDS) {
                const key = keyOf(kind);
                const s = st[kind] || {};
                out[kind] = { set: !!key, ok: !!s.ok, error: s.error || '', shown: key && shown[kind] > t ? key : '' };
            }
            return out;
        }

        function usageDesk() {
            const t = now();
            const rec = usageMerge(gmGet('usage', null), usagePending, t);
            const tornBars = usageSeries(rec, { service: 't', range: '1h', now: t }).bars.map((b) => b.total);
            const w3bBars = usageSeries(rec, { service: 'w', range: '1h', now: t }).bars.map((b) => b.total);
            while (refusedAt.length && t - refusedAt[0] > 3600000) refusedAt.shift();
            return { torn: tornBars, w3b: w3bBars, nowTorn: tornBars[tornBars.length - 1] || 0, nowW3b: w3bBars[w3bBars.length - 1] || 0, refused: refusedAt.length };
        }

        function desk() {
            return {
                view: perfTimed('view', () => engine.view()),
                keys: keysDesk(),
                usage: usageDesk(),
                turns: { ...share },
                server: serverDesk(),
                busy: engine.busy(),
                notice,
                version: VERSION,
                elsewhere: !leading,
            };
        }

        function draw() {
            if (!hub || !engine) return;
            drawnAt = now();
            const d = desk();
            perfTimed('draw', () => hub.show(d));
            shareView(false, d.view);
        }

        // ---- which tab reads ---------------------------------------------------------------------------------------------

        function lead(claim = false) {
            const r = hubLeader(gmGet(HUB_LEAD_KEY, null), tabId, { now: now(), claim });
            if (r.write) gmSet(HUB_LEAD_KEY, r.write);
            if (r.lead === leading) return;
            leading = r.lead;
            // The tab that takes the reading over starts from what is stored, not from its own older copy.
            if (leading) engine = newEngine();
            schedule();
        }

        async function step() {
            lead();
            looked();
            // Torn Trading seen, gone for two minutes, or looked at: the limits follow without a press.
            applyShare();
            if (!leading || stepping) return;
            stepping = true;
            try {
                readNotes();
                // Torn Trading came on: a server that did not know this PC may know it now.
                const beside = tradingRunning(gmGet(TRADING_SEEN_KEY, 0), now());
                if (beside && !besideWas) link.wake();
                besideWas = beside;
                // Before this page's first reads the server is told the PC is on, so that it makes room: its own
                // requests of the last minute come back with the answer and are waited out. Never longer than 5 s.
                if (!greeted && engine.state.self.id && engine.state.items.at) {
                    greeted = true;
                    link.wake();
                    await Promise.race([link.tick().catch(() => false), new Promise((done) => setTimeout(done, 5000))]);
                }
                await engine.step();
                // Not before Torn has said who you are and what the pieces are: your own bazaar is left out by your id.
                if (engine.state.self.id && engine.state.items.at) link.tick().catch((error) => logLine('error', 'Torn Shared Server', 'An exchange stopped', String((error && error.message) || error)));
            } catch (error) {
                logLine('error', 'Torn Archive', 'A round of reads stopped', String((error && error.stack) || error));
            } finally {
                stepping = false;
            }
            if (now() - shareAt > 60000) schedule();
        }

        // ---- what a press in the hub asks ----------------------------------------------------------------------------

        function download(name, bytes, type) {
            const url = URL.createObjectURL(new Blob([bytes], { type }));
            const a = document.createElement('a');
            a.href = url;
            a.download = name;
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(url), 10000);
        }

        const stamp = () => new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');

        function zip() {
            flushUsage();
            const t = now();
            const S = engine.state;
            // What was read and worked out, for finding a fault. No key is in it: keys are stored apart and never read here.
            const state = {};
            for (const part of ENGINE_PARTS) state[part] = S[part];
            const files = [
                { name: 'about.txt', text: 'Torn Archive ' + VERSION + '\nMade ' + new Date(t).toString() + '\nKeys set: ' + KEY_KINDS.filter((k) => keyOf(k)).join(', ') + '\nPieces watched: ' + ENGINE_ALL_PIECES.length + '\nNo key is in this file or any file beside it.\n' },
                { name: 'problems.txt', text: logAsText(gmGet('log', [])) },
                { name: 'usage-by-minute.csv', text: usageCsv(gmGet('usage', null), { by: 'minute' }) },
                { name: 'settings.json', text: JSON.stringify(settings(), null, 1) },
                { name: 'key-states.json', text: JSON.stringify(engine.keys(), null, 1) },
                { name: 'state.json', text: logText(JSON.stringify(state), 20 * 1024 * 1024) },
                ...speedFiles(perfRecord(t), { machine: perfMachine(), version: VERSION, now: t }),
            ];
            download('torn-archive-' + stamp() + '.zip', makeZip(files, new Date(t)), 'application/zip');
        }

        const actions = {
            set(patch) {
                gmSet('settings', archiveSettings({ ...settings(), ...patch }));
                engine.settingsChanged();
                if (patch && patch.notify === 'browser' && typeof Notification === 'function' && Notification.permission === 'default') Notification.requestPermission().catch(() => {});
                schedule();
            },
            cart: (id, place) => engine.act('cart', id, place),
            drop: (key) => engine.act('drop', key),
            cartAll: (id) => engine.act('cartAll', id),
            listOnly: (id) => engine.act('listOnly', id),
            makeList: (kind) => engine.act('makeList', kind),
            // The piece open on "Sold by": its bazaars are asked of Torn itself (not connected in 1.2.2: nothing was asked).
            // (1.3.0: no draw follows it. The draw sent it, so until then the Buy page drew itself without end.)
            look: (id) => engine.act('look', id),
            clearList: () => engine.act('clearList'),
            run: (op, place) => engine.act('run', op, place),
            read: () => { logLine('note', 'Torn Archive', 'Pressed: Read now', null); engine.readNow(); step(); },
            // "Read my stock": your items and your log, ahead of the rest, and nothing else.
            readStock: () => { engine.act('readStock'); },
            copy: (text) => gmCopy(text),
            keySave(kind, value) {
                if (!KEY_KINDS.includes(kind) || !value) return;
                gmSet('key.' + kind, String(value).trim());
                shown[kind] = 0;
                engine.keyChanged(kind);
                schedule();
                step();
            },
            keyForget(kind) {
                if (!KEY_KINDS.includes(kind)) return;
                gmDel('key.' + kind);
                shown[kind] = 0;
                engine.keyChanged(kind);
                schedule();
            },
            keyShow(kind) {
                if (!KEY_KINDS.includes(kind)) return;
                shown[kind] = shown[kind] > now() ? 0 : now() + REVEAL_MS;
                schedule();
                if (shown[kind]) setTimeout(schedule, REVEAL_MS + 100);
            },
            zip,
            w3b: (op) => engine.act('w3b', op),
            receipt: (id) => engine.act('receipt', id),
            usageExport() { flushUsage(); download('torn-archive-usage-' + stamp() + '.csv', usageCsv(gmGet('usage', null), { by: 'minute' }), 'text/csv'); },
            notifyTest() {
                const ask = typeof Notification === 'function' && Notification.permission === 'default' ? Notification.requestPermission() : Promise.resolve();
                const t = engine.view().trades.open[0];
                const n = t ? { ...tradeNotice(t, t.items, t.total), tradeId: t.id } : { title: 'Someone opened a trade with you', body: 'This is how Torn Archive will tell you.', tradeId: null };
                Promise.resolve(ask).catch(() => {}).then(() => { notify(n); schedule(true); });
            },
            here() { lead(true); step(); },
            serverSave(address, pass) {
                const r = link.saveConfig(address, pass);
                serverMsg = r.ok ? '' : r.why === 'address' ? 'Not saved. It must be the address of your server: https://….workers.dev' : 'Not saved. The password is the long one you were given for the server: letters and digits only.';
                schedule();
                if (r.ok) step();
            },
            serverForget() { link.forget(); serverMsg = ''; schedule(); },
        };

        // Your own press is drawn at once; what the reads bring, at the calm pace.
        for (const name of Object.keys(actions)) {
            if (HUB_QUIET.has(name)) continue;
            const fn = actions[name];
            actions[name] = (...args) => { const r = fn(...args); schedule(true); return r; };
        }

        // ---- start ---------------------------------------------------------------------------------------------------

        perfStart({ where: () => 'Torn Archive' });
        engine = newEngine();
        lead();
        looked();
        alive();
        applyShare();
        hub = mountHub(document, actions);
        draw();
        watchTrading(false);
        setInterval(step, STEP_MS);
        setInterval(alive, TRADING_LOOK_EVERY_MS);
        setInterval(() => { if (leading) gmSet(HUB_LEAD_KEY, { id: tabId, ts: now() }); }, HUB_LEAD_BEAT_MS);
        step();
        gmOnChange(SHARED_NOTES_KEY, () => { readNotes(); });
        gmOnChange(HUB_LEAD_KEY, () => lead());
        gmOnChange(TRADING_SEEN_KEY, applyShare);
        gmOnChange(TRADING_VIEW_KEY, applyShare);
        gmOnChange(ARCHIVE_VIEW_KEY, applyShare);
        window.addEventListener('focus', looked);
        // Torn Trading saying it keeps to less: heard as it is written, also by a tab out of view.
        window.addEventListener('storage', (e) => { if (!e || e.key === BEHIND_MARK || e.key === null) applyShare(); });
        gmOnChange('settings', () => { if (engine) engine.settingsChanged(); schedule(); });
        // Saved or forgotten in another tab of yours.
        gmOnChange(SERVER_CONFIG_KEY, () => { link.grantKept = undefined; schedule(); });
        document.addEventListener('visibilitychange', () => { looked(); if (document.visibilityState === 'visible') schedule(true); });
        window.addEventListener('pagehide', () => {
            flushUsage();
            if (leading && engine) {
                engine.flush();
                // The mark is given up at once, so another tab of yours can take the reading over without waiting.
                const r = gmGet(HUB_LEAD_KEY, null);
                if (r && r.id === tabId) gmSet(HUB_LEAD_KEY, { id: null, ts: 0 });
            }
        });
        return { engine: () => engine, hub, step, desk, actions, leading: () => leading, share: () => share, applyShare, link };
    }

    // ---- start -----------------------------------------------------------------------------------------------------------

    function boot() {
        if (typeof window === 'undefined' || typeof document === 'undefined') return null;
        // One copy a page: a second install, or the script run twice, would draw everything twice.
        if (window.__tarcBooted) return null;
        window.__tarcBooted = true;
        const href = window.location.href;
        const tabId = makeTabId();
        gmMenu('Open Torn Archive', () => gmOpenTab(ARCHIVE_PAGE_URL));
        if (isArchivePageUrl(href)) {
            const app = bootHub(tabId);
            window.__tarc = app;
            return app;
        }
        if (href.startsWith(TRADING_PAGE_URL)) {
            watchTrading(true);
            return null;
        }
        if (/(^|\.)torn\.com$/i.test(window.location.hostname) || /[?&]tarc=torn(?:[&#]|$)/.test(href)) {
            perfStart({ where: () => 'a Torn page' });
            window.addEventListener('pagehide', flushUsage);
            return mountTornPage(document, { tabId, version: VERSION });
        }
        return null;
    }

    boot();
})();
